export interface MCQItem {
  id: string;
  section: string;
  unit: string;
  chapter: string;
  questionNumber: string;
  question: string;
  options: Record<string, string>;
  correctOption: string;
  correctAnswer: string;
  questionType: string;
  explanation?: any;
}

export const MCQ_BANK_5: MCQItem[] = [{"id":"P1_U5_MCQ_001","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_001","question":"A newly opened artisan bakery needs finance to pay weekly staff wages and buy flour and sugar before customers pay for their orders. Which type of finance need does this describe?","options":{"A":"Start-up capital for non-current assets","B":"Working capital for day-to-day operations","C":"Long-term capital for international expansion","D":"Capital for replacing worn-out machinery"},"correctOption":"B","correctAnswer":"Working capital for day-to-day operations","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because working capital is the finance needed to pay for everyday running expenses such as wages, raw materials, and utility bills.","distractor_reasons":{"A":"Incorrect because start-up capital for non-current assets funds long-term items like ovens and premises rather than recurring weekly wages and ingredients.","B":"Correct selection.","C":"Incorrect because expansion capital is used to grow operations into new markets rather than covering routine daily trading costs.","D":"Incorrect because replacing machinery involves purchasing non-current assets rather than funding short-term operational expenses."}}},{"id":"P1_U5_MCQ_002","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_002","question":"A profitable private limited company plans to build three new regional distribution warehouses over the next eight years. Which external source of finance is most appropriate for this expansion?","options":{"A":"A bank overdraft","B":"Trade credit from suppliers","C":"A long-term bank loan","D":"Selling shares on the stock exchange"},"correctOption":"C","correctAnswer":"A long-term bank loan","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a long-term bank loan provides a large sum of finance repaid over several years, matching the long-term nature of building warehouses.","distractor_reasons":{"A":"Incorrect because a bank overdraft is a short-term facility for temporary working capital deficits and can be recalled by the bank at short notice.","B":"Incorrect because trade credit only delays payment for inventory by a few weeks and cannot fund major construction projects.","C":"Correct selection.","D":"Incorrect because a private limited company is legally prohibited from selling shares to the general public on a stock exchange."}}},{"id":"P1_U5_MCQ_003","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_003","question":"A courier company needs to replace ten ageing delivery vans immediately without paying a large upfront lump sum, and it prefers the finance provider to handle maintenance and repairs. Which source of finance should the company choose?","options":{"A":"Leasing","B":"Retained profit","C":"Government grants","D":"Issuing new ordinary shares"},"correctOption":"A","correctAnswer":"Leasing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because leasing allows a business to use non-current assets in return for regular rental payments without a large upfront outlay, and maintenance is usually included.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because buying ten vans outright with retained profit would require a large immediate cash outflow and leave the courier responsible for maintenance.","C":"Incorrect because government grants are typically awarded for job creation or relocating to deprived areas rather than routine vehicle replacement.","D":"Incorrect because issuing shares is slow, costly, and dilutes ownership control for a medium-term vehicle replacement need."}}},{"id":"P1_U5_MCQ_004","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_004","question":"A car parts manufacturer wants to invest $800,000 in automated robotic welding equipment to improve efficiency over the next decade. Why would trade credit be unsuitable for financing this investment?","options":{"A":"Trade credit requires giving up equity ownership to suppliers","B":"Trade credit charges a higher annual interest rate than a bank overdraft","C":"Trade credit is only available to public limited companies","D":"Trade credit only provides short-term delayed payment for raw materials and inventory"},"correctOption":"D","correctAnswer":"Trade credit only provides short-term delayed payment for raw materials and inventory","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because trade credit is a short-term arrangement with suppliers for purchasing materials or goods for resale, not for funding expensive long-term machinery.","distractor_reasons":{"A":"Incorrect because trade credit is a supplier payment arrangement and does not involve selling shares or giving up ownership.","B":"Incorrect because trade credit is usually interest-free during the agreed credit period, though early-payment discounts may be lost.","C":"Incorrect because sole traders, partnerships, and companies can all receive trade credit from suppliers.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_005","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_005","question":"A small furniture workshop has plenty of customer orders, but it cannot pay its electricity bill or purchase timber because all of its cash is tied up in unpaid customer invoices. What does this situation demonstrate about working capital?","options":{"A":"Working capital is only needed during the first month of trading","B":"Insufficient working capital can prevent a business from paying short-term debts and operating smoothly","C":"Working capital is used solely to purchase property and machinery","D":"High customer orders automatically guarantee sufficient working capital"},"correctOption":"B","correctAnswer":"Insufficient working capital can prevent a business from paying short-term debts and operating smoothly","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because adequate working capital is essential to pay day-to-day operational expenses and short-term liabilities on time.","distractor_reasons":{"A":"Incorrect because working capital is needed continuously throughout the life of a business, not just at start-up.","B":"Correct selection.","C":"Incorrect because property and machinery are funded by long-term capital, whereas working capital funds short-term current operations.","D":"Incorrect because credit sales increase trade receivables rather than immediate cash, which can strain working capital."}}},{"id":"P1_U5_MCQ_006","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_006","question":"A seasonal gift retailer needs $12,000 for six weeks to buy extra inventory ahead of a national festival, after which cash from sales will quickly repay the amount borrowed. Which source of finance is most suitable?","options":{"A":"A 10-year bank loan","B":"Venture capital","C":"A bank overdraft","D":"Hire purchase"},"correctOption":"C","correctAnswer":"A bank overdraft","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a bank overdraft is flexible and short-term, allowing the retailer to borrow only what is needed for six weeks and pay interest only on the daily overdrawn balance.","distractor_reasons":{"A":"Incorrect because a 10-year bank loan commits the business to long-term interest payments for a temporary six-week need.","B":"Incorrect because venture capital is long-term equity finance for high-growth companies rather than short-term seasonal inventory.","C":"Correct selection.","D":"Incorrect because hire purchase is used to acquire non-current assets over several years, not inventory for resale."}}},{"id":"P1_U5_MCQ_007","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_007","question":"An entrepreneur uses $15,000 of her own personal savings to launch a mobile pet-grooming business as a sole trader. What is a key advantage of using this internal source of finance?","options":{"A":"No interest has to be paid and the owner retains full control of the business","B":"The amount of capital available is unlimited","C":"The entrepreneur's personal wealth is protected by limited liability","D":"The money is guaranteed to be refunded by the government if the business fails"},"correctOption":"A","correctAnswer":"No interest has to be paid and the owner retains full control of the business","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because owners' investment is an internal source of finance that incurs no interest charges and avoids sharing ownership or decision-making control.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because personal savings are usually strictly limited, which is a disadvantage of relying solely on owners' investment.","C":"Incorrect because a sole trader has unlimited liability regardless of how the business is financed.","D":"Incorrect because owners' investment carries personal financial risk and is lost if the business fails."}}},{"id":"P1_U5_MCQ_008","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_008","question":"A well-established software company has accumulated $400,000 in retained profit over the last three years and uses it to fund the development of a new mobile app. What is a potential disadvantage of using retained profit for this project?","options":{"A":"The company must pay high monthly interest charges to its bank","B":"Existing shareholders will lose voting control to new external investors","C":"The company must provide non-current assets as collateral","D":"Shareholders may receive lower dividends in the short term"},"correctOption":"D","correctAnswer":"Shareholders may receive lower dividends in the short term","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because reinvesting profit back into the business reduces the amount of after-tax profit available to distribute as dividends to shareholders.","distractor_reasons":{"A":"Incorrect because retained profit is an internal source of finance with no interest charges.","B":"Incorrect because retained profit does not involve issuing new shares to external investors.","C":"Incorrect because collateral is required for secured bank loans, not for using internal retained profit.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_009","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_009","question":"A textile manufacturer closes an outdated storage depot and sells the surplus land and old forklifts to help pay for new sewing machines. Which internal source of finance is the business using?","options":{"A":"Reducing working capital","B":"Sale of unwanted assets","C":"Owners' investment","D":"Crowdfunding"},"correctOption":"B","correctAnswer":"Sale of unwanted assets","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because selling surplus non-current assets such as unused land and old equipment generates cash internally without increasing debt.","distractor_reasons":{"A":"Incorrect because reducing working capital involves lowering inventory levels or collecting trade receivables faster rather than selling non-current assets.","B":"Correct selection.","C":"Incorrect because owners' investment involves owners injecting new personal capital into the business.","D":"Incorrect because crowdfunding is an external source of finance raised from the public online."}}},{"id":"P1_U5_MCQ_010","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_010","question":"An electronics retailer needs $30,000 to upgrade its website and decides to raise the cash internally by holding less inventory in its warehouse and chasing overdue payments from business customers. Which source of finance is being used?","options":{"A":"Retained profit","B":"Sale of non-current assets","C":"Working capital","D":"Trade credit"},"correctOption":"C","correctAnswer":"Working capital","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because freeing up cash tied up in inventory and trade receivables is using working capital as an internal source of finance.","distractor_reasons":{"A":"Incorrect because retained profit comes from past trading surpluses rather than converting existing current assets into cash.","B":"Incorrect because inventory held for resale is a current asset, not a non-current asset.","C":"Correct selection.","D":"Incorrect because trade credit is an external source obtained by delaying payments to suppliers, not collecting from customers."}}},{"id":"P1_U5_MCQ_011","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_011","question":"A large public limited company wants to raise $25 million to enter overseas markets without increasing its debt or interest obligations. Why might the directors choose to issue new shares?","options":{"A":"Share capital is permanent finance that does not have to be repaid and incurs no interest","B":"Issuing new shares guarantees that existing majority shareholders keep 100% control","C":"Share capital can be arranged within 24 hours with zero legal or administrative costs","D":"Dividends paid to new shareholders are legally fixed regardless of company profit"},"correctOption":"A","correctAnswer":"Share capital is permanent finance that does not have to be repaid and incurs no interest","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because share capital raises large sums permanently without contractual repayment dates or interest expenses.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because issuing new shares to the public dilutes the ownership percentage and control of existing shareholders.","C":"Incorrect because issuing shares on a stock exchange involves high administrative, legal, and advertising costs and takes considerable time.","D":"Incorrect because ordinary dividends are not fixed and are only paid if the company makes sufficient profit and directors declare them."}}},{"id":"P1_U5_MCQ_012","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_012","question":"A profitable partnership running three dental clinics wants to raise $600,000 to open a fourth clinic, but its bank refuses a loan due to lack of collateral. Why can the partners not raise this money by issuing shares on the stock exchange?","options":{"A":"Issuing shares is only allowed for businesses in the secondary sector","B":"Partnerships are only permitted to use internal sources of finance","C":"Stock exchanges only provide short-term working capital","D":"Only public limited companies can sell shares to the general public"},"correctOption":"D","correctAnswer":"Only public limited companies can sell shares to the general public","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because legal form restricts share issues; unincorporated partnerships cannot issue shares, and only public limited companies can offer shares on a stock exchange.","distractor_reasons":{"A":"Incorrect because service-sector public limited companies can also issue shares on a stock exchange.","B":"Incorrect because partnerships can use external finance such as bank loans, overdrafts, leasing, and trade credit.","C":"Incorrect because share capital raised on a stock exchange is permanent long-term finance.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_013","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_013","question":"A young biotechnology private limited company has developed a promising medical device but has no track record of profit, so traditional banks consider lending to it too risky. Which external finance providers specialise in investing capital in such high-risk, high-growth businesses in exchange for an ownership stake?","options":{"A":"Commercial overdraft providers","B":"Venture capitalists","C":"Trade creditors","D":"Hire purchase companies"},"correctOption":"B","correctAnswer":"Venture capitalists","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because venture capitalists invest capital and specialist business expertise into small or medium-sized high-growth companies in return for equity shares.","distractor_reasons":{"A":"Incorrect because commercial banks avoid high-risk start-ups without collateral or steady cash flows.","B":"Correct selection.","C":"Incorrect because trade creditors are suppliers providing short-term credit on goods, not equity investors.","D":"Incorrect because hire purchase firms finance specific physical assets rather than investing equity into R&D companies."}}},{"id":"P1_U5_MCQ_014","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_014","question":"A wholesale fruit distributor experiences unpredictable weekly gaps between paying farmers and receiving payments from supermarkets. Why is a bank overdraft more suitable than a bank loan for managing this cash flow pattern?","options":{"A":"A bank overdraft has a lower annual interest rate than a secured bank loan","B":"A bank overdraft never needs to be repaid to the bank","C":"Interest is only paid on the exact amount overdrawn each day, making it flexible for fluctuating needs","D":"A bank overdraft guarantees a fixed interest rate for ten years"},"correctOption":"C","correctAnswer":"Interest is only paid on the exact amount overdrawn each day, making it flexible for fluctuating needs","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because an overdraft allows a business to overdraw its current account up to an agreed limit and pay interest only on the daily overdrawn balance.","distractor_reasons":{"A":"Incorrect because overdraft interest rates are typically higher than those on long-term secured bank loans.","B":"Incorrect because an overdraft is repayable on demand by the bank and is meant to be cleared regularly.","C":"Correct selection.","D":"Incorrect because overdrafts are short-term facilities with variable interest rates, not 10-year fixed-rate agreements."}}},{"id":"P1_U5_MCQ_015","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_015","question":"A printing company wants to acquire a high-speed digital press worth $90,000, pay for it in monthly instalments over four years, and legally own the machine once the final payment is made. Which source of finance matches this requirement?","options":{"A":"Hire purchase","B":"Operating leasing","C":"Bank overdraft","D":"Working capital"},"correctOption":"A","correctAnswer":"Hire purchase","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because hire purchase allows a business to buy a non-current asset via regular instalments and become the legal owner upon making the final payment.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because under leasing, legal ownership of the asset remains with the leasing company rather than transferring to the user.","C":"Incorrect because an overdraft is a short-term working capital facility rather than an asset-purchase instalment agreement.","D":"Incorrect because working capital refers to short-term funds for daily expenses, not buying a $90,000 printing press."}}},{"id":"P1_U5_MCQ_016","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_016","question":"A café owner borrows $30,000 from a bank to renovate her premises, agreeing to repay the principal plus interest in fixed monthly amounts over five years. What is a major advantage of this bank loan compared with a bank overdraft?","options":{"A":"No interest is charged on a bank loan","B":"The bank does not require any financial forecasts or collateral","C":"The café owner can vary the repayment amount every month depending on sales","D":"Fixed monthly repayments make financial planning and budgeting easier"},"correctOption":"D","correctAnswer":"Fixed monthly repayments make financial planning and budgeting easier","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a bank loan has a set repayment schedule over an agreed period, allowing the business to plan its cash outflows accurately.","distractor_reasons":{"A":"Incorrect because banks charge interest on loans as their return for lending money.","B":"Incorrect because banks usually require a business plan, cash flow forecast, and collateral before approving a loan.","C":"Incorrect because bank loans require fixed regular repayments rather than flexible daily adjustments.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_017","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_017","question":"A clothing store negotiates with its fabric supplier to delay paying a $10,000 invoice for 60 days so it can sell the clothes before paying for them. What is a potential drawback of relying heavily on this source of finance?","options":{"A":"The supplier becomes a part-owner of the clothing store","B":"The store may lose early-payment discounts or damage supplier relationships if payments are late","C":"The store must offer its shop premises as security to the supplier","D":"Trade credit counts as a non-current liability on the statement of financial position"},"correctOption":"B","correctAnswer":"The store may lose early-payment discounts or damage supplier relationships if payments are late","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because taking extended trade credit often means forfeiting discounts for prompt payment, and paying late can lead suppliers to refuse future deliveries.","distractor_reasons":{"A":"Incorrect because trade credit is a commercial debt arrangement and does not grant equity ownership.","B":"Correct selection.","C":"Incorrect because trade credit is unsecured short-term credit rather than a secured mortgage.","D":"Incorrect because trade payables are due within 12 months and are recorded as current liabilities."}}},{"id":"P1_U5_MCQ_018","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_018","question":"A solar panel manufacturer plans to build a new assembly plant in an economically depressed region where the government wants to create jobs. Which external source of finance might the manufacturer obtain that does not need to be repaid?","options":{"A":"Venture capital","B":"A bank loan","C":"A government grant","D":"Hire purchase"},"correctOption":"C","correctAnswer":"A government grant","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because government grants are financial awards given to businesses—often to encourage job creation or investment in specific regions—that do not require repayment if conditions are met.","distractor_reasons":{"A":"Incorrect because venture capitalists expect shares in the business and a high financial return when exiting.","B":"Incorrect because a bank loan must be repaid in full with interest.","C":"Correct selection.","D":"Incorrect because hire purchase requires paying full instalments plus interest to acquire an asset."}}},{"id":"P1_U5_MCQ_019","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_019","question":"An independent designer creates a prototype for an eco-friendly backpack and uses an online platform to collect small contributions from 2,500 supporters in exchange for early delivery of the product. Which source of finance is the designer using?","options":{"A":"Crowdfunding","B":"Retained profit","C":"Leasing","D":"Trade credit"},"correctOption":"A","correctAnswer":"Crowdfunding","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because crowdfunding involves raising small sums of money from a large number of people, usually via the internet, to finance a new venture or product.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because retained profit comes from past profits of an existing business rather than external public backers.","C":"Incorrect because leasing is renting non-current assets from a finance company.","D":"Incorrect because trade credit is delayed payment granted by suppliers."}}},{"id":"P1_U5_MCQ_020","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_020","question":"A medium-sized manufacturing company already has large existing bank loans and high monthly interest repayments. Why would the finance director advise against taking out another large bank loan to fund factory expansion?","options":{"A":"Bank loans reduce the company's total assets","B":"Taking another loan forces the company to convert into a sole trader","C":"Bank loans cannot be used to purchase factory buildings","D":"Additional debt increases financial risk and interest costs, making banks reluctant to lend further"},"correctOption":"D","correctAnswer":"Additional debt increases financial risk and interest costs, making banks reluctant to lend further","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because existing loans are a key factor when choosing finance; high existing debt raises default risk, increases interest burdens, and reduces the likelihood of loan approval.","distractor_reasons":{"A":"Incorrect because a bank loan increases cash or non-current assets alongside increasing liabilities.","B":"Incorrect because borrowing from a bank does not alter a business's legal structure.","C":"Incorrect because long-term bank loans and mortgages are commonly used to purchase factory buildings.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_021","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_021","question":"A small family-owned restaurant wants to buy a $4,000 commercial dishwasher. Which factor best explains why issuing shares is NOT a realistic option for raising this finance?","options":{"A":"Commercial dishwashers must legally be bought using retained profit","B":"The amount required is too small to justify the legal and administrative costs of a share issue","C":"Share capital can only be used to pay employee wages","D":"Restaurants are not allowed to raise external finance"},"correctOption":"B","correctAnswer":"The amount required is too small to justify the legal and administrative costs of a share issue","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the amount required ($4,000) is far too small to justify the time, legal formalities, and expense of issuing shares.","distractor_reasons":{"A":"Incorrect because equipment can be bought using cash, loans, leasing, or hire purchase.","B":"Correct selection.","C":"Incorrect because share capital is long-term finance typically used for expansion and non-current assets, not routine wages.","D":"Incorrect because restaurants can use external sources such as bank loans, overdrafts, leasing, and hire purchase."}}},{"id":"P1_U5_MCQ_022","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_022","question":"A logistics company is comparing a bank loan and a share issue to raise $2 million for a new warehouse. If the company's main priority is to minimise the ongoing cost of finance and avoid paying regular interest, which option aligns best with this factor?","options":{"A":"Arranging a $2 million bank overdraft","B":"Taking a variable-rate bank loan","C":"Issuing new ordinary shares","D":"Using 30-day trade credit"},"correctOption":"C","correctAnswer":"Issuing new ordinary shares","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because issuing ordinary shares carries no fixed interest payments, and dividends only need to be paid if the company earns sufficient profit.","distractor_reasons":{"A":"Incorrect because a bank overdraft is short-term and charges high interest rates.","B":"Incorrect because a bank loan requires mandatory regular interest payments regardless of profit levels.","C":"Correct selection.","D":"Incorrect because trade credit is only for short-term inventory purchases, not a $2 million warehouse."}}},{"id":"P1_U5_MCQ_023","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_023","question":"The owners of a private limited company want to expand rapidly by opening ten new stores, but they strongly refuse to lose majority control over business decisions. Why might they prefer a long-term bank loan over selling a 45% stake to venture capitalists?","options":{"A":"A bank loan does not dilute ownership or give the lender voting rights in the company","B":"A bank loan never requires any collateral or security","C":"Venture capitalists charge higher daily interest than a bank overdraft","D":"Private limited companies are not permitted to accept venture capital"},"correctOption":"A","correctAnswer":"A bank loan does not dilute ownership or give the lender voting rights in the company","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because lenders provide debt finance without becoming shareholders, allowing existing owners to retain full voting control over the business.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because banks normally require collateral (such as property) for large long-term loans.","C":"Incorrect because venture capitalists take an equity share and seek capital growth/dividends rather than charging daily interest.","D":"Incorrect because private limited companies can sell shares privately to venture capitalists."}}},{"id":"P1_U5_MCQ_024","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_024","question":"A sole trader operates a small carpentry business from a rented workshop and needs $2,500 to buy timber for a large customer order that will be paid in 45 days. Which combination of factors most strongly points toward using trade credit or a short-term overdraft?","options":{"A":"Large amount required and public limited legal status","B":"Long-term time period and purchase of land","C":"High existing retained profit and international expansion","D":"Small amount required, unincorporated legal form, and short-term working capital purpose"},"correctOption":"D","correctAnswer":"Small amount required, unincorporated legal form, and short-term working capital purpose","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the small sum ($2,500), sole trader status, and 45-day working capital purpose directly match short-term sources like trade credit or an overdraft.","distractor_reasons":{"A":"Incorrect because $2,500 is a small amount and a sole trader is unincorporated, not a public limited company.","B":"Incorrect because the finance is needed for 45 days to buy raw materials (timber), not long-term land.","C":"Incorrect because the business is a small local workshop funding a single order, not expanding internationally.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_025","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_025","question":"To launch a new catering business, an entrepreneur invests $32,000 of personal savings, raises $6,000 by selling an unused personal delivery van to the business, and secures a $10,000 government start-up grant. How much of this start-up finance comes from internal sources?","options":{"A":"$48,000","B":"$32,000","C":"$38,000","D":"$16,000"},"correctOption":"C","correctAnswer":"$38,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because internal sources of finance include the owner's personal investment ($32,000) and the sale of unwanted assets ($6,000), totalling $38,000, whereas the government grant is external.","distractor_reasons":{"A":"Incorrect because $48,000 includes the $10,000 government grant, which is an external source of finance.","B":"Incorrect because $32,000 omits the $6,000 raised from the sale of the unwanted asset.","C":"Correct selection.","D":"Incorrect because $16,000 adds the asset sale and external grant while omitting the owner's $32,000 investment."}}},{"id":"P1_U5_MCQ_026","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_026","question":"A profitable building contractor is forced to cease trading because it has no money in its bank account to pay its bricklayers' weekly wages or buy cement. Why is cash so vital to the survival of a business?","options":{"A":"Cash is needed to pay day-to-day obligations such as wages, suppliers, and bills as they fall due","B":"Cash is the only figure reported on a statement of profit or loss","C":"Businesses cannot legally make credit sales unless they hold large cash reserves","D":"Cash held in a current account always earns a higher return than investing in machinery"},"correctOption":"A","correctAnswer":"Cash is needed to pay day-to-day obligations such as wages, suppliers, and bills as they fall due","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because without sufficient cash (liquidity), a business cannot pay employees, suppliers, or landlords on time and may be forced into liquidation even if it is profitable.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the statement of profit or loss records revenue, cost of sales, expenses, and profit, not cash balances.","C":"Incorrect because there is no legal rule requiring cash reserves before offering trade credit to customers.","D":"Incorrect because cash in a bank account typically earns very low interest compared to productive non-current assets."}}},{"id":"P1_U5_MCQ_027","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_027","question":"Before approving a $40,000 loan for a new restaurant, a bank manager asks the entrepreneur to submit a cash flow forecast for the first 12 months. What does a cash flow forecast show?","options":{"A":"The historical revenue and expenses of the business over the past 12 months","B":"The market value of all non-current assets and equity at the end of the year","C":"An estimate of expected monthly cash inflows, cash outflows, and closing cash balances over a future period","D":"The exact amount of corporation tax the business paid last year"},"correctOption":"C","correctAnswer":"An estimate of expected monthly cash inflows, cash outflows, and closing cash balances over a future period","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a cash flow forecast is a forward-looking financial plan estimating expected cash receipts and payments month by month to predict surpluses or deficits.","distractor_reasons":{"A":"Incorrect because historical revenue and expenses are shown in a past statement of profit or loss, not a future cash flow forecast.","B":"Incorrect because assets, liabilities, and equity at a point in time are shown on a statement of financial position.","C":"Correct selection.","D":"Incorrect because past tax payments are historical records rather than a forecast of future monthly cash flows."}}},{"id":"P1_U5_MCQ_028","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_028","question":"The finance manager of a toy manufacturer prepares a six-month cash flow forecast every quarter. How does this forecast most directly help management make financial decisions?","options":{"A":"It calculates the exact gross profit margin on every toy sold","B":"It identifies future months with potential cash deficits in advance so an overdraft can be arranged","C":"It guarantees that all customers will pay their invoices on time","D":"It eliminates the need to prepare a statement of financial position"},"correctOption":"B","correctAnswer":"It identifies future months with potential cash deficits in advance so an overdraft can be arranged","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because forecasting future cash balances alerts managers early to potential cash shortfalls, giving them time to arrange an overdraft or adjust spending.","distractor_reasons":{"A":"Incorrect because gross profit margin is calculated from revenue and cost of sales in the statement of profit or loss.","B":"Correct selection.","C":"Incorrect because a forecast estimates expected receipts; it does not legally force customers to pay promptly.","D":"Incorrect because limited companies are still legally required to produce end-of-year financial statements."}}},{"id":"P1_U5_MCQ_029","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_029","question":"A bicycle retailer records several transactions in October: $12,000 in cash sales, $8,000 in goods sold on 30-day credit, $5,000 received from September credit customers, and $7,000 paid to suppliers. Which items are recorded as October cash inflows?","options":{"A":"$12,000 cash sales and $8,000 October credit sales","B":"$12,000 cash sales, $8,000 October credit sales, and $5,000 from September customers","C":"$8,000 October credit sales and $7,000 paid to suppliers","D":"$12,000 cash sales and $5,000 received from September credit customers"},"correctOption":"D","correctAnswer":"$12,000 cash sales and $5,000 received from September credit customers","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because cash inflows only record money actually entering the business during October ($12,000 cash sales + $5,000 collected from previous credit customers = $17,000).","distractor_reasons":{"A":"Incorrect because the $8,000 credit sales made in October will not generate a cash inflow until November.","B":"Incorrect because including both October credit sales and September receipts double-counts credit transactions before cash arrives.","C":"Incorrect because $8,000 is an unpaid credit sale and $7,000 paid to suppliers is a cash outflow.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_030","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_030","question":"During November, a printing business pays $6,500 in staff wages, receives a $15,000 bank loan, orders $4,000 of paper on 60-day trade credit, and pays $2,000 in workshop rent. Which items are November cash outflows?","options":{"A":"$6,500 wages and $2,000 workshop rent","B":"$6,500 wages, $2,000 rent, and $4,000 paper ordered on 60-day credit","C":"$15,000 bank loan and $6,500 wages","D":"$4,000 paper ordered on 60-day credit and $15,000 bank loan"},"correctOption":"A","correctAnswer":"$6,500 wages and $2,000 workshop rent","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cash outflows only include money actually leaving the business in November ($6,500 wages + $2,000 rent = $8,500).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the $4,000 paper ordered on 60-day trade credit will not be a cash outflow until January.","C":"Incorrect because receiving a $15,000 bank loan is a cash inflow, not an outflow.","D":"Incorrect because the loan is an inflow and the credit order has no cash movement in November."}}},{"id":"P1_U5_MCQ_031","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_031","question":"In July, a garden centre forecasts total cash inflows of $24,500 and total cash outflows of $28,200, with an opening bank balance of $5,000. What is the forecast net cash flow for July?","options":{"A":"$1,300","B":"$3,700","C":"-$3,700","D":"$52,700"},"correctOption":"C","correctAnswer":"-$3,700","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because net cash flow equals cash inflows minus cash outflows ($24,500 - $28,200 = -$3,700).","distractor_reasons":{"A":"Incorrect because $1,300 is the closing balance ($5,000 opening balance + (-$3,700) net cash flow), not the net cash flow.","B":"Incorrect because outflows exceed inflows, making the net cash flow negative (-$3,700) rather than positive.","C":"Correct selection.","D":"Incorrect because $52,700 adds inflows and outflows together instead of subtracting outflows from inflows."}}},{"id":"P1_U5_MCQ_032","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_032","question":"A florist starts August with an opening cash balance of $3,200. During August, total cash inflows are $19,800 and total cash outflows are $16,400. What is the florist's closing cash balance at the end of August?","options":{"A":"$3,400","B":"$6,600","C":"-$200","D":"$23,000"},"correctOption":"B","correctAnswer":"$6,600","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because net cash flow is $19,800 - $16,400 = $3,400, and closing balance equals opening balance plus net cash flow ($3,200 + $3,400 = $6,600).","distractor_reasons":{"A":"Incorrect because $3,400 is the net cash flow for August and ignores the $3,200 opening balance.","B":"Correct selection.","C":"Incorrect because -$200 subtracts net cash flow from the opening balance instead of adding it.","D":"Incorrect because $23,000 adds opening balance and inflows without deducting the $16,400 cash outflows."}}},{"id":"P1_U5_MCQ_033","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_033","question":"A small hotel begins September with an overdrawn opening cash balance of -$2,400. During September, cash inflows are $31,000 and cash outflows are $27,500. What is the closing cash balance at the end of September?","options":{"A":"$3,500","B":"-$5,900","C":"$5,900","D":"$1,100"},"correctOption":"D","correctAnswer":"$1,100","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because September's net cash flow is $31,000 - $27,500 = +$3,500, and adding this to the -$2,400 opening balance gives a positive closing balance of $1,100.","distractor_reasons":{"A":"Incorrect because $3,500 is the net cash flow and ignores the -$2,400 overdrawn opening balance.","B":"Incorrect because -$5,900 subtracts the positive net cash flow from -$2,400 instead of adding it.","C":"Incorrect because $5,900 treats the -$2,400 overdraft as a positive opening balance.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_034","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_034","question":"A courier business completes its cash flow forecast for Quarter 1 and finds that February ends with a closing balance of -$4,150. How is this figure used when preparing the forecast for March?","options":{"A":"It is entered as March's opening balance of -$4,150","B":"It is recorded as a March cash outflow of $4,150","C":"It is ignored so that March begins with an opening balance of $0","D":"It is deducted from March's total revenue on the statement of profit or loss"},"correctOption":"A","correctAnswer":"It is entered as March's opening balance of -$4,150","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the closing cash balance at the end of one month automatically carries forward to become the opening cash balance at the start of the next month.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because carrying a balance forward is not a new cash outflow transaction in March.","C":"Incorrect because resetting the opening balance to $0 would hide the existing overdraft and distort March's closing cash position.","D":"Incorrect because cash balances are not deducted from revenue in the statement of profit or loss."}}},{"id":"P1_U5_MCQ_035","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_035","question":"A coffee shop's April cash flow forecast shows an opening balance of $2,500, inflows of $14,000, and outflows of $13,000. The owner then decides to pay $4,800 cash in April for a new espresso machine. What is the amended April closing balance?","options":{"A":"$3,500","B":"$8,300","C":"-$1,300","D":"-$3,800"},"correctOption":"C","correctAnswer":"-$1,300","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because original outflows of $13,000 rise to $17,800 ($13,000 + $4,800), resulting in a net cash flow of -$3,800 ($14,000 - $17,800) and a closing balance of -$1,300 ($2,500 - $3,800).","distractor_reasons":{"A":"Incorrect because $3,500 is the original closing balance before including the $4,800 cash outflow for the espresso machine.","B":"Incorrect because $8,300 adds the $4,800 equipment purchase as a cash inflow instead of an outflow.","C":"Correct selection.","D":"Incorrect because -$3,800 is the amended net cash flow and ignores the $2,500 opening balance."}}},{"id":"P1_U5_MCQ_036","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_036","question":"A ski-resort hotel's annual cash flow forecast shows positive closing balances from December to April, followed by negative closing balances in May and June, before returning to strong positive balances from July onward. What is the most sensible action for the hotel manager to take?","options":{"A":"Permanently close the hotel because it will never survive","B":"Arrange a short-term bank overdraft to cover the temporary cash deficit in May and June","C":"Issue new ordinary shares on the stock exchange to cover the two-month gap","D":"Double room prices in May and June when tourist demand is lowest"},"correctOption":"B","correctAnswer":"Arrange a short-term bank overdraft to cover the temporary cash deficit in May and June","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the cash deficit is temporary and seasonal, making a short-term overdraft ideal until positive cash flows resume in July.","distractor_reasons":{"A":"Incorrect because the hotel generates strong positive cash flows during most of the year and only faces a brief seasonal dip.","B":"Correct selection.","C":"Incorrect because issuing shares is a permanent, expensive long-term measure unsuitable for a two-month seasonal shortfall.","D":"Incorrect because doubling prices during low-demand months would likely reduce bookings and worsen cash inflows."}}},{"id":"P1_U5_MCQ_037","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_037","question":"An ice-cream manufacturer spends heavily on ingredients, packaging, and wages in March and April to build up inventory, resulting in negative net cash flows, before collecting large cash receipts from supermarkets in June and July. What does this pattern illustrate?","options":{"A":"The business is making a severe financial loss and is bankrupt","B":"Cash outflows for production often occur months before cash inflows from seasonal sales","C":"Supermarkets are refusing to pay for the ice cream delivered","D":"A cash flow forecast is unnecessary for seasonal manufacturers"},"correctOption":"B","correctAnswer":"Cash outflows for production often occur months before cash inflows from seasonal sales","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because seasonal businesses frequently incur production cash outflows ahead of peak selling seasons, creating temporary negative net cash flows before sales receipts arrive.","distractor_reasons":{"A":"Incorrect because temporary negative net cash flows while building seasonal inventory do not mean the business is unprofitable or insolvent.","B":"Correct selection.","C":"Incorrect because the scenario states large cash receipts arrive from supermarkets in June and July.","D":"Incorrect because seasonal businesses need cash flow forecasts even more to plan financing for off-peak months."}}},{"id":"P1_U5_MCQ_038","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_038","question":"A retail business overcomes a one-month cash flow deficit by using an agreed bank overdraft. What is a significant risk of relying on a bank overdraft to solve cash flow problems?","options":{"A":"The bank charges relatively high interest and can demand immediate repayment at any time","B":"The business must give the bank a share of all future profits","C":"An overdraft locks the business into fixed repayments for 15 years","D":"Using an overdraft prevents the business from making credit sales"},"correctOption":"A","correctAnswer":"The bank charges relatively high interest and can demand immediate repayment at any time","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because bank overdrafts usually carry high interest rates and are technically repayable on demand if the bank withdraws the facility.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a bank is a lender charging interest, not an equity shareholder receiving profit shares.","C":"Incorrect because an overdraft is a flexible short-term facility, unlike a 15-year mortgage.","D":"Incorrect because an overdraft has no restriction on how a business sells to its customers."}}},{"id":"P1_U5_MCQ_039","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_039","question":"To resolve a temporary cash shortage, a furniture retailer negotiates with its timber suppliers to extend payment terms from 30 days to 60 days. What is a likely disadvantage of delaying payments to suppliers?","options":{"A":"The retailer's current assets will immediately fall by half","B":"The retailer will have to pay higher interest to its own bank","C":"Suppliers may refuse future deliveries, charge higher prices, or withdraw early-payment discounts","D":"Customers will stop buying furniture from the retailer"},"correctOption":"C","correctAnswer":"Suppliers may refuse future deliveries, charge higher prices, or withdraw early-payment discounts","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because delaying supplier payments can strain relationships, result in the loss of prompt-payment discounts, or cause suppliers to withhold future supplies.","distractor_reasons":{"A":"Incorrect because delaying payment keeps cash in the business rather than reducing current assets.","B":"Incorrect because trade credit is provided by suppliers, not the retailer's bank.","C":"Correct selection.","D":"Incorrect because extending payment terms with suppliers does not directly affect customers unless supplies run out."}}},{"id":"P1_U5_MCQ_040","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_040","question":"An industrial cleaning company is short of cash because its business clients take 60 days to pay invoices. To speed up cash inflows, the company reduces its credit period to 30 days and offers a 2% discount for immediate payment. What is a possible drawback of this strategy?","options":{"A":"It increases the company's non-current liabilities","B":"Customers may switch to competitors offering longer credit periods, and discounts reduce profit margins","C":"It delays when cash inflows appear on the cash flow forecast","D":"Suppliers will demand immediate cash payment for cleaning materials"},"correctOption":"B","correctAnswer":"Customers may switch to competitors offering longer credit periods, and discounts reduce profit margins","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because tightening credit terms can drive customers to rivals with more generous terms, while offering discounts reduces revenue and profit per sale.","distractor_reasons":{"A":"Incorrect because changing customer credit policies affects trade receivables and cash, not long-term debt.","B":"Correct selection.","C":"Incorrect because shorter credit periods accelerate cash inflows rather than delaying them.","D":"Incorrect because customer credit policies do not automatically alter supplier payment agreements."}}},{"id":"P1_U5_MCQ_041","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_041","question":"A catering firm facing a short-term cash flow deficit decides to postpone buying a $22,000 refrigerated delivery van for six months. What is a potential disadvantage of delaying the purchase of this non-current asset?","options":{"A":"The firm's immediate cash outflows will increase","B":"The firm will lose control to external shareholders","C":"The firm will have to pay higher corporation tax immediately","D":"The existing old van may break down, leading to higher repair costs and lost customer orders"},"correctOption":"D","correctAnswer":"The existing old van may break down, leading to higher repair costs and lost customer orders","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because postponing the replacement of ageing equipment can result in higher maintenance bills, lower efficiency, and unreliable deliveries.","distractor_reasons":{"A":"Incorrect because delaying the purchase reduces immediate cash outflows rather than increasing them.","B":"Incorrect because postponing capital expenditure does not involve issuing shares.","C":"Incorrect because delaying an asset purchase does not trigger an immediate tax penalty.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_042","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_042","question":"A wholesaler has a forecast closing cash balance of -$9,000 next month and wants to improve its short-term cash position immediately. Which action would actually WORSEN the wholesaler's short-term cash flow problem?","options":{"A":"Buying extra inventory for cash to take advantage of a supplier bulk discount","B":"Arranging a temporary $12,000 overdraft facility with its bank","C":"Chasing overdue trade receivables to pay their invoices within seven days","D":"Postponing the cash purchase of new warehouse shelving"},"correctOption":"A","correctAnswer":"Buying extra inventory for cash to take advantage of a supplier bulk discount","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because spending cash immediately to buy extra inventory increases cash outflows right away, making the -$9,000 deficit even larger.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because an overdraft provides immediate short-term funding to cover the cash shortfall.","C":"Incorrect because collecting trade receivables faster accelerates cash inflows.","D":"Incorrect because delaying the cash purchase of non-current assets reduces cash outflows."}}},{"id":"P1_U5_MCQ_043","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_043","question":"In March, an office furniture manufacturer sells $95,000 worth of desks on 60-day credit after paying $55,000 in cash for wood, metal, and factory wages. Why does the manufacturer show a profit of $40,000 for March despite having a negative net cash flow of -$55,000?","options":{"A":"Profit is only calculated at the end of ten years of trading","B":"Wages and raw materials are excluded from the statement of profit or loss","C":"Revenue is recorded when the credit sale is made, whereas cash inflows will not arrive until May","D":"Credit sales are never included in revenue until the customer pays cash"},"correctOption":"C","correctAnswer":"Revenue is recorded when the credit sale is made, whereas cash inflows will not arrive until May","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because profit is calculated from revenue earned minus costs incurred during the period, whereas cash flow only records actual cash movements—and the $95,000 cash will not arrive for 60 days.","distractor_reasons":{"A":"Incorrect because profit is normally calculated annually (or monthly/quarterly), not every ten years.","B":"Incorrect because wages and raw materials are deducted as costs when calculating profit.","C":"Correct selection.","D":"Incorrect because revenue includes both cash and credit sales made during the trading period."}}},{"id":"P1_U5_MCQ_044","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_044","question":"A clothing retailer makes a trading loss of -$8,000 in January, yet its bank balance increases by $15,000 during the same month. Which event best explains how a loss-making business can experience a positive net cash flow?","options":{"A":"The retailer sold all of its January goods on 90-day credit to customers","B":"The retailer received a $25,000 bank loan and sold off old inventory for cash","C":"The retailer paid all of its annual rent and insurance bills in cash during January","D":"The retailer purchased new shop fittings for cash in January"},"correctOption":"B","correctAnswer":"The retailer received a $25,000 bank loan and sold off old inventory for cash","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because receiving a bank loan is a cash inflow that does not count as trading revenue, allowing cash balances to rise even while the business makes a trading loss.","distractor_reasons":{"A":"Incorrect because selling on 90-day credit delays cash inflows and would worsen January's cash balance.","B":"Correct selection.","C":"Incorrect because paying annual bills upfront causes large cash outflows, reducing the bank balance.","D":"Incorrect because buying shop fittings for cash is a cash outflow that lowers the bank balance."}}},{"id":"P1_U5_MCQ_045","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_045","question":"A stationery wholesaler sells $15,000 of paper to a school on 1-month trade credit in April, and the school pays the invoice in full in May. In which month should the $15,000 appear as a cash inflow on the wholesaler's cash flow forecast?","options":{"A":"April, because that is when the paper was delivered","B":"Split equally with $7,500 in April and $7,500 in May","C":"Neither April nor May, because credit sales are excluded from cash flow forecasts","D":"May, because that is when the cash actually enters the wholesaler's bank account"},"correctOption":"D","correctAnswer":"May, because that is when the cash actually enters the wholesaler's bank account","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a cash flow forecast records cash inflows in the month the payment is actually received (May), not when the credit sale occurred.","distractor_reasons":{"A":"Incorrect because recording the sale in April applies to revenue on the statement of profit or loss, not the cash flow forecast.","B":"Incorrect because the school paid the full $15,000 in May rather than in two instalments.","C":"Incorrect because credit sales do appear on the cash flow forecast once the customer pays cash.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_046","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_046","question":"A logistics startup needs a $60,000 truck and chooses to lease it for $1,400 per month instead of buying it outright for cash. How does this decision affect the startup's Month 1 cash flow forecast?","options":{"A":"Cash outflows in Month 1 are $58,600 lower, improving the opening liquidity position","B":"Cash inflows in Month 1 increase by $60,000","C":"Month 1 net cash flow is completely unaffected by how the truck is financed","D":"The startup's closing balance in Month 1 becomes negative by $60,000"},"correctOption":"A","correctAnswer":"Cash outflows in Month 1 are $58,600 lower, improving the opening liquidity position","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because leasing requires only a $1,400 monthly payment instead of a $60,000 cash outflow in Month 1, preserving $58,600 of cash.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because leasing a truck is a cash outflow (rental expense), not a cash inflow.","C":"Incorrect because an outright purchase creates a $60,000 outflow immediately, whereas leasing spreads outflows over time.","D":"Incorrect because leasing avoids the large $60,000 upfront cash drain."}}},{"id":"P1_U5_MCQ_047","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_047","question":"At the end of the year, a café owner notices that her actual closing bank balance is $6,000 lower than predicted in her original cash flow forecast. What is a common limitation of cash flow forecasts that explains this difference?","options":{"A":"Cash flow forecasts are legally forbidden from including variable costs","B":"Cash flow forecasts only record non-cash items like depreciation","C":"Forecasts rely on estimates, so unexpected cost increases or lower-than-expected sales cause inaccuracies","D":"Cash flow forecasts ignore all cash inflows from customers"},"correctOption":"C","correctAnswer":"Forecasts rely on estimates, so unexpected cost increases or lower-than-expected sales cause inaccuracies","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because cash flow forecasts are based on predictions of future sales, customer payment times, and costs, which can change unexpectedly in reality.","distractor_reasons":{"A":"Incorrect because all expected cash outflows, including variable material and wage costs, are included in a cash flow forecast.","B":"Incorrect because cash flow forecasts exclude non-cash items and only record actual cash movements.","C":"Correct selection.","D":"Incorrect because customer receipts are the primary cash inflows in a cash flow forecast."}}},{"id":"P1_U5_MCQ_048","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_048","question":"A struggling bookstore's cash flow forecast predicts a negative net cash flow every single month for the next two years, causing its overdraft to grow continuously. Why is increasing its bank overdraft NOT an appropriate long-term solution?","options":{"A":"Bank overdrafts cannot be used to pay employee wages","B":"An overdraft is expensive, repayable on demand, and will not fix a fundamental lack of sales or excessive costs","C":"Overdrafts automatically convert into government grants after 12 months","D":"Banks legally forbid businesses from using overdrafts for more than two days"},"correctOption":"B","correctAnswer":"An overdraft is expensive, repayable on demand, and will not fix a fundamental lack of sales or excessive costs","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because continuous negative net cash flows indicate a long-term profitability or structural issue that requires raising prices, cutting costs, or securing long-term finance rather than relying on costly short-term overdraft debt.","distractor_reasons":{"A":"Incorrect because overdraft funds in a current account can be used to pay wages and other expenses.","B":"Correct selection.","C":"Incorrect because overdrafts are repayable debts that accrue interest, not non-repayable grants.","D":"Incorrect because businesses can use an agreed overdraft facility throughout the year, though it is meant for temporary deficits."}}},{"id":"P1_U5_MCQ_049","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_049","question":"A manufacturer's cash flow forecast shows closing balances of +$4,000 in January, -$2,500 in February, -$7,800 in March, and -$1,200 in April. When arranging a flexible overdraft facility with its bank, what minimum overdraft limit must the manufacturer secure?","options":{"A":"$1,200","B":"$2,500","C":"$4,000","D":"$7,800"},"correctOption":"D","correctAnswer":"$7,800","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the largest forecast negative closing balance occurs in March at -$7,800, so the overdraft limit must be at least $7,800 to cover peak borrowing needs.","distractor_reasons":{"A":"Incorrect because a $1,200 limit would only cover April and leave the business unable to pay bills in February and March.","B":"Incorrect because a $2,500 limit would cover February but fall short of March's -$7,800 deficit.","C":"Incorrect because $4,000 is January's positive cash surplus, not the peak overdraft needed in March.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_050","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_050","question":"A fast-growing electronics assembler wins several huge contracts from retail chains, requiring it to buy triple its normal volume of components and hire extra staff months before the retailers pay their 60-day invoices. Why does rapid expansion frequently cause a cash flow crisis?","options":{"A":"Cash outflows for materials and wages rise immediately, while cash inflows from credit sales are delayed","B":"Rapid growth causes fixed costs to fall to zero","C":"Winning large contracts makes a business immediately unprofitable","D":"Banks automatically freeze the accounts of fast-growing companies"},"correctOption":"A","correctAnswer":"Cash outflows for materials and wages rise immediately, while cash inflows from credit sales are delayed","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because expanding output requires immediate cash outflows for extra inventory and labour long before cash is collected from new credit customers (overtrading).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because rapid expansion typically increases total costs rather than reducing fixed costs to zero.","C":"Incorrect because the contracts can be highly profitable on paper while still causing a temporary cash shortfall.","D":"Incorrect because banks do not automatically freeze accounts simply because sales are growing."}}},{"id":"P1_U5_MCQ_051","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_051","question":"At the end of its financial year, a sole trader's total revenue is $180,000 and total costs are $145,000, leaving a surplus of $35,000. Which statement accurately defines this $35,000 profit?","options":{"A":"It is the exact amount of physical cash sitting in the business's bank account","B":"It is the financial surplus remaining after total costs have been subtracted from total revenue","C":"It is the total value of all property and machinery owned by the sole trader","D":"It is the gross revenue earned before deducting any cost of sales"},"correctOption":"B","correctAnswer":"It is the financial surplus remaining after total costs have been subtracted from total revenue","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because profit is defined as total revenue minus total costs (or gross profit minus expenses) over a trading period.","distractor_reasons":{"A":"Incorrect because profit includes credit sales and non-cash adjustments and rarely equals the exact bank balance.","B":"Correct selection.","C":"Incorrect because property and machinery are non-current assets shown on the statement of financial position.","D":"Incorrect because revenue before deducting cost of sales is $180,000, whereas $35,000 is the final profit after all costs."}}},{"id":"P1_U5_MCQ_052","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_052","question":"An entrepreneur leaves a secure salaried job and invests $50,000 of personal savings to launch a speciality coffee roastery. Why is making a profit essential to this private sector entrepreneur?","options":{"A":"Profit eliminates all business risks automatically","B":"Profit is legally required by the government for every sole trader in Year 1","C":"Profit reduces the business's gross profit margin to zero","D":"Profit acts as the financial reward for risk-taking and investing capital"},"correctOption":"D","correctAnswer":"Profit acts as the financial reward for risk-taking and investing capital","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because private sector entrepreneurs risk their own savings and foregone salary, so profit provides the essential reward for taking those risks.","distractor_reasons":{"A":"Incorrect because making a profit does not eliminate future market or economic risks.","B":"Incorrect because many new businesses make a loss in their first year without breaking any law.","C":"Incorrect because higher profit increases profitability rather than reducing gross profit margin.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_053","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_053","question":"A family-owned private limited company wants to open two new bakeries without taking out bank loans or selling shares to outsiders. How does making a healthy annual profit help the company achieve this goal?","options":{"A":"Retained profit provides an interest-free internal source of finance for expansion","B":"Profit increases the company's current liabilities on the statement of financial position","C":"Profit forces suppliers to provide free raw materials","D":"Profit allows the company to avoid paying employee wages"},"correctOption":"A","correctAnswer":"Retained profit provides an interest-free internal source of finance for expansion","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because profit retained in the business after tax and dividends serves as an internal source of finance for growth without interest or loss of control.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because retained profit increases equity/capital employed rather than current liabilities.","C":"Incorrect because profitable businesses still have to pay suppliers for materials.","D":"Incorrect because employee wages are a contractual expense that must be paid regardless of profit."}}},{"id":"P1_U5_MCQ_054","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_054","question":"The directors of a sporting goods company compare this year's profit of $320,000 against last year's profit of $240,000 and against a rival's profit of $280,000. Which role of profit is illustrated by this comparison?","options":{"A":"Using profit as a measure of short-term liquidity","B":"Using profit to calculate the company's current ratio","C":"Using profit as an indicator and measure of business success","D":"Using profit to determine the exact number of employees"},"correctOption":"C","correctAnswer":"Using profit as an indicator and measure of business success","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because profit is a primary indicator used by owners and managers to measure how successful a business is over time and relative to competitors.","distractor_reasons":{"A":"Incorrect because liquidity is measured using cash flow and liquidity ratios, not profit alone.","B":"Incorrect because the current ratio compares current assets to current liabilities.","C":"Correct selection.","D":"Incorrect because employee numbers are a measure of business size, not profit."}}},{"id":"P1_U5_MCQ_055","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_055","question":"A growing public limited company announces three consecutive years of rising profits and higher dividend payouts. Why is this profit performance important when the company decides to issue new shares?","options":{"A":"High profits legally exempt the company from publishing annual accounts","B":"Strong profits attract investors who expect reliable dividends and rising share prices","C":"High profits reduce the company's revenue on the statement of profit or loss","D":"Profitable companies do not need to pay for raw materials"},"correctOption":"B","correctAnswer":"Strong profits attract investors who expect reliable dividends and rising share prices","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because consistent profits demonstrate financial strength and the ability to pay dividends, attracting new investors to buy shares.","distractor_reasons":{"A":"Incorrect because all limited companies must legally file and publish annual accounts regardless of profit.","B":"Correct selection.","C":"Incorrect because higher profits usually result from higher revenue or lower costs, not reduced revenue.","D":"Incorrect because cost of sales is still incurred when producing goods."}}},{"id":"P1_U5_MCQ_056","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_056","question":"A social enterprise that employs disadvantaged workers to recycle plastic waste makes an annual profit of $45,000. How does the importance of profit for this social enterprise differ from that of a typical public limited company?","options":{"A":"Social enterprises are legally prohibited from making any profit","B":"Social enterprises distribute 100% of their profit as cash dividends to stock exchange investors","C":"Social enterprises do not record revenue or expenses on a statement of profit or loss","D":"Profit is mainly reinvested back into the business to expand its social and environmental impact rather than maximising shareholder dividends"},"correctOption":"D","correctAnswer":"Profit is mainly reinvested back into the business to expand its social and environmental impact rather than maximising shareholder dividends","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because social enterprises aim to make a profit primarily to reinvest in achieving their social and environmental objectives rather than paying high dividends to private shareholders.","distractor_reasons":{"A":"Incorrect because social enterprises do aim to make a profit in order to remain financially sustainable and grow.","B":"Incorrect because social enterprises are not focused on maximising dividend payouts to stock market shareholders.","C":"Incorrect because social enterprises still track revenue, costs, and profit on their financial statements.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_057","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_057","question":"During June, an online t-shirt store sells 3,500 t-shirts at an average selling price of $14 each, while spending $21,000 on blank t-shirts and printing ink. What is the store's revenue for June?","options":{"A":"$49,000","B":"$28,000","C":"$70,000","D":"$3,500"},"correctOption":"A","correctAnswer":"$49,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because revenue equals selling price per unit multiplied by number of units sold ($14 × 3,500 = $49,000).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $28,000 is the gross profit ($49,000 revenue - $21,000 cost of sales), not total revenue.","C":"Incorrect because $70,000 adds cost of sales to revenue instead of keeping revenue separate.","D":"Incorrect because 3,500 is the sales volume in units, not the dollar sales revenue."}}},{"id":"P1_U5_MCQ_058","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_058","question":"A supermarket chain is preparing its annual statement of profit or loss. Which item should be classified under 'cost of sales' rather than 'expenses'?","options":{"A":"Head office administrative salaries","B":"Television advertising campaigns","C":"Wholesale cost of groceries bought from suppliers for resale","D":"Interest paid on a long-term bank loan"},"correctOption":"C","correctAnswer":"Wholesale cost of groceries bought from suppliers for resale","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because cost of sales represents the direct cost of purchasing or manufacturing the goods that were actually sold during the period.","distractor_reasons":{"A":"Incorrect because head office salaries are indirect overhead expenses deducted after gross profit.","B":"Incorrect because advertising is a marketing overhead expense rather than a direct product cost.","C":"Correct selection.","D":"Incorrect because loan interest is a finance expense deducted after gross profit."}}},{"id":"P1_U5_MCQ_059","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_059","question":"An electronics shop records annual revenue of $340,000, cost of sales of $215,000, and overhead expenses of $75,000. What is the shop's gross profit?","options":{"A":"$50,000","B":"$125,000","C":"$265,000","D":"$555,000"},"correctOption":"B","correctAnswer":"$125,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because gross profit equals revenue minus cost of sales ($340,000 - $215,000 = $125,000).","distractor_reasons":{"A":"Incorrect because $50,000 is the final profit after deducting both cost of sales and $75,000 of overhead expenses.","B":"Correct selection.","C":"Incorrect because $265,000 subtracts overhead expenses from revenue instead of cost of sales.","D":"Incorrect because $555,000 adds revenue and cost of sales together."}}},{"id":"P1_U5_MCQ_060","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_060","question":"A bakery's statement of profit or loss shows revenue of $160,000, cost of sales of $65,000, and total overhead expenses (rent, shop wages, and utilities) of $58,000. What is the bakery's profit?","options":{"A":"$95,000","B":"$102,000","C":"$123,000","D":"$37,000"},"correctOption":"D","correctAnswer":"$37,000","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because gross profit is $160,000 - $65,000 = $95,000, and profit equals gross profit minus overhead expenses ($95,000 - $58,000 = $37,000).","distractor_reasons":{"A":"Incorrect because $95,000 is the gross profit before deducting the $58,000 of overhead expenses.","B":"Incorrect because $102,000 deducts only expenses from revenue and ignores cost of sales.","C":"Incorrect because $123,000 adds cost of sales and expenses together ($65,000 + $58,000).","D":"Correct selection."}}},{"id":"P1_U5_MCQ_061","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_061","question":"In a statement of profit or loss, gross profit is calculated first, and then overhead expenses are subtracted to find profit. Which of the following is an example of an overhead expense?","options":{"A":"Office rent, insurance, and marketing salaries","B":"Raw materials used directly on the factory assembly line","C":"Total revenue from selling finished products","D":"Share capital invested by the founders"},"correctOption":"A","correctAnswer":"Office rent, insurance, and marketing salaries","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because office rent, insurance, and marketing salaries are indirect running costs (expenses) subtracted from gross profit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because direct raw materials are part of cost of sales, deducted before gross profit.","C":"Incorrect because sales revenue is the top line of the statement of profit or loss, not an expense.","D":"Incorrect because share capital is equity recorded on the statement of financial position."}}},{"id":"P1_U5_MCQ_062","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_062","question":"A private limited company earns a profit after tax of $110,000, and its directors decide to pay $40,000 in dividends to shareholders. What happens to the remaining $70,000?","options":{"A":"It is recorded as a current liability owed to customers","B":"It is paid to the government as an additional sales tax","C":"It becomes retained profit, which is kept in the business to help finance future operations","D":"It is added to cost of sales for the following year"},"correctOption":"C","correctAnswer":"It becomes retained profit, which is kept in the business to help finance future operations","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because any profit remaining after tax and dividend distributions is retained profit, reinvested in the business as an internal source of finance.","distractor_reasons":{"A":"Incorrect because retained profit belongs to the equity of the business, not to customers.","B":"Incorrect because the $110,000 figure is already profit after tax.","C":"Correct selection.","D":"Incorrect because retained profit is an equity reserve on the statement of financial position, not an expense."}}},{"id":"P1_U5_MCQ_063","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_063","question":"A global coffee shortage forces a café chain to pay 20% more for coffee beans, while the chain keeps its menu prices and overhead expenses unchanged. How will this affect the chain's statement of profit or loss?","options":{"A":"Revenue will increase and gross profit will rise","B":"Cost of sales will increase, causing both gross profit and final profit to fall","C":"Gross profit will stay the same, but overhead expenses will increase","D":"Cost of sales will fall, increasing final profit"},"correctOption":"B","correctAnswer":"Cost of sales will increase, causing both gross profit and final profit to fall","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because coffee beans are a direct ingredient in cost of sales; higher bean prices raise cost of sales, which lowers gross profit and consequently reduces final profit.","distractor_reasons":{"A":"Incorrect because menu prices and sales volume did not increase, so revenue does not rise.","B":"Correct selection.","C":"Incorrect because coffee beans are part of cost of sales rather than indirect overhead expenses, so gross profit falls.","D":"Incorrect because paying 20% more for beans increases costs rather than reducing them."}}},{"id":"P1_U5_MCQ_064","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_064","question":"A stationery retailer spends an extra $12,000 on local radio advertising during December, but its sales revenue and cost of sales remain completely unchanged. What is the impact on its statement of profit or loss?","options":{"A":"Both gross profit and final profit fall by $12,000","B":"Gross profit falls by $12,000, while final profit stays the same","C":"Cost of sales increases by $12,000, reducing gross profit","D":"Gross profit stays the same, while expenses rise by $12,000 and final profit falls by $12,000"},"correctOption":"D","correctAnswer":"Gross profit stays the same, while expenses rise by $12,000 and final profit falls by $12,000","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because advertising is an overhead expense deducted after gross profit; therefore, gross profit is unaffected while final profit decreases by $12,000.","distractor_reasons":{"A":"Incorrect because gross profit only depends on revenue minus cost of sales, neither of which changed.","B":"Incorrect because final profit is calculated after deducting overhead expenses like advertising.","C":"Incorrect because advertising is an overhead expense, not a direct cost of sales.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_065","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_065","question":"A furniture manufacturer wants to increase its profit without raising prices to customers. Which action directly reduces cost of sales while aiming to protect product quality?","options":{"A":"Negotiating bulk-buying discounts with existing reliable timber suppliers","B":"Reducing the marketing budget for social media advertisements","C":"Subletting unused office space to another small business","D":"Switching to cheaper, low-grade wood that splinters easily"},"correctOption":"A","correctAnswer":"Negotiating bulk-buying discounts with existing reliable timber suppliers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because negotiating bulk discounts with existing quality suppliers lowers direct material costs (cost of sales) without compromising product quality.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because reducing marketing lowers overhead expenses rather than cost of sales.","C":"Incorrect because subletting office space reduces overhead rent expense rather than direct cost of sales.","D":"Incorrect because low-grade wood damages product quality and customer satisfaction, risking lower future sales."}}},{"id":"P1_U5_MCQ_066","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_066","question":"A call-centre company keeps its client fees and direct service costs constant, but installs energy-efficient lighting and negotiates a cheaper office lease. How does this increase the company's profit?","options":{"A":"It increases total revenue on the statement of profit or loss","B":"It lowers cost of sales and increases gross profit","C":"It reduces overhead expenses, leaving a larger profit after deducting expenses from gross profit","D":"It increases the company's non-current liabilities"},"correctOption":"C","correctAnswer":"It reduces overhead expenses, leaving a larger profit after deducting expenses from gross profit","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because electricity and office rent are overhead expenses; reducing them increases final profit even when gross profit stays constant.","distractor_reasons":{"A":"Incorrect because client fees and sales volume did not change.","B":"Incorrect because office rent and lighting are indirect expenses rather than direct cost of sales.","C":"Correct selection.","D":"Incorrect because lowering rent and utility bills reduces expenses rather than increasing long-term debt."}}},{"id":"P1_U5_MCQ_067","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_067","question":"A budget airline raises its ticket prices by 25% in an effort to boost profit, only to find that its annual profit actually falls sharply. What is the most likely reason this price increase failed to raise profit?","options":{"A":"Higher ticket prices automatically increased the cost of aviation fuel","B":"Customers switched to rival airlines, causing passenger numbers and total revenue to fall","C":"Raising prices is illegal under consumer protection laws","D":"Higher prices increased the airline's current liabilities"},"correctOption":"B","correctAnswer":"Customers switched to rival airlines, causing passenger numbers and total revenue to fall","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because in a competitive market, a large price rise can cause customers to switch to rivals, reducing sales volume and total revenue by more than the price gain.","distractor_reasons":{"A":"Incorrect because ticket prices do not determine the market price of aviation fuel.","B":"Correct selection.","C":"Incorrect because private sector airlines are free to set their own ticket prices.","D":"Incorrect because changing ticket prices does not create short-term debts."}}},{"id":"P1_U5_MCQ_068","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_068","question":"A cinema chain lowers ticket prices by 15% on quiet weekday afternoons, and its total profit increases. Under what condition does lowering selling prices successfully increase profit?","options":{"A":"When the number of tickets sold stays completely unchanged","B":"When fixed costs rise faster than ticket sales","C":"When cost of sales per ticket increases by 20%","D":"When the percentage increase in ticket sales volume more than offsets the lower price per ticket while costs remain controlled"},"correctOption":"D","correctAnswer":"When the percentage increase in ticket sales volume more than offsets the lower price per ticket while costs remain controlled","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because if demand responds strongly to a price cut, the rise in sales volume increases total revenue and gross profit above any extra variable costs.","distractor_reasons":{"A":"Incorrect because if ticket volume stays unchanged, a 15% price cut reduces revenue and lowers profit.","B":"Incorrect because rising fixed costs reduce profit rather than increasing it.","C":"Incorrect because higher unit costs alongside lower prices would squeeze profit margins.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_069","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_069","question":"A sports retailer compares two product lines: Running Shoes generate $150,000 in revenue with $110,000 in cost of sales, while Tennis Rackets generate $120,000 in revenue with $65,000 in cost of sales. Which decision is best supported by this statement of profit or loss data?","options":{"A":"Focus more promotion on Tennis Rackets because they generate $55,000 in gross profit compared to $40,000 for Running Shoes","B":"Discontinue Tennis Rackets immediately because their revenue is $30,000 lower","C":"Focus exclusively on Running Shoes because higher revenue always means higher profit","D":"Stop tracking cost of sales because only total revenue matters"},"correctOption":"A","correctAnswer":"Focus more promotion on Tennis Rackets because they generate $55,000 in gross profit compared to $40,000 for Running Shoes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Tennis Rackets earn a higher gross profit ($120,000 - $65,000 = $55,000) than Running Shoes ($150,000 - $110,000 = $40,000) despite lower revenue.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because discontinuing the product with higher gross profit would reduce total business profit.","C":"Incorrect because high revenue does not guarantee high profit when cost of sales is disproportionately high.","D":"Incorrect because ignoring cost of sales hides which products actually contribute most to profit."}}},{"id":"P1_U5_MCQ_070","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_070","question":"Comparing its statement of profit or loss with last year, a clothing brand sees that revenue rose by 12% and gross profit also rose by 12%, yet final profit fell by 10%. What is the most likely explanation for this result?","options":{"A":"The cost of raw cotton and fabric increased sharply","B":"The brand sold fewer items than in the previous year","C":"Overhead expenses such as store rents and head-office salaries increased significantly","D":"The brand reduced its selling prices by 12%"},"correctOption":"C","correctAnswer":"Overhead expenses such as store rents and head-office salaries increased significantly","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because gross profit grew in line with revenue (12%), meaning the drop in final profit must have been caused by a sharp rise in overhead expenses deducted below gross profit.","distractor_reasons":{"A":"Incorrect because higher fabric costs would increase cost of sales and cause gross profit to grow slower than revenue.","B":"Incorrect because revenue increased by 12%, indicating strong sales rather than a decline.","C":"Correct selection.","D":"Incorrect because a 12% price cut with constant unit costs would have reduced gross profit relative to revenue."}}},{"id":"P1_U5_MCQ_071","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_071","question":"An incomplete extract from a toy company's statement of profit or loss shows revenue of $280,000, gross profit of $115,000, and final profit of $42,000. What were the company's total overhead expenses for the year?","options":{"A":"$165,000","B":"$73,000","C":"$238,000","D":"$157,000"},"correctOption":"B","correctAnswer":"$73,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Profit = Gross profit - Expenses, so Expenses = Gross profit - Profit ($115,000 - $42,000 = $73,000).","distractor_reasons":{"A":"Incorrect because $165,000 is the cost of sales ($280,000 revenue - $115,000 gross profit), not overhead expenses.","B":"Correct selection.","C":"Incorrect because $238,000 subtracts final profit from total revenue ($280,000 - $42,000), which combines cost of sales and expenses.","D":"Incorrect because $157,000 adds gross profit and final profit together ($115,000 + $42,000)."}}},{"id":"P1_U5_MCQ_072","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_072","question":"A construction company reports an annual profit of $90,000 on its statement of profit or loss, yet its bank balance is only $4,000 at year-end. Why can the directors NOT immediately pay a $90,000 cash dividend to shareholders?","options":{"A":"Dividends can only be paid out of non-current liabilities","B":"The statement of profit or loss never includes credit sales","C":"Private sector companies are legally banned from paying dividends","D":"Much of the profit is tied up in unpaid trade receivables, inventory, or equipment purchases rather than available cash"},"correctOption":"D","correctAnswer":"Much of the profit is tied up in unpaid trade receivables, inventory, or equipment purchases rather than available cash","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because profit is not the same as cash; a profitable company may have its funds tied up in trade receivables, inventory, or capital expenditure and lack the cash to pay large dividends.","distractor_reasons":{"A":"Incorrect because dividends are distributed from after-tax profit and paid using available cash, not long-term debt.","B":"Incorrect because credit sales are included in revenue when calculating profit, which is precisely why profit can exceed cash.","C":"Incorrect because limited companies regularly pay dividends when both profit and cash are sufficient.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_073","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_073","question":"In July, a packaging company pays $70,000 in cash to buy a new automated box-folding machine that will be used for ten years. How is this $70,000 purchase treated in July's cash flow records compared with the statement of profit or loss?","options":{"A":"It is recorded as a $70,000 cash outflow in July, but is NOT deducted in full as a $70,000 cost of sales in that year's statement of profit or loss","B":"It is recorded as $70,000 of revenue on the statement of profit or loss","C":"It is ignored in both the cash flow forecast and the statement of financial position","D":"It is recorded as a $70,000 cash inflow because the company gained a machine"},"correctOption":"A","correctAnswer":"It is recorded as a $70,000 cash outflow in July, but is NOT deducted in full as a $70,000 cost of sales in that year's statement of profit or loss","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because purchasing a non-current asset creates an immediate $70,000 cash outflow, whereas on the statement of financial position it appears as a non-current asset rather than being expensed all at once as cost of sales.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because buying a machine is capital expenditure, not sales revenue.","C":"Incorrect because the cash payment is a cash outflow and the machine is a non-current asset on the statement of financial position.","D":"Incorrect because cash left the business to pay for the machine, making it a cash outflow."}}},{"id":"P1_U5_MCQ_074","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_074","question":"To boost this year's profit, the manager of a luxury hotel cuts staff training budgets and replaces high-quality toiletries with cheap alternatives. What is the main risk of using these cost-cutting methods to raise profit?","options":{"A":"The hotel's current assets will immediately exceed its non-current assets","B":"Cost of sales will automatically double next month","C":"Service standards and brand image may decline, leading to fewer repeat guests and lower future profit","D":"The hotel will no longer be able to calculate gross profit"},"correctOption":"C","correctAnswer":"Service standards and brand image may decline, leading to fewer repeat guests and lower future profit","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because cutting training and product quality in a luxury business can disappoint guests, damage reputation, and reduce future revenue and profit.","distractor_reasons":{"A":"Incorrect because reducing expenses does not alter the ratio of current to non-current assets in this way.","B":"Incorrect because using cheaper toiletries lowers direct costs in the short term rather than doubling them.","C":"Correct selection.","D":"Incorrect because gross profit can still be calculated normally from revenue and cost of sales."}}},{"id":"P1_U5_MCQ_075","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_075","question":"Every quarter, the senior managers of a retail chain review the statement of profit or loss for each store branch. How does this financial statement assist managers in operational decision-making?","options":{"A":"It shows the exact maturity dates of every bank loan held by the chain","B":"It lists the names and addresses of all trade payables","C":"It proves whether every store has enough cash to pay tomorrow's electricity bill","D":"It highlights underperforming branches where cost of sales or expenses are too high relative to revenue"},"correctOption":"D","correctAnswer":"It highlights underperforming branches where cost of sales or expenses are too high relative to revenue","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because reviewing revenue, gross profit, expenses, and profit across branches helps managers pinpoint high costs or weak sales and take corrective action.","distractor_reasons":{"A":"Incorrect because loan maturity details are related to liabilities on the statement of financial position, not the statement of profit or loss.","B":"Incorrect because supplier details are kept in purchase ledgers, not on the statement of profit or loss.","C":"Incorrect because short-term cash availability is tracked through cash flow records, not the statement of profit or loss.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_076","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_076","question":"At the close of business on 31 December, an accountant prepares a statement of financial position for a manufacturing company. What does this financial statement show?","options":{"A":"The value of the business's assets, liabilities, and equity at that specific point in time","B":"The total revenue and expenses earned by the business over the entire 12-month period","C":"The monthly forecast of cash inflows and outflows for the upcoming year","D":"The break-even level of output required to cover fixed costs"},"correctOption":"A","correctAnswer":"The value of the business's assets, liabilities, and equity at that specific point in time","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the statement of financial position provides a financial 'snapshot' of what a business owns (assets), owes (liabilities), and its equity on a specific date.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because revenue and expenses over a period are shown on the statement of profit or loss.","C":"Incorrect because future monthly cash receipts and payments are shown on a cash flow forecast.","D":"Incorrect because break-even output is determined through break-even analysis, not the statement of financial position."}}},{"id":"P1_U5_MCQ_077","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_077","question":"A food-processing company owns a factory building, automated bottling machinery, delivery trucks, raw fruit inventory, and cash in the bank. Which items are classified as non-current assets on its statement of financial position?","options":{"A":"Raw fruit inventory and cash in the bank","B":"Factory building, raw fruit inventory, and cash in the bank","C":"Factory building, automated bottling machinery, and delivery trucks","D":"Delivery trucks and unpaid supplier invoices"},"correctOption":"C","correctAnswer":"Factory building, automated bottling machinery, and delivery trucks","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because non-current assets are resources owned by the business and used for more than one year to generate output, such as property, machinery, and vehicles.","distractor_reasons":{"A":"Incorrect because inventory and cash are current assets expected to be used or converted within 12 months.","B":"Incorrect because raw fruit inventory and cash are current assets, not non-current assets.","C":"Correct selection.","D":"Incorrect because unpaid supplier invoices are trade payables (current liabilities)."}}},{"id":"P1_U5_MCQ_078","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_078","question":"A wholesale electronics distributor is listing its current assets on its statement of financial position. Which group of items consists entirely of current assets?","options":{"A":"Warehouse property, delivery vans, and machinery","B":"Inventory, trade receivables, and cash","C":"Trade payables, bank overdraft, and 5-year bank loan","D":"Share capital, retained profit, and cash"},"correctOption":"B","correctAnswer":"Inventory, trade receivables, and cash","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because current assets are short-term resources held for less than one year that will soon turn into cash: inventory, trade receivables, and cash.","distractor_reasons":{"A":"Incorrect because warehouse property, vans, and machinery are non-current assets.","B":"Correct selection.","C":"Incorrect because trade payables, overdrafts, and bank loans are liabilities (debts owed by the business).","D":"Incorrect because share capital and retained profit are equity items, not current assets."}}},{"id":"P1_U5_MCQ_079","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_079","question":"A stationery supplier delivers $9,000 of paper to an office firm on 30-day credit, so the office firm has not yet paid for the goods. How is this $9,000 recorded on the stationery supplier's statement of financial position?","options":{"A":"As a current liability under trade payables","B":"As a non-current asset under property and equipment","C":"As a non-current liability under bank loans","D":"As a current asset under trade receivables"},"correctOption":"D","correctAnswer":"As a current asset under trade receivables","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because money owed to the business by customers who bought goods on credit is recorded as trade receivables, which is a current asset.","distractor_reasons":{"A":"Incorrect because trade payables represent money the business owes to its suppliers, whereas here the customer owes the supplier.","B":"Incorrect because amounts owed by credit customers are short-term current assets, not physical non-current assets.","C":"Incorrect because trade receivables are assets owed to the business, not long-term debts.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_080","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_080","question":"A retail clothing chain owes $28,000 to garment suppliers due within 30 days and has an overdrawn bank account of $7,000. Under which heading on the statement of financial position are both of these amounts recorded?","options":{"A":"Current liabilities","B":"Non-current liabilities","C":"Current assets","D":"Shareholders' equity"},"correctOption":"A","correctAnswer":"Current liabilities","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because trade payables and bank overdrafts are short-term debts that must be repaid within 12 months, classifying them as current liabilities.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because non-current liabilities are long-term debts due after more than one year, such as multi-year bank loans.","C":"Incorrect because debts owed to suppliers and banks are liabilities, not assets owned by the business.","D":"Incorrect because equity represents the owners' stake in the business, not short-term debts."}}},{"id":"P1_U5_MCQ_081","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_081","question":"A hotel group takes out a $450,000 mortgage loan from a commercial bank to be repaid over 12 years. Where does this $450,000 appear on the hotel group's statement of financial position?","options":{"A":"Current liabilities","B":"Non-current assets","C":"Non-current liabilities","D":"Working capital"},"correctOption":"C","correctAnswer":"Non-current liabilities","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a 12-year bank loan is a long-term debt repayable over more than one year, making it a non-current liability.","distractor_reasons":{"A":"Incorrect because current liabilities only include debts due within one year.","B":"Incorrect because the hotel building purchased is a non-current asset, whereas the loan owed to the bank is a non-current liability.","C":"Correct selection.","D":"Incorrect because working capital is current assets minus current liabilities and excludes long-term loans."}}},{"id":"P1_U5_MCQ_082","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_082","question":"A hardware store's statement of financial position shows inventory of $22,000, trade receivables of $15,000, cash of $8,000, trade payables of $21,000, and a bank overdraft of $6,000. What is the store's working capital?","options":{"A":"$24,000","B":"$18,000","C":"$72,000","D":"$37,000"},"correctOption":"B","correctAnswer":"$18,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because total current assets are $45,000 ($22,000 + $15,000 + $8,000) and total current liabilities are $27,000 ($21,000 + $6,000), giving working capital of $18,000 ($45,000 - $27,000).","distractor_reasons":{"A":"Incorrect because $24,000 omits the $6,000 bank overdraft from current liabilities ($45,000 - $21,000).","B":"Correct selection.","C":"Incorrect because $72,000 adds current assets and current liabilities together ($45,000 + $27,000).","D":"Incorrect because $37,000 omits the $8,000 cash balance from current assets before deducting liabilities."}}},{"id":"P1_U5_MCQ_083","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_083","question":"A printing company owns premises valued at $310,000, printing presses valued at $95,000, inventory worth $28,000, trade receivables of $19,000, and cash of $8,000. What is the value of the company's total assets?","options":{"A":"$405,000","B":"$55,000","C":"$350,000","D":"$460,000"},"correctOption":"D","correctAnswer":"$460,000","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because total assets equal non-current assets ($310,000 + $95,000 = $405,000) plus current assets ($28,000 + $19,000 + $8,000 = $55,000), totalling $460,000.","distractor_reasons":{"A":"Incorrect because $405,000 includes only non-current assets and omits current assets.","B":"Incorrect because $55,000 includes only current assets and omits non-current assets.","C":"Incorrect because $350,000 subtracts current assets from non-current assets instead of adding them.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_084","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_084","question":"A manufacturing business has a long-term bank loan of $165,000, trade payables of $38,000, a bank overdraft of $12,000, and share capital of $200,000. What are the business's total liabilities?","options":{"A":"$215,000","B":"$50,000","C":"$415,000","D":"$165,000"},"correctOption":"A","correctAnswer":"$215,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because total liabilities equal non-current liabilities ($165,000) plus current liabilities ($38,000 + $12,000 = $50,000), giving $215,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $50,000 includes only current liabilities and omits the $165,000 non-current bank loan.","C":"Incorrect because $415,000 wrongly includes $200,000 of share capital (equity) as a liability.","D":"Incorrect because $165,000 includes only non-current liabilities and omits current liabilities."}}},{"id":"P1_U5_MCQ_085","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_085","question":"When calculating Return on Capital Employed (ROCE), an analyst checks the statement of financial position to determine the business's 'capital employed'. What does capital employed represent?","options":{"A":"Only the cash held in the business's current bank account","B":"Total current assets plus total current liabilities","C":"The total long-term finance invested in the business, equal to shareholders' equity plus non-current liabilities","D":"Total revenue minus cost of sales for the financial year"},"correctOption":"C","correctAnswer":"The total long-term finance invested in the business, equal to shareholders' equity plus non-current liabilities","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital employed is the total amount of capital invested in a business for generating profits, calculated as total equity plus non-current liabilities (or total assets minus current liabilities).","distractor_reasons":{"A":"Incorrect because cash is only one small component of current assets, not total capital invested.","B":"Incorrect because working capital is current assets minus current liabilities, whereas capital employed measures long-term invested capital.","C":"Correct selection.","D":"Incorrect because revenue minus cost of sales is gross profit on the statement of profit or loss."}}},{"id":"P1_U5_MCQ_086","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_086","question":"A private limited company's statement of financial position reports share capital of $180,000, retained profit of $75,000, a 10-year bank loan of $120,000, and trade payables of $30,000. What is the company's capital employed?","options":{"A":"$255,000","B":"$375,000","C":"$405,000","D":"$300,000"},"correctOption":"B","correctAnswer":"$375,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because capital employed equals shareholders' equity ($180,000 share capital + $75,000 retained profit = $255,000) plus non-current liabilities ($120,000 bank loan) = $375,000.","distractor_reasons":{"A":"Incorrect because $255,000 is total shareholders' equity and omits the $120,000 non-current bank loan.","B":"Correct selection.","C":"Incorrect because $405,000 wrongly includes $30,000 of short-term trade payables (current liabilities).","D":"Incorrect because $300,000 omits the $75,000 retained profit from shareholders' equity."}}},{"id":"P1_U5_MCQ_087","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_087","question":"On a company's statement of financial position, total assets equal $540,000 and total liabilities equal $210,000. Why must total shareholders' equity equal $330,000?","options":{"A":"Because shareholders' equity is always equal to current liabilities plus cash","B":"Because non-current assets must always equal non-current liabilities","C":"Because gross profit is added directly to total assets every month","D":"Because net assets (total assets minus total liabilities) are funded by and equal to total equity"},"correctOption":"D","correctAnswer":"Because net assets (total assets minus total liabilities) are funded by and equal to total equity","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the statement of financial position always balances: Net assets (Total assets - Total liabilities = $330,000) equal Total equity ($330,000).","distractor_reasons":{"A":"Incorrect because equity consists of share capital and retained profit, not current liabilities plus cash.","B":"Incorrect because non-current assets rarely equal non-current liabilities.","C":"Incorrect because the statement balances due to accounting identity (Assets - Liabilities = Equity), not monthly gross profit additions.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_088","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_088","question":"A supermarket buys $15,000 of canned food from a wholesaler on 30-day trade credit. How does this transaction immediately affect the supermarket's statement of financial position?","options":{"A":"Current assets (inventory) increase by $15,000 and current liabilities (trade payables) increase by $15,000","B":"Non-current assets increase by $15,000 and equity increases by $15,000","C":"Current assets decrease by $15,000 and working capital falls by $15,000","D":"Non-current liabilities increase by $15,000 and cash increases by $15,000"},"correctOption":"A","correctAnswer":"Current assets (inventory) increase by $15,000 and current liabilities (trade payables) increase by $15,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because receiving inventory adds $15,000 to current assets while owing the supplier adds $15,000 to current liabilities (trade payables), keeping the statement balanced.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because inventory held for resale is a current asset, and buying goods on credit does not increase equity.","C":"Incorrect because inventory increases current assets, and working capital remains unchanged since both current assets and current liabilities rise by $15,000.","D":"Incorrect because 30-day trade credit is a current liability and no cash was received."}}},{"id":"P1_U5_MCQ_089","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_089","question":"A furniture retailer uses $10,000 from its bank current account to pay off overdue trade payables. What is the immediate effect of this payment on the retailer's working capital?","options":{"A":"Working capital increases by $10,000","B":"Working capital decreases by $10,000","C":"Working capital remains unchanged because current assets and current liabilities both fall by $10,000","D":"Working capital doubles because trade payables are eliminated"},"correctOption":"C","correctAnswer":"Working capital remains unchanged because current assets and current liabilities both fall by $10,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because cash (a current asset) decreases by $10,000 and trade payables (a current liability) also decrease by $10,000, leaving working capital (Current assets - Current liabilities) unchanged.","distractor_reasons":{"A":"Incorrect because paying a supplier reduces cash by the same amount that liabilities fall.","B":"Incorrect because although cash falls by $10,000, current liabilities also drop by $10,000.","C":"Correct selection.","D":"Incorrect because reducing both current assets and current liabilities equally leaves their difference constant."}}},{"id":"P1_U5_MCQ_090","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_090","question":"A delivery business purchases a new van for $35,000 financed entirely by a 5-year bank loan. Which two items on the statement of financial position increase by $35,000?","options":{"A":"Current assets and current liabilities","B":"Non-current assets and non-current liabilities","C":"Non-current assets and shareholders' equity","D":"Current assets and retained profit"},"correctOption":"B","correctAnswer":"Non-current assets and non-current liabilities","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the delivery van is a non-current asset (+$35,000) and the 5-year bank loan is a non-current liability (+$35,000).","distractor_reasons":{"A":"Incorrect because both the van and the 5-year loan are long-term items (over one year), not current items.","B":"Correct selection.","C":"Incorrect because financing an asset with a bank loan creates a liability rather than increasing owners' equity.","D":"Incorrect because the van is a non-current asset and borrowing a loan does not generate retained profit."}}},{"id":"P1_U5_MCQ_091","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_091","question":"A manufacturing firm uses $50,000 of its cash reserves to buy a new CNC cutting machine outright. How does this purchase affect the firm's working capital?","options":{"A":"Working capital increases by $50,000","B":"Working capital is unaffected because both items are non-current assets","C":"Working capital increases because current liabilities fall by $50,000","D":"Working capital decreases by $50,000 because cash (a current asset) falls while current liabilities stay the same"},"correctOption":"D","correctAnswer":"Working capital decreases by $50,000 because cash (a current asset) falls while current liabilities stay the same","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because cash (a current asset) decreases by $50,000 to buy a non-current asset, reducing Current assets - Current liabilities (working capital) by $50,000.","distractor_reasons":{"A":"Incorrect because cash leaves current assets to become a non-current asset, lowering working capital.","B":"Incorrect because cash is a current asset, whereas the machine is a non-current asset.","C":"Incorrect because paying cash outright does not reduce existing current liabilities.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_092","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_092","question":"A restaurant's statement of financial position shows current assets of $18,000 and current liabilities of $34,000, giving negative working capital of -$16,000. What major risk does this indicate for the restaurant?","options":{"A":"It faces a high risk of being unable to pay short-term debts such as suppliers and overdrafts as they fall due","B":"It has too much idle cash sitting unproductive in its bank account","C":"Its non-current assets are worth less than zero","D":"It is guaranteed to have the highest gross profit margin in the industry"},"correctOption":"A","correctAnswer":"It faces a high risk of being unable to pay short-term debts such as suppliers and overdrafts as they fall due","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because negative working capital means short-term debts due within 12 months exceed short-term assets, signalling a serious liquidity risk.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because negative working capital indicates a shortage of liquid assets, not an excess of idle cash.","C":"Incorrect because working capital only compares current assets and current liabilities, not non-current assets.","D":"Incorrect because liquidity on the statement of financial position does not measure gross profit margin."}}},{"id":"P1_U5_MCQ_093","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_093","question":"A fashion retailer's total current assets increased from $60,000 to $95,000 over the past year, but $80,000 of this total consists of unsold seasonal clothing inventory while cash is only $2,000. Why might the retailer still struggle to pay urgent bills?","options":{"A":"Inventory is classified as a non-current liability","B":"Trade payables cannot legally be paid using cash from inventory sales","C":"Inventory is the least liquid current asset and may take time or heavy discounting to turn into cash","D":"Current assets are never used to pay current liabilities"},"correctOption":"C","correctAnswer":"Inventory is the least liquid current asset and may take time or heavy discounting to turn into cash","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because inventory must first be sold and converted into cash before it can pay bills, and out-of-season fashion inventory may be difficult to sell quickly.","distractor_reasons":{"A":"Incorrect because inventory is a current asset, not a liability.","B":"Incorrect because cash generated from selling inventory is the normal way retailers pay trade payables.","C":"Correct selection.","D":"Incorrect because current assets are the primary source used to settle current liabilities."}}},{"id":"P1_U5_MCQ_094","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_094","question":"Examining two consecutive statements of financial position, a wholesale business notices that its trade receivables rose from $30,000 to $75,000 while annual sales revenue grew by only 5%. What does this change most likely indicate?","options":{"A":"The business has paid off all of its long-term bank loans","B":"Credit customers are taking much longer to pay their invoices, tying up the business's working capital","C":"The business has reduced its inventory to zero","D":"Suppliers are demanding faster cash payments from the business"},"correctOption":"B","correctAnswer":"Credit customers are taking much longer to pay their invoices, tying up the business's working capital","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a 150% jump in trade receivables alongside a 5% rise in sales means customers are delaying payments, reducing cash availability.","distractor_reasons":{"A":"Incorrect because trade receivables reflect unpaid customer invoices, not bank loan repayments.","B":"Correct selection.","C":"Incorrect because rising trade receivables do not imply inventory has fallen to zero.","D":"Incorrect because supplier payment speed affects trade payables, whereas trade receivables track customer payments."}}},{"id":"P1_U5_MCQ_095","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_095","question":"At the end of the financial year, a profitable company retains $65,000 of its profit after paying tax and dividends. How does this retained profit appear on the company's statement of financial position?","options":{"A":"It is deducted from non-current assets","B":"It is added to current liabilities under trade payables","C":"It is recorded as a non-current liability owed to directors","D":"It is added to shareholders' equity, increasing total equity and capital employed"},"correctOption":"D","correctAnswer":"It is added to shareholders' equity, increasing total equity and capital employed","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because retained profit belongs to the owners/shareholders and is added to equity (reserves) on the statement of financial position, increasing capital employed.","distractor_reasons":{"A":"Incorrect because retained profit increases the net worth of the business rather than reducing assets.","B":"Incorrect because retained profit is internal equity, not an external debt owed to suppliers.","C":"Incorrect because retained profit is owned by shareholders, not a loan owed to directors.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_096","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_096","question":"A student comparing a company's annual financial statements asks why the statement of profit or loss covers 'the year ended 31 March', whereas the statement of financial position is headed 'as at 31 March'. What explains this difference?","options":{"A":"The statement of profit or loss measures trading performance over a period of time, while the statement of financial position shows assets, liabilities, and equity at a single date","B":"The statement of financial position is only prepared once every ten years","C":"The statement of profit or loss only records transactions that happen on the final day of the year","D":"The statement of financial position excludes all current assets and current liabilities"},"correctOption":"A","correctAnswer":"The statement of profit or loss measures trading performance over a period of time, while the statement of financial position shows assets, liabilities, and equity at a single date","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because revenue, costs, and profit accumulate over an entire trading period (flow), whereas assets, liabilities, and equity are measured at one specific moment in time (snapshot).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because limited companies prepare a statement of financial position every year.","C":"Incorrect because the statement of profit or loss totals all revenue and costs across the full 12-month period.","D":"Incorrect because current assets and current liabilities are essential sections of the statement of financial position."}}},{"id":"P1_U5_MCQ_097","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_097","question":"Over three years, a logistics company's non-current liabilities increased from $80,000 to $420,000 while its total equity remained at $140,000. Why might a bank hesitate to approve another large loan after reviewing this statement of financial position?","options":{"A":"The company has zero non-current liabilities to show borrowing experience","B":"High existing long-term debt relative to equity increases financial risk and fixed interest commitments","C":"Non-current liabilities are automatically deducted from the company's gross profit","D":"The company's working capital must be equal to its non-current liabilities"},"correctOption":"B","correctAnswer":"High existing long-term debt relative to equity increases financial risk and fixed interest commitments","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a high level of non-current liabilities compared with equity means heavy interest and repayment obligations, increasing the risk of default if sales dip.","distractor_reasons":{"A":"Incorrect because the company already has $420,000 in non-current liabilities.","B":"Correct selection.","C":"Incorrect because loan principal balances sit on the statement of financial position, not as deductions from gross profit.","D":"Incorrect because there is no requirement for working capital to equal non-current liabilities."}}},{"id":"P1_U5_MCQ_098","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_098","question":"A profitable company pays out $30,000 in cash dividends to its shareholders at the end of the year. How does paying these cash dividends affect the company's statement of financial position?","options":{"A":"Non-current assets increase by $30,000 and non-current liabilities decrease by $30,000","B":"Current assets (cash) increase by $30,000 and equity increases by $30,000","C":"Current assets (cash) decrease by $30,000 and equity (retained profit) decreases by $30,000","D":"Current liabilities increase by $30,000 and non-current assets decrease by $30,000"},"correctOption":"C","correctAnswer":"Current assets (cash) decrease by $30,000 and equity (retained profit) decreases by $30,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because paying cash dividends reduces the company's bank cash (current assets) by $30,000 and reduces retained profit within equity by $30,000.","distractor_reasons":{"A":"Incorrect because dividends are paid in cash (current asset) out of equity, not non-current items.","B":"Incorrect because paying dividends sends cash out of the company to shareholders, reducing both cash and retained profit.","C":"Correct selection.","D":"Incorrect because once paid in cash, no liability remains and non-current assets are unaffected."}}},{"id":"P1_U5_MCQ_099","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_099","question":"A manufacturing company's statement of financial position lists its factory machinery at a value of $220,000, but when the directors try to sell the machinery, buyers offer only $140,000. What does this illustrate about interpreting a statement of financial position?","options":{"A":"Asset values recorded in accounts are based on historical/book values and may differ from current market resale values","B":"Machinery should always be listed under current liabilities","C":"The company's accountant made an illegal error by recording the machinery","D":"Non-current assets always sell for more than their recorded value"},"correctOption":"A","correctAnswer":"Asset values recorded in accounts are based on historical/book values and may differ from current market resale values","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because asset values shown on a statement of financial position reflect accounting valuations (historical cost less depreciation) rather than guaranteed market liquidation prices.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because machinery is a non-current asset, not a liability.","C":"Incorrect because recording assets at book value follows standard accounting rules, even if market demand changes.","D":"Incorrect because specialised machinery often loses resale value faster than its accounting book value."}}},{"id":"P1_U5_MCQ_100","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_100","question":"A growing bakery chain applies for a $150,000 bank loan to purchase new ovens. Looking at the bakery's statement of financial position, which feature would most reassure the bank manager that the loan is low-risk?","options":{"A":"The bakery owns $400,000 in unmortgaged freehold property (non-current assets) that can be offered as collateral","B":"The bakery has negative working capital of -$45,000","C":"The bakery already has $600,000 in overdue trade payables","D":"The bakery's current assets consist entirely of perishable bread inventory"},"correctOption":"A","correctAnswer":"The bakery owns $400,000 in unmortgaged freehold property (non-current assets) that can be offered as collateral","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because owning $400,000 of debt-free property provides strong collateral/security that the bank could claim if the bakery defaulted on the loan.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because negative working capital signals severe short-term liquidity risk, alarming lenders.","C":"Incorrect because overdue trade payables show the business is already struggling to pay its creditors.","D":"Incorrect because perishable inventory is illiquid and cannot serve as reliable security for a long-term loan."}}},{"id":"P1_U5_MCQ_101","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_101","question":"A retail business achieves a 22% profit margin for the year, yet it struggles to pay its monthly utility bills and supplier invoices on time. What is the key difference between profitability and liquidity?","options":{"A":"Profitability measures cash in the bank, whereas liquidity measures total sales revenue","B":"Profitability measures profit made relative to sales or capital invested, whereas liquidity measures the ability to pay short-term debts as they fall due","C":"Profitability only applies to sole traders, whereas liquidity only applies to public limited companies","D":"Profitability is calculated from the statement of financial position, whereas liquidity is calculated solely from the statement of profit or loss"},"correctOption":"B","correctAnswer":"Profitability measures profit made relative to sales or capital invested, whereas liquidity measures the ability to pay short-term debts as they fall due","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because profitability evaluates profit performance relative to revenue or capital employed, while liquidity assesses whether current assets can cover immediate short-term liabilities.","distractor_reasons":{"A":"Incorrect because this reverses the two concepts; liquidity relates to cash and short-term assets, while profitability relates to profit.","B":"Correct selection.","C":"Incorrect because both profitability and liquidity are vital for businesses of all legal structures.","D":"Incorrect because profitability uses the statement of profit or loss (and capital employed), while liquidity uses current assets and current liabilities from the statement of financial position."}}},{"id":"P1_U5_MCQ_102","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_102","question":"A furniture retailer reports annual sales revenue of $500,000, cost of sales of $320,000, and final profit of $60,000. What is the retailer's gross profit margin?","options":{"A":"12%","B":"64%","C":"36%","D":"56.25%"},"correctOption":"C","correctAnswer":"36%","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Gross profit = $500,000 - $320,000 = $180,000, and Gross profit margin = ($180,000 / $500,000) × 100 = 36%.","distractor_reasons":{"A":"Incorrect because 12% is the profit margin ($60,000 / $500,000 × 100), not the gross profit margin.","B":"Incorrect because 64% is the ratio of cost of sales to revenue ($320,000 / $500,000 × 100).","C":"Correct selection.","D":"Incorrect because 56.25% divides gross profit by cost of sales ($180,000 / $320,000 × 100) instead of dividing by revenue."}}},{"id":"P1_U5_MCQ_103","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_103","question":"A supermarket's annual revenue increased by 10%, yet its gross profit margin fell from 28% to 22% over the same period. What is the most likely reason for this fall in gross profit margin?","options":{"A":"Supplier prices for goods rose faster than the supermarket's selling prices, or the supermarket cut prices to attract shoppers","B":"The supermarket spent more on head-office administrative salaries","C":"The supermarket took out a larger long-term bank loan","D":"Customers paid their credit accounts faster than last year"},"correctOption":"A","correctAnswer":"Supplier prices for goods rose faster than the supermarket's selling prices, or the supermarket cut prices to attract shoppers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because gross profit margin depends on the gap between selling prices and cost of sales; higher supplier costs or price discounts shrink this percentage margin.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because administrative salaries are overhead expenses deducted after gross profit, so they affect profit margin rather than gross profit margin.","C":"Incorrect because bank loans and interest do not affect gross profit margin.","D":"Incorrect because faster customer payments improve cash flow, not gross profit margin."}}},{"id":"P1_U5_MCQ_104","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_104","question":"A software consultancy generates annual revenue of $600,000, gross profit of $420,000, and final profit of $90,000. What is the consultancy's profit margin?","options":{"A":"70%","B":"21.4%","C":"55%","D":"15%"},"correctOption":"D","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Profit margin = (Profit / Revenue) × 100 = ($90,000 / $600,000) × 100 = 15%.","distractor_reasons":{"A":"Incorrect because 70% is the gross profit margin ($420,000 / $600,000 × 100), not the profit margin.","B":"Incorrect because 21.4% divides profit by gross profit ($90,000 / $420,000 × 100) instead of dividing by revenue.","C":"Incorrect because 55% subtracts profit margin from gross profit margin (70% - 15%).","D":"Correct selection."}}},{"id":"P1_U5_MCQ_105","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_105","question":"Between 2025 and 2026, a cosmetics brand's gross profit margin improved from 50% to 56%, while its profit margin fell from 18% to 13%. What does this divergence reveal about the brand's performance?","options":{"A":"Cost of sales rose sharply while overhead expenses fell","B":"The brand improved its direct product margin, but overhead expenses such as marketing or rent grew much faster than revenue","C":"The brand's liquidity ratios have fallen below 0.5 : 1","D":"Revenue fell by 50% during 2026"},"correctOption":"B","correctAnswer":"The brand improved its direct product margin, but overhead expenses such as marketing or rent grew much faster than revenue","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a higher gross profit margin shows improved control over cost of sales/pricing, whereas a lower profit margin indicates that indirect overhead expenses increased disproportionately.","distractor_reasons":{"A":"Incorrect because if cost of sales rose and expenses fell, gross profit margin would fall rather than rise.","B":"Correct selection.","C":"Incorrect because profitability margins do not measure liquidity ratios.","D":"Incorrect because profit margins measure percentages of revenue and do not imply a 50% drop in sales."}}},{"id":"P1_U5_MCQ_106","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_106","question":"A logistics company earns an annual profit of $120,000 and has capital employed of $800,000 (comprising $550,000 equity and $250,000 non-current liabilities). What is the company's Return on Capital Employed (ROCE)?","options":{"A":"21.8%","B":"48%","C":"15%","D":"12%"},"correctOption":"C","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because ROCE = (Profit / Capital employed) × 100 = ($120,000 / $800,000) × 100 = 15%.","distractor_reasons":{"A":"Incorrect because 21.8% divides profit only by equity ($120,000 / $550,000 × 100), omitting non-current liabilities from capital employed.","B":"Incorrect because 48% divides profit only by non-current liabilities ($120,000 / $250,000 × 100).","C":"Correct selection.","D":"Incorrect because 12% miscalculates the percentage by dividing by $1,000,000."}}},{"id":"P1_U5_MCQ_107","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_107","question":"An investor sees that Company X achieved a Return on Capital Employed (ROCE) of 16% this year, compared with 11% last year, a bank savings interest rate of 4%, and an industry average ROCE of 14%. How should the investor interpret Company X's ROCE?","options":{"A":"Company X is generating a strong and improving return on invested capital that outperforms both bank interest rates and industry rivals","B":"Company X is losing money because 16% is below 50%","C":"Company X has too much cash and should immediately repay all shareholders","D":"Company X's current liabilities exceed its current assets by 16%"},"correctOption":"A","correctAnswer":"Company X is generating a strong and improving return on invested capital that outperforms both bank interest rates and industry rivals","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ROCE measures how efficiently a business uses invested capital to generate profit; 16% improves on last year (11%), exceeds the risk-free bank rate (4%), and beats competitors (14%).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because an ROCE of 16% represents a healthy positive return on capital, not a loss.","C":"Incorrect because a high ROCE indicates effective use of capital rather than excess idle cash.","D":"Incorrect because ROCE is a profitability ratio and does not measure current assets against current liabilities."}}},{"id":"P1_U5_MCQ_108","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_108","question":"A manufacturing company wants to increase its Return on Capital Employed (ROCE) next year. Which action would directly improve the company's ROCE?","options":{"A":"Taking out a large new long-term bank loan to hold as idle cash in the bank","B":"Increasing overhead expenses while keeping revenue and capital employed constant","C":"Issuing $500,000 of new shares without generating any extra profit","D":"Cutting production waste to increase annual profit while keeping capital employed unchanged"},"correctOption":"D","correctAnswer":"Cutting production waste to increase annual profit while keeping capital employed unchanged","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because ROCE = (Profit / Capital employed) × 100; increasing profit (the numerator) without increasing capital employed (the denominator) directly raises ROCE.","distractor_reasons":{"A":"Incorrect because adding a new long-term loan increases capital employed without raising operating profit, lowering ROCE.","B":"Incorrect because higher expenses reduce profit, which lowers ROCE.","C":"Incorrect because raising share capital increases capital employed; if profit does not rise, ROCE falls.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_109","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_109","question":"A wholesale distributor has current assets of $135,000 (including $55,000 of inventory) and current liabilities of $75,000. What is the distributor's current ratio?","options":{"A":"1.07 : 1","B":"1.8 : 1","C":"0.56 : 1","D":"2.53 : 1"},"correctOption":"B","correctAnswer":"1.8 : 1","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Current ratio = Current assets / Current liabilities = $135,000 / $75,000 = 1.8 : 1.","distractor_reasons":{"A":"Incorrect because 1.07 : 1 deducts inventory first (($135,000 - $55,000) / $75,000), which is the acid-test ratio.","B":"Correct selection.","C":"Incorrect because 0.56 : 1 inverts the formula by dividing current liabilities by current assets ($75,000 / $135,000).","D":"Incorrect because 2.53 : 1 adds inventory to current assets instead of recognising it is already included ($190,000 / $75,000)."}}},{"id":"P1_U5_MCQ_110","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_110","question":"Over the past two years, a construction firm's current ratio has fallen from 1.9 : 1 to 0.75 : 1. What does a current ratio of 0.75 : 1 indicate?","options":{"A":"The firm's profit margin has increased to 75%","B":"The firm holds $1.75 of current assets for every $1 of current liabilities","C":"The firm has only $0.75 of current assets for every $1 of current liabilities, indicating a serious liquidity problem","D":"The firm has zero non-current assets on its statement of financial position"},"correctOption":"C","correctAnswer":"The firm has only $0.75 of current assets for every $1 of current liabilities, indicating a serious liquidity problem","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a current ratio below 1 : 1 means current liabilities exceed current assets, so the business may not be able to pay its short-term debts on time.","distractor_reasons":{"A":"Incorrect because the current ratio measures liquidity, not profit margin.","B":"Incorrect because 0.75 : 1 means $0.75 of current assets per $1 of current liabilities, not $1.75.","C":"Correct selection.","D":"Incorrect because the current ratio excludes non-current assets."}}},{"id":"P1_U5_MCQ_111","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_111","question":"A garden furniture retailer has a current ratio of 4.8 : 1, which is far above the typical safe benchmark of 1.5 : 1 to 2 : 1. Why might the retailer's finance manager view a current ratio of 4.8 : 1 as a concern?","options":{"A":"Too much capital is tied up unproductively in excess inventory, uncollected trade receivables, or low-interest cash","B":"The retailer is about to run out of cash to pay its short-term suppliers","C":"A current ratio above 2 : 1 is illegal for retail businesses","D":"It proves the retailer's gross profit margin is negative"},"correctOption":"A","correctAnswer":"Too much capital is tied up unproductively in excess inventory, uncollected trade receivables, or low-interest cash","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an excessively high current ratio suggests inefficient working capital management, with funds sitting idle in unsold inventory, overdue receivables, or low-return cash instead of being invested profitably.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a ratio of 4.8 : 1 indicates abundant current assets relative to short-term debts, not a liquidity shortage.","C":"Incorrect because there is no legal upper limit on a company's current ratio.","D":"Incorrect because the current ratio does not measure gross profit margin."}}},{"id":"P1_U5_MCQ_112","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_112","question":"A clothing wholesaler's statement of financial position shows current assets of $110,000, inventory of $50,000, and current liabilities of $40,000. What is the wholesaler's acid-test ratio?","options":{"A":"2.75 : 1","B":"1.25 : 1","C":"0.67 : 1","D":"1.5 : 1"},"correctOption":"D","correctAnswer":"1.5 : 1","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Acid-test ratio = (Current assets - Inventory) / Current liabilities = ($110,000 - $50,000) / $40,000 = $60,000 / $40,000 = 1.5 : 1.","distractor_reasons":{"A":"Incorrect because 2.75 : 1 is the current ratio ($110,000 / $40,000), which fails to subtract inventory.","B":"Incorrect because 1.25 : 1 divides inventory by current liabilities ($50,000 / $40,000).","C":"Incorrect because 0.67 : 1 inverts the acid-test formula ($40,000 / $60,000).","D":"Correct selection."}}},{"id":"P1_U5_MCQ_113","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_113","question":"When assessing whether a car dealership can pay its urgent short-term bills, a bank manager calculates the acid-test ratio in addition to the current ratio. Why is inventory subtracted from current assets in the acid-test ratio?","options":{"A":"Because inventory is a non-current liability","B":"Because inventory is the least liquid current asset and cannot always be turned into cash quickly at full value","C":"Because businesses are legally forbidden from selling inventory to pay debts","D":"Because inventory is already included inside cash and trade receivables"},"correctOption":"B","correctAnswer":"Because inventory is the least liquid current asset and cannot always be turned into cash quickly at full value","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because inventory must be sold first before generating cash and may take months to sell (especially high-value items like cars), so excluding it tests immediate liquidity.","distractor_reasons":{"A":"Incorrect because inventory is a current asset, not a liability.","B":"Correct selection.","C":"Incorrect because selling inventory is the primary way trading businesses generate cash.","D":"Incorrect because inventory is a separate current asset line item, not part of cash or trade receivables."}}},{"id":"P1_U5_MCQ_114","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_114","question":"A toy manufacturer has a current ratio of 2.4 : 1, which looks healthy, but its acid-test ratio is only 0.55 : 1. What does the large gap between these two liquidity ratios reveal?","options":{"A":"The manufacturer has no current liabilities","B":"The manufacturer's profit margin is 55%","C":"A very high proportion of the manufacturer's current assets is tied up in unsold inventory","D":"The manufacturer has too much cash sitting in its bank account"},"correctOption":"C","correctAnswer":"A very high proportion of the manufacturer's current assets is tied up in unsold inventory","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the only difference between the current ratio and the acid-test ratio is inventory; a sharp drop when inventory is removed shows the business is holding excessive inventory.","distractor_reasons":{"A":"Incorrect because if current liabilities were zero, neither ratio could be calculated as finite numbers.","B":"Incorrect because liquidity ratios do not measure profit margins.","C":"Correct selection.","D":"Incorrect because high cash balances would keep the acid-test ratio high alongside the current ratio."}}},{"id":"P1_U5_MCQ_115","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_115","question":"A retail company's current ratio has dropped to 0.9 : 1 and its acid-test ratio is 0.5 : 1, causing concern among suppliers. Which action would improve both liquidity ratios?","options":{"A":"Selling unwanted non-current assets for cash or replacing a short-term overdraft with a long-term bank loan","B":"Using existing bank cash to buy a new delivery van","C":"Paying out all available cash as dividends to shareholders","D":"Buying more inventory on 30-day trade credit"},"correctOption":"A","correctAnswer":"Selling unwanted non-current assets for cash or replacing a short-term overdraft with a long-term bank loan","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because selling unwanted non-current assets increases cash (current assets) while converting an overdraft into a long-term loan reduces current liabilities, raising both liquidity ratios.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because spending cash on a non-current asset reduces current assets and lowers both liquidity ratios.","C":"Incorrect because paying cash dividends reduces current assets and worsens liquidity ratios.","D":"Incorrect because buying inventory on credit increases both current assets (inventory) and current liabilities, lowering the acid-test ratio."}}},{"id":"P1_U5_MCQ_116","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_116","question":"Internal and external stakeholders analyse a company's published financial statements for different reasons. How do internal managers primarily use ratio analysis?","options":{"A":"To calculate how much corporation tax the government should collect from rival firms","B":"To decide whether to supply raw materials on trade credit to their own company","C":"To determine whether to approve a personal mortgage for a customer","D":"To monitor business performance against targets, control costs, and make pricing or investment decisions"},"correctOption":"D","correctAnswer":"To monitor business performance against targets, control costs, and make pricing or investment decisions","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because managers are internal users who analyse profitability and liquidity ratios to evaluate efficiency, spot rising costs, and guide strategic decisions.","distractor_reasons":{"A":"Incorrect because tax assessment is carried out by external government tax authorities.","B":"Incorrect because trade credit decisions are made by external suppliers.","C":"Incorrect because personal mortgages are assessed by external banks.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_117","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_117","question":"Before attending the Annual General Meeting (AGM) of a public limited company, a shareholder examines the company's profit margin, ROCE, and dividend per share compared with previous years. Why is this financial information important to shareholders?","options":{"A":"It allows shareholders to set the daily work rotas for factory employees","B":"It helps shareholders judge the return on their investment, decide whether to buy or sell shares, and assess directors' performance","C":"It determines whether the shareholder has unlimited liability for company debts","D":"It shows shareholders the exact credit score of every individual customer"},"correctOption":"B","correctAnswer":"It helps shareholders judge the return on their investment, decide whether to buy or sell shares, and assess directors' performance","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because shareholders own the company and use profitability ratios and profit trends to evaluate management effectiveness and decide whether to retain or sell their shares.","distractor_reasons":{"A":"Incorrect because operational work rotas are handled by managers and supervisors, not shareholders.","B":"Correct selection.","C":"Incorrect because shareholders in a limited company always have limited liability regardless of financial ratios.","D":"Incorrect because individual customer credit details are not published in company accounts."}}},{"id":"P1_U5_MCQ_118","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_118","question":"Trade union representatives representing factory workers study the employer's latest statement of profit or loss and liquidity ratios ahead of annual pay talks. How are employees and unions likely to use this financial data?","options":{"A":"To decide whether to grant the company a 10-year bank loan","B":"To calculate the company's import tariff obligations","C":"To assess job security and argue for higher wages if profits and profitability margins have risen","D":"To value the company's shares for a hostile takeover"},"correctOption":"C","correctAnswer":"To assess job security and argue for higher wages if profits and profitability margins have risen","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because employees are internal stakeholders who check profitability and liquidity to gauge whether their jobs are safe and whether the business can afford wage increases.","distractor_reasons":{"A":"Incorrect because bank loans are granted by external lenders/banks, not employees.","B":"Incorrect because import tariffs are customs taxes administered by government authorities.","C":"Correct selection.","D":"Incorrect because hostile takeovers are conducted by rival companies or external investors."}}},{"id":"P1_U5_MCQ_119","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_119","question":"A packaging company applies to a commercial bank for a $250,000 loan to buy new machinery. Why will the bank manager carefully analyse the company's liquidity ratios and existing non-current liabilities before approving the loan?","options":{"A":"To ensure the company has enough cash flow and liquid assets to pay interest and repay the loan on time without defaulting","B":"To check whether the company's employees are members of a trade union","C":"To decide what retail price the packaging company should charge its customers","D":"To calculate how many shares the bank will receive as dividends"},"correctOption":"A","correctAnswer":"To ensure the company has enough cash flow and liquid assets to pay interest and repay the loan on time without defaulting","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because banks are external lenders whose primary objective is ensuring the borrower can meet regular interest payments and repay the loan principal.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because trade union membership is not reported in financial ratios or used to assess loan repayment capacity.","C":"Incorrect because pricing decisions are made by the company's own marketing and finance managers.","D":"Incorrect because banks earn interest on loans rather than receiving shareholder dividends."}}},{"id":"P1_U5_MCQ_120","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_120","question":"A new retail chain asks a fabric manufacturer to supply $40,000 of goods on 60-day trade credit. Which ratios from the retail chain's accounts will the fabric manufacturer examine most closely before agreeing to offer trade credit?","options":{"A":"Gross profit margin and return on capital employed only","B":"Labour productivity and margin of safety","C":"Market share and break-even output","D":"Current ratio and acid-test ratio to verify whether the retailer can pay its short-term debts on time"},"correctOption":"D","correctAnswer":"Current ratio and acid-test ratio to verify whether the retailer can pay its short-term debts on time","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because suppliers are external stakeholders who need reassurance that a credit customer has sufficient short-term liquidity to pay invoices when they fall due.","distractor_reasons":{"A":"Incorrect because a profitable company can still run out of cash; suppliers prioritise liquidity ratios to ensure prompt payment.","B":"Incorrect because labour productivity and margin of safety are internal operational metrics not published in financial statements.","C":"Incorrect because market share and break-even output do not tell a supplier whether cash is available to pay invoices in 60 days.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_121","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_121","question":"Every year, incorporated businesses must submit their audited financial statements to government authorities. How does the government use this financial information?","options":{"A":"To set the business's internal marketing strategy and advertising budget","B":"To calculate the amount of corporation tax owed and monitor the health of key industries","C":"To decide which suppliers the business must buy raw materials from","D":"To vote for new directors at the company's Annual General Meeting"},"correctOption":"B","correctAnswer":"To calculate the amount of corporation tax owed and monitor the health of key industries","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because government tax authorities use reported profits to assess tax liabilities, while economic departments track business growth and employment trends.","distractor_reasons":{"A":"Incorrect because private sector businesses decide their own marketing strategies.","B":"Correct selection.","C":"Incorrect because supplier selection is an operational business decision, not a government function.","D":"Incorrect because only shareholders vote at an AGM unless the business is state-owned."}}},{"id":"P1_U5_MCQ_122","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_122","question":"An investor buys shares in an airline solely because its published accounts show a high ROCE and profit margin for the previous year, only for the airline to suffer heavy losses three months later due to a sudden fuel crisis. Which limitation of ratio analysis does this highlight?","options":{"A":"Ratios can only be calculated by government accountants","B":"Financial accounts deliberately exclude all expenses to make companies look profitable","C":"Accounts and ratios are based on historical data from the past and cannot predict sudden future market or economic changes","D":"Profitability ratios are always identical across every year"},"correctOption":"C","correctAnswer":"Accounts and ratios are based on historical data from the past and cannot predict sudden future market or economic changes","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because published financial statements report past trading performance, which is not a guarantee of future results when external conditions change.","distractor_reasons":{"A":"Incorrect because any student, investor, or manager can calculate ratios from published accounts.","B":"Incorrect because audited accounts must legally include all expenses.","C":"Correct selection.","D":"Incorrect because ratios fluctuate every year as revenue, costs, and assets change."}}},{"id":"P1_U5_MCQ_123","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_123","question":"A student compares the current ratio of a high-street supermarket (0.85 : 1) with that of a luxury yacht builder (2.6 : 1) and concludes that the supermarket is badly managed. Why is this comparison misleading?","options":{"A":"Businesses in different industries have very different operating cycles, inventory speeds, and working capital structures","B":"Supermarkets are not permitted to calculate liquidity ratios","C":"Yacht builders do not have any current liabilities","D":"Liquidity ratios can only be compared across companies in different countries"},"correctOption":"A","correctAnswer":"Businesses in different industries have very different operating cycles, inventory speeds, and working capital structures","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ratio comparisons are only meaningful between businesses in the same industry; supermarkets turn inventory into cash daily and safely operate with lower current ratios than yacht builders.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because supermarkets regularly calculate and monitor liquidity ratios.","C":"Incorrect because yacht builders have substantial trade payables and customer deposits as current liabilities.","D":"Incorrect because ratios should be compared with competitors in the same industry or with the business's own past performance."}}},{"id":"P1_U5_MCQ_124","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_124","question":"A manufacturing company's profit margin and ROCE improved slightly this year, yet its most experienced engineers are resigning due to poor working conditions and customers are complaining about declining product quality. What limitation of using accounts and ratio analysis does this demonstrate?","options":{"A":"Ratios only measure short-term cash inflows and outflows","B":"Companies are allowed to invent fake revenue figures on their statement of profit or loss","C":"Ratio analysis automatically calculates employee absenteeism rates","D":"Financial ratios ignore qualitative non-financial factors such as staff morale, product quality, and brand reputation that affect future success"},"correctOption":"D","correctAnswer":"Financial ratios ignore qualitative non-financial factors such as staff morale, product quality, and brand reputation that affect future success","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because financial accounts only capture numerical data and omit vital non-financial factors like workforce motivation, customer satisfaction, and environmental impact.","distractor_reasons":{"A":"Incorrect because profitability ratios measure profit relative to revenue or capital, not cash flows.","B":"Incorrect because falsifying revenue is illegal fraud, not a standard limitation of ratio analysis.","C":"Incorrect because absenteeism is an HR metric, not a financial ratio.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_125","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_125","question":"An analyst compares the ROCE of two rival engineering firms, Firm A and Firm B, and finds that Firm A values its factory land at its original purchase price from 20 years ago whereas Firm B revalued its land to current market prices this year. Why does this complicate ratio comparison between the two firms?","options":{"A":"Land is recorded as a current liability on both statements of financial position","B":"Different accounting valuation methods and inflation distort asset values and capital employed, making direct ratio comparisons less reliable","C":"ROCE is calculated using gross profit for Firm A and revenue for Firm B","D":"Revaluing land increases Firm B's cost of sales on the statement of profit or loss"},"correctOption":"B","correctAnswer":"Different accounting valuation methods and inflation distort asset values and capital employed, making direct ratio comparisons less reliable","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because differences in accounting policies (such as asset valuation) and inflation over time can artificially inflate or deflate capital employed, distorting ROCE comparisons.","distractor_reasons":{"A":"Incorrect because land is a non-current asset, not a liability.","B":"Correct selection.","C":"Incorrect because the standard ROCE formula uses profit divided by capital employed for all businesses.","D":"Incorrect because revaluing land changes non-current assets and equity on the statement of financial position, not cost of sales."}}},{"id":"P1_U5_MCQ_126","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_126","question":"An entrepreneur is setting up a new hairdressing salon and needs $25,000 to pay a premises lease deposit, install styling chairs, and buy hairdryers before opening to customers. Which type of finance need does this describe?","options":{"A":"Start-up capital","B":"Working capital","C":"Export credit","D":"Debt factoring"},"correctOption":"A","correctAnswer":"Start-up capital","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because start-up capital is the finance needed by an entrepreneur to pay for essential non-current assets and initial set-up costs before a new business begins trading.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because working capital funds recurring day-to-day running costs such as weekly wages and electricity bills once trading begins.","C":"Incorrect because export credit finances international trade transactions rather than launching a local salon.","D":"Incorrect because debt factoring involves selling unpaid customer invoices to raise immediate cash."}}},{"id":"P1_U5_MCQ_127","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_127","question":"A toy retailer needs $18,000 in October to purchase extra inventory and pay temporary shop assistants ahead of the December holiday rush. Which financial need is the retailer funding?","options":{"A":"Purchase of freehold land","B":"Takeover of a rival chain","C":"Working capital for seasonal trading","D":"Start-up capital for a new company"},"correctOption":"C","correctAnswer":"Working capital for seasonal trading","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because funding temporary inventory increases and short-term staff wages is a classic working capital requirement.","distractor_reasons":{"A":"Incorrect because freehold land is a long-term non-current asset rather than seasonal inventory and wages.","B":"Incorrect because acquiring another business is long-term external expansion.","C":"Correct selection.","D":"Incorrect because the toy retailer is an existing business preparing for peak seasonal demand, not a start-up."}}},{"id":"P1_U5_MCQ_128","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_128","question":"A profitable cloud-software company plans to acquire a smaller cybersecurity firm and open sales offices in three new countries. Which reason for needing finance applies to this situation?","options":{"A":"Covering daily petty cash expenses","B":"Financing long-term business expansion","C":"Replacing broken office printers","D":"Paying last month's utility bill"},"correctOption":"B","correctAnswer":"Financing long-term business expansion","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because acquiring other businesses and entering overseas markets require substantial long-term finance for expansion.","distractor_reasons":{"A":"Incorrect because petty cash covers minor routine expenses, not corporate acquisitions.","B":"Correct selection.","C":"Incorrect because replacing printers is minor routine asset replacement rather than international growth.","D":"Incorrect because utility bills are short-term working capital expenses."}}},{"id":"P1_U5_MCQ_129","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_129","question":"A commercial arable farm has used its combine harvester for twelve years, and frequent breakdowns are delaying grain harvests. What business need is driving the farm's request for $140,000 in finance?","options":{"A":"Funding short-term working capital","B":"Paying annual shareholder dividends","C":"Launching a new start-up business","D":"Replacing worn-out non-current assets"},"correctOption":"D","correctAnswer":"Replacing worn-out non-current assets","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because established businesses frequently require long-term finance to replace ageing or obsolete machinery and vehicles.","distractor_reasons":{"A":"Incorrect because a combine harvester is a long-term non-current asset, not a short-term working capital item.","B":"Incorrect because dividends are paid out of after-tax profits rather than borrowed to replace machinery.","C":"Incorrect because the farm has already been operating for at least twelve years.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_130","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_130","question":"A brand-new start-up café wants to buy an additional delivery scooter after two months of trading, but the owner cannot use retained profit to pay for it. Why is retained profit unavailable to this business?","options":{"A":"Retained profit can only be used by public limited companies","B":"A brand-new business has not traded long enough to accumulate past profits","C":"Retained profit is legally restricted to paying bank interest","D":"Sole traders are not allowed to retain profits in their business"},"correctOption":"B","correctAnswer":"A brand-new business has not traded long enough to accumulate past profits","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because retained profit comes from past trading surpluses kept in the business, which newly formed start-ups do not yet possess.","distractor_reasons":{"A":"Incorrect because businesses of any legal structure can retain profits once they become profitable.","B":"Correct selection.","C":"Incorrect because retained profit can be used for any legitimate business investment, including equipment.","D":"Incorrect because sole traders regularly reinvest their profits back into their businesses."}}},{"id":"P1_U5_MCQ_131","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_131","question":"A resort hotel owns an unused plot of land beside its car park and sells it for $95,000 to help pay for renovating its guest bedrooms. What is a major advantage of raising finance in this way?","options":{"A":"It makes better use of idle capital without incurring debt or interest charges","B":"The hotel retains legal ownership of the land after selling it","C":"It increases the hotel's non-current liabilities","D":"It can be repeated every month indefinitely"},"correctOption":"A","correctAnswer":"It makes better use of idle capital without incurring debt or interest charges","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because selling unwanted assets converts idle resources into immediate cash internally without adding debt or interest costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because selling an asset transfers legal ownership to the buyer.","C":"Incorrect because selling an asset reduces non-current assets and does not create any loan liability.","D":"Incorrect because a business has a limited supply of surplus assets to sell."}}},{"id":"P1_U5_MCQ_132","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_132","question":"An electronics manufacturer holds $120,000 of excess microchips in its storeroom and decides to reduce its inventory buffer to release $50,000 of cash for upgrading factory computers. What is a potential risk of using working capital as an internal source of finance in this way?","options":{"A":"The manufacturer must pay high interest to its shareholders","B":"Running down inventory too far may cause production stoppages if supplier deliveries are delayed","C":"Reducing inventory increases the company's long-term bank loans","D":"The manufacturer loses control of the business to external lenders"},"correctOption":"B","correctAnswer":"Running down inventory too far may cause production stoppages if supplier deliveries are delayed","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because reducing inventory levels frees up cash, but holding too little stock risks shortages and halted production if demand spikes or deliveries are late.","distractor_reasons":{"A":"Incorrect because using internal working capital incurs no interest charges.","B":"Correct selection.","C":"Incorrect because reducing inventory converts current assets into cash without increasing debt.","D":"Incorrect because internal finance does not involve external lenders or equity dilution."}}},{"id":"P1_U5_MCQ_133","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_133","question":"Three accountants running a partnership decide to expand into tax consultancy and each partner invests an extra $20,000 of personal savings into the firm. How is this $60,000 classified?","options":{"A":"External short-term finance","B":"Trade credit","C":"Internal finance through owners' investment","D":"Venture capital"},"correctOption":"C","correctAnswer":"Internal finance through owners' investment","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital contributed directly by the existing owners or partners from their own funds is an internal source of finance.","distractor_reasons":{"A":"Incorrect because the funds come from the owners themselves, not external institutions, and are permanent.","B":"Incorrect because trade credit is delayed payment granted by suppliers.","C":"Correct selection.","D":"Incorrect because venture capital comes from outside specialist investment firms rather than existing partners."}}},{"id":"P1_U5_MCQ_134","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_134","question":"A public limited company issues 5 million new ordinary shares on the stock exchange to raise $40 million for building a clean-energy power plant. What is a significant disadvantage of issuing shares to raise this finance?","options":{"A":"The $40 million must be repaid to shareholders within five years","B":"The company must pay fixed monthly interest even if it makes a loss","C":"Existing shareholders' voting control is diluted and dividends are expected from future profits","D":"Share capital reduces the company's total equity on the statement of financial position"},"correctOption":"C","correctAnswer":"Existing shareholders' voting control is diluted and dividends are expected from future profits","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because issuing new shares spreads ownership across more shareholders, diluting original control and creating expectations for future dividend payouts.","distractor_reasons":{"A":"Incorrect because ordinary share capital is permanent finance with no repayment date.","B":"Incorrect because ordinary shares carry dividends (which are not paid if profits are insufficient), not fixed interest.","C":"Correct selection.","D":"Incorrect because issuing shares increases share capital and total equity."}}},{"id":"P1_U5_MCQ_135","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_135","question":"A private limited company needs $500,000 to purchase a new warehouse and is comparing a 10-year bank loan with issuing shares to a new private investor. Which statement correctly contrasts these two options?","options":{"A":"The bank loan requires regular interest and principal repayments, whereas share capital does not have to be repaid","B":"The bank loan gives the bank permanent voting rights, whereas shares must be repaid in 12 months","C":"Both options are internal sources of finance","D":"Neither option affects the company's statement of financial position"},"correctOption":"A","correctAnswer":"The bank loan requires regular interest and principal repayments, whereas share capital does not have to be repaid","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a bank loan is debt that must be repaid with interest over an agreed term, whereas share capital is permanent equity finance.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because banks do not gain voting shares from a loan, and share capital is permanent rather than 12-month debt.","C":"Incorrect because both bank loans and new share issues are external sources of finance.","D":"Incorrect because both increase cash/assets alongside either non-current liabilities (loan) or equity (shares)."}}},{"id":"P1_U5_MCQ_136","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_136","question":"A small events-management agency uses a $15,000 bank overdraft continuously for two years to cover its everyday expenses. Why is using an overdraft in this way poor financial management?","options":{"A":"Overdrafts charge high variable interest rates and the bank can demand immediate repayment at short notice","B":"Overdrafts require the agency to give up 50% of its shares to the bank","C":"Overdrafts can only be used to buy freehold property","D":"Overdrafts are classified as non-current assets"},"correctOption":"A","correctAnswer":"Overdrafts charge high variable interest rates and the bank can demand immediate repayment at short notice","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because overdrafts are designed for brief, temporary cash deficits; using one permanently incurs high interest and exposes the firm to sudden recall by the bank.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because an overdraft is short-term borrowing, not an equity stake.","C":"Incorrect because overdrafts are meant for short-term working capital, not buying property.","D":"Incorrect because an overdrawn bank balance is a current liability."}}},{"id":"P1_U5_MCQ_137","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_137","question":"An entrepreneur applies for a $75,000 five-year bank loan to open a fitness gym, and the bank asks for collateral before approving the loan. What does the bank mean by collateral?","options":{"A":"A list of all potential gym members who have promised to join","B":"An asset such as property or equipment that the bank can sell if the borrower fails to repay the loan","C":"A guarantee from the government to pay the entrepreneur's staff wages","D":"The entrepreneur's personal university degree certificate"},"correctOption":"B","correctAnswer":"An asset such as property or equipment that the bank can sell if the borrower fails to repay the loan","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because collateral (security) is a valuable asset pledged by the borrower that the lender can seize and sell to recover its money in case of default.","distractor_reasons":{"A":"Incorrect because customer interest lists do not provide physical security for a loan.","B":"Correct selection.","C":"Incorrect because collateral is pledged by the borrower, not a government wage subsidy.","D":"Incorrect because academic qualifications have no resale value to cover a defaulted loan."}}},{"id":"P1_U5_MCQ_138","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_138","question":"A newly opened convenience store asks food wholesalers for 45 days of trade credit on its first stock delivery, but the wholesalers insist on cash on delivery. Why do suppliers often refuse trade credit to brand-new businesses?","options":{"A":"Trade credit is illegal for businesses trading for less than one year","B":"Wholesalers are not allowed to record trade receivables","C":"New businesses lack a proven trading history, creating a high risk that they may fail before paying","D":"Trade credit can only be used to purchase non-current assets"},"correctOption":"C","correctAnswer":"New businesses lack a proven trading history, creating a high risk that they may fail before paying","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because suppliers face a high risk of non-payment when lending goods on credit to unproven start-ups with high failure rates.","distractor_reasons":{"A":"Incorrect because there is no law banning suppliers from offering credit to new businesses.","B":"Incorrect because wholesalers routinely record trade receivables for established credit customers.","C":"Correct selection.","D":"Incorrect because trade credit is specifically used for purchasing raw materials and inventory."}}},{"id":"P1_U5_MCQ_139","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_139","question":"A self-employed tailor in a low-income rural community needs $350 to buy an electric sewing machine, but commercial banks refuse to lend such a small sum without property collateral. Which source of finance is specifically designed to help entrepreneurs in this situation?","options":{"A":"Issuing debentures on the stock exchange","B":"Microfinance","C":"Venture capital","D":"Sale and leaseback of factories"},"correctOption":"B","correctAnswer":"Microfinance","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because microfinance institutions provide very small loans (microloans) to low-income entrepreneurs who lack traditional collateral or access to commercial banks.","distractor_reasons":{"A":"Incorrect because stock exchange issues raise millions of dollars for large public limited companies.","B":"Correct selection.","C":"Incorrect because venture capitalists invest large sums into high-growth technology or scalable companies.","D":"Incorrect because sale and leaseback applies to businesses that already own expensive property."}}},{"id":"P1_U5_MCQ_140","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_140","question":"An independent game developer uses a crowdfunding website to raise $35,000 from 1,400 backers to manufacture a new strategy board game. Aside from raising cash, what is a key benefit of crowdfunding for the developer?","options":{"A":"It tests market demand and builds an early customer base before full production begins","B":"It guarantees that no competitors can ever copy the game idea","C":"It exempts the developer from paying any taxes on future sales","D":"It provides unlimited long-term finance without needing to deliver any rewards"},"correctOption":"A","correctAnswer":"It tests market demand and builds an early customer base before full production begins","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because reaching a crowdfunding target proves that real customers are willing to pay for the product and generates publicity before mass production.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because publishing a prototype online actually exposes the concept to public view rather than preventing copying.","C":"Incorrect because crowdfunding campaigns do not grant tax exemptions.","D":"Incorrect because reward-based crowdfunding requires delivering promised products or perks to backers."}}},{"id":"P1_U5_MCQ_141","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_141","question":"A fast-growing electric bicycle start-up accepts $1.2 million from a venture capital firm in exchange for a 30% shareholding. What is a major advantage of venture capital compared with a bank loan for this start-up?","options":{"A":"The founders keep 100% ownership and never have to consult the investors","B":"Venture capitalists provide specialist business advice and contacts, and require no fixed monthly interest payments","C":"Venture capital is completely free and investors expect zero financial return","D":"Venture capital can be arranged within one hour without a business plan"},"correctOption":"B","correctAnswer":"Venture capitalists provide specialist business advice and contacts, and require no fixed monthly interest payments","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because venture capitalists bring strategic mentorship and industry networks alongside risk capital that does not burden a young firm with fixed monthly loan repayments.","distractor_reasons":{"A":"Incorrect because the founders gave up 30% equity and venture capitalists usually expect board representation.","B":"Correct selection.","C":"Incorrect because venture capitalists expect high capital growth or dividends when they eventually sell their stake.","D":"Incorrect because venture capitalists conduct thorough due diligence on the business plan before investing."}}},{"id":"P1_U5_MCQ_142","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_142","question":"A private diagnostic clinic needs a $450,000 medical scanner, where technology advances rapidly every three to four years. Why would leasing be preferable to buying the scanner outright?","options":{"A":"Leasing transfers immediate legal ownership of the scanner to the clinic on Day 1","B":"Leasing eliminates all monthly cash outflows","C":"The clinic avoids a huge upfront cash outlay and can upgrade to newer models when the lease ends","D":"Leasing is always cheaper over 20 years than buying an asset outright"},"correctOption":"C","correctAnswer":"The clinic avoids a huge upfront cash outlay and can upgrade to newer models when the lease ends","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because leasing preserves cash flow and protects the clinic against technological obsolescence by allowing easy replacement at the end of the lease term.","distractor_reasons":{"A":"Incorrect because legal ownership remains with the leasing company throughout the lease.","B":"Incorrect because leasing requires regular monthly or quarterly rental payments.","C":"Correct selection.","D":"Incorrect because over a very long period, total lease payments usually exceed the cash purchase price."}}},{"id":"P1_U5_MCQ_143","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_143","question":"A civil engineering contractor acquires a bulldozer via hire purchase over four years instead of leasing it. How does hire purchase differ from leasing?","options":{"A":"Hire purchase requires no deposit and zero interest charges","B":"Under hire purchase, the contractor becomes the legal owner of the bulldozer once the final instalment is paid","C":"Hire purchase is an internal source of finance","D":"Hire purchase can only be used for buying raw materials and inventory"},"correctOption":"B","correctAnswer":"Under hire purchase, the contractor becomes the legal owner of the bulldozer once the final instalment is paid","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because hire purchase is an instalment purchase agreement where ownership passes to the buyer upon completion of all payments, whereas leased assets remain owned by the lessor.","distractor_reasons":{"A":"Incorrect because hire purchase usually requires an initial deposit and includes interest within the instalments.","B":"Correct selection.","C":"Incorrect because hire purchase is provided by an external finance company.","D":"Incorrect because hire purchase is used to buy durable non-current assets such as vehicles and machinery."}}},{"id":"P1_U5_MCQ_144","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_144","question":"A textile factory receives a $60,000 government grant to install solar panels and retrain 40 workers in green manufacturing. What condition is typically attached to such a government grant?","options":{"A":"The factory must repay the $60,000 with 12% annual interest within two years","B":"The government becomes the majority shareholder of the factory","C":"The factory must use the funds for the agreed purpose, such as meeting environmental or training targets","D":"The factory must sell all of its products exclusively to government departments"},"correctOption":"C","correctAnswer":"The factory must use the funds for the agreed purpose, such as meeting environmental or training targets","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because government grants do not have to be repaid provided the business meets specific conditions like creating jobs, training staff, or investing in green technology.","distractor_reasons":{"A":"Incorrect because grants are non-repayable financial awards unless the business breaches the grant conditions.","B":"Incorrect because grants do not give the government equity ownership in private businesses.","C":"Correct selection.","D":"Incorrect because grant recipients continue selling to their normal commercial customers."}}},{"id":"P1_U5_MCQ_145","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_145","question":"A food-processing company finances the $900,000 construction of a new canning factory using a short-term bank overdraft. Why is this choice of finance risky?","options":{"A":"The factory will take years to generate enough cash to repay the debt, while the bank could recall the overdraft at any time","B":"Bank overdrafts cannot be recorded in a company's accounting books","C":"Using an overdraft forces the company to pay dividends every week","D":"A factory cannot be used until all bank debts are completely repaid"},"correctOption":"A","correctAnswer":"The factory will take years to generate enough cash to repay the debt, while the bank could recall the overdraft at any time","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because long-term assets like factories should be matched with long-term finance; funding one with an on-demand overdraft creates severe liquidity and interest-rate risk.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because overdrafts are always recorded as current liabilities.","C":"Incorrect because overdrafts incur interest, not weekly dividends.","D":"Incorrect because businesses routinely operate factories financed by long-term mortgages or loans."}}},{"id":"P1_U5_MCQ_146","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_146","question":"Why does a public limited company have access to a wider range of external finance sources than a sole trader?","options":{"A":"Sole traders are legally prohibited from opening business bank accounts","B":"Public limited companies can sell shares to the general public on a stock exchange and usually have more assets for collateral","C":"Public limited companies never have to pay interest on bank loans","D":"Sole traders are banned from using trade credit or leasing"},"correctOption":"B","correctAnswer":"Public limited companies can sell shares to the general public on a stock exchange and usually have more assets for collateral","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because legal form and business size allow public limited companies to issue shares publicly and secure large loans against substantial assets.","distractor_reasons":{"A":"Incorrect because sole traders can open business bank accounts and apply for loans or overdrafts.","B":"Correct selection.","C":"Incorrect because public limited companies still pay interest on borrowed debt.","D":"Incorrect because sole traders can use both trade credit and leasing."}}},{"id":"P1_U5_MCQ_147","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_147","question":"A small bakery needs $900 urgently to repair a broken dough mixer so it can fulfill tomorrow's orders. Which factor makes a bank overdraft or personal savings far more suitable than a 5-year bank loan?","options":{"A":"The small amount required and the need for immediate speed","B":"The bakery's status as a multinational public limited company","C":"The 15-year lifespan of the repair","D":"The requirement to dilute shareholder ownership"},"correctOption":"A","correctAnswer":"The small amount required and the need for immediate speed","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because $900 is too small for formal long-term loan paperwork and is needed immediately, making an existing overdraft or owner's cash ideal.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the scenario describes a small bakery, not a multinational plc.","C":"Incorrect because a minor repair is a short-term operational expense, not a 15-year capital project.","D":"Incorrect because a small bakery does not want to dilute ownership for a $900 repair."}}},{"id":"P1_U5_MCQ_148","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_148","question":"When choosing between a bank loan and issuing new shares, the directors of a profitable family-owned private limited company check their existing debt level and find they currently have zero loans. How does this factor influence their decision?","options":{"A":"Having zero existing debt makes them unable to qualify for any bank loan","B":"Having low existing debt means they can safely afford loan interest repayments without giving up family ownership control","C":"Having zero existing debt forces them to convert into a sole trader","D":"Having zero existing debt means banks will charge them 0% interest"},"correctOption":"B","correctAnswer":"Having low existing debt means they can safely afford loan interest repayments without giving up family ownership control","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because existing loans (gearing) affect financial risk; with no current debt, the company can easily service a bank loan while keeping 100% family control.","distractor_reasons":{"A":"Incorrect because having low existing debt makes a profitable company more attractive to banks, not less.","B":"Correct selection.","C":"Incorrect because debt levels do not change a company's incorporated legal status.","D":"Incorrect because banks still charge market interest rates on loans."}}},{"id":"P1_U5_MCQ_149","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_149","question":"A construction company needs $300,000 for new cranes and compares two finance options: Option 1 is retained profit, and Option 2 is a 7-year bank loan at 8% annual interest. Which factor is the finance director evaluating when comparing the 8% interest charge against zero interest?","options":{"A":"The cost of finance","B":"The legal form of the business","C":"The location of the construction site","D":"The number of employees in the firm"},"correctOption":"A","correctAnswer":"The cost of finance","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because comparing interest rates, arrangement fees, and dividend expectations evaluates the cost of each source of finance.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because both retained profit and a bank loan are available to the company regardless of legal structure.","C":"Incorrect because site location does not determine interest rate comparisons.","D":"Incorrect because workforce size is not what is being compared by the 8% interest rate."}}},{"id":"P1_U5_MCQ_150","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_150","question":"A manufacturing company raises $500,000 for factory modernisation from four sources: $180,000 from retained profit, $45,000 from selling old machinery, $200,000 from a 6-year bank loan, and $75,000 from a government grant. How much of this finance was raised from external sources?","options":{"A":"$225,000","B":"$275,000","C":"$200,000","D":"$500,000"},"correctOption":"B","correctAnswer":"$275,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because external sources come from outside the business: the bank loan ($200,000) plus the government grant ($75,000) = $275,000.","distractor_reasons":{"A":"Incorrect because $225,000 is the total from internal sources ($180,000 retained profit + $45,000 asset sale).","B":"Correct selection.","C":"Incorrect because $200,000 only counts the bank loan and omits the $75,000 government grant.","D":"Incorrect because $500,000 is the total finance raised from both internal and external sources combined."}}},{"id":"P1_U5_MCQ_151","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_151","question":"A wholesale bakery generates high sales revenue on paper, yet it is shut down by creditors because it cannot pay its flour suppliers or staff wages at the end of the month. What does this demonstrate about the importance of cash?","options":{"A":"Without sufficient cash liquidity to pay immediate bills, even a profitable business cannot survive","B":"Cash is less important than non-current assets for paying weekly wages","C":"Businesses only need cash at the end of their financial year","D":"High sales revenue automatically guarantees cash in the bank"},"correctOption":"A","correctAnswer":"Without sufficient cash liquidity to pay immediate bills, even a profitable business cannot survive","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cash is required to settle immediate day-to-day obligations like wages and supplier invoices; running out of cash leads to insolvency.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because workers and suppliers must be paid in cash, not with machinery or property.","C":"Incorrect because cash is required continuously every week and month to pay ongoing expenses.","D":"Incorrect because sales made on credit do not immediately provide cash."}}},{"id":"P1_U5_MCQ_152","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_152","question":"Which statement accurately describes the cash flow of a business over a trading period?","options":{"A":"The total value of all buildings and machinery owned by the business","B":"The movement of money into and out of the business over a given period of time","C":"The difference between gross profit and overhead expenses","D":"The total amount of share capital invested by founders"},"correctOption":"B","correctAnswer":"The movement of money into and out of the business over a given period of time","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because cash flow refers to the actual cash inflows (receipts) entering and cash outflows (payments) leaving a business during a specific timeframe.","distractor_reasons":{"A":"Incorrect because buildings and machinery are non-current assets on the statement of financial position.","B":"Correct selection.","C":"Incorrect because gross profit minus expenses equals profit, not cash flow.","D":"Incorrect because share capital is equity finance rather than ongoing cash movement."}}},{"id":"P1_U5_MCQ_153","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_153","question":"A gardening business records the following items for May: $9,000 received from cash customers, $4,500 collected from April credit clients, a $10,000 bank loan deposited into its account, and $6,000 paid for new lawnmowers. What are the total cash inflows for May?","options":{"A":"$13,500","B":"$19,000","C":"$23,500","D":"$17,500"},"correctOption":"C","correctAnswer":"$23,500","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because all money entering the bank account counts as cash inflows: $9,000 cash sales + $4,500 credit receipts + $10,000 bank loan = $23,500.","distractor_reasons":{"A":"Incorrect because $13,500 omits the $10,000 bank loan inflow.","B":"Incorrect because $19,000 omits the $4,500 collected from April credit clients.","C":"Correct selection.","D":"Incorrect because $17,500 subtracts the $6,000 lawnmower outflow from total inflows."}}},{"id":"P1_U5_MCQ_154","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_154","question":"During June, an engineering workshop pays $11,000 in wages, pays $3,500 in factory rent, repays $1,500 of bank loan principal, and orders $5,000 of steel on 60-day trade credit. What are the workshop's total cash outflows for June?","options":{"A":"$21,000","B":"$16,000","C":"$14,500","D":"$19,500"},"correctOption":"B","correctAnswer":"$16,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because June cash outflows include only actual payments made in June: $11,000 wages + $3,500 rent + $1,500 loan repayment = $16,000 (the steel on 60-day credit is paid in August).","distractor_reasons":{"A":"Incorrect because $21,000 wrongly includes the $5,000 steel ordered on 60-day credit.","B":"Correct selection.","C":"Incorrect because $14,500 omits the $1,500 loan repayment cash outflow.","D":"Incorrect because $19,500 includes the credit order and omits the loan repayment."}}},{"id":"P1_U5_MCQ_155","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_155","question":"Which item should NEVER be entered into a monthly cash flow forecast?","options":{"A":"Cash receipts from customers paying their invoices","B":"Monthly rent paid to the landlord","C":"Sales made on credit where the customer will not pay until next year","D":"Proceeds from issuing new shares for cash"},"correctOption":"C","correctAnswer":"Sales made on credit where the customer will not pay until next year","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a cash flow forecast only records actual cash inflows and outflows during the forecast period, excluding unpaid credit transactions.","distractor_reasons":{"A":"Incorrect because cash received from credit customers is a genuine cash inflow.","B":"Incorrect because rent paid is a regular cash outflow.","C":"Correct selection.","D":"Incorrect because cash received from issuing shares is a cash inflow."}}},{"id":"P1_U5_MCQ_156","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_156","question":"A furniture wholesaler makes total sales of $30,000 in January and $40,000 in February. Half (50%) of all sales are paid in cash immediately, and the remaining 50% are paid one month later. What is the wholesaler's total cash inflow in February?","options":{"A":"$40,000","B":"$35,000","C":"$20,000","D":"$70,000"},"correctOption":"B","correctAnswer":"$35,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because February cash inflows consist of 50% of February's sales paid immediately ($20,000) plus 50% of January's credit sales collected one month later ($15,000) = $35,000.","distractor_reasons":{"A":"Incorrect because $40,000 is total February sales revenue, half of which will not be collected until March.","B":"Correct selection.","C":"Incorrect because $20,000 only counts February cash sales and ignores the $15,000 collected from January credit customers.","D":"Incorrect because $70,000 adds total January and February revenue together."}}},{"id":"P1_U5_MCQ_157","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_157","question":"A clothing manufacturer buys $16,000 of fabric in March on 1-month trade credit and $22,000 of fabric in April on 1-month trade credit, while paying $9,000 in factory wages each month. What are the manufacturer's total cash outflows in April?","options":{"A":"$31,000","B":"$25,000","C":"$16,000","D":"$47,000"},"correctOption":"B","correctAnswer":"$25,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because in April the manufacturer pays for March's fabric purchase ($16,000) plus April's wages ($9,000) = $25,000 (April's $22,000 fabric purchase is paid in May).","distractor_reasons":{"A":"Incorrect because $31,000 uses April's $22,000 credit fabric purchase instead of March's $16,000 invoice due in April.","B":"Correct selection.","C":"Incorrect because $16,000 omits the $9,000 April wages outflow.","D":"Incorrect because $47,000 includes both March and April fabric purchases in April."}}},{"id":"P1_U5_MCQ_158","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_158","question":"In September, a bookstore forecasts total cash inflows of $42,600 and total cash outflows of $36,900. What is the bookstore's forecast net cash flow for September?","options":{"A":"$5,700","B":"-$5,700","C":"$79,500","D":"$6,700"},"correctOption":"A","correctAnswer":"$5,700","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Net cash flow = Cash inflows - Cash outflows ($42,600 - $36,900 = $5,700).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because inflows exceed outflows, so net cash flow is positive rather than negative.","C":"Incorrect because $79,500 adds inflows and outflows together instead of subtracting outflows.","D":"Incorrect due to a subtraction error ($42,600 - $36,900 = $5,700, not $6,700)."}}},{"id":"P1_U5_MCQ_159","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_159","question":"During February, a swimming pool maintenance business expects cash inflows of $11,200 and cash outflows of $15,850. What is the forecast net cash flow for February?","options":{"A":"$4,650","B":"$27,050","C":"-$4,650","D":"-$4,450"},"correctOption":"C","correctAnswer":"-$4,650","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Net cash flow = Cash inflows - Cash outflows ($11,200 - $15,850 = -$4,650).","distractor_reasons":{"A":"Incorrect because outflows exceed inflows, making the net cash flow negative (-$4,650).","B":"Incorrect because $27,050 adds inflows and outflows together.","C":"Correct selection.","D":"Incorrect due to a subtraction error ($15,850 - $11,200 = $4,650)."}}},{"id":"P1_U5_MCQ_160","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_160","question":"A travel agency begins November with an opening cash balance of $6,400. During November, cash inflows are $21,000 and cash outflows are $25,300. What is the agency's closing cash balance at the end of November?","options":{"A":"-$4,300","B":"$10,700","C":"$2,100","D":"-$2,100"},"correctOption":"C","correctAnswer":"$2,100","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because November's net cash flow is $21,000 - $25,300 = -$4,300, and adding this to the $6,400 opening balance gives a closing balance of $2,100.","distractor_reasons":{"A":"Incorrect because -$4,300 is the net cash flow and ignores the $6,400 opening balance.","B":"Incorrect because $10,700 adds $4,300 to the opening balance instead of subtracting the deficit.","C":"Correct selection.","D":"Incorrect because $6,400 - $4,300 is positive $2,100, not negative."}}},{"id":"P1_U5_MCQ_161","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_161","question":"A printing firm starts December with an overdrawn opening balance of -$3,800. During December, cash inflows are $29,000 and cash outflows are $31,200. What is the firm's closing cash balance at the end of December?","options":{"A":"-$2,200","B":"-$6,000","C":"$1,600","D":"-$1,600"},"correctOption":"B","correctAnswer":"-$6,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because December's net cash flow is $29,000 - $31,200 = -$2,200, and combining this with the -$3,800 opening overdraft yields -$6,000.","distractor_reasons":{"A":"Incorrect because -$2,200 is only December's net cash flow and omits the -$3,800 opening overdraft.","B":"Correct selection.","C":"Incorrect because $1,600 treats the -$3,800 overdraft as a positive opening balance (+$3,800 - $2,200).","D":"Incorrect because -$3,800 + (-$2,200) deepens the overdraft to -$6,000 rather than reducing it."}}},{"id":"P1_U5_MCQ_162","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_162","question":"A café has an opening balance of $1,500 in January. In January, inflows are $12,000 and outflows are $10,500. In February, inflows are $11,000 and outflows are $13,200. What is the café's closing cash balance at the end of February?","options":{"A":"-$2,200","B":"$3,000","C":"$800","D":"-$700"},"correctOption":"C","correctAnswer":"$800","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because January closing balance = $1,500 + ($12,000 - $10,500) = $3,000, which becomes February's opening balance; February closing balance = $3,000 + ($11,000 - $13,200) = $800.","distractor_reasons":{"A":"Incorrect because -$2,200 is February's net cash flow alone.","B":"Incorrect because $3,000 is January's closing balance (February's opening balance), not February's closing balance.","C":"Correct selection.","D":"Incorrect because -$700 ignores January's net cash flow of +$1,500."}}},{"id":"P1_U5_MCQ_163","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_163","question":"A gift shop forecasts July cash inflows of $20,000, cash outflows of $18,500, and an opening balance of $1,000. If actual July cash inflows turn out to be 15% lower than forecast while outflows stay unchanged, what will the July closing balance be?","options":{"A":"$2,500","B":"-$500","C":"-$1,500","D":"$5,500"},"correctOption":"B","correctAnswer":"-$500","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a 15% drop reduces inflows from $20,000 to $17,000; net cash flow becomes $17,000 - $18,500 = -$1,500, and adding the $1,000 opening balance gives -$500.","distractor_reasons":{"A":"Incorrect because $2,500 is the original closing balance before the 15% fall in cash inflows.","B":"Correct selection.","C":"Incorrect because -$1,500 is the revised net cash flow and ignores the $1,000 opening balance.","D":"Incorrect because $5,500 adds the $3,000 variance instead of subtracting it."}}},{"id":"P1_U5_MCQ_164","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_164","question":"A restaurant normally pays its meat supplier $4,000 per month on 1-month trade credit, so in August it planned to pay July's $4,000 bill. However, the supplier suddenly demands immediate cash payment on delivery for August's $4,500 order as well. By how much will the restaurant's August cash outflows increase?","options":{"A":"$4,000","B":"$8,500","C":"$500","D":"$4,500"},"correctOption":"D","correctAnswer":"$4,500","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the restaurant must still pay July's $4,000 invoice in August AND now also pay August's $4,500 order in cash, increasing August cash outflows by $4,500.","distractor_reasons":{"A":"Incorrect because the $4,000 for July was already included in August's forecast outflows.","B":"Incorrect because $8,500 is the new total paid to the supplier in August, not the increase above the original forecast.","C":"Incorrect because the restaurant is paying both invoices in August rather than replacing one with the other.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_165","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_165","question":"When an entrepreneur applies for a bank loan to start a new business, why does the bank manager insist on reviewing a 12-month cash flow forecast?","options":{"A":"To verify that the business will generate enough monthly cash inflows to afford loan interest and repayments on time","B":"To calculate the exact market value of the entrepreneur's personal home","C":"To confirm that the entrepreneur has paid corporation tax for the last five years","D":"To determine how many shares the bank will own in the start-up"},"correctOption":"A","correctAnswer":"To verify that the business will generate enough monthly cash inflows to afford loan interest and repayments on time","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because lenders use cash flow forecasts to judge whether the new business is realistically planned and will have sufficient cash liquidity to repay the loan.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because property valuations are assessed separately for collateral, not via a cash flow forecast.","C":"Incorrect because a new start-up does not have five years of past tax records.","D":"Incorrect because banks lend money for interest rather than taking share ownership."}}},{"id":"P1_U5_MCQ_166","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_166","question":"A software company's cash flow forecast reveals that its positive closing cash balance will grow steadily from $25,000 in January to $95,000 by June. How can management best use this forecast information?","options":{"A":"Arrange an emergency high-interest bank overdraft","B":"Plan to invest the surplus cash in higher-interest accounts, repay existing loans early, or fund new equipment","C":"Stop collecting payments from credit customers","D":"Delay paying staff salaries for six months"},"correctOption":"B","correctAnswer":"Plan to invest the surplus cash in higher-interest accounts, repay existing loans early, or fund new equipment","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because cash flow forecasts do not only spot deficits; they also highlight large cash surpluses so managers can put idle cash to productive use.","distractor_reasons":{"A":"Incorrect because a growing positive balance means no overdraft is needed.","B":"Correct selection.","C":"Incorrect because businesses should always collect money owed by customers promptly.","D":"Incorrect because withholding wages is illegal and unnecessary when cash is abundant."}}},{"id":"P1_U5_MCQ_167","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_167","question":"A manufacturing firm predicts a temporary cash shortfall of -$6,000 in April before large customer payments arrive in May. Why is arranging a short-term bank overdraft a widely used solution for this problem?","options":{"A":"It quickly covers the temporary deficit without damaging supplier relationships, and interest is only paid for one month","B":"The bank never charges any interest or arrangement fees on overdrafts","C":"It permanently increases the firm's share capital","D":"It eliminates the need to collect money from May customers"},"correctOption":"A","correctAnswer":"It quickly covers the temporary deficit without damaging supplier relationships, and interest is only paid for one month","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an overdraft bridges short-term timing gaps cleanly so bills are paid on time, and it is cleared as soon as May receipts arrive.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because banks charge relatively high interest rates and often an arrangement fee on overdrafts.","C":"Incorrect because an overdraft is temporary debt, not share capital.","D":"Incorrect because May customer receipts are needed to pay off the overdraft."}}},{"id":"P1_U5_MCQ_168","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_168","question":"To ease a cash shortage this month, an electrical contractor asks its cable suppliers for an extra 30 days to pay outstanding invoices. How does this action immediately improve the contractor's cash flow?","options":{"A":"It increases this month's cash inflows from customers","B":"It reduces or delays this month's cash outflows, keeping cash in the bank for longer","C":"It permanently cancels the debt owed to the cable suppliers","D":"It lowers the contractor's cost of sales on the statement of profit or loss"},"correctOption":"B","correctAnswer":"It reduces or delays this month's cash outflows, keeping cash in the bank for longer","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because extending trade credit postpones cash outflows into a later month, improving the current month's closing cash balance.","distractor_reasons":{"A":"Incorrect because supplier payment terms affect cash outflows, not customer inflows.","B":"Correct selection.","C":"Incorrect because the invoice still has to be paid 30 days later.","D":"Incorrect because delaying payment does not reduce the purchase price of the cables (and may even forfeit early-payment discounts)."}}},{"id":"P1_U5_MCQ_169","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_169","question":"A wholesale distributor has $50,000 tied up in unpaid trade receivables and faces an urgent cash shortage. Instead of waiting 60 days for customers to pay, the distributor uses debt factoring, receiving 85% of the invoice value immediately from a finance company. What is the main disadvantage of this cash flow solution?","options":{"A":"The distributor receives less than the full invoice value (losing 15% as a fee), reducing its overall profit","B":"The distributor must wait an extra 60 days before receiving any cash","C":"The distributor must offer its factory building as collateral","D":"Suppliers will refuse to sell goods to the distributor"},"correctOption":"A","correctAnswer":"The distributor receives less than the full invoice value (losing 15% as a fee), reducing its overall profit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because while debt factoring provides immediate cash inflows, the factor deducts a substantial fee/discount, reducing the business's revenue collected and profit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because debt factoring accelerates cash inflows immediately rather than delaying them.","C":"Incorrect because factoring is based on the value of unpaid customer invoices rather than property collateral.","D":"Incorrect because getting cash faster actually helps the distributor pay its suppliers on time."}}},{"id":"P1_U5_MCQ_170","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_170","question":"A printing company facing a six-month cash crunch decides to lease a new $45,000 binding machine for $950 a month instead of paying $45,000 cash upfront. How does this decision help solve its short-term cash flow problem?","options":{"A":"It spreads the cash outflows over several years instead of causing a large immediate cash drain","B":"It increases monthly cash inflows from printing customers","C":"It turns the binding machine into a current asset","D":"It makes the machine completely free over a ten-year period"},"correctOption":"A","correctAnswer":"It spreads the cash outflows over several years instead of causing a large immediate cash drain","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because leasing replaces a large lump-sum capital cash outflow with manageable monthly rental payments.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because leasing reduces cash outflows rather than increasing customer inflows.","C":"Incorrect because leased assets are owned by the lessor and are not current assets.","D":"Incorrect because lease rentals must be paid every month throughout the contract."}}},{"id":"P1_U5_MCQ_171","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_171","question":"To quickly boost cash inflows during a cash deficit, a local water utility supplier considers cutting its prices by 20%, even though demand for water is largely unaffected by price changes. Why would this action worsen its cash flow problem?","options":{"A":"Sales volume will hardly rise, so total cash inflows from customers will fall by nearly 20%","B":"Cutting prices automatically increases fixed rent expenses","C":"Customers will refuse to pay in cash if prices are lower","D":"Lower prices increase the interest rate on the company's bank loan"},"correctOption":"A","correctAnswer":"Sales volume will hardly rise, so total cash inflows from customers will fall by nearly 20%","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because when demand does not respond strongly to lower prices (price-inelastic demand), a 20% price cut reduces total cash receipts.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because fixed rent expenses are independent of product selling prices.","C":"Incorrect because lower prices do not prevent customers from paying in cash.","D":"Incorrect because loan interest rates are set by the bank, not by product pricing."}}},{"id":"P1_U5_MCQ_172","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_172","question":"During its first year, an architectural firm records $240,000 in completed client fee revenue and $150,000 in expenses, giving a profit of $90,000, yet its bank balance falls by -$35,000. Which combination of factors best explains how the firm is profitable yet cash-negative?","options":{"A":"Clients were given 90 days to pay their invoices and the firm bought $60,000 of computer equipment for cash","B":"All clients paid in cash on Day 1 and the firm had zero equipment purchases","C":"The firm received a $100,000 cash grant that was excluded from profit","D":"Expenses were paid on 12-month credit so no cash left the bank"},"correctOption":"A","correctAnswer":"Clients were given 90 days to pay their invoices and the firm bought $60,000 of computer equipment for cash","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because credit revenue is counted in profit before cash arrives, while cash spent on non-current computer equipment reduces cash without being deducted in full from profit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because immediate cash receipts and no capital spending would result in a strongly positive cash balance.","C":"Incorrect because receiving a $100,000 cash grant would increase the bank balance rather than reducing it.","D":"Incorrect because delaying cash outflows would keep the bank balance positive."}}},{"id":"P1_U5_MCQ_173","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_173","question":"A struggling retail chain makes an annual loss of -$45,000, yet its net cash flow for the year is +$30,000. Which transaction explains how a loss-making business can generate positive net cash flow?","options":{"A":"The chain sold two unused delivery trucks for $85,000 cash","B":"The chain paid all its suppliers 60 days early","C":"The chain allowed customers to take six months to pay for goods","D":"The chain bought $90,000 of new display shelves for cash"},"correctOption":"A","correctAnswer":"The chain sold two unused delivery trucks for $85,000 cash","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because selling non-current assets generates a large cash inflow ($85,000) that boosts cash balances even when normal trading makes a loss.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because paying suppliers early accelerates cash outflows and reduces cash.","C":"Incorrect because giving customers six months to pay delays cash inflows.","D":"Incorrect because buying shelves for cash creates a large cash outflow."}}},{"id":"P1_U5_MCQ_174","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_174","question":"A small biscuit manufacturer wins a contract to supply a national supermarket chain, doubling its production volume overnight, but runs out of cash two months later despite strong profit margins. What caused this 'overtrading' cash flow crisis?","options":{"A":"The manufacturer had to pay cash immediately for extra flour, packaging, and overtime wages long before the supermarket paid its 60-day invoices","B":"Supermarkets are legally prohibited from paying for biscuits","C":"Doubling output automatically reduced the manufacturer's revenue to zero","D":"The manufacturer's profit margin became negative when output doubled"},"correctOption":"A","correctAnswer":"The manufacturer had to pay cash immediately for extra flour, packaging, and overtime wages long before the supermarket paid its 60-day invoices","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because expanding output rapidly requires immediate working capital outflows for materials and labour before cash inflows from new credit sales arrive.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because supermarkets pay invoices after the agreed credit period.","C":"Incorrect because doubling output doubled sales revenue, even though cash collection was delayed.","D":"Incorrect because the scenario states the manufacturer had strong profit margins."}}},{"id":"P1_U5_MCQ_175","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_175","question":"A new café owner prepares a cash flow forecast assuming 150 customers per day, but a rival coffee chain opens next door in Month 3, cutting daily customers to 80. What limitation of cash flow forecasts does this illustrate?","options":{"A":"Forecasts are based on estimates and assumptions that can be invalidated by unexpected changes in competition or market conditions","B":"Cash flow forecasts are only allowed to include fixed costs","C":"A cash flow forecast legally prevents a business from changing its prices","D":"Cash flow forecasts ignore all cash payments to suppliers"},"correctOption":"A","correctAnswer":"Forecasts are based on estimates and assumptions that can be invalidated by unexpected changes in competition or market conditions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because forecasts rely on predictions of future sales and costs; sudden external events like a new competitor make the original numbers inaccurate unless updated.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because forecasts include both fixed and variable cash outflows.","C":"Incorrect because a forecast is a planning tool, not a legal restriction on pricing.","D":"Incorrect because supplier payments are included as cash outflows."}}},{"id":"P1_U5_MCQ_176","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_176","question":"Over a 12-month financial year, a local cinema earns $410,000 from ticket and snack sales while incurring total costs of $435,000. Which financial outcome has the cinema experienced?","options":{"A":"A profit of $25,000","B":"A loss of $25,000","C":"A gross profit of $410,000","D":"A positive net cash flow of $25,000"},"correctOption":"B","correctAnswer":"A loss of $25,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because when total costs ($435,000) exceed total revenue ($410,000), the business makes a loss ($410,000 - $435,000 = -$25,000).","distractor_reasons":{"A":"Incorrect because costs are higher than revenue, resulting in a loss rather than a profit.","B":"Correct selection.","C":"Incorrect because $410,000 is total revenue before deducting cost of sales.","D":"Incorrect because revenue minus costs measures profit/loss, not net cash flow."}}},{"id":"P1_U5_MCQ_177","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_177","question":"Why is making a profit essential for the long-term survival of a private sector business?","options":{"A":"Without profit, owners have no reward for risking their capital and the business lacks internal funds to reinvest or survive downturns","B":"Profit is the only item recorded on a statement of financial position","C":"Private sector businesses are fined by the government every month they do not make a profit","D":"Profit guarantees that the business will never face competition"},"correctOption":"A","correctAnswer":"Without profit, owners have no reward for risking their capital and the business lacks internal funds to reinvest or survive downturns","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because profit rewards entrepreneurs for risk-taking and provides retained profit to finance growth and cushion against tough trading periods.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the statement of financial position lists assets, liabilities, and equity.","C":"Incorrect because governments do not fine businesses for making a loss (in fact, loss-making firms pay no corporation tax).","D":"Incorrect because high profits often attract new competitors into an industry."}}},{"id":"P1_U5_MCQ_178","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_178","question":"A medium-sized packaging company plans to automate its production line over the next five years without taking on heavy bank debt. How does making consistent profits enable this strategy?","options":{"A":"Retained profit can be accumulated as an interest-free internal source of finance to buy the automated machinery","B":"Profit automatically reduces the purchase price of machinery by 50%","C":"Profit increases the company's trade payables","D":"Profit allows the company to stop paying utility bills"},"correctOption":"A","correctAnswer":"Retained profit can be accumulated as an interest-free internal source of finance to buy the automated machinery","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because retained profit is one of the cheapest and safest sources of finance for funding long-term capital investment.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because machinery suppliers charge the same price regardless of the buyer's profit.","C":"Incorrect because retained profit increases equity, not short-term supplier debts.","D":"Incorrect because profitable businesses still have to pay all operating expenses."}}},{"id":"P1_U5_MCQ_179","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_179","question":"A start-up software firm is deciding between two mobile app concepts: App X is expected to generate $80,000 in annual profit, while App Y is expected to generate $35,000. How is profit being used by the management team here?","options":{"A":"As a measure of short-term bank liquidity","B":"As a criterion for comparing options and deciding which project offers the best financial return","C":"As a way to calculate the firm's acid-test ratio","D":"As a method for valuing non-current liabilities"},"correctOption":"B","correctAnswer":"As a criterion for comparing options and deciding which project offers the best financial return","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because expected profit serves as a key benchmark for managers when comparing investment projects and allocating resources.","distractor_reasons":{"A":"Incorrect because liquidity measures cash availability, not projected project profit.","B":"Correct selection.","C":"Incorrect because the acid-test ratio uses current assets, inventory, and current liabilities.","D":"Incorrect because projected profit does not value long-term liabilities."}}},{"id":"P1_U5_MCQ_180","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_180","question":"A community-owned bakery operates as a social enterprise, training unemployed young people while selling artisan bread. Why does this social enterprise still aim to make a profit?","options":{"A":"To maximise cash dividends for wealthy stock exchange investors","B":"To avoid having to pay its bakers any wages","C":"To remain financially self-sustaining and reinvest surpluses into training more young people","D":"Because social enterprises are legally required to pay 90% of profit to banks"},"correctOption":"C","correctAnswer":"To remain financially self-sustaining and reinvest surpluses into training more young people","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because social enterprises need profit to survive without relying solely on donations and to reinvest in expanding their social mission.","distractor_reasons":{"A":"Incorrect because social enterprises prioritise social/environmental objectives over private shareholder dividends.","B":"Incorrect because social enterprises pay fair wages to their employees.","C":"Correct selection.","D":"Incorrect because there is no law requiring social enterprises to pay 90% of profits to banks."}}},{"id":"P1_U5_MCQ_181","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_181","question":"Why is 'profit' on a statement of profit or loss rarely equal to the 'closing cash balance' on a cash flow statement for the same year?","options":{"A":"Because credit sales are included in revenue before cash is received, and cash inflows like loans or outflows like asset purchases are excluded from profit","B":"Because accountants are allowed to guess revenue figures on the statement of profit or loss","C":"Because cash flow statements never include wages or rent","D":"Because profit is only calculated for cash sales"},"correctOption":"A","correctAnswer":"Because credit sales are included in revenue before cash is received, and cash inflows like loans or outflows like asset purchases are excluded from profit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because profit follows accrual accounting (matching revenue earned with costs incurred), whereas cash flow tracks actual money entering and leaving the bank.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because revenue must be accurately recorded from invoices and sales records.","C":"Incorrect because wages and rent paid are major cash outflows on a cash flow statement.","D":"Incorrect because profit includes both cash and credit sales."}}},{"id":"P1_U5_MCQ_182","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_182","question":"During the financial year, a bicycle manufacturer sells 1,200 mountain bikes at $450 each and 800 road bikes at $600 each. What is the manufacturer's total revenue for the year?","options":{"A":"$540,000","B":"$480,000","C":"$1,020,000","D":"$2,000"},"correctOption":"C","correctAnswer":"$1,020,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because total revenue = (1,200 × $450) + (800 × $600) = $540,000 + $480,000 = $1,020,000.","distractor_reasons":{"A":"Incorrect because $540,000 only counts revenue from mountain bikes.","B":"Incorrect because $480,000 only counts revenue from road bikes.","C":"Correct selection.","D":"Incorrect because 2,000 is the total number of bicycles sold, not the dollar revenue."}}},{"id":"P1_U5_MCQ_183","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_183","question":"A shoe manufacturer is preparing its statement of profit or loss. Which item should be included in 'cost of sales'?","options":{"A":"Leather, rubber soles, and wages of factory machine operators making the shoes","B":"Salaries of the human resources and accounting departments","C":"Interest paid on a long-term bank mortgage","D":"Rent paid for the head office building"},"correctOption":"A","correctAnswer":"Leather, rubber soles, and wages of factory machine operators making the shoes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cost of sales comprises the direct materials and direct production labour costs involved in making the goods sold.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because HR and accounting salaries are indirect administrative expenses.","C":"Incorrect because loan interest is a finance expense deducted after gross profit.","D":"Incorrect because head office rent is an indirect overhead expense."}}},{"id":"P1_U5_MCQ_184","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_184","question":"A sporting goods retailer records annual revenue of $720,000, cost of sales of $430,000, and overhead expenses of $195,000. What is the retailer's gross profit?","options":{"A":"$95,000","B":"$290,000","C":"$525,000","D":"$235,000"},"correctOption":"B","correctAnswer":"$290,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Gross profit = Revenue - Cost of sales ($720,000 - $430,000 = $290,000).","distractor_reasons":{"A":"Incorrect because $95,000 is the final profit after deducting both cost of sales and $195,000 of overhead expenses.","B":"Correct selection.","C":"Incorrect because $525,000 subtracts expenses from revenue instead of cost of sales.","D":"Incorrect because $235,000 subtracts expenses from cost of sales ($430,000 - $195,000)."}}},{"id":"P1_U5_MCQ_185","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_185","question":"Which group of costs consists solely of indirect 'expenses' (overheads) deducted from gross profit on a statement of profit or loss?","options":{"A":"Direct raw materials, packaging for products, and piece-rate factory wages","B":"Office electricity, delivery van insurance, and marketing salaries","C":"Wholesale purchase price of goods bought for resale","D":"Revenue from online sales and cash register sales"},"correctOption":"B","correctAnswer":"Office electricity, delivery van insurance, and marketing salaries","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because office electricity, vehicle insurance, and marketing salaries are indirect running expenses deducted from gross profit to calculate profit.","distractor_reasons":{"A":"Incorrect because direct raw materials, product packaging, and piece-rate production wages are direct costs included in cost of sales.","B":"Correct selection.","C":"Incorrect because goods bought for resale form part of cost of sales.","D":"Incorrect because sales figures represent revenue, not expenses."}}},{"id":"P1_U5_MCQ_186","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_186","question":"A florist shop has annual revenue of $210,000, cost of sales of $88,000, and overhead expenses of $74,000. What is the shop's profit for the year?","options":{"A":"$122,000","B":"$136,000","C":"$48,000","D":"$162,000"},"correctOption":"C","correctAnswer":"$48,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Gross profit = $210,000 - $88,000 = $122,000, and Profit = Gross profit - Expenses ($122,000 - $74,000 = $48,000).","distractor_reasons":{"A":"Incorrect because $122,000 is the gross profit before deducting $74,000 of overhead expenses.","B":"Incorrect because $136,000 deducts only expenses from revenue and ignores cost of sales.","C":"Correct selection.","D":"Incorrect because $162,000 adds cost of sales and expenses together ($88,000 + $74,000)."}}},{"id":"P1_U5_MCQ_187","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_187","question":"A limited company earns a profit before tax of $200,000. Corporation tax is $40,000, and the directors pay $55,000 in dividends to shareholders. How much retained profit is added to the company's equity?","options":{"A":"$160,000","B":"$145,000","C":"$105,000","D":"$95,000"},"correctOption":"C","correctAnswer":"$105,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Profit after tax = $200,000 - $40,000 = $160,000, and Retained profit = Profit after tax - Dividends ($160,000 - $55,000 = $105,000).","distractor_reasons":{"A":"Incorrect because $160,000 is profit after tax before subtracting the $55,000 dividend payout.","B":"Incorrect because $145,000 subtracts dividends ($55,000) from profit before tax and forgets the $40,000 tax.","C":"Correct selection.","D":"Incorrect because $95,000 is the sum of tax and dividends paid out ($40,000 + $55,000)."}}},{"id":"P1_U5_MCQ_188","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_188","question":"An extract from a bakery's statement of profit or loss shows cost of sales of $135,000, gross profit of $195,000, and overhead expenses of $110,000. What was the bakery's total revenue?","options":{"A":"$330,000","B":"$60,000","C":"$85,000","D":"$440,000"},"correctOption":"A","correctAnswer":"$330,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Gross profit = Revenue - Cost of sales, so Revenue = Gross profit + Cost of sales ($195,000 + $135,000 = $330,000).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $60,000 subtracts cost of sales from gross profit instead of adding them.","C":"Incorrect because $85,000 is the final profit ($195,000 gross profit - $110,000 expenses).","D":"Incorrect because $440,000 adds overhead expenses to revenue ($330,000 + $110,000)."}}},{"id":"P1_U5_MCQ_189","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_189","question":"A hardware store reports annual revenue of $450,000, overhead expenses of $95,000, and a final profit of $65,000. What was the store's cost of sales?","options":{"A":"$160,000","B":"$290,000","C":"$385,000","D":"$355,000"},"correctOption":"B","correctAnswer":"$290,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Gross profit = Profit + Expenses ($65,000 + $95,000 = $160,000), and Cost of sales = Revenue - Gross profit ($450,000 - $160,000 = $290,000).","distractor_reasons":{"A":"Incorrect because $160,000 is the gross profit, not the cost of sales.","B":"Correct selection.","C":"Incorrect because $385,000 subtracts only final profit from revenue ($450,000 - $65,000), failing to remove overhead expenses.","D":"Incorrect because $355,000 subtracts only overhead expenses from revenue ($450,000 - $95,000)."}}},{"id":"P1_U5_MCQ_190","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_190","question":"A steel tariff raises the cost of sheet metal for a washing-machine manufacturer by $35,000, while the manufacturer's sales revenue and overhead expenses remain unchanged. How does this tariff affect the statement of profit or loss?","options":{"A":"Gross profit falls by $35,000 and final profit also falls by $35,000","B":"Gross profit stays unchanged, while final profit falls by $35,000","C":"Revenue increases by $35,000 and gross profit stays unchanged","D":"Cost of sales falls by $35,000 and gross profit rises by $35,000"},"correctOption":"A","correctAnswer":"Gross profit falls by $35,000 and final profit also falls by $35,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sheet metal is a direct raw material in cost of sales; raising cost of sales by $35,000 lowers gross profit by $35,000 and flows through to lower final profit by $35,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because sheet metal is part of cost of sales rather than an indirect overhead expense, so gross profit decreases.","C":"Incorrect because higher material costs do not automatically increase sales revenue.","D":"Incorrect because a tariff increases the cost of sheet metal rather than reducing it."}}},{"id":"P1_U5_MCQ_191","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_191","question":"An accounting firm's landlord increases annual office rent by $18,000, while client fee revenue and direct costs remain unchanged. What is the effect on the firm's statement of profit or loss?","options":{"A":"Gross profit falls by $18,000 and profit falls by $18,000","B":"Gross profit is unchanged, while overhead expenses rise by $18,000 and profit falls by $18,000","C":"Cost of sales rises by $18,000 and profit stays unchanged","D":"Both gross profit and profit increase by $18,000"},"correctOption":"B","correctAnswer":"Gross profit is unchanged, while overhead expenses rise by $18,000 and profit falls by $18,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because office rent is an indirect overhead expense deducted after gross profit; gross profit is unaffected, but final profit drops by $18,000.","distractor_reasons":{"A":"Incorrect because office rent is not part of cost of sales, so gross profit does not change.","B":"Correct selection.","C":"Incorrect because higher rent increases expenses and reduces final profit.","D":"Incorrect because higher rent is a cost increase, not a gain."}}},{"id":"P1_U5_MCQ_192","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_192","question":"A chocolate manufacturer wants to increase its profit by 15% next year by increasing its revenue. Which strategy aims to increase revenue without raising selling prices?","options":{"A":"Launching a targeted advertising campaign and selling through new online retail channels to boost sales volume","B":"Switching to cheaper cocoa beans from a new supplier","C":"Reducing head-office administrative staff numbers","D":"Selling off an unused storage warehouse"},"correctOption":"A","correctAnswer":"Launching a targeted advertising campaign and selling through new online retail channels to boost sales volume","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because revenue equals price multiplied by quantity sold; expanding distribution and promotion increases sales volume and revenue at existing prices.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cheaper cocoa beans reduce cost of sales rather than increasing revenue.","C":"Incorrect because cutting office staff reduces overhead expenses rather than increasing revenue.","D":"Incorrect because selling a warehouse is a one-off asset disposal, not sales revenue."}}},{"id":"P1_U5_MCQ_193","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_193","question":"A clothing retailer spends $25,000 on an influencer marketing campaign that boosts revenue by $60,000, with associated cost of sales of $20,000. How does this campaign affect the retailer's profit?","options":{"A":"Profit increases by $60,000","B":"Profit decreases by $25,000","C":"Profit increases by $15,000","D":"Profit increases by $40,000"},"correctOption":"C","correctAnswer":"Profit increases by $15,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because extra gross profit is $60,000 revenue - $20,000 cost of sales = $40,000, and subtracting the $25,000 marketing expense gives a net profit gain of $15,000.","distractor_reasons":{"A":"Incorrect because $60,000 is the extra revenue before deducting cost of sales and marketing expenses.","B":"Incorrect because the extra gross profit ($40,000) exceeds the $25,000 marketing cost.","C":"Correct selection.","D":"Incorrect because $40,000 is the extra gross profit before deducting the $25,000 marketing expense."}}},{"id":"P1_U5_MCQ_194","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_194","question":"To reduce its cost of sales, a smartphone maker replaces a reliable precision-lens supplier with a much cheaper, untested supplier. What is the main danger of this cost-cutting approach?","options":{"A":"Faulty lenses may increase product returns and damage brand reputation, causing future sales and profit to fall","B":"Lower lens prices will immediately increase the smartphone maker's overhead expenses","C":"Cost of sales will increase because cheaper components cost more","D":"Gross profit will fall immediately even if sales stay constant"},"correctOption":"A","correctAnswer":"Faulty lenses may increase product returns and damage brand reputation, causing future sales and profit to fall","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cutting direct material costs by sacrificing component quality often leads to defects, warranty claims, and lost customer trust.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because component prices affect cost of sales rather than indirect overheads.","C":"Incorrect because cheaper lenses lower direct cost per unit in the short term.","D":"Incorrect because if sales stay constant and unit costs fall, gross profit rises initially before quality issues emerge."}}},{"id":"P1_U5_MCQ_195","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_195","question":"A nationwide insurance company reduces its indirect expenses by moving customer-service teams from expensive city-centre offices to smaller regional hubs and allowing remote work. How does this decision affect its statement of profit or loss?","options":{"A":"It lowers overhead expenses, increasing final profit while leaving gross profit unchanged","B":"It increases cost of sales and lowers gross profit","C":"It increases revenue and decreases retained profit","D":"It eliminates the need to pay corporation tax on profits"},"correctOption":"A","correctAnswer":"It lowers overhead expenses, increasing final profit while leaving gross profit unchanged","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because office rent and facility bills are overhead expenses deducted below gross profit; cutting them raises profit without altering gross profit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because office rent is an indirect expense, not cost of sales.","C":"Incorrect because cutting rent expenses raises profit and potential retained profit rather than reducing them.","D":"Incorrect because higher profit actually increases corporation tax obligations."}}},{"id":"P1_U5_MCQ_196","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_196","question":"Reviewing its statement of profit or loss, a restaurant group finds that its City Branch generated $500,000 in revenue with $380,000 in cost of sales and $140,000 in expenses, resulting in a loss of -$20,000. Before deciding to close the City Branch, what should senior managers consider?","options":{"A":"Whether the City Branch contributes towards shared head-office fixed costs and whether cost controls or menu changes could restore it to profit","B":"Closing any branch that makes a small loss is always mandatory by law","C":"A loss-making branch always has a positive cash flow that cannot be replaced","D":"Closing the branch will automatically increase revenue at all other branches by 100%"},"correctOption":"A","correctAnswer":"Whether the City Branch contributes towards shared head-office fixed costs and whether cost controls or menu changes could restore it to profit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because managers use profit statements alongside strategic judgement: the branch earns a positive gross profit ($120,000) that helps cover shared overheads and might be turned around.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because businesses often keep temporarily unprofitable branches open while restructuring them.","C":"Incorrect because a loss-making branch does not automatically generate positive cash flow.","D":"Incorrect because closing a branch usually loses local customers rather than doubling sales elsewhere."}}},{"id":"P1_U5_MCQ_197","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_197","question":"Between Year 1 and Year 2, a bicycle shop's revenue stayed constant at $300,000, its gross profit fell from $120,000 to $90,000, and its overhead expenses remained constant at $70,000. What caused the shop's final profit to fall from $50,000 to $20,000?","options":{"A":"Cost of sales increased by $30,000","B":"Overhead expenses increased by $30,000","C":"Sales revenue fell by $30,000","D":"Dividend payments increased by $30,000"},"correctOption":"A","correctAnswer":"Cost of sales increased by $30,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because revenue stayed at $300,000 while gross profit dropped by $30,000 ($120,000 to $90,000), meaning cost of sales must have risen from $180,000 to $210,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the question states overhead expenses remained constant at $70,000.","C":"Incorrect because revenue remained constant at $300,000.","D":"Incorrect because dividends are distributed out of profit after tax rather than deducted before profit."}}},{"id":"P1_U5_MCQ_198","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_198","question":"A luxury watch retailer achieves a very high gross profit of $600,000 on $1,000,000 of revenue, yet its final profit is a loss of -$50,000. How can a business earn a large gross profit and still make an overall loss?","options":{"A":"Its indirect overhead expenses (such as flagship store rent and marketing) exceeded its $600,000 gross profit","B":"Its cost of sales was higher than its $1,000,000 revenue","C":"Its current assets were lower than its current liabilities","D":"It paid too much corporation tax before calculating gross profit"},"correctOption":"A","correctAnswer":"Its indirect overhead expenses (such as flagship store rent and marketing) exceeded its $600,000 gross profit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Profit = Gross profit - Expenses; if indirect expenses total $650,000, a $600,000 gross profit becomes a -$50,000 loss.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because gross profit was +$600,000, proving cost of sales was $400,000 (less than revenue).","C":"Incorrect because liquidity ratios on the statement of financial position do not determine trading loss.","D":"Incorrect because corporation tax is only charged when a business makes a positive profit."}}},{"id":"P1_U5_MCQ_199","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_199","question":"When reviewing a supplier's statement of profit or loss, why should a business NOT rely solely on the profit figure to judge whether the supplier is financially safe?","options":{"A":"Because a business with high reported profit can still face a severe cash shortage and go bankrupt if customers fail to pay","B":"Because the statement of profit or loss never includes sales revenue","C":"Because profit figures are legally allowed to be invented by directors","D":"Because cost of sales is always excluded from profit calculations"},"correctOption":"A","correctAnswer":"Because a business with high reported profit can still face a severe cash shortage and go bankrupt if customers fail to pay","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the statement of profit or loss measures profitability rather than cash liquidity; a profitable supplier can still collapse from poor cash flow.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because sales revenue is the very first line of the statement of profit or loss.","C":"Incorrect because directors are legally required to present true and fair accounts.","D":"Incorrect because cost of sales is always deducted from revenue to find gross profit."}}},{"id":"P1_U5_MCQ_200","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_200","question":"A public limited company's statement of profit or loss shows revenue of $2.4m, cost of sales of $1.5m, expenses of $500,000, tax of $80,000, and dividends of $120,000. What is the company's retained profit for the year?","options":{"A":"$400,000","B":"$320,000","C":"$200,000","D":"$900,000"},"correctOption":"C","correctAnswer":"$200,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Gross profit = $2.4m - $1.5m = $900,000; Profit before tax = $900,000 - $500,000 = $400,000; Profit after tax = $400,000 - $80,000 = $320,000; Retained profit = $320,000 - $120,000 = $200,000.","distractor_reasons":{"A":"Incorrect because $400,000 is profit before tax and dividends.","B":"Incorrect because $320,000 is profit after tax before deducting the $120,000 dividend payout.","C":"Correct selection.","D":"Incorrect because $900,000 is the gross profit."}}},{"id":"P1_U5_MCQ_201","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_201","question":"Which financial statement acts like a photograph of a business's financial health at one exact date, showing everything it owns, everything it owes, and the owners' stake?","options":{"A":"Statement of financial position","B":"Statement of profit or loss","C":"Monthly cash flow forecast","D":"Break-even chart"},"correctOption":"A","correctAnswer":"Statement of financial position","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the statement of financial position records assets, liabilities, and equity at a specific point in time.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the statement of profit or loss records trading revenue, costs, and profit over an entire accounting period.","C":"Incorrect because a cash flow forecast estimates future monthly cash inflows and outflows.","D":"Incorrect because a break-even chart shows costs, revenue, and break-even output levels."}}},{"id":"P1_U5_MCQ_202","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_202","question":"An airline owns passenger aircraft, airport hangar buildings, spare jet engines held in storage for maintenance, and cash in its bank accounts. Which items are classified as non-current assets?","options":{"A":"Passenger aircraft and airport hangar buildings","B":"Cash in bank accounts and unpaid ticket receivables","C":"Passenger aircraft and bank overdrafts","D":"Airport hangar buildings and unpaid fuel supplier invoices"},"correctOption":"A","correctAnswer":"Passenger aircraft and airport hangar buildings","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because passenger aircraft and hangar buildings are long-term physical resources owned and used by the airline for more than one year.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cash and trade receivables are short-term current assets.","C":"Incorrect because bank overdrafts are current liabilities.","D":"Incorrect because unpaid fuel supplier invoices are trade payables (current liabilities)."}}},{"id":"P1_U5_MCQ_203","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_203","question":"Why are inventory, trade receivables, and cash grouped together as 'current assets' on a statement of financial position?","options":{"A":"Because they are owned permanently and will never be sold or used up","B":"Because they are held for less than one year and are expected to be converted into cash during normal trading","C":"Because they represent debts that the business must repay to suppliers within 30 days","D":"Because they are excluded when calculating a business's total assets"},"correctOption":"B","correctAnswer":"Because they are held for less than one year and are expected to be converted into cash during normal trading","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because current assets are short-term resources that circulate continuously within a 12-month trading cycle into cash.","distractor_reasons":{"A":"Incorrect because permanent long-term resources are non-current assets.","B":"Correct selection.","C":"Incorrect because debts owed to suppliers within 30 days are current liabilities (trade payables).","D":"Incorrect because total assets equal non-current assets plus current assets."}}},{"id":"P1_U5_MCQ_204","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_204","question":"When listing current assets in order of increasing liquidity (from hardest to turn into cash quickly to easiest), which sequence is correct?","options":{"A":"Cash → Trade receivables → Inventory","B":"Trade receivables → Cash → Inventory","C":"Inventory → Trade receivables → Cash","D":"Inventory → Cash → Trade receivables"},"correctOption":"C","correctAnswer":"Inventory → Trade receivables → Cash","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because inventory must first be sold to create a trade receivable, which must then be collected to become cash—making cash the most liquid asset.","distractor_reasons":{"A":"Incorrect because this lists current assets from most liquid to least liquid.","B":"Incorrect because cash is more liquid than both trade receivables and inventory.","C":"Correct selection.","D":"Incorrect because cash is already liquid money, whereas trade receivables still await customer payment."}}},{"id":"P1_U5_MCQ_205","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_205","question":"Which list contains ONLY current liabilities on a company's statement of financial position?","options":{"A":"Trade payables, bank overdraft, and corporation tax payable within 6 months","B":"10-year bank loan, share capital, and retained profit","C":"Trade receivables, inventory, and cash at bank","D":"Freehold factory, delivery vans, and 15-year mortgage"},"correctOption":"A","correctAnswer":"Trade payables, bank overdraft, and corporation tax payable within 6 months","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because trade payables, overdrafts, and tax due within a year are short-term obligations classified as current liabilities.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a 10-year loan is a non-current liability, while share capital and retained profit are equity.","C":"Incorrect because trade receivables, inventory, and cash are current assets.","D":"Incorrect because factory and vans are non-current assets, and a 15-year mortgage is a non-current liability."}}},{"id":"P1_U5_MCQ_206","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_206","question":"A shipping company borrows $2.5 million via a 15-year mortgage to buy a new cargo vessel. How is this $2.5 million debt classified on the shipping company's statement of financial position?","options":{"A":"Non-current liability","B":"Current liability","C":"Non-current asset","D":"Shareholders' equity"},"correctOption":"A","correctAnswer":"Non-current liability","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because debts that are due to be repaid over more than 12 months are recorded as non-current liabilities.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because current liabilities only include debts falling due within one year.","C":"Incorrect because the cargo vessel is the non-current asset, whereas the mortgage owed to the lender is a non-current liability.","D":"Incorrect because a mortgage is borrowed debt, not owners' equity."}}},{"id":"P1_U5_MCQ_207","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_207","question":"On a limited company's statement of financial position, which two items are combined to show total shareholders' equity?","options":{"A":"Share capital and retained profit","B":"Non-current assets and current assets","C":"Trade receivables and trade payables","D":"Bank loans and bank overdrafts"},"correctOption":"A","correctAnswer":"Share capital and retained profit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because shareholders' equity represents the owners' stake in the company, consisting of original share capital invested plus accumulated retained profits.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because non-current assets plus current assets equals total assets.","C":"Incorrect because trade receivables are current assets and trade payables are current liabilities.","D":"Incorrect because bank loans and overdrafts are debt liabilities."}}},{"id":"P1_U5_MCQ_208","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_208","question":"A bakery's statement of financial position shows premises of $240,000, ovens of $60,000, inventory of $12,000, trade receivables of $9,000, and cash of $5,000. What is the value of the bakery's total current assets?","options":{"A":"$300,000","B":"$26,000","C":"$326,000","D":"$21,000"},"correctOption":"B","correctAnswer":"$26,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Current assets = Inventory ($12,000) + Trade receivables ($9,000) + Cash ($5,000) = $26,000.","distractor_reasons":{"A":"Incorrect because $300,000 is the total of non-current assets ($240,000 + $60,000).","B":"Correct selection.","C":"Incorrect because $326,000 is total assets (both non-current and current combined).","D":"Incorrect because $21,000 omits the $5,000 cash balance."}}},{"id":"P1_U5_MCQ_209","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_209","question":"A toy wholesaler has current assets of $84,000 and current liabilities of $51,000, alongside non-current assets of $190,000 and non-current liabilities of $70,000. What is the wholesaler's net current assets (working capital)?","options":{"A":"$33,000","B":"$135,000","C":"$153,000","D":"$274,000"},"correctOption":"A","correctAnswer":"$33,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Net current assets (working capital) = Current assets - Current liabilities ($84,000 - $51,000 = $33,000).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $135,000 adds current assets and current liabilities together ($84,000 + $51,000).","C":"Incorrect because $153,000 is total net assets ($190,000 + $84,000 - $51,000 - $70,000).","D":"Incorrect because $274,000 is total assets ($190,000 + $84,000)."}}},{"id":"P1_U5_MCQ_210","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_210","question":"A logistics firm reports non-current assets of $420,000, current assets of $95,000, current liabilities of $55,000, and non-current liabilities of $160,000. What is the value of the firm's net assets?","options":{"A":"$515,000","B":"$460,000","C":"$300,000","D":"$215,000"},"correctOption":"C","correctAnswer":"$300,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Total assets = $420,000 + $95,000 = $515,000, Total liabilities = $55,000 + $160,000 = $215,000, and Net assets = Total assets - Total liabilities ($515,000 - $215,000 = $300,000).","distractor_reasons":{"A":"Incorrect because $515,000 is total assets before deducting any liabilities.","B":"Incorrect because $460,000 is capital employed (Total assets - Current liabilities), which does not subtract non-current liabilities.","C":"Correct selection.","D":"Incorrect because $215,000 is total liabilities."}}},{"id":"P1_U5_MCQ_211","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_211","question":"A company's statement of financial position shows non-current assets of $500,000, working capital (net current assets) of $80,000, non-current liabilities of $180,000, share capital of $250,000, and retained profit of $150,000. What is the company's capital employed?","options":{"A":"$400,000","B":"$580,000","C":"$430,000","D":"$660,000"},"correctOption":"B","correctAnswer":"$580,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Capital employed = Total equity ($250,000 + $150,000 = $400,000) + Non-current liabilities ($180,000) = $580,000 (which also equals Non-current assets $500,000 + Working capital $80,000).","distractor_reasons":{"A":"Incorrect because $400,000 is shareholders' equity alone and omits the $180,000 non-current liabilities.","B":"Correct selection.","C":"Incorrect because $430,000 omits the $150,000 retained profit.","D":"Incorrect because $660,000 adds working capital twice."}}},{"id":"P1_U5_MCQ_212","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_212","question":"On a company's statement of financial position, total assets are $620,000, total liabilities are $245,000, and share capital is $250,000. What must the company's retained profit be for the statement to balance?","options":{"A":"$375,000","B":"$125,000","C":"$120,000","D":"$495,000"},"correctOption":"B","correctAnswer":"$125,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Net assets = Total assets - Total liabilities ($620,000 - $245,000 = $375,000), which must equal Total equity (Share capital $250,000 + Retained profit), giving Retained profit = $375,000 - $250,000 = $125,000.","distractor_reasons":{"A":"Incorrect because $375,000 is total shareholders' equity, not retained profit alone.","B":"Correct selection.","C":"Incorrect due to a subtraction error ($375,000 - $250,000 = $125,000).","D":"Incorrect because $495,000 adds liabilities and share capital together."}}},{"id":"P1_U5_MCQ_213","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_213","question":"A public limited company issues new ordinary shares and receives $1,000,000 in cash into its bank account. How does this transaction immediately change the company's statement of financial position?","options":{"A":"Current assets (cash) increase by $1,000,000 and shareholders' equity (share capital) increases by $1,000,000","B":"Non-current assets increase by $1,000,000 and current liabilities increase by $1,000,000","C":"Current liabilities decrease by $1,000,000 and retained profit decreases by $1,000,000","D":"Current assets decrease by $1,000,000 and non-current liabilities increase by $1,000,000"},"correctOption":"A","correctAnswer":"Current assets (cash) increase by $1,000,000 and shareholders' equity (share capital) increases by $1,000,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because receiving cash increases current assets by $1,000,000 while issuing shares increases share capital within equity by $1,000,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cash is a current asset and share issues create equity rather than liabilities.","C":"Incorrect because share issues bring money into the company rather than reducing liabilities or retained profit.","D":"Incorrect because cash increases rather than decreases, and share capital is equity rather than debt."}}},{"id":"P1_U5_MCQ_214","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_214","question":"A wholesaler collects $14,000 in cash from credit customers who owed money for earlier deliveries. What is the immediate impact on the wholesaler's total current assets?","options":{"A":"Total current assets increase by $14,000","B":"Total current assets decrease by $14,000","C":"Total current assets remain unchanged because cash rises by $14,000 while trade receivables fall by $14,000","D":"Total current assets increase by $28,000"},"correctOption":"C","correctAnswer":"Total current assets remain unchanged because cash rises by $14,000 while trade receivables fall by $14,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because both cash and trade receivables are current assets; converting $14,000 of receivables into cash leaves total current assets unchanged.","distractor_reasons":{"A":"Incorrect because trade receivables drop by the exact same amount that cash rises.","B":"Incorrect because the cash remains inside current assets.","C":"Correct selection.","D":"Incorrect because collecting a receivable does not double current assets."}}},{"id":"P1_U5_MCQ_215","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_215","question":"A company uses $40,000 of its cash balance to pay off part of its long-term bank loan. Which two sections of the statement of financial position decrease by $40,000?","options":{"A":"Current assets and non-current liabilities","B":"Non-current assets and current liabilities","C":"Current assets and shareholders' equity","D":"Non-current assets and shareholders' equity"},"correctOption":"A","correctAnswer":"Current assets and non-current liabilities","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cash (a current asset) decreases by $40,000 and the long-term bank loan (a non-current liability) also decreases by $40,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cash is a current asset and a long-term loan is a non-current liability.","C":"Incorrect because repaying a bank loan reduces debt liabilities rather than owners' equity.","D":"Incorrect because neither non-current assets nor equity changes when cash repays a long-term loan."}}},{"id":"P1_U5_MCQ_216","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_216","question":"A supermarket pays $12,000 in cash to purchase fresh produce inventory from farmers. How does this purchase affect the supermarket's working capital?","options":{"A":"Working capital decreases by $12,000","B":"Working capital increases by $12,000","C":"Working capital remains unchanged because cash falls by $12,000 while inventory rises by $12,000","D":"Working capital becomes negative by $12,000"},"correctOption":"C","correctAnswer":"Working capital remains unchanged because cash falls by $12,000 while inventory rises by $12,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because both cash and inventory are current assets; swapping one current asset for another leaves total current assets and working capital unchanged.","distractor_reasons":{"A":"Incorrect because inventory increases by the same $12,000 that cash decreases.","B":"Incorrect because total current assets do not increase when cash is spent on inventory.","C":"Correct selection.","D":"Incorrect because swapping cash for inventory does not alter working capital."}}},{"id":"P1_U5_MCQ_217","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_217","question":"Comparing its statement of financial position over two years, a consumer electronics retailer sees its inventory value jump from $45,000 to $140,000 while annual sales fell by 10%. What problem does this data highlight?","options":{"A":"The retailer is accumulating unsold, potentially obsolete stock that ties up cash and risks write-downs","B":"The retailer has paid off all of its trade payables","C":"The retailer's non-current liabilities have fallen to zero","D":"The retailer has too much cash in its bank account"},"correctOption":"A","correctAnswer":"The retailer is accumulating unsold, potentially obsolete stock that ties up cash and risks write-downs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because surging inventory during falling sales indicates poor stock control and slow-moving products that tie up working capital.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because rising inventory does not mean trade payables are zero.","C":"Incorrect because inventory levels do not show non-current liabilities.","D":"Incorrect because buying excess inventory drains cash rather than creating excess cash."}}},{"id":"P1_U5_MCQ_218","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_218","question":"A catering firm's statement of financial position shows cash of $1,000, trade receivables of $9,000, inventory of $8,000, trade payables of $22,000, and a bank overdraft of $11,000. What is the firm's working capital?","options":{"A":"$15,000","B":"-$15,000","C":"-$4,000","D":"$51,000"},"correctOption":"B","correctAnswer":"-$15,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Current assets = $1,000 + $9,000 + $8,000 = $18,000 and Current liabilities = $22,000 + $11,000 = $33,000, giving working capital of $18,000 - $33,000 = -$15,000.","distractor_reasons":{"A":"Incorrect because current liabilities exceed current assets, making working capital negative (-$15,000).","B":"Correct selection.","C":"Incorrect because -$4,000 omits the $11,000 bank overdraft from current liabilities ($18,000 - $22,000).","D":"Incorrect because $51,000 adds current assets and current liabilities together."}}},{"id":"P1_U5_MCQ_219","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_219","question":"Between 2024 and 2026, a manufacturing company's non-current liabilities rose from $100,000 to $500,000 while its total equity remained at $200,000. How has the company's financial structure changed?","options":{"A":"It has become much more reliant on long-term borrowed debt, increasing interest costs and financial risk","B":"It has become completely debt-free","C":"Its current assets have grown five times larger","D":"Its retained profit has increased by $400,000"},"correctOption":"A","correctAnswer":"It has become much more reliant on long-term borrowed debt, increasing interest costs and financial risk","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because non-current liabilities grew from half of equity to 2.5 times equity, showing heavy reliance on long-term debt (high gearing).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because non-current liabilities rose to $500,000.","C":"Incorrect because non-current liabilities do not measure current asset growth.","D":"Incorrect because total equity remained unchanged at $200,000."}}},{"id":"P1_U5_MCQ_220","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_220","question":"Over five profitable years, a private limited company never issues any new shares and keeps its bank loans unchanged, yet its total assets grow from $300,000 to $580,000. Which item on the statement of financial position must have increased by $280,000 to fund this growth?","options":{"A":"Retained profit within shareholders' equity","B":"Original share capital","C":"Non-current liabilities","D":"Cost of sales"},"correctOption":"A","correctAnswer":"Retained profit within shareholders' equity","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because with share capital and liabilities unchanged, the $280,000 increase in net assets must have been funded by accumulated retained profits in equity.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the scenario states no new shares were issued.","C":"Incorrect because the scenario states bank loans remained unchanged.","D":"Incorrect because cost of sales appears on the statement of profit or loss, not the statement of financial position."}}},{"id":"P1_U5_MCQ_221","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_221","question":"What is the exact difference between 'trade receivables' and 'trade payables' on a business's statement of financial position?","options":{"A":"Trade receivables are money owed TO the business by credit customers (current asset), whereas trade payables are money owed BY the business to credit suppliers (current liability)","B":"Trade receivables are long-term loans, whereas trade payables are non-current assets","C":"Trade receivables are paid to the government, whereas trade payables are paid to shareholders","D":"Trade receivables are non-current assets, whereas trade payables are shareholders' equity"},"correctOption":"A","correctAnswer":"Trade receivables are money owed TO the business by credit customers (current asset), whereas trade payables are money owed BY the business to credit suppliers (current liability)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because trade receivables represent incoming cash owed by customers, while trade payables represent outgoing cash owed to suppliers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because both are short-term working capital items, not long-term loans or non-current assets.","C":"Incorrect because taxes and dividends are separate items from trade credit with customers and suppliers.","D":"Incorrect because trade receivables are current assets and trade payables are current liabilities."}}},{"id":"P1_U5_MCQ_222","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_222","question":"Which item appears on the statement of profit or loss, rather than on the statement of financial position?","options":{"A":"Cost of sales","B":"Trade receivables","C":"Non-current liabilities","D":"Share capital"},"correctOption":"A","correctAnswer":"Cost of sales","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cost of sales is a trading cost deducted from revenue on the statement of profit or loss, whereas the other three items sit on the statement of financial position.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because trade receivables are current assets on the statement of financial position.","C":"Incorrect because non-current liabilities appear on the statement of financial position.","D":"Incorrect because share capital is part of equity on the statement of financial position."}}},{"id":"P1_U5_MCQ_223","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_223","question":"The directors of a logistics firm want to spend $120,000 in cash to buy three new vans. Before approving the purchase, they check the statement of financial position and see cash of $130,000, inventory of $20,000, and current liabilities of $145,000. Why should the directors NOT pay $120,000 cash outright?","options":{"A":"Spending $120,000 cash would leave only $10,000 cash and $20,000 inventory to cover $145,000 of short-term debts, triggering a severe liquidity crisis","B":"Vans cannot legally be recorded as non-current assets","C":"Buying vans for cash reduces total assets to zero","D":"Current liabilities are automatically cancelled when non-current assets are bought"},"correctOption":"A","correctAnswer":"Spending $120,000 cash would leave only $10,000 cash and $20,000 inventory to cover $145,000 of short-term debts, triggering a severe liquidity crisis","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the firm barely has enough current assets ($150,000) to cover current liabilities ($145,000); draining $120,000 of cash would leave it unable to pay short-term creditors.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because delivery vans are standard non-current assets.","C":"Incorrect because buying vans converts cash (current asset) into vans (non-current asset) without reducing total assets.","D":"Incorrect because current liabilities must still be paid regardless of van purchases."}}},{"id":"P1_U5_MCQ_224","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_224","question":"A commercial bank is reviewing a hotel company's statement of financial position before deciding on a $500,000 loan application. Which detail on the statement helps the bank check if the company has sufficient assets to back the loan?","options":{"A":"The value of unmortgaged freehold hotel buildings under non-current assets","B":"The company's annual marketing expenditure","C":"The number of guests who stayed at the hotel in July","D":"The gross profit margin percentage"},"correctOption":"A","correctAnswer":"The value of unmortgaged freehold hotel buildings under non-current assets","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because non-current assets like debt-free freehold property are shown on the statement of financial position and can be used as loan collateral.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because marketing expenditure is an expense on the statement of profit or loss, not collateral.","C":"Incorrect because guest numbers are operational statistics, not on the statement of financial position.","D":"Incorrect because gross profit margin is a profitability ratio, not a physical asset for security."}}},{"id":"P1_U5_MCQ_225","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_225","question":"A retail company delays paying its suppliers until the day after its financial year-end so that its year-end cash balance looks unusually high on its published statement of financial position. What limitation of the statement of financial position does this illustrate?","options":{"A":"Because it is a snapshot taken on a single date, figures can be temporarily manipulated ('window-dressed') and may not reflect typical daily liquidity","B":"The statement of financial position never includes cash balances","C":"Supplier invoices are permanently erased if not paid before year-end","D":"Current liabilities are always excluded from published accounts"},"correctOption":"A","correctAnswer":"Because it is a snapshot taken on a single date, figures can be temporarily manipulated ('window-dressed') and may not reflect typical daily liquidity","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a single-day snapshot reflects balances only on that exact date and may not represent normal cash levels throughout the rest of the year.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cash is always listed under current assets.","C":"Incorrect because unpaid supplier invoices remain recorded as trade payables (current liabilities).","D":"Incorrect because current liabilities are a required part of the statement of financial position."}}},{"id":"P1_U5_MCQ_226","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_226","question":"Why do financial analysts calculate BOTH profitability ratios and liquidity ratios when evaluating a business's annual accounts?","options":{"A":"Because profitability ratios show how effectively the business generates profit from sales and capital, whereas liquidity ratios show whether it can pay short-term debts on time","B":"Because profitability ratios are only for sole traders and liquidity ratios are only for companies","C":"Because profitability ratios always equal liquidity ratios","D":"Because liquidity ratios measure total revenue and profitability ratios measure total liabilities"},"correctOption":"A","correctAnswer":"Because profitability ratios show how effectively the business generates profit from sales and capital, whereas liquidity ratios show whether it can pay short-term debts on time","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a business needs both long-term profitability to reward owners and short-term liquidity to survive and pay immediate bills.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because both sets of ratios are used across all types of businesses.","C":"Incorrect because profitability is expressed as a percentage and liquidity as a ratio, measuring completely different aspects of performance.","D":"Incorrect because neither set of ratios simply reports raw revenue or total liabilities."}}},{"id":"P1_U5_MCQ_227","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_227","question":"An organic food wholesaler reports annual sales revenue of $800,000, cost of sales of $520,000, and overhead expenses of $160,000. What is the wholesaler's gross profit margin?","options":{"A":"15%","B":"65%","C":"35%","D":"20%"},"correctOption":"C","correctAnswer":"35%","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Gross profit = $800,000 - $520,000 = $280,000, and Gross profit margin = ($280,000 / $800,000) × 100 = 35%.","distractor_reasons":{"A":"Incorrect because 15% is the profit margin ($120,000 / $800,000 × 100).","B":"Incorrect because 65% is cost of sales as a percentage of revenue ($520,000 / $800,000 × 100).","C":"Correct selection.","D":"Incorrect because 20% is overhead expenses as a percentage of revenue ($160,000 / $800,000 × 100)."}}},{"id":"P1_U5_MCQ_228","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_228","question":"A footwear chain's gross profit margin dropped from 44% last year to 38% this year. Which change best explains this decline?","options":{"A":"The chain offered frequent 20% 'flash sale' price discounts to clear stock while supplier shoe costs stayed the same","B":"The chain spent more on head-office IT support staff","C":"The chain repaid a long-term bank loan early","D":"The chain reduced its store advertising budget"},"correctOption":"A","correctAnswer":"The chain offered frequent 20% 'flash sale' price discounts to clear stock while supplier shoe costs stayed the same","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cutting selling prices while unit cost of sales stays unchanged shrinks the gross profit earned on every dollar of sales.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because head-office IT salaries are indirect overhead expenses deducted after gross profit.","C":"Incorrect because repaying a bank loan does not affect gross profit margin.","D":"Incorrect because advertising is an overhead expense and reducing it would increase profit margin, not lower gross profit margin."}}},{"id":"P1_U5_MCQ_229","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_229","question":"A bakery wants to raise its gross profit margin from 45% to 50%. Which action directly increases the gross profit margin?","options":{"A":"Reducing flour wastage during baking and negotiating a 5% bulk discount from flour suppliers without lowering bread prices","B":"Reducing the bakery's annual accounting audit fee","C":"Replacing a short-term overdraft with a long-term loan","D":"Selling an unused delivery van for cash"},"correctOption":"A","correctAnswer":"Reducing flour wastage during baking and negotiating a 5% bulk discount from flour suppliers without lowering bread prices","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because lowering direct ingredient costs (cost of sales) relative to selling price directly widens the gross profit margin.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because audit fees are indirect overhead expenses that affect profit margin rather than gross profit margin.","C":"Incorrect because restructuring debt affects liquidity ratios, not gross profit margin.","D":"Incorrect because selling a non-current asset affects cash flow and assets, not gross profit margin."}}},{"id":"P1_U5_MCQ_230","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_230","question":"A digital marketing agency earns annual revenue of $450,000, gross profit of $315,000, and final profit of $63,000. What is the agency's profit margin?","options":{"A":"70%","B":"14%","C":"20%","D":"56%"},"correctOption":"B","correctAnswer":"14%","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Profit margin = (Profit / Revenue) × 100 = ($63,000 / $450,000) × 100 = 14%.","distractor_reasons":{"A":"Incorrect because 70% is the gross profit margin ($315,000 / $450,000 × 100).","B":"Correct selection.","C":"Incorrect because 20% divides profit by gross profit ($63,000 / $315,000 × 100) instead of dividing by revenue.","D":"Incorrect because 56% is overhead expenses as a percentage of revenue ($252,000 / $450,000 × 100)."}}},{"id":"P1_U5_MCQ_231","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_231","question":"A hotel chain's gross profit margin remained steady at 65% over two years, while its profit margin rose from 12% to 17%. What does this improvement indicate?","options":{"A":"The hotel chain controlled its indirect overhead expenses more effectively relative to revenue","B":"The cost of food and beverages bought for guests fell by half","C":"The hotel chain's current ratio fell below 1 : 1","D":"Room prices were cut by 50%"},"correctOption":"A","correctAnswer":"The hotel chain controlled its indirect overhead expenses more effectively relative to revenue","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an unchanged gross profit margin paired with a rising profit margin proves that indirect expenses took up a smaller share of revenue.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because lower direct food/beverage costs would have increased the gross profit margin.","C":"Incorrect because profitability margins do not measure the current ratio.","D":"Incorrect because a 50% room price cut would have reduced both gross profit margin and profit margin."}}},{"id":"P1_U5_MCQ_232","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_232","question":"A courier company wants to improve its profit margin without changing customer delivery prices or driver wages. Which action would achieve this?","options":{"A":"Using route-optimisation software to cut overhead fuel and administrative office costs","B":"Issuing new ordinary shares on the stock exchange","C":"Extending customer credit terms from 30 days to 90 days","D":"Holding larger inventories of spare tires"},"correctOption":"A","correctAnswer":"Using route-optimisation software to cut overhead fuel and administrative office costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because reducing running expenses leaves a larger profit from the same revenue, directly raising the profit margin.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because issuing shares affects equity and capital employed, not profit margin.","C":"Incorrect because longer customer credit terms slow down cash flow rather than raising profit margin.","D":"Incorrect because holding extra tire inventory ties up working capital without lowering expenses."}}},{"id":"P1_U5_MCQ_233","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_233","question":"A manufacturing business generates an annual profit of $180,000, and its statement of financial position shows shareholders' equity of $750,000 and non-current liabilities of $250,000. What is the business's Return on Capital Employed (ROCE)?","options":{"A":"24%","B":"72%","C":"18%","D":"36%"},"correctOption":"C","correctAnswer":"18%","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Capital employed = Equity ($750,000) + Non-current liabilities ($250,000) = $1,000,000, and ROCE = ($180,000 / $1,000,000) × 100 = 18%.","distractor_reasons":{"A":"Incorrect because 24% divides profit only by equity ($180,000 / $750,000 × 100), omitting non-current liabilities.","B":"Incorrect because 72% divides profit only by non-current liabilities ($180,000 / $250,000 × 100).","C":"Correct selection.","D":"Incorrect because 36% divides profit by the difference between equity and debt ($180,000 / $500,000 × 100)."}}},{"id":"P1_U5_MCQ_234","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_234","question":"An entrepreneur invests $200,000 of her own savings into a retail business that earns a profit of $6,000 for the year (an ROCE of 3%), while safe government bonds pay 5% annual interest. How would a financial adviser interpret this 3% ROCE?","options":{"A":"The return on capital invested is weak because the entrepreneur is earning less than she could earn risk-free from government bonds","B":"The business has an ideal liquidity ratio","C":"The business is earning a high return because any positive ROCE is automatically successful","D":"The business has zero non-current assets"},"correctOption":"A","correctAnswer":"The return on capital invested is weak because the entrepreneur is earning less than she could earn risk-free from government bonds","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ROCE should be compared against alternative risk-free returns such as bank deposit or bond interest rates; earning 3% while taking business risk is poor compared to 5% risk-free.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because ROCE measures return on invested capital, not short-term liquidity.","C":"Incorrect because a 3% return fails to compensate for the financial risk of running a business when safe interest rates are 5%.","D":"Incorrect because ROCE does not indicate whether non-current assets are zero."}}},{"id":"P1_U5_MCQ_235","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_235","question":"A logistics company sells an underused, empty depot for $300,000 cash and uses the proceeds to pay off a $300,000 non-current bank loan, while its annual operating profit stays unchanged at $90,000. How does this affect the company's ROCE?","options":{"A":"ROCE increases because the same profit is generated using $300,000 less capital employed","B":"ROCE decreases because non-current assets fell","C":"ROCE stays completely unchanged","D":"ROCE falls to 0%"},"correctOption":"A","correctAnswer":"ROCE increases because the same profit is generated using $300,000 less capital employed","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because repaying the $300,000 non-current loan reduces capital employed (the denominator in ROCE) while profit stays constant, raising ROCE.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because reducing unproductive capital employed improves capital efficiency and raises ROCE.","C":"Incorrect because capital employed decreased by $300,000 while profit remained $90,000.","D":"Incorrect because profit is still $90,000, so ROCE remains positive and higher than before."}}},{"id":"P1_U5_MCQ_236","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_236","question":"A hardware wholesaler has inventory of $48,000, trade receivables of $32,000, cash of $10,000, trade payables of $35,000, and a bank overdraft of $15,000. What is the wholesaler's current ratio?","options":{"A":"0.84 : 1","B":"1.8 : 1","C":"0.56 : 1","D":"2.57 : 1"},"correctOption":"B","correctAnswer":"1.8 : 1","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Current assets = $48,000 + $32,000 + $10,000 = $90,000 and Current liabilities = $35,000 + $15,000 = $50,000, giving Current ratio = $90,000 / $50,000 = 1.8 : 1.","distractor_reasons":{"A":"Incorrect because 0.84 : 1 is the acid-test ratio (($90,000 - $48,000) / $50,000).","B":"Correct selection.","C":"Incorrect because 0.56 : 1 divides current liabilities by current assets ($50,000 / $90,000).","D":"Incorrect because 2.57 : 1 omits the $15,000 bank overdraft from current liabilities ($90,000 / $35,000)."}}},{"id":"P1_U5_MCQ_237","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_237","question":"Which current ratio figure generally indicates a healthy, balanced liquidity position for a typical manufacturing or trading business?","options":{"A":"0.4 : 1","B":"1.7 : 1","C":"6.5 : 1","D":"0.85 : 1"},"correctOption":"B","correctAnswer":"1.7 : 1","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a current ratio between 1.5 : 1 and 2 : 1 shows the business can comfortably cover short-term liabilities without tying up excessive unproductive funds.","distractor_reasons":{"A":"Incorrect because 0.4 : 1 means current liabilities are 2.5 times larger than current assets, signalling acute insolvency risk.","B":"Correct selection.","C":"Incorrect because 6.5 : 1 is excessively high, indicating huge amounts of idle cash, uncollected receivables, or excess inventory.","D":"Incorrect because 0.85 : 1 is below 1 : 1, meaning short-term debts exceed current assets."}}},{"id":"P1_U5_MCQ_238","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_238","question":"A furniture retailer has current assets of $160,000, which includes $95,000 of sofa and table inventory, and current liabilities of $50,000. What is the retailer's acid-test ratio?","options":{"A":"3.2 : 1","B":"1.9 : 1","C":"1.3 : 1","D":"0.77 : 1"},"correctOption":"C","correctAnswer":"1.3 : 1","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Acid-test ratio = (Current assets - Inventory) / Current liabilities = ($160,000 - $95,000) / $50,000 = $65,000 / $50,000 = 1.3 : 1.","distractor_reasons":{"A":"Incorrect because 3.2 : 1 is the current ratio ($160,000 / $50,000), which fails to deduct inventory.","B":"Incorrect because 1.9 : 1 divides inventory by current liabilities ($95,000 / $50,000).","C":"Correct selection.","D":"Incorrect because 0.77 : 1 inverts the formula ($50,000 / $65,000)."}}},{"id":"P1_U5_MCQ_239","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_239","question":"Why is the acid-test ratio considered a stricter test of a business's immediate liquidity than the current ratio?","options":{"A":"Because it excludes inventory, which cannot always be quickly converted into cash to pay urgent bills","B":"Because it includes non-current assets such as factory buildings","C":"Because it deducts long-term bank loans from cash","D":"Because it uses gross profit instead of current assets"},"correctOption":"A","correctAnswer":"Because it excludes inventory, which cannot always be quickly converted into cash to pay urgent bills","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because inventory is the least liquid current asset and may take months to sell, so removing it shows whether cash and receivables alone can pay short-term debts.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because non-current assets are excluded from both liquidity ratios.","C":"Incorrect because long-term bank loans are non-current liabilities and are excluded from both ratios.","D":"Incorrect because gross profit is a profitability figure, not used in the acid-test ratio."}}},{"id":"P1_U5_MCQ_240","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_240","question":"A winter coat retailer's current ratio is 2.8 : 1, while its acid-test ratio is 0.45 : 1. What action should the retailer take to address the issue revealed by these two ratios?","options":{"A":"Run promotions to clear excess unsold coat inventory and turn it into cash","B":"Order twice as much coat inventory on 30-day credit","C":"Use all remaining bank cash to buy a new delivery van","D":"Take out a new short-term bank overdraft to buy more stock"},"correctOption":"A","correctAnswer":"Run promotions to clear excess unsold coat inventory and turn it into cash","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the huge drop from 2.8 : 1 to 0.45 : 1 shows that almost all current assets are stuck in unsold inventory, which needs to be converted into cash.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because buying even more stock on credit would worsen overstocking and push the acid-test ratio even lower.","C":"Incorrect because spending cash on a van would reduce liquid assets even further.","D":"Incorrect because increasing an overdraft and buying more inventory would deepen the liquidity problem."}}},{"id":"P1_U5_MCQ_241","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_241","question":"A printing company has a weak current ratio of 0.85 : 1 and wants to raise it above 1.2 : 1. Which action will increase the company's current ratio?","options":{"A":"Converting a $30,000 short-term bank overdraft into a 5-year long-term bank loan","B":"Using $20,000 cash to buy a new printing press","C":"Paying $15,000 cash in dividends to shareholders","D":"Buying $10,000 of paper inventory for cash"},"correctOption":"A","correctAnswer":"Converting a $30,000 short-term bank overdraft into a 5-year long-term bank loan","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because replacing a short-term overdraft (current liability) with a 5-year loan (non-current liability) reduces current liabilities while keeping current assets unchanged, raising the current ratio.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because spending cash on a non-current asset reduces current assets and lowers the current ratio.","C":"Incorrect because paying cash dividends reduces current assets and lowers the current ratio.","D":"Incorrect because swapping cash for inventory leaves total current assets and the current ratio unchanged."}}},{"id":"P1_U5_MCQ_242","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_242","question":"A retailer currently has current assets of $80,000 (including $30,000 of inventory) and current liabilities of $50,000, giving an acid-test ratio of 1.0 : 1. If the retailer buys $10,000 of extra inventory on 30-day trade credit, what happens to its acid-test ratio?","options":{"A":"It falls from 1.0 : 1 to 0.83 : 1 because current liabilities rise by $10,000 while liquid assets (excluding inventory) stay at $50,000","B":"It rises from 1.0 : 1 to 1.2 : 1 because current assets increase","C":"It stays completely unchanged at 1.0 : 1","D":"It rises to 1.5 : 1"},"correctOption":"A","correctAnswer":"It falls from 1.0 : 1 to 0.83 : 1 because current liabilities rise by $10,000 while liquid assets (excluding inventory) stay at $50,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because liquid assets (Current assets - Inventory) stay at $50,000, while current liabilities rise from $50,000 to $60,000, reducing the acid-test ratio to $50,000 / $60,000 = 0.83 : 1.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the $10,000 increase in current assets is inventory, which is excluded from the acid-test numerator.","C":"Incorrect because current liabilities increase while the numerator does not.","D":"Incorrect because buying inventory on credit weakens rather than improves the acid-test ratio."}}},{"id":"P1_U5_MCQ_243","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_243","question":"Which stakeholder group is an INTERNAL user of a company's financial accounts and ratios?","options":{"A":"Senior managers and department heads","B":"Commercial bank loan officers","C":"Government tax authorities","D":"External raw material suppliers"},"correctOption":"A","correctAnswer":"Senior managers and department heads","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because managers work inside the business and use accounting ratios to monitor efficiency, control costs, and make daily strategic decisions.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because commercial banks are external lenders.","C":"Incorrect because government tax authorities are external regulators.","D":"Incorrect because suppliers are external trade creditors."}}},{"id":"P1_U5_MCQ_244","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_244","question":"A potential investor is comparing two public limited companies in the same sector, Alpha plc (ROCE 19%, profit margin 14%) and Beta plc (ROCE 8%, profit margin 6%), before buying shares. How does this ratio analysis help the investor?","options":{"A":"It shows that Alpha plc generates a much higher return on capital and sales, indicating stronger dividend and share-price growth potential","B":"It guarantees that Alpha plc will never face a cash flow deficit","C":"It proves that Beta plc has higher current assets than Alpha plc","D":"It allows the investor to set Alpha plc's employee wages"},"correctOption":"A","correctAnswer":"It shows that Alpha plc generates a much higher return on capital and sales, indicating stronger dividend and share-price growth potential","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because external investors compare profitability ratios across rival firms to identify which company uses capital more effectively to reward shareholders.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because profitability ratios do not measure cash liquidity.","C":"Incorrect because ROCE and profit margin do not indicate the size of current assets.","D":"Incorrect because ordinary shareholders do not set operational employee wages."}}},{"id":"P1_U5_MCQ_245","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_245","question":"Before approving a $400,000 expansion loan for a food manufacturer, a bank manager inspects the manufacturer's current ratio, acid-test ratio, and existing non-current liabilities. Why are these specific figures most important to the bank?","options":{"A":"They show whether the manufacturer already carries heavy debt and whether it has enough liquid assets to pay interest and loan instalments on time","B":"They tell the bank what flavours of food the manufacturer should launch next","C":"They determine how many shares the bank will receive instead of interest","D":"They show the exact customer satisfaction score of the manufacturer"},"correctOption":"A","correctAnswer":"They show whether the manufacturer already carries heavy debt and whether it has enough liquid assets to pay interest and loan instalments on time","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because lenders focus on default risk, assessing existing debt commitments and short-term liquidity to ensure timely repayment.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because product development decisions are made by the manufacturer's marketing team.","C":"Incorrect because banks earn interest on loans rather than receiving shares.","D":"Incorrect because customer satisfaction is a non-financial metric not shown in liquidity ratios."}}},{"id":"P1_U5_MCQ_246","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_246","question":"A timber wholesaler is asked by a furniture maker to supply $25,000 of wood on 60-day trade credit. After checking the furniture maker's accounts and finding an acid-test ratio of 0.35 : 1, what decision is the wholesaler most likely to make?","options":{"A":"Refuse 60-day trade credit and insist on cash on delivery because the furniture maker lacks liquid assets to pay short-term bills","B":"Offer 180 days of interest-free trade credit immediately","C":"Buy shares in the furniture maker to increase its ROCE","D":"Ignore the acid-test ratio because suppliers never care when they get paid"},"correctOption":"A","correctAnswer":"Refuse 60-day trade credit and insist on cash on delivery because the furniture maker lacks liquid assets to pay short-term bills","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an acid-test ratio of 0.35 : 1 signals severe short-term liquidity weakness, warning suppliers that invoices may go unpaid.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because extending longer credit to a cash-strapped customer increases bad-debt risk.","C":"Incorrect because a timber supplier wants prompt payment for goods, not equity ownership in a struggling customer.","D":"Incorrect because suppliers depend on timely invoice payments to manage their own cash flow."}}},{"id":"P1_U5_MCQ_247","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_247","question":"Why do employees and trade unions examine a company's published statement of profit or loss and statement of financial position?","options":{"A":"To assess whether the business is profitable and financially secure enough to protect jobs and fund pay rises","B":"To calculate the exact amount of corporation tax owed to the government","C":"To decide whether to grant the company a 15-year mortgage","D":"To value the company's inventory for resale"},"correctOption":"A","correctAnswer":"To assess whether the business is profitable and financially secure enough to protect jobs and fund pay rises","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because workers rely on the business for employment and income, so strong profits and liquidity support job security and wage claims.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because tax assessment is conducted by government tax authorities.","C":"Incorrect because mortgages are provided by banks and lenders.","D":"Incorrect because inventory valuation is performed by accountants and auditors."}}},{"id":"P1_U5_MCQ_248","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_248","question":"Aside from tax authorities, which external group studies a rival company's published gross profit margin, profit margin, and ROCE to benchmark its own performance?","options":{"A":"Competitors in the same industry","B":"Local primary school students","C":"Internal factory supervisors","D":"The company's own board of directors"},"correctOption":"A","correctAnswer":"Competitors in the same industry","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because rival firms analyse published accounts of competitors to compare profit margins, efficiency, and financial strength.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because primary school students are not business stakeholders analysing industry benchmarks.","C":"Incorrect because internal supervisors work inside the company rather than being external competitors.","D":"Incorrect because the board of directors is internal to the company."}}},{"id":"P1_U5_MCQ_249","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_249","question":"When comparing a company's profit margin and ROCE from 2016 with its ratios in 2026, why can high inflation over that ten-year period make comparisons misleading?","options":{"A":"Inflation pushes up current sales revenues and profits in nominal dollar terms while older non-current assets remain recorded at lower historical purchase prices","B":"Inflation makes it illegal to calculate percentages over more than two years","C":"Inflation removes all current liabilities from the statement of financial position","D":"Inflation automatically forces gross profit margins to equal 100%"},"correctOption":"A","correctAnswer":"Inflation pushes up current sales revenues and profits in nominal dollar terms while older non-current assets remain recorded at lower historical purchase prices","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because inflation inflates current prices and profits relative to historical asset book values, artificially boosting ROCE over long time spans.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because multi-year ratio analysis is completely legal and common.","C":"Incorrect because current liabilities remain on the statement of financial position regardless of inflation.","D":"Incorrect because inflation raises both costs and revenues rather than making gross profit margin 100%."}}},{"id":"P1_U5_MCQ_250","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_250","question":"A company reports an impressive ROCE of 22% and a profit margin of 16%, but published accounts provide no details on its high staff turnover, polluting factory emissions, or falling customer loyalty scores. Which major limitation of accounting ratios does this illustrate?","options":{"A":"Financial accounts only measure quantitative historical numbers and ignore crucial qualitative non-financial factors that threaten long-term success","B":"Published accounts are forbidden from reporting profit margins above 10%","C":"Ratios only use forecast numbers from future years rather than real data","D":"ROCE and profit margin cannot be calculated for manufacturing companies"},"correctOption":"A","correctAnswer":"Financial accounts only measure quantitative historical numbers and ignore crucial qualitative non-financial factors that threaten long-term success","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ratio analysis relies exclusively on historical financial figures and overlooks qualitative factors like workforce morale, environmental impact, and brand reputation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because there is no legal cap on reported profit margins.","C":"Incorrect because published financial ratios are calculated from historical past accounts, not future forecasts.","D":"Incorrect because ROCE and profit margin are routinely calculated for manufacturing firms."}}},{"id":"P1_U5_MCQ_251","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_251","question":"Two software engineers are leaving their jobs to form a private limited company developing educational games. They need $40,000 to register the company, buy high-specification computers, and rent an office before releasing their first game. What type of finance do they need?","options":{"A":"Working capital","B":"Start-up capital","C":"Trade credit","D":"Debt factoring"},"correctOption":"B","correctAnswer":"Start-up capital","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because start-up capital is the finance required by entrepreneurs to pay for initial set-up costs and essential non-current assets before a new business starts trading.","distractor_reasons":{"A":"Incorrect because working capital covers ongoing day-to-day running expenses once trading is underway.","B":"Correct selection.","C":"Incorrect because trade credit is delayed payment on inventory purchased from suppliers.","D":"Incorrect because debt factoring sells unpaid customer invoices for immediate cash."}}},{"id":"P1_U5_MCQ_252","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_252","question":"A thriving regional supermarket chain plans to buy out a smaller competitor with 12 stores and build a new automated cold-storage hub. Which financial need is driving this capital requirement?","options":{"A":"Funding long-term business expansion","B":"Paying weekly cashier wages","C":"Covering a three-day bank timing gap","D":"Replacing a broken checkout scanner"},"correctOption":"A","correctAnswer":"Funding long-term business expansion","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because acquiring rival businesses and building major distribution facilities require substantial long-term expansion capital.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because weekly wages are short-term working capital expenses.","C":"Incorrect because a three-day cash gap is a temporary working capital timing issue.","D":"Incorrect because replacing a single scanner is minor routine equipment maintenance."}}},{"id":"P1_U5_MCQ_253","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_253","question":"A busy print shop has plenty of profitable orders from corporate clients, but it lacks cash to buy paper rolls and pay electricity bills because clients take 45 days to pay. Which financial need does this highlight?","options":{"A":"Start-up capital for premises","B":"Long-term capital for international takeovers","C":"Working capital for day-to-day trading operations","D":"Capital for buying freehold land"},"correctOption":"C","correctAnswer":"Working capital for day-to-day trading operations","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because working capital is needed to pay routine running costs such as raw materials and utility bills while waiting for credit customers to pay.","distractor_reasons":{"A":"Incorrect because the print shop is already an established trading business.","B":"Incorrect because international takeovers require long-term expansion finance, not money for paper and electricity.","C":"Correct selection.","D":"Incorrect because freehold land is a long-term non-current asset."}}},{"id":"P1_U5_MCQ_254","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_254","question":"A profitable food-packaging company has accumulated $350,000 in retained profit over the last four years and uses $280,000 of it to buy a new automated laminating machine. What is a major advantage of using retained profit for this purchase?","options":{"A":"It does not have to be repaid and incurs zero interest charges","B":"It increases the company's non-current liabilities","C":"It gives the company's bank a share of future profits","D":"It guarantees lower corporation tax next year"},"correctOption":"A","correctAnswer":"It does not have to be repaid and incurs zero interest charges","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because retained profit is an internal source of finance that carries no interest payments, arrangement fees, or repayment deadlines.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because using internal retained profit creates no external loan debt.","C":"Incorrect because retained profit comes from inside the business without involving a bank.","D":"Incorrect because funding machinery from retained profit does not automatically lower tax rates."}}},{"id":"P1_U5_MCQ_255","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_255","question":"A haulage company upgrades its fleet and sells four older trucks that are no longer needed, raising $68,000 in cash to help pay for a new warehouse loading bay. Which type of finance is this?","options":{"A":"External short-term finance","B":"Internal finance from the sale of unwanted assets","C":"External equity finance","D":"Working capital reduction"},"correctOption":"B","correctAnswer":"Internal finance from the sale of unwanted assets","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because selling surplus non-current assets such as old trucks generates cash internally without borrowing or issuing shares.","distractor_reasons":{"A":"Incorrect because the cash comes from selling the company's own assets rather than external borrowing.","B":"Correct selection.","C":"Incorrect because no shares were issued to external investors.","D":"Incorrect because trucks are non-current assets, whereas working capital relates to current assets like inventory."}}},{"id":"P1_U5_MCQ_256","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_256","question":"A home-appliance wholesaler needs $45,000 to pay for a software upgrade and decides to raise the cash internally by tightening credit collection from retail stores and holding smaller warehouse stocks of washing machines. Which internal source of finance is being used?","options":{"A":"Sale of non-current assets","B":"Retained profit","C":"Owners' personal savings","D":"Reducing working capital"},"correctOption":"D","correctAnswer":"Reducing working capital","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because converting trade receivables and excess inventory into cash frees up funds tied up in working capital.","distractor_reasons":{"A":"Incorrect because washing machine inventory is a current asset, not a non-current asset.","B":"Incorrect because retained profit comes from past profits rather than releasing cash from inventory and receivables.","C":"Incorrect because the owners did not inject new personal money into the business.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_257","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_257","question":"A sole trader running a mobile car-valeting van needs $8,000 to buy a second van and decides to invest $8,000 from her personal savings account. What is a common limitation of relying on owners' investment as a source of finance?","options":{"A":"The owner must pay high monthly interest to the bank","B":"The amount of personal savings available to owners is often limited","C":"The sole trader loses decision-making control to external investors","D":"Personal savings can only be used to pay utility bills"},"correctOption":"B","correctAnswer":"The amount of personal savings available to owners is often limited","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because individual owners usually have limited personal wealth, restricting how much finance can be raised internally for major expansion.","distractor_reasons":{"A":"Incorrect because owners' investment is internal and incurs no interest charges.","B":"Correct selection.","C":"Incorrect because investing personal savings keeps 100% control with the sole trader.","D":"Incorrect because owners' investment can be used for any business purpose, including buying vehicles."}}},{"id":"P1_U5_MCQ_258","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_258","question":"A large public limited supermarket group wants to raise $60 million to build a national automated distribution network without taking on any new debt. Why is issuing new ordinary shares on the stock exchange suitable for this goal?","options":{"A":"It can raise very large sums of permanent capital with no repayment date and no contractual interest charges","B":"It guarantees that existing shareholders retain the exact same percentage of voting control","C":"It requires zero legal fees or administrative paperwork","D":"It allows the company to avoid publishing annual financial statements"},"correctOption":"A","correctAnswer":"It can raise very large sums of permanent capital with no repayment date and no contractual interest charges","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because public share issues allow plcs to raise substantial long-term funds permanently without fixed interest obligations.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because issuing new shares to the public dilutes the ownership percentage of existing shareholders.","C":"Incorrect because a public share issue is costly and requires extensive legal and regulatory compliance.","D":"Incorrect because all public limited companies must publish audited annual accounts."}}},{"id":"P1_U5_MCQ_259","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_259","question":"Why is a private limited company (Ltd) unable to raise finance by selling shares to the general public on a stock exchange?","options":{"A":"Private limited companies are legally restricted to selling shares privately with the agreement of existing shareholders","B":"Private limited companies have unlimited liability","C":"Private limited companies are not permitted to make a profit","D":"Private limited companies can only use internal sources of finance"},"correctOption":"A","correctAnswer":"Private limited companies are legally restricted to selling shares privately with the agreement of existing shareholders","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because legal restrictions prevent private limited companies from offering shares to the public; only public limited companies (plcs) can list on a stock exchange.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because shareholders in both private and public limited companies have limited liability.","C":"Incorrect because private limited companies are private sector profit-seeking businesses.","D":"Incorrect because private limited companies can use external debt, leasing, grants, and private share issues."}}},{"id":"P1_U5_MCQ_260","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_260","question":"A restaurant group borrows $200,000 from a bank to refurbish four restaurants, agreeing to repay the amount in fixed monthly instalments over six years. What is a potential disadvantage of this bank loan?","options":{"A":"Interest must be paid regularly regardless of whether the restaurants make a profit, and collateral is usually required","B":"The bank becomes a 50% owner of the restaurant group","C":"The loan must be repaid in full within 30 days","D":"The restaurant group cannot claim loan interest as a business expense"},"correctOption":"A","correctAnswer":"Interest must be paid regularly regardless of whether the restaurants make a profit, and collateral is usually required","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because bank loans impose mandatory interest and repayment commitments even during weak trading periods, and banks typically require assets as security.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because lenders do not take equity ownership when granting a loan.","C":"Incorrect because a six-year bank loan is repaid over six years, unlike an on-demand overdraft.","D":"Incorrect because interest paid is a legitimate business expense."}}},{"id":"P1_U5_MCQ_261","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_261","question":"A florist faces fluctuating weekly cash balances, occasionally dipping -$1,500 into the negative for ten days before corporate clients pay their monthly bills. Why is a bank overdraft better suited than a bank loan for this situation?","options":{"A":"An overdraft is flexible, allowing the florist to borrow only when needed and pay interest only for the ten days overdrawn","B":"An overdraft has a lower interest rate than a secured mortgage","C":"An overdraft never has to be repaid","D":"An overdraft is recorded as a non-current asset"},"correctOption":"A","correctAnswer":"An overdraft is flexible, allowing the florist to borrow only when needed and pay interest only for the ten days overdrawn","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an overdraft is tailored to short-term, fluctuating working capital gaps and charges interest strictly on the daily overdrawn amount.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because overdraft interest rates are normally higher than secured long-term loan rates.","C":"Incorrect because an overdraft is a repayable short-term liability.","D":"Incorrect because an overdrawn bank balance is a current liability."}}},{"id":"P1_U5_MCQ_262","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_262","question":"A hardware store buys $15,000 of paint and tools from a wholesaler with 45 days to pay the invoice. How does this trade credit benefit the hardware store?","options":{"A":"It acts as a short-term, usually interest-free source of finance that lets the store sell the goods before paying the supplier","B":"It permanently reduces the store's cost of sales to zero","C":"It allows the store to buy freehold shop premises on 10-year terms","D":"It increases the store's shareholders' equity"},"correctOption":"A","correctAnswer":"It acts as a short-term, usually interest-free source of finance that lets the store sell the goods before paying the supplier","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because trade credit delays cash outflows for inventory, giving the retailer time to generate cash from sales first.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the goods must still be paid for after 45 days, so cost of sales is unchanged.","C":"Incorrect because trade credit applies only to short-term purchases of raw materials or goods for resale.","D":"Incorrect because trade credit creates a current liability (trade payable), not equity."}}},{"id":"P1_U5_MCQ_263","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_263","question":"An accounting firm needs 40 new desktop computers and chooses to lease them for three years rather than buying them outright. What happens to the computers at the end of the 3-year lease agreement?","options":{"A":"They remain the property of the leasing company, and the firm can return them or upgrade to newer models","B":"They automatically become the permanent legal property of the accounting firm","C":"They are transferred to the government as tax payment","D":"They are recorded as trade receivables on the firm's accounts"},"correctOption":"A","correctAnswer":"They remain the property of the leasing company, and the firm can return them or upgrade to newer models","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because under a lease, legal ownership never transfers to the user; the leasing company owns the asset and often replaces it with updated equipment at renewal.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because transfer of ownership upon final payment is a feature of hire purchase, not leasing.","C":"Incorrect because leased assets belong to the finance/leasing company.","D":"Incorrect because trade receivables represent money owed by customers."}}},{"id":"P1_U5_MCQ_264","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_264","question":"A farmer acquires a $70,000 tractor through a hire purchase agreement over five years. What is a disadvantage of using hire purchase compared with buying the tractor outright with retained profit?","options":{"A":"Total payments over five years will exceed $70,000 because interest charges are added to the instalments","B":"The farmer never gains legal ownership of the tractor even after paying all instalments","C":"Hire purchase requires giving up voting shares in the farm","D":"The farmer cannot use the tractor until the final instalment is paid"},"correctOption":"A","correctAnswer":"Total payments over five years will exceed $70,000 because interest charges are added to the instalments","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because hire purchase includes finance/interest charges in the regular instalments, making the total cost higher than paying cash upfront.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because under hire purchase, legal ownership passes to the buyer once the final payment is completed.","C":"Incorrect because hire purchase is asset-backed instalment credit, not equity finance.","D":"Incorrect because the buyer uses the asset immediately upon paying the initial deposit."}}},{"id":"P1_U5_MCQ_265","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_265","question":"A small group of female artisans in a developing rural town needs $600 to buy looms and natural dyes to start a weaving cooperative, but commercial banks reject their application due to lack of collateral. Which source of finance is designed specifically for this situation?","options":{"A":"Microfinance","B":"Issuing ordinary shares on a stock exchange","C":"Venture capital","D":"Commercial trade credit"},"correctOption":"A","correctAnswer":"Microfinance","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because microfinance provides small loans to low-income entrepreneurs who lack collateral and cannot access traditional commercial banks.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because stock exchange listings are only for large public limited companies.","C":"Incorrect because venture capitalists invest large sums into high-growth scalable firms.","D":"Incorrect because new rural cooperatives without a trading record rarely qualify for supplier trade credit."}}},{"id":"P1_U5_MCQ_266","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_266","question":"An inventor designs a smart water bottle and raises $45,000 online from 900 individuals who each contribute $50 in advance to receive one of the first bottles produced. What is a potential disadvantage of using crowdfunding in this way?","options":{"A":"Publishing the product design online before launch may allow competitors to copy the idea, and if the funding target is missed, no money may be received","B":"The inventor must pay 25% monthly interest to a commercial bank","C":"Crowdfunding is illegal for start-up businesses","D":"The inventor must immediately repay all $45,000 in cash within seven days"},"correctOption":"A","correctAnswer":"Publishing the product design online before launch may allow competitors to copy the idea, and if the funding target is missed, no money may be received","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because crowdfunding exposes innovative concepts publicly before patenting/launch and carries the risk of failing to reach the campaign target.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because reward-based crowdfunding does not involve commercial bank interest.","C":"Incorrect because crowdfunding is a widely used legal funding method for start-ups.","D":"Incorrect because backers receive the promised product reward rather than cash repayment."}}},{"id":"P1_U5_MCQ_267","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_267","question":"A promising clean-tech private limited company has developed a new battery recycling process and receives $2 million from a venture capital firm. Why might the founders hesitate before accepting venture capital?","options":{"A":"Venture capitalists demand a significant share of ownership and influence over major business decisions","B":"Venture capitalists require the company to repay the $2 million within 30 days","C":"Venture capitalists provide zero business advice or industry contacts","D":"Venture capital can only be used to buy office stationery"},"correctOption":"A","correctAnswer":"Venture capitalists demand a significant share of ownership and influence over major business decisions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because venture capitalists invest in return for an equity stake and board influence, meaning founders give up partial ownership and autonomy.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because venture capital is long-term equity investment rather than a 30-day loan.","C":"Incorrect because providing specialist expertise and contacts is actually an advantage of venture capital.","D":"Incorrect because venture capital funds major growth, R&D, and expansion."}}},{"id":"P1_U5_MCQ_268","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_268","question":"An automotive components manufacturer builds a new research centre in a high-unemployment region and receives a $150,000 government grant. Why is a government grant attractive compared with a bank loan?","options":{"A":"It does not need to be repaid and incurs no interest, provided the manufacturer meets the grant's job-creation conditions","B":"It is guaranteed to be approved within 24 hours for every applicant","C":"It has no conditions attached and can be spent on executive bonuses","D":"It gives the government permanent ownership of the factory"},"correctOption":"A","correctAnswer":"It does not need to be repaid and incurs no interest, provided the manufacturer meets the grant's job-creation conditions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because government grants are non-repayable subsidies designed to encourage regional investment, training, or innovation when specific criteria are met.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because grant applications are competitive and often involve lengthy approval processes.","C":"Incorrect because grants have strict conditions on how the money is spent.","D":"Incorrect because grants do not transfer private business ownership to the state."}}},{"id":"P1_U5_MCQ_269","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_269","question":"A bakery needs $3,000 to pay flour suppliers this week and $180,000 to buy an adjacent shop unit for long-term expansion. Which pairing correctly matches the time period and source of finance for these two needs?","options":{"A":"Overdraft or trade credit for the $3,000; long-term bank loan or retained profit for the $180,000","B":"Issuing shares on the stock exchange for the $3,000; 30-day trade credit for the $180,000","C":"15-year mortgage for the $3,000; bank overdraft for the $180,000","D":"Hire purchase for the $3,000; microfinance for the $180,000"},"correctOption":"A","correctAnswer":"Overdraft or trade credit for the $3,000; long-term bank loan or retained profit for the $180,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because short-term working capital ($3,000) should be funded by short-term sources (overdraft/trade credit), while a long-term property purchase ($180,000) requires long-term finance.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because share issues are for massive long-term sums and trade credit cannot buy property.","C":"Incorrect because this reverses short-term and long-term finance matching.","D":"Incorrect because hire purchase is for physical equipment and microfinance provides very small loans."}}},{"id":"P1_U5_MCQ_270","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_270","question":"A profitable private limited company wants to raise $400,000 to open a second factory. The founders refuse to dilute their family ownership, and the company currently has zero bank loans. Which factor most strongly guides them toward a long-term bank loan rather than selling shares to venture capitalists?","options":{"A":"Maintaining ownership control combined with low existing gearing (debt)","B":"Legal prohibition against private limited companies having shareholders","C":"A desire to pay zero interest on borrowed money","D":"The fact that factories are short-term current assets"},"correctOption":"A","correctAnswer":"Maintaining ownership control combined with low existing gearing (debt)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a bank loan preserves 100% family voting control, and having zero existing debt means the firm can comfortably manage loan repayments.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because private limited companies do have shareholders.","C":"Incorrect because bank loans charge interest; retained profit would be used if avoiding interest were the sole priority.","D":"Incorrect because factories are long-term non-current assets."}}},{"id":"P1_U5_MCQ_271","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_271","question":"A small partnership running two dental surgeries wants to raise $90,000 for new X-ray equipment. Why is issuing shares on a stock exchange NOT an option for this business?","options":{"A":"Legal form: partnerships are unincorporated and cannot issue shares","B":"Dental equipment cannot be financed using external sources","C":"Partnerships are legally required to use only microfinance","D":"Stock exchanges only lend money for 30 days"},"correctOption":"A","correctAnswer":"Legal form: partnerships are unincorporated and cannot issue shares","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a business's legal structure determines its finance options; only incorporated public limited companies can offer shares on a stock exchange.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because dental surgeries can use bank loans, leasing, or hire purchase.","C":"Incorrect because partnerships have access to standard commercial bank finance.","D":"Incorrect because share capital raised on a stock exchange is permanent long-term finance."}}},{"id":"P1_U5_MCQ_272","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_272","question":"A construction company already has $1.2 million in bank loans and pays high monthly interest. When seeking $300,000 for new project equipment, why would banks likely reject another loan application?","options":{"A":"High existing debt (high gearing) increases the risk that the company will default on interest and loan repayments if construction demand slows","B":"Construction companies are banned from borrowing more than $1 million by law","C":"Banks prefer lending to companies that already struggle to pay existing interest","D":"Equipment purchases can only be funded through crowdfunding"},"correctOption":"A","correctAnswer":"High existing debt (high gearing) increases the risk that the company will default on interest and loan repayments if construction demand slows","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because existing loans are a crucial factor; heavy existing debt raises financial risk for lenders and makes further borrowing difficult or very expensive.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because there is no statutory $1 million borrowing cap.","C":"Incorrect because banks avoid high-risk borrowers with heavy debt burdens.","D":"Incorrect because equipment can be funded via leasing, hire purchase, retained profit, or equity."}}},{"id":"P1_U5_MCQ_273","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_273","question":"A tech start-up needs $5,000 for an urgent server upgrade. Why would the finance manager choose a bank overdraft or retained profit over a public share issue?","options":{"A":"The amount needed is too small to justify the high legal, administrative, and underwriting costs of issuing shares","B":"Tech companies are not allowed to have shareholders","C":"Overdrafts never incur any interest charges","D":"Server upgrades are paid for by government tax refunds"},"correctOption":"A","correctAnswer":"The amount needed is too small to justify the high legal, administrative, and underwriting costs of issuing shares","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the amount required ($5,000) is a key factor; issuing shares is slow and expensive and only worthwhile for raising large sums.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because incorporated tech companies do have shareholders.","C":"Incorrect because overdrafts do charge interest on overdrawn balances.","D":"Incorrect because businesses pay for their own IT upgrades."}}},{"id":"P1_U5_MCQ_274","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_274","question":"Which list contains ONLY external sources of finance?","options":{"A":"Bank loan, trade credit, leasing, and venture capital","B":"Retained profit, bank loan, sale of unwanted assets, and overdraft","C":"Owners' savings, retained profit, and reducing inventory","D":"Sale of surplus land, hire purchase, and government grant"},"correctOption":"A","correctAnswer":"Bank loan, trade credit, leasing, and venture capital","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because bank loans, trade credit, leasing, and venture capital all obtain funds from outside the business.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because retained profit and sale of unwanted assets are internal sources.","C":"Incorrect because owners' savings, retained profit, and reducing inventory are all internal sources.","D":"Incorrect because selling surplus land is an internal source of finance."}}},{"id":"P1_U5_MCQ_275","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_275","question":"A logistics company raises $320,000 to build a new depot: $110,000 from retained profit, $30,000 from selling old forklifts, $140,000 from a 7-year bank loan, and $40,000 from a regional development grant. How much finance was raised from internal sources?","options":{"A":"$140,000","B":"$180,000","C":"$110,000","D":"$320,000"},"correctOption":"A","correctAnswer":"$140,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because internal sources are retained profit ($110,000) plus the sale of old forklifts ($30,000) = $140,000 (while the loan and grant are external).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $180,000 is the sum of the external sources ($140,000 bank loan + $40,000 grant).","C":"Incorrect because $110,000 omits the $30,000 raised from selling old forklifts.","D":"Incorrect because $320,000 is the total of all internal and external finance combined."}}},{"id":"P1_U5_MCQ_276","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_276","question":"A newly launched furniture maker has full order books and high projected profits, yet it goes bankrupt in Month 4 because it cannot pay carpenters' weekly wages or timber bills. What does this illustrate?","options":{"A":"Cash is essential to pay day-to-day obligations as they fall due; lack of cash causes insolvency even in profitable firms","B":"Profitable businesses never need to monitor their bank balances","C":"Wages and timber can be paid using unpaid customer invoices","D":"High profit automatically prevents any cash outflows"},"correctOption":"A","correctAnswer":"Cash is essential to pay day-to-day obligations as they fall due; lack of cash causes insolvency even in profitable firms","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because businesses must hold enough liquid cash to pay immediate bills like wages and suppliers; without cash, a business cannot continue operating.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because profitable firms frequently suffer cash crises if credit customers pay slowly.","C":"Incorrect because employees and suppliers require payment in cash, not uncollected receivables.","D":"Incorrect because producing goods requires immediate cash outflows for labour and materials."}}},{"id":"P1_U5_MCQ_277","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_277","question":"What is the main purpose of preparing a cash flow forecast before starting a new business?","options":{"A":"To estimate future monthly cash inflows and outflows so potential cash shortages can be spotted early and financing arranged","B":"To calculate the historical corporation tax paid over the last five years","C":"To record the exact resale value of all non-current assets at year-end","D":"To replace the legal requirement to keep sales receipts"},"correctOption":"A","correctAnswer":"To estimate future monthly cash inflows and outflows so potential cash shortages can be spotted early and financing arranged","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a cash flow forecast predicts expected cash receipts and payments month by month, helping founders and banks plan overdrafts or loans before deficits occur.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a start-up has no historical tax records and a forecast looks forward.","C":"Incorrect because assets at a point in time are shown on a statement of financial position.","D":"Incorrect because businesses must still keep accurate accounting records of all transactions."}}},{"id":"P1_U5_MCQ_278","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_278","question":"During July, a sports equipment shop makes $18,000 in cash sales, sells $12,000 of goods to schools on 30-day credit, collects $9,500 from June credit customers, and pays $14,000 for rent and wages. What are the shop's total cash inflows in July?","options":{"A":"$27,500","B":"$30,000","C":"$39,500","D":"$13,500"},"correctOption":"A","correctAnswer":"$27,500","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because July cash inflows include actual cash received in July: $18,000 cash sales + $9,500 collected from June credit customers = $27,500 (July credit sales arrive in August).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $30,000 adds July cash sales and July unpaid credit sales ($18,000 + $12,000).","C":"Incorrect because $39,500 wrongly includes the $12,000 unpaid July credit sales.","D":"Incorrect because $13,500 is net cash flow ($27,500 inflows - $14,000 outflows), not total cash inflows."}}},{"id":"P1_U5_MCQ_279","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_279","question":"In August, a bakery pays $7,200 in wages, pays $3,800 to flour suppliers for July's credit delivery, orders $4,500 of sugar on 30-day trade credit, and pays $1,500 in electricity bills. What are the bakery's total cash outflows in August?","options":{"A":"$12,500","B":"$17,000","C":"$13,200","D":"$8,700"},"correctOption":"A","correctAnswer":"$12,500","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because August cash outflows include actual cash payments made in August: $7,200 wages + $3,800 paid for July flour + $1,500 electricity = $12,500 (August's sugar order is paid in September).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $17,000 wrongly includes the $4,500 sugar ordered on 30-day credit.","C":"Incorrect because $13,200 uses August's $4,500 credit order instead of July's $3,800 invoice paid in August.","D":"Incorrect because $8,700 omits the $3,800 payment to flour suppliers."}}},{"id":"P1_U5_MCQ_280","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_280","question":"A wholesale distributor sells $50,000 of goods in March and $60,000 in April. Customers pay 40% in cash immediately and 60% one month later. What is the distributor's total cash inflow from sales in April?","options":{"A":"$54,000","B":"$60,000","C":"$24,000","D":"$56,000"},"correctOption":"A","correctAnswer":"$54,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because April cash inflows consist of 40% of April sales paid immediately ($24,000) plus 60% of March sales collected one month later ($30,000) = $54,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $60,000 is total April sales revenue, 60% of which is collected in May.","C":"Incorrect because $24,000 only counts April immediate cash sales and ignores March credit receipts.","D":"Incorrect because $56,000 reverses the percentages (60% of April + 40% of March)."}}},{"id":"P1_U5_MCQ_281","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_281","question":"In October, a garden centre forecasts total cash inflows of $33,400 and total cash outflows of $29,150, with an opening balance of $4,000. What is the forecast net cash flow for October?","options":{"A":"$4,250","B":"$8,250","C":"-$4,250","D":"$62,550"},"correctOption":"A","correctAnswer":"$4,250","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Net cash flow = Cash inflows - Cash outflows ($33,400 - $29,150 = $4,250).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $8,250 is the closing balance ($4,000 opening + $4,250 net cash flow), not the net cash flow.","C":"Incorrect because inflows exceed outflows, making net cash flow positive.","D":"Incorrect because $62,550 adds inflows and outflows together."}}},{"id":"P1_U5_MCQ_282","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_282","question":"A boutique hotel starts May with an opening cash balance of $7,500. During May, total cash inflows are $41,000 and total cash outflows are $44,800. What is the hotel's closing cash balance at the end of May?","options":{"A":"$3,700","B":"-$3,800","C":"$11,300","D":"-$3,700"},"correctOption":"A","correctAnswer":"$3,700","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because May net cash flow = $41,000 - $44,800 = -$3,800, and Closing balance = Opening balance + Net cash flow ($7,500 + (-$3,800) = $3,700).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because -$3,800 is the net cash flow and ignores the $7,500 opening balance.","C":"Incorrect because $11,300 adds the $3,800 deficit instead of subtracting it.","D":"Incorrect because $7,500 - $3,800 leaves a positive balance of +$3,700."}}},{"id":"P1_U5_MCQ_283","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_283","question":"A courier firm starts March with an overdrawn opening balance of -$1,900. During March, cash inflows are $26,500 and cash outflows are $23,800. What is the firm's closing cash balance at the end of March?","options":{"A":"$800","B":"$2,700","C":"$4,600","D":"-$4,600"},"correctOption":"A","correctAnswer":"$800","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because March net cash flow = $26,500 - $23,800 = +$2,700, and adding this to the -$1,900 overdrawn opening balance gives a positive closing balance of $800.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $2,700 is the net cash flow and ignores the -$1,900 opening overdraft.","C":"Incorrect because $4,600 treats the -$1,900 overdraft as a positive opening balance (+$1,900 + $2,700).","D":"Incorrect because -$4,600 subtracts the positive net cash flow from -$1,900."}}},{"id":"P1_U5_MCQ_284","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_284","question":"A café has an opening cash balance of $2,000 in June. In June, cash inflows are $15,000 and cash outflows are $16,500. In July, cash inflows are $18,000 and cash outflows are $14,200. What is the café's closing cash balance at the end of July?","options":{"A":"$4,300","B":"$500","C":"$3,800","D":"$7,300"},"correctOption":"A","correctAnswer":"$4,300","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because June closing balance = $2,000 + ($15,000 - $16,500) = $500, which becomes July's opening balance; July closing balance = $500 + ($18,000 - $14,200) = $4,300.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $500 is June's closing balance (July's opening balance), not July's closing balance.","C":"Incorrect because $3,800 is July's net cash flow alone and ignores the $500 opening balance.","D":"Incorrect because $7,300 adds June's $1,500 deficit instead of subtracting it."}}},{"id":"P1_U5_MCQ_285","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_285","question":"A clothing store forecasts September inflows of $30,000, outflows of $27,000, and an opening balance of $1,500. If an unexpected repair bill increases September outflows by 20%, what will the new September closing balance be?","options":{"A":"-$900","B":"$4,500","C":"-$2,400","D":"$9,900"},"correctOption":"A","correctAnswer":"-$900","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a 20% rise increases outflows from $27,000 to $32,400 ($27,000 × 1.2); net cash flow becomes $30,000 - $32,400 = -$2,400, and adding the $1,500 opening balance gives -$900.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $4,500 is the original closing balance before the 20% cost increase.","C":"Incorrect because -$2,400 is the revised net cash flow and ignores the $1,500 opening balance.","D":"Incorrect because $9,900 subtracts 20% from outflows instead of adding 20%."}}},{"id":"P1_U5_MCQ_286","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_286","question":"A toy manufacturer's cash flow forecast predicts closing balances of +$8,000 in August, -$3,200 in September, -$9,400 in October, -$4,100 in November, and +$12,000 in December. What is the minimum bank overdraft limit the manufacturer must arrange?","options":{"A":"$9,400","B":"$3,200","C":"$4,100","D":"$16,700"},"correctOption":"A","correctAnswer":"$9,400","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because closing balances are cumulative; the peak negative closing balance occurs in October at -$9,400, so the overdraft limit must be at least $9,400.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $3,200 only covers September and would be exceeded in October and November.","C":"Incorrect because $4,100 only covers November and falls short in October.","D":"Incorrect because $16,700 mistakenly adds all negative closing balances together, even though closing balances already carry forward month to month."}}},{"id":"P1_U5_MCQ_287","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_287","question":"To overcome a short-term cash deficit, an office supply company stops offering 60-day trade credit and requires all customers to pay within 14 days. What is a likely drawback of this action?","options":{"A":"Regular business customers may switch to competitors that still offer 60-day credit terms, reducing future sales","B":"The company's current liabilities will immediately double","C":"The company will have to pay higher interest to its suppliers","D":"Cash inflows will be delayed by an extra 46 days"},"correctOption":"A","correctAnswer":"Regular business customers may switch to competitors that still offer 60-day credit terms, reducing future sales","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because tightening credit terms speeds up cash inflows from paying customers, but risks losing price- and credit-sensitive buyers to rivals.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because changing customer credit terms affects trade receivables, not supplier liabilities.","C":"Incorrect because customer credit policies do not alter supplier interest rates.","D":"Incorrect because shortening credit from 60 to 14 days accelerates cash inflows rather than delaying them."}}},{"id":"P1_U5_MCQ_288","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_288","question":"A restaurant facing a two-month cash shortfall delays paying its kitchen equipment and food suppliers by an extra 30 days without their agreement. What is a major risk of delaying supplier payments?","options":{"A":"Suppliers may refuse future deliveries, demand cash on delivery, or withdraw bulk discounts","B":"The restaurant's gross profit margin will immediately rise to 100%","C":"Customers will stop paying for their meals in cash","D":"The restaurant's non-current assets will lose all value"},"correctOption":"A","correctAnswer":"Suppliers may refuse future deliveries, demand cash on delivery, or withdraw bulk discounts","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because paying suppliers late damages trust and can halt essential raw material deliveries.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because delaying payment does not reduce cost of sales to zero.","C":"Incorrect because supplier payment delays do not prevent restaurant diners from paying.","D":"Incorrect because late supplier payments do not erase non-current asset values."}}},{"id":"P1_U5_MCQ_289","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_289","question":"A wholesaler has $80,000 in unpaid customer invoices due in 60 days and needs cash immediately to pay staff wages. It sells the invoices to a debt factoring company for $68,000 cash today. How does debt factoring affect the business?","options":{"A":"It provides $68,000 of immediate cash inflow to solve the liquidity shortage, but reduces profit by $12,000 due to the factor's fee","B":"It increases total profit by $12,000","C":"It forces the wholesaler to give up 50% of its ordinary shares","D":"It delays cash inflows by another 60 days"},"correctOption":"A","correctAnswer":"It provides $68,000 of immediate cash inflow to solve the liquidity shortage, but reduces profit by $12,000 due to the factor's fee","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because debt factoring turns trade receivables into instant cash, but the finance firm keeps a percentage fee ($12,000), lowering overall profit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because receiving $68,000 for $80,000 of invoices reduces profit by $12,000 rather than increasing it.","C":"Incorrect because factoring involves selling invoices, not issuing shares.","D":"Incorrect because factoring accelerates cash collection immediately."}}},{"id":"P1_U5_MCQ_290","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_290","question":"A haulage company experiencing temporary cash flow pressure decides to postpone replacing two five-year-old lorries until next year. How does this decision help short-term cash flow, and what is its main risk?","options":{"A":"It avoids large immediate capital cash outflows, but the older lorries may suffer costly breakdowns and delay customer deliveries","B":"It increases immediate cash inflows from customers, but reduces shareholders' equity","C":"It eliminates all fuel and driver wage expenses, but increases current liabilities","D":"It converts non-current assets into current liabilities"},"correctOption":"A","correctAnswer":"It avoids large immediate capital cash outflows, but the older lorries may suffer costly breakdowns and delay customer deliveries","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because delaying capital expenditure keeps cash in the bank in the short run, though ageing vehicles risk higher repair costs and lower reliability.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because postponing a purchase reduces cash outflows rather than increasing customer inflows.","C":"Incorrect because existing lorries still require fuel and drivers.","D":"Incorrect because delaying a purchase does not convert assets into liabilities."}}},{"id":"P1_U5_MCQ_291","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_291","question":"A furniture retailer has a forecast closing cash balance of -$7,500 at the end of November. Which action would help solve this November cash deficit?","options":{"A":"Running a promotional clearance sale on slow-moving sofa inventory for cash","B":"Paying December's warehouse rent one month early in November","C":"Buying $10,000 of new display computers for cash in November","D":"Extending customer credit periods from 30 days to 90 days"},"correctOption":"A","correctAnswer":"Running a promotional clearance sale on slow-moving sofa inventory for cash","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because selling existing inventory for cash generates immediate cash inflows without requiring new cash outflows for stock.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because paying rent early increases November cash outflows and worsens the deficit.","C":"Incorrect because buying computers for cash increases November outflows.","D":"Incorrect because extending customer credit delays cash inflows."}}},{"id":"P1_U5_MCQ_292","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_292","question":"In Year 1, a commercial cleaning business earns $180,000 in revenue and incurs $120,000 in costs, reporting a profit of $60,000. However, its closing bank balance is -$15,000 because corporate clients owe $55,000 in unpaid invoices and the firm bought $30,000 of floor-polishing machines for cash. What does this demonstrate?","options":{"A":"A business can be profitable on its statement of profit or loss while simultaneously suffering a negative cash balance","B":"The accountant made an error because profit and closing cash must always be identical","C":"Equipment purchases are always deducted in full from gross profit","D":"Unpaid customer invoices are never counted as revenue"},"correctOption":"A","correctAnswer":"A business can be profitable on its statement of profit or loss while simultaneously suffering a negative cash balance","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because credit revenue boosts profit before cash arrives, while cash spent on non-current equipment drains cash without reducing profit immediately.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because profit and cash flow measure different things and rarely equal each other.","C":"Incorrect because non-current equipment sits on the statement of financial position rather than being deducted from gross profit.","D":"Incorrect because credit sales are included in revenue when the service is delivered."}}},{"id":"P1_U5_MCQ_293","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_293","question":"A fashion retailer makes a trading loss of -$12,000 in February, yet its bank balance rises by +$28,000 during February. Which event explains how a loss-making business can experience positive net cash flow?","options":{"A":"The retailer received a $45,000 long-term bank loan into its current account in February","B":"The retailer bought $45,000 of new shop fittings for cash in February","C":"All February customers bought clothes on 60-day credit","D":"The retailer paid off a $45,000 bank loan in February"},"correctOption":"A","correctAnswer":"The retailer received a $45,000 long-term bank loan into its current account in February","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because receiving a bank loan is a cash inflow that boosts the bank balance even though loans are liabilities, not trading revenue.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because buying shop fittings for cash is a cash outflow that reduces the bank balance.","C":"Incorrect because selling on 60-day credit delays cash inflows and worsens February's cash flow.","D":"Incorrect because repaying a loan is a cash outflow."}}},{"id":"P1_U5_MCQ_294","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_294","question":"Why does a cash flow forecast become less reliable the further into the future it projects (for example, Month 11 compared with Month 1)?","options":{"A":"Economic conditions, competitor actions, supplier prices, and customer demand become harder to predict accurately over longer periods","B":"Cash outflows are legally excluded from forecasts after Month 6","C":"Opening balances reset to zero every six months","D":"Banks prohibit businesses from forecasting beyond three months"},"correctOption":"A","correctAnswer":"Economic conditions, competitor actions, supplier prices, and customer demand become harder to predict accurately over longer periods","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cash flow forecasts rely on assumptions about future sales and costs, and uncertainty increases over longer time horizons.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because all expected cash outflows are included throughout the forecast period.","C":"Incorrect because closing balances carry forward continuously from month to month.","D":"Incorrect because banks often require 12-month or multi-year cash flow forecasts for loans."}}},{"id":"P1_U5_MCQ_295","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_295","question":"A gift-wrap printer experiences negative net cash flows every month from January to August while printing holiday stock, followed by huge positive net cash flows from September to December when retail chains pay for deliveries. What should the printer do?","options":{"A":"Use the cash flow forecast to arrange a seasonal overdraft or working capital loan from January to August that is repaid from September–December receipts","B":"Close the factory permanently in February because net cash flow is negative","C":"Stop printing gift wrap until September so no costs are incurred in spring","D":"Issue new shares every single month from January to August"},"correctOption":"A","correctAnswer":"Use the cash flow forecast to arrange a seasonal overdraft or working capital loan from January to August that is repaid from September–December receipts","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because predictable seasonal cash cycles are best managed by arranging planned short-term finance during production months and clearing it during peak sales receipts.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the business is viable over the full year once seasonal sales receipts arrive.","C":"Incorrect because waiting until September to start printing would leave insufficient time to fulfill retail orders.","D":"Incorrect because issuing shares monthly is impractical, expensive, and unnecessary for a seasonal working capital cycle."}}},{"id":"P1_U5_MCQ_296","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_296","question":"A small electronics company buys $20,000 of components in May on 60-day trade credit. In which month will this $20,000 be recorded as a cash outflow on its cash flow forecast?","options":{"A":"July","B":"May","C":"June","D":"August"},"correctOption":"A","correctAnswer":"July","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because 60 days (two months) after May is July, when cash actually leaves the company's bank account to pay the supplier.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because May is when the order is received on credit, with no cash paid yet.","C":"Incorrect because June is only 30 days after May.","D":"Incorrect because August is 90 days after May."}}},{"id":"P1_U5_MCQ_297","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_297","question":"A restaurant owner is deciding whether to buy a $36,000 pizza oven outright for cash or acquire it via hire purchase with a $6,000 deposit and $600 monthly payments. How does choosing hire purchase improve the restaurant's Month 1 cash flow forecast?","options":{"A":"Month 1 cash outflows are $29,400 lower ($6,600 instead of $36,000), preserving immediate cash liquidity","B":"Month 1 cash inflows increase by $36,000","C":"Month 1 cash outflows drop to $0","D":"Hire purchase eliminates all future cash outflows for the oven"},"correctOption":"A","correctAnswer":"Month 1 cash outflows are $29,400 lower ($6,600 instead of $36,000), preserving immediate cash liquidity","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because paying $6,000 deposit plus the first $600 instalment ($6,600) instead of $36,000 cash saves $29,400 of cash in Month 1.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because acquiring an oven involves cash outflows, not cash inflows.","C":"Incorrect because the $6,000 deposit and $600 first instalment still leave the bank in Month 1.","D":"Incorrect because monthly instalments continue as cash outflows over the agreement term."}}},{"id":"P1_U5_MCQ_298","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_298","question":"During a review of its quarterly cash flow forecast, a clothing manufacturer notices that actual cash outflows were $8,000 higher than forecast while actual cash inflows matched the forecast. What is the direct effect on the closing cash balance?","options":{"A":"The closing cash balance is $8,000 lower than originally forecast","B":"The closing cash balance is $8,000 higher than originally forecast","C":"The closing cash balance is unaffected because inflows matched the forecast","D":"The opening cash balance for that quarter increases by $8,000"},"correctOption":"A","correctAnswer":"The closing cash balance is $8,000 lower than originally forecast","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because higher cash outflows reduce net cash flow by $8,000, directly lowering the closing cash balance by $8,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because higher outflows drain cash rather than increasing the balance.","C":"Incorrect because net cash flow depends on both inflows and outflows.","D":"Incorrect because the opening balance at the start of the quarter is already fixed."}}},{"id":"P1_U5_MCQ_299","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_299","question":"Why do established businesses update their cash flow forecasts regularly (for example, every month) rather than creating one forecast at the start of the year and ignoring it?","options":{"A":"To compare actual cash flows against forecast figures, spot variances early, and adjust spending or financing plans promptly","B":"Because government tax laws require monthly forecasts to be published in newspapers","C":"To ensure that actual profit always equals closing cash","D":"Because bank overdraft limits automatically double every time a forecast is updated"},"correctOption":"A","correctAnswer":"To compare actual cash flows against forecast figures, spot variances early, and adjust spending or financing plans promptly","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because regular monitoring lets managers identify unexpected drops in receipts or rises in costs early enough to take corrective action.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cash flow forecasts are internal planning documents, not publicly mandated newspaper filings.","C":"Incorrect because updating a forecast does not make profit equal cash.","D":"Incorrect because banks do not automatically double overdraft limits without formal approval."}}},{"id":"P1_U5_MCQ_300","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_300","question":"A wholesale beverage distributor has a forecast closing balance of -$14,000 in April, -$16,500 in May, and -$19,000 in June, with no recovery expected later in the year. Why is simply asking suppliers for 15 extra days of credit insufficient to solve this problem?","options":{"A":"A growing, persistent deficit indicates a fundamental profitability or cost issue that requires long-term restructuring, higher revenue, or permanent finance","B":"Suppliers are legally prohibited from extending credit by 15 days","C":"Extending supplier credit increases monthly cash outflows","D":"Cash flow deficits can only be solved by issuing shares on a stock exchange"},"correctOption":"A","correctAnswer":"A growing, persistent deficit indicates a fundamental profitability or cost issue that requires long-term restructuring, higher revenue, or permanent finance","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because short-term cash flow tactics only delay payments temporarily; when deficits worsen month after month, the underlying business model or long-term funding must be fixed.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because suppliers can agree to extend credit terms if they choose.","C":"Incorrect because extending credit delays outflows rather than increasing them.","D":"Incorrect because businesses can also raise prices, cut costs, sell assets, or secure long-term loans."}}},{"id":"P1_U5_MCQ_301","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_301","question":"In a market economy, why are entrepreneurs willing to invest their personal savings and take financial risks to launch new businesses?","options":{"A":"Because profit serves as the financial reward for risk-taking and enterprise","B":"Because the government reimburses all losses made by private companies","C":"Because profit is guaranteed for every business within six months","D":"Because entrepreneurs are not allowed to earn a salary anywhere else"},"correctOption":"A","correctAnswer":"Because profit serves as the financial reward for risk-taking and enterprise","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the prospect of earning profit compensates entrepreneurs for risking their capital and effort.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because private sector owners bear the financial risk of failure themselves.","C":"Incorrect because many new ventures make losses initially or fail.","D":"Incorrect because entrepreneurs choose self-employment despite having salaried alternatives."}}},{"id":"P1_U5_MCQ_302","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_302","question":"Besides rewarding business owners, what are two other major reasons why profit is important to a private sector business?","options":{"A":"It acts as a key internal source of finance (retained profit) for expansion and serves as a measure of business success","B":"It eliminates all current liabilities and removes the need for a bank account","C":"It guarantees zero competition and fixes raw material prices permanently","D":"It replaces the need to prepare a statement of financial position"},"correctOption":"A","correctAnswer":"It acts as a key internal source of finance (retained profit) for expansion and serves as a measure of business success","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because retained profit funds growth without debt or dilution, and profit levels allow owners, investors, and lenders to judge performance.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because profitable businesses still have trade payables and need bank accounts.","C":"Incorrect because high profits actually attract competitors and do not freeze supplier prices.","D":"Incorrect because limited companies must still produce a statement of financial position."}}},{"id":"P1_U5_MCQ_303","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_303","question":"A social enterprise runs a café that trains and employs people recovering from homelessness. Why does this organisation aim to make a profit even though its primary mission is social?","options":{"A":"To survive without depending on charity grants and reinvest profit into expanding its social training programmes","B":"To pay maximum cash dividends to private stock-market shareholders","C":"To avoid paying any wages to its café staff","D":"Because social enterprises are legally fined if their profit margin is below 30%"},"correctOption":"A","correctAnswer":"To survive without depending on charity grants and reinvest profit into expanding its social training programmes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because social enterprises need profit to remain financially independent and reinvest surpluses into achieving their social goals.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because social enterprises reinvest most profits into their social mission rather than maximising private shareholder dividends.","C":"Incorrect because social enterprises pay fair wages to employees.","D":"Incorrect because there is no statutory 30% profit margin requirement."}}},{"id":"P1_U5_MCQ_304","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_304","question":"During the year, a pottery studio sells 4,000 ceramic mugs at $15 each and 1,500 bowls at $24 each. What is the studio's total revenue?","options":{"A":"$96,000","B":"$60,000","C":"$36,000","D":"$5,500"},"correctOption":"A","correctAnswer":"$96,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because total revenue = (4,000 × $15) + (1,500 × $24) = $60,000 + $36,000 = $96,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $60,000 is only the revenue from mugs.","C":"Incorrect because $36,000 is only the revenue from bowls.","D":"Incorrect because 5,500 is the total number of items sold, not the dollar revenue."}}},{"id":"P1_U5_MCQ_305","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_305","question":"In a manufacturing business's statement of profit or loss, which cost is included in 'cost of sales' rather than 'overhead expenses'?","options":{"A":"Raw steel and direct assembly-line worker wages used to produce the goods sold","B":"Annual rent for the corporate head office","C":"Salaries of the marketing and human resources managers","D":"Interest paid on a 10-year bank mortgage"},"correctOption":"A","correctAnswer":"Raw steel and direct assembly-line worker wages used to produce the goods sold","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cost of sales measures the direct production or purchase costs of the products sold during the period.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because head office rent is an indirect overhead expense.","C":"Incorrect because marketing and HR salaries are indirect administrative expenses.","D":"Incorrect because mortgage interest is a finance expense deducted after gross profit."}}},{"id":"P1_U5_MCQ_306","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_306","question":"A bookshop records annual revenue of $390,000, cost of sales of $225,000, and overhead expenses of $105,000. What is the bookshop's gross profit?","options":{"A":"$165,000","B":"$60,000","C":"$285,000","D":"$120,000"},"correctOption":"A","correctAnswer":"$165,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Gross profit = Revenue - Cost of sales ($390,000 - $225,000 = $165,000).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $60,000 is the final profit after deducting both cost of sales and $105,000 of expenses.","C":"Incorrect because $285,000 subtracts expenses from revenue instead of cost of sales.","D":"Incorrect because $120,000 subtracts expenses from cost of sales ($225,000 - $105,000)."}}},{"id":"P1_U5_MCQ_307","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_307","question":"A toy store has annual revenue of $510,000, cost of sales of $290,000, and indirect overhead expenses of $145,000. What is the toy store's profit?","options":{"A":"$75,000","B":"$220,000","C":"$365,000","D":"$435,000"},"correctOption":"A","correctAnswer":"$75,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Gross profit = $510,000 - $290,000 = $220,000, and Profit = Gross profit - Overhead expenses ($220,000 - $145,000 = $75,000).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $220,000 is the gross profit before deducting $145,000 of overhead expenses.","C":"Incorrect because $365,000 deducts only expenses from revenue and omits cost of sales.","D":"Incorrect because $435,000 adds cost of sales and expenses together ($290,000 + $145,000)."}}},{"id":"P1_U5_MCQ_308","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_308","question":"An incomplete statement of profit or loss for a garden centre shows cost of sales of $185,000, gross profit of $145,000, and overhead expenses of $92,000. What were the garden centre's total revenue and final profit?","options":{"A":"Revenue: $330,000; Final profit: $53,000","B":"Revenue: $40,000; Final profit: $53,000","C":"Revenue: $330,000; Final profit: $237,000","D":"Revenue: $277,000; Final profit: $53,000"},"correctOption":"A","correctAnswer":"Revenue: $330,000; Final profit: $53,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Revenue = Gross profit + Cost of sales ($145,000 + $185,000 = $330,000), and Final profit = Gross profit - Expenses ($145,000 - $92,000 = $53,000).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $40,000 subtracts gross profit from cost of sales instead of adding them.","C":"Incorrect because $237,000 adds overhead expenses to gross profit instead of subtracting them.","D":"Incorrect because $277,000 adds cost of sales and expenses instead of cost of sales and gross profit."}}},{"id":"P1_U5_MCQ_309","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_309","question":"A private limited company earns a profit before tax of $300,000. It pays $60,000 in corporation tax and distributes $90,000 in dividends to shareholders. How much retained profit remains in the business?","options":{"A":"$150,000","B":"$240,000","C":"$210,000","D":"$390,000"},"correctOption":"A","correctAnswer":"$150,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Profit after tax = $300,000 - $60,000 = $240,000, and Retained profit = Profit after tax - Dividends ($240,000 - $90,000 = $150,000).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $240,000 is profit after tax before deducting the $90,000 dividend payment.","C":"Incorrect because $210,000 subtracts dividends from profit before tax and ignores the $60,000 tax.","D":"Incorrect because $390,000 adds dividends to profit before tax instead of subtracting tax and dividends."}}},{"id":"P1_U5_MCQ_310","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_310","question":"A bakery's flour supplier raises prices by 15%, increasing the bakery's cost of sales by $9,000 while bread prices, sales volume, and overhead expenses stay unchanged. How does this affect the bakery's statement of profit or loss?","options":{"A":"Both gross profit and final profit fall by $9,000","B":"Gross profit stays unchanged, while final profit falls by $9,000","C":"Revenue rises by $9,000 and gross profit stays unchanged","D":"Overhead expenses rise by $9,000 and gross profit rises by $9,000"},"correctOption":"A","correctAnswer":"Both gross profit and final profit fall by $9,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because flour is a direct ingredient in cost of sales; raising cost of sales by $9,000 directly reduces gross profit by $9,000 and final profit by $9,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because flour is part of cost of sales rather than an overhead expense, so gross profit falls.","C":"Incorrect because bread prices and sales volume did not increase.","D":"Incorrect because higher ingredient costs reduce rather than increase gross profit."}}},{"id":"P1_U5_MCQ_311","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_311","question":"An insurance broker's electricity and office cleaning bills increase by $6,500 over the year, while fee revenue and direct costs remain unchanged. What is the impact on the broker's statement of profit or loss?","options":{"A":"Gross profit remains unchanged, while overhead expenses rise by $6,500 and final profit falls by $6,500","B":"Gross profit falls by $6,500 and final profit stays unchanged","C":"Cost of sales rises by $6,500 and gross profit falls by $6,500","D":"Both gross profit and final profit rise by $6,500"},"correctOption":"A","correctAnswer":"Gross profit remains unchanged, while overhead expenses rise by $6,500 and final profit falls by $6,500","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because electricity and office cleaning are indirect overhead expenses deducted after gross profit; gross profit is unaffected, while final profit drops by $6,500.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because overhead expenses are deducted from gross profit to find final profit.","C":"Incorrect because office utilities and cleaning are indirect expenses, not cost of sales.","D":"Incorrect because higher utility bills represent an increase in costs, reducing final profit."}}},{"id":"P1_U5_MCQ_312","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_312","question":"A restaurant wants to increase its annual profit without raising menu prices. Which action directly reduces its cost of sales?","options":{"A":"Reducing kitchen food spoilage through better portion control and negotiating bulk discounts with vegetable wholesalers","B":"Switching to a cheaper accountant for annual tax filings","C":"Reducing expenditure on local newspaper advertisements","D":"Subletting an unused upstairs office room"},"correctOption":"A","correctAnswer":"Reducing kitchen food spoilage through better portion control and negotiating bulk discounts with vegetable wholesalers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ingredients and food waste form part of cost of sales; reducing waste and ingredient purchase prices lowers cost of sales and boosts gross profit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because accounting fees are indirect overhead expenses.","C":"Incorrect because advertising is an indirect marketing expense.","D":"Incorrect because subletting reduces indirect rent overhead rather than direct food cost of sales."}}},{"id":"P1_U5_MCQ_313","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_313","question":"A clothing manufacturer keeps its selling prices and fabric costs unchanged, but installs automated heating controls and renegotiates lower warehouse insurance premiums. How does this increase profit?","options":{"A":"It lowers overhead expenses, increasing final profit while leaving gross profit unchanged","B":"It increases total revenue on the statement of profit or loss","C":"It lowers cost of sales and increases gross profit","D":"It increases current assets on the statement of financial position"},"correctOption":"A","correctAnswer":"It lowers overhead expenses, increasing final profit while leaving gross profit unchanged","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because heating and insurance are overhead expenses deducted below gross profit; lowering them directly raises final profit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because selling prices and sales volume did not change.","C":"Incorrect because heating and insurance are indirect overheads, not direct cost of sales.","D":"Incorrect because reducing expenses improves profit rather than automatically creating current assets."}}},{"id":"P1_U5_MCQ_314","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_314","question":"A coffee shop raises the price of its lattes by 30% to boost profit, only to find that its monthly profit falls by half. Why did raising the selling price reduce profit?","options":{"A":"Many regular customers switched to nearby rival cafés, causing sales volume and total revenue to fall sharply","B":"Higher latte prices automatically doubled the shop's fixed rent","C":"Raising prices is illegal for small cafés","D":"Higher prices increased the cost of coffee beans per cup"},"correctOption":"A","correctAnswer":"Many regular customers switched to nearby rival cafés, causing sales volume and total revenue to fall sharply","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because in a competitive market with many substitutes, a steep price hike drives away customers, reducing quantity sold and total revenue.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because fixed rent is unaffected by menu prices.","C":"Incorrect because private cafés set their own menu prices freely.","D":"Incorrect because supplier bean costs do not depend on retail latte prices."}}},{"id":"P1_U5_MCQ_315","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_315","question":"To boost profit quickly, a factory manager cancels all preventative machinery maintenance and cuts worker safety training. What is the main long-term risk of this cost-cutting strategy?","options":{"A":"Frequent machinery breakdowns, workplace accidents, and lower product quality will disrupt output and reduce future profits","B":"Gross profit will immediately fall to zero this month","C":"The factory's non-current liabilities will double","D":"Suppliers will raise raw material prices because training was cut"},"correctOption":"A","correctAnswer":"Frequent machinery breakdowns, workplace accidents, and lower product quality will disrupt output and reduce future profits","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cutting essential maintenance and training saves expenses briefly but leads to costly equipment failures, lower productivity, and damaged reputation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cutting overhead expenses actually makes short-term profit look higher before problems emerge.","C":"Incorrect because cutting expenses does not create long-term debt.","D":"Incorrect because suppliers do not set raw material prices based on a buyer's training budget."}}},{"id":"P1_U5_MCQ_316","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_316","question":"A supermarket compares two bakery products: Artisan Bread generates $90,000 in revenue with $40,000 in cost of sales, whereas Standard Loaves generate $140,000 in revenue with $105,000 in cost of sales. Which conclusion is supported by this statement of profit or loss data?","options":{"A":"Artisan Bread generates more gross profit ($50,000) than Standard Loaves ($35,000) despite lower sales revenue","B":"Standard Loaves are more profitable because their revenue is $50,000 higher","C":"Artisan Bread should be discontinued immediately because its revenue is under $100,000","D":"Both products generate the exact same gross profit"},"correctOption":"A","correctAnswer":"Artisan Bread generates more gross profit ($50,000) than Standard Loaves ($35,000) despite lower sales revenue","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Artisan Bread earns $50,000 gross profit ($90,000 - $40,000), exceeding Standard Loaves' $35,000 gross profit ($140,000 - $105,000).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because higher revenue does not produce higher profit when cost of sales is much higher.","C":"Incorrect because discontinuing the higher-gross-profit product would reduce total profit.","D":"Incorrect because $50,000 is greater than $35,000."}}},{"id":"P1_U5_MCQ_317","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_317","question":"Between Year 1 and Year 2, a hardware retailer's revenue rose from $400,000 to $460,000 and its gross profit rose from $160,000 to $184,000, yet its final profit fell from $60,000 to $44,000. What caused final profit to fall despite higher sales and gross profit?","options":{"A":"Overhead expenses rose sharply from $100,000 to $140,000","B":"Cost of sales increased as a percentage of revenue","C":"Sales revenue fell by $60,000","D":"The retailer paid out too much share capital"},"correctOption":"A","correctAnswer":"Overhead expenses rose sharply from $100,000 to $140,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Gross profit - Expenses = Profit; in Year 1 expenses were $100,000 ($160,000 - $60,000), whereas in Year 2 expenses jumped to $140,000 ($184,000 - $44,000).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because gross profit remained at 40% of revenue in both years ($160k/$400k and $184k/$460k).","C":"Incorrect because revenue increased from $400,000 to $460,000.","D":"Incorrect because share capital is not deducted as an expense on the statement of profit or loss."}}},{"id":"P1_U5_MCQ_318","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_318","question":"An electronics manufacturer reports a profit of $250,000 on its statement of profit or loss, yet it cannot pay a $200,000 cash dividend to shareholders because its bank account holds only $15,000. What does this illustrate?","options":{"A":"Profit is not the same as cash; a business can be profitable while having its funds tied up in trade receivables, inventory, or equipment","B":"Companies are legally prohibited from paying dividends out of profits","C":"The statement of profit or loss only records cash transactions","D":"Dividends must always be paid using bank overdrafts"},"correctOption":"A","correctAnswer":"Profit is not the same as cash; a business can be profitable while having its funds tied up in trade receivables, inventory, or equipment","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because profit includes credit sales and excludes capital expenditure, so high profit does not guarantee sufficient cash in the bank to pay large cash dividends.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because dividends are normally distributed from after-tax profits when cash is available.","C":"Incorrect because the statement of profit or loss includes credit sales and accrued expenses.","D":"Incorrect because companies should avoid borrowing via overdrafts just to pay dividends."}}},{"id":"P1_U5_MCQ_319","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_319","question":"A courier company spends $40,000 on a new digital parcel-tracking app campaign that increases revenue by $95,000 and incurs $30,000 in extra direct delivery costs (cost of sales). What is the net effect on the company's profit?","options":{"A":"Profit increases by $25,000","B":"Profit increases by $65,000","C":"Profit increases by $95,000","D":"Profit decreases by $40,000"},"correctOption":"A","correctAnswer":"Profit increases by $25,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because extra gross profit = $95,000 revenue - $30,000 cost of sales = $65,000, and subtracting the $40,000 campaign expense yields a net profit gain of $25,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $65,000 is the increase in gross profit before deducting the $40,000 campaign expense.","C":"Incorrect because $95,000 is the increase in revenue before deducting direct delivery costs and campaign expenses.","D":"Incorrect because the extra gross profit ($65,000) exceeds the $40,000 campaign cost."}}},{"id":"P1_U5_MCQ_320","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_320","question":"Why is a statement of profit or loss useful to a commercial bank when a small business applies for a loan?","options":{"A":"It shows the business's track record of generating revenue, controlling costs, and earning profits over recent trading periods","B":"It lists the exact resale value of the owner's personal house","C":"It proves the business will never face new competitors","D":"It shows the exact daily bank balance for the next five years"},"correctOption":"A","correctAnswer":"It shows the business's track record of generating revenue, controlling costs, and earning profits over recent trading periods","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because banks review past statements of profit or loss to assess whether the business is viable, well-managed, and capable of earning profits to service debt.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because personal property values are not shown on a business statement of profit or loss.","C":"Incorrect because historical profit statements cannot prevent future competition.","D":"Incorrect because future daily/monthly cash balances are projected in a cash flow forecast."}}},{"id":"P1_U5_MCQ_321","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_321","question":"A toy company's statement of profit or loss shows revenue of $620,000, overhead expenses of $140,000, and final profit of $85,000. What was the company's cost of sales?","options":{"A":"$395,000","B":"$225,000","C":"$535,000","D":"$480,000"},"correctOption":"A","correctAnswer":"$395,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Gross profit = Final profit + Overhead expenses ($85,000 + $140,000 = $225,000), and Cost of sales = Revenue - Gross profit ($620,000 - $225,000 = $395,000).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $225,000 is the gross profit, not cost of sales.","C":"Incorrect because $535,000 subtracts only final profit from revenue ($620,000 - $85,000), failing to remove overhead expenses.","D":"Incorrect because $480,000 subtracts only overhead expenses from revenue ($620,000 - $140,000)."}}},{"id":"P1_U5_MCQ_322","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_322","question":"A car-rental firm sells five old rental cars for $55,000 cash. Why is this $55,000 NOT recorded as 'sales revenue' on the firm's statement of profit or loss?","options":{"A":"Because sales revenue only records income from the business's main trading activities (renting cars), whereas selling old vehicles is disposing of non-current assets","B":"Because car-rental firms are legally forbidden from selling used cars","C":"Because cash receipts are never recorded anywhere in company accounts","D":"Because selling old cars is recorded under cost of sales"},"correctOption":"A","correctAnswer":"Because sales revenue only records income from the business's main trading activities (renting cars), whereas selling old vehicles is disposing of non-current assets","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because revenue represents normal trading turnover from selling goods or services, whereas selling used vehicles reduces non-current assets on the statement of financial position.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because car-rental companies routinely sell off older fleet vehicles.","C":"Incorrect because cash receipts are recorded in cash flow records and on the statement of financial position.","D":"Incorrect because cost of sales records direct costs of goods sold, not asset disposals."}}},{"id":"P1_U5_MCQ_323","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_323","question":"When a business makes a loss (where total costs exceed total revenue), what happens to its retained profit reserve on the statement of financial position?","options":{"A":"The loss reduces accumulated retained profit (shareholders' equity), shrinking the net worth of the business","B":"The loss is added to non-current assets","C":"The loss increases share capital automatically","D":"The loss is paid to shareholders as a negative dividend"},"correctOption":"A","correctAnswer":"The loss reduces accumulated retained profit (shareholders' equity), shrinking the net worth of the business","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because just as retained profits increase equity, trading losses erode accumulated reserves and reduce total shareholders' equity.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a trading loss reduces net assets rather than increasing non-current assets.","C":"Incorrect because share capital only changes when new shares are issued or bought back.","D":"Incorrect because shareholders cannot be forced to pay negative dividends due to limited liability."}}},{"id":"P1_U5_MCQ_324","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_324","question":"A chain of gyms sees its annual profit fall from $190,000 to $110,000 despite opening two new branches. Which step should the directors take first using their statement of profit or loss?","options":{"A":"Compare revenue, cost of sales, and overhead expenses across individual branches to identify whether weak membership sales or rising running costs caused the drop","B":"Immediately close all gyms across the country","C":"Stop recording overhead expenses on future statements of profit or loss","D":"Double membership prices at every branch without researching competitors"},"correctOption":"A","correctAnswer":"Compare revenue, cost of sales, and overhead expenses across individual branches to identify whether weak membership sales or rising running costs caused the drop","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because managers use detailed profit and loss breakdowns to diagnose whether low revenue or excessive costs caused profit to decline before choosing corrective action.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the chain is still making $110,000 profit, so closing everything would destroy a profitable business.","C":"Incorrect because omitting expenses would falsify the financial statements.","D":"Incorrect because doubling prices blindly could drive away members and worsen profit."}}},{"id":"P1_U5_MCQ_325","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_325","question":"A bakery's statement of profit or loss shows revenue of $480,000, cost of sales of $210,000, overhead expenses of $170,000, tax of $20,000, and dividends of $35,000. What is the bakery's retained profit for the year?","options":{"A":"$45,000","B":"$100,000","C":"$80,000","D":"$270,000"},"correctOption":"A","correctAnswer":"$45,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Gross profit = $480,000 - $210,000 = $270,000; Profit before tax = $270,000 - $170,000 = $100,000; Profit after tax = $100,000 - $20,000 = $80,000; Retained profit = $80,000 - $35,000 = $45,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $100,000 is profit before tax and dividends.","C":"Incorrect because $80,000 is profit after tax before deducting the $35,000 dividend payout.","D":"Incorrect because $270,000 is the gross profit."}}},{"id":"P1_U5_MCQ_326","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_326","question":"Which statement accurately defines an 'asset' on a business's statement of financial position?","options":{"A":"Any resource or item of value owned by the business that is expected to provide future economic benefit","B":"Any debt or financial obligation that the business owes to external lenders or suppliers","C":"The total sales revenue earned by the business during the financial year","D":"The annual electricity and wage expenses paid by the business"},"correctOption":"A","correctAnswer":"Any resource or item of value owned by the business that is expected to provide future economic benefit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because assets are items of value owned by a business, divided into non-current assets (held >1 year) and current assets (held <1 year).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because debts owed by the business are liabilities, not assets.","C":"Incorrect because sales revenue appears on the statement of profit or loss.","D":"Incorrect because running expenses appear on the statement of profit or loss."}}},{"id":"P1_U5_MCQ_327","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_327","question":"Which group of items consists ENTIRELY of non-current assets on a manufacturing company's statement of financial position?","options":{"A":"Factory premises, CNC lathes, and company delivery trucks","B":"Finished goods inventory, trade receivables, and cash","C":"Factory premises, raw steel inventory, and bank overdraft","D":"10-year bank loan, share capital, and retained profit"},"correctOption":"A","correctAnswer":"Factory premises, CNC lathes, and company delivery trucks","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because factory premises, machinery, and vehicles are long-term physical resources owned and used by the business for more than 12 months.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because inventory, trade receivables, and cash are short-term current assets.","C":"Incorrect because raw steel inventory is a current asset and a bank overdraft is a current liability.","D":"Incorrect because a 10-year loan is a non-current liability, while share capital and retained profit are equity."}}},{"id":"P1_U5_MCQ_328","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_328","question":"Why are 'trade receivables' classified as a current asset on a statement of financial position?","options":{"A":"Because they represent money owed to the business by credit customers that is expected to be collected in cash within 12 months","B":"Because they represent money the business owes to its raw material suppliers","C":"Because they are permanent factory buildings owned by the business","D":"Because they are long-term loans borrowed from a commercial bank"},"correctOption":"A","correctAnswer":"Because they represent money owed to the business by credit customers that is expected to be collected in cash within 12 months","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because trade receivables are short-term claims on credit customers that normally convert into cash within 30 to 90 days.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because money owed to suppliers is recorded as trade payables (a current liability).","C":"Incorrect because factory buildings are non-current assets.","D":"Incorrect because long-term loans are non-current liabilities."}}},{"id":"P1_U5_MCQ_329","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_329","question":"Which item is classified as a 'current liability' on a retail business's statement of financial position?","options":{"A":"Trade payables owed to clothing suppliers due in 30 days","B":"A 15-year commercial mortgage on the store building","C":"Cash held in the store's safe and bank current account","D":"Share capital invested by the company's founders"},"correctOption":"A","correctAnswer":"Trade payables owed to clothing suppliers due in 30 days","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because current liabilities are short-term debts that must be repaid within one year, such as trade payables and bank overdrafts.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a 15-year mortgage is a long-term non-current liability.","C":"Incorrect because cash is a current asset.","D":"Incorrect because share capital is part of shareholders' equity."}}},{"id":"P1_U5_MCQ_330","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_330","question":"What distinguishes a 'non-current liability' from a 'current liability' on a statement of financial position?","options":{"A":"A non-current liability is a debt repayable after more than one year, whereas a current liability is due within one year","B":"A non-current liability never has to be repaid, whereas a current liability must be repaid","C":"A non-current liability is owned by the business, whereas a current liability is owed to the business","D":"A non-current liability is part of share capital, whereas a current liability is part of retained profit"},"correctOption":"A","correctAnswer":"A non-current liability is a debt repayable after more than one year, whereas a current liability is due within one year","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because liabilities are separated by repayment timeframe: current liabilities fall due within 12 months, while non-current liabilities (like multi-year loans) are due after 12 months.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because both current and non-current liabilities are legally binding debts that must be repaid.","C":"Incorrect because all liabilities are debts owed by the business to external parties.","D":"Incorrect because share capital and retained profit are equity, not liabilities."}}},{"id":"P1_U5_MCQ_331","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_331","question":"A florist's statement of financial position shows inventory of $9,500, trade receivables of $6,500, cash of $4,000, trade payables of $8,200, and a bank overdraft of $2,800. What is the florist's working capital (net current assets)?","options":{"A":"$9,000","B":"$11,800","C":"$31,000","D":"$5,000"},"correctOption":"A","correctAnswer":"$9,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Current assets = $9,500 + $6,500 + $4,000 = $20,000 and Current liabilities = $8,200 + $2,800 = $11,000, giving working capital of $20,000 - $11,000 = $9,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $11,800 omits the $2,800 bank overdraft from current liabilities ($20,000 - $8,200).","C":"Incorrect because $31,000 adds current assets and current liabilities together ($20,000 + $11,000).","D":"Incorrect because $5,000 omits the $4,000 cash balance from current assets ($16,000 - $11,000)."}}},{"id":"P1_U5_MCQ_332","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_332","question":"A carpentry workshop owns buildings valued at $260,000, woodworking machinery valued at $75,000, timber inventory of $19,000, trade receivables of $14,000, and cash of $7,000. What is the value of the workshop's total assets?","options":{"A":"$375,000","B":"$335,000","C":"$40,000","D":"$295,000"},"correctOption":"A","correctAnswer":"$375,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Total assets = Non-current assets ($260,000 + $75,000 = $335,000) + Current assets ($19,000 + $14,000 + $7,000 = $40,000) = $375,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $335,000 is non-current assets alone.","C":"Incorrect because $40,000 is current assets alone.","D":"Incorrect because $295,000 subtracts current assets from non-current assets."}}},{"id":"P1_U5_MCQ_333","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_333","question":"A logistics company's statement of financial position shows non-current assets of $640,000, current assets of $120,000, current liabilities of $70,000, and non-current liabilities of $240,000. What is the company's capital employed?","options":{"A":"$690,000","B":"$450,000","C":"$760,000","D":"$520,000"},"correctOption":"A","correctAnswer":"$690,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Capital employed = Total assets - Current liabilities ($640,000 + $120,000 - $70,000 = $690,000), which also equals Total equity ($450,000) + Non-current liabilities ($240,000).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $450,000 is net assets / total shareholders' equity, which deducts non-current liabilities as well.","C":"Incorrect because $760,000 is total assets without deducting current liabilities.","D":"Incorrect because $520,000 omits current assets ($640,000 - $120,000)."}}},{"id":"P1_U5_MCQ_334","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_334","question":"On a private limited company's statement of financial position, non-current assets are $380,000, current assets are $95,000, current liabilities are $45,000, non-current liabilities are $130,000, and share capital is $200,000. What must the company's retained profit be?","options":{"A":"$100,000","B":"$300,000","C":"$230,000","D":"$145,000"},"correctOption":"A","correctAnswer":"$100,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Total assets = $380,000 + $95,000 = $475,000; Total liabilities = $45,000 + $130,000 = $175,000; Total equity (Net assets) = $475,000 - $175,000 = $300,000; Retained profit = $300,000 - $200,000 share capital = $100,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $300,000 is total shareholders' equity, not retained profit alone.","C":"Incorrect because $230,000 forgets to subtract the $130,000 non-current liabilities.","D":"Incorrect because $145,000 forgets to subtract the $45,000 current liabilities."}}},{"id":"P1_U5_MCQ_335","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_335","question":"A toy retailer takes out a $25,000 short-term bank loan (repayable in 9 months) and deposits the cash into its bank current account. How does this transaction immediately affect the retailer's statement of financial position?","options":{"A":"Current assets (cash) increase by $25,000 and current liabilities increase by $25,000","B":"Non-current assets increase by $25,000 and shareholders' equity increases by $25,000","C":"Current assets increase by $25,000 and non-current liabilities increase by $25,000","D":"Working capital increases by $25,000"},"correctOption":"A","correctAnswer":"Current assets (cash) increase by $25,000 and current liabilities increase by $25,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cash in the bank rises by $25,000 (current asset) while a 9-month loan is due within one year, increasing current liabilities by $25,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cash is a current asset and a loan creates a liability rather than equity.","C":"Incorrect because a 9-month loan is repayable within 12 months, making it a current liability rather than non-current.","D":"Incorrect because both current assets and current liabilities rise by $25,000, leaving working capital unchanged."}}},{"id":"P1_U5_MCQ_336","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_336","question":"A wholesaler sells $18,000 of inventory (at cost) to a retail chain on 30-day credit for $18,000 (ignoring profit margin for simplicity). How does this transaction immediately change the wholesaler's current assets?","options":{"A":"Inventory decreases by $18,000 and trade receivables increase by $18,000, leaving total current assets unchanged","B":"Cash increases by $18,000 and inventory increases by $18,000","C":"Current liabilities increase by $18,000 and total current assets fall by $18,000","D":"Non-current assets increase by $18,000"},"correctOption":"A","correctAnswer":"Inventory decreases by $18,000 and trade receivables increase by $18,000, leaving total current assets unchanged","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because inventory leaves the warehouse (-$18,000) and is replaced by an unpaid customer invoice under trade receivables (+$18,000), both within current assets.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the sale was on 30-day credit (no cash yet) and inventory decreased.","C":"Incorrect because selling to a customer creates a trade receivable (asset), not a liability.","D":"Incorrect because inventory and trade receivables are both current assets."}}},{"id":"P1_U5_MCQ_337","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_337","question":"A construction company uses $75,000 of its cash balance to buy a new excavator machine. What is the immediate effect on the company's total assets and working capital?","options":{"A":"Total assets remain unchanged, while working capital decreases by $75,000","B":"Total assets increase by $75,000 and working capital increases by $75,000","C":"Total assets decrease by $75,000 and working capital stays unchanged","D":"Both total assets and working capital decrease by $75,000"},"correctOption":"A","correctAnswer":"Total assets remain unchanged, while working capital decreases by $75,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cash (-$75,000 current asset) is exchanged for an excavator (+$75,000 non-current asset), keeping total assets constant while lowering current assets and working capital by $75,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cash was spent to acquire the machine, so total assets do not increase.","C":"Incorrect because the excavator is added to non-current assets, keeping total assets unchanged.","D":"Incorrect because total assets stay the same when one asset is exchanged for another of equal value."}}},{"id":"P1_U5_MCQ_338","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_338","question":"Examining a boutique clothing brand's statement of financial position, an analyst sees current assets of $42,000 and current liabilities of $68,000. What does this negative working capital of -$26,000 signal?","options":{"A":"The brand does not have enough short-term assets to cover debts due within 12 months, creating a serious risk of liquidity failure","B":"The brand has $26,000 in surplus cash ready to pay dividends","C":"The brand's gross profit margin is 26%","D":"The brand has zero long-term bank loans"},"correctOption":"A","correctAnswer":"The brand does not have enough short-term assets to cover debts due within 12 months, creating a serious risk of liquidity failure","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because negative working capital means current liabilities exceed current assets, warning that the business may be unable to pay suppliers and short-term creditors on time.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because negative working capital indicates a liquidity deficit, not a cash surplus.","C":"Incorrect because working capital does not measure gross profit margin.","D":"Incorrect because working capital excludes non-current liabilities."}}},{"id":"P1_U5_MCQ_339","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_339","question":"Why is it important for a business to maintain positive working capital, yet avoid holding excessively high working capital?","options":{"A":"Too little working capital risks inability to pay short-term bills, while excessive working capital ties up funds unproductively in idle cash, excess stock, or slow receivables","B":"High working capital increases corporation tax rates to 80%","C":"Negative working capital is required by law for all public limited companies","D":"Working capital is deducted from revenue when calculating gross profit"},"correctOption":"A","correctAnswer":"Too little working capital risks inability to pay short-term bills, while excessive working capital ties up funds unproductively in idle cash, excess stock, or slow receivables","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because effective working capital management balances liquidity safety (paying bills on time) against efficiency (avoiding idle resources).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because tax rates are based on taxable profit, not working capital levels.","C":"Incorrect because businesses aim for positive working capital to stay solvent.","D":"Incorrect because working capital sits on the statement of financial position, not on the statement of profit or loss."}}},{"id":"P1_U5_MCQ_340","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_340","question":"Over three years, a supermarket chain's trade payables grew from $90,000 to $210,000 while its cash balance fell from $50,000 to $4,000. What is the most likely interpretation of this trend on its statement of financial position?","options":{"A":"The supermarket is running short of cash and delaying payments to suppliers, risking supply disruptions","B":"The supermarket has eliminated all of its current liabilities","C":"The supermarket has become completely debt-free","D":"Customers are paying for groceries in cash faster than ever before"},"correctOption":"A","correctAnswer":"The supermarket is running short of cash and delaying payments to suppliers, risking supply disruptions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sharply rising trade payables paired with plummeting cash indicates worsening liquidity and reliance on unpaid supplier credit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because trade payables are current liabilities and more than doubled.","C":"Incorrect because trade payables represent short-term commercial debt owed to suppliers.","D":"Incorrect because faster customer cash payments would increase rather than drain the cash balance."}}},{"id":"P1_U5_MCQ_341","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_341","question":"A tech company's statement of financial position lists 'share capital' at $500,000. What does this $500,000 figure represent?","options":{"A":"The total amount of money originally invested into the company by shareholders in exchange for shares","B":"The amount of cash currently sitting in the company's bank account","C":"The total value of unsold computer inventory in the warehouse","D":"The total amount of loans owed to commercial banks"},"correctOption":"A","correctAnswer":"The total amount of money originally invested into the company by shareholders in exchange for shares","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because share capital records the permanent capital raised by issuing shares to owners, forming part of shareholders' equity.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cash raised from shares is spent on assets and operations, so share capital rarely equals the bank balance.","C":"Incorrect because inventory is recorded under current assets.","D":"Incorrect because bank loans are debt liabilities, not share capital."}}},{"id":"P1_U5_MCQ_342","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_342","question":"Which statement explains why a statement of financial position must always balance (Total assets = Total liabilities + Shareholders' equity)?","options":{"A":"Because every asset owned by the business must be financed either by borrowing from external creditors (liabilities) or by funds belonging to the owners (equity)","B":"Because cash inflows always equal cash outflows every single day","C":"Because non-current assets must always equal current assets","D":"Because accountants adjust revenue figures until both sides match"},"correctOption":"A","correctAnswer":"Because every asset owned by the business must be financed either by borrowing from external creditors (liabilities) or by funds belonging to the owners (equity)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the accounting equation reflects that all business resources (assets) are funded by external claims (liabilities) plus owners' claims (equity).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because daily cash inflows and outflows rarely equal each other.","C":"Incorrect because non-current assets and current assets rarely have identical values.","D":"Incorrect because revenue is not on the statement of financial position, and accounts balance naturally through double-entry bookkeeping."}}},{"id":"P1_U5_MCQ_343","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_343","question":"A solar energy company's statement of financial position shows non-current assets of $850,000, working capital of $150,000, and non-current liabilities of $400,000. What is the value of total shareholders' equity?","options":{"A":"$600,000","B":"$1,000,000","C":"$1,400,000","D":"$300,000"},"correctOption":"A","correctAnswer":"$600,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Net assets = Non-current assets ($850,000) + Working capital ($150,000) - Non-current liabilities ($400,000) = $600,000, which equals Total shareholders' equity.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $1,000,000 is capital employed ($850,000 + $150,000), which has not yet deducted the $400,000 non-current liabilities.","C":"Incorrect because $1,400,000 adds non-current liabilities instead of subtracting them.","D":"Incorrect because $300,000 subtracts working capital instead of adding it."}}},{"id":"P1_U5_MCQ_344","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_344","question":"How do shareholders use a company's statement of financial position at the end of the financial year?","options":{"A":"To check whether the net worth (equity) of the business has grown and whether debt levels (non-current liabilities) are safely managed","B":"To calculate the exact hourly wage rate of every factory worker","C":"To decide which raw material suppliers offer the best bulk discounts","D":"To replace the statement of profit or loss when calculating gross profit margin"},"correctOption":"A","correctAnswer":"To check whether the net worth (equity) of the business has grown and whether debt levels (non-current liabilities) are safely managed","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because shareholders track changes in equity/retained profit and debt levels to see if their investment is growing safely in value.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because hourly wage rates are operational payroll details, not shown on the statement of financial position.","C":"Incorrect because supplier procurement decisions are made by purchasing managers.","D":"Incorrect because gross profit margin is calculated from the statement of profit or loss."}}},{"id":"P1_U5_MCQ_345","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_345","question":"A packaging supplier asks to inspect a new retail customer's statement of financial position before offering $30,000 of goods on 60-day credit. Which figures will the supplier examine most closely?","options":{"A":"Current assets (especially cash and trade receivables) compared with current liabilities to ensure short-term bills can be paid","B":"The historical date when the retail company's founders were born","C":"The retail customer's annual advertising budget","D":"The retail customer's total share capital alone"},"correctOption":"A","correctAnswer":"Current assets (especially cash and trade receivables) compared with current liabilities to ensure short-term bills can be paid","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because trade suppliers need to know whether a credit customer holds enough liquid current assets to settle short-term liabilities within 60 days.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because personal biographical dates are irrelevant and not in financial statements.","C":"Incorrect because advertising expenditure appears on the statement of profit or loss and does not prove short-term liquidity.","D":"Incorrect because high historical share capital could still be tied up in illiquid buildings while the firm lacks cash."}}},{"id":"P1_U5_MCQ_346","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_346","question":"Why are intangible assets like brand reputation, customer loyalty, and skilled employees usually NOT shown with a dollar value on a standard statement of financial position?","options":{"A":"Because they are difficult to measure objectively in reliable monetary terms, which is a limitation of financial statements","B":"Because brand reputation and skilled staff have zero impact on business success","C":"Because they are classified as current liabilities","D":"Because companies are fined if they employ skilled workers"},"correctOption":"A","correctAnswer":"Because they are difficult to measure objectively in reliable monetary terms, which is a limitation of financial statements","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because accounting statements primarily record verifiable financial transactions and physical/monetary assets, omitting qualitative strengths like staff talent and brand loyalty.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because brand reputation and skilled staff are major drivers of competitive advantage.","C":"Incorrect because they are intangible strengths, not financial debts.","D":"Incorrect because skilled staff are an asset to operations, never penalized."}}},{"id":"P1_U5_MCQ_347","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_347","question":"A toy manufacturer buys $30,000 of plastic pellets on 45-day trade credit. How does this purchase affect the manufacturer's statement of financial position?","options":{"A":"Current assets (inventory) increase by $30,000 and current liabilities (trade payables) increase by $30,000","B":"Current assets (cash) decrease by $30,000 and non-current assets increase by $30,000","C":"Shareholders' equity increases by $30,000 and current liabilities decrease by $30,000","D":"Non-current liabilities increase by $30,000 and working capital falls by $30,000"},"correctOption":"A","correctAnswer":"Current assets (inventory) increase by $30,000 and current liabilities (trade payables) increase by $30,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because raw material inventory rises by $30,000 (current asset) and money owed to suppliers rises by $30,000 (current liability).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because no cash was paid yet and plastic pellets are inventory (current asset), not a non-current asset.","C":"Incorrect because buying materials on credit creates a liability rather than increasing equity.","D":"Incorrect because 45-day trade credit is a current liability, and working capital remains unchanged."}}},{"id":"P1_U5_MCQ_348","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_348","question":"A hotel group's statement of financial position shows non-current assets of $1,200,000, inventory of $30,000, trade receivables of $45,000, cash of $25,000, current liabilities of $80,000, and non-current liabilities of $520,000. What is the hotel group's total assets?","options":{"A":"$1,300,000","B":"$1,200,000","C":"$100,000","D":"$700,000"},"correctOption":"A","correctAnswer":"$1,300,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Total assets = Non-current assets ($1,200,000) + Current assets ($30,000 + $45,000 + $25,000 = $100,000) = $1,300,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $1,200,000 includes only non-current assets.","C":"Incorrect because $100,000 includes only current assets.","D":"Incorrect because $700,000 is total shareholders' equity / net assets ($1,300,000 - $80,000 - $520,000)."}}},{"id":"P1_U5_MCQ_349","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_349","question":"A wholesale distributor receives a $20,000 payment from a credit customer and immediately uses that $20,000 cash to pay a supplier invoice. What is the combined net effect of these two transactions on the statement of financial position?","options":{"A":"Trade receivables decrease by $20,000 and trade payables decrease by $20,000, while cash returns to its original level","B":"Cash increases by $40,000 and equity increases by $40,000","C":"Non-current assets increase by $20,000 and non-current liabilities decrease by $20,000","D":"Working capital increases by $20,000"},"correctOption":"A","correctAnswer":"Trade receivables decrease by $20,000 and trade payables decrease by $20,000, while cash returns to its original level","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because collecting from the customer reduces trade receivables (-$20,000) and adds cash (+$20,000), and paying the supplier removes that cash (-$20,000) and reduces trade payables (-$20,000).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the cash received was immediately paid out to the supplier.","C":"Incorrect because neither non-current assets nor non-current liabilities are involved.","D":"Incorrect because current assets fall by $20,000 and current liabilities also fall by $20,000, leaving working capital unchanged."}}},{"id":"P1_U5_MCQ_350","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_350","question":"An agricultural cooperative's statement of financial position shows that 90% of its total assets are tied up in specialized grain silos and farmland, while its current liabilities exceed its current assets. What challenge does this asset structure create?","options":{"A":"Low liquidity: farmland and silos cannot be quickly turned into cash to pay urgent short-term bills","B":"Excessive idle cash sitting in current accounts","C":"Zero collateral available for long-term mortgages","D":"An inability to calculate gross profit margin"},"correctOption":"A","correctAnswer":"Low liquidity: farmland and silos cannot be quickly turned into cash to pay urgent short-term bills","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because non-current assets like farmland and silos are illiquid and take months to sell, leaving the cooperative vulnerable to short-term cash shortages.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because current liabilities exceed current assets, indicating a shortage of cash rather than excess cash.","C":"Incorrect because farmland and silos actually provide strong collateral for long-term loans.","D":"Incorrect because gross profit margin is calculated from the statement of profit or loss."}}},{"id":"P1_U5_MCQ_351","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_351","question":"Why is calculating ratios (such as profit margin or current ratio) often more informative than simply looking at raw dollar figures in a company's accounts?","options":{"A":"Ratios allow meaningful comparisons across businesses of different sizes and across different years by relating one figure to another","B":"Ratios eliminate the need to record revenue or expenses accurately","C":"Ratios are legally guaranteed to remain constant every year","D":"Ratios convert non-current liabilities into shareholders' equity"},"correctOption":"A","correctAnswer":"Ratios allow meaningful comparisons across businesses of different sizes and across different years by relating one figure to another","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because raw profit of $100,000 means very different things for a small shop versus a giant supermarket; ratios express performance relative to sales, capital, or debts.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because accurate underlying financial data is essential to compute valid ratios.","C":"Incorrect because ratios change whenever trading performance or asset balances shift.","D":"Incorrect because ratios are analytical tools and do not alter accounting classifications."}}},{"id":"P1_U5_MCQ_352","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_352","question":"A stationery retailer reports annual revenue of $650,000, cost of sales of $390,000, and overhead expenses of $162,500. What is the retailer's gross profit margin?","options":{"A":"40%","B":"15%","C":"60%","D":"25%"},"correctOption":"A","correctAnswer":"40%","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Gross profit = $650,000 - $390,000 = $260,000, and Gross profit margin = ($260,000 / $650,000) × 100 = 40%.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because 15% is the profit margin ($97,500 / $650,000 × 100).","C":"Incorrect because 60% is cost of sales as a percentage of revenue ($390,000 / $650,000 × 100).","D":"Incorrect because 25% is overhead expenses as a percentage of revenue ($162,500 / $650,000 × 100)."}}},{"id":"P1_U5_MCQ_353","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_353","question":"A café chain's gross profit margin rose from 58% to 64% over the past year. Which change best explains this improvement?","options":{"A":"The chain negotiated cheaper wholesale coffee and food ingredient contracts while slightly raising menu prices","B":"The chain reduced its head-office marketing budget","C":"The chain repaid a 5-year bank loan early","D":"The chain sold an unused delivery van for cash"},"correctOption":"A","correctAnswer":"The chain negotiated cheaper wholesale coffee and food ingredient contracts while slightly raising menu prices","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because gross profit margin increases when selling prices rise relative to direct cost of sales (ingredients).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because marketing is an indirect overhead expense that affects profit margin, not gross profit margin.","C":"Incorrect because repaying a bank loan does not affect gross profit margin.","D":"Incorrect because selling a non-current asset does not affect gross profit margin."}}},{"id":"P1_U5_MCQ_354","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_354","question":"An interior design company generates annual revenue of $750,000, gross profit of $450,000, and final profit of $135,000. What is the company's profit margin?","options":{"A":"18%","B":"60%","C":"30%","D":"42%"},"correctOption":"A","correctAnswer":"18%","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Profit margin = (Profit / Revenue) × 100 = ($135,000 / $750,000) × 100 = 18%.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because 60% is the gross profit margin ($450,000 / $750,000 × 100).","C":"Incorrect because 30% divides profit by gross profit ($135,000 / $450,000 × 100) instead of dividing by revenue.","D":"Incorrect because 42% subtracts profit margin from gross profit margin (60% - 18%)."}}},{"id":"P1_U5_MCQ_355","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_355","question":"A supermarket's gross profit margin stayed unchanged at 26% for two consecutive years, yet its profit margin dropped from 8% to 4.5%. What does this indicate?","options":{"A":"Indirect overhead expenses such as store wages, energy bills, or rent increased faster than sales revenue","B":"The cost of groceries bought from suppliers doubled","C":"The supermarket's current ratio rose above 2 : 1","D":"The supermarket cut its retail grocery prices by half"},"correctOption":"A","correctAnswer":"Indirect overhead expenses such as store wages, energy bills, or rent increased faster than sales revenue","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a steady gross profit margin paired with a falling profit margin shows that expenses deducted below gross profit grew disproportionately.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because doubling supplier grocery costs would have reduced the gross profit margin.","C":"Incorrect because profitability margins do not measure the current ratio.","D":"Incorrect because cutting retail prices in half would have collapsed the gross profit margin."}}},{"id":"P1_U5_MCQ_356","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_356","question":"A packaging company earns an annual profit of $210,000, and its statement of financial position shows shareholders' equity of $900,000 and non-current liabilities of $500,000. What is the company's Return on Capital Employed (ROCE)?","options":{"A":"15%","B":"23.3%","C":"42%","D":"52.5%"},"correctOption":"A","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Capital employed = Equity ($900,000) + Non-current liabilities ($500,000) = $1,400,000, and ROCE = ($210,000 / $1,400,000) × 100 = 15%.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because 23.3% divides profit only by equity ($210,000 / $900,000 × 100), omitting non-current liabilities.","C":"Incorrect because 42% divides profit only by non-current liabilities ($210,000 / $500,000 × 100).","D":"Incorrect because 52.5% divides profit by the difference between equity and debt ($210,000 / $400,000 × 100)."}}},{"id":"P1_U5_MCQ_357","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_357","question":"What does Return on Capital Employed (ROCE) measure for investors and managers?","options":{"A":"The percentage profit generated for every $100 of long-term capital invested in the business","B":"The number of days it takes credit customers to pay their invoices","C":"The ability of current assets to cover immediate short-term debts","D":"The percentage of sales revenue left after deducting direct cost of sales"},"correctOption":"A","correctAnswer":"The percentage profit generated for every $100 of long-term capital invested in the business","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ROCE = (Profit / Capital employed) × 100, measuring how efficiently total long-term invested funds generate profit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because customer collection speed is measured by receivables days, not ROCE.","C":"Incorrect because short-term debt coverage is measured by liquidity ratios.","D":"Incorrect because gross profit as a percentage of revenue is the gross profit margin."}}},{"id":"P1_U5_MCQ_358","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_358","question":"A retail chain increases its annual profit from $150,000 to $195,000 while keeping its capital employed unchanged at $1,000,000. How does its ROCE change?","options":{"A":"ROCE rises from 15% to 19.5%","B":"ROCE falls from 19.5% to 15%","C":"ROCE stays unchanged at 15%","D":"ROCE rises to 45%"},"correctOption":"A","correctAnswer":"ROCE rises from 15% to 19.5%","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Year 1 ROCE = ($150,000 / $1,000,000) × 100 = 15%, and Year 2 ROCE = ($195,000 / $1,000,000) × 100 = 19.5%.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because profit increased rather than decreased, so ROCE improved.","C":"Incorrect because higher profit with constant capital employed raises ROCE.","D":"Incorrect because $45,000 is the dollar profit increase, which represents a 4.5 percentage point rise, not 45%."}}},{"id":"P1_U5_MCQ_359","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_359","question":"An electronics wholesaler has inventory of $60,000, trade receivables of $45,000, cash of $15,000, trade payables of $50,000, and a bank overdraft of $30,000. What is the wholesaler's current ratio?","options":{"A":"1.5 : 1","B":"0.75 : 1","C":"0.67 : 1","D":"2.4 : 1"},"correctOption":"A","correctAnswer":"1.5 : 1","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Current assets = $60,000 + $45,000 + $15,000 = $120,000 and Current liabilities = $50,000 + $30,000 = $80,000, giving Current ratio = $120,000 / $80,000 = 1.5 : 1.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because 0.75 : 1 is the acid-test ratio (($120,000 - $60,000) / $80,000).","C":"Incorrect because 0.67 : 1 divides current liabilities by current assets ($80,000 / $120,000).","D":"Incorrect because 2.4 : 1 omits the $30,000 bank overdraft from current liabilities ($120,000 / $50,000)."}}},{"id":"P1_U5_MCQ_360","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_360","question":"A restaurant group's current ratio has declined steadily over three years from 1.8 : 1 to 1.2 : 1 and now stands at 0.8 : 1. What does this trend show?","options":{"A":"The group's liquidity is deteriorating, and its short-term debts now exceed its current assets","B":"The group's gross profit margin has risen to 80%","C":"The group holds $1.80 of cash for every $1 of debt","D":"The group has paid off all of its trade payables"},"correctOption":"A","correctAnswer":"The group's liquidity is deteriorating, and its short-term debts now exceed its current assets","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a falling current ratio that drops below 1 : 1 warns that short-term liabilities are growing faster than current assets, creating insolvency risk.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the current ratio measures liquidity, not gross profit margin.","C":"Incorrect because 0.8 : 1 means $0.80 of current assets per $1 of current liabilities.","D":"Incorrect because paying off trade payables would improve rather than reduce a low current ratio."}}},{"id":"P1_U5_MCQ_361","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_361","question":"A furniture distributor has current assets of $195,000 (including $105,000 of inventory) and current liabilities of $75,000. What is the distributor's acid-test ratio?","options":{"A":"1.2 : 1","B":"2.6 : 1","C":"1.4 : 1","D":"0.83 : 1"},"correctOption":"A","correctAnswer":"1.2 : 1","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Acid-test ratio = (Current assets - Inventory) / Current liabilities = ($195,000 - $105,000) / $75,000 = $90,000 / $75,000 = 1.2 : 1.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because 2.6 : 1 is the current ratio ($195,000 / $75,000), which fails to remove inventory.","C":"Incorrect because 1.4 : 1 divides inventory by current liabilities ($105,000 / $75,000).","D":"Incorrect because 0.83 : 1 inverts the formula ($75,000 / $90,000)."}}},{"id":"P1_U5_MCQ_362","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_362","question":"A jeweller has a current ratio of 3.5 : 1, but its acid-test ratio is only 0.4 : 1. Why is the acid-test ratio so much lower than the current ratio?","options":{"A":"Because almost all of the jeweller's current assets consist of expensive, slow-moving inventory rather than cash or receivables","B":"Because the jeweller has zero current liabilities","C":"Because non-current assets are included in the current ratio","D":"Because the jeweller's profit margin is negative"},"correctOption":"A","correctAnswer":"Because almost all of the jeweller's current assets consist of expensive, slow-moving inventory rather than cash or receivables","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because subtracting inventory causes the ratio to plunge from 3.5 : 1 to 0.4 : 1, proving that high-value stock accounts for the vast majority of current assets.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because current liabilities are the denominator in both ratios.","C":"Incorrect because non-current assets are excluded from both liquidity ratios.","D":"Incorrect because liquidity ratios do not measure profit margins."}}},{"id":"P1_U5_MCQ_363","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_363","question":"An engineering firm's acid-test ratio has dropped to 0.65 : 1, worrying its bank manager. Which action would directly improve the firm's acid-test ratio?","options":{"A":"Selling unused factory machinery for cash or taking a long-term loan to pay off a short-term bank overdraft","B":"Using existing cash to purchase extra steel inventory","C":"Buying more steel inventory on 30-day trade credit","D":"Paying cash dividends to shareholders"},"correctOption":"A","correctAnswer":"Selling unused factory machinery for cash or taking a long-term loan to pay off a short-term bank overdraft","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because selling unwanted non-current assets increases cash (liquid assets), while replacing a short-term overdraft with a long-term loan reduces current liabilities.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because turning cash into inventory reduces the acid-test numerator (since inventory is excluded).","C":"Incorrect because buying inventory on credit increases current liabilities without raising liquid assets.","D":"Incorrect because paying cash dividends reduces cash and lowers the acid-test ratio."}}},{"id":"P1_U5_MCQ_364","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_364","question":"A supermarket currently has liquid assets (cash + receivables) of $90,000 and current liabilities of $90,000, giving an acid-test ratio of 1.0 : 1. If the supermarket uses $20,000 of its cash to buy fresh food inventory, what happens to its acid-test ratio?","options":{"A":"It falls from 1.0 : 1 to 0.78 : 1 because cash decreases by $20,000 while inventory is excluded from the acid-test numerator","B":"It stays at 1.0 : 1 because cash and inventory are both current assets","C":"It rises to 1.22 : 1","D":"It falls to 0 : 1"},"correctOption":"A","correctAnswer":"It falls from 1.0 : 1 to 0.78 : 1 because cash decreases by $20,000 while inventory is excluded from the acid-test numerator","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because liquid assets (excluding inventory) drop from $90,000 to $70,000 while current liabilities stay at $90,000, giving $70,000 / $90,000 = 0.78 : 1.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because while the current ratio stays at 1.0 : 1, the acid-test ratio excludes inventory.","C":"Incorrect because spending cash on inventory lowers rather than raises the acid-test ratio.","D":"Incorrect because $70,000 of liquid assets still remain."}}},{"id":"P1_U5_MCQ_365","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_365","question":"How do internal managers use profitability and liquidity ratios when planning next year's business strategy?","options":{"A":"To spot falling profit margins caused by rising costs, identify weak liquidity before cash runs out, and set departmental financial targets","B":"To calculate how much corporation tax rival companies owe","C":"To decide whether to approve personal bank loans for customers","D":"To replace the need for market research when launching new products"},"correctOption":"A","correctAnswer":"To spot falling profit margins caused by rising costs, identify weak liquidity before cash runs out, and set departmental financial targets","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because managers are internal users who rely on ratio trends to diagnose operational weaknesses, control expenses, and safeguard liquidity.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because tax assessment is carried out by external government tax authorities.","C":"Incorrect because personal loans are assessed by external commercial banks.","D":"Incorrect because financial ratios cannot replace primary or secondary market research."}}},{"id":"P1_U5_MCQ_366","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_366","question":"An investor owns shares in a pharmaceutical company and notices that its ROCE has fallen from 21% to 9% over two years while its profit margin halved. How is this ratio analysis likely to influence the investor?","options":{"A":"The investor may sell their shares and invest in a rival company offering a higher return on capital","B":"The investor will immediately increase the company's inventory levels","C":"The investor will grant the company a 10-year commercial mortgage","D":"The investor will reduce the company's corporation tax rate"},"correctOption":"A","correctAnswer":"The investor may sell their shares and invest in a rival company offering a higher return on capital","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because shareholders use profitability ratios to judge returns and management performance; falling ROCE often prompts investors to sell shares.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because outside shareholders do not manage day-to-day inventory levels.","C":"Incorrect because mortgages are provided by banks, not ordinary shareholders.","D":"Incorrect because tax rates are set by the government."}}},{"id":"P1_U5_MCQ_367","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_367","question":"A commercial bank is evaluating loan applications from two delivery firms: Firm X has a current ratio of 1.8 : 1 and an acid-test ratio of 1.3 : 1, while Firm Y has a current ratio of 0.7 : 1 and an acid-test ratio of 0.4 : 1. Which firm is a safer lending prospect for the bank?","options":{"A":"Firm X, because its strong liquidity ratios show it can comfortably pay short-term debts and regular loan interest","B":"Firm Y, because banks prefer lending to firms with liquidity ratios below 1 : 1","C":"Firm Y, because lower liquidity ratios automatically mean higher profit margins","D":"Neither firm, because banks never look at liquidity ratios when lending"},"correctOption":"A","correctAnswer":"Firm X, because its strong liquidity ratios show it can comfortably pay short-term debts and regular loan interest","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Firm X has healthy liquidity ratios within safe benchmarks, demonstrating lower risk of defaulting on loan repayments.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because ratios below 1 : 1 signal high default risk, which banks avoid.","C":"Incorrect because low liquidity ratios do not imply higher profit margins.","D":"Incorrect because liquidity ratios and existing debt are central to bank credit assessments."}}},{"id":"P1_U5_MCQ_368","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_368","question":"A flour mill receives a large credit order from a new bakery chain. Before granting 60 days of trade credit, the flour mill's credit controller checks the bakery's current ratio and acid-test ratio. Why?","options":{"A":"To check whether the bakery has enough liquid assets to pay the flour invoice on time in 60 days","B":"To calculate how many loaves of bread the bakery bakes per hour","C":"To decide whether to buy ordinary shares in the bakery","D":"To determine the bakery's corporation tax bill"},"correctOption":"A","correctAnswer":"To check whether the bakery has enough liquid assets to pay the flour invoice on time in 60 days","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because suppliers are external trade creditors who rely on a customer's short-term liquidity to ensure invoices are paid without bad-debt losses.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because hourly baking output is an internal production metric.","C":"Incorrect because a supplier wants prompt payment for goods, not equity ownership.","D":"Incorrect because tax calculations are handled by government tax authorities."}}},{"id":"P1_U5_MCQ_369","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_369","question":"During annual wage negotiations, a factory's trade union points to the company's rising profit margin (up from 9% to 15%) and strong liquidity ratios. How are employees using these financial accounts?","options":{"A":"To demonstrate that the company is financially secure and can afford to pay higher wages without threatening jobs","B":"To approve a new 15-year mortgage for the company","C":"To calculate the company's import customs duties","D":"To value the company's machinery for resale"},"correctOption":"A","correctAnswer":"To demonstrate that the company is financially secure and can afford to pay higher wages without threatening jobs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because employees and unions examine profitability and liquidity to assess job security and negotiate fair pay increases when profits grow.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because mortgages are approved by banks.","C":"Incorrect because customs duties are assessed by government authorities.","D":"Incorrect because machinery valuation is performed by accountants/valuers."}}},{"id":"P1_U5_MCQ_370","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_370","question":"Why do government departments and tax authorities require incorporated businesses to submit annual financial statements?","options":{"A":"To verify reported profits so the correct amount of corporation tax is collected and to monitor economic activity across industries","B":"To set the retail prices that private businesses must charge customers","C":"To decide which employees should be promoted inside private companies","D":"To guarantee that every company achieves an ROCE of at least 20%"},"correctOption":"A","correctAnswer":"To verify reported profits so the correct amount of corporation tax is collected and to monitor economic activity across industries","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because governments use company accounts to assess taxes accurately and track business sector performance and compliance.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because private firms set their own prices in market economies.","C":"Incorrect because internal promotions are HR decisions made by company managers.","D":"Incorrect because governments do not guarantee private sector ROCE."}}},{"id":"P1_U5_MCQ_371","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_371","question":"A student compares the gross profit margin of a luxury jewellery boutique (62%) with that of a discount grocery supermarket (18%) and concludes that the supermarket is poorly managed. Why is this comparison invalid?","options":{"A":"Ratios should only be compared between businesses in the same industry, because supermarkets operate on high-volume, low-margin models while luxury boutiques operate on low-volume, high-margin models","B":"Supermarkets are not allowed to calculate gross profit margin","C":"Jewellery boutiques do not have any cost of sales","D":"Gross profit margin can only be compared across companies in different countries"},"correctOption":"A","correctAnswer":"Ratios should only be compared between businesses in the same industry, because supermarkets operate on high-volume, low-margin models while luxury boutiques operate on low-volume, high-margin models","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because inter-industry ratio comparisons are misleading; different sectors have fundamentally different pricing, cost structures, and stock turnover speeds.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because supermarkets regularly calculate gross profit margin.","C":"Incorrect because jewellery boutiques incur high cost of sales for gold, diamonds, and watches.","D":"Incorrect because meaningful comparisons require businesses in the same sector."}}},{"id":"P1_U5_MCQ_372","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_372","question":"A travel agency published strong profit margins and liquidity ratios for the year ended 31 December, yet by March of the following year it entered bankruptcy after a volcanic eruption halted all international flights. Which limitation of accounting analysis does this demonstrate?","options":{"A":"Financial accounts are historical records of past performance and cannot foresee sudden external shocks or guarantee future success","B":"Published accounts are allowed to hide all current liabilities","C":"Ratio analysis only applies to manufacturing businesses","D":"Profit margins are calculated using future estimated sales"},"correctOption":"A","correctAnswer":"Financial accounts are historical records of past performance and cannot foresee sudden external shocks or guarantee future success","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because published financial statements look backward at past periods and cannot predict unexpected external disruptions.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because hiding liabilities in published accounts is illegal.","C":"Incorrect because ratio analysis is used across service, retail, and manufacturing sectors.","D":"Incorrect because published profit margins are based on historical actual results."}}},{"id":"P1_U5_MCQ_373","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_373","question":"Two rival logistics companies, FastFreight Ltd and SwiftHaul Ltd, earn identical annual profits of $120,000, but FastFreight values its older warehouses at historical cost ($400,000) while SwiftHaul revalues its identical warehouses at current market value ($800,000). How does this affect their ROCE comparison?","options":{"A":"FastFreight appears to have double the ROCE (30% vs 15%) purely due to different asset valuation methods rather than superior operational performance","B":"Both companies will still show the exact same ROCE","C":"SwiftHaul's gross profit margin will be twice as high as FastFreight's","D":"Asset valuation differences only affect the acid-test ratio"},"correctOption":"A","correctAnswer":"FastFreight appears to have double the ROCE (30% vs 15%) purely due to different asset valuation methods rather than superior operational performance","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because different accounting policies for valuing non-current assets change capital employed, distorting ROCE comparisons between firms.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because capital employed differs ($400,000 vs $800,000), producing different ROCE percentages.","C":"Incorrect because warehouse valuation sits on the statement of financial position and does not alter gross profit margin.","D":"Incorrect because non-current warehouse values are excluded from the acid-test ratio."}}},{"id":"P1_U5_MCQ_374","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_374","question":"A chemical manufacturer reports rising ROCE and healthy liquidity ratios, yet local communities are protesting toxic river pollution and customers are boycotting its products on social media. What limitation of relying purely on financial ratios does this highlight?","options":{"A":"Financial accounts ignore qualitative non-financial factors such as environmental impact, ethical reputation, and customer sentiment","B":"Ratios only measure short-term cash outflows","C":"Published accounts are prohibited from showing profit margins","D":"Liquidity ratios automatically include social media sentiment scores"},"correctOption":"A","correctAnswer":"Financial accounts ignore qualitative non-financial factors such as environmental impact, ethical reputation, and customer sentiment","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because accounting ratios capture purely quantitative financial data and miss critical non-financial risks like environmental damage and reputational backlash.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because profitability ratios measure profit relative to revenue or capital, not cash outflows.","C":"Incorrect because profit margins are routinely calculated from published statements.","D":"Incorrect because liquidity ratios only use current assets, inventory, and current liabilities."}}},{"id":"P1_U5_MCQ_375","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_375","question":"A company borrows a short-term cash sum the day before its financial year-end to inflate its closing cash balance on the statement of financial position, then repays it the next day. Why is this practice ('window dressing') a limitation when external stakeholders analyse accounts?","options":{"A":"It makes the business's liquidity appear stronger on the reporting date than it actually is during normal daily operations","B":"It permanently increases the company's gross profit margin by 50%","C":"It eliminates all non-current assets from the accounts","D":"It turns current liabilities into retained profit"},"correctOption":"A","correctAnswer":"It makes the business's liquidity appear stronger on the reporting date than it actually is during normal daily operations","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a statement of financial position is a single-day snapshot, so temporary year-end adjustments can distort liquidity ratios and mislead lenders or suppliers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because borrowing cash does not affect gross profit margin.","C":"Incorrect because non-current assets remain unaffected on the statement of financial position.","D":"Incorrect because borrowed funds are liabilities, not retained profit."}}},{"id":"P1_U5_MCQ_376","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_376","question":"An entrepreneur is launching a mobile pet-grooming business and needs $22,000 to register the business, buy grooming tables and clippers, and purchase initial shampoo supplies before serving her first client. What type of finance does she require?","options":{"A":"Trade credit from corporate customers","B":"Start-up capital","C":"Debt factoring finance","D":"Long-term expansion equity"},"correctOption":"B","correctAnswer":"Start-up capital","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because start-up capital is the finance needed by an entrepreneur to pay for initial set-up costs, essential equipment, and opening inventory before trading begins.","distractor_reasons":{"A":"Incorrect because trade credit is granted by suppliers to established buyers, not by customers.","B":"Correct selection.","C":"Incorrect because debt factoring sells existing unpaid customer invoices, which a pre-launch business does not yet have.","D":"Incorrect because expansion finance is used by established firms to grow, not to launch a new start-up."}}},{"id":"P1_U5_MCQ_377","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_377","question":"A profitable regional bakery chain plans to acquire a rival pastry manufacturer and build a new automated distribution warehouse. Which business financial need does this represent?","options":{"A":"Funding routine weekly wage bills","B":"Covering a temporary three-day overdraft","C":"Funding long-term business expansion","D":"Replacing a broken shop cash register"},"correctOption":"C","correctAnswer":"Funding long-term business expansion","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because taking over rival firms and constructing major facilities require large sums of long-term finance for business growth.","distractor_reasons":{"A":"Incorrect because weekly wages are short-term day-to-day working capital expenses.","B":"Incorrect because a three-day cash gap is a minor short-term liquidity fluctuation.","C":"Correct selection.","D":"Incorrect because replacing a single register is minor routine maintenance."}}},{"id":"P1_U5_MCQ_378","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_378","question":"Every October, a toy wholesaler must spend $90,000 extra on stock and temporary warehouse staff to prepare for peak holiday orders, even though retail stores will not pay their invoices until January. What type of finance is needed here?","options":{"A":"Additional working capital","B":"Start-up capital","C":"Freehold property mortgage","D":"Permanent share capital"},"correctOption":"A","correctAnswer":"Additional working capital","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because additional working capital is needed to fund seasonal increases in inventory and running costs while waiting for credit customers to pay.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the wholesaler is an established seasonal business, not a new start-up.","C":"Incorrect because a mortgage is used to purchase long-term land or buildings.","D":"Incorrect because permanent share capital is unsuitable for a temporary three-month seasonal cash gap."}}},{"id":"P1_U5_MCQ_379","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_379","question":"How do accountants and business managers distinguish between short-term finance and long-term finance?","options":{"A":"Short-term finance is used only by sole traders, while long-term finance is used only by public limited companies","B":"Short-term finance never incurs interest, while long-term finance always incurs interest","C":"Short-term finance is internal, while long-term finance is always external","D":"Short-term finance is required for up to one year to cover day-to-day operations, while long-term finance is required for more than one year to fund non-current assets or growth"},"correctOption":"D","correctAnswer":"Short-term finance is required for up to one year to cover day-to-day operations, while long-term finance is required for more than one year to fund non-current assets or growth","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the standard financial distinction is a one-year time horizon: under 12 months for working capital needs versus over 12 months for capital investment.","distractor_reasons":{"A":"Incorrect because businesses of all legal structures use both short-term and long-term finance.","B":"Incorrect because short-term sources like bank overdrafts do charge interest.","C":"Incorrect because short-term finance includes external sources like overdrafts and trade credit, while long-term finance includes internal retained profit."}}},{"id":"P1_U5_MCQ_380","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_380","question":"Why is retained profit unavailable as a source of finance for a brand-new start-up business?","options":{"A":"New businesses have not yet traded long enough to earn and accumulate past profits","B":"Government regulations forbid new businesses from keeping any profit for three years","C":"Retained profit can only be used to pay bank overdraft interest","D":"Retained profit is legally classified as a current liability"},"correctOption":"A","correctAnswer":"New businesses have not yet traded long enough to earn and accumulate past profits","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because retained profit comes from profits earned in previous trading years after tax and dividends, which a newly formed business does not yet possess.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because there is no law preventing new businesses from retaining profits once earned.","C":"Incorrect because retained profit can be reinvested in any area of the business.","D":"Incorrect because retained profit forms part of owners' or shareholders' equity."}}},{"id":"P1_U5_MCQ_381","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_381","question":"A manufacturing firm raises $55,000 internally by selling off surplus machinery and an unused storage yard. What is a potential disadvantage of raising finance through the sale of existing assets?","options":{"A":"The firm must pay high annual interest on the cash received","B":"It can take a long time to find a buyer, and the assets may sell for less than their book value","C":"The buyer gains voting shares in the manufacturing firm","D":"The cash received must be repaid to the buyer within 12 months"},"correctOption":"B","correctAnswer":"It can take a long time to find a buyer, and the assets may sell for less than their book value","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because non-current assets like machinery and property can be slow to sell, may fetch lower prices in urgent sales, and are no longer available if needed later.","distractor_reasons":{"A":"Incorrect because selling owned assets is internal finance and incurs no interest.","B":"Correct selection.","C":"Incorrect because asset buyers acquire physical equipment or land, not company shares.","D":"Incorrect because an outright asset sale generates permanent cash with no repayment obligation."}}},{"id":"P1_U5_MCQ_382","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_382","question":"A building supplies merchant frees up $40,000 of internal cash by reducing its warehouse inventory of bricks and timber to lower levels. What is a major risk of relying on inventory reduction to raise finance?","options":{"A":"The merchant may run out of stock during sudden demand surges and lose customers to rivals","B":"Warehouse storage and insurance costs will double","C":"The merchant's non-current liabilities will increase by $40,000","D":"Suppliers will be forced to pay interest to the merchant"},"correctOption":"A","correctAnswer":"The merchant may run out of stock during sudden demand surges and lose customers to rivals","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cutting inventory levels releases working capital cash and saves storage costs, but leaves less buffer stock to meet unexpected orders.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because holding smaller inventory lowers rather than increases storage and insurance costs.","C":"Incorrect because reducing inventory is an internal working capital adjustment that creates no debt.","D":"Incorrect because reducing inventory does not obligate suppliers to pay interest."}}},{"id":"P1_U5_MCQ_383","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_383","question":"Two partners running an independent architecture practice each invest $15,000 of their personal savings to buy new 3D-printing equipment. What is a key advantage of using owners' savings as a source of finance?","options":{"A":"It is quickly available without complex bank loan applications, incurs no interest charges, and keeps full control with the partners","B":"It gives the partners limited liability for all partnership debts","C":"It guarantees unlimited amounts of capital whenever the practice expands","D":"It is tax-deductible as an immediate operating expense"},"correctOption":"A","correctAnswer":"It is quickly available without complex bank loan applications, incurs no interest charges, and keeps full control with the partners","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because owners' personal savings are an internal source that avoids borrowing costs, collateral requirements, and external interference.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because ordinary partnerships still have unlimited liability regardless of how equipment is funded.","C":"Incorrect because owners' personal savings are usually limited in amount.","D":"Incorrect because capital injected by owners is equity, not an operating expense."}}},{"id":"P1_U5_MCQ_384","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_384","question":"A public limited company (plc) raises $25 million by issuing new ordinary shares on the stock exchange. What is a disadvantage of this source of finance for the existing shareholders?","options":{"A":"The company must repay the $25 million in cash within five years","B":"The company must pay fixed contractual interest every quarter even if it makes a loss","C":"Existing shareholders' percentage ownership and voting control are diluted, and future profits must be shared across more shares","D":"The company is barred from borrowing from commercial banks in the future"},"correctOption":"C","correctAnswer":"Existing shareholders' percentage ownership and voting control are diluted, and future profits must be shared across more shares","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because issuing additional ordinary shares spreads voting rights and dividend payouts over a larger share base, diluting original owners' control.","distractor_reasons":{"A":"Incorrect because ordinary share capital is permanent finance with no repayment date.","B":"Incorrect because dividends on ordinary shares are discretionary and depend on profits, unlike fixed loan interest.","C":"Correct selection.","D":"Incorrect because issuing shares reduces gearing and actually makes banks more willing to lend later."}}},{"id":"P1_U5_MCQ_385","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_385","question":"A logistics company takes out a 7-year bank loan of $300,000 at a fixed interest rate to buy four refrigerated trucks. What is a major advantage of a fixed-rate bank loan for the company's financial planning?","options":{"A":"Monthly repayments remain predictable throughout the seven years, making cash flow budgeting easier, and ownership control is unaffected","B":"The loan never has to be repaid if profits fall","C":"No collateral or security is ever requested by banks for large loans","D":"The company pays zero interest over the seven-year period"},"correctOption":"A","correctAnswer":"Monthly repayments remain predictable throughout the seven years, making cash flow budgeting easier, and ownership control is unaffected","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a fixed-rate loan provides certainty over regular repayment amounts for cash flow forecasting while keeping 100% ownership with the business.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because bank loans are legally binding obligations that must be repaid regardless of profit.","C":"Incorrect because banks usually require collateral (such as property or the trucks) to secure large loans.","D":"Incorrect because commercial bank loans always charge interest."}}},{"id":"P1_U5_MCQ_386","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_386","question":"A large public limited energy company raises $15 million by issuing debentures that pay 6% annual interest and mature in 12 years. How do debentures differ from ordinary shares?","options":{"A":"Debentures are long-term loan certificates that carry no voting rights and must be repaid at maturity with fixed interest","B":"Debenture holders become part-owners of the company with full voting rights at the AGM","C":"Debentures are short-term supplier invoices due within 30 days","D":"Debentures are non-repayable government grants"},"correctOption":"A","correctAnswer":"Debentures are long-term loan certificates that carry no voting rights and must be repaid at maturity with fixed interest","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because debentures are long-term debt instruments issued by companies; holders are creditors earning fixed interest rather than voting shareholders.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because ordinary shareholders hold voting ownership, whereas debenture holders are lenders.","C":"Incorrect because 30-day supplier invoices are trade credit.","D":"Incorrect because debentures are repayable long-term debt raised from investors."}}},{"id":"P1_U5_MCQ_387","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_387","question":"A clothing manufacturer sells $100,000 of unpaid retail store invoices to a debt factoring firm, receiving $85,000 in immediate cash while the factor collects the full $100,000 from the stores. Besides reducing profit by $15,000, what is another potential disadvantage of debt factoring?","options":{"A":"Aggressive debt collection methods used by the factoring firm could damage goodwill with loyal retail customers","B":"The manufacturer must give the factoring firm 40% of its ordinary shares","C":"The manufacturer must wait an extra 90 days before receiving any cash","D":"Debt factoring increases the manufacturer's non-current liabilities"},"correctOption":"A","correctAnswer":"Aggressive debt collection methods used by the factoring firm could damage goodwill with loyal retail customers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because handing customer invoice collection over to a third-party factor risks harsh payment chasing that can alienate valued buyers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because debt factoring is a commercial service fee arrangement, not an equity investment.","C":"Incorrect because factoring provides immediate cash upfront rather than delaying cash.","D":"Incorrect because factoring converts trade receivables into cash without creating long-term debt."}}},{"id":"P1_U5_MCQ_388","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_388","question":"A recycling company receives a $120,000 grant from a national environmental agency to install solar-powered sorting machinery. Which condition typically applies to grants from outside agencies?","options":{"A":"The money does not have to be repaid as long as the business uses it strictly for the approved project and meets set criteria","B":"The company must repay the grant with 12% compound interest over five years","C":"The agency takes permanent majority ownership of the recycling company","D":"The grant can be spent freely on shareholder dividends or executive cars"},"correctOption":"A","correctAnswer":"The money does not have to be repaid as long as the business uses it strictly for the approved project and meets set criteria","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because grants are non-repayable funds awarded by governments or agencies to support specific economic, social, or environmental goals.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because grants do not require repayment or interest unless the recipient breaches the grant conditions.","C":"Incorrect because grants are subsidies rather than equity purchases.","D":"Incorrect because grants are strictly ring-fenced for approved purposes such as green equipment or job creation."}}},{"id":"P1_U5_MCQ_389","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_389","question":"A small printing company relies heavily on a $25,000 bank overdraft throughout the year to pay staff and suppliers. Why is relying permanently on a large bank overdraft risky?","options":{"A":"The bank can demand full repayment of the overdraft at very short notice, and overdraft interest rates are usually high and variable","B":"Overdrafts require giving the bank a seat on the board of directors","C":"Overdrafts can only be used to buy freehold land and buildings","D":"Overdrafts are legally banned for private limited companies"},"correctOption":"A","correctAnswer":"The bank can demand full repayment of the overdraft at very short notice, and overdraft interest rates are usually high and variable","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because overdrafts are repayable on demand and carry relatively high variable interest rates, making them dangerous for long-term funding.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because banks do not join the board of directors when granting an overdraft.","C":"Incorrect because overdrafts are meant for short-term working capital, not long-term property purchases.","D":"Incorrect because private limited companies routinely use bank overdrafts."}}},{"id":"P1_U5_MCQ_390","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_390","question":"A supermarket chain buys $200,000 of packaged food on 60-day trade credit from a supplier instead of paying immediately, thereby forfeiting a 3% early-payment discount. What is the hidden cost of using this trade credit?","options":{"A":"The supermarket loses the $6,000 cash discount it would have saved by paying immediately","B":"The supermarket must pay 20% bank interest to the supplier","C":"The supermarket's non-current assets fall by $200,000","D":"The supplier becomes a shareholder in the supermarket"},"correctOption":"A","correctAnswer":"The supermarket loses the $6,000 cash discount it would have saved by paying immediately","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because while trade credit appears 'interest-free', missing out on a 3% prompt-payment discount ($200,000 × 3% = $6,000) is an effective financing cost.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because suppliers offer early-settlement discounts rather than charging 20% bank interest.","C":"Incorrect because packaged food is current inventory, not a non-current asset.","D":"Incorrect because trade credit creates a trade payable liability, not share ownership."}}},{"id":"P1_U5_MCQ_391","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_391","question":"Which comparison accurately distinguishes between a bank overdraft and debt factoring as short-term sources of finance?","options":{"A":"An overdraft borrows extra cash from a bank up to an agreed limit, whereas debt factoring sells existing unpaid customer invoices to a specialist firm for immediate cash","B":"An overdraft is a long-term mortgage, whereas debt factoring is an internal source of finance","C":"An overdraft is only available to plcs, whereas debt factoring is only available to sole traders","D":"An overdraft never charges interest, whereas debt factoring never charges a fee"},"correctOption":"A","correctAnswer":"An overdraft borrows extra cash from a bank up to an agreed limit, whereas debt factoring sells existing unpaid customer invoices to a specialist firm for immediate cash","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an overdraft is short-term bank borrowing, whereas debt factoring converts existing trade receivables into immediate cash at a discount.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because both are short-term external sources of finance.","C":"Incorrect because both are widely used by small and medium-sized trading businesses.","D":"Incorrect because overdrafts charge interest and factors charge service/discount fees."}}},{"id":"P1_U5_MCQ_392","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_392","question":"A hospital needs high-tech diagnostic scanners that become technologically outdated every four years, and it wants maintenance and repairs included in its monthly payments. Why is leasing better than hire purchase for this hospital?","options":{"A":"Leasing normally includes maintenance and lets the hospital upgrade to newer scanners at the end of the contract without owning obsolete equipment","B":"Leasing transfers permanent legal ownership of the scanners to the hospital on Day 1","C":"Leasing requires paying the entire purchase price upfront in cash","D":"Leasing is an internal source of finance"},"correctOption":"A","correctAnswer":"Leasing normally includes maintenance and lets the hospital upgrade to newer scanners at the end of the contract without owning obsolete equipment","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because leasing avoids obsolescence risk and includes servicing, whereas hire purchase results in owning equipment that may soon be outdated.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because legal ownership remains with the leasing company throughout and after the lease.","C":"Incorrect because leasing spreads payments over time with no large upfront capital outlay.","D":"Incorrect because leasing is provided by an external finance/leasing company."}}},{"id":"P1_U5_MCQ_393","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_393","question":"A microfinance institution lends $400 to a street-food vendor in a developing economy to buy a refrigerated cart. Why do microfinance loans often carry higher percentage interest rates than large corporate bank loans?","options":{"A":"Managing and collecting many tiny, unsecured loans involves high administrative costs relative to the small loan size","B":"Microfinance institutions are legally required to charge at least 90% interest","C":"Street-food vendors receive $400 in free company shares alongside the loan","D":"Microfinance loans last for 50 years without any repayments"},"correctOption":"A","correctAnswer":"Managing and collecting many tiny, unsecured loans involves high administrative costs relative to the small loan size","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because processing, monitoring, and collecting numerous small loans without collateral incurs high per-dollar administrative expenses.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because there is no statutory 90% interest floor.","C":"Incorrect because microfinance provides small loans, not share issues.","D":"Incorrect because microfinance loans are typically repaid in frequent small instalments over short periods."}}},{"id":"P1_U5_MCQ_394","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_394","question":"A start-up board-game designer launches a crowdfunding campaign to raise $30,000, offering backers an early copy of the game in exchange for pledges. Beyond raising money, what is a major marketing benefit of crowdfunding?","options":{"A":"It tests market demand before mass production and builds an engaged community of early customers","B":"It guarantees that competitors will never see the product idea","C":"It eliminates the need to manufacture or ship the board games","D":"It converts the start-up into a public limited company on a stock exchange"},"correctOption":"A","correctAnswer":"It tests market demand before mass production and builds an engaged community of early customers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because strong crowdfunding pledges prove genuine customer interest before committing to factory production and create word-of-mouth promotion.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because listing on a public crowdfunding platform exposes the idea to competitors.","C":"Incorrect because the creator still must produce and deliver the promised rewards to backers.","D":"Incorrect because reward-based crowdfunding does not list shares on a stock exchange."}}},{"id":"P1_U5_MCQ_395","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_395","question":"A property developer borrows money using a 6-month bank overdraft to buy land and construct an apartment block that will take three years to build and sell. Why is this a poor financing choice?","options":{"A":"Mismatch of time period: a long-term 3-year project should be funded with long-term finance, as the overdraft could be recalled before apartments are sold","B":"Apartment blocks are classified as short-term current assets","C":"Overdrafts can only be used by public limited companies","D":"Construction materials cannot be paid for using bank accounts"},"correctOption":"A","correctAnswer":"Mismatch of time period: a long-term 3-year project should be funded with long-term finance, as the overdraft could be recalled before apartments are sold","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because matching the time period of finance to the life of the project is vital; funding a multi-year build with short-term recallable debt creates severe liquidity risk.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a 3-year construction project requires long-term capital.","C":"Incorrect because businesses of any legal structure can use overdrafts.","D":"Incorrect because suppliers are routinely paid via bank transfers."}}},{"id":"P1_U5_MCQ_396","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_396","question":"A multinational airline wants to raise $800 million to purchase 15 new passenger aircraft. Why would a public share issue or debenture issue be considered instead of a bank overdraft or microfinance?","options":{"A":"Amount required: only capital markets (shares or debentures) can supply $800 million in long-term funds","B":"Airlines are legally forbidden from holding bank accounts","C":"Microfinance loans are restricted to amounts above $1 billion","D":"Share issues take less than 10 minutes to arrange with zero fees"},"correctOption":"A","correctAnswer":"Amount required: only capital markets (shares or debentures) can supply $800 million in long-term funds","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the scale of finance needed ($800 million) rules out small short-term facilities like overdrafts or microfinance.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because airlines obviously use commercial bank accounts.","C":"Incorrect because microfinance provides very small loans (typically hundreds or a few thousand dollars).","D":"Incorrect because public share and debenture issues involve substantial legal costs and preparation time."}}},{"id":"P1_U5_MCQ_397","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_397","question":"Why do commercial banks often charge higher interest rates—or demand personal collateral—when lending to a small newly established sole trader compared with an established public limited company?","options":{"A":"Small start-ups lack a proven trading track record and have higher failure rates, making lending riskier for the bank","B":"Sole traders are legally prohibited from repaying loans early","C":"Public limited companies are owned by the central bank","D":"Sole traders are not allowed to earn profits"},"correctOption":"A","correctAnswer":"Small start-ups lack a proven trading track record and have higher failure rates, making lending riskier for the bank","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because size and trading history influence perceived risk; smaller new firms pose higher default risk, prompting banks to charge higher rates or seek security.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because loan repayment terms are contractual, not banned by law.","C":"Incorrect because public limited companies are owned by private sector shareholders.","D":"Incorrect because sole traders are profit-seeking private businesses."}}},{"id":"P1_U5_MCQ_398","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_398","question":"The founders of a family-owned software company want to raise $500,000 for expansion, but they refuse to issue new shares to outside investors or accept venture capital. Which factor is driving their financing decision?","options":{"A":"Maintaining full ownership and decision-making control within the founding family","B":"A legal ban on private limited companies having retained profit","C":"A desire to maximize annual interest expenses","D":"The fact that software companies cannot take bank loans"},"correctOption":"A","correctAnswer":"Maintaining full ownership and decision-making control within the founding family","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because issuing external equity dilutes voting control, so owners prioritizing control favor retained profit or debt finance.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because private limited companies regularly use retained profit.","C":"Incorrect because businesses aim to minimize, not maximize, interest costs.","D":"Incorrect because software companies can apply for bank loans."}}},{"id":"P1_U5_MCQ_399","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_399","question":"An airline already has $900 million in long-term loans and debentures, compared with only $200 million in shareholders' equity. Why will directors likely choose a share issue rather than more borrowing to raise $150 million?","options":{"A":"Existing debt (gearing) is already very high, so taking on more loans would create dangerous fixed interest burdens during travel downturns","B":"Share issues never dilute existing shareholders' ownership","C":"Issuing shares is completely free of legal and administrative costs","D":"Banks are legally prohibited from lending to airlines"},"correctOption":"A","correctAnswer":"Existing debt (gearing) is already very high, so taking on more loans would create dangerous fixed interest burdens during travel downturns","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because high existing debt increases financial risk; raising equity avoids mandatory interest payments and strengthens the company's capital base.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because issuing new shares to outside investors does dilute existing ownership.","C":"Incorrect because share issues incur significant underwriting and legal fees.","D":"Incorrect because banks do lend to airlines when debt levels are manageable."}}},{"id":"P1_U5_MCQ_400","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_400","question":"A food-processing company funds a $500,000 factory upgrade using $180,000 of retained profit, $40,000 from selling old vans, $200,000 from a 10-year bank loan, $50,000 from a 6-month bank overdraft, and $30,000 from 30-day trade credit. How much external short-term finance was used?","options":{"A":"$80,000","B":"$280,000","C":"$220,000","D":"$50,000"},"correctOption":"A","correctAnswer":"$80,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because external short-term sources (repayable within one year) are the 6-month bank overdraft ($50,000) plus 30-day trade credit ($30,000) = $80,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $280,000 is total external finance, including the 10-year long-term bank loan ($200,000).","C":"Incorrect because $220,000 is total internal finance ($180,000 retained profit + $40,000 van sales).","D":"Incorrect because $50,000 omits the $30,000 of short-term trade credit."}}},{"id":"P1_U5_MCQ_401","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_401","question":"Why can a business with strong annual profits still be forced into liquidation if it runs out of cash?","options":{"A":"Workers, suppliers, and utility companies demand immediate payment in cash, not promises of future customer payments","B":"Profitable businesses are legally barred from using bank overdrafts","C":"Cash outflows are always double sales revenue in profitable firms","D":"Liquidation occurs automatically whenever gross profit exceeds $50,000"},"correctOption":"A","correctAnswer":"Workers, suppliers, and utility companies demand immediate payment in cash, not promises of future customer payments","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cash is the liquid medium required to settle immediate day-to-day obligations; if a business cannot pay debts as they fall due, creditors can force liquidation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because profitable businesses frequently use overdrafts to bridge working capital gaps.","C":"Incorrect because in profitable firms, total revenue exceeds total costs.","D":"Incorrect because earning a gross profit above $50,000 is positive, not a trigger for liquidation."}}},{"id":"P1_U5_MCQ_402","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_402","question":"Which list contains ONLY items that would be recorded as cash inflows on a manufacturing company's cash flow forecast?","options":{"A":"Cash sales, payments received from trade receivables, and receipt of a new bank loan","B":"Credit sales due in 60 days, depreciation of machinery, and retained profit","C":"Cash sales, wages paid to factory workers, and purchase of raw materials","D":"Payments to trade payables, corporation tax paid, and dividends paid"},"correctOption":"A","correctAnswer":"Cash sales, payments received from trade receivables, and receipt of a new bank loan","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cash sales, collections from credit customers, and bank loan drawdowns all bring actual money into the business's bank account.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because uncollected credit sales, depreciation (a non-cash accounting charge), and retained profit are not cash inflows.","C":"Incorrect because wages paid and raw material purchases are cash outflows.","D":"Incorrect because payments to suppliers, tax, and dividends are all cash outflows."}}},{"id":"P1_U5_MCQ_403","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_403","question":"Which list contains ONLY items that would be recorded as cash outflows on a retail store's cash flow forecast?","options":{"A":"Rent paid, wages paid, cash paid for inventory, and purchase of new checkout computers","B":"Cash sales, rent paid, and receipt of a government grant","C":"Inventory ordered on 60-day credit (not yet paid), wages paid, and electricity bills paid","D":"Payments from credit customers, bank loan interest paid, and owner's capital injection"},"correctOption":"A","correctAnswer":"Rent paid, wages paid, cash paid for inventory, and purchase of new checkout computers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because rent, wages, cash stock purchases, and equipment purchases all represent money leaving the business's bank account.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cash sales and government grants are cash inflows.","C":"Incorrect because inventory ordered on 60-day credit does not create a cash outflow until paid two months later.","D":"Incorrect because payments from credit customers and owner capital injections are cash inflows."}}},{"id":"P1_U5_MCQ_404","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_404","question":"In January, an IT consultancy invoices clients for $40,000 of work on 60-day credit terms, receives $15,000 from November credit clients, and records $2,000 of computer depreciation. How much cash inflow is entered on January's cash flow forecast?","options":{"A":"$15,000","B":"$55,000","C":"$57,000","D":"$40,000"},"correctOption":"A","correctAnswer":"$15,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because only the $15,000 collected from November clients enters the bank in January; January's $40,000 credit invoices arrive in March, and depreciation is non-cash.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $55,000 wrongly counts January's uncollected $40,000 credit invoices.","C":"Incorrect because $57,000 includes both uncollected credit invoices and non-cash depreciation.","D":"Incorrect because $40,000 is January credit revenue, not cash received in January."}}},{"id":"P1_U5_MCQ_405","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_405","question":"A stationery wholesaler forecasts total sales of $40,000 in April, $50,000 in May, and $60,000 in June. Customers pay 50% in cash at purchase, 30% one month later, and 20% two months later. What is the forecast cash inflow from sales in June?","options":{"A":"$53,000","B":"$60,000","C":"$45,000","D":"$30,000"},"correctOption":"A","correctAnswer":"$53,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because June receipts = 50% of June ($30,000) + 30% of May ($15,000) + 20% of April ($8,000) = $53,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $60,000 is total June sales revenue, half of which is collected in July and August.","C":"Incorrect because $45,000 omits the 20% collected from April sales ($8,000).","D":"Incorrect because $30,000 counts only June's immediate cash sales."}}},{"id":"P1_U5_MCQ_406","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_406","question":"A restaurant orders $10,000 of food ingredients in August on 30-day trade credit, pays $8,500 for July's food order, pays $9,000 in August staff wages, and pays $4,000 cash for a new commercial dishwasher in August. What are total cash outflows in August?","options":{"A":"$21,500","B":"$23,000","C":"$31,500","D":"$17,500"},"correctOption":"A","correctAnswer":"$21,500","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because August cash outflows = $8,500 (July food paid) + $9,000 (wages) + $4,000 (dishwasher) = $21,500 (August's $10,000 credit food order is paid in September).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $23,000 uses August's $10,000 credit order instead of July's $8,500 invoice paid in August.","C":"Incorrect because $31,500 counts both July's and August's food orders.","D":"Incorrect because $17,500 omits the $4,000 cash paid for the dishwasher."}}},{"id":"P1_U5_MCQ_407","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_407","question":"In February, a ski-equipment shop forecasts total cash inflows of $28,400 and total cash outflows of $34,900, starting with an opening balance of $9,000. What is the forecast net cash flow for February?","options":{"A":"-$6,500","B":"$2,500","C":"$6,500","D":"$63,300"},"correctOption":"A","correctAnswer":"-$6,500","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Net cash flow = Cash inflows - Cash outflows ($28,400 - $34,900 = -$6,500).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $2,500 is the closing balance ($9,000 opening - $6,500 net cash flow), not net cash flow.","C":"Incorrect because outflows exceed inflows, so net cash flow must be negative.","D":"Incorrect because $63,300 adds inflows and outflows together."}}},{"id":"P1_U5_MCQ_408","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_408","question":"A garden landscaping firm starts April with an opening cash balance of $3,200. During April, forecast cash inflows are $19,500 and cash outflows are $24,100. What is the firm's forecast closing cash balance at the end of April?","options":{"A":"-$1,400","B":"-$4,600","C":"$7,800","D":"$1,400"},"correctOption":"A","correctAnswer":"-$1,400","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because April net cash flow = $19,500 - $24,100 = -$4,600, and Closing balance = Opening balance + Net cash flow ($3,200 + (-$4,600) = -$1,400).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because -$4,600 is April's net cash flow and ignores the $3,200 opening balance.","C":"Incorrect because $7,800 adds the $4,600 deficit to the $3,200 opening balance.","D":"Incorrect because $3,200 - $4,600 results in a negative (overdrawn) balance of -$1,400."}}},{"id":"P1_U5_MCQ_409","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_409","question":"A small print shop starts November with an overdrawn opening balance of -$2,400. During November, cash inflows are $14,000 and cash outflows are $16,300. What is the closing cash balance at the end of November?","options":{"A":"-$4,700","B":"-$2,300","C":"$100","D":"$4,700"},"correctOption":"A","correctAnswer":"-$4,700","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because November net cash flow = $14,000 - $16,300 = -$2,300, and adding this to the -$2,400 opening overdraft gives a closing balance of -$4,700.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because -$2,300 is November's net cash flow and ignores the -$2,400 opening overdraft.","C":"Incorrect because $100 treats the opening overdraft as +$2,400 instead of -$2,400.","D":"Incorrect because both the opening balance and net cash flow are negative, making the closing balance -$4,700."}}},{"id":"P1_U5_MCQ_410","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_410","question":"A juice bar starts Month 1 with $5,000 cash. Net cash flow is +$1,200 in Month 1, -$2,800 in Month 2, and +$900 in Month 3. What is the juice bar's closing cash balance at the end of Month 3?","options":{"A":"$4,300","B":"$3,400","C":"$6,200","D":"-$700"},"correctOption":"A","correctAnswer":"$4,300","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Month 1 closing = $5,000 + $1,200 = $6,200; Month 2 closing = $6,200 - $2,800 = $3,400; Month 3 closing = $3,400 + $900 = $4,300.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $3,400 is Month 2's closing balance before adding Month 3's +$900 net cash flow.","C":"Incorrect because $6,200 is Month 1's closing balance.","D":"Incorrect because -$700 omits the $5,000 initial opening balance."}}},{"id":"P1_U5_MCQ_411","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_411","question":"In August, a bookstore has an opening cash balance of $4,500, total cash inflows of $21,000, and a closing cash balance of $6,200. What were the bookstore's total cash outflows in August?","options":{"A":"$19,300","B":"$22,700","C":"$14,800","D":"$25,500"},"correctOption":"A","correctAnswer":"$19,300","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Net cash flow = Closing balance - Opening balance ($6,200 - $4,500 = +$1,700), and Cash outflows = Cash inflows - Net cash flow ($21,000 - $1,700 = $19,300).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $22,700 adds the $1,700 net cash inflow to $21,000 instead of subtracting it.","C":"Incorrect because $14,800 subtracts closing balance from inflows ($21,000 - $6,200) and ignores the opening balance.","D":"Incorrect because $25,500 adds opening balance and inflows ($4,500 + $21,000)."}}},{"id":"P1_U5_MCQ_412","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_412","question":"Why is a cash flow forecast an essential part of a business plan when starting up a new company?","options":{"A":"It shows how much initial working capital is needed to survive early months before customer receipts cover ongoing costs","B":"It guarantees that the new company will earn a profit in Month 1","C":"It replaces the legal requirement to register the company with authorities","D":"It fixes supplier raw material prices for the next ten years"},"correctOption":"A","correctAnswer":"It shows how much initial working capital is needed to survive early months before customer receipts cover ongoing costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because start-ups experience high initial outflows and slow early receipts; a forecast calculates how much cash buffer is required to avoid early failure.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a forecast projects cash movements and cannot guarantee profitability.","C":"Incorrect because company registration is a separate legal obligation.","D":"Incorrect because forecasts estimate future costs rather than locking in supplier prices."}}},{"id":"P1_U5_MCQ_413","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_413","question":"A toy manufacturer's cash flow forecast shows large surplus cash balances of +$85,000 accumulating between January and April. How can managers use this forecast information effectively?","options":{"A":"Plan to pay off expensive loans early, buy raw materials in bulk for discounts, or place the surplus cash in an interest-earning deposit account","B":"Stop invoicing credit customers until May","C":"Ignore the surplus because cash balances reset to zero every quarter","D":"Ask the bank for an emergency high-interest overdraft"},"correctOption":"A","correctAnswer":"Plan to pay off expensive loans early, buy raw materials in bulk for discounts, or place the surplus cash in an interest-earning deposit account","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cash flow forecasts do not just spot deficits—they also reveal surplus cash so managers can put idle funds to productive use.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because delaying customer invoicing would harm liquidity and increase bad debt risk.","C":"Incorrect because cash balances carry forward continuously from month to month.","D":"Incorrect because a business with an $85,000 cash surplus does not need an emergency overdraft."}}},{"id":"P1_U5_MCQ_414","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_414","question":"Why do commercial banks almost always insist on seeing a 12-month cash flow forecast before approving a business loan or overdraft facility?","options":{"A":"To check the size and timing of expected cash deficits and verify that the business will generate enough future cash inflows to repay the debt","B":"To calculate the exact resale value of the owner's personal car","C":"Because banks are legally forbidden from reading statements of profit or loss","D":"To set the retail prices the business must charge its customers"},"correctOption":"A","correctAnswer":"To check the size and timing of expected cash deficits and verify that the business will generate enough future cash inflows to repay the debt","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because banks lend based on repayment ability; a credible cash flow forecast demonstrates how much borrowing is needed and when cash will be available for repayments.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because personal vehicle values are not shown on a business cash flow forecast.","C":"Incorrect because banks examine both historical profit statements and forward-looking cash flow forecasts.","D":"Incorrect because banks do not dictate a borrower's retail pricing."}}},{"id":"P1_U5_MCQ_415","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_415","question":"A kitchenware distributor discovers through its cash flow forecast that even though sales are rising, its cash balance is shrinking because credit customers take 75 days to pay while suppliers demand payment in 30 days. How is the forecast helping management?","options":{"A":"By highlighting an unsustainable working capital timing gap so managers can tighten customer credit control or negotiate longer supplier terms","B":"By proving that the distributor should stop selling kitchenware immediately","C":"By showing that gross profit margin has fallen to zero","D":"By eliminating the need to pay supplier invoices"},"correctOption":"A","correctAnswer":"By highlighting an unsustainable working capital timing gap so managers can tighten customer credit control or negotiate longer supplier terms","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because monitoring cash flow forecasts exposes cash trapped in slow trade receivables and guides timely corrective action.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because rising sales are positive once the credit timing gap is managed.","C":"Incorrect because cash timing differences do not mean gross profit margin is zero.","D":"Incorrect because supplier invoices remain legally payable."}}},{"id":"P1_U5_MCQ_416","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_416","question":"A building contractor takes out a new short-term bank loan to cover a three-month cash flow deficit. What is a limitation of using a bank loan to solve a cash flow problem?","options":{"A":"While it provides an immediate cash inflow, it increases future cash outflows through interest payments and principal repayments","B":"It immediately reduces the contractor's sales revenue","C":"It forces the contractor to give 50% of its profits to the bank forever","D":"Bank loans never improve short-term cash balances"},"correctOption":"A","correctAnswer":"While it provides an immediate cash inflow, it increases future cash outflows through interest payments and principal repayments","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a bank loan injects cash today, but the debt must be repaid with interest in subsequent months, adding future cash outflows.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because taking a loan does not lower sales revenue.","C":"Incorrect because loans charge interest rather than taking a permanent share of equity profits.","D":"Incorrect because receiving loan funds directly increases the immediate cash balance."}}},{"id":"P1_U5_MCQ_417","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_417","question":"To overcome a forecast cash deficit in May, a bakery negotiates with its flour and butter suppliers to extend payment terms from 30 days to 60 days. How does this resolve the May cash shortfall?","options":{"A":"It delays cash outflows into June, keeping cash inside the bakery during May","B":"It increases May cash inflows from bakery customers","C":"It permanently cancels the cost of flour and butter","D":"It converts trade payables into non-current assets"},"correctOption":"A","correctAnswer":"It delays cash outflows into June, keeping cash inside the bakery during May","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because extending supplier credit pushes cash outflows into a later month, relieving immediate liquidity pressure.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because supplier credit terms affect cash outflows, not customer cash inflows.","C":"Incorrect because the invoices must still be paid in full after 60 days.","D":"Incorrect because trade payables remain current liabilities until settled."}}},{"id":"P1_U5_MCQ_418","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_418","question":"An electrical wholesaler offers its credit customers a 2% cash discount if they settle their invoices within 7 days instead of waiting 45 days. How does this affect the wholesaler's cash flow and profit?","options":{"A":"It accelerates cash inflows into the business sooner, though the 2% discount slightly reduces profit margin","B":"It delays cash inflows by 38 days and doubles profit margin","C":"It increases monthly cash outflows for raw materials","D":"It eliminates all trade payables on the statement of financial position"},"correctOption":"A","correctAnswer":"It accelerates cash inflows into the business sooner, though the 2% discount slightly reduces profit margin","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because prompt-payment discounts incentivize trade receivables to pay faster, boosting short-term liquidity at the minor cost of the 2% discount.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cash arrives 38 days earlier, and giving a discount slightly lowers rather than doubles profit.","C":"Incorrect because customer discounts do not increase supplier material costs.","D":"Incorrect because customer discounts affect trade receivables, not trade payables."}}},{"id":"P1_U5_MCQ_419","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_419","question":"Facing a projected cash deficit over the next two quarters, a printing firm cancels its plan to buy a $65,000 digital press for cash and continues using its existing machines. What is the immediate impact on its cash flow forecast?","options":{"A":"Forecast cash outflows are reduced by $65,000, preventing or shrinking the cash deficit","B":"Forecast cash inflows rise by $65,000","C":"The firm's current liabilities double immediately","D":"The firm's gross profit falls by $65,000 this month"},"correctOption":"A","correctAnswer":"Forecast cash outflows are reduced by $65,000, preventing or shrinking the cash deficit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because delaying or cancelling capital expenditure eliminates a major cash outflow, directly improving net cash flow and closing cash balances.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cancelling an equipment purchase avoids a cash outflow rather than generating a cash inflow.","C":"Incorrect because cancelling a cash purchase creates no new liabilities.","D":"Incorrect because non-current asset purchases do not reduce gross profit."}}},{"id":"P1_U5_MCQ_420","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_420","question":"A courier company needs three new delivery vans costing $90,000 total, but buying them for cash would push its bank balance into a -$50,000 deficit. Instead, it leases the vans for $2,200 per month. How does leasing help manage cash flow?","options":{"A":"It replaces a single $90,000 cash outflow with smaller, predictable monthly outflows that can be funded from ongoing delivery receipts","B":"It increases monthly cash inflows by $90,000","C":"It eliminates all fuel and driver wage outflows","D":"It makes the total multi-year cost of the vans lower than buying them for cash"},"correctOption":"A","correctAnswer":"It replaces a single $90,000 cash outflow with smaller, predictable monthly outflows that can be funded from ongoing delivery receipts","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because leasing spreads payments evenly over time, avoiding a huge upfront capital drain on working capital.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because leasing involves rental outflows, not cash inflows.","C":"Incorrect because leased vans still require fuel and drivers.","D":"Incorrect because over the full term, total lease rentals usually exceed the cash purchase price."}}},{"id":"P1_U5_MCQ_421","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_421","question":"A supermarket chain facing severe short-term liquidity pressure sells its freehold store buildings to a property investment firm for $4 million cash and immediately signs a 20-year lease to continue operating in the same stores. How does this 'sale and leaseback' affect cash flow?","options":{"A":"It generates an immediate $4 million cash inflow to resolve the liquidity crisis, while introducing regular future rent outflows","B":"It eliminates all future rent and property expenses permanently","C":"It forces the supermarket to close all its stores immediately","D":"It increases current liabilities by $4 million"},"correctOption":"A","correctAnswer":"It generates an immediate $4 million cash inflow to resolve the liquidity crisis, while introducing regular future rent outflows","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sale and leaseback unlocks cash tied up in non-current property assets without disrupting operations, though ongoing lease rent increases future outflows.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because leasing the buildings back creates new annual rent payments.","C":"Incorrect because the supermarket continues trading in the exact same stores.","D":"Incorrect because selling an asset for cash boosts current assets (cash) rather than increasing current liabilities."}}},{"id":"P1_U5_MCQ_422","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_422","question":"Which sequence accurately illustrates the working capital cycle of a manufacturing business?","options":{"A":"Cash -> purchase raw materials -> produce finished goods -> sell on credit (trade receivables) -> collect cash from customers","B":"Cash -> issue ordinary shares -> buy freehold land -> pay corporation tax -> close factory","C":"Trade payables -> non-current liabilities -> depreciation -> retained profit -> dividends","D":"Customer cash -> bank overdraft -> fixed assets -> marketing -> liquidation"},"correctOption":"A","correctAnswer":"Cash -> purchase raw materials -> produce finished goods -> sell on credit (trade receivables) -> collect cash from customers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the working capital cycle shows how cash flows into materials and production, becomes inventory and trade receivables, and returns as cash when customers pay.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because share issues and freehold land are long-term capital transactions, not the routine working capital cycle.","C":"Incorrect because non-current liabilities and depreciation are not part of the short-term trading cash cycle.","D":"Incorrect because this does not represent the operational flow of current assets."}}},{"id":"P1_U5_MCQ_423","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_423","question":"In June, a carpentry business receives a $30,000 long-term bank loan into its bank account. How is this $30,000 treated in the cash flow forecast versus the statement of profit or loss?","options":{"A":"It is recorded as a $30,000 cash inflow in the cash flow forecast, but it is NOT recorded as revenue or profit on the statement of profit or loss","B":"It is recorded as $30,000 of sales revenue on the statement of profit or loss, but omitted from the cash flow forecast","C":"It is recorded as both $30,000 of profit and $30,000 of cash inflow","D":"It is recorded as a $30,000 cash outflow in the cash flow forecast"},"correctOption":"A","correctAnswer":"It is recorded as a $30,000 cash inflow in the cash flow forecast, but it is NOT recorded as revenue or profit on the statement of profit or loss","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because receiving a loan brings cash into the bank (cash inflow) while creating a repayable debt liability rather than earned trading revenue.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because loans are borrowed debt, not sales revenue.","C":"Incorrect because borrowing money does not generate profit.","D":"Incorrect because receiving loan funds increases cash (inflow), whereas repaying a loan is an outflow."}}},{"id":"P1_U5_MCQ_424","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_424","question":"A bakery spends $42,000 in cash to purchase a new delivery van. Why does this $42,000 payment reduce the bakery's closing cash balance immediately without reducing its gross profit by $42,000?","options":{"A":"Buying a van is a capital cash outflow on the cash flow forecast, whereas on the statement of financial position it simply exchanges cash for a non-current asset rather than being a direct cost of sales","B":"Delivery vans are paid for using trade receivables rather than cash","C":"Gross profit is calculated before deducting any costs at all","D":"Accountants ignore vehicle purchases until the van is sold"},"correctOption":"A","correctAnswer":"Buying a van is a capital cash outflow on the cash flow forecast, whereas on the statement of financial position it simply exchanges cash for a non-current asset rather than being a direct cost of sales","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because purchasing a non-current asset drains cash immediately on the cash flow forecast, while only gradual depreciation (not the full $42,000 purchase price) is charged as an expense over the van's life.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the scenario states the van was purchased in cash.","C":"Incorrect because gross profit deducts direct cost of sales from revenue.","D":"Incorrect because the van is recorded immediately under non-current assets on the statement of financial position."}}},{"id":"P1_U5_MCQ_425","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_425","question":"A travel company's actual closing cash balance in August turns out to be -$11,000 instead of the +$6,000 predicted in its cash flow forecast prepared six months earlier. Which factor best explains why such variances occur?","options":{"A":"Cash flow forecasts rely on estimates of future sales and costs, which can be disrupted by unexpected fuel price spikes, currency shifts, or slower customer payments","B":"Cash flow forecasts are legally required to exclude utility bills and wages","C":"Closing balances on a cash flow forecast never include opening balances","D":"Banks randomly change a company's historical sales figures"},"correctOption":"A","correctAnswer":"Cash flow forecasts rely on estimates of future sales and costs, which can be disrupted by unexpected fuel price spikes, currency shifts, or slower customer payments","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because forecasts are projections based on assumptions; unforeseen market or cost changes cause actual cash flows to differ from estimates.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because wages and utility bills are always included in forecast outflows.","C":"Incorrect because closing balance always equals opening balance plus net cash flow.","D":"Incorrect because banks do not alter a company's accounting records."}}},{"id":"P1_U5_MCQ_426","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_426","question":"How is 'profit' fundamentally defined for a trading business over a financial year?","options":{"A":"The positive financial surplus remaining when total revenue exceeds total costs over a trading period","B":"The exact amount of physical cash sitting in the business's safe on 31 December","C":"The total amount of money borrowed from commercial banks during the year","D":"Total revenue minus only the cost of buying non-current assets"},"correctOption":"A","correctAnswer":"The positive financial surplus remaining when total revenue exceeds total costs over a trading period","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because profit measures trading surplus (Total revenue - Total costs) over an accounting period.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cash in the safe is a liquid asset, whereas profit includes credit transactions and excludes loans or asset purchases.","C":"Incorrect because borrowed loans are liabilities, not profit.","D":"Incorrect because non-current asset purchases are capital expenditure, not deducted from revenue to find profit."}}},{"id":"P1_U5_MCQ_427","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_427","question":"Why is earning consistent profit crucial for a private limited company seeking to grow without taking on heavy debt?","options":{"A":"Retained profit provides an interest-free internal source of finance for expansion and demonstrates business success to attract investors","B":"Earning profit automatically exempts the company from paying corporation tax","C":"Profit guarantees that the company will never face a cash shortage","D":"High profit forces competitors to leave the industry by law"},"correctOption":"A","correctAnswer":"Retained profit provides an interest-free internal source of finance for expansion and demonstrates business success to attract investors","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because profit rewards owners, signals viability, and generates retained profit to fund growth internally without debt or dilution.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because profitable companies must pay corporation tax on their profits.","C":"Incorrect because profitable firms can still suffer cash crises if receivables pay late.","D":"Incorrect because high profits actually attract new competitors into a market."}}},{"id":"P1_U5_MCQ_428","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_428","question":"A fair-trade chocolate social enterprise reinvests 85% of its annual surplus into building schools for cocoa-farming communities. Why is generating profit still vital to this organisation?","options":{"A":"Without profit, the social enterprise cannot remain financially self-sustaining or fund its community school-building mission","B":"Social enterprises are legally required to pay 100% of profits to stock-market speculators","C":"Profit allows social enterprises to pay workers below the legal minimum wage","D":"Social enterprises are fined by the government if they break even"},"correctOption":"A","correctAnswer":"Without profit, the social enterprise cannot remain financially self-sustaining or fund its community school-building mission","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because social enterprises use business trading profits to survive independently and finance their social or environmental objectives.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because social enterprises reinvest surpluses into their social mission rather than maximizing private dividends.","C":"Incorrect because social enterprises must obey employment laws and typically prioritize fair wages.","D":"Incorrect because breaking even is not penalized by law."}}},{"id":"P1_U5_MCQ_429","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_429","question":"During the year, a bicycle shop sells 600 mountain bikes at $450 each and 300 road bikes at $700 each, while also receiving a $50,000 bank loan. What is the shop's revenue on its statement of profit or loss?","options":{"A":"$480,000","B":"$530,000","C":"$270,000","D":"$210,000"},"correctOption":"A","correctAnswer":"$480,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Revenue = (600 × $450) + (300 × $700) = $270,000 + $210,000 = $480,000 (the $50,000 bank loan is a liability, not sales revenue).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $530,000 wrongly includes the $50,000 bank loan in sales revenue.","C":"Incorrect because $270,000 is only the revenue from mountain bikes.","D":"Incorrect because $210,000 is only the revenue from road bikes."}}},{"id":"P1_U5_MCQ_430","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_430","question":"On a retail clothing store's statement of profit or loss, what does 'cost of sales' represent?","options":{"A":"The direct purchase cost to the store of the specific garments sold to customers during the year","B":"The annual salary of the store's human resources director","C":"The cost of buying a new freehold shop building","D":"Interest paid on a long-term bank loan"},"correctOption":"A","correctAnswer":"The direct purchase cost to the store of the specific garments sold to customers during the year","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because for a retailer, cost of sales is the direct wholesale cost of the goods actually sold during the trading period.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because HR salaries are indirect overhead expenses.","C":"Incorrect because buying a freehold shop is capital expenditure on a non-current asset.","D":"Incorrect because loan interest is a finance expense deducted after gross profit."}}},{"id":"P1_U5_MCQ_431","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_431","question":"At the start of the year, a hardware shop held opening inventory worth $35,000. During the year, it purchased $190,000 of goods for resale, and at year-end it held closing inventory worth $45,000. What was the shop's cost of sales for the year?","options":{"A":"$180,000","B":"$200,000","C":"$270,000","D":"$190,000"},"correctOption":"A","correctAnswer":"$180,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Cost of sales = Opening inventory + Purchases - Closing inventory ($35,000 + $190,000 - $45,000 = $180,000).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $200,000 subtracts opening inventory and adds closing inventory ($190,000 - $35,000 + $45,000).","C":"Incorrect because $270,000 adds all three figures together instead of subtracting unsold closing inventory.","D":"Incorrect because $190,000 is purchases alone and ignores the $10,000 net increase in unsold inventory."}}},{"id":"P1_U5_MCQ_432","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_432","question":"A furniture retailer records annual sales revenue of $840,000, opening inventory of $60,000, purchases of $490,000, closing inventory of $70,000, and overhead expenses of $210,000. What is the retailer's gross profit?","options":{"A":"$360,000","B":"$150,000","C":"$350,000","D":"$630,000"},"correctOption":"A","correctAnswer":"$360,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Cost of sales = $60,000 + $490,000 - $70,000 = $480,000, and Gross profit = Revenue - Cost of sales ($840,000 - $480,000 = $360,000).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $150,000 is the final profit after deducting $210,000 of overhead expenses ($360,000 - $210,000).","C":"Incorrect because $350,000 subtracts purchases ($490,000) directly from revenue without adjusting for opening and closing inventory.","D":"Incorrect because $630,000 subtracts overhead expenses from revenue instead of cost of sales."}}},{"id":"P1_U5_MCQ_433","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_433","question":"Which group of costs is classified under 'overhead expenses' (rather than cost of sales) on a manufacturer's statement of profit or loss?","options":{"A":"Head-office administrative salaries, marketing campaigns, and warehouse insurance","B":"Direct raw steel and direct factory assembly wages","C":"Opening inventory of finished goods and raw material purchases","D":"Purchase of a new freehold factory building"},"correctOption":"A","correctAnswer":"Head-office administrative salaries, marketing campaigns, and warehouse insurance","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because administrative salaries, advertising, and insurance are indirect running expenses deducted from gross profit to find profit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because direct raw materials and direct production wages are part of cost of sales.","C":"Incorrect because inventory and material purchases form part of cost of sales.","D":"Incorrect because buying a freehold factory is capital expenditure on a non-current asset."}}},{"id":"P1_U5_MCQ_434","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_434","question":"A sports retailer achieves revenue of $920,000, cost of sales of $540,000, and indirect overhead expenses of $265,000. What is the retailer's profit for the year?","options":{"A":"$115,000","B":"$380,000","C":"$655,000","D":"$805,000"},"correctOption":"A","correctAnswer":"$115,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Gross profit = $920,000 - $540,000 = $380,000, and Profit = Gross profit - Overhead expenses ($380,000 - $265,000 = $115,000).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $380,000 is gross profit before deducting $265,000 of overhead expenses.","C":"Incorrect because $655,000 deducts only overhead expenses from revenue and omits cost of sales.","D":"Incorrect because $805,000 adds cost of sales and overhead expenses together ($540,000 + $265,000)."}}},{"id":"P1_U5_MCQ_435","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_435","question":"At the bottom of a public limited company's statement of profit or loss, how is profit after tax divided (appropriated)?","options":{"A":"Between dividends paid out to shareholders and retained profit kept inside the company for reinvestment","B":"Between cost of sales and overhead expenses","C":"Between current assets and current liabilities","D":"Between opening inventory and closing inventory"},"correctOption":"A","correctAnswer":"Between dividends paid out to shareholders and retained profit kept inside the company for reinvestment","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because after corporation tax is deducted, remaining profit is either distributed to shareholders as dividends or retained in the business as retained profit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cost of sales and overhead expenses are deducted earlier to arrive at profit before tax.","C":"Incorrect because assets and liabilities appear on the statement of financial position.","D":"Incorrect because inventories are used earlier to calculate cost of sales."}}},{"id":"P1_U5_MCQ_436","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_436","question":"A packaging company reports revenue of $1,200,000, cost of sales of $720,000, overhead expenses of $280,000, corporation tax of $40,000, and dividends paid of $65,000. What is the company's retained profit for the year?","options":{"A":"$95,000","B":"$160,000","C":"$200,000","D":"$480,000"},"correctOption":"A","correctAnswer":"$95,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Gross profit = $1,200,000 - $720,000 = $480,000; Profit before tax = $480,000 - $280,000 = $200,000; Profit after tax = $200,000 - $40,000 = $160,000; Retained profit = $160,000 - $65,000 = $95,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $160,000 is profit after tax before deducting $65,000 of dividends.","C":"Incorrect because $200,000 is profit before tax and dividends.","D":"Incorrect because $480,000 is gross profit."}}},{"id":"P1_U5_MCQ_437","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_437","question":"A damaged statement of profit or loss shows cost of sales of $310,000, overhead expenses of $115,000, and final profit of $65,000. What were the business's gross profit and total revenue?","options":{"A":"Gross profit: $180,000; Revenue: $490,000","B":"Gross profit: $50,000; Revenue: $360,000","C":"Gross profit: $180,000; Revenue: $130,000","D":"Gross profit: $375,000; Revenue: $490,000"},"correctOption":"A","correctAnswer":"Gross profit: $180,000; Revenue: $490,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Gross profit = Final profit + Overhead expenses ($65,000 + $115,000 = $180,000), and Revenue = Gross profit + Cost of sales ($180,000 + $310,000 = $490,000).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $50,000 subtracts final profit from overhead expenses instead of adding them.","C":"Incorrect because $130,000 subtracts gross profit from cost of sales instead of adding them.","D":"Incorrect because $375,000 adds cost of sales and final profit ($310,000 + $65,000) instead of overhead expenses and final profit."}}},{"id":"P1_U5_MCQ_438","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_438","question":"A luxury watchmaker increases its selling prices by 10% and sees unit sales fall by only 2% because wealthy customers are insensitive to price changes. How does this affect total revenue and profit?","options":{"A":"Total revenue and profit both increase because the 10% price rise outweighs the tiny 2% drop in unit volume","B":"Gross profit falls because cost of sales increases by 10%","C":"Overhead expenses rise by 10% automatically","D":"Total revenue falls by 12%"},"correctOption":"A","correctAnswer":"Total revenue and profit both increase because the 10% price rise outweighs the tiny 2% drop in unit volume","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because when demand is price inelastic, raising selling prices boosts total revenue while slightly lower unit volume even lowers total cost of sales, increasing profit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because raising retail prices does not increase supplier cost of sales per watch.","C":"Incorrect because fixed overhead expenses do not rise when retail prices increase.","D":"Incorrect because 1.10 × 0.98 = 1.078, representing a 7.8% increase in revenue."}}},{"id":"P1_U5_MCQ_439","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_439","question":"To reduce cost of sales and boost gross profit, a gourmet burger chain switches to a much cheaper beef supplier. What is the main commercial risk of this cost-cutting measure?","options":{"A":"Lower meat quality may disappoint regular diners, harming brand reputation and causing future sales revenue to fall","B":"Cheaper beef automatically doubles fixed restaurant rent","C":"Gross profit margin will immediately drop to 0%","D":"The burger chain will have to pay more corporation tax even if revenue collapses"},"correctOption":"A","correctAnswer":"Lower meat quality may disappoint regular diners, harming brand reputation and causing future sales revenue to fall","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cutting direct material costs can improve short-term gross margin, but sacrificing quality drives away repeat customers.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because supplier beef prices do not change fixed property rent.","C":"Incorrect because cheaper beef lowers cost of sales and raises gross profit margin initially.","D":"Incorrect because corporation tax is charged as a percentage of actual profit earned."}}},{"id":"P1_U5_MCQ_440","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_440","question":"An accounting consultancy reduces its annual profit decline by moving from an expensive city-centre office to a lower-rent suburban office park. How does this decision affect its statement of profit or loss?","options":{"A":"Overhead expenses decrease, increasing final profit while leaving gross profit unchanged","B":"Cost of sales decreases and gross profit rises","C":"Sales revenue increases automatically","D":"Share capital increases on the statement of profit or loss"},"correctOption":"A","correctAnswer":"Overhead expenses decrease, increasing final profit while leaving gross profit unchanged","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because office rent is an indirect overhead expense; lowering it directly increases final profit without altering gross profit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because office rent is an indirect overhead rather than a direct cost of sales.","C":"Incorrect because moving to a cheaper office does not automatically increase client fee revenue.","D":"Incorrect because share capital appears on the statement of financial position, not the statement of profit or loss."}}},{"id":"P1_U5_MCQ_441","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_441","question":"A fitness equipment brand spends $25,000 on an online advertising campaign. As a result, sales revenue rises by $80,000, while direct manufacturing cost of sales rises by $42,000. What is the net impact on the brand's final profit?","options":{"A":"Final profit increases by $13,000","B":"Final profit increases by $38,000","C":"Final profit increases by $55,000","D":"Final profit decreases by $25,000"},"correctOption":"A","correctAnswer":"Final profit increases by $13,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because extra gross profit = $80,000 revenue - $42,000 cost of sales = $38,000, and subtracting the $25,000 advertising expense yields a net profit gain of $13,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $38,000 is the increase in gross profit before deducting the $25,000 advertising expense.","C":"Incorrect because $55,000 subtracts advertising from revenue ($80,000 - $25,000) and forgets the $42,000 extra cost of sales.","D":"Incorrect because the $38,000 gross profit gain exceeds the $25,000 ad spend."}}},{"id":"P1_U5_MCQ_442","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_442","question":"Comparing Year 1 and Year 2 statements of profit or loss, a clothing retailer sees revenue stay constant at $500,000, overhead expenses stay constant at $120,000, and final profit fall from $130,000 to $90,000. What caused the $40,000 drop in profit?","options":{"A":"Cost of sales increased by $40,000 (from $250,000 to $290,000), reducing gross profit by $40,000","B":"Overhead expenses increased by $40,000","C":"Revenue fell by $40,000","D":"Shareholders withdrew $40,000 in share capital"},"correctOption":"A","correctAnswer":"Cost of sales increased by $40,000 (from $250,000 to $290,000), reducing gross profit by $40,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because since revenue ($500,000) and overhead expenses ($120,000) were unchanged, the $40,000 fall in profit must have come from a $40,000 rise in cost of sales.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the question states overhead expenses stayed constant at $120,000.","C":"Incorrect because the question states revenue stayed constant at $500,000.","D":"Incorrect because share capital changes do not appear on the statement of profit or loss."}}},{"id":"P1_U5_MCQ_443","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_443","question":"A restaurant group reviews branch-level profit statements: City Bistro earns $400,000 revenue, $140,000 cost of sales, and $190,000 branch expenses; Airport Café earns $350,000 revenue, $120,000 cost of sales, and $140,000 branch expenses. Which branch contributes more final profit?","options":{"A":"Airport Café contributes $90,000 profit compared with $70,000 from City Bistro","B":"City Bistro contributes $260,000 profit compared with $230,000 from Airport Café","C":"Both branches contribute the exact same final profit of $70,000","D":"City Bistro is making a loss of -$50,000"},"correctOption":"A","correctAnswer":"Airport Café contributes $90,000 profit compared with $70,000 from City Bistro","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Airport Café profit = $350,000 - $120,000 - $140,000 = $90,000, exceeding City Bistro's profit of $400,000 - $140,000 - $190,000 = $70,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $260,000 and $230,000 are gross profits before deducting branch overhead expenses.","C":"Incorrect because $90,000 is $20,000 higher than $70,000.","D":"Incorrect because City Bistro earns a positive profit of $70,000."}}},{"id":"P1_U5_MCQ_444","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_444","question":"A phone-case seller currently sells 10,000 cases at $20 each (unit cost of sales $8, fixed overheads $70,000). If cutting the price to $16 boosts sales volume to 15,000 cases while unit cost and fixed overheads stay unchanged, how does profit change?","options":{"A":"Profit stays unchanged at $50,000 ($120,000 gross profit minus $70,000 overheads in both cases)","B":"Profit rises from $50,000 to $90,000","C":"Profit falls from $50,000 to $10,000","D":"Profit rises from $120,000 to $170,000"},"correctOption":"A","correctAnswer":"Profit stays unchanged at $50,000 ($120,000 gross profit minus $70,000 overheads in both cases)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because initially: ($200,000 revenue - $80,000 cost of sales) - $70,000 overheads = $50,000 profit; after price cut: ($240,000 revenue - $120,000 cost of sales) - $70,000 overheads = $50,000 profit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $90,000 forgets that unit cost of sales ($8) applies to the 5,000 extra cases sold ($40,000 extra cost).","C":"Incorrect because total gross profit stayed at $120,000 (($16 - $8) × 15,000).","D":"Incorrect because $120,000 is gross profit before deducting $70,000 of overheads."}}},{"id":"P1_U5_MCQ_445","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_445","question":"When deciding how to divide profit after tax between dividends and retained profit, what conflict must a public limited company's directors balance?","options":{"A":"Paying generous dividends keeps current shareholders happy and supports the share price, whereas retaining profit funds long-term growth without borrowing","B":"Paying dividends increases corporation tax to 100%","C":"Retained profit must be handed over to competitors at year-end","D":"Dividends are subtracted before calculating gross profit"},"correctOption":"A","correctAnswer":"Paying generous dividends keeps current shareholders happy and supports the share price, whereas retaining profit funds long-term growth without borrowing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because directors must balance shareholders' desire for immediate dividend income against the company's need for internal retained capital to invest in future expansion.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because dividends are paid out of after-tax profit and do not raise corporation tax rates.","C":"Incorrect because retained profit stays inside the company as reserves.","D":"Incorrect because dividends are appropriated at the very bottom after profit after tax."}}},{"id":"P1_U5_MCQ_446","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_446","question":"How do potential investors use a company's statement of profit or loss before deciding whether to buy its shares?","options":{"A":"To examine revenue growth, cost control, and after-tax profit trends to judge likely future dividends and share value growth","B":"To verify the exact street addresses of all retail suppliers","C":"To check whether the company has any physical premises","D":"To replace the statement of financial position when checking long-term mortgages"},"correctOption":"A","correctAnswer":"To examine revenue growth, cost control, and after-tax profit trends to judge likely future dividends and share value growth","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because investors evaluate historical profitability trends to assess management efficiency and expected returns on their investment.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because supplier street addresses are not listed in financial statements.","C":"Incorrect because physical property assets appear on the statement of financial position.","D":"Incorrect because mortgages appear on the statement of financial position."}}},{"id":"P1_U5_MCQ_447","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_447","question":"When reviewing a statement of profit or loss, why does a bank manager check profit before interest and tax alongside existing loan interest expenses?","options":{"A":"To see whether the business generates enough operating profit to comfortably cover existing and proposed interest charges","B":"To calculate how many employees work in the marketing department","C":"To determine whether the business holds enough raw material inventory","D":"To set the government's national corporation tax rate"},"correctOption":"A","correctAnswer":"To see whether the business generates enough operating profit to comfortably cover existing and proposed interest charges","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because lenders assess whether trading profits provide a safe margin above contractual interest obligations.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because headcount is not calculated from interest figures.","C":"Incorrect because inventory levels are shown on the statement of financial position.","D":"Incorrect because governments set tax rates, not commercial bank managers."}}},{"id":"P1_U5_MCQ_448","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_448","question":"Why do employees and trade unions examine their employer's annual statement of profit or loss?","options":{"A":"To assess job security and use strong profit growth as evidence when negotiating higher pay or bonuses","B":"To decide whether to approve a new share issue on the stock exchange","C":"To calculate the exact depreciation rate of factory computers","D":"To assess whether the company's customers are paying on 30-day credit"},"correctOption":"A","correctAnswer":"To assess job security and use strong profit growth as evidence when negotiating higher pay or bonuses","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sustained profits reassure workers about job stability and strengthen union arguments for pay rises.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because new share issues are approved by shareholders and directors, not employees.","C":"Incorrect because depreciation policies are set by company accountants.","D":"Incorrect because customer credit periods are analyzed from trade receivables on the statement of financial position."}}},{"id":"P1_U5_MCQ_449","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_449","question":"Why is a raw-material supplier interested in a customer's statement of profit or loss in addition to its statement of financial position?","options":{"A":"A profitable customer is likely to stay in business and continue placing repeat orders over the long term","B":"Suppliers collect a percentage of their customers' retained profit by law","C":"The statement of profit or loss shows the customer's exact daily bank balance","D":"Suppliers use it to calculate their own corporation tax bill"},"correctOption":"A","correctAnswer":"A profitable customer is likely to stay in business and continue placing repeat orders over the long term","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because suppliers want reliable, ongoing trading partners; consistent profitability signals long-term business survival and repeat orders.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because suppliers are paid for goods delivered, not a share of customer profits.","C":"Incorrect because bank balances appear on the statement of financial position and cash records.","D":"Incorrect because a supplier pays tax on its own profits, not its customers' profits."}}},{"id":"P1_U5_MCQ_450","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_450","question":"Which statement describes a key limitation of relying solely on a company's statement of profit or loss to judge its overall health?","options":{"A":"It records past trading profit rather than cash liquidity, so a company reporting high profits could still be close to running out of cash","B":"It illegally omits all overhead expenses in public limited companies","C":"It only records transactions where physical banknotes changed hands","D":"It can only be prepared once every five years"},"correctOption":"A","correctAnswer":"It records past trading profit rather than cash liquidity, so a company reporting high profits could still be close to running out of cash","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the statement of profit or loss measures profitability over a past period and does not show cash balances, liquidity, or debt obligations.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because all overhead expenses must be included by law.","C":"Incorrect because credit sales and accrued expenses are included regardless of when cash moves.","D":"Incorrect because statements of profit or loss are prepared at least annually."}}},{"id":"P1_U5_MCQ_451","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_451","question":"Why is a statement of financial position often described as a 'financial snapshot' rather than a video of the whole year?","options":{"A":"Because it records the exact value of a business's assets, liabilities, and equity at one specific point in time (such as 31 December)","B":"Because it only includes photographs of the company's factories and vehicles","C":"Because it measures total sales revenue earned across all 12 months","D":"Because its figures never change from one year to the next"},"correctOption":"A","correctAnswer":"Because it records the exact value of a business's assets, liabilities, and equity at one specific point in time (such as 31 December)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because unlike the statement of profit or loss (which covers a period of time), the statement of financial position shows balances on a single reporting date.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because it is a numerical financial statement, not a collection of photographs.","C":"Incorrect because total sales revenue over 12 months appears on the statement of profit or loss.","D":"Incorrect because asset, liability, and reserve balances change continuously as the business trades."}}},{"id":"P1_U5_MCQ_452","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_452","question":"Which item on an airline's statement of financial position is classified as a 'non-current asset'?","options":{"A":"Passenger aircraft and airport maintenance hangars owned by the airline","B":"Jet fuel inventory stored for next week's flights","C":"Ticket payments owed by corporate travel agencies within 30 days","D":"A 12-year bank loan used to finance fleet expansion"},"correctOption":"A","correctAnswer":"Passenger aircraft and airport maintenance hangars owned by the airline","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because aircraft and hangars are long-term physical resources owned and used for more than 12 months to generate revenue.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because jet fuel inventory is a short-term current asset.","C":"Incorrect because money owed by travel agencies is trade receivables (a current asset).","D":"Incorrect because a 12-year bank loan is a non-current liability."}}},{"id":"P1_U5_MCQ_453","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_453","question":"Which group consists ENTIRELY of 'current assets' on a manufacturing business's statement of financial position?","options":{"A":"Raw material inventory, finished goods inventory, trade receivables, and cash at bank","B":"Factory land, delivery vans, and cash at bank","C":"Trade receivables, trade payables, and cash in hand","D":"Bank overdraft, raw material inventory, and retained profit"},"correctOption":"A","correctAnswer":"Raw material inventory, finished goods inventory, trade receivables, and cash at bank","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because inventories, trade receivables, and cash are all short-term resources expected to be used or converted into cash within one year.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because factory land and delivery vans are non-current assets.","C":"Incorrect because trade payables are a current liability, not an asset.","D":"Incorrect because a bank overdraft is a current liability and retained profit is equity."}}},{"id":"P1_U5_MCQ_454","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_454","question":"In what order are current assets normally listed on a standard statement of financial position from least liquid to most liquid?","options":{"A":"Inventories -> Trade receivables -> Cash and cash equivalents","B":"Cash and cash equivalents -> Trade receivables -> Inventories","C":"Trade receivables -> Cash and cash equivalents -> Inventories","D":"Inventories -> Cash and cash equivalents -> Trade receivables"},"correctOption":"A","correctAnswer":"Inventories -> Trade receivables -> Cash and cash equivalents","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because inventories must first be sold (often on credit) to become trade receivables, which are then collected to become cash—the most liquid asset.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because this lists them from most liquid to least liquid.","C":"Incorrect because cash is more liquid than both trade receivables and inventories.","D":"Incorrect because trade receivables convert into cash sooner than unsold inventories."}}},{"id":"P1_U5_MCQ_455","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_455","question":"Which pair of items represents 'current liabilities' on a retail company's statement of financial position?","options":{"A":"Trade payables owed to stock suppliers and a short-term bank overdraft","B":"Trade receivables owed by customers and cash in the till","C":"A 20-year mortgage and issued share capital","D":"Shop display shelving and retained profit"},"correctOption":"A","correctAnswer":"Trade payables owed to stock suppliers and a short-term bank overdraft","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because trade payables and bank overdrafts are short-term debts that must be settled within 12 months.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because trade receivables and cash are current assets.","C":"Incorrect because a 20-year mortgage is a non-current liability and share capital is equity.","D":"Incorrect because display shelving is a non-current asset and retained profit is equity."}}},{"id":"P1_U5_MCQ_456","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_456","question":"Which item is classified as a 'non-current liability' on a company's statement of financial position?","options":{"A":"A 10-year commercial mortgage borrowed to purchase a warehouse","B":"Unpaid electricity bills due next month","C":"Retained profit accumulated over five years","D":"Freehold land owned by the company"},"correctOption":"A","correctAnswer":"A 10-year commercial mortgage borrowed to purchase a warehouse","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a 10-year mortgage is a long-term debt obligation repayable over more than one year.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because bills due next month are current liabilities.","C":"Incorrect because retained profit is part of shareholders' equity, not a debt.","D":"Incorrect because freehold land is a non-current asset."}}},{"id":"P1_U5_MCQ_457","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_457","question":"On a limited company's statement of financial position, which two items are added together to calculate 'Total shareholders' equity'?","options":{"A":"Share capital and retained profit (reserves)","B":"Non-current assets and current assets","C":"Current liabilities and non-current liabilities","D":"Gross profit and overhead expenses"},"correctOption":"A","correctAnswer":"Share capital and retained profit (reserves)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because shareholders' equity represents the owners' total financial stake in the company, comprising original share capital plus accumulated retained profits.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because non-current assets plus current assets equals total assets.","C":"Incorrect because current liabilities plus non-current liabilities equals total liabilities.","D":"Incorrect because gross profit and overhead expenses appear on the statement of profit or loss."}}},{"id":"P1_U5_MCQ_458","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_458","question":"A bakery's statement of financial position shows inventories of $12,000, trade receivables of $8,500, cash of $4,500, trade payables of $11,000, and a bank overdraft of $3,500. What is the bakery's net current assets (working capital)?","options":{"A":"$10,500","B":"$14,000","C":"$39,500","D":"$6,000"},"correctOption":"A","correctAnswer":"$10,500","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Current assets = $12,000 + $8,500 + $4,500 = $25,000 and Current liabilities = $11,000 + $3,500 = $14,500, so Working capital = $25,000 - $14,500 = $10,500.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $14,000 omits the $3,500 bank overdraft from current liabilities ($25,000 - $11,000).","C":"Incorrect because $39,500 adds current assets and current liabilities ($25,000 + $14,500).","D":"Incorrect because $6,000 omits the $4,500 cash balance from current assets ($20,500 - $14,500)."}}},{"id":"P1_U5_MCQ_459","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_459","question":"A printing company has non-current assets of $520,000, current assets of $110,000, current liabilities of $65,000, and non-current liabilities of $195,000. What is the value of the company's net assets?","options":{"A":"$370,000","B":"$565,000","C":"$630,000","D":"$260,000"},"correctOption":"A","correctAnswer":"$370,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Net assets = Total assets ($520,000 + $110,000 = $630,000) - Total liabilities ($65,000 + $195,000 = $260,000) = $370,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $565,000 is capital employed ($630,000 - $65,000), which has not deducted non-current liabilities.","C":"Incorrect because $630,000 is total assets before deducting any liabilities.","D":"Incorrect because $260,000 is total liabilities, not net assets."}}},{"id":"P1_U5_MCQ_460","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_460","question":"A food-processing company has share capital of $400,000, retained profit of $250,000, non-current liabilities of $350,000, and current liabilities of $90,000. What is the company's capital employed?","options":{"A":"$1,000,000","B":"$650,000","C":"$1,090,000","D":"$750,000"},"correctOption":"A","correctAnswer":"$1,000,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Capital employed = Total shareholders' equity ($400,000 + $250,000 = $650,000) + Non-current liabilities ($350,000) = $1,000,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $650,000 is shareholders' equity alone, omitting non-current liabilities.","C":"Incorrect because $1,090,000 wrongly includes short-term current liabilities ($90,000).","D":"Incorrect because $750,000 omits retained profit ($400,000 + $350,000)."}}},{"id":"P1_U5_MCQ_461","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_461","question":"On a company's statement of financial position, non-current assets are $410,000, inventories are $30,000, trade receivables are $25,000, current liabilities are $40,000, non-current liabilities are $120,000, share capital is $200,000, and retained profit is $120,000. What must the missing cash balance be for the statement to balance?","options":{"A":"$15,000","B":"$55,000","C":"$70,000","D":"$0"},"correctOption":"A","correctAnswer":"$15,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Total equity = $200,000 + $120,000 = $320,000; Net assets must equal $320,000, so Total assets = $320,000 + $120,000 + $40,000 = $480,000; Cash = $480,000 - ($410,000 + $30,000 + $25,000) = $15,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $55,000 forgets to include the $40,000 current liabilities in total assets.","C":"Incorrect because $70,000 is total current assets ($30,000 + $25,000 + $15,000), not cash alone.","D":"Incorrect because without $15,000 of cash, total assets ($465,000) would not match total liabilities and equity ($480,000)."}}},{"id":"P1_U5_MCQ_462","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_462","question":"A private limited company issues 50,000 new ordinary shares at $2 each, receiving $100,000 cash into its bank current account. How does this transaction immediately change the company's statement of financial position?","options":{"A":"Current assets (cash) increase by $100,000 and shareholders' equity (share capital) increases by $100,000","B":"Current assets (cash) increase by $100,000 and non-current liabilities increase by $100,000","C":"Non-current assets increase by $100,000 and current liabilities increase by $100,000","D":"Working capital decreases by $100,000"},"correctOption":"A","correctAnswer":"Current assets (cash) increase by $100,000 and shareholders' equity (share capital) increases by $100,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because receiving cash from shareholders boosts cash (+$100,000 current asset) and increases issued share capital (+$100,000 equity).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because issuing ordinary shares raises equity, not long-term debt liabilities.","C":"Incorrect because cash is a current asset and share capital is equity.","D":"Incorrect because current assets rise by $100,000 while current liabilities stay unchanged, so working capital increases by $100,000."}}},{"id":"P1_U5_MCQ_463","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_463","question":"A manufacturing firm borrows $160,000 via a 6-year bank loan and immediately spends the entire $160,000 to buy automated packaging machinery. What is the net effect on the statement of financial position?","options":{"A":"Non-current assets increase by $160,000 and non-current liabilities increase by $160,000","B":"Current assets increase by $160,000 and shareholders' equity increases by $160,000","C":"Working capital increases by $160,000","D":"Non-current assets increase by $160,000 and current liabilities increase by $160,000"},"correctOption":"A","correctAnswer":"Non-current assets increase by $160,000 and non-current liabilities increase by $160,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the packaging machinery adds $160,000 to non-current assets, while the 6-year loan adds $160,000 to non-current liabilities.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the cash was spent on machinery, and loans create liabilities rather than equity.","C":"Incorrect because neither current assets nor current liabilities changed on net.","D":"Incorrect because a 6-year bank loan is a non-current liability, not a current liability."}}},{"id":"P1_U5_MCQ_464","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_464","question":"A clothing store uses $14,000 from its bank current account to pay off an overdue supplier invoice (trade payable). How does this payment affect the store's statement of financial position?","options":{"A":"Current assets (cash) decrease by $14,000 and current liabilities (trade payables) decrease by $14,000, leaving working capital unchanged","B":"Working capital decreases by $14,000","C":"Shareholders' equity decreases by $14,000","D":"Non-current assets decrease by $14,000"},"correctOption":"A","correctAnswer":"Current assets (cash) decrease by $14,000 and current liabilities (trade payables) decrease by $14,000, leaving working capital unchanged","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because paying a supplier reduces cash (-$14,000 current asset) and eliminates the debt (-$14,000 current liability), leaving Net current assets unchanged.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because both current assets and current liabilities fall by the exact same $14,000.","C":"Incorrect because paying an existing liability does not reduce shareholders' equity.","D":"Incorrect because cash is a current asset, not a non-current asset."}}},{"id":"P1_U5_MCQ_465","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_465","question":"During the year, a profitable design agency earns $45,000 in retained profit, all of which stays in its bank current account at year-end. How does this retained profit appear on the year-end statement of financial position?","options":{"A":"It increases the cash balance under current assets by $45,000 and increases the retained profit reserve under shareholders' equity by $45,000","B":"It increases non-current liabilities by $45,000","C":"It reduces share capital by $45,000","D":"It is recorded only as a current liability owed to customers"},"correctOption":"A","correctAnswer":"It increases the cash balance under current assets by $45,000 and increases the retained profit reserve under shareholders' equity by $45,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because retained profit belongs to the owners (increasing equity reserves) while the cash earned sits in current assets (or other assets acquired).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because retained profit is owners' equity, not an external debt liability.","C":"Incorrect because retained profit adds to equity rather than reducing share capital.","D":"Incorrect because retained profit is not owed to customers."}}},{"id":"P1_U5_MCQ_466","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_466","question":"An electronics shop sells a batch of laptops that cost $10,000 for $14,000 in immediate cash. How does this sale change the shop's statement of financial position?","options":{"A":"Inventory falls by $10,000, cash rises by $14,000, and retained profit (equity) rises by the $4,000 profit","B":"Inventory falls by $14,000 and cash rises by $10,000","C":"Total assets remain completely unchanged","D":"Current liabilities increase by $4,000"},"correctOption":"A","correctAnswer":"Inventory falls by $10,000, cash rises by $14,000, and retained profit (equity) rises by the $4,000 profit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because total assets rise by $4,000 net (+$14,000 cash minus -$10,000 inventory at cost), balanced by the $4,000 profit added to shareholders' equity.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because inventory is valued at its $10,000 cost, while cash received is the $14,000 selling price.","C":"Incorrect because total assets increase by $4,000 when goods are sold above cost.","D":"Incorrect because selling goods for cash creates no liability."}}},{"id":"P1_U5_MCQ_467","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_467","question":"A toy retailer's statement of financial position shows inventories of $180,000, trade receivables of $15,000, cash of $2,000, and a bank overdraft of $95,000. What liquidity issue does this reveal?","options":{"A":"The retailer has too much cash tied up in unsold toy inventory and lacks liquid cash to cover its large bank overdraft","B":"The retailer holds excessive idle cash in its bank current account","C":"The retailer has zero short-term liabilities","D":"The retailer's non-current liabilities exceed its non-current assets"},"correctOption":"A","correctAnswer":"The retailer has too much cash tied up in unsold toy inventory and lacks liquid cash to cover its large bank overdraft","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because $180,000 is locked in slow-moving stock while cash is only $2,000 against a $95,000 overdraft, signaling overstocking and poor liquidity.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cash is only $2,000 alongside a $95,000 overdraft.","C":"Incorrect because a $95,000 bank overdraft is a substantial current liability.","D":"Incorrect because non-current figures are not mentioned and the problem lies in working capital."}}},{"id":"P1_U5_MCQ_468","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_468","question":"Examining a hotel chain's statement of financial position, an analyst sees non-current liabilities of $2,400,000 and total shareholders' equity of $600,000. What risk does this capital structure highlight?","options":{"A":"High reliance on long-term borrowing (high gearing), leaving the chain vulnerable to rising interest rates or falling tourist demand","B":"The hotel chain has no non-current assets","C":"The hotel chain cannot accept credit card payments from guests","D":"Shareholders' equity is four times larger than long-term debt"},"correctOption":"A","correctAnswer":"High reliance on long-term borrowing (high gearing), leaving the chain vulnerable to rising interest rates or falling tourist demand","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because non-current liabilities ($2.4m) are four times larger than shareholders' equity ($0.6m), meaning the business is heavily debt-financed with high fixed interest commitments.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because hotel chains typically hold substantial property under non-current assets.","C":"Incorrect because debt structure does not prevent accepting card payments.","D":"Incorrect because long-term debt ($2.4m) is four times larger than equity ($0.6m), not the reverse."}}},{"id":"P1_U5_MCQ_469","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_469","question":"Over four years, a software company's retained profit reserve on its statement of financial position grew steadily from $80,000 to $490,000 while its bank loans fell to zero. What does this trend show?","options":{"A":"The company has been consistently profitable, reinvested earnings to grow its net worth, and strengthened its financial stability","B":"The company has been making continuous losses every year","C":"The company paid out 100% of its profits as dividends every year","D":"The company's current liabilities have quadrupled"},"correctOption":"A","correctAnswer":"The company has been consistently profitable, reinvested earnings to grow its net worth, and strengthened its financial stability","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because rising retained profit reserves paired with eliminated debt demonstrate sustained profitability and internal wealth accumulation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because losses erode rather than build retained profit reserves.","C":"Incorrect because paying out 100% of profits as dividends would leave retained profit unchanged.","D":"Incorrect because bank loans fell to zero rather than quadrupling."}}},{"id":"P1_U5_MCQ_470","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_470","question":"Before approving a $500,000 10-year loan for a haulage company, why does a bank inspect the company's non-current assets and non-current liabilities on its statement of financial position?","options":{"A":"To check whether the company owns valuable unencumbered property or vehicles to act as collateral and how much long-term debt it already owes","B":"To calculate the company's gross profit margin on fuel sales","C":"To decide which truck drivers should receive annual bonuses","D":"To replace the need for a cash flow forecast"},"correctOption":"A","correctAnswer":"To check whether the company owns valuable unencumbered property or vehicles to act as collateral and how much long-term debt it already owes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because banks assess non-current assets for potential loan security and non-current liabilities to measure existing long-term debt burdens.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because gross profit margin is calculated from the statement of profit or loss.","C":"Incorrect because driver bonuses are internal HR decisions.","D":"Incorrect because banks examine both the statement of financial position and cash flow forecasts."}}},{"id":"P1_U5_MCQ_471","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_471","question":"A timber wholesaler is deciding whether to extend 60-day trade credit to a furniture manufacturer. Looking at the manufacturer's statement of financial position, which combination would reassure the wholesaler?","options":{"A":"Current assets that comfortably exceed current liabilities, including a healthy cash balance","B":"Zero current assets and large overdue trade payables","C":"A large bank overdraft exceeding total current assets","D":"Negative working capital of -$80,000"},"correctOption":"A","correctAnswer":"Current assets that comfortably exceed current liabilities, including a healthy cash balance","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because positive working capital and strong cash reserves indicate the manufacturer can pay supplier invoices on time.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because zero current assets and overdue payables signal high default risk.","C":"Incorrect because a massive overdraft indicates severe cash strain.","D":"Incorrect because negative working capital warns that short-term debts exceed short-term assets."}}},{"id":"P1_U5_MCQ_472","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_472","question":"A multinational food group is considering buying out a smaller snack-food company. How does the snack-food company's statement of financial position assist the buyer?","options":{"A":"It shows the net asset value of the target company's factories, equipment, inventory, and cash minus all debts that the buyer will inherit","B":"It guarantees how many new snack flavours customers will buy next year","C":"It shows the personal bank balances of the target company's factory workers","D":"It eliminates the need to negotiate a takeover price"},"correctOption":"A","correctAnswer":"It shows the net asset value of the target company's factories, equipment, inventory, and cash minus all debts that the buyer will inherit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because acquiring a company means taking over its assets and liabilities; net assets provide a baseline valuation of the business.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because historical financial positions do not guarantee future product demand.","C":"Incorrect because employee personal finances are not part of company accounts.","D":"Incorrect because net asset value informs valuation negotiations rather than replacing them."}}},{"id":"P1_U5_MCQ_473","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_473","question":"A family bakery bought its freehold shop building 25 years ago for $120,000, and it is still listed at that historical cost on its statement of financial position, even though local property prices have tripled. What limitation of financial statements does this illustrate?","options":{"A":"Assets recorded at historical cost minus depreciation may differ significantly from their true current market resale value","B":"Freehold buildings are illegally omitted from statements of financial position","C":"Buildings are classified as short-term current liabilities","D":"Historical cost accounting overstates cash in the bank"},"correctOption":"A","correctAnswer":"Assets recorded at historical cost minus depreciation may differ significantly from their true current market resale value","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because accounting conventions often value non-current assets based on historical purchase cost rather than current market prices, understating true property worth.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because freehold buildings are included under non-current assets.","C":"Incorrect because owned buildings are non-current assets, not liabilities.","D":"Incorrect because historical property valuation does not alter the cash balance."}}},{"id":"P1_U5_MCQ_474","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_474","question":"Why might a statement of financial position dated 31 December give a misleading impression of a seasonal ski-resort hotel's typical financial position?","options":{"A":"Because 31 December falls during peak winter holiday season when cash balances are unusually high compared with quiet summer months","B":"Because hotels are legally allowed to omit all bank loans on 31 December","C":"Because non-current assets disappear during winter months","D":"Because statements of financial position never balance on 31 December"},"correctOption":"A","correctAnswer":"Because 31 December falls during peak winter holiday season when cash balances are unusually high compared with quiet summer months","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a single-day snapshot reflects seasonal peaks or troughs and may not represent average liquidity throughout the year.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because all liabilities must be reported accurately on the balance sheet date.","C":"Incorrect because hotel buildings and equipment remain throughout the year.","D":"Incorrect because statements of financial position always balance regardless of the date."}}},{"id":"P1_U5_MCQ_475","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_475","question":"A world-famous software firm's most valuable competitive strengths are its patented algorithms, loyal user base, and highly skilled engineers, yet these do not appear fully on its statement of financial position. Why?","options":{"A":"Financial statements only record items that can be reliably measured in monetary terms, omitting qualitative human capital and internally built brand loyalty","B":"Software firms are legally prohibited from preparing statements of financial position","C":"Skilled engineers are recorded as non-current liabilities","D":"Customer loyalty is deducted from gross profit on the statement of profit or loss"},"correctOption":"A","correctAnswer":"Financial statements only record items that can be reliably measured in monetary terms, omitting qualitative human capital and internally built brand loyalty","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because standard accounting statements capture tangible and quantifiable monetary figures while excluding intangible human and reputational strengths.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because incorporated software firms must prepare full financial statements.","C":"Incorrect because employees are not recorded as liabilities on the balance sheet.","D":"Incorrect because customer loyalty is not an expense."}}},{"id":"P1_U5_MCQ_476","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_476","question":"What are the two main types of comparison that businesses and investors perform using financial ratios?","options":{"A":"Comparing a business's ratios over time (trend analysis) and comparing them with competitors in the same industry (inter-firm comparison)","B":"Comparing a local bakery's ratios with a multinational oil company and a hospital","C":"Comparing cash inflows with the number of factory windows","D":"Comparing historical share prices with employee birthdays"},"correctOption":"A","correctAnswer":"Comparing a business's ratios over time (trend analysis) and comparing them with competitors in the same industry (inter-firm comparison)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ratios become meaningful when tracked across consecutive years for the same firm or benchmarked against direct industry rivals.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because comparing businesses across completely different industries is invalid.","C":"Incorrect because physical building features are not financial ratio benchmarks.","D":"Incorrect because personal biographical dates are irrelevant to financial analysis."}}},{"id":"P1_U5_MCQ_477","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_477","question":"A book retailer reports annual revenue of $480,000, cost of sales of $264,000, and overhead expenses of $144,000. What is the retailer's gross profit margin?","options":{"A":"45%","B":"15%","C":"55%","D":"30%"},"correctOption":"A","correctAnswer":"45%","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Gross profit = $480,000 - $264,000 = $216,000, and Gross profit margin = ($216,000 / $480,000) × 100 = 45%.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because 15% is the profit margin ($72,000 / $480,000 × 100).","C":"Incorrect because 55% is cost of sales as a percentage of revenue ($264,000 / $480,000 × 100).","D":"Incorrect because 30% is overhead expenses as a percentage of revenue ($144,000 / $480,000 × 100)."}}},{"id":"P1_U5_MCQ_478","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_478","question":"A kitchenware store achieves a gross profit margin of 35% on annual sales revenue of $600,000. What was the store's cost of sales for the year?","options":{"A":"$390,000","B":"$210,000","C":"$810,000","D":"$350,000"},"correctOption":"A","correctAnswer":"$390,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Gross profit = 35% × $600,000 = $210,000, so Cost of sales = Revenue - Gross profit ($600,000 - $210,000 = $390,000).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $210,000 is the gross profit, not the cost of sales.","C":"Incorrect because $810,000 adds gross profit to revenue instead of subtracting it.","D":"Incorrect because 35% of $600,000 is $210,000, leaving $390,000 rather than $350,000."}}},{"id":"P1_U5_MCQ_479","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_479","question":"Over the last year, a bakery's gross profit margin fell from 52% to 44%. Which event most likely caused this decline?","options":{"A":"Wholesale flour and butter prices jumped sharply, and the bakery held promotional 'buy-one-get-one-free' discounts on bread","B":"The bakery's head-office accounting fees doubled","C":"The bakery took out a new 5-year bank loan","D":"The bakery sold an old delivery van for cash"},"correctOption":"A","correctAnswer":"Wholesale flour and butter prices jumped sharply, and the bakery held promotional 'buy-one-get-one-free' discounts on bread","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because higher ingredient costs (raising cost of sales) and promotional price cuts (lowering revenue per unit) directly compress gross profit margin.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because accounting fees are indirect overheads that reduce profit margin, not gross profit margin.","C":"Incorrect because taking a bank loan does not affect gross profit margin.","D":"Incorrect because selling a non-current asset does not affect gross profit margin."}}},{"id":"P1_U5_MCQ_480","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_480","question":"A travel agency generates annual revenue of $850,000, gross profit of $340,000, and final profit of $102,000. What is the agency's profit margin?","options":{"A":"12%","B":"40%","C":"30%","D":"28%"},"correctOption":"A","correctAnswer":"12%","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Profit margin = (Profit / Revenue) × 100 = ($102,000 / $850,000) × 100 = 12%.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because 40% is the gross profit margin ($340,000 / $850,000 × 100).","C":"Incorrect because 30% divides profit by gross profit ($102,000 / $340,000 × 100) instead of revenue.","D":"Incorrect because 28% subtracts profit margin from gross profit margin (40% - 12%)."}}},{"id":"P1_U5_MCQ_481","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_481","question":"A furniture retailer reports annual revenue of $900,000, a gross profit margin of 40%, and a profit margin of 14%. How much were the retailer's indirect overhead expenses for the year?","options":{"A":"$234,000","B":"$360,000","C":"$126,000","D":"$540,000"},"correctOption":"A","correctAnswer":"$234,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Gross profit = 40% × $900,000 = $360,000 and Profit = 14% × $900,000 = $126,000, so Overhead expenses = $360,000 - $126,000 = $234,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $360,000 is gross profit, not overhead expenses.","C":"Incorrect because $126,000 is final profit, not overhead expenses.","D":"Incorrect because $540,000 is cost of sales ($900,000 - $360,000)."}}},{"id":"P1_U5_MCQ_482","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_482","question":"Two rival courier firms have identical gross profit margins of 50%, yet Firm A has a profit margin of 22% while Firm B has a profit margin of only 9%. What does this comparison reveal?","options":{"A":"Firm B has much higher indirect overhead expenses (such as head-office admin, rent, or marketing) relative to its revenue than Firm A","B":"Firm B pays twice as much for direct fuel and driver wages as Firm A","C":"Firm A has a lower current ratio than Firm B","D":"Firm B earns higher total dollar profit than Firm A"},"correctOption":"A","correctAnswer":"Firm B has much higher indirect overhead expenses (such as head-office admin, rent, or marketing) relative to its revenue than Firm A","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the difference between gross profit margin and profit margin reflects indirect overhead expenses as a share of revenue.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because identical gross profit margins (50%) show that direct cost of sales as a percentage of revenue is the same for both firms.","C":"Incorrect because profit margins do not measure liquidity ratios.","D":"Incorrect because margins are percentages and do not prove higher total dollar profit."}}},{"id":"P1_U5_MCQ_483","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_483","question":"An engineering company earns an annual profit of $270,000. Its statement of financial position shows non-current assets of $1,350,000, current assets of $300,000, and current liabilities of $150,000. What is the company's Return on Capital Employed (ROCE)?","options":{"A":"18%","B":"20%","C":"16.4%","D":"15%"},"correctOption":"A","correctAnswer":"18%","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Capital employed = Non-current assets + Current assets - Current liabilities ($1,350,000 + $300,000 - $150,000 = $1,500,000), and ROCE = ($270,000 / $1,500,000) × 100 = 18%.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because 20% divides profit only by non-current assets ($270,000 / $1,350,000 × 100), omitting working capital.","C":"Incorrect because 16.4% divides profit by total assets ($270,000 / $1,650,000 × 100) without subtracting current liabilities.","D":"Incorrect because 15% divides profit by $1,800,000 (adding current liabilities instead of subtracting them)."}}},{"id":"P1_U5_MCQ_484","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_484","question":"A retail chain achieves an ROCE of 4.5%, while risk-free commercial bank savings accounts pay 5.5% interest and bank business loans cost 8% interest. How will shareholders interpret this 4.5% ROCE?","options":{"A":"Poor performance: the business is generating a lower return than risk-free bank interest and less than the cost of borrowing capital","B":"Outstanding performance because any positive ROCE above 1% is considered high","C":"Proof that the retail chain has a current ratio above 3 : 1","D":"Proof that the retail chain pays zero corporation tax"},"correctOption":"A","correctAnswer":"Poor performance: the business is generating a lower return than risk-free bank interest and less than the cost of borrowing capital","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because investors benchmark ROCE against safe deposit interest rates and borrowing costs; earning less than a bank deposit signals inefficient capital use.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because investors take business risks expecting returns well above safe bank interest rates.","C":"Incorrect because ROCE measures profitability, not liquidity.","D":"Incorrect because ROCE does not measure tax exemptions."}}},{"id":"P1_U5_MCQ_485","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_485","question":"A logistics company wants to increase its Return on Capital Employed (ROCE) without raising delivery prices. Which action would directly raise its ROCE?","options":{"A":"Selling off idle, underused warehouse land and using the cash to repay long-term bank loans while maintaining existing profits","B":"Borrowing $1 million in new long-term loans to hold as idle cash in a zero-interest account","C":"Increasing head-office administrative salaries by 20%","D":"Issuing $500,000 of new shares without investing the money in profitable projects"},"correctOption":"A","correctAnswer":"Selling off idle, underused warehouse land and using the cash to repay long-term bank loans while maintaining existing profits","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because reducing capital employed (repaying non-current debt via unused asset sales) while keeping profit steady increases the ratio Profit / Capital employed.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because increasing capital employed without generating extra profit lowers ROCE.","C":"Incorrect because higher admin salaries reduce profit and lower ROCE.","D":"Incorrect because raising share capital increases capital employed and lowers ROCE if profit stays flat."}}},{"id":"P1_U5_MCQ_486","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_486","question":"A hardware distributor has inventory of $85,000, trade receivables of $55,000, cash of $20,000, trade payables of $60,000, and a bank overdraft of $20,000. What is the distributor's current ratio?","options":{"A":"2.0 : 1","B":"0.94 : 1","C":"0.5 : 1","D":"2.67 : 1"},"correctOption":"A","correctAnswer":"2.0 : 1","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Current assets = $85,000 + $55,000 + $20,000 = $160,000 and Current liabilities = $60,000 + $20,000 = $80,000, giving Current ratio = $160,000 / $80,000 = 2.0 : 1.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because 0.94 : 1 is the acid-test ratio (($160,000 - $85,000) / $80,000).","C":"Incorrect because 0.5 : 1 inverts the ratio ($80,000 / $160,000).","D":"Incorrect because 2.67 : 1 omits the $20,000 bank overdraft from current liabilities ($160,000 / $60,000)."}}},{"id":"P1_U5_MCQ_487","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_487","question":"A furniture wholesaler has a current ratio of 4.8 : 1, far above the typical industry benchmark of 1.5 : 1 to 2.0 : 1. Why might financial analysts criticize such a high current ratio?","options":{"A":"It suggests funds are tied up unproductively in excessive unsold inventory, slow-paying receivables, or idle low-interest cash rather than being invested for growth","B":"It means the wholesaler is about to run out of cash next week","C":"It proves the wholesaler has too many non-current liabilities","D":"It indicates that gross profit margin is negative"},"correctOption":"A","correctAnswer":"It suggests funds are tied up unproductively in excessive unsold inventory, slow-paying receivables, or idle low-interest cash rather than being invested for growth","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an excessively high current ratio indicates inefficient working capital management and lost opportunity to earn higher returns.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a high current ratio indicates abundant current assets, not an immediate cash shortage.","C":"Incorrect because non-current liabilities are not part of the current ratio.","D":"Incorrect because the current ratio does not measure gross profit margin."}}},{"id":"P1_U5_MCQ_488","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_488","question":"A construction supplier's current ratio is 0.85 : 1. What does this ratio specifically tell the supplier's managers?","options":{"A":"The business has only $0.85 of current assets for every $1.00 of short-term liabilities, indicating a high risk of being unable to pay bills on time","B":"The business earns $0.85 of profit on every $1.00 of sales revenue","C":"The business holds $85,000 in physical cash","D":"The business has zero inventory in its warehouse"},"correctOption":"A","correctAnswer":"The business has only $0.85 of current assets for every $1.00 of short-term liabilities, indicating a high risk of being unable to pay bills on time","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a current ratio below 1 : 1 means current liabilities exceed current assets (negative working capital), creating serious liquidity danger.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because profit per dollar of sales is measured by profit margin, not current ratio.","C":"Incorrect because a ratio shows a relative proportion, not a specific dollar balance.","D":"Incorrect because current assets include inventory, receivables, and cash."}}},{"id":"P1_U5_MCQ_489","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_489","question":"A toy distributor has current assets of $240,000 (including $135,000 of inventory) and current liabilities of $70,000. What is the distributor's acid-test ratio?","options":{"A":"1.5 : 1","B":"3.43 : 1","C":"1.93 : 1","D":"0.67 : 1"},"correctOption":"A","correctAnswer":"1.5 : 1","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Acid-test ratio = (Current assets - Inventory) / Current liabilities = ($240,000 - $135,000) / $70,000 = $105,000 / $70,000 = 1.5 : 1.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because 3.43 : 1 is the current ratio ($240,000 / $70,000) without subtracting inventory.","C":"Incorrect because 1.93 : 1 divides inventory by current liabilities ($135,000 / $70,000).","D":"Incorrect because 0.67 : 1 inverts the acid-test formula ($70,000 / $105,000)."}}},{"id":"P1_U5_MCQ_490","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_490","question":"Firm X and Firm Y both have a current ratio of 2.0 : 1. However, Firm X has an acid-test ratio of 1.6 : 1 while Firm Y has an acid-test ratio of 0.5 : 1. Which firm is in a stronger short-term liquidity position?","options":{"A":"Firm X, because most of its current assets are already in liquid cash and receivables, whereas Firm Y relies heavily on selling inventory to pay short-term debts","B":"Firm Y, because holding large amounts of unsold inventory guarantees instant cash","C":"Both firms have identical liquidity because their current ratios are both 2.0 : 1","D":"Firm Y, because a lower acid-test ratio means higher profit margins"},"correctOption":"A","correctAnswer":"Firm X, because most of its current assets are already in liquid cash and receivables, whereas Firm Y relies heavily on selling inventory to pay short-term debts","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the acid-test ratio excludes inventory (the least liquid current asset), showing that Firm X can easily pay immediate bills without needing emergency stock clearances.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because inventory can be slow or difficult to convert quickly into cash.","C":"Incorrect because two firms with equal current ratios can have very different liquidity depending on how much stock they hold.","D":"Incorrect because liquidity ratios do not measure profit margins."}}},{"id":"P1_U5_MCQ_491","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_491","question":"Why is the acid-test ratio considered a much more reliable liquidity test than the current ratio for a high-fashion clothing boutique or a fresh-seafood wholesaler?","options":{"A":"Because fashion clothing can suddenly go out of style and fresh seafood can spoil, meaning inventory may not easily convert into cash at full value","B":"Because fashion boutiques and seafood wholesalers are not allowed to hold bank accounts","C":"Because current liabilities are excluded from the acid-test ratio","D":"Because non-current assets are included in the acid-test ratio"},"correctOption":"A","correctAnswer":"Because fashion clothing can suddenly go out of style and fresh seafood can spoil, meaning inventory may not easily convert into cash at full value","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because perishable or trend-sensitive inventory carries high risk of obsolescence or spoilage, so excluding inventory tests whether truly liquid assets cover short-term debts.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because both types of businesses hold standard bank accounts.","C":"Incorrect because current liabilities are the denominator in both ratios.","D":"Incorrect because non-current assets are excluded from both liquidity ratios."}}},{"id":"P1_U5_MCQ_492","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_492","question":"A retail business currently has current assets of $100,000 and current liabilities of $50,000 (a current ratio of 2.0 : 1). If it uses $25,000 of its cash to pay off $25,000 of trade payables, what happens to its current ratio?","options":{"A":"It rises from 2.0 : 1 to 3.0 : 1 ($75,000 / $25,000)","B":"It stays unchanged at 2.0 : 1","C":"It falls from 2.0 : 1 to 1.5 : 1","D":"It falls to 0.5 : 1"},"correctOption":"A","correctAnswer":"It rises from 2.0 : 1 to 3.0 : 1 ($75,000 / $25,000)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because current assets fall to $75,000 ($100,000 - $25,000) and current liabilities fall to $25,000 ($50,000 - $25,000), raising the ratio to $75,000 / $25,000 = 3.0 : 1.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because subtracting equal amounts from numerator and denominator changes the ratio whenever the initial ratio is not 1 : 1.","C":"Incorrect because paying off debt when current assets exceed current liabilities increases rather than decreases the current ratio.","D":"Incorrect because $75,000 is three times $25,000, not half."}}},{"id":"P1_U5_MCQ_493","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_493","question":"A wholesaler has liquid assets of $40,000 cash and $60,000 trade receivables, against $80,000 of current liabilities (an acid-test ratio of 1.25 : 1). If credit customers pay $30,000 in cash, what happens to the acid-test ratio?","options":{"A":"It remains unchanged at 1.25 : 1 because cash rises by $30,000 while trade receivables fall by $30,000, leaving total liquid assets at $100,000","B":"It rises to 1.625 : 1","C":"It falls to 0.875 : 1","D":"It doubles to 2.5 : 1"},"correctOption":"A","correctAnswer":"It remains unchanged at 1.25 : 1 because cash rises by $30,000 while trade receivables fall by $30,000, leaving total liquid assets at $100,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because both cash and trade receivables are included in the acid-test numerator; shifting $30,000 from receivables to cash leaves $100,000 / $80,000 = 1.25 : 1.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $130,000 double-counts the $30,000 cash without reducing trade receivables.","C":"Incorrect because collecting receivables does not reduce total liquid assets.","D":"Incorrect because total liquid assets remain $100,000."}}},{"id":"P1_U5_MCQ_494","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_494","question":"Why do internal department managers calculate gross profit margin and profit margin every quarter?","options":{"A":"To spot rising direct costs or overhead overspending early and take corrective action before year-end accounts are finalized","B":"To calculate the exact market share price on the stock exchange","C":"To decide whether government tax authorities should audit rival firms","D":"To replace the need for quality control on the factory floor"},"correctOption":"A","correctAnswer":"To spot rising direct costs or overhead overspending early and take corrective action before year-end accounts are finalized","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because internal managers use regular ratio tracking as an early-warning diagnostic tool to control costs and protect margins.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because share prices are determined by supply and demand on the stock exchange.","C":"Incorrect because tax audits are decided by government tax agencies.","D":"Incorrect because financial ratios complement rather than replace operational quality control."}}},{"id":"P1_U5_MCQ_495","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_495","question":"Which set of ratios would an existing shareholder examine most closely to evaluate how efficiently directors are generating returns on invested funds?","options":{"A":"Return on Capital Employed (ROCE) and Profit margin","B":"Current ratio and Acid-test ratio alone","C":"Trade payables days and inventory spoilage rate alone","D":"Bank overdraft limit and daily cash float"},"correctOption":"A","correctAnswer":"Return on Capital Employed (ROCE) and Profit margin","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because shareholders focus primarily on profitability ratios—especially ROCE and profit margin—to judge management effectiveness and dividend prospects.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because liquidity ratios are the main priority of short-term creditors and banks rather than equity investors.","C":"Incorrect because these are operational working capital metrics rather than headline investor return ratios.","D":"Incorrect because daily cash management is monitored internally by finance managers."}}},{"id":"P1_U5_MCQ_496","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_496","question":"Why do both commercial banks and trade suppliers focus heavily on liquidity ratios (current ratio and acid-test ratio) when analyzing a business's accounts?","options":{"A":"Because creditors need assurance that the business holds enough liquid assets to pay invoices and loan interest on time without defaulting","B":"Because banks and suppliers receive a percentage of the business's gross profit instead of cash payments","C":"Because liquidity ratios measure employee motivation and product quality","D":"Because liquidity ratios tell creditors how much corporation tax the government owes"},"correctOption":"A","correctAnswer":"Because creditors need assurance that the business holds enough liquid assets to pay invoices and loan interest on time without defaulting","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because external lenders and trade creditors face direct financial loss if a customer lacks short-term liquidity to pay debts as they fall due.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because banks and suppliers require contractual cash repayments, not profit shares.","C":"Incorrect because liquidity ratios measure short-term financial solvency, not qualitative factors.","D":"Incorrect because businesses pay tax to governments, not the reverse."}}},{"id":"P1_U5_MCQ_497","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_497","question":"How do government tax authorities and trade unions differ in their reasons for analyzing a large corporation's financial accounts?","options":{"A":"Tax authorities verify profit figures to collect accurate corporation tax, whereas trade unions check profitability and liquidity to assess job security and negotiate pay rises","B":"Tax authorities negotiate employee wage rises, whereas trade unions collect corporation tax","C":"Tax authorities approve bank overdrafts, whereas trade unions set retail product prices","D":"Neither group is legally permitted to view published public limited company accounts"},"correctOption":"A","correctAnswer":"Tax authorities verify profit figures to collect accurate corporation tax, whereas trade unions check profitability and liquidity to assess job security and negotiate pay rises","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because different external stakeholders analyze the same published statements for distinct purposes—tax compliance for government versus pay and employment security for unions.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because this reverses the roles of tax authorities and trade unions.","C":"Incorrect because banks approve overdrafts and company managers set retail prices.","D":"Incorrect because public limited companies must publish their annual accounts publicly."}}},{"id":"P1_U5_MCQ_498","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_498","question":"Over a five-year period of high inflation, a supermarket's sales revenue rose by 35%, making its financial growth look impressive at first glance. Why is inflation a limitation when comparing accounts across several years?","options":{"A":"Higher revenue and asset figures may simply reflect rising general price levels rather than genuine growth in sales volume or real efficiency","B":"Inflation automatically doubles a company's acid-test ratio every year","C":"Accountants are legally required to divide all figures by ten during inflation","D":"Inflation eliminates all overhead expenses on the statement of profit or loss"},"correctOption":"A","correctAnswer":"Higher revenue and asset figures may simply reflect rising general price levels rather than genuine growth in sales volume or real efficiency","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because inflation inflates nominal monetary figures over time, making historical comparisons misleading unless price increases are accounted for.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because inflation does not automatically double liquidity ratios.","C":"Incorrect because no such accounting rule exists.","D":"Incorrect because inflation actually raises overhead expenses such as wages, rent, and energy."}}},{"id":"P1_U5_MCQ_499","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_499","question":"Two competing car-rental companies use different accounting policies for valuing their vehicle fleets and calculating depreciation. How does this limit inter-firm ratio comparisons?","options":{"A":"Differences in profit and capital employed figures may reflect different accounting methods rather than true differences in operational performance","B":"Companies using different accounting policies are banned from calculating ROCE","C":"Depreciation policies change a company's daily bank cash balance","D":"Different accounting policies only affect sole traders, never limited companies"},"correctOption":"A","correctAnswer":"Differences in profit and capital employed figures may reflect different accounting methods rather than true differences in operational performance","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because variations in asset valuation, inventory valuation, or depreciation methods alter reported profits and asset totals, distorting ratio comparisons between firms.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because any company can calculate ROCE, though analysts must interpret differences carefully.","C":"Incorrect because depreciation is a non-cash accounting charge that does not alter cash in the bank.","D":"Incorrect because limited companies also exercise judgment within accounting standards."}}},{"id":"P1_U5_MCQ_500","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_500","question":"An analyst calculates that a retailer's profit margin fell from 14% to 8%, its current ratio dropped from 1.9 : 1 to 1.1 : 1, and its ROCE fell from 18% to 10%. What is a fundamental limitation of ratio analysis when deciding how to fix the business?","options":{"A":"Ratios highlight financial symptoms (such as falling margins or weaker liquidity), but they do not explain the underlying operational causes or qualitative issues like poor customer service or rising competition","B":"Ratios can only be calculated if a business has zero liabilities","C":"Ratios guarantee that next year's profit margin will return to 14%","D":"Ratios are illegal to use for internal management decision-making"},"correctOption":"A","correctAnswer":"Ratios highlight financial symptoms (such as falling margins or weaker liquidity), but they do not explain the underlying operational causes or qualitative issues like poor customer service or rising competition","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ratios diagnose where performance has weakened, but managers must investigate market conditions, product quality, and staff motivation to uncover root causes.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because liquidity ratios specifically require current liabilities in the denominator.","C":"Incorrect because ratios analyze past data and cannot guarantee future recovery.","D":"Incorrect because internal ratio analysis is a core management tool."}}},{"id":"P1_U5_MCQ_501","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_501","question":"What is meant by the term 'start-up capital'?","options":{"A":"The finance needed by an entrepreneur to pay for essential non-current assets and initial inventories before trading begins","B":"The profit kept inside an established company after corporation tax and dividends have been paid","C":"The short-term money owed to a business by customers who have bought goods on credit","D":"The annual interest paid to commercial banks on long-term commercial mortgages"},"correctOption":"A","correctAnswer":"The finance needed by an entrepreneur to pay for essential non-current assets and initial inventories before trading begins","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because start-up capital is the initial finance required to set up a new business, purchase essential premises or equipment, and acquire opening stock before revenue flows in.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because profit kept inside an established business is retained profit, which a new start-up does not yet have.","C":"Incorrect because amounts owed by credit customers are trade receivables.","D":"Incorrect because interest paid on loans is a finance expense, not start-up capital."}}},{"id":"P1_U5_MCQ_502","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_502","question":"Why does a trading business require 'working capital'?","options":{"A":"To purchase freehold land and construct new manufacturing factories","B":"To pay for day-to-day running costs such as wages, raw materials, and utility bills","C":"To distribute annual cash dividends to ordinary shareholders","D":"To pay off 25-year debentures upon maturity"},"correctOption":"B","correctAnswer":"To pay for day-to-day running costs such as wages, raw materials, and utility bills","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because working capital is the finance needed for everyday operational expenses and to bridge the time gap between paying suppliers and receiving cash from customers.","distractor_reasons":{"A":"Incorrect because buying freehold land and factories is long-term capital expenditure.","B":"Correct selection.","C":"Incorrect because dividends are distributed out of after-tax profits rather than being the purpose of working capital.","D":"Incorrect because repaying 25-year debentures is a long-term financing obligation."}}},{"id":"P1_U5_MCQ_503","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_503","question":"Which of the following is the best definition of 'capital expenditure'?","options":{"A":"Money spent on day-to-day running expenses such as electricity, stationery, and fuel","B":"Money spent on purchasing raw materials that will be turned into finished goods within a week","C":"Money spent on acquiring or upgrading non-current assets that will be used in the business for more than one year","D":"Money repaid to suppliers to settle 30-day trade credit invoices"},"correctOption":"C","correctAnswer":"Money spent on acquiring or upgrading non-current assets that will be used in the business for more than one year","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital expenditure involves spending on long-term physical or intangible assets (such as machinery, vehicles, or buildings) that last more than 12 months.","distractor_reasons":{"A":"Incorrect because spending on day-to-day running expenses is revenue expenditure.","B":"Incorrect because spending on short-term raw materials is revenue expenditure.","C":"Correct selection.","D":"Incorrect because settling short-term supplier invoices is a working capital cash outflow, not capital expenditure."}}},{"id":"P1_U5_MCQ_504","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_504","question":"Which of the following is classified as 'revenue expenditure'?","options":{"A":"Buying a new fleet of refrigerated delivery trucks","B":"Purchasing an adjoining plot of land to build a warehouse","C":"Installing a permanent automated assembly line in a factory","D":"Paying monthly rent, staff wages, and routine equipment repairs"},"correctOption":"D","correctAnswer":"Paying monthly rent, staff wages, and routine equipment repairs","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because revenue expenditure refers to spending on day-to-day operational items that are consumed within the current accounting year.","distractor_reasons":{"A":"Incorrect because delivery trucks are long-term non-current assets (capital expenditure).","B":"Incorrect because purchasing land is long-term capital expenditure.","C":"Incorrect because installing a permanent assembly line is capital expenditure.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_505","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_505","question":"What is meant by 'internal sources of finance'?","options":{"A":"Funds obtained from within the business itself, such as retained profit, sale of existing assets, or reducing inventory levels","B":"Funds borrowed from commercial banks using long-term mortgages or short-term overdrafts","C":"Funds raised by issuing new ordinary shares to investors on a public stock exchange","D":"Non-repayable funds awarded by government agencies to encourage regional job creation"},"correctOption":"A","correctAnswer":"Funds obtained from within the business itself, such as retained profit, sale of existing assets, or reducing inventory levels","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because internal finance is generated from the business's own resources without involving outside lenders or external investors.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because bank loans and overdrafts are external sources of finance.","C":"Incorrect because issuing shares to outside investors is an external source of finance.","D":"Incorrect because government grants come from an outside agency and are external finance."}}},{"id":"P1_U5_MCQ_506","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_506","question":"Which list contains ONLY 'external sources of finance'?","options":{"A":"Retained profit, owners' savings, and sale of surplus machinery","B":"Bank loans, issue of shares, debentures, and trade credit","C":"Reducing inventory levels, retained profit, and crowdfunding","D":"Sale of existing assets, bank overdraft, and debt factoring"},"correctOption":"B","correctAnswer":"Bank loans, issue of shares, debentures, and trade credit","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because bank loans, share issues, debentures, and trade credit all bring funds or credit into the business from outside parties.","distractor_reasons":{"A":"Incorrect because retained profit, owners' savings, and asset sales are all internal sources.","B":"Correct selection.","C":"Incorrect because reducing inventory levels and retained profit are internal sources.","D":"Incorrect because the sale of existing assets is an internal source of finance."}}},{"id":"P1_U5_MCQ_507","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_507","question":"What is a major limitation of relying on 'retained profit' as a source of finance?","options":{"A":"It must be repaid to commercial banks with high compound interest within one year","B":"It dilutes the voting control of existing ordinary shareholders","C":"It is unavailable to newly formed businesses and may be too small if past profits were low","D":"It requires offering freehold property as collateral to external lenders"},"correctOption":"C","correctAnswer":"It is unavailable to newly formed businesses and may be too small if past profits were low","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because new start-ups have no trading history to accumulate retained profit, and low-margin firms may not retain enough profit to fund major projects.","distractor_reasons":{"A":"Incorrect because retained profit is internal equity and incurs no interest or repayment obligation.","B":"Incorrect because retaining profit keeps ownership intact without issuing new voting shares.","C":"Correct selection.","D":"Incorrect because collateral is required for secured external loans, not internal retained profit."}}},{"id":"P1_U5_MCQ_508","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_508","question":"What is a key disadvantage of raising internal finance through the 'sale of existing assets'?","options":{"A":"The business must pay annual dividends to the buyer of the assets","B":"The funds raised must be repaid within 30 days","C":"The business immediately loses its status as a limited company","D":"It can take a long time to find a buyer, and the assets may sell for less than their true value"},"correctOption":"D","correctAnswer":"It can take a long time to find a buyer, and the assets may sell for less than their true value","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because non-current assets such as property or specialized machinery are illiquid, slow to sell, and no longer available for future production once sold.","distractor_reasons":{"A":"Incorrect because asset buyers purchase physical items rather than shares.","B":"Incorrect because outright asset sales generate permanent cash with no repayment.","C":"Incorrect because selling surplus assets does not alter a company's legal structure.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_509","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_509","question":"How does 'reducing inventory levels' act as an internal source of finance, and what is its main operational risk?","options":{"A":"It frees up cash tied up in unsold stock, but risks running out of goods if customer demand suddenly increases","B":"It increases bank overdraft limits automatically, but doubles warehouse insurance costs","C":"It creates new share capital, but forces the business to pay higher corporation tax","D":"It delays supplier payments by six months, but lowers product selling prices"},"correctOption":"A","correctAnswer":"It frees up cash tied up in unsold stock, but risks running out of goods if customer demand suddenly increases","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because holding lower stock releases working capital cash and cuts storage costs, but leaves less buffer inventory to meet unexpected orders.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because holding smaller inventory lowers rather than doubles warehouse insurance costs.","C":"Incorrect because adjusting inventory levels is a working capital measure, not a share issue.","D":"Incorrect because reducing inventory does not extend supplier credit terms."}}},{"id":"P1_U5_MCQ_510","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_510","question":"Why is 'owners' savings' a particularly common source of finance for sole traders and partnerships?","options":{"A":"It legally grants unincorporated owners limited liability for business debts","B":"It is quickly available without complex bank loan applications and incurs no interest charges","C":"It provides unlimited amounts of capital for multinational expansion","D":"It is guaranteed by the government against any trading losses"},"correctOption":"B","correctAnswer":"It is quickly available without complex bank loan applications and incurs no interest charges","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because sole traders and partnerships cannot issue shares and often struggle to obtain bank loans without a track record, making personal savings fast and interest-free.","distractor_reasons":{"A":"Incorrect because sole traders and ordinary partners retain unlimited liability regardless of how they fund the business.","B":"Correct selection.","C":"Incorrect because personal savings are usually limited in size.","D":"Incorrect because owners bear the full risk of losing their personal savings if the business fails."}}},{"id":"P1_U5_MCQ_511","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_511","question":"Which statement accurately describes 'issue of shares' as a source of finance?","options":{"A":"It is available to sole traders and partnerships to raise short-term working capital","B":"It is a short-term loan that must be repaid to shareholders within 12 months","C":"It is available only to limited companies and provides permanent capital that does not have to be repaid","D":"It guarantees fixed annual interest payments to investors even when the company makes a loss"},"correctOption":"C","correctAnswer":"It is available only to limited companies and provides permanent capital that does not have to be repaid","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because only incorporated limited companies (Ltd and plc) can issue shares, and ordinary share capital is permanent finance with no repayment date.","distractor_reasons":{"A":"Incorrect because unincorporated businesses (sole traders and partnerships) cannot issue shares.","B":"Incorrect because share capital is permanent long-term equity, not a short-term loan.","C":"Correct selection.","D":"Incorrect because ordinary shareholders receive variable dividends only if profits allow, unlike fixed loan interest."}}},{"id":"P1_U5_MCQ_512","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_512","question":"What is a major disadvantage to existing owners of raising finance by issuing new ordinary shares to outside investors?","options":{"A":"The company must provide physical property as collateral to the new shareholders","B":"The company's interest expenses immediately double","C":"The new shares must be bought back by the company within five years","D":"Existing owners' percentage ownership and voting control are diluted, and future profits must be shared among more shareholders"},"correctOption":"D","correctAnswer":"Existing owners' percentage ownership and voting control are diluted, and future profits must be shared among more shareholders","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because issuing additional voting shares reduces the proportion of control held by original shareholders and spreads future dividend payouts.","distractor_reasons":{"A":"Incorrect because equity investors share business risk rather than taking collateral.","B":"Incorrect because shares carry dividends rather than interest expenses.","C":"Incorrect because ordinary shares have no maturity or mandatory buy-back date.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_513","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_513","question":"Which characteristic applies to a 'bank loan' as a source of business finance?","options":{"A":"It provides a lump sum repaid in regular instalments with interest over an agreed period, and does not dilute ownership control","B":"It gives the lending bank voting rights at the company's Annual General Meeting","C":"It is an internal source of finance that requires no formal application","D":"It never requires collateral or security regardless of the amount borrowed"},"correctOption":"A","correctAnswer":"It provides a lump sum repaid in regular instalments with interest over an agreed period, and does not dilute ownership control","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a bank loan delivers an agreed sum upfront, is repaid with interest over a fixed term, and leaves full ownership with the business owners.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because banks are external creditors, not voting shareholders.","C":"Incorrect because bank loans are external finance requiring financial forecasts and approval.","D":"Incorrect because banks frequently demand security/collateral for medium- and long-term loans."}}},{"id":"P1_U5_MCQ_514","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_514","question":"What are 'debentures'?","options":{"A":"Short-term supplier invoices that must be paid within 30 days","B":"Long-term loan certificates issued by limited companies that pay fixed interest and must be repaid at a set maturity date","C":"Non-repayable government subsidies awarded for exporting goods","D":"Voting equity shares sold to the general public on a stock exchange"},"correctOption":"B","correctAnswer":"Long-term loan certificates issued by limited companies that pay fixed interest and must be repaid at a set maturity date","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because debentures are long-term debt instruments issued by companies; debenture holders are creditors earning fixed interest rather than voting owners.","distractor_reasons":{"A":"Incorrect because 30-day supplier invoices are trade credit.","B":"Correct selection.","C":"Incorrect because non-repayable government funds are grants.","D":"Incorrect because voting equity instruments are ordinary shares, whereas debentures carry no voting rights."}}},{"id":"P1_U5_MCQ_515","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_515","question":"How does 'debt factoring' work as a short-term source of finance?","options":{"A":"A business borrows money from a bank by mortgaging its freehold factory","B":"A business delays paying its own suppliers for up to 90 days","C":"A specialist financial firm buys a business's unpaid customer invoices at a discount in exchange for immediate cash","D":"A business raises small donations from thousands of online supporters"},"correctOption":"C","correctAnswer":"A specialist financial firm buys a business's unpaid customer invoices at a discount in exchange for immediate cash","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because debt factoring converts trade receivables into immediate liquidity by selling the invoices to a factor, which collects the full debt from customers.","distractor_reasons":{"A":"Incorrect because borrowing against property is a commercial mortgage.","B":"Incorrect because delaying supplier payments is trade credit.","C":"Correct selection.","D":"Incorrect because raising small sums online from the public is crowdfunding."}}},{"id":"P1_U5_MCQ_516","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_516","question":"What is a potential disadvantage of using 'debt factoring'?","options":{"A":"The business must wait an extra six months before receiving any cash","B":"The factoring company becomes the majority owner of the business","C":"The business's non-current liabilities increase substantially","D":"The business receives less than the full face value of its invoices, and aggressive collection by the factor may harm customer relationships"},"correctOption":"D","correctAnswer":"The business receives less than the full face value of its invoices, and aggressive collection by the factor may harm customer relationships","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the factor deducts a service fee/discount (reducing the business's profit) and takes over chasing customers for payment.","distractor_reasons":{"A":"Incorrect because debt factoring provides immediate cash upfront.","B":"Incorrect because debt factoring is a commercial fee service, not an equity purchase.","C":"Incorrect because factoring converts an existing current asset (receivables) into cash without adding long-term debt.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_517","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_517","question":"What is a defining feature of 'grants and subsidies from outside agencies'?","options":{"A":"They do not have to be repaid, provided the business meets specific conditions such as creating jobs or locating in a target region","B":"They carry higher interest rates than commercial bank overdrafts","C":"They are automatically granted to every profitable business upon request","D":"They require the recipient business to list its shares on a stock exchange"},"correctOption":"A","correctAnswer":"They do not have to be repaid, provided the business meets specific conditions such as creating jobs or locating in a target region","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because grants are non-repayable funds offered by governments or development agencies to achieve specific economic or social policy objectives.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because grants do not require repayment or interest unless conditions are breached.","C":"Incorrect because grants are selective, competitive, and subject to strict eligibility criteria.","D":"Incorrect because small private businesses can receive grants without becoming public limited companies."}}},{"id":"P1_U5_MCQ_518","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_518","question":"What is 'microfinance'?","options":{"A":"The issue of multi-million-dollar corporate bonds by multinational corporations","B":"The provision of very small loans and basic financial services to low-income entrepreneurs who lack access to traditional commercial banks","C":"The practice of selling unpaid corporate invoices to international investment banks","D":"Internal retained profit accumulated by small retail shops"},"correctOption":"B","correctAnswer":"The provision of very small loans and basic financial services to low-income entrepreneurs who lack access to traditional commercial banks","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because microfinance institutions provide small-scale credit (often without traditional collateral) to help low-income individuals start or expand micro-enterprises.","distractor_reasons":{"A":"Incorrect because multi-million-dollar corporate bonds are large capital-market instruments.","B":"Correct selection.","C":"Incorrect because selling unpaid invoices is debt factoring.","D":"Incorrect because microfinance is an external lending service, not internal retained profit."}}},{"id":"P1_U5_MCQ_519","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_519","question":"How does 'crowdfunding' operate, and what is a key secondary benefit for an entrepreneur?","options":{"A":"It borrows funds from a single central bank and eliminates all production costs","B":"It sells company assets to competitors and guarantees monopoly power","C":"It raises small sums of money from a large number of people via online platforms, while also testing market demand and building early customer awareness","D":"It provides interest-free overdrafts from commercial banks without any public disclosure"},"correctOption":"C","correctAnswer":"It raises small sums of money from a large number of people via online platforms, while also testing market demand and building early customer awareness","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because crowdfunding pools small pledges from the public online and serves as valuable market validation and promotion before full launch.","distractor_reasons":{"A":"Incorrect because central banks do not lend directly to individual entrepreneurs via crowdfunding.","B":"Incorrect because crowdfunding raises funds from online backers rather than selling assets to rivals.","C":"Correct selection.","D":"Incorrect because crowdfunding is publicly visible on internet platforms, which actually carries the risk of idea imitation."}}},{"id":"P1_U5_MCQ_520","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_520","question":"Why is a 'bank overdraft' considered risky if used to finance long-term capital projects?","options":{"A":"Overdrafts require issuing voting shares to the bank","B":"Overdrafts have a fixed 20-year repayment schedule that cannot be changed","C":"Overdrafts can only be used to pay corporation tax","D":"The bank can demand full repayment at very short notice, and interest rates are usually high and variable"},"correctOption":"D","correctAnswer":"The bank can demand full repayment at very short notice, and interest rates are usually high and variable","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because overdrafts are flexible short-term facilities repayable on demand with high daily interest, making them dangerous for funding long-term investments.","distractor_reasons":{"A":"Incorrect because bank overdrafts are debt facilities and do not involve issuing shares.","B":"Incorrect because a fixed 20-year repayment schedule describes a mortgage or long-term loan, not an overdraft.","C":"Incorrect because overdrafts can cover any routine current account payments.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_521","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_521","question":"What is 'trade credit' and what is a common hidden cost of using it?","options":{"A":"Delaying payment to suppliers for goods already received; the business may lose out on early-payment cash discounts","B":"Borrowing cash from customers before delivering goods; the business must pay high bank arrangement fees","C":"Selling unpaid invoices to a factor; the business loses control over its bank account","D":"Leasing machinery from a finance firm; the business never owns the asset"},"correctOption":"A","correctAnswer":"Delaying payment to suppliers for goods already received; the business may lose out on early-payment cash discounts","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because trade credit allows a buyer to purchase inventory now and pay later (e.g., in 30 or 60 days), though suppliers often offer prompt-payment discounts that are forfeited.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because trade credit is granted by suppliers to buyers, not by customers.","C":"Incorrect because selling unpaid invoices describes debt factoring.","D":"Incorrect because renting equipment describes leasing."}}},{"id":"P1_U5_MCQ_522","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_522","question":"How does 'leasing' differ from 'hire purchase' when acquiring a non-current asset?","options":{"A":"Leasing transfers immediate legal ownership on Day 1, whereas hire purchase never transfers ownership","B":"With leasing, legal ownership remains with the leasing company and maintenance is often included, whereas with hire purchase, ownership passes to the buyer once the final instalment is paid","C":"Leasing is an internal source of finance, whereas hire purchase is an external source","D":"Leasing requires paying the full purchase price upfront in cash, whereas hire purchase requires no payments"},"correctOption":"B","correctAnswer":"With leasing, legal ownership remains with the leasing company and maintenance is often included, whereas with hire purchase, ownership passes to the buyer once the final instalment is paid","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because leasing is a rental agreement where the lessor retains ownership and handles servicing, while hire purchase is an instalment purchase ending in ownership.","distractor_reasons":{"A":"Incorrect because this reverses the ownership rules of leasing and hire purchase.","B":"Correct selection.","C":"Incorrect because both leasing and hire purchase are external asset-finance arrangements.","D":"Incorrect because neither option requires paying the full purchase price upfront in cash."}}},{"id":"P1_U5_MCQ_523","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_523","question":"What is a key advantage of 'hire purchase' for a business acquiring expensive equipment?","options":{"A":"It avoids paying any interest over the life of the agreement","B":"It is recorded as an internal reserve on the statement of financial position","C":"It avoids a large immediate cash outflow by spreading payments over time while leading to eventual ownership of the asset","D":"It allows the business to return the asset at any time without penalty"},"correctOption":"C","correctAnswer":"It avoids a large immediate cash outflow by spreading payments over time while leading to eventual ownership of the asset","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because hire purchase preserves working capital by paying in instalments while building toward full asset ownership.","distractor_reasons":{"A":"Incorrect because hire purchase includes interest charges, making total payments higher than the cash price.","B":"Incorrect because hire purchase is an external liability, not an internal equity reserve.","C":"Correct selection.","D":"Incorrect because hire purchase commits the buyer to the instalment contract."}}},{"id":"P1_U5_MCQ_524","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_524","question":"How do accountants distinguish between 'short-term finance' and 'long-term finance'?","options":{"A":"Short-term finance is used only by unincorporated businesses, while long-term finance is used only by limited companies","B":"Short-term finance is always interest-free, while long-term finance always carries variable interest","C":"Short-term finance is always internal, while long-term finance is always external","D":"Short-term finance is required for up to one year to fund working capital, while long-term finance is required for more than one year to fund non-current assets or expansion"},"correctOption":"D","correctAnswer":"Short-term finance is required for up to one year to fund working capital, while long-term finance is required for more than one year to fund non-current assets or expansion","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the standard financial dividing line is 12 months: under one year for short-term operational needs versus over one year for long-term capital investment.","distractor_reasons":{"A":"Incorrect because businesses of all legal forms use both short-term and long-term finance.","B":"Incorrect because short-term sources such as bank overdrafts charge interest.","C":"Incorrect because short-term finance includes external sources (e.g., overdrafts, trade credit) and long-term finance includes internal retained profit.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_525","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_525","question":"Why does a business with already high existing debt (high gearing) often prefer issuing shares rather than taking another long-term bank loan?","options":{"A":"Taking on additional debt increases mandatory fixed interest payments and raises the risk of insolvency during sales downturns","B":"Issuing shares never dilutes existing shareholders' control","C":"Bank loans require distributing dividends every month","D":"Issuing shares has zero legal or administrative setup costs"},"correctOption":"A","correctAnswer":"Taking on additional debt increases mandatory fixed interest payments and raises the risk of insolvency during sales downturns","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because existing debt levels influence finance choice; high gearing makes further borrowing risky due to rigid interest commitments, whereas dividends on shares are discretionary.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because issuing new shares to outside investors does dilute existing ownership.","C":"Incorrect because bank loans require interest and principal repayments, not dividends.","D":"Incorrect because share issues involve substantial legal, underwriting, and administrative costs."}}},{"id":"P1_U5_MCQ_526","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_526","question":"What is meant by the term 'cash flow'?","options":{"A":"The total profit remaining after all operating expenses and taxes are deducted from revenue","B":"The movement of cash inflows into and cash outflows out of a business over a period of time","C":"The total value of non-current assets owned by a business on a specific date","D":"The total amount of share capital invested by ordinary shareholders"},"correctOption":"B","correctAnswer":"The movement of cash inflows into and cash outflows out of a business over a period of time","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because cash flow tracks the actual receipts (inflows) and payments (outflows) moving through a business's bank and cash balances over time.","distractor_reasons":{"A":"Incorrect because total profit is calculated on the statement of profit or loss and differs from cash flow.","B":"Correct selection.","C":"Incorrect because non-current asset values appear on the statement of financial position.","D":"Incorrect because share capital is owners' equity on the statement of financial position."}}},{"id":"P1_U5_MCQ_527","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_527","question":"Which of the following is an example of a 'cash inflow' for a business?","options":{"A":"Paying monthly wages to production workers","B":"Purchasing raw materials from suppliers for immediate cash","C":"Receiving payments from trade receivables (credit customers) who have settled their invoices","D":"Paying corporation tax to government tax authorities"},"correctOption":"C","correctAnswer":"Receiving payments from trade receivables (credit customers) who have settled their invoices","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because collecting payments owed by credit customers brings actual money into the business's bank account.","distractor_reasons":{"A":"Incorrect because paying wages is a cash outflow.","B":"Incorrect because paying suppliers for raw materials is a cash outflow.","C":"Correct selection.","D":"Incorrect because paying corporation tax is a cash outflow."}}},{"id":"P1_U5_MCQ_528","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_528","question":"Which of the following is an example of a 'cash outflow' for a business?","options":{"A":"Receiving a new long-term loan from a commercial bank","B":"Collecting cash sales from retail customers at the checkout","C":"Receiving a non-repayable government grant into the bank account","D":"Paying suppliers for inventory, paying rent, and purchasing new equipment for cash"},"correctOption":"D","correctAnswer":"Paying suppliers for inventory, paying rent, and purchasing new equipment for cash","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because payments to suppliers, rent expenses, and cash asset purchases all result in money leaving the business.","distractor_reasons":{"A":"Incorrect because receiving loan funds brings money into the business (cash inflow).","B":"Incorrect because cash sales generate a cash inflow.","C":"Incorrect because receiving a grant is a cash inflow.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_529","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_529","question":"Why is a sale made on 60-day credit NOT recorded as a cash inflow in the month the goods are delivered?","options":{"A":"Because no actual money enters the business's bank account until the customer pays the invoice two months later","B":"Because credit sales are excluded from all accounting records until the financial year ends","C":"Because credit sales are classified as non-current liabilities","D":"Because credit sales reduce the business's gross profit"},"correctOption":"A","correctAnswer":"Because no actual money enters the business's bank account until the customer pays the invoice two months later","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cash flow forecasts strictly record cash movements when money actually enters or leaves the bank, whereas revenue is recognized on the income statement at the point of sale.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because credit sales are recorded immediately as revenue on the statement of profit or loss and as trade receivables on the statement of financial position.","C":"Incorrect because unpaid credit sales are trade receivables (current assets).","D":"Incorrect because credit sales add to revenue and gross profit."}}},{"id":"P1_U5_MCQ_530","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_530","question":"Why is 'depreciation' excluded from a cash flow forecast?","options":{"A":"Because depreciation is illegal to calculate in limited companies","B":"Because depreciation is a non-cash accounting charge that spreads an asset's cost over time without any money leaving the bank","C":"Because depreciation is recorded as a cash inflow at the end of each year","D":"Because depreciation only applies to raw material inventories"},"correctOption":"B","correctAnswer":"Because depreciation is a non-cash accounting charge that spreads an asset's cost over time without any money leaving the bank","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the cash outflow happens when the non-current asset is paid for; subsequent annual depreciation charges do not involve physical cash movements.","distractor_reasons":{"A":"Incorrect because depreciation is a standard accounting requirement.","B":"Correct selection.","C":"Incorrect because depreciation is an expense on the statement of profit or loss, never a cash inflow.","D":"Incorrect because depreciation applies to non-current assets such as machinery and vehicles, not inventories."}}},{"id":"P1_U5_MCQ_531","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_531","question":"How is 'net cash flow' calculated for a given month?","options":{"A":"Opening cash balance + Closing cash balance","B":"Sales revenue - Cost of sales","C":"Total cash inflows - Total cash outflows","D":"Current assets - Current liabilities"},"correctOption":"C","correctAnswer":"Total cash inflows - Total cash outflows","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because net cash flow measures the net gain or loss of cash during a specific period by subtracting total cash outflows from total cash inflows.","distractor_reasons":{"A":"Incorrect because opening and closing balances are stock positions at the start and end of the month.","B":"Incorrect because sales revenue minus cost of sales calculates gross profit.","C":"Correct selection.","D":"Incorrect because current assets minus current liabilities calculates working capital."}}},{"id":"P1_U5_MCQ_532","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_532","question":"How is the 'closing cash balance' at the end of a month calculated?","options":{"A":"Total cash inflows + Total cash outflows","B":"Opening cash balance - Total cash inflows","C":"Gross profit + Net cash flow","D":"Opening cash balance + Net cash flow"},"correctOption":"D","correctAnswer":"Opening cash balance + Net cash flow","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the closing balance reflects the cash held at the start of the month adjusted by the month's net cash flow (inflows minus outflows).","distractor_reasons":{"A":"Incorrect because adding inflows and outflows ignores the direction of cash movement and the opening balance.","B":"Incorrect because inflows add to cash rather than being subtracted.","C":"Incorrect because gross profit is an income statement figure, not a cash balance.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_533","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_533","question":"On a multi-month cash flow forecast, how does the 'closing balance' of one month relate to the following month?","options":{"A":"The closing cash balance at the end of one month becomes the opening cash balance at the start of the next month","B":"The closing cash balance is reset to zero at the start of every new month","C":"The closing cash balance is transferred to retained profit and removed from the bank account","D":"The closing cash balance becomes the next month's total cash outflows"},"correctOption":"A","correctAnswer":"The closing cash balance at the end of one month becomes the opening cash balance at the start of the next month","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cash balances carry forward continuously from the end of one accounting period into the start of the next.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cash in a bank account does not vanish at month-end.","C":"Incorrect because retained profit is an accounting equity figure, not a physical removal of bank cash.","D":"Incorrect because an opening balance is a starting cash position, not an expense."}}},{"id":"P1_U5_MCQ_534","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_534","question":"What does a negative closing cash balance on a cash flow forecast indicate?","options":{"A":"The business has earned a net loss on its statement of profit or loss","B":"The business is forecast to have a cash deficit and will need a bank overdraft or alternative cash injection to pay its bills","C":"The business has zero non-current assets","D":"The business has paid off all its long-term liabilities"},"correctOption":"B","correctAnswer":"The business is forecast to have a cash deficit and will need a bank overdraft or alternative cash injection to pay its bills","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a negative closing balance signals that cash outflows have exceeded available cash plus inflows, requiring an overdraft facility or corrective action.","distractor_reasons":{"A":"Incorrect because a business can be profitable while experiencing a temporary cash deficit.","B":"Correct selection.","C":"Incorrect because negative cash balances often result from heavy spending on non-current assets.","D":"Incorrect because a negative cash balance indicates a cash shortfall, not debt elimination."}}},{"id":"P1_U5_MCQ_535","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_535","question":"What is a 'cash flow forecast'?","options":{"A":"A historical record of all assets and liabilities held by a company at the end of last year","B":"A legal tax return submitted to calculate corporation tax on past profits","C":"An estimate of future cash inflows and cash outflows for a business, usually broken down on a month-by-month basis","D":"A list of all shareholders and the number of voting shares they hold"},"correctOption":"C","correctAnswer":"An estimate of future cash inflows and cash outflows for a business, usually broken down on a month-by-month basis","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a cash flow forecast is a forward-looking financial planning tool projecting expected monthly receipts, payments, and cash balances.","distractor_reasons":{"A":"Incorrect because a historical record of assets and liabilities is a statement of financial position.","B":"Incorrect because tax calculations rely on historical profit statements.","C":"Correct selection.","D":"Incorrect because shareholder ownership records are maintained in a company's share register."}}},{"id":"P1_U5_MCQ_536","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_536","question":"Why is preparing a cash flow forecast particularly important when starting up a new business?","options":{"A":"It guarantees that customers will pay immediately in cash rather than asking for credit","B":"It legally exempts the start-up from paying value-added taxes","C":"It fixes supplier raw material prices for the first three years of trading","D":"It helps the entrepreneur calculate how much initial working capital is needed to survive early months before sales receipts cover expenses"},"correctOption":"D","correctAnswer":"It helps the entrepreneur calculate how much initial working capital is needed to survive early months before sales receipts cover expenses","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because new businesses face heavy upfront outflows and slow initial inflows; forecasting shows the minimum cash buffer required to avoid early failure.","distractor_reasons":{"A":"Incorrect because a forecast estimates customer behavior rather than forcing cash payments.","B":"Incorrect because forecasts provide no tax exemptions.","C":"Incorrect because forecasts estimate future costs rather than locking in supplier contracts.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_537","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_537","question":"Why do commercial banks require a cash flow forecast before approving a business loan or overdraft?","options":{"A":"To check the size and timing of expected cash shortages and verify that the business will generate enough future cash inflows to repay the borrowing","B":"To calculate the exact depreciation rate of the business's office furniture","C":"Because banks are legally forbidden from viewing statements of profit or loss","D":"To determine how many employees the business should hire"},"correctOption":"A","correctAnswer":"To check the size and timing of expected cash shortages and verify that the business will generate enough future cash inflows to repay the borrowing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because lenders evaluate repayment capacity and credit risk by examining when cash deficits occur and when surpluses return.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because depreciation is non-cash and is not shown on a cash flow forecast.","C":"Incorrect because banks review historical profit statements alongside cash flow forecasts.","D":"Incorrect because staffing decisions belong to business managers, not the bank."}}},{"id":"P1_U5_MCQ_538","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_538","question":"How can managers use a cash flow forecast when it predicts large positive cash surpluses accumulating over several months?","options":{"A":"Stop sending invoices to credit customers until the surplus disappears","B":"Plan productive uses for idle cash, such as repaying high-interest debt early, buying stock in bulk for discounts, or placing funds in interest-earning deposits","C":"Ask the bank for an emergency short-term overdraft","D":"Ignore the surplus because positive cash balances cannot be spent"},"correctOption":"B","correctAnswer":"Plan productive uses for idle cash, such as repaying high-interest debt early, buying stock in bulk for discounts, or placing funds in interest-earning deposits","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because holding excessive idle cash in a zero-interest current account incurs an opportunity cost; forecasting surpluses allows smart treasury planning.","distractor_reasons":{"A":"Incorrect because delaying invoices weakens credit control and increases bad-debt risk.","B":"Correct selection.","C":"Incorrect because an overdraft is needed for cash deficits, not cash surpluses.","D":"Incorrect because positive cash balances are liquid funds available for business use."}}},{"id":"P1_U5_MCQ_539","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_539","question":"How does regular monitoring of a cash flow forecast help prevent business failure?","options":{"A":"It automatically converts all trade payables into shareholders' equity","B":"It guarantees that gross profit margin will rise every quarter","C":"It gives managers advance warning of upcoming cash deficits so they can arrange overdrafts, delay capital spending, or tighten credit control in time","D":"It eliminates the legal obligation to pay employee wages during slow months"},"correctOption":"C","correctAnswer":"It gives managers advance warning of upcoming cash deficits so they can arrange overdrafts, delay capital spending, or tighten credit control in time","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because spotting a forecast cash shortage months ahead allows proactive corrective measures before the business runs out of cash.","distractor_reasons":{"A":"Incorrect because supplier debts remain liabilities until paid.","B":"Incorrect because a cash flow forecast monitors liquidity rather than guaranteeing profit margins.","C":"Correct selection.","D":"Incorrect because wages remain legally payable regardless of seasonal trading."}}},{"id":"P1_U5_MCQ_540","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_540","question":"Which statement accurately describes the difference between 'cash' and 'profit'?","options":{"A":"Cash and profit are always identical at the end of every trading month","B":"Cash is recorded only on the statement of profit or loss, whereas profit is recorded only on the cash flow forecast","C":"Profit includes bank loans received, whereas cash excludes bank loans received","D":"Profit is the surplus of revenue over costs over a trading period, whereas cash is the liquid money held by the business at a point in time"},"correctOption":"D","correctAnswer":"Profit is the surplus of revenue over costs over a trading period, whereas cash is the liquid money held by the business at a point in time","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because profit measures trading performance (including credit transactions and non-cash depreciation), whereas cash measures actual liquid funds available to pay bills.","distractor_reasons":{"A":"Incorrect because credit terms, asset purchases, and loan movements cause cash and profit to diverge.","B":"Incorrect because this reverses where cash and profit are recorded.","C":"Incorrect because bank loans received are cash inflows, not trading profit.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_541","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_541","question":"How can a business that reports a healthy profit on its statement of profit or loss still run out of cash and face liquidation?","options":{"A":"By selling goods on long credit terms to customers while having to pay suppliers, wages, and capital expenditure immediately in cash","B":"Because profitable businesses are legally prohibited from holding positive bank balances","C":"Because gross profit is always subtracted from the bank current account","D":"By receiving all customer payments upfront in cash before incurring any costs"},"correctOption":"A","correctAnswer":"By selling goods on long credit terms to customers while having to pay suppliers, wages, and capital expenditure immediately in cash","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because credit sales count toward revenue and profit immediately, but if cash is tied up in slow-paying trade receivables or heavy capital purchases, the business can run out of liquid cash.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because profitable firms routinely hold positive bank balances.","C":"Incorrect because gross profit is a calculation, not a cash deduction.","D":"Incorrect because collecting cash upfront before paying costs creates strong positive cash flow."}}},{"id":"P1_U5_MCQ_542","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_542","question":"How can a business that makes a trading loss during a period still record a positive net cash flow?","options":{"A":"By paying all suppliers upfront in cash while giving customers 90-day credit","B":"By receiving a large cash inflow from a new bank loan, share issue, or sale of non-current assets, or by collecting past trade receivables","C":"Because trading losses are automatically added to the bank current account","D":"By purchasing expensive freehold land using physical cash"},"correctOption":"B","correctAnswer":"By receiving a large cash inflow from a new bank loan, share issue, or sale of non-current assets, or by collecting past trade receivables","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because non-trading cash inflows (loans, equity injections, asset sales) and collections from previous credit sales boost cash without counting as current-period profit.","distractor_reasons":{"A":"Incorrect because paying upfront and granting long credit worsens cash flow.","B":"Correct selection.","C":"Incorrect because trading losses drain rather than increase cash.","D":"Incorrect because buying freehold land for cash causes a large cash outflow."}}},{"id":"P1_U5_MCQ_543","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_543","question":"Which sequence accurately represents the 'working capital cycle'?","options":{"A":"Cash -> issue shares -> buy freehold land -> pay dividends","B":"Trade payables -> depreciation -> non-current liabilities -> retained profit","C":"Cash -> purchase inventories -> produce and sell goods on credit -> collect cash from trade receivables","D":"Bank overdraft -> fixed assets -> corporation tax -> liquidation"},"correctOption":"C","correctAnswer":"Cash -> purchase inventories -> produce and sell goods on credit -> collect cash from trade receivables","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the working capital cycle shows how cash is spent on stock and production, converted into trade receivables upon credit sale, and returned as cash when customers pay.","distractor_reasons":{"A":"Incorrect because share issues and land purchases are long-term capital transactions.","B":"Incorrect because depreciation and non-current liabilities are not part of the short-term trading cash cycle.","C":"Correct selection.","D":"Incorrect because this does not represent the operational flow of current assets."}}},{"id":"P1_U5_MCQ_544","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_544","question":"Why is arranging or increasing a 'bank overdraft' often used to overcome a temporary, short-term cash flow deficit?","options":{"A":"It eliminates all future business costs permanently","B":"It increases sales revenue on the statement of profit or loss","C":"It converts short-term trade payables into permanent share capital","D":"It is flexible, quick to arrange, and allows the business to spend more than its current account balance up to an agreed limit, paying interest only on the overdrawn amount"},"correctOption":"D","correctAnswer":"It is flexible, quick to arrange, and allows the business to spend more than its current account balance up to an agreed limit, paying interest only on the overdrawn amount","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because an overdraft is specifically designed to bridge brief seasonal or timing gaps in cash flow without taking on a rigid multi-year loan.","distractor_reasons":{"A":"Incorrect because an overdraft adds interest expenses rather than eliminating costs.","B":"Incorrect because borrowing via an overdraft does not generate sales revenue.","C":"Incorrect because an overdraft is a short-term debt liability, not share capital.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_545","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_545","question":"How does 'delaying payments to suppliers' (extending trade credit) help resolve a short-term cash shortage?","options":{"A":"It postpones cash outflows into a later month, keeping cash inside the business during the deficit period","B":"It increases immediate cash inflows from retail customers","C":"It permanently cancels the legal obligation to pay for raw materials","D":"It increases the business's gross profit margin"},"correctOption":"A","correctAnswer":"It postpones cash outflows into a later month, keeping cash inside the business during the deficit period","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because negotiating longer payment terms with trade payables slows down cash outflows and preserves immediate liquidity.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because supplier credit affects cash outflows, not customer inflows.","C":"Incorrect because supplier invoices must still be paid at the end of the extended credit period.","D":"Incorrect because delaying payment does not reduce the purchase cost of goods sold."}}},{"id":"P1_U5_MCQ_546","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_546","question":"How does 'asking credit customers to pay more quickly' or 'offering a prompt-payment discount' improve a business's cash flow?","options":{"A":"It delays cash outflows for staff wages and factory rent","B":"It accelerates cash inflows from trade receivables so cash enters the bank account sooner","C":"It increases the value of unsold inventories on the statement of financial position","D":"It reduces the business's non-current liabilities"},"correctOption":"B","correctAnswer":"It accelerates cash inflows from trade receivables so cash enters the bank account sooner","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because shortening the credit collection period converts trade receivables into liquid cash faster, though offering a cash discount slightly reduces profit.","distractor_reasons":{"A":"Incorrect because customer credit policies influence cash inflows rather than wage or rent outflows.","B":"Correct selection.","C":"Incorrect because collecting receivables reduces trade receivables and increases cash, leaving inventory unchanged.","D":"Incorrect because customer collections affect current assets, not non-current liabilities."}}},{"id":"P1_U5_MCQ_547","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_547","question":"How does 'delaying or cancelling planned capital expenditure' (such as postponing the purchase of new machinery) help solve a forecast cash deficit?","options":{"A":"It generates immediate cash inflows from external investors","B":"It increases monthly sales revenue","C":"It avoids a large cash outflow in the short term, preserving cash to cover essential day-to-day running costs","D":"It reduces the business's trade payables to zero"},"correctOption":"C","correctAnswer":"It avoids a large cash outflow in the short term, preserving cash to cover essential day-to-day running costs","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital equipment purchases involve substantial cash outflows; deferring non-urgent capital spending immediately relieves pressure on cash balances.","distractor_reasons":{"A":"Incorrect because postponing spending avoids an outflow rather than creating an external inflow.","B":"Incorrect because delaying machinery purchases does not directly raise sales revenue.","C":"Correct selection.","D":"Incorrect because existing supplier bills still have to be paid."}}},{"id":"P1_U5_MCQ_548","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_548","question":"What is a major limitation of taking out a 'short-term bank loan' to solve a recurring cash flow shortage?","options":{"A":"It never increases the business's immediate cash balance","B":"It immediately reduces the business's gross profit margin","C":"It forces the business to give up its limited liability status","D":"While it provides a temporary cash inflow, it creates future cash outflows through interest charges and principal repayments, without fixing underlying trading problems"},"correctOption":"D","correctAnswer":"While it provides a temporary cash inflow, it creates future cash outflows through interest charges and principal repayments, without fixing underlying trading problems","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because borrowing bridges a short-term cash gap, but the debt must be repaid with interest later and does not resolve poor credit control or unprofitability.","distractor_reasons":{"A":"Incorrect because receiving loan funds directly increases the immediate cash balance.","B":"Incorrect because loan interest is a finance expense deducted after gross profit.","C":"Incorrect because borrowing does not alter legal structure.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_549","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_549","question":"What is a major risk of repeatedly 'delaying payments to suppliers' without their agreement in order to improve cash flow?","options":{"A":"Suppliers may refuse future deliveries, withdraw trade credit, charge late-payment penalties, or take legal action to recover the debt","B":"The business's corporation tax bill will automatically double","C":"Credit customers will stop paying their invoices","D":"The business's non-current assets will lose all market value"},"correctOption":"A","correctAnswer":"Suppliers may refuse future deliveries, withdraw trade credit, charge late-payment penalties, or take legal action to recover the debt","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because damaging supplier goodwill by paying late can cut off vital raw material supplies and force the business to pay cash on delivery in the future.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because late supplier payments do not double corporation tax rates.","C":"Incorrect because supplier relationships do not dictate whether customers pay.","D":"Incorrect because late supplier payments do not alter non-current asset values."}}},{"id":"P1_U5_MCQ_550","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_550","question":"What is a key limitation of all 'cash flow forecasts'?","options":{"A":"They are legally forbidden from including cash inflows from credit customers","B":"They rely on estimates and assumptions about future sales, costs, and payment timings, which may prove inaccurate due to unexpected market changes","C":"They can only be prepared after the financial year has completely ended","D":"They ignore all cash outflows such as rent, wages, and loan repayments"},"correctOption":"B","correctAnswer":"They rely on estimates and assumptions about future sales, costs, and payment timings, which may prove inaccurate due to unexpected market changes","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because forecasts project future events; sudden shifts in demand, raw material prices, interest rates, or customer defaults can cause actual cash flows to differ from forecasts.","distractor_reasons":{"A":"Incorrect because expected receipts from credit customers are a central component of cash flow forecasts.","B":"Correct selection.","C":"Incorrect because cash flow forecasts are forward-looking planning tools prepared before or during a trading period.","D":"Incorrect because all expected cash outflows are included in a cash flow forecast."}}},{"id":"P1_U5_MCQ_551","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_551","question":"How is 'profit' defined for a business over a trading period?","options":{"A":"The total physical cash held in the business's bank account at year-end","B":"The total value of all assets minus all liabilities on the statement of financial position","C":"The positive financial surplus remaining when total revenue exceeds total costs over a period of time","D":"The total amount of money raised by issuing shares and taking bank loans"},"correctOption":"C","correctAnswer":"The positive financial surplus remaining when total revenue exceeds total costs over a period of time","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because profit is a flow measure over an accounting period calculated as Total revenue minus Total costs.","distractor_reasons":{"A":"Incorrect because physical cash in the bank is liquidity, not profit.","B":"Incorrect because total assets minus total liabilities equals net assets (equity).","C":"Correct selection.","D":"Incorrect because share issues and loans are financing inflows, not trading profit."}}},{"id":"P1_U5_MCQ_552","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_552","question":"Why is earning profit vital for private sector businesses?","options":{"A":"Because earning profit legally exempts a business from paying wages during recessions","B":"Because profit is the only item recorded on a cash flow forecast","C":"Because earning profit guarantees that a business will never run out of cash","D":"Because it rewards entrepreneurs and shareholders for taking risks, provides retained profit for reinvestment, and signals success to attract external investors"},"correctOption":"D","correctAnswer":"Because it rewards entrepreneurs and shareholders for taking risks, provides retained profit for reinvestment, and signals success to attract external investors","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because profit serves as the incentive for risk-taking, a primary internal source of expansion capital, and a key indicator of business viability.","distractor_reasons":{"A":"Incorrect because profitable businesses must still pay full contracted wages.","B":"Incorrect because profit is calculated on the statement of profit or loss, not the cash flow forecast.","C":"Incorrect because profitable firms can still suffer cash crises if working capital is poorly managed.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_553","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_553","question":"Why is generating a financial surplus (profit) still important for a 'social enterprise'?","options":{"A":"To remain financially self-sustaining without relying solely on donations and to reinvest surpluses into its social or environmental mission","B":"To maximize dividend payouts to wealthy stock-market speculators","C":"Because social enterprises are fined by the government if they break even","D":"Because social enterprises are prohibited from paying staff salaries"},"correctOption":"A","correctAnswer":"To remain financially self-sustaining without relying solely on donations and to reinvest surpluses into its social or environmental mission","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because social enterprises operate commercially to earn profits that are reinvested to achieve social, community, or environmental goals.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because social enterprises prioritize social objectives over maximizing private shareholder dividends.","C":"Incorrect because breaking even is not penalized by law.","D":"Incorrect because social enterprises employ paid staff alongside any volunteers."}}},{"id":"P1_U5_MCQ_554","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_554","question":"How does the purchase of a new non-current asset (such as a delivery van) for cash affect 'cash flow' versus 'profit' at the time of purchase?","options":{"A":"It reduces profit immediately by the full purchase price, but has zero effect on cash flow","B":"It reduces cash flow immediately by the full purchase price, whereas only gradual annual depreciation reduces profit over the asset's useful life","C":"It increases both cash flow and profit immediately by the purchase price","D":"It is omitted from both the cash flow forecast and the statement of financial position"},"correctOption":"B","correctAnswer":"It reduces cash flow immediately by the full purchase price, whereas only gradual annual depreciation reduces profit over the asset's useful life","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because buying a non-current asset drains cash immediately on the cash flow statement, while on the statement of profit or loss its cost is spread out via annual depreciation.","distractor_reasons":{"A":"Incorrect because paying cash immediately reduces the cash balance, while the full asset cost is not expensed at once.","B":"Correct selection.","C":"Incorrect because buying an asset is a cash outflow, not an inflow or profit.","D":"Incorrect because the cash outflow appears on the cash flow statement and the asset appears on the statement of financial position."}}},{"id":"P1_U5_MCQ_555","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_555","question":"What is the purpose of a 'statement of profit or loss' (income statement)?","options":{"A":"To show the assets, liabilities, and equity of a business on a single day","B":"To project monthly cash inflows and outflows for the upcoming year","C":"To record the revenue, costs, and profit or loss made by a business over a trading period (usually one year)","D":"To list the personal bank balances of the company's directors"},"correctOption":"C","correctAnswer":"To record the revenue, costs, and profit or loss made by a business over a trading period (usually one year)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the statement of profit or loss summarizes trading income and expenses across a financial period to show gross profit, profit for the year, and retained profit.","distractor_reasons":{"A":"Incorrect because showing assets, liabilities, and equity on a single date is the role of the statement of financial position.","B":"Incorrect because projecting future monthly cash movements is the role of a cash flow forecast.","C":"Correct selection.","D":"Incorrect because directors' personal finances are separate from company financial statements."}}},{"id":"P1_U5_MCQ_556","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_556","question":"What is meant by 'revenue' (sales revenue) on a statement of profit or loss?","options":{"A":"The total cash received from bank loans and share issues during the year","B":"The profit remaining after deducting cost of sales from total sales","C":"The total value of unsold goods held in the warehouse at year-end","D":"The total income earned by a business from selling its goods or services during a period (Selling price × Quantity sold)"},"correctOption":"D","correctAnswer":"The total income earned by a business from selling its goods or services during a period (Selling price × Quantity sold)","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because revenue represents total trading turnover generated from sales of products or services, whether sold for cash or on credit.","distractor_reasons":{"A":"Incorrect because bank loans and share issues are financing receipts, not trading revenue.","B":"Incorrect because sales minus cost of sales defines gross profit.","C":"Incorrect because unsold goods at year-end are closing inventory.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_557","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_557","question":"What is meant by 'cost of sales' on a statement of profit or loss?","options":{"A":"The direct costs of producing or purchasing the specific goods that were actually sold during the trading period","B":"All indirect overhead expenses such as head-office rent, marketing, and administrative salaries","C":"The purchase price of new freehold land and factory buildings","D":"Corporation tax paid to the government on annual profits"},"correctOption":"A","correctAnswer":"The direct costs of producing or purchasing the specific goods that were actually sold during the trading period","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cost of sales measures direct variable/production costs (such as raw materials, direct factory wages, or wholesale cost of goods resold) linked to items sold.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because indirect running costs are overhead expenses deducted after gross profit.","C":"Incorrect because freehold land and buildings are non-current assets (capital expenditure).","D":"Incorrect because corporation tax is deducted after operating profit is calculated."}}},{"id":"P1_U5_MCQ_558","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_558","question":"How is 'cost of sales' calculated for a retail business that holds inventory?","options":{"A":"Closing inventory + Purchases - Opening inventory","B":"Opening inventory + Purchases - Closing inventory","C":"Revenue - Gross profit - Overhead expenses","D":"Opening inventory + Closing inventory + Purchases"},"correctOption":"B","correctAnswer":"Opening inventory + Purchases - Closing inventory","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because total goods available for sale (Opening inventory + Purchases) minus unsold goods left at year-end (Closing inventory) equals the cost of goods actually sold.","distractor_reasons":{"A":"Incorrect because opening inventory was available to sell and closing inventory remains unsold, so signs are reversed.","B":"Correct selection.","C":"Incorrect because revenue minus gross profit equals cost of sales; subtracting overhead expenses as well gives an incorrect figure.","D":"Incorrect because adding unsold closing inventory overstates the cost of items sold."}}},{"id":"P1_U5_MCQ_559","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_559","question":"How is 'gross profit' calculated on a statement of profit or loss?","options":{"A":"Revenue - Total overhead expenses","B":"Revenue - Cost of sales - Overhead expenses - Tax","C":"Revenue - Cost of sales","D":"Gross profit margin × Cost of sales"},"correctOption":"C","correctAnswer":"Revenue - Cost of sales","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because gross profit measures the trading surplus made purely from buying/producing and selling goods before indirect overhead expenses are deducted.","distractor_reasons":{"A":"Incorrect because gross profit deducts direct cost of sales, not indirect overhead expenses.","B":"Incorrect because deducting overhead expenses and tax gives profit after tax, not gross profit.","C":"Correct selection.","D":"Incorrect because gross profit margin is a percentage of revenue, not cost of sales."}}},{"id":"P1_U5_MCQ_560","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_560","question":"Which of the following best defines 'overhead expenses' (indirect expenses) on a statement of profit or loss?","options":{"A":"The direct purchase cost of raw materials incorporated into finished products","B":"The money spent buying long-term non-current assets such as delivery vans","C":"The cash dividends distributed to shareholders at the end of the year","D":"The day-to-day running costs of the business that are not directly tied to making a specific unit of output, such as office salaries, rent, and advertising"},"correctOption":"D","correctAnswer":"The day-to-day running costs of the business that are not directly tied to making a specific unit of output, such as office salaries, rent, and advertising","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because overhead expenses are indirect operational costs deducted from gross profit to calculate profit for the year.","distractor_reasons":{"A":"Incorrect because direct raw materials form part of cost of sales.","B":"Incorrect because delivery vans are capital expenditure on non-current assets.","C":"Incorrect because dividends are an appropriation of after-tax profit, not an operating expense.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_561","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_561","question":"Which item would be recorded under 'cost of sales' rather than 'overhead expenses' for a manufacturing business?","options":{"A":"Wages paid to factory assembly-line workers directly making the product","B":"Salaries paid to head-office human resources and accounting staff","C":"Annual television and social media advertising costs","D":"Insurance and electricity bills for the administrative head office"},"correctOption":"A","correctAnswer":"Wages paid to factory assembly-line workers directly making the product","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because direct production labor is directly involved in manufacturing the goods sold and therefore belongs in cost of sales.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because administrative salaries are indirect overhead expenses.","C":"Incorrect because marketing and advertising costs are indirect overhead expenses.","D":"Incorrect because head-office utilities and insurance are indirect overhead expenses."}}},{"id":"P1_U5_MCQ_562","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_562","question":"How is 'profit' (operating profit / profit before tax) calculated on a statement of profit or loss?","options":{"A":"Revenue - Cost of sales","B":"Gross profit - Overhead expenses","C":"Gross profit + Overhead expenses","D":"Profit after tax - Dividends"},"correctOption":"B","correctAnswer":"Gross profit - Overhead expenses","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because deducting all indirect overhead running expenses from gross profit yields the business's operating profit.","distractor_reasons":{"A":"Incorrect because revenue minus cost of sales calculates gross profit.","B":"Correct selection.","C":"Incorrect because overhead expenses are costs that must be subtracted, not added.","D":"Incorrect because profit after tax minus dividends calculates retained profit."}}},{"id":"P1_U5_MCQ_563","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_563","question":"Where does 'corporation tax' appear on a limited company's statement of profit or loss?","options":{"A":"It is added to sales revenue at the top of the statement","B":"It is included inside cost of sales before gross profit is calculated","C":"It is deducted from profit before tax to arrive at profit after tax","D":"It is deducted after retained profit has already been calculated"},"correctOption":"C","correctAnswer":"It is deducted from profit before tax to arrive at profit after tax","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because corporation tax is levied by the government as a percentage of a company's profit before tax, leaving profit after tax available for dividends or retention.","distractor_reasons":{"A":"Incorrect because tax is a compulsory payment, not revenue.","B":"Incorrect because corporation tax is calculated on final profit, not direct production costs.","C":"Correct selection.","D":"Incorrect because tax is paid before the company decides how much profit to retain or distribute as dividends."}}},{"id":"P1_U5_MCQ_564","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_564","question":"What are 'dividends' on a limited company's statement of profit or loss?","options":{"A":"Fixed interest payments legally owed to commercial banks on long-term loans","B":"Direct wages paid to factory production staff","C":"Taxes paid to the government on sales revenue","D":"The share of profit after tax distributed to shareholders as a return on their investment"},"correctOption":"D","correctAnswer":"The share of profit after tax distributed to shareholders as a return on their investment","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because dividends represent the portion of after-tax earnings paid out to ordinary shareholders, as recommended by the board of directors.","distractor_reasons":{"A":"Incorrect because contractual payments to banks are loan interest expenses.","B":"Incorrect because worker pay is wages/salaries.","C":"Incorrect because government levies on company profits are corporation tax.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_565","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_565","question":"What is 'retained profit'?","options":{"A":"The profit after tax remaining inside a business after dividends have been paid out to shareholders, kept for reinvestment","B":"The total cash sitting in the business's safe on the last day of the year","C":"The difference between sales revenue and cost of sales","D":"The total amount of money borrowed from banks over the past five years"},"correctOption":"A","correctAnswer":"The profit after tax remaining inside a business after dividends have been paid out to shareholders, kept for reinvestment","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because retained profit is the undistributed portion of after-tax profit ploughed back into the business to fund future growth.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because retained profit is an accounting equity figure, not physical cash in a safe.","C":"Incorrect because sales revenue minus cost of sales is gross profit.","D":"Incorrect because borrowed funds are liabilities, not retained profit."}}},{"id":"P1_U5_MCQ_566","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_566","question":"How is 'retained profit' calculated at the bottom of a company's statement of profit or loss?","options":{"A":"Gross profit - Dividends","B":"Profit after tax - Dividends","C":"Revenue - Cost of sales - Dividends","D":"Profit before tax + Dividends"},"correctOption":"B","correctAnswer":"Profit after tax - Dividends","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because once corporation tax has been subtracted from profit, the remaining profit after tax is split between dividends paid and retained profit kept.","distractor_reasons":{"A":"Incorrect because overhead expenses and corporation tax must be deducted before dividends.","B":"Correct selection.","C":"Incorrect because this omits overhead expenses and corporation tax.","D":"Incorrect because dividends are paid out (subtracted) from after-tax profit, not added."}}},{"id":"P1_U5_MCQ_567","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_567","question":"Which sequence shows the correct top-to-bottom order of items on a limited company's statement of profit or loss?","options":{"A":"Gross profit -> Revenue -> Cost of sales -> Overhead expenses -> Retained profit","B":"Revenue -> Overhead expenses -> Gross profit -> Cost of sales -> Profit after tax","C":"Revenue -> Cost of sales -> Gross profit -> Overhead expenses -> Profit before tax -> Tax -> Profit after tax -> Dividends -> Retained profit","D":"Retained profit -> Dividends -> Profit after tax -> Overhead expenses -> Gross profit -> Revenue"},"correctOption":"C","correctAnswer":"Revenue -> Cost of sales -> Gross profit -> Overhead expenses -> Profit before tax -> Tax -> Profit after tax -> Dividends -> Retained profit","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a standard income statement starts with revenue, deducts cost of sales to find gross profit, deducts overheads to find profit, deducts tax, and finally appropriates after-tax profit into dividends and retained profit.","distractor_reasons":{"A":"Incorrect because revenue must appear before cost of sales and gross profit.","B":"Incorrect because cost of sales is deducted before gross profit, while overhead expenses are deducted after gross profit.","C":"Correct selection.","D":"Incorrect because this reverses the entire statement from bottom to top."}}},{"id":"P1_U5_MCQ_568","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_568","question":"If a manufacturer negotiates lower raw material prices from suppliers while keeping selling prices and sales volume unchanged, what happens on its statement of profit or loss?","options":{"A":"Revenue rises and overhead expenses fall","B":"Cost of sales rises and gross profit falls","C":"Gross profit stays unchanged while retained profit falls","D":"Cost of sales falls, which increases both gross profit and profit for the year"},"correctOption":"D","correctAnswer":"Cost of sales falls, which increases both gross profit and profit for the year","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because raw materials are a direct cost of sales; lowering them boosts gross profit directly, which flows down to increase final profit.","distractor_reasons":{"A":"Incorrect because unchanged selling prices and volume leave revenue unchanged, and raw materials are not overhead expenses.","B":"Incorrect because lower material prices reduce cost of sales and increase gross profit.","C":"Incorrect because lower direct costs directly increase gross profit.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_569","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_569","question":"If a business reduces its head-office administrative salaries while revenue and direct production costs stay constant, how are gross profit and profit for the year affected?","options":{"A":"Gross profit stays unchanged, while profit for the year increases","B":"Both gross profit and profit for the year increase","C":"Gross profit increases, while profit for the year stays unchanged","D":"Both gross profit and profit for the year decrease"},"correctOption":"A","correctAnswer":"Gross profit stays unchanged, while profit for the year increases","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because administrative salaries are indirect overhead expenses deducted after gross profit; reducing them leaves gross profit untouched while raising final profit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because gross profit only depends on revenue and cost of sales.","C":"Incorrect because gross profit does not change when indirect overheads fall.","D":"Incorrect because lowering expenses increases rather than decreases profit."}}},{"id":"P1_U5_MCQ_570","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_570","question":"Why does raising the selling price of a product with price-inelastic demand normally increase a business's revenue and profit?","options":{"A":"Because customers buy a much larger quantity when prices increase","B":"Because the percentage drop in quantity demanded is smaller than the percentage rise in price, so total revenue increases while total cost of sales slightly falls","C":"Because raising selling prices automatically reduces fixed rent and administrative salaries","D":"Because price-inelastic products are exempt from cost of sales"},"correctOption":"B","correctAnswer":"Because the percentage drop in quantity demanded is smaller than the percentage rise in price, so total revenue increases while total cost of sales slightly falls","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because when demand is price inelastic, customers are relatively insensitive to price hikes, lifting total revenue and profit.","distractor_reasons":{"A":"Incorrect because higher prices still reduce quantity demanded slightly (unless it is a rare Veblen good).","B":"Correct selection.","C":"Incorrect because retail pricing does not reduce fixed overhead costs.","D":"Incorrect because every physical product still incurs direct cost of sales."}}},{"id":"P1_U5_MCQ_571","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_571","question":"What strategic trade-off do company directors face when deciding how to divide profit after tax between dividends and retained profit?","options":{"A":"Paying dividends increases corporation tax rates, whereas retaining profit reduces sales revenue","B":"Retained profit must be paid to commercial banks, whereas dividends are paid to suppliers","C":"Paying higher dividends satisfies current shareholders and supports share demand, whereas retaining more profit provides interest-free internal finance for future growth","D":"Dividends are deducted before gross profit, whereas retained profit is deducted before operating profit"},"correctOption":"C","correctAnswer":"Paying higher dividends satisfies current shareholders and supports share demand, whereas retaining more profit provides interest-free internal finance for future growth","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because every dollar paid out as a dividend is a dollar unavailable for internal reinvestment, requiring directors to balance short-term shareholder rewards against long-term expansion.","distractor_reasons":{"A":"Incorrect because dividend choices do not alter tax rates or sales revenue.","B":"Incorrect because retained profit stays inside the company and dividends go to shareholders.","C":"Correct selection.","D":"Incorrect because both dividends and retained profit appear at the very bottom after profit after tax."}}},{"id":"P1_U5_MCQ_572","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_572","question":"How do existing shareholders and potential investors primarily use a company's statement of profit or loss?","options":{"A":"To check the exact daily cash balance held in the company's till","B":"To verify whether the company owns freehold land free of mortgages","C":"To calculate the company's current ratio and acid-test ratio","D":"To assess revenue growth, cost control, and profit trends in order to judge management performance and likely future dividends"},"correctOption":"D","correctAnswer":"To assess revenue growth, cost control, and profit trends in order to judge management performance and likely future dividends","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because shareholders focus on profitability trends over time and against rivals to evaluate returns on their equity investment.","distractor_reasons":{"A":"Incorrect because cash balances appear on the statement of financial position, not the income statement.","B":"Incorrect because freehold property and mortgages appear on the statement of financial position.","C":"Incorrect because liquidity ratios are calculated using current assets and current liabilities from the statement of financial position.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_573","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_573","question":"Why do commercial banks examine a business's statement of profit or loss when evaluating a loan application?","options":{"A":"To check whether the business generates sufficient operating profit to afford interest payments and remain viable over the loan period","B":"To determine the exact resale value of the business's existing machinery","C":"To calculate how much inventory the business holds in its warehouse","D":"To decide which suppliers the business should purchase raw materials from"},"correctOption":"A","correctAnswer":"To check whether the business generates sufficient operating profit to afford interest payments and remain viable over the loan period","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sustained profitability gives lenders confidence that the borrower can service interest obligations and survive long term.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because non-current asset values appear on the statement of financial position.","C":"Incorrect because closing inventory values appear on the statement of financial position.","D":"Incorrect because supplier selection is an operational decision for business managers."}}},{"id":"P1_U5_MCQ_574","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_574","question":"Why are employees and trade unions interested in reading a company's annual statement of profit or loss?","options":{"A":"To calculate the company's acid-test ratio before approving a share issue","B":"To assess job security and use strong profit figures as evidence when negotiating wage increases or bonuses","C":"To verify whether the company has paid its suppliers within 30 days","D":"To set the government's corporation tax rate for the upcoming year"},"correctOption":"B","correctAnswer":"To assess job security and use strong profit figures as evidence when negotiating wage increases or bonuses","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because rising profits reassure workers that their jobs are safe and strengthen trade union arguments that the employer can afford higher pay.","distractor_reasons":{"A":"Incorrect because liquidity ratios come from the statement of financial position, and share issues are approved by shareholders.","B":"Correct selection.","C":"Incorrect because trade payables appear on the statement of financial position.","D":"Incorrect because governments set tax rates, not trade unions."}}},{"id":"P1_U5_MCQ_575","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_575","question":"What is a major limitation of using only a statement of profit or loss to judge a business's financial health?","options":{"A":"It omits all indirect overhead expenses and corporation tax","B":"It only records transactions where physical banknotes changed hands","C":"It shows past profitability rather than cash liquidity or debt burdens, so a highly profitable business could still be close to running out of cash","D":"It is prepared only once every ten years by public limited companies"},"correctOption":"C","correctAnswer":"It shows past profitability rather than cash liquidity or debt burdens, so a highly profitable business could still be close to running out of cash","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the statement of profit or loss does not display cash balances, working capital, or long-term debt liabilities, requiring analysis alongside the statement of financial position.","distractor_reasons":{"A":"Incorrect because overhead expenses and tax are always included on the statement of profit or loss.","B":"Incorrect because credit transactions are included on an accruals basis.","C":"Correct selection.","D":"Incorrect because limited companies must prepare financial statements annually."}}},{"id":"P1_U5_MCQ_576","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_576","question":"What is the primary purpose of a 'statement of financial position' (balance sheet)?","options":{"A":"To record total sales revenue, cost of sales, and profit earned across an entire year","B":"To forecast expected monthly cash inflows and outflows for the next 12 months","C":"To calculate the exact break-even level of output for a new product","D":"To show the value of a business's assets, liabilities, and owners' equity at one specific point in time"},"correctOption":"D","correctAnswer":"To show the value of a business's assets, liabilities, and owners' equity at one specific point in time","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the statement of financial position details what the business owns (assets), what it owes (liabilities), and how it is financed (equity) on the reporting date.","distractor_reasons":{"A":"Incorrect because revenue and profit over a year are shown on the statement of profit or loss.","B":"Incorrect because future monthly cash movements are shown on a cash flow forecast.","C":"Incorrect because break-even analysis is a separate cost-volume-profit management tool.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_577","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_577","question":"Why is a statement of financial position often described as a 'financial snapshot'?","options":{"A":"Because its figures are only valid on the exact date it is drawn up, since trading transactions change asset, liability, and cash balances the very next day","B":"Because it includes photographs of all factories and vehicles owned by the firm","C":"Because it only measures transactions that take place during a single 24-hour trading day","D":"Because its numbers are legally fixed and never change across consecutive years"},"correctOption":"A","correctAnswer":"Because its figures are only valid on the exact date it is drawn up, since trading transactions change asset, liability, and cash balances the very next day","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because unlike flow statements (income statement and cash flow forecast) that cover a period, the statement of financial position captures balances at a single instant in time.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because it is a quantitative financial table, not a set of photographs.","C":"Incorrect because the balances reflect cumulative positions built up over time up to that date.","D":"Incorrect because asset, debt, and reserve balances change continuously as the business operates."}}},{"id":"P1_U5_MCQ_578","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_578","question":"What are 'assets' on a statement of financial position?","options":{"A":"Debts and financial obligations that the business owes to external creditors and banks","B":"Items of monetary value that are owned by the business, such as property, equipment, inventories, trade receivables, and cash","C":"The indirect overhead expenses incurred in running the business during the year","D":"Dividends paid out to ordinary shareholders"},"correctOption":"B","correctAnswer":"Items of monetary value that are owned by the business, such as property, equipment, inventories, trade receivables, and cash","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because assets are economic resources controlled/owned by the business that provide future economic benefit.","distractor_reasons":{"A":"Incorrect because amounts owed to external parties are liabilities.","B":"Correct selection.","C":"Incorrect because running costs are expenses on the statement of profit or loss.","D":"Incorrect because dividends are distributions of profit to owners."}}},{"id":"P1_U5_MCQ_579","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_579","question":"What are 'liabilities' on a statement of financial position?","options":{"A":"Physical resources owned by the business for more than one year","B":"Unpaid invoices owed to the business by its credit customers","C":"Debts and financial obligations owed by the business to outside parties, such as suppliers, banks, and tax authorities","D":"The retained profits accumulated inside the business over previous years"},"correctOption":"C","correctAnswer":"Debts and financial obligations owed by the business to outside parties, such as suppliers, banks, and tax authorities","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because liabilities represent external claims against the business's assets that must be settled in the short or long term.","distractor_reasons":{"A":"Incorrect because long-term physical resources owned by the business are non-current assets.","B":"Incorrect because money owed by customers is trade receivables (a current asset).","C":"Correct selection.","D":"Incorrect because retained profit forms part of owners' equity, not an external debt liability."}}},{"id":"P1_U5_MCQ_580","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_580","question":"How are 'non-current assets' (fixed assets) defined?","options":{"A":"Short-term assets that are expected to be converted into cash within 12 months","B":"Debts that must be repaid to suppliers within 30 days","C":"The share capital invested by the founders of the company","D":"Long-term resources owned and used by a business for more than one year to generate income, rather than held for immediate resale"},"correctOption":"D","correctAnswer":"Long-term resources owned and used by a business for more than one year to generate income, rather than held for immediate resale","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because non-current assets have a useful life exceeding one year and support ongoing operations (such as land, buildings, vehicles, and machinery).","distractor_reasons":{"A":"Incorrect because assets converted into cash within 12 months are current assets.","B":"Incorrect because short-term supplier debts are current liabilities (trade payables).","C":"Incorrect because share capital is equity.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_581","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_581","question":"Which group consists ENTIRELY of 'non-current assets'?","options":{"A":"Freehold factory land, warehouse buildings, production machinery, and delivery vehicles","B":"Delivery vehicles, raw material inventory, and cash at bank","C":"Factory buildings, trade receivables, and office computers","D":"Production machinery, 10-year bank loan, and freehold land"},"correctOption":"A","correctAnswer":"Freehold factory land, warehouse buildings, production machinery, and delivery vehicles","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because land, buildings, machinery, and vehicles are all long-term assets retained in the business for more than one year.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because raw material inventory and cash at bank are current assets.","C":"Incorrect because trade receivables are current assets.","D":"Incorrect because a 10-year bank loan is a non-current liability."}}},{"id":"P1_U5_MCQ_582","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_582","question":"Why are non-current assets such as machinery and vehicles reduced in value each year on a statement of financial position through 'depreciation'?","options":{"A":"Because the business sells a small percentage of its machinery every month","B":"Because non-current assets lose value over time due to wear and tear, usage, and technological obsolescence","C":"Because inflation automatically lowers the market price of all machinery every year","D":"Because depreciation increases the cash balance in the bank account"},"correctOption":"B","correctAnswer":"Because non-current assets lose value over time due to wear and tear, usage, and technological obsolescence","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because depreciation allocates the cost of a non-current asset over its useful working life to reflect loss of value from aging, wear, and newer technology.","distractor_reasons":{"A":"Incorrect because the business keeps using the machinery; depreciation is an accounting valuation adjustment.","B":"Correct selection.","C":"Incorrect because inflation generally pushes prices up, whereas depreciation accounts for asset wear and obsolescence.","D":"Incorrect because depreciation is a non-cash expense that has no effect on cash."}}},{"id":"P1_U5_MCQ_583","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_583","question":"How are 'current assets' defined on a statement of financial position?","options":{"A":"Long-term property and machinery used for more than five years","B":"Short-term debts owed by the business that must be paid within 12 months","C":"Assets owned by the business that are already cash or are expected to be sold or converted into cash within 12 months","D":"Permanent capital contributed by ordinary shareholders"},"correctOption":"C","correctAnswer":"Assets owned by the business that are already cash or are expected to be sold or converted into cash within 12 months","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because current assets are short-term working resources (inventories, trade receivables, and cash) that circulate continuously within a one-year trading cycle.","distractor_reasons":{"A":"Incorrect because long-term property and machinery are non-current assets.","B":"Incorrect because short-term debts owed by the business are current liabilities.","C":"Correct selection.","D":"Incorrect because shareholder contributions are share capital (equity)."}}},{"id":"P1_U5_MCQ_584","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_584","question":"In what order are 'current assets' normally listed on a statement of financial position from least liquid to most liquid?","options":{"A":"Cash -> Trade receivables -> Inventories","B":"Trade receivables -> Cash -> Inventories","C":"Inventories -> Cash -> Trade receivables","D":"Inventories -> Trade receivables -> Cash"},"correctOption":"D","correctAnswer":"Inventories -> Trade receivables -> Cash","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because inventories must first be sold (often on credit) to become trade receivables, which are then collected to become cash, the most liquid asset.","distractor_reasons":{"A":"Incorrect because this lists current assets from most liquid to least liquid.","B":"Incorrect because cash is already completely liquid, whereas receivables still await collection.","C":"Incorrect because trade receivables convert into cash sooner than unsold inventories.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_585","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_585","question":"What are 'trade receivables' (debtors) on a statement of financial position?","options":{"A":"Amounts of money owed to the business by customers who have purchased goods on credit, classified as a current asset","B":"Amounts of money owed by the business to its raw-material suppliers, classified as a current liability","C":"Long-term loans owed by the business to commercial banks","D":"Unsold finished goods stored in the business's warehouse"},"correctOption":"A","correctAnswer":"Amounts of money owed to the business by customers who have purchased goods on credit, classified as a current asset","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because trade receivables represent short-term sums due from credit customers that will convert into cash within the credit period.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because amounts owed to suppliers are trade payables (current liabilities).","C":"Incorrect because long-term bank loans are non-current liabilities.","D":"Incorrect because unsold finished goods are inventories."}}},{"id":"P1_U5_MCQ_586","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_586","question":"Which items are included under 'inventories' (stock) on a manufacturing company's statement of financial position?","options":{"A":"Factory machinery, delivery vans, and office computers","B":"Raw materials, work-in-progress (part-finished goods), and unsold finished goods","C":"Unpaid customer invoices and bank overdrafts","D":"Issued share capital and retained profit reserves"},"correctOption":"B","correctAnswer":"Raw materials, work-in-progress (part-finished goods), and unsold finished goods","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a manufacturer holds inventory across three stages of production: raw materials awaiting use, semi-finished work-in-progress, and finished goods ready for sale.","distractor_reasons":{"A":"Incorrect because machinery, vans, and computers are non-current assets.","B":"Correct selection.","C":"Incorrect because unpaid customer invoices are trade receivables and bank overdrafts are current liabilities.","D":"Incorrect because share capital and retained profit are shareholders' equity."}}},{"id":"P1_U5_MCQ_587","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_587","question":"How are 'current liabilities' defined?","options":{"A":"Long-term mortgages and debentures repayable over more than one year","B":"Short-term assets such as cash and trade receivables","C":"Short-term debts and financial obligations owed by a business that must be paid within 12 months","D":"The total amount of money invested in the business by its owners"},"correctOption":"C","correctAnswer":"Short-term debts and financial obligations owed by a business that must be paid within 12 months","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because current liabilities are obligations falling due within the next accounting year, such as trade payables and bank overdrafts.","distractor_reasons":{"A":"Incorrect because debts repayable over more than one year are non-current liabilities.","B":"Incorrect because cash and trade receivables are current assets.","C":"Correct selection.","D":"Incorrect because owner investments form equity."}}},{"id":"P1_U5_MCQ_588","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_588","question":"Which group consists ENTIRELY of 'current liabilities'?","options":{"A":"Trade payables, trade receivables, and cash at bank","B":"Bank overdraft, 15-year mortgage, and unpaid corporation tax","C":"Retained profit, trade payables, and bank overdraft","D":"Trade payables, bank overdraft, and unpaid short-term tax or utility bills"},"correctOption":"D","correctAnswer":"Trade payables, bank overdraft, and unpaid short-term tax or utility bills","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because trade payables, bank overdrafts, and unpaid short-term bills are all debts due for settlement within one year.","distractor_reasons":{"A":"Incorrect because trade receivables and cash at bank are current assets.","B":"Incorrect because a 15-year mortgage is a non-current liability.","C":"Incorrect because retained profit is shareholders' equity.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_589","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_589","question":"What are 'trade payables' (creditors) on a statement of financial position?","options":{"A":"Amounts of money owed by the business to suppliers for goods or raw materials bought on credit, classified as a current liability","B":"Amounts of money owed to the business by customers who bought goods on credit, classified as a current asset","C":"Dividends owed to shareholders from five years ago","D":"Freehold property owned by the business"},"correctOption":"A","correctAnswer":"Amounts of money owed by the business to suppliers for goods or raw materials bought on credit, classified as a current liability","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because trade payables arise when a business uses trade credit from suppliers and must settle those invoices within the agreed short-term credit period.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because amounts owed by credit customers are trade receivables (current assets).","C":"Incorrect because trade payables relate to commercial supplier purchases, not historical dividends.","D":"Incorrect because freehold property is a non-current asset."}}},{"id":"P1_U5_MCQ_590","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_590","question":"How are 'non-current liabilities' defined?","options":{"A":"Supplier invoices that must be paid within 30 days","B":"Long-term debts owed by a business that are repayable over a period of more than one year","C":"Long-term physical machinery owned by the business","D":"Permanent share capital issued to ordinary shareholders"},"correctOption":"B","correctAnswer":"Long-term debts owed by a business that are repayable over a period of more than one year","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because non-current liabilities represent long-term borrowed funds (repayable after more than 12 months) used to finance long-term business operations.","distractor_reasons":{"A":"Incorrect because 30-day supplier invoices are current liabilities (trade payables).","B":"Correct selection.","C":"Incorrect because machinery owned by the business is a non-current asset.","D":"Incorrect because share capital is equity, which never has to be repaid."}}},{"id":"P1_U5_MCQ_591","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_591","question":"Which group consists ENTIRELY of 'non-current liabilities'?","options":{"A":"Bank overdraft, trade payables, and long-term bank loan","B":"Share capital, retained profit, and debentures","C":"Long-term bank loans, commercial property mortgages, and debentures","D":"Freehold land, commercial mortgages, and delivery vehicles"},"correctOption":"C","correctAnswer":"Long-term bank loans, commercial property mortgages, and debentures","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because long-term bank loans, mortgages, and debentures are all long-term external debt obligations repayable over more than one year.","distractor_reasons":{"A":"Incorrect because a bank overdraft and trade payables are current liabilities.","B":"Incorrect because share capital and retained profit are shareholders' equity.","C":"Correct selection.","D":"Incorrect because freehold land and delivery vehicles are non-current assets."}}},{"id":"P1_U5_MCQ_592","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_592","question":"How is 'working capital' (net current assets) calculated on a statement of financial position?","options":{"A":"Non-current assets - Non-current liabilities","B":"Total assets - Total liabilities","C":"Current assets + Current liabilities","D":"Current assets - Current liabilities"},"correctOption":"D","correctAnswer":"Current assets - Current liabilities","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because working capital (net current assets) measures the short-term liquid resources remaining after covering all short-term liabilities due within 12 months.","distractor_reasons":{"A":"Incorrect because working capital only involves short-term current items, not non-current items.","B":"Incorrect because total assets minus total liabilities calculates net assets.","C":"Incorrect because current liabilities must be subtracted from current assets, not added.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_593","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_593","question":"How is 'net assets' calculated on a statement of financial position?","options":{"A":"Total assets - Total liabilities (or Non-current assets + Working capital - Non-current liabilities)","B":"Non-current assets + Current assets","C":"Current assets - Current liabilities","D":"Non-current liabilities + Current liabilities"},"correctOption":"A","correctAnswer":"Total assets - Total liabilities (or Non-current assets + Working capital - Non-current liabilities)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because net assets represents the net wealth of the business belonging to its owners after deducting all short-term and long-term debts from total assets.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because non-current assets plus current assets equals total assets before deducting liabilities.","C":"Incorrect because current assets minus current liabilities calculates working capital (net current assets).","D":"Incorrect because adding non-current and current liabilities equals total liabilities."}}},{"id":"P1_U5_MCQ_594","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_594","question":"What are the two main components of 'total shareholders' equity' on a limited company's statement of financial position?","options":{"A":"Non-current assets and current assets","B":"Share capital and retained profit (reserves)","C":"Current liabilities and non-current liabilities","D":"Trade receivables and trade payables"},"correctOption":"B","correctAnswer":"Share capital and retained profit (reserves)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because total shareholders' equity represents the owners' total stake in the business, consisting of original share capital plus accumulated retained profits.","distractor_reasons":{"A":"Incorrect because non-current and current assets make up total assets.","B":"Correct selection.","C":"Incorrect because current and non-current liabilities make up total external debt.","D":"Incorrect because trade receivables are current assets and trade payables are current liabilities."}}},{"id":"P1_U5_MCQ_595","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_595","question":"How is 'capital employed' calculated from a statement of financial position?","options":{"A":"Current assets - Current liabilities","B":"Share capital + Current liabilities","C":"Total shareholders' equity + Non-current liabilities (which also equals Non-current assets + Working capital)","D":"Total revenue - Cost of sales"},"correctOption":"C","correctAnswer":"Total shareholders' equity + Non-current liabilities (which also equals Non-current assets + Working capital)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital employed represents all long-term permanent funds invested in the business (owners' equity plus long-term borrowing).","distractor_reasons":{"A":"Incorrect because current assets minus current liabilities is working capital.","B":"Incorrect because short-term current liabilities are excluded from long-term capital employed.","C":"Correct selection.","D":"Incorrect because revenue minus cost of sales is gross profit."}}},{"id":"P1_U5_MCQ_596","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_596","question":"Why must a statement of financial position always 'balance'?","options":{"A":"Because cash inflows must always equal cash outflows every year","B":"Because gross profit must always equal overhead expenses","C":"Because current assets must always equal current liabilities","D":"Because every asset owned by the business is financed either by external liabilities or by owners' equity (Net assets = Total equity)"},"correctOption":"D","correctAnswer":"Because every asset owned by the business is financed either by external liabilities or by owners' equity (Net assets = Total equity)","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because of the fundamental accounting identity (Assets = Liabilities + Equity, or Net assets = Total equity), reflecting dual-entry bookkeeping.","distractor_reasons":{"A":"Incorrect because cash inflows rarely equal outflows; differences change the closing cash balance.","B":"Incorrect because if gross profit equaled overheads, profit would always be zero.","C":"Incorrect because healthy businesses normally have current assets greater than current liabilities.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_597","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_597","question":"How are the statement of profit or loss and the statement of financial position directly linked at the end of a financial year?","options":{"A":"The retained profit calculated at the bottom of the statement of profit or loss is added to the retained profit reserve under shareholders' equity on the statement of financial position","B":"The gross profit figure is recorded as a non-current liability on the statement of financial position","C":"The total overhead expenses are added to non-current assets on the statement of financial position","D":"The sales revenue figure replaces the cash balance on the statement of financial position"},"correctOption":"A","correctAnswer":"The retained profit calculated at the bottom of the statement of profit or loss is added to the retained profit reserve under shareholders' equity on the statement of financial position","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because retained profit earned during the year increases the accumulated equity reserves owned by shareholders on the year-end statement of financial position.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because gross profit is an income statement subtotal, not a debt liability.","C":"Incorrect because overhead expenses reduce profit rather than creating non-current assets.","D":"Incorrect because revenue includes credit sales and is not the year-end cash balance."}}},{"id":"P1_U5_MCQ_598","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_598","question":"Why do commercial banks examine a company's statement of financial position before approving a long-term loan?","options":{"A":"To check the company's gross profit margin on individual product lines","B":"To see what valuable non-current assets could serve as loan security (collateral) and how much debt the company already owes","C":"To calculate how many employees work in the company's marketing department","D":"To replace the need for a forward-looking cash flow forecast"},"correctOption":"B","correctAnswer":"To see what valuable non-current assets could serve as loan security (collateral) and how much debt the company already owes","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because banks assess asset backing for collateral and inspect existing current and non-current liabilities to judge default risk.","distractor_reasons":{"A":"Incorrect because gross profit margin is calculated from the statement of profit or loss.","B":"Correct selection.","C":"Incorrect because headcount is not reported on the statement of financial position.","D":"Incorrect because lenders examine both the statement of financial position and cash flow forecasts."}}},{"id":"P1_U5_MCQ_599","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_599","question":"Why do trade suppliers inspect a customer's statement of financial position before granting 60-day trade credit?","options":{"A":"To calculate the customer's annual corporation tax liability","B":"To check whether the customer's shareholders receive high dividends","C":"To verify that the customer holds enough liquid current assets (such as cash and receivables) relative to current liabilities to pay invoices on time","D":"To determine the customer's exact advertising budget"},"correctOption":"C","correctAnswer":"To verify that the customer holds enough liquid current assets (such as cash and receivables) relative to current liabilities to pay invoices on time","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because suppliers risk non-payment if a buyer has negative working capital or severe short-term liquidity shortages.","distractor_reasons":{"A":"Incorrect because tax calculations belong to tax authorities.","B":"Incorrect because suppliers care about short-term bill-paying ability rather than shareholder dividend payouts.","C":"Correct selection.","D":"Incorrect because advertising budgets are internal marketing figures."}}},{"id":"P1_U5_MCQ_600","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_600","question":"What is a major limitation of a statement of financial position when judging the true worth of a business?","options":{"A":"It omits all current liabilities and bank overdrafts","B":"It records assets at their exact future selling prices ten years from now","C":"It is legally required to exclude cash and trade receivables","D":"Non-current assets are recorded at historical cost minus depreciation rather than current market value, and valuable intangible strengths like brand reputation or skilled staff are omitted"},"correctOption":"D","correctAnswer":"Non-current assets are recorded at historical cost minus depreciation rather than current market value, and valuable intangible strengths like brand reputation or skilled staff are omitted","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because historical cost accounting can understate rising property values, and financial statements exclude non-monetary qualitative assets such as workforce skill and brand loyalty.","distractor_reasons":{"A":"Incorrect because all current liabilities and overdrafts must be included.","B":"Incorrect because statements record historical cost values rather than speculative future prices.","C":"Incorrect because cash and trade receivables are core components of current assets.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_601","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_601","question":"What is the main purpose of calculating 'financial ratios' from a business's accounts?","options":{"A":"To convert raw dollar figures into relative percentages or proportions so performance and liquidity can be meaningfully compared across time and against competitors","B":"To replace the legal requirement to prepare a statement of profit or loss and statement of financial position","C":"To guarantee that the business will earn higher profits next year","D":"To eliminate all corporation tax and interest expenses"},"correctOption":"A","correctAnswer":"To convert raw dollar figures into relative percentages or proportions so performance and liquidity can be meaningfully compared across time and against competitors","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because raw dollar profit or asset totals mean little in isolation; ratios standardize performance relative to revenue, capital, or liabilities.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because ratios are calculated from completed financial statements rather than replacing them.","C":"Incorrect because ratios are analytical tools that cannot guarantee future financial results.","D":"Incorrect because ratios measure financial figures without altering tax or interest obligations."}}},{"id":"P1_U5_MCQ_602","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_602","question":"Which two comparisons make financial ratio analysis most useful to managers and investors?","options":{"A":"Comparing a local retail shop's ratios with a multinational oil corporation and a public hospital","B":"Comparing a business's ratios over several consecutive years (trend analysis) and comparing them with competitors in the same industry (inter-firm comparison)","C":"Comparing gross profit margin with the number of factory employees","D":"Comparing current ratio with the company's total share price"},"correctOption":"B","correctAnswer":"Comparing a business's ratios over several consecutive years (trend analysis) and comparing them with competitors in the same industry (inter-firm comparison)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because tracking trends over time reveals whether performance is improving or deteriorating, while benchmarking against same-industry rivals shows competitive standing.","distractor_reasons":{"A":"Incorrect because valid inter-firm comparisons must compare businesses of similar size in the same industry.","B":"Correct selection.","C":"Incorrect because comparing a percentage margin to headcount is not a meaningful financial benchmark.","D":"Incorrect because liquidity ratios are benchmarked against standard norms (such as 1.5 : 1 to 2 : 1) and industry peers, not share prices."}}},{"id":"P1_U5_MCQ_603","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_603","question":"What is the correct formula for calculating 'Gross profit margin (%)'?","options":{"A":"(Profit / Revenue) × 100","B":"(Cost of sales / Revenue) × 100","C":"(Gross profit / Revenue) × 100","D":"(Gross profit / Capital employed) × 100"},"correctOption":"C","correctAnswer":"(Gross profit / Revenue) × 100","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because gross profit margin expresses gross profit as a percentage of total sales revenue.","distractor_reasons":{"A":"Incorrect because (Profit / Revenue) × 100 is the formula for profit margin.","B":"Incorrect because (Cost of sales / Revenue) × 100 measures direct costs as a share of sales.","C":"Correct selection.","D":"Incorrect because capital employed is the denominator in Return on Capital Employed (ROCE)."}}},{"id":"P1_U5_MCQ_604","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_604","question":"What does a business's 'gross profit margin' specifically measure?","options":{"A":"How quickly the business can convert its current assets into cash to pay short-term bills","B":"The percentage return generated on all long-term capital invested in the business","C":"The percentage of revenue left after paying all indirect overheads and corporation tax","D":"How much gross profit is earned on every $100 of sales revenue after covering direct cost of sales"},"correctOption":"D","correctAnswer":"How much gross profit is earned on every $100 of sales revenue after covering direct cost of sales","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because gross profit margin reflects pricing strength and direct production/purchasing cost efficiency before indirect overheads are considered.","distractor_reasons":{"A":"Incorrect because short-term bill-paying ability is measured by liquidity ratios (current and acid-test ratios).","B":"Incorrect because return on invested capital is measured by ROCE.","C":"Incorrect because profit after overheads is measured by profit margin.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_605","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_605","question":"What is the correct formula for calculating 'Profit margin (%)'?","options":{"A":"(Profit / Revenue) × 100","B":"(Gross profit / Revenue) × 100","C":"(Profit / Capital employed) × 100","D":"(Overhead expenses / Revenue) × 100"},"correctOption":"A","correctAnswer":"(Profit / Revenue) × 100","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because profit margin expresses final operating profit (after deducting both cost of sales and overhead expenses) as a percentage of sales revenue.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because (Gross profit / Revenue) × 100 calculates gross profit margin.","C":"Incorrect because (Profit / Capital employed) × 100 calculates Return on Capital Employed (ROCE).","D":"Incorrect because this measures overhead expenses as a proportion of sales."}}},{"id":"P1_U5_MCQ_606","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_606","question":"If a business's gross profit margin remains steady over two years while its profit margin falls significantly, what does this indicate?","options":{"A":"Direct raw material prices have doubled while indirect overheads fell","B":"Indirect overhead expenses (such as rent, marketing, or administrative salaries) have risen faster than sales revenue","C":"The business has taken on too many long-term non-current liabilities","D":"The business's current ratio has risen above 2 : 1"},"correctOption":"B","correctAnswer":"Indirect overhead expenses (such as rent, marketing, or administrative salaries) have risen faster than sales revenue","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the gap between gross profit margin and profit margin represents indirect overhead expenses as a percentage of revenue.","distractor_reasons":{"A":"Incorrect because higher raw material prices would have reduced gross profit margin.","B":"Correct selection.","C":"Incorrect because non-current liabilities affect ROCE rather than operating profit margin.","D":"Incorrect because liquidity ratios do not explain the gap between gross profit margin and profit margin."}}},{"id":"P1_U5_MCQ_607","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_607","question":"What is the correct formula for calculating 'Return on Capital Employed (ROCE) (%)'?","options":{"A":"(Gross profit / Revenue) × 100","B":"(Profit / Current assets) × 100","C":"(Profit / Capital employed) × 100","D":"(Capital employed / Profit) × 100"},"correctOption":"C","correctAnswer":"(Profit / Capital employed) × 100","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because ROCE measures the percentage profit generated relative to the total long-term capital invested in the business (Shareholders' equity + Non-current liabilities).","distractor_reasons":{"A":"Incorrect because this is the formula for gross profit margin.","B":"Incorrect because ROCE uses total long-term capital employed, not short-term current assets.","C":"Correct selection.","D":"Incorrect because this inverts the ROCE formula."}}},{"id":"P1_U5_MCQ_608","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_608","question":"Why is 'Return on Capital Employed (ROCE)' often regarded as the most comprehensive indicator of a business's overall profitability?","options":{"A":"Because it measures whether the business holds enough physical cash to pay next week's supplier bills","B":"Because it ignores all overhead expenses and taxes","C":"Because it measures only the direct mark-up on goods sold","D":"Because it compares profit earned against the total amount of capital invested, allowing comparison across businesses of different sizes and with alternative investments"},"correctOption":"D","correctAnswer":"Because it compares profit earned against the total amount of capital invested, allowing comparison across businesses of different sizes and with alternative investments","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because ROCE shows how efficiently management uses all funds invested by owners and long-term lenders to generate profit.","distractor_reasons":{"A":"Incorrect because short-term liquidity is measured by the current and acid-test ratios.","B":"Incorrect because operating profit in the numerator already deducts overhead expenses.","C":"Incorrect because direct trading mark-up is reflected in gross profit margin.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_609","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_609","question":"How do shareholders and managers judge whether a calculated 'ROCE' percentage is satisfactory?","options":{"A":"By comparing it with the business's ROCE in previous years, the ROCE of competitors in the same industry, and prevailing bank deposit or borrowing interest rates","B":"By checking whether it is lower than the interest rate paid on a risk-free bank savings account","C":"By checking whether it is identical to the business's current ratio","D":"By ensuring it is always below 1%"},"correctOption":"A","correctAnswer":"By comparing it with the business's ROCE in previous years, the ROCE of competitors in the same industry, and prevailing bank deposit or borrowing interest rates","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a satisfactory ROCE should rise over time, compare well with industry rivals, and comfortably exceed risk-free savings rates and loan interest costs.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because earning less than a safe bank deposit indicates poor capital efficiency.","C":"Incorrect because ROCE is a percentage return on capital, whereas the current ratio is a liquidity proportion.","D":"Incorrect because an ROCE below 1% is extremely weak."}}},{"id":"P1_U5_MCQ_610","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_610","question":"What is meant by 'liquidity' in financial analysis?","options":{"A":"The total amount of profit retained in the business over ten years","B":"The ability of a business to pay its short-term debts and day-to-day bills as they fall due using cash and assets that can quickly be converted into cash","C":"The total value of freehold land and factories owned by a company","D":"The percentage of sales revenue left after deducting cost of sales"},"correctOption":"B","correctAnswer":"The ability of a business to pay its short-term debts and day-to-day bills as they fall due using cash and assets that can quickly be converted into cash","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because liquidity measures short-term solvency—having sufficient accessible cash or near-cash current assets to meet immediate liabilities.","distractor_reasons":{"A":"Incorrect because retained profit is an equity reserve, not liquidity.","B":"Correct selection.","C":"Incorrect because freehold land and factories are illiquid non-current assets.","D":"Incorrect because revenue minus cost of sales percentage is gross profit margin."}}},{"id":"P1_U5_MCQ_611","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_611","question":"What is the correct formula for calculating the 'Current ratio'?","options":{"A":"Current liabilities / Current assets","B":"(Current assets - Inventories) / Current liabilities","C":"Current assets / Current liabilities","D":"Total assets / Total liabilities"},"correctOption":"C","correctAnswer":"Current assets / Current liabilities","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the current ratio compares all current assets against all current liabilities (usually expressed as X : 1).","distractor_reasons":{"A":"Incorrect because this inverts the current ratio formula.","B":"Incorrect because subtracting inventories gives the acid-test (quick) ratio.","C":"Correct selection.","D":"Incorrect because total assets and total liabilities include non-current items excluded from short-term liquidity ratios."}}},{"id":"P1_U5_MCQ_612","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_612","question":"What does a 'current ratio' below 1 : 1 indicate about a business's financial position?","options":{"A":"The business is earning exceptionally high gross profit margins","B":"The business holds excessive idle cash in its bank current account","C":"The business has zero short-term debts","D":"The business's current liabilities exceed its current assets (negative working capital), creating a high risk of cash flow and bill-paying difficulties"},"correctOption":"D","correctAnswer":"The business's current liabilities exceed its current assets (negative working capital), creating a high risk of cash flow and bill-paying difficulties","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a current ratio under 1 : 1 means that even if all short-term assets were turned into cash, they would not cover debts due within 12 months.","distractor_reasons":{"A":"Incorrect because liquidity ratios do not measure gross profit margins.","B":"Incorrect because a ratio below 1 : 1 signals a shortage, not an excess, of current assets.","C":"Incorrect because zero current liabilities would make the denominator zero, not produce a ratio under 1 : 1.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_613","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_613","question":"Why might financial analysts criticize a business whose 'current ratio' is excessively high (for example, well above 2 : 1)?","options":{"A":"It suggests too much working capital is tied up unproductively in excessive inventories, slow-paying receivables, or low-interest cash instead of being invested to earn higher returns","B":"It proves the business is about to go bankrupt within a month","C":"It means the business has too many non-current liabilities","D":"It indicates that the business is making a trading loss"},"correctOption":"A","correctAnswer":"It suggests too much working capital is tied up unproductively in excessive inventories, slow-paying receivables, or low-interest cash instead of being invested to earn higher returns","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because holding far more current assets than needed to cover short-term bills creates an opportunity cost and reduces overall ROCE.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a high current ratio indicates ample short-term asset coverage, not imminent insolvency.","C":"Incorrect because non-current liabilities do not enter the current ratio.","D":"Incorrect because liquidity ratios do not measure trading profit or loss."}}},{"id":"P1_U5_MCQ_614","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_614","question":"What is the correct formula for calculating the 'Acid-test (quick) ratio'?","options":{"A":"Current assets / Current liabilities","B":"(Current assets - Inventories) / Current liabilities","C":"(Current assets - Trade receivables) / Current liabilities","D":"Cash / Non-current liabilities"},"correctOption":"B","correctAnswer":"(Current assets - Inventories) / Current liabilities","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the acid-test ratio strips out inventories from current assets to compare only the most liquid assets (cash and trade receivables) against current liabilities.","distractor_reasons":{"A":"Incorrect because including inventories gives the current ratio.","B":"Correct selection.","C":"Incorrect because trade receivables are liquid assets retained in the numerator, whereas inventories are subtracted.","D":"Incorrect because liquidity ratios use current liabilities, not non-current liabilities, as the denominator."}}},{"id":"P1_U5_MCQ_615","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_615","question":"Why are 'inventories' subtracted from current assets when calculating the 'acid-test ratio'?","options":{"A":"Because inventories are classified as non-current assets on the statement of financial position","B":"Because inventories are actually a current liability owed to suppliers","C":"Because inventories are the least liquid current asset and cannot always be quickly converted into cash without heavy discounting or risk of spoilage/obsolescence","D":"Because inventories are never insured against theft or fire"},"correctOption":"C","correctAnswer":"Because inventories are the least liquid current asset and cannot always be quickly converted into cash without heavy discounting or risk of spoilage/obsolescence","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because unsold stock must first find buyers before generating cash, making the acid-test ratio a stricter test of immediate liquidity.","distractor_reasons":{"A":"Incorrect because inventories are current assets, just the least liquid ones.","B":"Incorrect because inventories are assets owned by the business, not liabilities.","C":"Correct selection.","D":"Incorrect because businesses routinely insure their inventories."}}},{"id":"P1_U5_MCQ_616","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_616","question":"If a business has a healthy current ratio (around 2 : 1) but a very low acid-test ratio (well below 1 : 1), what does this reveal?","options":{"A":"The business holds almost all of its current assets in physical bank cash","B":"The business has zero trade payables or bank overdrafts","C":"The business's non-current assets are worth less than its current liabilities","D":"A large proportion of the business's current assets is tied up in unsold inventories, leaving insufficient liquid cash and receivables to pay immediate short-term debts"},"correctOption":"D","correctAnswer":"A large proportion of the business's current assets is tied up in unsold inventories, leaving insufficient liquid cash and receivables to pay immediate short-term debts","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the large drop between the current ratio and the acid-test ratio is entirely caused by high inventory levels.","distractor_reasons":{"A":"Incorrect because high bank cash would produce a high acid-test ratio as well.","B":"Incorrect because zero current liabilities would not yield a low acid-test ratio.","C":"Incorrect because neither ratio includes non-current assets.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_617","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_617","question":"Which group of ratios is of greatest primary interest to existing shareholders and potential equity investors?","options":{"A":"Profitability ratios, particularly Return on Capital Employed (ROCE) and Profit margin","B":"Liquidity ratios alone, ignoring all profit figures","C":"Supplier trade payables days alone","D":"Raw material wastage ratios alone"},"correctOption":"A","correctAnswer":"Profitability ratios, particularly Return on Capital Employed (ROCE) and Profit margin","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because shareholders invest for dividends and capital growth, which depend directly on strong profit margins and high returns on capital employed.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because liquidity ratios are the top concern of short-term creditors and banks rather than equity investors.","C":"Incorrect because trade payables days is an operational working capital metric.","D":"Incorrect because raw material wastage is a factory operations metric."}}},{"id":"P1_U5_MCQ_618","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_618","question":"Why do commercial banks and trade suppliers pay close attention to a business's 'liquidity ratios' (current ratio and acid-test ratio)?","options":{"A":"Because banks and suppliers earn a percentage of the business's gross profit instead of fixed payments","B":"To check whether the business holds enough liquid assets to pay invoices, loan interest, and principal repayments on time without defaulting","C":"To decide whether the business should launch a new advertising campaign","D":"To calculate how much corporation tax the business owes the government"},"correctOption":"B","correctAnswer":"To check whether the business holds enough liquid assets to pay invoices, loan interest, and principal repayments on time without defaulting","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because creditors face direct financial loss if a borrowing customer lacks short-term liquidity to honor debts as they fall due.","distractor_reasons":{"A":"Incorrect because creditors receive contractual debt repayments, not equity profit shares.","B":"Correct selection.","C":"Incorrect because marketing decisions belong to company managers.","D":"Incorrect because corporation tax is calculated from profit figures, not liquidity ratios."}}},{"id":"P1_U5_MCQ_619","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_619","question":"How do internal business managers use financial ratio analysis in decision-making?","options":{"A":"To set national interest rates across the economy","B":"To audit the tax returns of competing companies","C":"To monitor cost control, pricing effectiveness, capital efficiency, and working capital liquidity so corrective action can be taken early","D":"To eliminate the need for market research before launching products"},"correctOption":"C","correctAnswer":"To monitor cost control, pricing effectiveness, capital efficiency, and working capital liquidity so corrective action can be taken early","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because internal managers track profitability and liquidity ratios regularly to diagnose weaknesses and guide operational and strategic adjustments.","distractor_reasons":{"A":"Incorrect because central banks set national interest rates.","B":"Incorrect because government tax authorities conduct tax audits.","C":"Correct selection.","D":"Incorrect because financial ratios complement rather than replace market research."}}},{"id":"P1_U5_MCQ_620","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_620","question":"Why do government tax authorities examine a business's financial accounts?","options":{"A":"To decide whether to grant the business a commercial bank overdraft","B":"To negotiate annual pay increases on behalf of factory workers","C":"To set the retail prices of the business's products","D":"To verify declared profit figures and ensure the correct amount of corporation tax is assessed and collected"},"correctOption":"D","correctAnswer":"To verify declared profit figures and ensure the correct amount of corporation tax is assessed and collected","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because tax authorities rely on accurate income statements to calculate and verify business tax liabilities.","distractor_reasons":{"A":"Incorrect because commercial banks decide on overdraft facilities.","B":"Incorrect because trade unions negotiate worker wages.","C":"Incorrect because businesses set their own retail prices in free markets.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_621","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_621","question":"How can 'competitors' use the published annual accounts of a public limited company (plc)?","options":{"A":"To benchmark their own profit margins, sales growth, and efficiency against the rival firm and identify industry trends","B":"To legally force the rival firm to lower its selling prices","C":"To access the confidential personal bank details of the rival firm's customers","D":"To rewrite the rival firm's statement of financial position"},"correctOption":"A","correctAnswer":"To benchmark their own profit margins, sales growth, and efficiency against the rival firm and identify industry trends","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because public limited companies must publish their annual accounts, allowing rivals to compare margins, ROCE, and growth rates.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because competitors cannot legally dictate a rival's pricing.","C":"Incorrect because published accounts contain summarized corporate totals, not individual customer data.","D":"Incorrect because competitors have no authority over a rival's accounting records."}}},{"id":"P1_U5_MCQ_622","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_622","question":"Why is the 'historical nature' of financial accounts considered a limitation of ratio analysis?","options":{"A":"Because historical accounts omit all sales revenue and cost of sales","B":"Because ratios are calculated from past trading data and cannot guarantee future performance if market conditions, competition, or interest rates change","C":"Because historical accounts are never audited or checked for accuracy","D":"Because historical ratios can only be calculated for businesses that have closed down"},"correctOption":"B","correctAnswer":"Because ratios are calculated from past trading data and cannot guarantee future performance if market conditions, competition, or interest rates change","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because financial statements look backward at completed periods; rapid technological or economic shifts can quickly make past ratios outdated.","distractor_reasons":{"A":"Incorrect because revenue and cost of sales are core figures in historical accounts.","B":"Correct selection.","C":"Incorrect because public limited company accounts undergo independent external audits.","D":"Incorrect because ratios are routinely calculated for active, ongoing businesses."}}},{"id":"P1_U5_MCQ_623","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_623","question":"How does 'inflation' limit the reliability of comparing financial accounts over several years?","options":{"A":"Inflation automatically doubles a company's acid-test ratio every year","B":"Inflation forces accountants to omit all overhead expenses","C":"Rising general price levels inflate nominal revenue and asset values over time, making growth appear larger than real increases in sales volume or efficiency","D":"Inflation eliminates all non-current liabilities from the statement of financial position"},"correctOption":"C","correctAnswer":"Rising general price levels inflate nominal revenue and asset values over time, making growth appear larger than real increases in sales volume or efficiency","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because when prices rise across the economy, higher dollar sales or profit figures may simply reflect inflation rather than genuine real-terms growth.","distractor_reasons":{"A":"Incorrect because inflation does not automatically double liquidity ratios.","B":"Incorrect because all expenses remain recorded during inflation.","C":"Correct selection.","D":"Incorrect because debt obligations remain on the statement of financial position."}}},{"id":"P1_U5_MCQ_624","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_624","question":"Why can differences in 'accounting policies' between two companies distort inter-firm ratio comparisons?","options":{"A":"Because companies using different accounting policies are forbidden from calculating gross profit margin","B":"Because accounting policies determine a company's daily bank cash balance","C":"Because accounting policies only apply to sole traders","D":"Because different methods of valuing inventories or depreciating non-current assets alter reported profit and asset values even when underlying operations are similar"},"correctOption":"D","correctAnswer":"Because different methods of valuing inventories or depreciating non-current assets alter reported profit and asset values even when underlying operations are similar","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because variations in depreciation rates or inventory valuation rules directly affect profit and capital employed, making like-for-like comparison harder.","distractor_reasons":{"A":"Incorrect because all trading businesses can calculate gross profit margin.","B":"Incorrect because accounting valuation policies do not change physical bank cash.","C":"Incorrect because limited companies also apply accounting policies within accounting standards.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_625","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_625","question":"What is a fundamental limitation of financial ratios when managers are trying to solve declining business performance?","options":{"A":"Ratios identify financial symptoms (such as falling profit margins or weaker liquidity), but do not explain underlying operational causes or qualitative issues like poor product quality or low staff morale","B":"Ratios can only be calculated by external government officials","C":"Ratios ignore all figures from the statement of profit or loss","D":"Ratios are invalid whenever a business holds both current assets and non-current assets"},"correctOption":"A","correctAnswer":"Ratios identify financial symptoms (such as falling profit margins or weaker liquidity), but do not explain underlying operational causes or qualitative issues like poor product quality or low staff morale","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ratios act like a thermometer showing that a problem exists, requiring managers to investigate qualitative operational and market factors to find the root cause.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because internal managers, investors, and analysts routinely calculate ratios.","C":"Incorrect because profitability ratios rely directly on the statement of profit or loss.","D":"Incorrect because virtually all businesses hold both current and non-current assets."}}},{"id":"P1_U5_MCQ_626","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_626","question":"Besides starting up a business and funding day-to-day working capital, why do established businesses commonly require finance?","options":{"A":"To fund long-term business expansion, replace worn-out non-current assets, and invest in research and development","B":"To avoid having to prepare annual statements of profit or loss","C":"To eliminate the legal obligation to pay employee wages and salaries","D":"To convert all current liabilities into non-current assets"},"correctOption":"A","correctAnswer":"To fund long-term business expansion, replace worn-out non-current assets, and invest in research and development","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because established firms need capital to grow into new markets, take over rivals, upgrade aging machinery, and develop new products.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because raising finance does not exempt a business from statutory financial reporting.","C":"Incorrect because businesses must always pay contracted wages regardless of their financing.","D":"Incorrect because liabilities are debts owed and cannot simply be converted into assets."}}},{"id":"P1_U5_MCQ_627","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_627","question":"How does 'expansion capital' differ from 'start-up capital'?","options":{"A":"Expansion capital is always short-term, whereas start-up capital is always repaid within 30 days","B":"Expansion capital is raised by established businesses to grow operations or acquire other firms, whereas start-up capital is needed before a new business begins trading","C":"Expansion capital can only come from personal savings, whereas start-up capital can only come from stock market share issues","D":"Expansion capital is used only for paying electricity bills, whereas start-up capital is used only for paying dividends"},"correctOption":"B","correctAnswer":"Expansion capital is raised by established businesses to grow operations or acquire other firms, whereas start-up capital is needed before a new business begins trading","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because start-up capital funds initial set-up before trading begins, whereas expansion capital funds growth once a business is established.","distractor_reasons":{"A":"Incorrect because both start-up capital and expansion capital are typically long-term funding needs.","B":"Correct selection.","C":"Incorrect because start-ups cannot issue shares on a public stock exchange, while established firms can use retained profit, loans, or share issues.","D":"Incorrect because electricity bills are working capital expenses and new start-ups do not pay dividends before trading."}}},{"id":"P1_U5_MCQ_628","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_628","question":"Why is 'working capital' essential for bridging the time gap in a trading business?","options":{"A":"Because customers always pay months before raw materials are purchased","B":"Because commercial banks forbid businesses from holding cash in current accounts","C":"Because a business must pay for raw materials, wages, and running costs before it receives cash payments from customers who buy on credit","D":"Because working capital is used exclusively to buy freehold land and factories"},"correctOption":"C","correctAnswer":"Because a business must pay for raw materials, wages, and running costs before it receives cash payments from customers who buy on credit","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because cash outflows for production and stock occur before cash inflows arrive from sales, requiring working capital to keep operations running smoothly.","distractor_reasons":{"A":"Incorrect because in most industries, businesses spend cash on inputs before collecting cash from customers.","B":"Incorrect because businesses routinely hold cash in current accounts to pay daily bills.","C":"Correct selection.","D":"Incorrect because buying freehold land and factories is long-term capital expenditure, not working capital."}}},{"id":"P1_U5_MCQ_629","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_629","question":"Which pairing correctly distinguishes an example of 'capital expenditure' from an example of 'revenue expenditure'?","options":{"A":"Capital expenditure: paying monthly factory rent; Revenue expenditure: buying freehold factory land","B":"Capital expenditure: purchasing raw materials for resale; Revenue expenditure: purchasing commercial delivery vans","C":"Capital expenditure: paying weekly staff wages; Revenue expenditure: installing permanent automated machinery","D":"Capital expenditure: buying new production machinery; Revenue expenditure: paying routine machine maintenance and electricity"},"correctOption":"D","correctAnswer":"Capital expenditure: buying new production machinery; Revenue expenditure: paying routine machine maintenance and electricity","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because buying long-term machinery is capital expenditure (lasting over one year), whereas routine maintenance and electricity are day-to-day revenue expenditure.","distractor_reasons":{"A":"Incorrect because this reverses capital expenditure and revenue expenditure.","B":"Incorrect because raw materials are revenue expenditure and delivery vans are capital expenditure.","C":"Incorrect because weekly wages are revenue expenditure and automated machinery is capital expenditure.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_630","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_630","question":"Although 'retained profit' incurs no interest charges, what is the 'opportunity cost' of using retained profit to finance expansion?","options":{"A":"The forgone alternative uses of those funds, such as paying higher dividends to shareholders or earning interest in a deposit account","B":"The mandatory fixed interest payments owed to commercial banks every month","C":"The dilution of voting control caused by issuing new shares to outside investors","D":"The collateral seized by creditors if sales revenue falls"},"correctOption":"A","correctAnswer":"The forgone alternative uses of those funds, such as paying higher dividends to shareholders or earning interest in a deposit account","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because retaining profit inside the business means shareholders miss out on immediate dividend payouts or external interest returns.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because retained profit is internal equity and involves no bank interest payments.","C":"Incorrect because retaining profit does not involve issuing new voting shares.","D":"Incorrect because retained profit is an internal reserve and requires no collateral."}}},{"id":"P1_U5_MCQ_631","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_631","question":"How does 'sale and leaseback' of existing property raise finance, and what is its main long-term disadvantage?","options":{"A":"The business buys a rival's factory for cash, which eliminates all future rent expenses","B":"The business sells its freehold premises for an immediate lump sum of cash and rents them back, but loses asset ownership and faces ongoing future lease payments","C":"The business issues new ordinary shares to property investors, which doubles its non-current liabilities","D":"The business borrows a short-term overdraft, which must be repaid within seven days"},"correctOption":"B","correctAnswer":"The business sells its freehold premises for an immediate lump sum of cash and rents them back, but loses asset ownership and faces ongoing future lease payments","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because sale and leaseback unlocks capital tied up in owned buildings without disrupting operations, at the cost of permanent ownership and future rent outflows.","distractor_reasons":{"A":"Incorrect because sale and leaseback sells rather than buys property, creating new rent outflows.","B":"Correct selection.","C":"Incorrect because sale and leaseback involves selling physical property, not issuing shares.","D":"Incorrect because sale and leaseback is a long-term property arrangement, not a short-term bank overdraft."}}},{"id":"P1_U5_MCQ_632","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_632","question":"Why is 'reducing inventory levels' considered only a temporary, one-off way to generate internal cash rather than a continuous source of finance?","options":{"A":"Because inventory can only be sold once every five years by law","B":"Because reducing inventory increases warehouse rent and insurance costs","C":"Because once stock is reduced to the minimum buffer needed to meet customer orders, it cannot be reduced further without causing stockouts","D":"Because cash released from selling inventory must be handed over to the government"},"correctOption":"C","correctAnswer":"Because once stock is reduced to the minimum buffer needed to meet customer orders, it cannot be reduced further without causing stockouts","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because trimming excess stock releases cash once, after which the business must maintain sufficient inventory to continue trading normally.","distractor_reasons":{"A":"Incorrect because there is no law restricting how often inventory is sold.","B":"Incorrect because holding less inventory reduces rather than increases storage and insurance costs.","C":"Correct selection.","D":"Incorrect because cash freed from working capital stays within the business."}}},{"id":"P1_U5_MCQ_633","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_633","question":"What is a major limitation of relying on 'owners' savings' when an unincorporated business wants to fund rapid, large-scale expansion?","options":{"A":"Owners' savings incur higher interest rates than commercial bank overdrafts","B":"Using personal savings forces the business to become a public limited company","C":"Personal savings must be repaid to outside investors within 12 months","D":"The personal wealth of sole traders or partners is usually limited and may be insufficient to finance major capital projects"},"correctOption":"D","correctAnswer":"The personal wealth of sole traders or partners is usually limited and may be insufficient to finance major capital projects","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because while personal savings are quick and interest-free, individual owners rarely possess enough personal funds for large-scale growth.","distractor_reasons":{"A":"Incorrect because personal savings are an internal source with no interest charges.","B":"Incorrect because using personal savings does not change a business's legal structure.","C":"Incorrect because owners' capital involves no repayment obligation to outside lenders.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_634","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_634","question":"How does raising finance through 'issue of shares' differ between a private limited company (Ltd) and a public limited company (plc)?","options":{"A":"A plc can advertise and sell shares to the general public on a stock exchange to raise huge sums, whereas an Ltd can only sell shares privately with existing shareholders' agreement","B":"An Ltd can sell shares to the general public on a stock exchange, whereas a plc cannot issue any shares","C":"Shares issued by a plc must be repaid in cash after five years, whereas Ltd shares are permanent","D":"Only an Ltd has limited liability, whereas a plc has unlimited liability"},"correctOption":"A","correctAnswer":"A plc can advertise and sell shares to the general public on a stock exchange to raise huge sums, whereas an Ltd can only sell shares privately with existing shareholders' agreement","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because public limited companies have access to public stock markets for large capital issues, whereas private limited companies are restricted to private share placements.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because this reverses the legal rules for Ltds and plcs.","C":"Incorrect because ordinary shares in both Ltds and plcs are permanent capital.","D":"Incorrect because shareholders in both Ltds and plcs enjoy limited liability."}}},{"id":"P1_U5_MCQ_635","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_635","question":"Why do 'ordinary shares' carry higher risk for investors than 'debentures', yet remain attractive to equity investors?","options":{"A":"Ordinary shareholders never receive any dividends even when the company earns record profits","B":"Ordinary dividends are not guaranteed and shareholders are paid last if the company fails, but they gain voting rights and potentially unlimited dividend and share-price growth","C":"Ordinary shareholders are personally liable for all company debts beyond their investment","D":"Debenture holders control the board of directors through majority voting rights"},"correctOption":"B","correctAnswer":"Ordinary dividends are not guaranteed and shareholders are paid last if the company fails, but they gain voting rights and potentially unlimited dividend and share-price growth","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because ordinary shareholders bear residual business risk (variable dividends and last claim in liquidation) in exchange for voting control and capital appreciation.","distractor_reasons":{"A":"Incorrect because ordinary shareholders receive dividends when profits and board decisions allow.","B":"Correct selection.","C":"Incorrect because limited company shareholders have limited liability.","D":"Incorrect because debenture holders are lenders with no voting rights."}}},{"id":"P1_U5_MCQ_636","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_636","question":"What is the role of 'collateral' (security) when a business applies for a large bank loan?","options":{"A":"It is the non-repayable grant given by the bank to help the business start up","B":"It is the annual dividend paid by the borrower to the bank's shareholders","C":"It is a valuable asset (such as property or equipment) pledged by the borrower that the bank can seize and sell if the loan is not repaid","D":"It is the short-term trade credit offered by raw-material suppliers"},"correctOption":"C","correctAnswer":"It is a valuable asset (such as property or equipment) pledged by the borrower that the bank can seize and sell if the loan is not repaid","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because collateral reduces the bank's lending risk by providing an asset to recover the unpaid debt in case of borrower default.","distractor_reasons":{"A":"Incorrect because banks provide repayable loans rather than non-repayable grants.","B":"Incorrect because borrowers pay loan interest, not dividends, to banks.","C":"Correct selection.","D":"Incorrect because trade credit is provided by commercial suppliers, not lending banks."}}},{"id":"P1_U5_MCQ_637","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_637","question":"What is a 'commercial mortgage'?","options":{"A":"A short-term facility allowing a business to overdraw its current account for a few days","B":"An internal source of finance generated by selling unsold inventory","C":"A non-repayable government subsidy for hiring apprentices","D":"A very long-term loan (often 15 to 25 years) specifically used to buy land or buildings, with the property itself acting as security"},"correctOption":"D","correctAnswer":"A very long-term loan (often 15 to 25 years) specifically used to buy land or buildings, with the property itself acting as security","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a mortgage is a long-term secured loan tied directly to purchasing real estate/property.","distractor_reasons":{"A":"Incorrect because overdrawing a current account is a bank overdraft.","B":"Incorrect because a mortgage is external long-term debt.","C":"Incorrect because a mortgage must be repaid with interest.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_638","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_638","question":"Why might a large public limited company choose to issue 'debentures' rather than new 'ordinary shares' to raise long-term capital?","options":{"A":"Issuing debentures raises long-term funds without diluting existing shareholders' voting control, and interest costs are fixed and predictable","B":"Debentures never have to be repaid at maturity","C":"Debentures require zero interest payments even when the company is highly profitable","D":"Debentures can be issued by sole traders and partnerships"},"correctOption":"A","correctAnswer":"Issuing debentures raises long-term funds without diluting existing shareholders' voting control, and interest costs are fixed and predictable","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because debenture holders are creditors without voting rights, allowing existing shareholders to retain full control while raising long-term debt.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because debentures have a fixed maturity date when the principal must be repaid.","C":"Incorrect because debentures carry contractual fixed interest that must be paid regardless of profit.","D":"Incorrect because only limited companies can issue debentures."}}},{"id":"P1_U5_MCQ_639","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_639","question":"How does 'debt factoring' differ from using a 'bank overdraft'?","options":{"A":"Debt factoring is a long-term mortgage, whereas a bank overdraft is internal retained profit","B":"Debt factoring releases cash from existing unpaid customer invoices sold to a specialist firm, whereas a bank overdraft borrows additional money from a bank up to an agreed limit","C":"Debt factoring increases non-current liabilities, whereas a bank overdraft increases share capital","D":"Debt factoring is free of any fees, whereas a bank overdraft charges dividends"},"correctOption":"B","correctAnswer":"Debt factoring releases cash from existing unpaid customer invoices sold to a specialist firm, whereas a bank overdraft borrows additional money from a bank up to an agreed limit","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because debt factoring monetizes existing trade receivables at a discount, whereas an overdraft is short-term bank credit on a current account.","distractor_reasons":{"A":"Incorrect because both are short-term external working capital solutions.","B":"Correct selection.","C":"Incorrect because neither increases non-current liabilities or share capital.","D":"Incorrect because factors charge a discount/service fee and overdrafts charge interest."}}},{"id":"P1_U5_MCQ_640","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_640","question":"What is a common limitation or restriction attached to 'government grants and subsidies'?","options":{"A":"They carry higher interest rates than commercial credit cards","B":"They force the recipient business to shut down after two years","C":"They often come with strict conditions (such as locating in a high-unemployment area or matching the grant with private funds) and lengthy application processes","D":"They require handing over 100% of company voting shares to the government"},"correctOption":"C","correctAnswer":"They often come with strict conditions (such as locating in a high-unemployment area or matching the grant with private funds) and lengthy application processes","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because grants are conditional public funds; failure to meet agreed criteria can require repaying the grant, and approval can be slow and competitive.","distractor_reasons":{"A":"Incorrect because grants are non-repayable subsidies without interest.","B":"Incorrect because grants aim to support long-term business survival and regional growth.","C":"Correct selection.","D":"Incorrect because grants do not transfer private business ownership to the state."}}},{"id":"P1_U5_MCQ_641","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_641","question":"Why do 'microfinance' loans often carry higher percentage interest rates than large corporate bank loans?","options":{"A":"Because microfinance institutions are owned by stock-market speculators who ban small repayments","B":"Because microfinance loans last for 40 years without any instalments","C":"Because microfinance borrowers receive free equity shares with every loan","D":"Because processing, monitoring, and collecting many tiny, unsecured loans involves high administrative costs relative to the small loan amount"},"correctOption":"D","correctAnswer":"Because processing, monitoring, and collecting many tiny, unsecured loans involves high administrative costs relative to the small loan amount","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because lending very small sums without traditional collateral requires intensive field administration per dollar lent.","distractor_reasons":{"A":"Incorrect because microfinance typically involves frequent small repayments tailored to micro-entrepreneurs.","B":"Incorrect because microfinance loans are generally short-term.","C":"Incorrect because microfinance provides small loans, not share issues.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_642","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_642","question":"What is the key difference between 'reward-based crowdfunding' and 'equity-based crowdfunding'?","options":{"A":"Reward-based backers receive a product, perk, or early access in return for pledges, whereas equity-based backers receive shares and a stake in future profits","B":"Reward-based crowdfunding is only for plcs, whereas equity-based crowdfunding is only for sole traders","C":"Reward-based crowdfunding requires paying monthly bank interest, whereas equity-based crowdfunding is a government grant","D":"Reward-based crowdfunding gives backers voting seats on the board, whereas equity-based crowdfunding gives backers free t-shirts"},"correctOption":"A","correctAnswer":"Reward-based backers receive a product, perk, or early access in return for pledges, whereas equity-based backers receive shares and a stake in future profits","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because reward crowdfunding pre-sells perks or products without diluting ownership, whereas equity crowdfunding sells small shareholdings to online investors.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because sole traders cannot issue equity shares.","C":"Incorrect because neither form involves commercial bank interest or government grants.","D":"Incorrect because this reverses the rewards and ownership rights of the two models."}}},{"id":"P1_U5_MCQ_643","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_643","question":"What is a major risk for an entrepreneur who uses a public 'crowdfunding' website to raise start-up capital for a new invention?","options":{"A":"The entrepreneur must offer freehold land as collateral to every online backer","B":"Publishing the product idea online exposes it to competitors who may copy the concept before it is patented or launched, and if the funding target is missed, pledges may be returned","C":"Crowdfunding platforms automatically take 90% of the company's annual sales revenue forever","D":"Crowdfunding is legally banned for all consumer products"},"correctOption":"B","correctAnswer":"Publishing the product idea online exposes it to competitors who may copy the concept before it is patented or launched, and if the funding target is missed, pledges may be returned","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because public online pitches reveal product designs early, risking imitation, and 'all-or-nothing' platforms return funds if the goal is not reached.","distractor_reasons":{"A":"Incorrect because crowdfunding does not require property collateral.","B":"Correct selection.","C":"Incorrect because platforms charge a modest percentage fee on funds raised, not 90% of ongoing revenue.","D":"Incorrect because consumer products are the most common category on crowdfunding sites."}}},{"id":"P1_U5_MCQ_644","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_644","question":"Why can a 'bank overdraft' be more cost-effective than a 'bank loan' for covering brief, fluctuating cash shortages?","options":{"A":"Because an overdraft never charges any interest regardless of how long it is used","B":"Because an overdraft converts into non-repayable retained profit after six months","C":"Because interest is paid only on the exact amount overdrawn and only for the specific days the account is in deficit, rather than on a full fixed lump sum","D":"Because an overdraft always has a lower annual interest rate than a long-term mortgage"},"correctOption":"C","correctAnswer":"Because interest is paid only on the exact amount overdrawn and only for the specific days the account is in deficit, rather than on a full fixed lump sum","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because overdraft interest is calculated daily on the actual negative balance, avoiding paying interest on idle borrowed cash.","distractor_reasons":{"A":"Incorrect because overdrafts charge interest whenever the account is overdrawn.","B":"Incorrect because an overdraft remains a repayable short-term liability.","C":"Correct selection.","D":"Incorrect because overdraft annual interest rates are typically higher than secured long-term loans."}}},{"id":"P1_U5_MCQ_645","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_645","question":"Why do suppliers offer 'trade credit' to business customers, and what happens if a buyer abuses these terms by repeatedly paying late?","options":{"A":"Suppliers offer credit to win repeat orders, but late payment damages supplier goodwill and may cause the supplier to refuse future credit or demand cash on delivery","B":"Suppliers offer credit because they are legally forbidden from accepting immediate cash","C":"Late payment forces the supplier to issue free shares to the buyer","D":"Suppliers offer credit so they can double the buyer's corporation tax bill"},"correctOption":"A","correctAnswer":"Suppliers offer credit to win repeat orders, but late payment damages supplier goodwill and may cause the supplier to refuse future credit or demand cash on delivery","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because trade credit is a competitive selling tool for suppliers, but relying on delayed payment harms trust and risks supply disruption.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because suppliers prefer cash on delivery when possible and extend credit to attract B2B buyers.","C":"Incorrect because trade credit is a commercial debt arrangement, not a share transaction.","D":"Incorrect because suppliers have no control over a buyer's tax liabilities."}}},{"id":"P1_U5_MCQ_646","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_646","question":"Why is 'leasing' particularly suitable for acquiring high-technology equipment such as computers or medical scanners?","options":{"A":"Because leasing makes the business the permanent owner on Day 1","B":"Because the business avoids a large upfront cash outlay and can upgrade to newer models at the end of the lease without being stuck with obsolete equipment","C":"Because leasing is an internal source of finance that requires zero monthly payments","D":"Because leased equipment appears as share capital on the statement of financial position"},"correctOption":"B","correctAnswer":"Because the business avoids a large upfront cash outlay and can upgrade to newer models at the end of the lease without being stuck with obsolete equipment","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because leasing transfers obsolescence risk and maintenance responsibilities to the leasing company while preserving working capital.","distractor_reasons":{"A":"Incorrect because the leasing company retains legal ownership throughout and after the lease.","B":"Correct selection.","C":"Incorrect because leasing is external finance requiring regular rental payments.","D":"Incorrect because leased assets are rented, not share capital."}}},{"id":"P1_U5_MCQ_647","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_647","question":"What is a common disadvantage shared by both 'leasing' and 'hire purchase' compared with buying an asset outright for cash?","options":{"A":"Neither option allows the business to use the asset until the final year","B":"Both options immediately dilute the voting control of existing shareholders","C":"The total cumulative amount paid over the contract period is higher than the outright cash purchase price due to finance/interest charges","D":"Both options require listing the business on a public stock exchange"},"correctOption":"C","correctAnswer":"The total cumulative amount paid over the contract period is higher than the outright cash purchase price due to finance/interest charges","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because spreading payments over time incurs interest and administrative margins charged by the finance or leasing company.","distractor_reasons":{"A":"Incorrect because the business gets immediate operational use of the asset from the start of the agreement.","B":"Incorrect because neither leasing nor hire purchase involves issuing equity shares.","C":"Correct selection.","D":"Incorrect because businesses of any legal structure can use leasing or hire purchase."}}},{"id":"P1_U5_MCQ_648","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_648","question":"According to the principle of matching the 'time period' of finance to the purpose, how should a business finance a new factory building expected to last 20 years?","options":{"A":"Using a 30-day supplier trade credit facility","B":"Using a short-term bank overdraft repayable on demand","C":"Using microfinance loans due within three months","D":"Using long-term finance such as retained profit, a share issue, debentures, or a long-term commercial mortgage"},"correctOption":"D","correctAnswer":"Using long-term finance such as retained profit, a share issue, debentures, or a long-term commercial mortgage","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because long-term capital investments take many years to generate returns and should be matched with long-term funding sources to avoid liquidity crises.","distractor_reasons":{"A":"Incorrect because 30-day trade credit is for short-term stock purchases.","B":"Incorrect because an overdraft can be recalled at short notice before the factory pays for itself.","C":"Incorrect because microfinance provides tiny short-term loans unsuitable for factory construction.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_649","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_649","question":"How does a business's 'legal structure' restrict its choice of sources of finance?","options":{"A":"Sole traders and partnerships cannot raise capital by issuing shares or debentures, whereas limited companies can","B":"Public limited companies are legally forbidden from using retained profit or bank loans","C":"Sole traders are legally prohibited from using their own personal savings","D":"Private limited companies can sell shares freely to the public on a stock exchange, whereas plcs cannot"},"correctOption":"A","correctAnswer":"Sole traders and partnerships cannot raise capital by issuing shares or debentures, whereas limited companies can","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because only incorporated limited companies have share capital and can issue shares or corporate debentures.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because public limited companies frequently use retained profit and bank loans.","C":"Incorrect because sole traders commonly rely on personal savings.","D":"Incorrect because only plcs can float shares on a public stock exchange."}}},{"id":"P1_U5_MCQ_650","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_650","question":"Why does the 'size of a business' influence its ability to access external sources of finance?","options":{"A":"Small businesses always pay lower interest rates than large multinational corporations","B":"Large established businesses have greater asset collateral, proven profit track records, and access to capital markets, making lenders view them as lower risk","C":"Large businesses are legally barred from applying for commercial bank loans","D":"Small businesses have unlimited access to public stock market share issues"},"correctOption":"B","correctAnswer":"Large established businesses have greater asset collateral, proven profit track records, and access to capital markets, making lenders view them as lower risk","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because larger firms offer stronger collateral and lower default risk, giving them broader finance options at lower interest rates.","distractor_reasons":{"A":"Incorrect because small businesses are riskier to lenders and generally face higher interest rates.","B":"Correct selection.","C":"Incorrect because large businesses regularly borrow from commercial banks.","D":"Incorrect because small businesses are rarely plcs and cannot afford stock exchange listing costs."}}},{"id":"P1_U5_MCQ_651","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_651","question":"Why is 'cash' described as the most liquid asset a business holds?","options":{"A":"Because cash earns the highest rate of profit of any asset","B":"Because cash never changes value during periods of inflation","C":"Because cash is already in spendable money form and can be used immediately to pay wages, suppliers, and bills without needing to be sold or converted","D":"Because cash is classified as a non-current asset on the statement of financial position"},"correctOption":"C","correctAnswer":"Because cash is already in spendable money form and can be used immediately to pay wages, suppliers, and bills without needing to be sold or converted","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because liquidity measures how quickly an asset can be used to settle obligations, and cash is immediately spendable.","distractor_reasons":{"A":"Incorrect because idle cash earns little or no return compared with productive assets.","B":"Incorrect because inflation reduces the purchasing power of cash.","C":"Correct selection.","D":"Incorrect because cash is a current asset."}}},{"id":"P1_U5_MCQ_652","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_652","question":"What happens if a business runs out of cash and cannot arrange an overdraft or emergency funds to pay its immediate debts?","options":{"A":"It automatically converts its trade payables into retained profit","B":"It is exempt from paying suppliers until the next financial year","C":"It becomes a public limited company on the stock exchange","D":"It becomes insolvent and may be forced into liquidation by unpaid creditors, even if it has profitable orders"},"correctOption":"D","correctAnswer":"It becomes insolvent and may be forced into liquidation by unpaid creditors, even if it has profitable orders","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because businesses pay employees, suppliers, and banks in cash; inability to pay debts as they fall due causes insolvency.","distractor_reasons":{"A":"Incorrect because supplier debts remain legal liabilities until settled.","B":"Incorrect because creditors can demand payment on agreed due dates and take legal action.","C":"Incorrect because insolvency leads to closure or restructuring, not a stock exchange listing.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_653","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_653","question":"Which group contains ONLY 'financing cash inflows' (rather than day-to-day trading cash inflows) on a cash flow forecast?","options":{"A":"Receipt of a new bank loan, cash from issuing new shares, and owners' capital injections","B":"Cash sales at the till and collections from credit customers","C":"Payments to raw-material suppliers and monthly staff wages","D":"Retained profit and annual depreciation charges"},"correctOption":"A","correctAnswer":"Receipt of a new bank loan, cash from issuing new shares, and owners' capital injections","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because bank loans, share issues, and owner capital injections bring external or owner funding into the bank account rather than coming from product sales.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cash sales and collections from trade receivables are operating trading inflows.","C":"Incorrect because payments to suppliers and wages are operating cash outflows.","D":"Incorrect because retained profit and depreciation are non-cash accounting figures."}}},{"id":"P1_U5_MCQ_654","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_654","question":"Which item represents a 'capital expenditure cash outflow' on a cash flow forecast?","options":{"A":"Paying monthly electricity and water bills for the office","B":"Paying cash to purchase new factory machinery or delivery vehicles","C":"Paying weekly wages to warehouse staff","D":"Receiving payment from a customer who bought goods on credit"},"correctOption":"B","correctAnswer":"Paying cash to purchase new factory machinery or delivery vehicles","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because buying long-term non-current assets for cash creates an immediate capital cash outflow on the cash flow forecast.","distractor_reasons":{"A":"Incorrect because utility bills are routine revenue expenditure outflows.","B":"Correct selection.","C":"Incorrect because weekly wages are routine revenue expenditure outflows.","D":"Incorrect because receiving customer payments is a cash inflow."}}},{"id":"P1_U5_MCQ_655","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_655","question":"When a business purchases raw materials on 30-day trade credit in March and pays the supplier in April, how is this recorded on the cash flow forecast?","options":{"A":"As a cash outflow in March when the raw materials are delivered","B":"As a cash inflow in March and a cash outflow in April","C":"As zero cash outflow in March, and as a cash outflow in April when the payment actually leaves the bank account","D":"It is omitted from the cash flow forecast completely because it was bought on credit"},"correctOption":"C","correctAnswer":"As zero cash outflow in March, and as a cash outflow in April when the payment actually leaves the bank account","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a cash flow forecast records money strictly in the month cash actually moves out of or into the bank.","distractor_reasons":{"A":"Incorrect because no cash leaves the bank in March when buying on 30-day credit.","B":"Incorrect because buying materials never generates a cash inflow.","C":"Correct selection.","D":"Incorrect because credit purchases still result in a cash outflow when paid in April."}}},{"id":"P1_U5_MCQ_656","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_656","question":"Why is 'retained profit' NOT entered as a cash inflow line on a monthly cash flow forecast?","options":{"A":"Because retained profit is a current liability owed to commercial banks","B":"Because retained profit is illegal for limited companies to calculate","C":"Because retained profit is always paid out to shareholders in cash","D":"Because retained profit is an accounting profit figure already reflected through actual cash sales inflows minus cash cost outflows"},"correctOption":"D","correctAnswer":"Because retained profit is an accounting profit figure already reflected through actual cash sales inflows minus cash cost outflows","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because cash flow forecasts track actual cash receipts and payments directly; including retained profit separately would double-count cash already captured via sales and expenses.","distractor_reasons":{"A":"Incorrect because retained profit is owners' equity, not a bank liability.","B":"Incorrect because retained profit is a standard line on a company's statement of profit or loss.","C":"Incorrect because dividends are paid out to shareholders, whereas retained profit is kept in the business.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_657","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_657","question":"What does a 'negative net cash flow' in a single month indicate?","options":{"A":"Cash outflows exceeded cash inflows during that month, causing the cash balance to fall (or an overdraft to grow)","B":"The business has definitely made an annual net loss on its statement of profit or loss","C":"The business's closing cash balance must automatically be negative","D":"The business had zero sales revenue during that month"},"correctOption":"A","correctAnswer":"Cash outflows exceeded cash inflows during that month, causing the cash balance to fall (or an overdraft to grow)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because negative net cash flow means more cash left the business than entered during that month, reducing the opening cash balance.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a single month's negative net cash flow could simply reflect buying equipment or seasonal stock while still being profitable overall.","C":"Incorrect because if the opening cash balance was larger than the monthly deficit, the closing balance can still remain positive.","D":"Incorrect because a business can have substantial sales revenue (especially on credit) and still have outflows exceed inflows in a given month."}}},{"id":"P1_U5_MCQ_658","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_658","question":"If a business starts a month with an overdrawn (negative) opening cash balance and experiences a negative net cash flow during that month, what happens to its closing cash balance?","options":{"A":"The closing cash balance becomes positive","B":"The closing cash balance becomes even more negative (a larger bank overdraft)","C":"The closing cash balance resets to zero","D":"The closing cash balance equals total cash inflows"},"correctOption":"B","correctAnswer":"The closing cash balance becomes even more negative (a larger bank overdraft)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Closing balance = Opening balance + Net cash flow; adding a negative net cash flow to an already negative opening balance deepens the overdraft.","distractor_reasons":{"A":"Incorrect because a negative net cash flow drains cash further rather than turning a deficit positive.","B":"Correct selection.","C":"Incorrect because bank overdraft balances carry forward continuously.","D":"Incorrect because closing balance accounts for opening balance, inflows, and outflows."}}},{"id":"P1_U5_MCQ_659","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_659","question":"How does including a 12-month cash flow forecast strengthen an entrepreneur's 'business plan'?","options":{"A":"It legally guarantees that customers will buy the forecast quantity of goods","B":"It eliminates the need to register the business with tax authorities","C":"It demonstrates financial foresight to banks and investors by identifying peak borrowing needs and proving when cash surpluses will repay finance","D":"It fixes interest rates on all commercial loans for ten years"},"correctOption":"C","correctAnswer":"It demonstrates financial foresight to banks and investors by identifying peak borrowing needs and proving when cash surpluses will repay finance","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because lenders and investors look for realistic cash flow projections to verify that the entrepreneur understands working capital timing and repayment capacity.","distractor_reasons":{"A":"Incorrect because forecasts are estimates and cannot force customers to buy.","B":"Incorrect because legal registration is mandatory regardless of business plans.","C":"Correct selection.","D":"Incorrect because interest rates are determined by lenders and financial markets."}}},{"id":"P1_U5_MCQ_660","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_660","question":"Why do 'seasonal businesses' (such as ski resorts, toy manufacturers, or agricultural farms) rely especially heavily on monthly cash flow forecasts?","options":{"A":"Because seasonal businesses are exempt from paying taxes during off-peak months","B":"Because seasonal businesses never have any fixed overhead costs","C":"Because seasonal businesses only sell goods for immediate cash","D":"Because they incur heavy cash outflows for stock and preparation months before peak seasonal sales inflows arrive, requiring planned overdraft facilities"},"correctOption":"D","correctAnswer":"Because they incur heavy cash outflows for stock and preparation months before peak seasonal sales inflows arrive, requiring planned overdraft facilities","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because seasonal mismatches between production outflows and peak sales receipts create predictable cash troughs that must be financed in advance.","distractor_reasons":{"A":"Incorrect because seasonal businesses pay taxes on their annual profits like any other firm.","B":"Incorrect because seasonal businesses still pay fixed rent, insurance, and core salaries year-round.","C":"Incorrect because seasonal manufacturers often sell on credit to retailers.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_661","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_661","question":"How does a cash flow forecast help managers set an appropriate 'bank overdraft limit'?","options":{"A":"By revealing the largest forecast negative closing cash balance during the year so the business can negotiate a sufficient overdraft facility before the deficit hits","B":"By calculating the exact gross profit margin on every product sold","C":"By eliminating all cash outflows during winter months","D":"By converting all current liabilities into ordinary share capital"},"correctOption":"A","correctAnswer":"By revealing the largest forecast negative closing cash balance during the year so the business can negotiate a sufficient overdraft facility before the deficit hits","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because knowing the maximum projected cash deficit allows management to arrange an adequate overdraft ceiling in advance rather than having payments bounce.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because gross profit margin is calculated from the statement of profit or loss.","C":"Incorrect because forecasts predict outflows rather than eliminating them.","D":"Incorrect because overdrafts are debt facilities, not share capital."}}},{"id":"P1_U5_MCQ_662","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_662","question":"Why do commercial banks react much more favorably when a business uses a cash flow forecast to request an overdraft *before* a deficit occurs, rather than exceeding its limit unannounced?","options":{"A":"Because banks are legally forbidden from charging interest on pre-arranged overdrafts","B":"Because presenting a forecast shows competent financial control and proves the deficit is temporary, whereas unarranged overdrafts signal poor management and incur penalty fees","C":"Because pre-arranged overdrafts never have to be repaid","D":"Because banks receive 50% of the borrower's retained profit"},"correctOption":"B","correctAnswer":"Because presenting a forecast shows competent financial control and proves the deficit is temporary, whereas unarranged overdrafts signal poor management and incur penalty fees","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because advance planning builds lender trust and secures lower agreed overdraft rates, whereas sudden cash emergencies risk refusal or high penalty charges.","distractor_reasons":{"A":"Incorrect because banks still charge interest on pre-arranged overdrafts, just at lower rates than unauthorized overdrafts.","B":"Correct selection.","C":"Incorrect because overdrafts remain repayable on demand.","D":"Incorrect because banks earn interest and fees, not equity profit shares."}}},{"id":"P1_U5_MCQ_663","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_663","question":"How can a cash flow forecast help managers decide *when* to buy expensive new equipment for cash?","options":{"A":"By showing which months have large accumulated cash surpluses capable of absorbing the capital outflow without pushing the bank balance into deficit","B":"By forcing equipment suppliers to reduce their prices by 50%","C":"By recording equipment purchases as sales revenue","D":"By eliminating depreciation expenses on the statement of profit or loss"},"correctOption":"A","correctAnswer":"By showing which months have large accumulated cash surpluses capable of absorbing the capital outflow without pushing the bank balance into deficit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because timing capital expenditure to coincide with peak cash balances prevents liquidity strain.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a forecast does not force suppliers to cut prices.","C":"Incorrect because buying equipment is an asset purchase and cash outflow, not revenue.","D":"Incorrect because non-current assets are still depreciated over their useful lives."}}},{"id":"P1_U5_MCQ_664","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_664","question":"Why do 'profit' and 'cash flow' differ when a business sells most of its goods on 60-day credit terms?","options":{"A":"Because credit sales are excluded from the statement of profit or loss","B":"Because credit sales increase revenue and profit immediately when goods are invoiced, whereas cash inflow is delayed for 60 days until customers pay","C":"Because credit sales are recorded as cash outflows on the cash flow forecast","D":"Because credit customers never pay for the goods they buy"},"correctOption":"B","correctAnswer":"Because credit sales increase revenue and profit immediately when goods are invoiced, whereas cash inflow is delayed for 60 days until customers pay","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because profit follows the accruals principle (recognizing revenue at sale), whereas cash flow records actual receipt of funds two months later.","distractor_reasons":{"A":"Incorrect because credit sales are included in revenue on the statement of profit or loss.","B":"Correct selection.","C":"Incorrect because customer payments are cash inflows once received.","D":"Incorrect because most credit customers pay within the agreed credit period (only rare bad debts go unpaid)."}}},{"id":"P1_U5_MCQ_665","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_665","question":"How does repaying the principal amount of a bank loan affect 'cash flow' versus 'profit'?","options":{"A":"Both the principal repayment and the interest reduce profit immediately","B":"Neither the principal repayment nor the interest appears on the cash flow forecast","C":"Repaying the loan principal creates a cash outflow that reduces cash, but only the interest charge reduces profit on the statement of profit or loss","D":"Repaying the loan principal increases gross profit"},"correctOption":"C","correctAnswer":"Repaying the loan principal creates a cash outflow that reduces cash, but only the interest charge reduces profit on the statement of profit or loss","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because repaying borrowed principal reduces cash and reduces the loan liability on the balance sheet without being a trading expense, whereas interest is an expense reducing profit.","distractor_reasons":{"A":"Incorrect because only the interest portion is an expense on the statement of profit or loss.","B":"Incorrect because both principal and interest payments involve cash leaving the bank and appear as cash outflows.","C":"Correct selection.","D":"Incorrect because loan repayments have no effect on gross profit."}}},{"id":"P1_U5_MCQ_666","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_666","question":"When a company issues new ordinary shares for cash, how does this transaction affect 'cash flow' and 'profit'?","options":{"A":"It increases both cash flow and gross profit by the share issue amount","B":"It reduces cash flow and increases overhead expenses","C":"It has no effect on either cash flow or the statement of financial position","D":"It creates a cash inflow that increases the cash balance, but it has zero effect on profit on the statement of profit or loss"},"correctOption":"D","correctAnswer":"It creates a cash inflow that increases the cash balance, but it has zero effect on profit on the statement of profit or loss","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because issuing shares brings financing cash into the business (increasing cash and share capital) rather than earning trading revenue.","distractor_reasons":{"A":"Incorrect because share proceeds are capital raised from owners, not sales revenue or gross profit.","B":"Incorrect because issuing shares brings cash into the business.","C":"Incorrect because it increases cash and share capital on the statement of financial position.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_667","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_667","question":"Why can rapid sales expansion without sufficient working capital (known as 'overtrading') cause a profitable business to run out of cash?","options":{"A":"Because expanding output requires immediate cash outflows for extra raw materials, stock, and wages before cash inflows arrive from new credit customers","B":"Because rapid sales growth automatically reduces gross profit margin to zero","C":"Because commercial banks cancel all overdrafts whenever sales increase","D":"Because rapid sales growth eliminates all trade receivables"},"correctOption":"A","correctAnswer":"Because expanding output requires immediate cash outflows for extra raw materials, stock, and wages before cash inflows arrive from new credit customers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because fulfilling surging orders absorbs large amounts of working capital upfront while cash remains tied up in higher inventories and trade receivables.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because higher sales volume can generate strong profit margins while still draining cash.","C":"Incorrect because banks do not automatically cancel overdrafts when sales rise.","D":"Incorrect because rapid credit sales increase rather than eliminate trade receivables."}}},{"id":"P1_U5_MCQ_668","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_668","question":"What is a potential drawback of relying on a 'bank overdraft' to fix a cash flow deficit?","options":{"A":"It forces the business to give up voting shares to the bank","B":"Interest rates are relatively high and variable, and the bank has the legal right to demand immediate repayment at short notice","C":"It takes several years to arrange and cannot be used for paying wages","D":"It permanently reduces the business's sales revenue"},"correctOption":"B","correctAnswer":"Interest rates are relatively high and variable, and the bank has the legal right to demand immediate repayment at short notice","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because overdrafts are short-term, recallable facilities with high daily interest rates if relied upon continuously.","distractor_reasons":{"A":"Incorrect because banks do not receive equity shares when granting an overdraft.","B":"Correct selection.","C":"Incorrect because overdrafts are quick to arrange and cover routine current account outflows like wages.","D":"Incorrect because an overdraft does not reduce sales revenue."}}},{"id":"P1_U5_MCQ_669","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_669","question":"What is a commercial risk of 'reducing the credit period' offered to customers (for example, from 60 days to 15 days) to speed up cash inflows?","options":{"A":"The business's non-current liabilities will double","B":"Suppliers will refuse to deliver raw materials","C":"Customers may switch to rival suppliers that still offer more generous 60-day credit terms, causing sales revenue to fall","D":"The business's gross profit margin will automatically drop to zero"},"correctOption":"C","correctAnswer":"Customers may switch to rival suppliers that still offer more generous 60-day credit terms, causing sales revenue to fall","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because trade credit is an important competitive factor in business-to-business sales; tightening credit terms too aggressively can drive buyers to competitors.","distractor_reasons":{"A":"Incorrect because tightening customer credit affects current assets, not non-current liabilities.","B":"Incorrect because customer credit terms do not dictate supplier willingness to sell.","C":"Correct selection.","D":"Incorrect because shortening credit terms does not reduce unit selling prices or raise direct costs."}}},{"id":"P1_U5_MCQ_670","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_670","question":"How does using 'debt factoring' to overcome a cash shortage affect a business's cash flow versus its profit?","options":{"A":"It delays cash inflows by three months and increases profit","B":"It reduces cash inflows and doubles retained profit","C":"It has no effect on either cash flow or profit","D":"It accelerates immediate cash inflows into the bank account, but reduces profit because the factor deducts a service fee/discount"},"correctOption":"D","correctAnswer":"It accelerates immediate cash inflows into the bank account, but reduces profit because the factor deducts a service fee/discount","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because debt factoring trades a small portion of profit margin (the factor's discount fee) for immediate cash liquidity.","distractor_reasons":{"A":"Incorrect because factoring accelerates rather than delays cash inflows, and reduces rather than increases profit.","B":"Incorrect because factoring increases immediate cash inflows and lowers profit.","C":"Incorrect because factoring directly boosts short-term cash while charging a fee expense.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_671","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_671","question":"How does choosing to 'lease' a new machine instead of buying it outright for cash help solve a forecast cash deficit?","options":{"A":"It replaces a single large capital cash outflow with smaller, predictable monthly rental outflows that can be paid from ongoing revenue","B":"It creates a large immediate cash inflow from the leasing company","C":"It eliminates all monthly cash outflows for the next five years","D":"It increases the value of freehold property on the statement of financial position"},"correctOption":"A","correctAnswer":"It replaces a single large capital cash outflow with smaller, predictable monthly rental outflows that can be paid from ongoing revenue","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because leasing spreads payments over time, protecting short-term working capital from a major upfront cash drain.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because leasing involves rental outflows, not cash inflows.","C":"Incorrect because monthly lease rentals are ongoing cash outflows.","D":"Incorrect because leased assets are not owned by the business."}}},{"id":"P1_U5_MCQ_672","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_672","question":"What is the long-term cash flow consequence of using 'sale and leaseback' of freehold buildings to resolve an immediate liquidity crisis?","options":{"A":"Future annual cash outflows decrease permanently because rent is eliminated","B":"While it generates a large immediate cash inflow today, it introduces regular ongoing rent outflows for many years into the future","C":"The business receives the buildings back free of charge after 12 months","D":"The business's current liabilities increase by the value of the buildings"},"correctOption":"B","correctAnswer":"While it generates a large immediate cash inflow today, it introduces regular ongoing rent outflows for many years into the future","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because sale and leaseback exchanges a one-off capital inflow now for recurring rental outflows over the lease term.","distractor_reasons":{"A":"Incorrect because the business now has to pay rent on buildings it previously owned outright.","B":"Correct selection.","C":"Incorrect because ownership transfers permanently to the buyer/lessor.","D":"Incorrect because selling property for cash increases current assets (cash) rather than current liabilities."}}},{"id":"P1_U5_MCQ_673","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_673","question":"How does 'reducing inventory levels' (such as adopting just-in-time ordering) improve a business's cash flow?","options":{"A":"It doubles the selling price of every finished product","B":"It delays payments from credit customers by 60 days","C":"It reduces immediate cash outflows spent on purchasing and storing excess stock while converting existing stock into cash sales","D":"It eliminates all employee wage outflows"},"correctOption":"C","correctAnswer":"It reduces immediate cash outflows spent on purchasing and storing excess stock while converting existing stock into cash sales","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because holding less inventory frees cash previously locked up in warehouse shelves and lowers storage/insurance cash outflows.","distractor_reasons":{"A":"Incorrect because inventory management does not double retail prices.","B":"Incorrect because delaying customer payments would worsen rather than improve cash flow.","C":"Correct selection.","D":"Incorrect because staff wages are still paid."}}},{"id":"P1_U5_MCQ_674","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_674","question":"Why is taking out a '5-year bank loan' generally unsuitable for solving a brief, one-month seasonal cash shortage?","options":{"A":"Because 5-year bank loans never provide any cash inflows","B":"Because banks prohibit businesses from using loan funds to pay suppliers","C":"Because 5-year bank loans dilute shareholders' voting rights","D":"Because the business would be locked into paying interest over five years for funds it only needed for a few weeks, whereas an overdraft is far more flexible"},"correctOption":"D","correctAnswer":"Because the business would be locked into paying interest over five years for funds it only needed for a few weeks, whereas an overdraft is far more flexible","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because matching finance duration to need avoids unnecessary multi-year interest costs on idle funds once seasonal cash inflows return.","distractor_reasons":{"A":"Incorrect because bank loans provide a lump-sum cash inflow upon approval.","B":"Incorrect because working capital loans can be used for operating payments.","C":"Incorrect because bank loans are debt and do not affect share ownership.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_675","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_675","question":"Why should managers regularly update a 'cash flow forecast' with actual figures throughout the year?","options":{"A":"Because comparing actual cash flows against forecast figures identifies variances early (such as slower customer payments or rising supplier costs) so revised projections and corrective actions remain accurate","B":"Because updating a forecast automatically increases annual profit","C":"Because tax authorities fine businesses that do not change their forecasts every week","D":"Because updating a forecast converts all trade receivables into cash immediately"},"correctOption":"A","correctAnswer":"Because comparing actual cash flows against forecast figures identifies variances early (such as slower customer payments or rising supplier costs) so revised projections and corrective actions remain accurate","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because variance analysis between forecast and actual cash flows keeps liquidity planning realistic in changing market conditions.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because updating a planning document does not by itself create profit.","C":"Incorrect because cash flow forecasts are internal management and lending tools, not weekly tax filings.","D":"Incorrect because updating numbers on paper does not force customers to pay faster."}}},{"id":"P1_U5_MCQ_676","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_676","question":"What is the key conceptual difference between 'revenue' and 'profit'?","options":{"A":"Revenue is calculated after deducting all costs, whereas profit is calculated before deducting any costs","B":"Revenue is the total income earned from sales before deducting any costs, whereas profit is the surplus remaining after all costs have been subtracted from revenue","C":"Revenue is recorded on the statement of financial position, whereas profit is recorded only on the cash flow forecast","D":"Revenue and profit are always identical for every business"},"correctOption":"B","correctAnswer":"Revenue is the total income earned from sales before deducting any costs, whereas profit is the surplus remaining after all costs have been subtracted from revenue","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because revenue is total sales turnover (Price × Quantity), whereas profit is net earnings after deducting cost of sales and overhead expenses.","distractor_reasons":{"A":"Incorrect because this reverses revenue and profit.","B":"Correct selection.","C":"Incorrect because both revenue and profit are reported on the statement of profit or loss.","D":"Incorrect because revenue and profit could only be equal if a business had zero costs."}}},{"id":"P1_U5_MCQ_677","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_677","question":"How does a 'charity or non-profit organization' treat a financial surplus compared with a 'public limited company'?","options":{"A":"A charity distributes its surplus as cash dividends to private shareholders, whereas a plc cannot pay dividends","B":"Charities are legally forbidden from earning more income than their expenses","C":"A charity reinvests any surplus entirely back into its charitable cause rather than paying dividends to private owners, whereas a plc distributes dividends to shareholders and retains profit for growth","D":"A plc donates 100% of its profit to the government, whereas a charity keeps 100% for directors"},"correctOption":"C","correctAnswer":"A charity reinvests any surplus entirely back into its charitable cause rather than paying dividends to private owners, whereas a plc distributes dividends to shareholders and retains profit for growth","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because non-profit organizations have no private shareholders to receive dividends and plough surpluses back into their mission.","distractor_reasons":{"A":"Incorrect because charities have no private shareholders and cannot pay dividends.","B":"Incorrect because charities aim to generate surpluses to fund their charitable activities.","C":"Correct selection.","D":"Incorrect because plcs pay corporation tax on profits and distribute dividends to shareholders."}}},{"id":"P1_U5_MCQ_678","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_678","question":"How does 'profit' serve as a measure of business success and efficiency?","options":{"A":"It measures the exact number of employees hired during the year","B":"It proves that the business holds zero debt on its statement of financial position","C":"It guarantees that the business will never face competition","D":"It shows whether the value of output sold exceeds the total cost of resources used to produce and market it, allowing comparisons over time and against rivals"},"correctOption":"D","correctAnswer":"It shows whether the value of output sold exceeds the total cost of resources used to produce and market it, allowing comparisons over time and against rivals","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because profit reflects how effectively management turns inputs into valued customer outputs while controlling costs.","distractor_reasons":{"A":"Incorrect because profit is a financial surplus, not a headcount figure.","B":"Incorrect because profitable businesses frequently use debt financing.","C":"Incorrect because high profits actually attract competitors into the market.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_679","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_679","question":"In a market economy, what role does 'high profit' in a particular industry play as an economic signal?","options":{"A":"It attracts new businesses and investment capital into that industry to supply goods that consumers strongly demand","B":"It forces existing businesses in that industry to shut down immediately","C":"It proves that consumers dislike the products being sold","D":"It eliminates all raw material costs for firms in that industry"},"correctOption":"A","correctAnswer":"It attracts new businesses and investment capital into that industry to supply goods that consumers strongly demand","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because high profitability signals strong consumer demand and attractive returns, encouraging entrepreneurs and capital to enter the market.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because persistent losses, not high profits, force firms to exit an industry.","C":"Incorrect because strong profits indicate customers value the product above its production cost.","D":"Incorrect because raw material costs still apply regardless of industry profitability."}}},{"id":"P1_U5_MCQ_680","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_680","question":"Why are proceeds from a 'new bank loan' or 'selling an old company van' excluded from 'sales revenue' on a statement of profit or loss?","options":{"A":"Because bank loans and van sales are illegal in limited companies","B":"Because sales revenue only records income earned from selling the business's regular goods or services, whereas loans are liabilities and van sales are asset disposals","C":"Because bank loans and van sales are recorded inside cost of sales","D":"Because sales revenue only includes cash received in banknotes"},"correctOption":"B","correctAnswer":"Because sales revenue only records income earned from selling the business's regular goods or services, whereas loans are liabilities and van sales are asset disposals","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because trading revenue reflects core operational sales, keeping financing and capital asset transactions separate.","distractor_reasons":{"A":"Incorrect because both are normal, legal business transactions.","B":"Correct selection.","C":"Incorrect because neither is a direct cost of producing goods sold.","D":"Incorrect because sales revenue includes both cash sales and credit sales."}}},{"id":"P1_U5_MCQ_681","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_681","question":"How do the components of 'cost of sales' typically differ between a 'retail shop' and a 'manufacturing factory'?","options":{"A":"A retail shop has zero cost of sales, whereas a factory includes head-office advertising in cost of sales","B":"A retail shop includes corporation tax in cost of sales, whereas a factory includes dividends","C":"A retail shop's cost of sales is the wholesale purchase cost of finished goods resold, whereas a factory's cost of sales includes direct raw materials and direct production wages","D":"Both retail shops and factories include only head-office administrative salaries in cost of sales"},"correctOption":"C","correctAnswer":"A retail shop's cost of sales is the wholesale purchase cost of finished goods resold, whereas a factory's cost of sales includes direct raw materials and direct production wages","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because retailers buy finished goods for resale, while manufacturers incur direct material and direct factory labor costs to make goods.","distractor_reasons":{"A":"Incorrect because retailers incur the wholesale cost of stock sold, and advertising is an overhead expense.","B":"Incorrect because corporation tax and dividends appear at the bottom of the income statement.","C":"Correct selection.","D":"Incorrect because administrative salaries are indirect overhead expenses."}}},{"id":"P1_U5_MCQ_682","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_682","question":"Why is 'closing inventory' subtracted when calculating 'cost of sales' (Opening inventory + Purchases - Closing inventory)?","options":{"A":"Because closing inventory was stolen during the year","B":"Because closing inventory is a non-current liability owed to banks","C":"Because closing inventory has already been sold to credit customers","D":"Because closing inventory remains unsold at year-end, so its cost must be excluded from the cost of goods actually sold during the current year"},"correctOption":"D","correctAnswer":"Because closing inventory remains unsold at year-end, so its cost must be excluded from the cost of goods actually sold during the current year","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the matching principle matches the revenue from goods sold during the period strictly against the cost of those same sold goods.","distractor_reasons":{"A":"Incorrect because closing inventory represents valid unsold stock still held by the business.","B":"Incorrect because closing inventory is a current asset.","C":"Incorrect because goods sold to customers are no longer in closing inventory.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_683","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_683","question":"How does 'closing inventory' at the end of Year 1 appear in Year 2's statement of profit or loss?","options":{"A":"It becomes the 'opening inventory' at the start of Year 2","B":"It is added to Year 2's sales revenue","C":"It is deducted as an overhead expense in Year 2","D":"It disappears completely from all Year 2 accounting records"},"correctOption":"A","correctAnswer":"It becomes the 'opening inventory' at the start of Year 2","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because unsold goods sitting in the warehouse at 11:59 PM on the last day of Year 1 are the exact same goods on hand at the start of Day 1 of Year 2.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because inventory is stock held, not sales revenue.","C":"Incorrect because opening inventory is part of cost of sales, not an overhead expense.","D":"Incorrect because inventory carries continuously from one accounting year to the next."}}},{"id":"P1_U5_MCQ_684","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_684","question":"What is the structural difference between 'gross profit' and 'profit for the year' (operating profit)?","options":{"A":"Gross profit deducts indirect overheads, whereas profit for the year deducts direct cost of sales","B":"Gross profit deducts only direct cost of sales from revenue, whereas profit for the year also deducts all indirect overhead expenses","C":"Gross profit includes dividends paid, whereas profit for the year excludes dividends","D":"Gross profit is calculated on the statement of financial position, whereas profit for the year is calculated on the cash flow forecast"},"correctOption":"B","correctAnswer":"Gross profit deducts only direct cost of sales from revenue, whereas profit for the year also deducts all indirect overhead expenses","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Gross profit = Revenue - Cost of sales, while Profit for the year = Gross profit - Overhead expenses.","distractor_reasons":{"A":"Incorrect because this reverses cost of sales and overhead expenses.","B":"Correct selection.","C":"Incorrect because dividends are deducted at the very bottom after profit after tax.","D":"Incorrect because both figures appear on the statement of profit or loss."}}},{"id":"P1_U5_MCQ_685","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_685","question":"How can a business earn a substantial 'gross profit' yet still end up with a 'net loss' for the year?","options":{"A":"When direct cost of sales is greater than total sales revenue","B":"When the business holds zero inventory at year-end","C":"When indirect overhead expenses (such as rent, marketing, salaries, and interest) exceed the gross profit earned","D":"When credit customers pay their invoices early"},"correctOption":"C","correctAnswer":"When indirect overhead expenses (such as rent, marketing, salaries, and interest) exceed the gross profit earned","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Profit = Gross profit - Overhead expenses; if indirect running costs are larger than gross profit, final profit becomes negative (a loss).","distractor_reasons":{"A":"Incorrect because if cost of sales exceeded revenue, gross profit itself would already be negative.","B":"Incorrect because holding zero closing inventory does not automatically cause a net loss.","C":"Correct selection.","D":"Incorrect because early customer payments improve cash flow and do not cause a trading loss."}}},{"id":"P1_U5_MCQ_686","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_686","question":"Which cost is classified as a 'direct cost' (part of cost of sales) rather than an 'indirect overhead expense'?","options":{"A":"Annual audit fees paid to external accountants","B":"Salary of the company's chief executive officer","C":"Rent and business rates for the administrative head office","D":"Packaging materials used directly on each unit of product manufactured and sold"},"correctOption":"D","correctAnswer":"Packaging materials used directly on each unit of product manufactured and sold","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because direct product packaging varies directly with units produced and sold, forming part of cost of sales.","distractor_reasons":{"A":"Incorrect because audit fees are indirect administrative overhead expenses.","B":"Incorrect because executive salaries are indirect overhead expenses.","C":"Incorrect because head-office rent and rates are indirect overhead expenses.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_687","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_687","question":"Which group contains ONLY 'indirect overhead expenses' deducted from gross profit on a statement of profit or loss?","options":{"A":"Office administrative salaries, marketing and advertising, shop rent, and annual depreciation of office equipment","B":"Opening inventory, raw material purchases, and direct factory assembly wages","C":"Purchase of freehold factory land and issuance of ordinary shares","D":"Dividends paid to shareholders and corporation tax"},"correctOption":"A","correctAnswer":"Office administrative salaries, marketing and advertising, shop rent, and annual depreciation of office equipment","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because administrative salaries, advertising, rent, and office depreciation are all indirect running costs deducted after gross profit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because inventory, purchases, and direct production wages belong in cost of sales.","C":"Incorrect because freehold land is a non-current asset and share issues are equity.","D":"Incorrect because tax and dividends are deducted after operating profit."}}},{"id":"P1_U5_MCQ_688","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_688","question":"Where is 'interest paid' on bank loans and debentures accounted for on a statement of profit or loss?","options":{"A":"It is added to sales revenue at the top of the statement","B":"It is deducted after operating profit (profit before interest and tax) to calculate profit before tax","C":"It is included in opening inventory","D":"It is omitted completely because interest is a cash flow item"},"correctOption":"B","correctAnswer":"It is deducted after operating profit (profit before interest and tax) to calculate profit before tax","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because finance costs (loan and debenture interest) are deducted from operating profit before corporation tax is calculated.","distractor_reasons":{"A":"Incorrect because interest paid is an expense, not revenue.","B":"Correct selection.","C":"Incorrect because interest is a finance cost, not physical inventory.","D":"Incorrect because interest is a genuine expense reducing profit before tax."}}},{"id":"P1_U5_MCQ_689","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_689","question":"What is the difference between 'profit before tax' and 'profit after tax' for a limited company?","options":{"A":"Profit before tax has not yet deducted overhead expenses","B":"Profit after tax has already deducted dividends paid to shareholders","C":"Profit after tax is the profit remaining once government corporation tax has been subtracted from profit before tax","D":"Profit before tax is calculated on the statement of financial position"},"correctOption":"C","correctAnswer":"Profit after tax is the profit remaining once government corporation tax has been subtracted from profit before tax","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because corporation tax is assessed on profit before tax; deducting that tax leaves profit after tax.","distractor_reasons":{"A":"Incorrect because overhead expenses are deducted earlier to arrive at profit before tax.","B":"Incorrect because dividends are deducted *after* profit after tax to find retained profit.","C":"Correct selection.","D":"Incorrect because both figures appear on the statement of profit or loss."}}},{"id":"P1_U5_MCQ_690","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_690","question":"Why do 'corporation tax' and 'dividends' appear on a limited company's statement of profit or loss, whereas they do NOT appear on a sole trader's statement of profit or loss?","options":{"A":"Because sole traders are legally prohibited from earning any profit","B":"Because sole traders do not have to pay any taxes to the government","C":"Because sole traders are owned by public stock market shareholders","D":"Because a limited company is a separate legal entity paying corporation tax and shareholder dividends, whereas a sole trader is unincorporated and pays personal income tax while taking 'drawings'"},"correctOption":"D","correctAnswer":"Because a limited company is a separate legal entity paying corporation tax and shareholder dividends, whereas a sole trader is unincorporated and pays personal income tax while taking 'drawings'","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because unincorporated businesses do not have separate corporate legal personality, share capital, or corporation tax.","distractor_reasons":{"A":"Incorrect because sole traders are profit-seeking private businesses.","B":"Incorrect because sole traders pay personal income tax on their business profits.","C":"Incorrect because sole traders are owned by one individual, not stock market shareholders.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_691","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_691","question":"What is the difference between 'drawings' and 'dividends'?","options":{"A":"Drawings are cash or goods withdrawn by a sole trader or partner for personal use, whereas dividends are shares of after-tax profit distributed to a limited company's shareholders","B":"Drawings are paid to commercial banks, whereas dividends are paid to suppliers","C":"Drawings are deducted before gross profit, whereas dividends are added to sales revenue","D":"Drawings apply only to public limited companies, whereas dividends apply only to sole traders"},"correctOption":"A","correctAnswer":"Drawings are cash or goods withdrawn by a sole trader or partner for personal use, whereas dividends are shares of after-tax profit distributed to a limited company's shareholders","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because drawings represent owner withdrawals in unincorporated firms, whereas dividends are corporate profit distributions to shareholders.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because neither drawings nor dividends are payments to banks or suppliers.","C":"Incorrect because neither is an operating expense or revenue item.","D":"Incorrect because this reverses unincorporated and incorporated legal structures."}}},{"id":"P1_U5_MCQ_692","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_692","question":"Why might a company's board of directors choose to pay 'zero dividends' in a year when the company made only a modest profit?","options":{"A":"Because paying dividends is illegal whenever profit is below $1 million","B":"Because ordinary dividends are discretionary, and directors may prefer to retain all profit to preserve cash liquidity or fund essential investments","C":"Because paying dividends increases the company's cost of sales","D":"Because zero dividends automatically turns the company into a charity"},"correctOption":"B","correctAnswer":"Because ordinary dividends are discretionary, and directors may prefer to retain all profit to preserve cash liquidity or fund essential investments","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because unlike mandatory loan interest, ordinary dividends are flexible and can be reduced or suspended to protect cash flow and reserves.","distractor_reasons":{"A":"Incorrect because there is no statutory minimum profit threshold for paying dividends.","B":"Correct selection.","C":"Incorrect because dividends are appropriated after tax and do not affect cost of sales.","D":"Incorrect because skipping a dividend does not alter a company's commercial legal status."}}},{"id":"P1_U5_MCQ_693","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_693","question":"How does consistently accumulating 'retained profit' strengthen a limited company over time?","options":{"A":"It increases the company's short-term current liabilities every year","B":"It eliminates all future overhead expenses","C":"It builds up internal equity reserves to finance expansion without borrowing, reduces gearing risk, and provides a financial cushion against future downturns","D":"It forces competitors to exit the market"},"correctOption":"C","correctAnswer":"It builds up internal equity reserves to finance expansion without borrowing, reduces gearing risk, and provides a financial cushion against future downturns","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because retained profit expands the company's equity base, funding growth cheaply while improving financial resilience.","distractor_reasons":{"A":"Incorrect because retained profit increases shareholders' equity, not liabilities.","B":"Incorrect because ongoing businesses still incur overhead expenses.","C":"Correct selection.","D":"Incorrect because internal reserves do not automatically force rivals out of the market."}}},{"id":"P1_U5_MCQ_694","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_694","question":"Under what condition will 'increasing selling prices' FAIL to increase a business's profit?","options":{"A":"When the product has price-inelastic demand and loyal customers","B":"When unit cost of sales stays constant","C":"When fixed overhead expenses remain unchanged","D":"When demand is price-elastic, causing customers to switch to cheaper rivals so sharply that sales volume and total revenue fall"},"correctOption":"D","correctAnswer":"When demand is price-elastic, causing customers to switch to cheaper rivals so sharply that sales volume and total revenue fall","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because if demand is price-elastic, a price hike triggers a disproportionately larger drop in unit sales, reducing revenue and profit.","distractor_reasons":{"A":"Incorrect because price-inelastic demand causes revenue and profit to rise when price increases.","B":"Incorrect because constant unit costs allow higher prices to widen unit profit margins.","C":"Incorrect because constant fixed overheads help higher margins flow into higher profit.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_695","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_695","question":"Under what condition can 'lowering selling prices' actually *increase* a business's total profit?","options":{"A":"When demand is price-elastic so the percentage rise in sales volume outweighs the lower profit margin per unit, provided the business has spare capacity to meet extra orders","B":"When demand is completely price-inelastic so sales volume does not change at all","C":"When the new selling price is set below the direct variable cost of sales per unit","D":"When lowering prices automatically doubles fixed rent expenses"},"correctOption":"A","correctAnswer":"When demand is price-elastic so the percentage rise in sales volume outweighs the lower profit margin per unit, provided the business has spare capacity to meet extra orders","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cutting prices on price-elastic goods expands total revenue and total contribution when unit selling price still exceeds variable cost.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because if volume stays unchanged at a lower price, revenue and profit fall.","C":"Incorrect because selling below direct variable cost makes a loss on every extra unit sold.","D":"Incorrect because retail pricing does not change fixed rent."}}},{"id":"P1_U5_MCQ_696","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_696","question":"What is a potential trade-off when a business tries to increase gross profit by switching to a cheaper raw-material supplier?","options":{"A":"Cheaper raw materials automatically increase head-office rent","B":"Lower material quality may increase defect rates, damage brand reputation, and reduce repeat customer sales in the long run","C":"Cheaper raw materials increase cost of sales","D":"Switching suppliers converts equity into non-current liabilities"},"correctOption":"B","correctAnswer":"Lower material quality may increase defect rates, damage brand reputation, and reduce repeat customer sales in the long run","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because reducing direct input costs boosts gross margin initially, but sacrificing product quality can alienate customers.","distractor_reasons":{"A":"Incorrect because raw material prices do not change fixed office rent.","B":"Correct selection.","C":"Incorrect because cheaper raw materials reduce rather than increase cost of sales.","D":"Incorrect because supplier changes do not alter capital structure."}}},{"id":"P1_U5_MCQ_697","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_697","question":"What is a major risk of cutting 'overhead expenses' such as marketing budgets or staff training in order to boost short-term profit?","options":{"A":"Gross profit margin will immediately fall to zero","B":"Current liabilities will double overnight","C":"While profit increases immediately due to lower expenses, future brand awareness, customer loyalty, and workforce productivity may decline","D":"The business will have to pay corporation tax even if it makes a loss"},"correctOption":"C","correctAnswer":"While profit increases immediately due to lower expenses, future brand awareness, customer loyalty, and workforce productivity may decline","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because slashing discretionary overheads like advertising and training improves this year's bottom line at the expense of future competitiveness.","distractor_reasons":{"A":"Incorrect because marketing and training are indirect overheads, not part of gross profit.","B":"Incorrect because reducing expenses does not double current liabilities.","C":"Correct selection.","D":"Incorrect because corporation tax is charged only when positive profit is earned."}}},{"id":"P1_U5_MCQ_698","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_698","question":"Why do 'suppliers' examine a business customer's statement of profit or loss in addition to its statement of financial position?","options":{"A":"To calculate how much corporation tax the supplier owes","B":"To check the customer's exact daily physical cash balance","C":"To set the customer's retail selling prices","D":"To see whether the customer is consistently profitable and growing, indicating it will remain a reliable long-term buyer placing repeat orders"},"correctOption":"D","correctAnswer":"To see whether the customer is consistently profitable and growing, indicating it will remain a reliable long-term buyer placing repeat orders","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because suppliers value profitable customers who are likely to survive, grow, and generate ongoing B2B sales.","distractor_reasons":{"A":"Incorrect because a supplier pays tax on its own profit, not its customer's profit.","B":"Incorrect because cash balances appear on the statement of financial position, not the income statement.","C":"Incorrect because businesses set their own retail prices.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_699","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_699","question":"Besides assessing corporation tax, why does the 'government' review the published statements of profit or loss of major corporations?","options":{"A":"To monitor overall economic growth, industry profitability, and employment stability across the economy","B":"To decide which dividends individual private shareholders should spend","C":"To approve every routine purchase of raw materials","D":"To guarantee that no company ever makes a loss"},"correctOption":"A","correctAnswer":"To monitor overall economic growth, industry profitability, and employment stability across the economy","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because corporate profit trends help governments forecast tax revenues and gauge macroeconomic health.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because shareholders freely decide how to use their dividend income.","C":"Incorrect because governments do not approve routine commercial purchases.","D":"Incorrect because private businesses bear commercial risk in market economies."}}},{"id":"P1_U5_MCQ_700","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_700","question":"Why can comparing raw dollar profit figures between a large multinational corporation and a small local business be misleading?","options":{"A":"Because small businesses are legally forbidden from preparing statements of profit or loss","B":"Because a large corporation invests far more capital and generates much higher revenue, so relative profitability ratios (like profit margin and ROCE) are needed to judge efficiency fairly","C":"Because multinational corporations do not deduct cost of sales","D":"Because raw dollar profit is always equal to cash in the bank"},"correctOption":"B","correctAnswer":"Because a large corporation invests far more capital and generates much higher revenue, so relative profitability ratios (like profit margin and ROCE) are needed to judge efficiency fairly","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because absolute profit reflects business scale; percentage ratios standardize performance relative to sales and capital employed.","distractor_reasons":{"A":"Incorrect because all businesses track revenue, costs, and profit.","B":"Correct selection.","C":"Incorrect because all trading businesses deduct cost of sales.","D":"Incorrect because profit differs from cash flow due to credit terms, non-cash items, and capital spending."}}},{"id":"P1_U5_MCQ_701","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_701","question":"Why was the 'statement of financial position' traditionally called a 'balance sheet'?","options":{"A":"Because cash inflows must always equal cash outflows on the statement","B":"Because gross profit must always equal indirect overhead expenses","C":"Because total assets minus total liabilities (net assets) must always equal total owners' equity, meaning both sides of the accounting equation balance","D":"Because non-current assets must always equal current liabilities"},"correctOption":"C","correctAnswer":"Because total assets minus total liabilities (net assets) must always equal total owners' equity, meaning both sides of the accounting equation balance","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because double-entry accounting ensures that Net assets = Total equity (or Total assets = Total liabilities + Total equity) at all times.","distractor_reasons":{"A":"Incorrect because cash inflows and outflows appear on the cash flow statement and rarely equal each other.","B":"Incorrect because gross profit and overheads appear on the statement of profit or loss.","C":"Correct selection.","D":"Incorrect because non-current assets and current liabilities have no requirement to be equal."}}},{"id":"P1_U5_MCQ_702","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_702","question":"How does the time horizon of a 'statement of profit or loss' differ from that of a 'statement of financial position'?","options":{"A":"A statement of profit or loss covers one single day, whereas a statement of financial position covers ten years","B":"Both statements cover only a single 24-hour trading day","C":"A statement of profit or loss projects the future, whereas a statement of financial position records only cash","D":"A statement of profit or loss measures financial flows over a period of time (e.g., 12 months), whereas a statement of financial position records asset, liability, and equity balances at one specific date"},"correctOption":"D","correctAnswer":"A statement of profit or loss measures financial flows over a period of time (e.g., 12 months), whereas a statement of financial position records asset, liability, and equity balances at one specific date","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the income statement is a period flow report ('For the year ended...'), while the statement of financial position is a point-in-time snapshot ('As at...').","distractor_reasons":{"A":"Incorrect because this reverses the period vs point-in-time distinction.","B":"Incorrect because the income statement covers an entire accounting period.","C":"Incorrect because both statements are historical financial reports.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_703","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_703","question":"Which pairing correctly distinguishes a 'tangible non-current asset' from an 'intangible non-current asset'?","options":{"A":"Tangible: factory machinery and delivery vans; Intangible: purchased patents, copyrights, and brand goodwill","B":"Tangible: trade receivables and cash; Intangible: trade payables and bank overdrafts","C":"Tangible: purchased patents; Intangible: freehold land and buildings","D":"Tangible: issued share capital; Intangible: retained profit"},"correctOption":"A","correctAnswer":"Tangible: factory machinery and delivery vans; Intangible: purchased patents, copyrights, and brand goodwill","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because tangible non-current assets have physical form (machinery, vehicles, buildings), whereas intangible non-current assets are non-physical legal or commercial rights (patents, copyrights, purchased goodwill).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because receivables and cash are current assets, while payables and overdrafts are current liabilities.","C":"Incorrect because this reverses tangible and intangible assets.","D":"Incorrect because share capital and retained profit are shareholders' equity."}}},{"id":"P1_U5_MCQ_704","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_704","question":"Why does 'freehold land' generally NOT depreciate over time on a statement of financial position, whereas 'machinery and vehicles' do?","options":{"A":"Because land is classified as a current asset","B":"Because land has an unlimited useful life and does not wear out, whereas machinery and vehicles deteriorate through usage and become technologically obsolete","C":"Because businesses sell all their land at the end of every financial year","D":"Because machinery and vehicles are classified as current liabilities"},"correctOption":"B","correctAnswer":"Because land has an unlimited useful life and does not wear out, whereas machinery and vehicles deteriorate through usage and become technologically obsolete","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because depreciation spreads the cost of finite-life assets over their working lives, whereas land normally retains permanent utility.","distractor_reasons":{"A":"Incorrect because freehold land is a non-current asset.","B":"Correct selection.","C":"Incorrect because businesses hold freehold land for long-term operations.","D":"Incorrect because machinery and vehicles are non-current assets."}}},{"id":"P1_U5_MCQ_705","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_705","question":"How is the 'net book value' of a non-current asset (such as a delivery van) calculated on a statement of financial position?","options":{"A":"Original historical purchase cost + Accumulated depreciation","B":"Current selling price - Trade payables","C":"Original historical purchase cost - Accumulated depreciation to date","D":"Annual sales revenue - Cost of sales"},"correctOption":"C","correctAnswer":"Original historical purchase cost - Accumulated depreciation to date","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because net book value represents the remaining un-depreciated carrying value of the non-current asset on the reporting date.","distractor_reasons":{"A":"Incorrect because depreciation reduces rather than increases an asset's carrying value.","B":"Incorrect because trade payables are unrelated short-term supplier liabilities.","C":"Correct selection.","D":"Incorrect because revenue minus cost of sales calculates gross profit."}}},{"id":"P1_U5_MCQ_706","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_706","question":"In the context of ordering current assets on a statement of financial position, what does 'degree of liquidity' refer to?","options":{"A":"The physical weight of the assets stored in the warehouse","B":"The amount of corporation tax charged on each asset","C":"The interest rate paid on long-term commercial mortgages","D":"How quickly and easily each current asset can be converted into spendable cash without significant loss of value"},"correctOption":"D","correctAnswer":"How quickly and easily each current asset can be converted into spendable cash without significant loss of value","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because current assets are arranged in order of convertibility into cash: Inventories (least liquid) -> Trade receivables -> Cash (most liquid).","distractor_reasons":{"A":"Incorrect because liquidity is a financial concept, not a physical property.","B":"Incorrect because corporation tax is levied on profit, not individual current assets.","C":"Incorrect because mortgage rates apply to non-current debt liabilities.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_707","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_707","question":"Why are 'trade receivables' considered more liquid than 'inventories' on a statement of financial position?","options":{"A":"Because trade receivables represent goods already sold to customers who are contractually obligated to pay cash soon, whereas inventories still have to find buyers","B":"Because trade receivables are physical cash stored in the safe","C":"Because inventories are classified as non-current liabilities","D":"Because trade receivables never involve any risk of non-payment"},"correctOption":"A","correctAnswer":"Because trade receivables represent goods already sold to customers who are contractually obligated to pay cash soon, whereas inventories still have to find buyers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because receivables are one step closer to cash than unsold stock, which must still be marketed and sold.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because trade receivables are unpaid customer invoices, not physical cash yet.","C":"Incorrect because inventories are current assets.","D":"Incorrect because trade receivables still carry a small risk of bad debts."}}},{"id":"P1_U5_MCQ_708","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_708","question":"What financial risk arises if a business allows its 'trade receivables' balance to grow excessively large without strong credit control?","options":{"A":"The business will automatically have to pay higher dividends","B":"Cash is tied up outside the business, causing liquidity shortages, and some overdue customer invoices may turn into irrecoverable bad debts","C":"The business's non-current assets will lose all value","D":"The business will be banned from taking out long-term bank loans"},"correctOption":"B","correctAnswer":"Cash is tied up outside the business, causing liquidity shortages, and some overdue customer invoices may turn into irrecoverable bad debts","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because high trade receivables starve the business of cash and increase exposure to customer defaults (bad debts).","distractor_reasons":{"A":"Incorrect because high receivables drain cash and make paying dividends harder, not mandatory.","B":"Correct selection.","C":"Incorrect because customer receivables do not affect non-current asset values.","D":"Incorrect because high receivables do not legally ban bank loans."}}},{"id":"P1_U5_MCQ_709","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_709","question":"What financial and operational risks arise when a business holds excessively high 'inventories' on its statement of financial position?","options":{"A":"High inventory guarantees instant cash liquidity whenever bills arrive","B":"High inventory eliminates all warehouse rent and insurance expenses","C":"Large amounts of working capital are tied up in unsold goods, storage and insurance costs rise, and stock risks spoiling or becoming obsolete","D":"High inventory reduces current assets and increases non-current liabilities"},"correctOption":"C","correctAnswer":"Large amounts of working capital are tied up in unsold goods, storage and insurance costs rise, and stock risks spoiling or becoming obsolete","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because overstocking drains cash liquidity and creates storage costs and write-down risks.","distractor_reasons":{"A":"Incorrect because inventory is the least liquid current asset and cannot immediately pay bills.","B":"Incorrect because holding more inventory increases warehouse storage and insurance expenses.","C":"Correct selection.","D":"Incorrect because inventory is part of current assets."}}},{"id":"P1_U5_MCQ_710","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_710","question":"When does a business's bank account appear under 'current liabilities' instead of 'current assets' on a statement of financial position?","options":{"A":"Whenever the business holds positive cash savings in a deposit account","B":"Whenever the business receives payments from credit customers","C":"Whenever the business issues new ordinary shares","D":"Whenever the bank current account is overdrawn (a bank overdraft), meaning the business owes money to the bank"},"correctOption":"D","correctAnswer":"Whenever the bank current account is overdrawn (a bank overdraft), meaning the business owes money to the bank","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a positive bank balance is a current asset owned by the firm, whereas a negative (overdrawn) balance is a short-term debt owed to the bank.","distractor_reasons":{"A":"Incorrect because positive bank deposits are current assets.","B":"Incorrect because customer receipts increase positive cash assets.","C":"Incorrect because issuing shares brings cash into the bank.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_711","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_711","question":"How are 'bank overdrafts' and 'long-term bank loans' classified differently on a statement of financial position?","options":{"A":"A bank overdraft is a current liability (due within 12 months), whereas a long-term bank loan is a non-current liability (repayable over more than 12 months)","B":"A bank overdraft is a current asset, whereas a long-term bank loan is shareholders' equity","C":"Both are classified as non-current assets","D":"A bank overdraft is a non-current liability, whereas a long-term bank loan is a current liability"},"correctOption":"A","correctAnswer":"A bank overdraft is a current liability (due within 12 months), whereas a long-term bank loan is a non-current liability (repayable over more than 12 months)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because liabilities are separated by their repayment timeframe: under 12 months (current) vs over 12 months (non-current).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because both are external debt liabilities, not assets or equity.","C":"Incorrect because borrowed funds are liabilities, not assets.","D":"Incorrect because this reverses current and non-current classifications."}}},{"id":"P1_U5_MCQ_712","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_712","question":"Why is 'corporation tax owed' at the end of the financial year classified as a 'current liability' on a company's statement of financial position?","options":{"A":"Because corporation tax is owed to the company by government agencies","B":"Because it is a short-term financial obligation that must be paid to tax authorities within 12 months of the year-end","C":"Because corporation tax is part of issued share capital","D":"Because corporation tax is repayable over 25 years"},"correctOption":"B","correctAnswer":"Because it is a short-term financial obligation that must be paid to tax authorities within 12 months of the year-end","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because unpaid tax at the reporting date is a short-term debt due within the next accounting year.","distractor_reasons":{"A":"Incorrect because the company owes tax to the government, making it a liability rather than an asset.","B":"Correct selection.","C":"Incorrect because share capital is owners' equity.","D":"Incorrect because corporation tax is settled annually, not over 25 years."}}},{"id":"P1_U5_MCQ_713","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_713","question":"Why is the subtotal 'Current assets - Current liabilities' on a statement of financial position called both 'net current assets' and 'working capital'?","options":{"A":"Because it measures the value of all freehold buildings owned by the business","B":"Because it shows the total profit earned over the past five years","C":"Because it shows the net short-term liquid resources available to fund day-to-day operations after covering all short-term debts due within a year","D":"Because it equals the total amount of long-term mortgages owed to banks"},"correctOption":"C","correctAnswer":"Because it shows the net short-term liquid resources available to fund day-to-day operations after covering all short-term debts due within a year","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because net current assets represent the surplus of short-term trading assets over short-term trading liabilities, which forms operational working capital.","distractor_reasons":{"A":"Incorrect because freehold buildings are non-current assets.","B":"Incorrect because multi-year accumulated profit is retained profit under equity.","C":"Correct selection.","D":"Incorrect because long-term mortgages are non-current liabilities."}}},{"id":"P1_U5_MCQ_714","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_714","question":"What warning sign does 'negative working capital' (where current liabilities exceed current assets) send to analysts?","options":{"A":"The business holds too much idle cash in its bank account","B":"The business has zero short-term trade payables","C":"The business is earning exceptionally high profit margins","D":"The business may struggle to pay its short-term debts as they fall due and faces serious liquidity risk"},"correctOption":"D","correctAnswer":"The business may struggle to pay its short-term debts as they fall due and faces serious liquidity risk","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because if short-term obligations exceed short-term assets, the business could run out of cash unless it has rapid cash turnover or unused overdraft facilities.","distractor_reasons":{"A":"Incorrect because negative working capital indicates a shortage, not an excess, of liquid assets.","B":"Incorrect because negative working capital occurs when short-term liabilities are high relative to current assets.","C":"Incorrect because working capital measures liquidity rather than profit margins.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_715","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_715","question":"On a limited company's statement of financial position, what is 'Net assets' always equal to?","options":{"A":"Total shareholders' equity (Share capital + Retained profit reserves)","B":"Total current liabilities","C":"Total non-current liabilities","D":"Gross profit minus overhead expenses"},"correctOption":"A","correctAnswer":"Total shareholders' equity (Share capital + Retained profit reserves)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Net assets = Total assets - Total liabilities, which by the accounting equation equals Total shareholders' equity.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because current liabilities are already deducted when calculating net assets.","C":"Incorrect because non-current liabilities are already deducted when calculating net assets.","D":"Incorrect because gross profit minus overheads equals operating profit on the income statement."}}},{"id":"P1_U5_MCQ_716","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_716","question":"Within 'shareholders' equity' on a statement of financial position, how does 'issued share capital' differ from 'retained profit'?","options":{"A":"Issued share capital is borrowed from commercial banks, whereas retained profit is borrowed from suppliers","B":"Issued share capital is the original money invested directly by shareholders buying shares, whereas retained profit is cumulative profit earned by trading and kept inside the company","C":"Issued share capital is a current asset, whereas retained profit is a current liability","D":"Issued share capital must be repaid every year, whereas retained profit is paid to tax authorities"},"correctOption":"B","correctAnswer":"Issued share capital is the original money invested directly by shareholders buying shares, whereas retained profit is cumulative profit earned by trading and kept inside the company","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because share capital reflects external equity contributions from shareholders, while retained profit reflects internal wealth generated through profitable trading.","distractor_reasons":{"A":"Incorrect because neither is borrowed debt; both belong to shareholders.","B":"Correct selection.","C":"Incorrect because both are components of shareholders' equity.","D":"Incorrect because share capital is permanent and retained profit remains in the business."}}},{"id":"P1_U5_MCQ_717","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_717","question":"Which two formulas are mathematically equivalent ways of expressing 'Capital employed' on a statement of financial position?","options":{"A":"'Current assets - Current liabilities' and 'Gross profit - Expenses'","B":"'Total revenue - Cost of sales' and 'Cash inflows - Cash outflows'","C":"'Total shareholders' equity + Non-current liabilities' and 'Non-current assets + Net current assets (working capital)'","D":"'Issued share capital - Retained profit' and 'Current liabilities + Non-current liabilities'"},"correctOption":"C","correctAnswer":"'Total shareholders' equity + Non-current liabilities' and 'Non-current assets + Net current assets (working capital)'","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because since Net assets (Non-current assets + Working capital - Non-current liabilities) equals Total equity, adding Non-current liabilities back to both sides gives Capital employed.","distractor_reasons":{"A":"Incorrect because these calculate working capital and operating profit respectively.","B":"Incorrect because these calculate gross profit and net cash flow respectively.","C":"Correct selection.","D":"Incorrect because retained profit is added to share capital, and current liabilities are excluded from capital employed."}}},{"id":"P1_U5_MCQ_718","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_718","question":"When a business purchases raw material inventory on 30-day trade credit, what is the immediate effect on its statement of financial position?","options":{"A":"Current assets (inventories) increase and current liabilities (trade payables) increase by the same amount, leaving working capital unchanged","B":"Current assets (cash) decrease and shareholders' equity decreases","C":"Non-current assets increase and non-current liabilities increase","D":"Working capital doubles immediately"},"correctOption":"A","correctAnswer":"Current assets (inventories) increase and current liabilities (trade payables) increase by the same amount, leaving working capital unchanged","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because receiving stock adds to inventories (+current asset) while owing the supplier adds to trade payables (+current liability) equally.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because buying on credit uses no cash immediately and does not reduce equity.","C":"Incorrect because raw materials are current assets and 30-day credit is a current liability.","D":"Incorrect because equal increases in current assets and current liabilities leave Net current assets unchanged."}}},{"id":"P1_U5_MCQ_719","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_719","question":"When a credit customer pays an outstanding invoice in cash, how does this transaction change the business's statement of financial position?","options":{"A":"Total current assets increase by the payment amount","B":"Cash (current asset) increases and trade receivables (current asset) decrease by the exact same amount, leaving total current assets unchanged","C":"Current liabilities (trade payables) decrease","D":"Shareholders' equity increases by the payment amount"},"correctOption":"B","correctAnswer":"Cash (current asset) increases and trade receivables (current asset) decrease by the exact same amount, leaving total current assets unchanged","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because collecting a receivable swaps one current asset (unpaid invoice) for another current asset (cash) of equal value.","distractor_reasons":{"A":"Incorrect because cash rises while trade receivables fall by the exact same figure.","B":"Correct selection.","C":"Incorrect because customer payments affect trade receivables, not trade payables.","D":"Incorrect because profit was already recognized when the credit sale was originally made."}}},{"id":"P1_U5_MCQ_720","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_720","question":"When a business uses cash from its bank current account to repay part of a long-term bank loan, what happens on its statement of financial position?","options":{"A":"Current assets (cash) increase and non-current liabilities increase","B":"Current liabilities decrease and shareholders' equity increases","C":"Current assets (cash) decrease and non-current liabilities decrease by the same amount, leaving net assets unchanged","D":"Non-current assets decrease and retained profit increases"},"correctOption":"C","correctAnswer":"Current assets (cash) decrease and non-current liabilities decrease by the same amount, leaving net assets unchanged","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because using cash (-current asset) to pay down long-term debt (-non-current liability) reduces assets and liabilities equally.","distractor_reasons":{"A":"Incorrect because paying off debt reduces cash and reduces debt.","B":"Incorrect because a long-term bank loan is a non-current liability, and repaying principal does not create equity.","C":"Correct selection.","D":"Incorrect because cash is a current asset and debt repayment does not create retained profit."}}},{"id":"P1_U5_MCQ_721","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_721","question":"When a business buys a new delivery vehicle using cash from its bank account, what is the net effect on 'total assets' and 'working capital'?","options":{"A":"Total assets increase and working capital increases","B":"Total assets decrease and working capital stays unchanged","C":"Non-current liabilities increase and working capital increases","D":"Non-current assets increase and current assets (cash) decrease by the same amount, so total assets stay unchanged while working capital decreases"},"correctOption":"D","correctAnswer":"Non-current assets increase and current assets (cash) decrease by the same amount, so total assets stay unchanged while working capital decreases","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because cash (a current asset) is converted into a vehicle (a non-current asset); total assets remain constant, but current assets—and thus working capital—fall.","distractor_reasons":{"A":"Incorrect because cash falls by the exact price of the vehicle.","B":"Incorrect because total assets are unchanged while working capital falls.","C":"Incorrect because buying for cash creates no debt liability.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_722","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_722","question":"How do 'shareholders' use a company's statement of financial position to evaluate long-term financial stability?","options":{"A":"By checking how the business is financed (comparing long-term debt against shareholders' equity) and seeing whether net assets and retained profit reserves are growing over time","B":"By calculating the exact gross profit margin on individual product lines","C":"By checking the daily attendance records of factory employees","D":"By calculating the government's national inflation rate"},"correctOption":"A","correctAnswer":"By checking how the business is financed (comparing long-term debt against shareholders' equity) and seeing whether net assets and retained profit reserves are growing over time","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because shareholders inspect capital gearing (debt vs equity) and net asset growth to judge risk and long-term wealth creation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because gross profit margin comes from the statement of profit or loss.","C":"Incorrect because attendance records are internal HR data.","D":"Incorrect because inflation rates are macroeconomic statistics."}}},{"id":"P1_U5_MCQ_723","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_723","question":"Why does a company planning to take over (acquire) another business carefully examine the target company's statement of financial position?","options":{"A":"Because acquiring the company means taking over all its non-current and current assets as well as all its short-term and long-term liabilities","B":"Because the statement of financial position guarantees future customer demand","C":"Because the statement of financial position lists the personal savings of all rival managers","D":"Because tax authorities prohibit takeovers unless current liabilities are zero"},"correctOption":"A","correctAnswer":"Because acquiring the company means taking over all its non-current and current assets as well as all its short-term and long-term liabilities","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a buyer inherits both the target's assets and its debts, making net asset value and liability obligations central to takeover valuation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because balance sheets show historical positions, not future demand guarantees.","C":"Incorrect because personal finances of managers are excluded from company statements.","D":"Incorrect because virtually all operating businesses have some current liabilities."}}},{"id":"P1_U5_MCQ_724","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_724","question":"How are 'inventories' normally valued on a statement of financial position, and why can this understate potential cash inflows?","options":{"A":"Inventories are valued at double their retail selling price, overstating cash","B":"Inventories are valued at their purchase/production cost (or lower realizable value) rather than their full retail selling price, excluding the profit margin expected upon sale","C":"Inventories are omitted completely from the statement of financial position","D":"Inventories are valued at the same price as freehold land"},"correctOption":"B","correctAnswer":"Inventories are valued at their purchase/production cost (or lower realizable value) rather than their full retail selling price, excluding the profit margin expected upon sale","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because under accounting prudence rules, unsold stock is recorded at cost rather than anticipated selling price until a sale actually takes place.","distractor_reasons":{"A":"Incorrect because accounting rules forbid recording unrealized retail profit before goods are sold.","B":"Correct selection.","C":"Incorrect because inventories are a core component of current assets.","D":"Incorrect because inventories are valued based on their own purchase or manufacturing cost."}}},{"id":"P1_U5_MCQ_725","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_725","question":"Why can the year-end reporting date of a 'statement of financial position' create a slightly distorted picture of a business's typical liquidity?","options":{"A":"Because statements of financial position are legally allowed to omit all bank overdrafts on the last day of the year","B":"Because non-current assets disappear on the reporting date","C":"Because a single-day snapshot may fall right after a seasonal cash peak or temporary working capital adjustment ('window dressing') that does not reflect typical mid-year cash levels","D":"Because share capital is reset to zero on the reporting date"},"correctOption":"C","correctAnswer":"Because a single-day snapshot may fall right after a seasonal cash peak or temporary working capital adjustment ('window dressing') that does not reflect typical mid-year cash levels","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because balance sheets capture a single day's position, which may look unusually strong or weak depending on seasonal cycles or year-end payment timing.","distractor_reasons":{"A":"Incorrect because all liabilities must be reported truthfully on the reporting date.","B":"Incorrect because non-current assets remain recorded at net book value.","C":"Correct selection.","D":"Incorrect because share capital remains permanently on the statement."}}},{"id":"P1_U5_MCQ_726","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_726","question":"Which grouping correctly separates 'profitability ratios' from 'liquidity ratios'?","options":{"A":"Profitability ratios: Current ratio and Acid-test ratio; Liquidity ratios: Gross profit margin, Profit margin, and ROCE","B":"Profitability ratios: Gross profit margin and Current ratio; Liquidity ratios: Profit margin and ROCE","C":"Profitability ratios: ROCE and Acid-test ratio; Liquidity ratios: Gross profit margin and Profit margin","D":"Profitability ratios: Gross profit margin, Profit margin, and Return on Capital Employed (ROCE); Liquidity ratios: Current ratio and Acid-test ratio"},"correctOption":"D","correctAnswer":"Profitability ratios: Gross profit margin, Profit margin, and Return on Capital Employed (ROCE); Liquidity ratios: Current ratio and Acid-test ratio","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because profitability ratios measure profit relative to sales or capital invested, whereas liquidity ratios measure short-term assets relative to short-term liabilities.","distractor_reasons":{"A":"Incorrect because this reverses profitability and liquidity ratios.","B":"Incorrect because the current ratio is a liquidity ratio, while profit margin and ROCE are profitability ratios.","C":"Incorrect because ROCE is a profitability ratio and the acid-test ratio is a liquidity ratio.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_727","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_727","question":"Why is calculating 'profit margin (%)' more informative than looking at dollar profit alone when tracking a growing business over five years?","options":{"A":"Because profit margin reveals whether profit is growing faster or slower than sales revenue, showing if cost control is improving or slipping as sales expand","B":"Because dollar profit figures are illegal to publish in annual reports","C":"Because profit margin measures the exact cash balance in the bank","D":"Because profit margin automatically eliminates all overhead expenses"},"correctOption":"A","correctAnswer":"Because profit margin reveals whether profit is growing faster or slower than sales revenue, showing if cost control is improving or slipping as sales expand","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because if sales double while profit rises by only 10%, dollar profit looks higher, but a falling profit margin warns that costs are rising faster than revenue.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because dollar profit figures are always published in financial statements.","C":"Incorrect because profit margin is calculated from profit and revenue, not bank cash.","D":"Incorrect because profit margin is calculated *after* deducting overhead expenses."}}},{"id":"P1_U5_MCQ_728","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_728","question":"Which combination of events would directly increase a business's 'gross profit margin'?","options":{"A":"Lowering selling prices while paying higher prices for raw materials","B":"Raising selling prices (without losing proportional volume) or negotiating cheaper raw material/wholesale purchase costs per unit","C":"Reducing head-office administrative salaries and television advertising","D":"Issuing new ordinary shares and repaying a long-term bank loan"},"correctOption":"B","correctAnswer":"Raising selling prices (without losing proportional volume) or negotiating cheaper raw material/wholesale purchase costs per unit","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because gross profit margin depends on the spread between unit selling price and direct unit cost of sales.","distractor_reasons":{"A":"Incorrect because lower prices and higher input costs would shrink gross profit margin.","B":"Correct selection.","C":"Incorrect because reducing indirect overheads improves profit margin, not gross profit margin.","D":"Incorrect because financing changes do not alter gross profit margin."}}},{"id":"P1_U5_MCQ_729","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_729","question":"Why can supermarkets operate successfully with very low 'profit margins' (often 2% to 4%), whereas luxury jewelry boutiques require high profit margins?","options":{"A":"Because supermarkets are exempt from paying cost of sales and wages","B":"Because supermarkets are owned by the government and do not need to earn profit","C":"Because supermarkets sell huge volumes of everyday essentials with rapid inventory turnover, generating large total profits from small per-unit margins, whereas jewelers sell low volumes infrequently","D":"Because luxury jewelers have negative gross profit margins"},"correctOption":"C","correctAnswer":"Because supermarkets sell huge volumes of everyday essentials with rapid inventory turnover, generating large total profits from small per-unit margins, whereas jewelers sell low volumes infrequently","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because industry benchmarks differ: high-volume, fast-turnover retailers earn strong total returns from slim margins, while low-volume specialty sellers need high margins per sale.","distractor_reasons":{"A":"Incorrect because supermarkets pay full cost of sales and staff wages.","B":"Incorrect because commercial supermarkets are private-sector profit-seeking businesses.","C":"Correct selection.","D":"Incorrect because luxury jewelers rely on high positive gross profit margins."}}},{"id":"P1_U5_MCQ_730","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_730","question":"How can a business improve its 'profit margin' even when its 'gross profit margin' remains completely unchanged?","options":{"A":"By increasing raw material wastage in the factory","B":"By doubling the bank overdraft limit","C":"By buying more freehold land for cash","D":"By reducing indirect overhead expenses (such as head-office admin, rent, or energy bills) relative to sales revenue"},"correctOption":"D","correctAnswer":"By reducing indirect overhead expenses (such as head-office admin, rent, or energy bills) relative to sales revenue","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because controlling indirect overhead expenses allows a larger share of gross profit to convert into final operating profit.","distractor_reasons":{"A":"Incorrect because higher material wastage increases cost of sales and lowers both gross profit margin and profit margin.","B":"Incorrect because raising an overdraft limit does not reduce operating expenses.","C":"Incorrect because buying land is capital expenditure and does not improve operating profit margin.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_731","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_731","question":"Why is 'Return on Capital Employed (ROCE)' often referred to as the 'primary ratio' when evaluating overall business performance?","options":{"A":"Because it links profit directly to the total long-term capital invested in the business, measuring how effectively management generates returns on every dollar of capital employed","B":"Because it is the only ratio that can be calculated without any financial statements","C":"Because it measures whether the business can pay next week's electricity bill","D":"Because it is always equal to 100% for every limited company"},"correctOption":"A","correctAnswer":"Because it links profit directly to the total long-term capital invested in the business, measuring how effectively management generates returns on every dollar of capital employed","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ROCE combines profitability and capital efficiency into a single benchmark comparable across firms and against interest rates.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because calculating ROCE requires profit from the income statement and capital employed from the statement of financial position.","C":"Incorrect because short-term bill-paying ability is measured by liquidity ratios.","D":"Incorrect because ROCE varies widely across businesses and typically ranges between 5% and 25%."}}},{"id":"P1_U5_MCQ_732","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_732","question":"What happens to a company's 'Return on Capital Employed (ROCE)' if its operating profit increases while its capital employed remains unchanged?","options":{"A":"ROCE decreases","B":"ROCE increases, showing improved efficiency in generating profit from existing capital","C":"ROCE remains completely unchanged","D":"ROCE becomes negative"},"correctOption":"B","correctAnswer":"ROCE increases, showing improved efficiency in generating profit from existing capital","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because ROCE = (Profit / Capital employed) × 100; a larger numerator with a constant denominator raises the percentage return.","distractor_reasons":{"A":"Incorrect because higher profit increases rather than decreases ROCE.","B":"Correct selection.","C":"Incorrect because ROCE changes whenever profit or capital employed changes.","D":"Incorrect because rising positive profit keeps ROCE positive."}}},{"id":"P1_U5_MCQ_733","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_733","question":"Why might a company's 'ROCE' temporarily *fall* in the year immediately after it borrows a large long-term loan to build a new factory?","options":{"A":"Because building a new factory permanently reduces sales revenue","B":"Because bank loans are subtracted from capital employed","C":"Because capital employed increases immediately by the new loan, whereas the new factory may take time to be completed and generate full additional profits","D":"Because factories are classified as current liabilities"},"correctOption":"C","correctAnswer":"Because capital employed increases immediately by the new loan, whereas the new factory may take time to be completed and generate full additional profits","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital employed (denominator) rises immediately upon raising long-term finance, while profit (numerator) lags until the new capacity operates fully.","distractor_reasons":{"A":"Incorrect because a new factory is built to expand future output and revenue.","B":"Incorrect because non-current liabilities are added to equity to form capital employed.","C":"Correct selection.","D":"Incorrect because factories are non-current assets."}}},{"id":"P1_U5_MCQ_734","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_734","question":"Why is comparing 'ROCE' between a heavy steel manufacturer and a freelance software consultancy misleading?","options":{"A":"Because software consultancies are forbidden from earning profit","B":"Because steel manufacturers do not hold any non-current assets","C":"Because ROCE can only be calculated for retail shops","D":"Because steel manufacturing is highly capital-intensive (requiring huge capital employed in plants and machinery), whereas software consultancies require minimal physical capital, naturally giving different ROCE norms"},"correctOption":"D","correctAnswer":"Because steel manufacturing is highly capital-intensive (requiring huge capital employed in plants and machinery), whereas software consultancies require minimal physical capital, naturally giving different ROCE norms","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because valid inter-firm ratio comparisons must compare businesses within the same industry and with similar capital structures.","distractor_reasons":{"A":"Incorrect because software consultancies are profit-seeking businesses.","B":"Incorrect because steel manufacturers own massive non-current assets.","C":"Incorrect because ROCE can be calculated for any business.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_735","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_735","question":"What is generally regarded as a safe, comfortable benchmark range for the 'current ratio' in most traditional manufacturing and trading businesses?","options":{"A":"Between 1.5 : 1 and 2.0 : 1","B":"Below 0.5 : 1","C":"Above 10.0 : 1","D":"Exactly 0 : 1"},"correctOption":"A","correctAnswer":"Between 1.5 : 1 and 2.0 : 1","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a current ratio of 1.5 : 1 to 2.0 : 1 means current assets comfortably cover short-term liabilities without tying up excessive idle working capital.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a ratio below 0.5 : 1 indicates severe liquidity danger.","C":"Incorrect because a ratio above 10 : 1 indicates massive unproductive working capital.","D":"Incorrect because a 0 : 1 ratio would mean having zero current assets."}}},{"id":"P1_U5_MCQ_736","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_736","question":"Why can large supermarket chains often operate safely with a 'current ratio' around 1.0 : 1 or slightly lower, whereas a heavy machinery manufacturer would struggle at that level?","options":{"A":"Because supermarkets never have any current liabilities","B":"Because supermarkets sell goods immediately for cash every day while paying food suppliers on 30- to 60-day credit, generating continuous cash inflows before payables fall due","C":"Because machinery manufacturers sell all equipment for instant cash on Day 1","D":"Because supermarkets are exempt from paying their suppliers"},"correctOption":"B","correctAnswer":"Because supermarkets sell goods immediately for cash every day while paying food suppliers on 30- to 60-day credit, generating continuous cash inflows before payables fall due","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because negative or tight working capital works safely when stock turns into cash faster than supplier credit terms expire.","distractor_reasons":{"A":"Incorrect because supermarkets carry substantial trade payables.","B":"Correct selection.","C":"Incorrect because machinery manufacturers have long production cycles and sell on credit.","D":"Incorrect because supermarkets must pay their suppliers in full."}}},{"id":"P1_U5_MCQ_737","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_737","question":"Which action would directly *improve* a business's dangerously low 'current ratio'?","options":{"A":"Using cash from the bank account to buy expensive new factory machinery","B":"Taking out a short-term bank overdraft to pay shareholder dividends","C":"Selling surplus, underused non-current assets for cash or raising long-term finance (such as a share issue or long-term loan) to boost cash and pay down short-term overdrafts","D":"Increasing the amount of cash withdrawn as owner drawings"},"correctOption":"C","correctAnswer":"Selling surplus, underused non-current assets for cash or raising long-term finance (such as a share issue or long-term loan) to boost cash and pay down short-term overdrafts","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because injecting long-term funds or converting illiquid non-current assets into cash increases current assets relative to current liabilities.","distractor_reasons":{"A":"Incorrect because spending cash on non-current assets reduces current assets and lowers the current ratio further.","B":"Incorrect because increasing an overdraft and paying out cash reduces working capital and worsens liquidity.","C":"Correct selection.","D":"Incorrect because higher drawings drain cash and worsen the current ratio."}}},{"id":"P1_U5_MCQ_738","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_738","question":"What does an 'acid-test ratio' of at least 1 : 1 signify about a business's short-term liquidity?","options":{"A":"The business has zero inventory in its warehouse","B":"The business earns $1 of profit for every $1 of sales revenue","C":"The business's non-current assets equal its non-current liabilities","D":"The business can cover all of its immediate current liabilities using only its liquid cash and trade receivables, without relying on selling any inventory"},"correctOption":"D","correctAnswer":"The business can cover all of its immediate current liabilities using only its liquid cash and trade receivables, without relying on selling any inventory","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because an acid-test ratio of 1 : 1 or higher means liquid assets (Current assets - Inventories) equal or exceed current liabilities.","distractor_reasons":{"A":"Incorrect because a business can hold substantial inventory and still have an acid-test ratio above 1 : 1.","B":"Incorrect because profit per dollar of sales is profit margin, not the acid-test ratio.","C":"Incorrect because the acid-test ratio only examines current items.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_739","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_739","question":"Why is a business's 'acid-test ratio' always lower than (or at most equal to) its 'current ratio'?","options":{"A":"Because inventories are subtracted from the numerator in the acid-test ratio while the denominator (current liabilities) stays the same","B":"Because current liabilities are doubled in the acid-test ratio","C":"Because non-current assets are added to the current ratio","D":"Because trade receivables are subtracted from the current ratio"},"correctOption":"A","correctAnswer":"Because inventories are subtracted from the numerator in the acid-test ratio while the denominator (current liabilities) stays the same","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because subtracting non-negative inventory reduces the numerator, making the acid-test ratio smaller than the current ratio (or equal only if inventory is zero).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because both ratios use the exact same current liabilities denominator.","C":"Incorrect because neither ratio includes non-current assets.","D":"Incorrect because trade receivables remain in the numerator of both ratios."}}},{"id":"P1_U5_MCQ_740","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_740","question":"If a business holds a promotional clearance sale that converts slow-moving inventory into cash, how does this affect its 'acid-test ratio'?","options":{"A":"The acid-test ratio decreases","B":"The acid-test ratio increases because cash (included in the acid-test numerator) rises while inventory (excluded from the acid-test numerator) falls","C":"The acid-test ratio remains completely unchanged","D":"The acid-test ratio becomes zero"},"correctOption":"B","correctAnswer":"The acid-test ratio increases because cash (included in the acid-test numerator) rises while inventory (excluded from the acid-test numerator) falls","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because shifting value out of excluded inventory and into liquid cash raises the acid-test numerator without changing current liabilities.","distractor_reasons":{"A":"Incorrect because increasing cash raises rather than lowers the acid-test ratio.","B":"Correct selection.","C":"Incorrect because converting excluded stock into included cash changes the acid-test numerator.","D":"Incorrect because higher cash creates a positive numerator."}}},{"id":"P1_U5_MCQ_741","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_741","question":"Which list contains ONLY 'external users' of a business's financial accounts?","options":{"A":"Departmental managers, factory supervisors, and internal financial controllers","B":"Board of directors, internal accountants, and commercial banks","C":"Commercial banks, trade suppliers, government tax authorities, potential investors, and trade unions","D":"Chief executive officer, marketing director, and operations manager"},"correctOption":"C","correctAnswer":"Commercial banks, trade suppliers, government tax authorities, potential investors, and trade unions","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because banks, suppliers, tax authorities, outside investors, and trade unions operate outside the company's internal management structure.","distractor_reasons":{"A":"Incorrect because departmental managers, supervisors, and financial controllers are internal users.","B":"Incorrect because the board of directors and internal accountants are internal users.","C":"Correct selection.","D":"Incorrect because the CEO, marketing director, and operations manager are internal executives."}}},{"id":"P1_U5_MCQ_742","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_742","question":"Why do internal managers prepare monthly or quarterly 'management accounts' rather than waiting for the annual published financial statements?","options":{"A":"Because annual published accounts are illegal for managers to read","B":"Because annual accounts omit all revenue and profit figures","C":"Because monthly management accounts replace the need to pay corporation tax","D":"Because managers need timely, product-level and branch-level data throughout the year to spot problems early and make rapid operational decisions"},"correctOption":"D","correctAnswer":"Because managers need timely, product-level and branch-level data throughout the year to spot problems early and make rapid operational decisions","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because annual published statements summarize the whole business too late for day-to-day operational control.","distractor_reasons":{"A":"Incorrect because managers obviously review annual accounts as well.","B":"Incorrect because annual accounts include full revenue and profit statements.","C":"Incorrect because corporation tax is still assessed annually.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_743","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_743","question":"Why do 'commercial banks' analyze *both* profitability ratios and liquidity ratios before granting a long-term business loan?","options":{"A":"Profitability ratios show whether the business is viable enough to earn future profits and afford interest, while liquidity ratios show whether it has enough short-term cash to pay instalments on time without defaulting","B":"Because banks require both ratios to be identical before approving any loan","C":"Because banks take direct control of the borrower's marketing department","D":"Because liquidity ratios measure employee motivation while profitability ratios measure factory size"},"correctOption":"A","correctAnswer":"Profitability ratios show whether the business is viable enough to earn future profits and afford interest, while liquidity ratios show whether it has enough short-term cash to pay instalments on time without defaulting","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a business needs both long-term earning power (profitability) and immediate cash-paying capacity (liquidity) to service debt reliably.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because profitability percentages and liquidity ratios are measured on completely different scales.","C":"Incorrect because banks are lenders, not operational managers.","D":"Incorrect because both sets of ratios measure financial performance, not motivation or factory size."}}},{"id":"P1_U5_MCQ_744","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_744","question":"Why do 'trade unions' examine a company's liquidity ratios alongside its profit figures during wage negotiations?","options":{"A":"To calculate the exact market value of the company's patents","B":"To check whether the company actually has enough liquid cash to afford a wage rise without triggering a cash crisis or redundancies","C":"To decide whether the company should issue debentures on the stock exchange","D":"To audit the company's supplier invoices"},"correctOption":"B","correctAnswer":"To check whether the company actually has enough liquid cash to afford a wage rise without triggering a cash crisis or redundancies","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because high paper profits do not automatically mean spare cash; unions check liquidity to ensure wage demands are sustainable and protect jobs.","distractor_reasons":{"A":"Incorrect because intangible patents are not measured by liquidity ratios.","B":"Correct selection.","C":"Incorrect because financing decisions belong to directors and shareholders.","D":"Incorrect because independent external auditors audit company accounts."}}},{"id":"P1_U5_MCQ_745","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_745","question":"Why might the 'local community' and 'pressure groups' examine the published annual reports and accounts of a large local factory?","options":{"A":"To collect corporation tax directly from the factory","B":"To approve the factory's short-term bank overdraft","C":"To assess whether the factory is financially stable enough to protect local employment and whether it invests in environmentally responsible practices","D":"To set the factory's wholesale selling prices"},"correctOption":"C","correctAnswer":"To assess whether the factory is financially stable enough to protect local employment and whether it invests in environmentally responsible practices","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because local residents and campaigners care about regional job stability and corporate social/environmental responsibility.","distractor_reasons":{"A":"Incorrect because only government tax authorities collect corporation tax.","B":"Incorrect because commercial banks approve overdrafts.","C":"Correct selection.","D":"Incorrect because company managers set selling prices."}}},{"id":"P1_U5_MCQ_746","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_746","question":"Why can comparing ratios between two businesses in the *same* industry still be misleading if one is a massive multinational and the other is a small local firm?","options":{"A":"Because small local firms never calculate gross profit","B":"Because multinational corporations are legally banned from having current liabilities","C":"Because small local firms always have higher ROCE than multinationals","D":"Because large multinationals benefit from economies of scale (such as bulk-buying discounts and lower unit overheads) that small local competitors cannot access"},"correctOption":"D","correctAnswer":"Because large multinationals benefit from economies of scale (such as bulk-buying discounts and lower unit overheads) that small local competitors cannot access","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because valid inter-firm comparison requires comparing businesses of comparable scale as well as the same industry.","distractor_reasons":{"A":"Incorrect because small firms also calculate gross profit.","B":"Incorrect because multinationals carry substantial current liabilities.","C":"Incorrect because ROCE varies depending on performance and capital structure.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_747","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_747","question":"How can 'summarized company-wide financial statements' limit ratio analysis for a diversified conglomerate operating several different divisions?","options":{"A":"Aggregate ratios average all divisions together, potentially hiding severe losses or poor liquidity in one failing division behind strong profits in another","B":"Diversified conglomerates are legally forbidden from publishing statements of financial position","C":"Aggregate ratios always overstate current liabilities by 50%","D":"Diversified conglomerates never pay corporation tax"},"correctOption":"A","correctAnswer":"Aggregate ratios average all divisions together, potentially hiding severe losses or poor liquidity in one failing division behind strong profits in another","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because consolidated financial statements combine figures across the entire group, masking individual product or branch weaknesses.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because plcs must publish full consolidated financial statements.","C":"Incorrect because liabilities are reported accurately according to accounting standards.","D":"Incorrect because conglomerates pay corporation tax on their profits."}}},{"id":"P1_U5_MCQ_748","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_748","question":"Why must investors and managers consider 'qualitative factors' alongside financial ratios when evaluating a business?","options":{"A":"Because financial ratios are illegal to use in business decision-making","B":"Because ratios measure only numerical accounting data and ignore crucial qualitative strengths or risks such as staff morale, customer loyalty, product innovation, and new competitors","C":"Because qualitative factors automatically calculate the acid-test ratio","D":"Because financial statements already include exact dollar values for employee motivation"},"correctOption":"B","correctAnswer":"Because ratios measure only numerical accounting data and ignore crucial qualitative strengths or risks such as staff morale, customer loyalty, product innovation, and new competitors","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because non-financial factors heavily drive future profitability and survival, even though they cannot be captured directly in accounting ratios.","distractor_reasons":{"A":"Incorrect because financial ratios are a standard, essential analytical tool.","B":"Correct selection.","C":"Incorrect because the acid-test ratio is purely quantitative.","D":"Incorrect because employee motivation cannot be quantified in monetary terms on financial statements."}}},{"id":"P1_U5_MCQ_749","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_749","question":"How can 'different financial year-end dates' between two competing companies distort inter-firm ratio comparisons?","options":{"A":"Companies with different year-ends are prohibited from calculating ROCE","B":"Companies with a June year-end never have any trade receivables","C":"In seasonal industries, one company's reporting date may fall at peak stock/cash season while its rival's date falls in a quiet off-peak month, distorting inventory and liquidity ratios","D":"Different year-ends double a company's gross profit margin"},"correctOption":"C","correctAnswer":"In seasonal industries, one company's reporting date may fall at peak stock/cash season while its rival's date falls in a quiet off-peak month, distorting inventory and liquidity ratios","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because balance sheet figures (such as inventories and cash) fluctuate seasonally, making comparisons across different calendar dates uneven.","distractor_reasons":{"A":"Incorrect because any business can calculate ROCE regardless of its fiscal year-end.","B":"Incorrect because trade receivables exist whenever goods are sold on credit.","C":"Correct selection.","D":"Incorrect because reporting dates do not double gross profit margins."}}},{"id":"P1_U5_MCQ_750","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_750","question":"What is the best overall approach for an analyst or manager using financial information to make strategic business decisions?","options":{"A":"Rely exclusively on a single ratio such as gross profit margin and ignore all other documents","B":"Ignore all financial ratios and rely purely on intuition","C":"Look only at cash in the bank and ignore profitability and debt obligations","D":"Combine profitability ratios, liquidity ratios, multi-year trends, industry benchmarks, cash flow forecasts, and qualitative market information for a balanced evaluation"},"correctOption":"D","correctAnswer":"Combine profitability ratios, liquidity ratios, multi-year trends, industry benchmarks, cash flow forecasts, and qualitative market information for a balanced evaluation","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because every financial statement and ratio has limitations in isolation; combining quantitative ratios, forward cash forecasts, and qualitative context produces sound decisions.","distractor_reasons":{"A":"Incorrect because focusing on a single ratio ignores liquidity, capital efficiency, and market context.","B":"Incorrect because ignoring financial data leads to uninformed, high-risk decisions.","C":"Incorrect because cash alone does not show whether the business is profitable or heavily indebted.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_751","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_751","question":"What is the primary role of the 'finance department' within a business organization?","options":{"A":"Raising funds, managing cash flows, budgeting, and recording financial transactions to support business decisions","B":"Designing product packaging and running television advertising campaigns","C":"Recruiting production line workers and negotiating union wage agreements","D":"Operating factory machinery and inspecting finished goods for quality defects"},"correctOption":"A","correctAnswer":"Raising funds, managing cash flows, budgeting, and recording financial transactions to support business decisions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the finance function manages capital raising, liquidity, budgets, and financial accounting records across the organization.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because product packaging and advertising belong to the marketing department.","C":"Incorrect because recruitment and industrial relations belong to the human resources department.","D":"Incorrect because manufacturing and quality control belong to the operations department."}}},{"id":"P1_U5_MCQ_752","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_752","question":"Why do established technology and pharmaceutical businesses require significant finance for 'research and development (R&D)'?","options":{"A":"To pay short-term trade payables within seven days","B":"To fund the high upfront costs of inventing, testing, and patenting new products long before any sales revenue is generated","C":"To distribute weekly cash dividends to commercial banks","D":"To avoid recording depreciation on their factory equipment"},"correctOption":"B","correctAnswer":"To fund the high upfront costs of inventing, testing, and patenting new products long before any sales revenue is generated","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because R&D involves substantial long-term expenditure with uncertain outcomes and a long delay before commercial revenue begins.","distractor_reasons":{"A":"Incorrect because paying suppliers is routine working capital management, not R&D.","B":"Correct selection.","C":"Incorrect because banks receive loan interest, not dividends, and R&D funds innovation.","D":"Incorrect because R&D does not exempt a business from depreciating its equipment."}}},{"id":"P1_U5_MCQ_753","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_753","question":"Why is 'working capital' often described by business analysts as the 'lifeblood' of a business?","options":{"A":"Because working capital is used solely to purchase freehold land","B":"Because working capital is paid out entirely to shareholders every month","C":"Because without sufficient short-term liquid funds to pay wages, suppliers, and daily bills, even a profitable business will halt operations and fail","D":"Because working capital eliminates all corporation tax obligations"},"correctOption":"C","correctAnswer":"Because without sufficient short-term liquid funds to pay wages, suppliers, and daily bills, even a profitable business will halt operations and fail","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because working capital keeps the continuous daily cycle of buying stock, paying workers, and fulfilling orders moving smoothly.","distractor_reasons":{"A":"Incorrect because purchasing freehold land is long-term capital expenditure.","B":"Incorrect because working capital must stay circulating inside the business to fund operations.","C":"Correct selection.","D":"Incorrect because profitable businesses still pay corporation tax."}}},{"id":"P1_U5_MCQ_754","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_754","question":"Why is purchasing a long-term 'patent' or 'commercial franchise licence' classified as 'capital expenditure'?","options":{"A":"Because it is consumed completely within a single trading week","B":"Because it is recorded as a current liability on the statement of financial position","C":"Because it is paid out of a short-term bank overdraft","D":"Because it acquires an intangible non-current asset that will generate benefits for the business over more than one year"},"correctOption":"D","correctAnswer":"Because it acquires an intangible non-current asset that will generate benefits for the business over more than one year","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because capital expenditure includes spending on both tangible and intangible long-term assets lasting beyond 12 months.","distractor_reasons":{"A":"Incorrect because items consumed within one year are revenue expenditure.","B":"Incorrect because acquired patents and licences are non-current assets, not liabilities.","C":"Incorrect because classification depends on asset lifespan, not the bank account used.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_755","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_755","question":"Why are 'staff training costs' and 'routine vehicle servicing' classified as 'revenue expenditure' rather than 'capital expenditure'?","options":{"A":"Because they are ongoing operational expenses incurred within the current accounting year rather than purchases of long-term non-current assets","B":"Because they are financed exclusively by issuing ordinary shares","C":"Because they appear as non-current assets on the statement of financial position","D":"Because they never involve any cash outflow"},"correctOption":"A","correctAnswer":"Because they are ongoing operational expenses incurred within the current accounting year rather than purchases of long-term non-current assets","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because day-to-day running and maintenance costs are expensed on the statement of profit or loss in the period incurred.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because routine operational costs are normally funded out of ongoing sales revenue.","C":"Incorrect because revenue expenditure is recorded as an expense on the income statement, not as a balance sheet asset.","D":"Incorrect because training fees and servicing bills require cash payments."}}},{"id":"P1_U5_MCQ_756","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_756","question":"Why is 'retained profit' considered the single most important long-term source of finance for established, profitable companies?","options":{"A":"Because it is guaranteed by the government against all trading losses","B":"Because it is permanent internal finance that requires no interest payments, no debt repayments, no collateral, and causes no dilution of ownership control","C":"Because it is always equal to the physical cash balance in the bank","D":"Because it can be used by brand-new start-ups on their very first day"},"correctOption":"B","correctAnswer":"Because it is permanent internal finance that requires no interest payments, no debt repayments, no collateral, and causes no dilution of ownership control","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because retained profit avoids the financial risk of debt interest and the control dilution of issuing new shares.","distractor_reasons":{"A":"Incorrect because governments do not insure private company profits.","B":"Correct selection.","C":"Incorrect because retained profit is an accounting equity figure, not necessarily equal to liquid bank cash.","D":"Incorrect because new start-ups have no prior trading history to accumulate retained profit."}}},{"id":"P1_U5_MCQ_757","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_757","question":"What is a key advantage of raising internal finance through the 'sale of surplus non-current assets' compared with taking out a bank loan?","options":{"A":"It increases the business's annual tax-deductible interest expenses","B":"It allows the business to keep using the sold machinery free of charge forever","C":"It makes better use of idle capital tied up in unneeded assets without incurring interest charges or increasing debt liabilities","D":"It immediately increases the business's gross profit margin"},"correctOption":"C","correctAnswer":"It makes better use of idle capital tied up in unneeded assets without incurring interest charges or increasing debt liabilities","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because disposing of redundant equipment or unused land unlocks cash with zero borrowing cost or repayment obligation.","distractor_reasons":{"A":"Incorrect because selling an asset creates no interest expenses.","B":"Incorrect because once an asset is sold outright, the buyer owns and takes possession of it.","C":"Correct selection.","D":"Incorrect because selling a non-current asset is not trading revenue and does not alter gross profit margin."}}},{"id":"P1_U5_MCQ_758","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_758","question":"How does 'tightening credit control to collect trade receivables faster' serve as an internal source of working capital?","options":{"A":"It borrows money from a commercial bank at a fixed interest rate","B":"It issues new shares to credit customers","C":"It delays paying employee wages by three months","D":"It releases cash already owed to the business by customers sooner, reducing the need for external short-term borrowing"},"correctOption":"D","correctAnswer":"It releases cash already owed to the business by customers sooner, reducing the need for external short-term borrowing","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because converting unpaid invoices into cash faster unlocks internal working capital without paying bank interest.","distractor_reasons":{"A":"Incorrect because collecting receivables does not involve bank borrowing.","B":"Incorrect because collecting customer debts is not an equity share issue.","C":"Incorrect because employee wages must be paid on contractual pay dates.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_759","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_759","question":"When a sole trader injects personal savings into their business, how is this finance classified?","options":{"A":"As internal owner's capital (equity) that incurs no interest charges and has no fixed repayment date","B":"As a short-term current liability repayable within 30 days","C":"As an external non-current liability carrying compound interest","D":"As sales revenue on the statement of profit or loss"},"correctOption":"A","correctAnswer":"As internal owner's capital (equity) that incurs no interest charges and has no fixed repayment date","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the owner and unincorporated business are legally the same entity, so personal savings represent internal equity capital.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because owner's capital is equity, not a short-term external debt.","C":"Incorrect because owner's savings are internal equity, not an external loan.","D":"Incorrect because capital injections are equity funding, not revenue from selling goods."}}},{"id":"P1_U5_MCQ_760","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_760","question":"What is a 'rights issue' of shares by an existing limited company?","options":{"A":"Selling debentures to commercial banks at a fixed interest rate","B":"Offering existing shareholders the first option to buy newly issued shares in proportion to their current holdings, allowing the company to raise equity without necessarily diluting existing owners' voting percentages","C":"Forcing customers to buy company shares before purchasing products","D":"Returning all share capital to shareholders in cash"},"correctOption":"B","correctAnswer":"Offering existing shareholders the first option to buy newly issued shares in proportion to their current holdings, allowing the company to raise equity without necessarily diluting existing owners' voting percentages","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a rights issue raises new permanent share capital while giving existing shareholders the opportunity to preserve their proportional ownership.","distractor_reasons":{"A":"Incorrect because debentures are long-term debt instruments, not equity shares.","B":"Correct selection.","C":"Incorrect because customers are not forced to buy shares.","D":"Incorrect because a rights issue brings new cash into the company rather than returning capital."}}},{"id":"P1_U5_MCQ_761","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_761","question":"What is a major financial drawback of raising capital by floating a company on a public stock exchange (an Initial Public Offering)?","options":{"A":"The funds raised must be repaid to stock market investors within 12 months","B":"The company is legally banned from earning retained profit afterward","C":"It involves very high legal, underwriting, and administrative fees, and exposes the company to takeover risks and strict public disclosure rules","D":"The company must pay fixed monthly interest to every shareholder"},"correctOption":"C","correctAnswer":"It involves very high legal, underwriting, and administrative fees, and exposes the company to takeover risks and strict public disclosure rules","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because going public is expensive, increases regulatory transparency, and leaves shares freely tradable on the open market.","distractor_reasons":{"A":"Incorrect because ordinary share capital is permanent and never repaid.","B":"Incorrect because plcs routinely accumulate retained profit.","C":"Correct selection.","D":"Incorrect because ordinary shares pay discretionary dividends, not fixed monthly interest."}}},{"id":"P1_U5_MCQ_762","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_762","question":"What is the key difference between a 'fixed-rate bank loan' and a 'variable-rate bank loan'?","options":{"A":"A fixed-rate loan never has to be repaid, whereas a variable-rate loan is repaid weekly","B":"A fixed-rate loan is an internal source of finance, whereas a variable-rate loan is external","C":"A fixed-rate loan gives the bank voting shares, whereas a variable-rate loan does not","D":"A fixed-rate loan keeps the interest rate and monthly repayments constant throughout the loan term (making budgeting certain), whereas a variable-rate loan changes when market interest rates move"},"correctOption":"D","correctAnswer":"A fixed-rate loan keeps the interest rate and monthly repayments constant throughout the loan term (making budgeting certain), whereas a variable-rate loan changes when market interest rates move","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because fixed-rate loans protect borrowers against interest rate hikes and simplify cash flow forecasting, while variable-rate loans fluctuate with central bank rates.","distractor_reasons":{"A":"Incorrect because both fixed-rate and variable-rate loans must be repaid according to contract.","B":"Incorrect because both are external bank debt.","C":"Incorrect because neither type of bank loan gives the bank equity voting rights.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_763","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_763","question":"Why are commercial banks often reluctant to grant large unsecured loans to newly established start-up businesses?","options":{"A":"Because start-ups have no trading track record of profitability, high failure rates, and little or no non-current asset collateral to secure the debt","B":"Because banks are legally forbidden from lending money to sole traders or small companies","C":"Because start-ups never need working capital","D":"Because banks prefer to invest only in loss-making charities"},"correctOption":"A","correctAnswer":"Because start-ups have no trading track record of profitability, high failure rates, and little or no non-current asset collateral to secure the debt","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because banks are risk-averse lenders that assess default risk using historical accounts and asset security.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because banks can lend to small businesses if presented with a strong business plan and collateral.","C":"Incorrect because start-ups heavily need working capital.","D":"Incorrect because commercial banks lend to viable, creditworthy enterprises."}}},{"id":"P1_U5_MCQ_764","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_764","question":"If a limited company fails and goes into liquidation, how are 'debenture holders' treated compared with 'ordinary shareholders'?","options":{"A":"Ordinary shareholders are repaid first, while debenture holders receive nothing","B":"Debenture holders are creditors and must be repaid before ordinary shareholders receive any remaining funds","C":"Both debenture holders and ordinary shareholders are personally liable for the company's unpaid supplier bills","D":"Debenture holders take over the personal houses of the ordinary shareholders"},"correctOption":"B","correctAnswer":"Debenture holders are creditors and must be repaid before ordinary shareholders receive any remaining funds","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because debt creditors (including debenture holders) hold priority legal claims over company assets ahead of equity shareholders.","distractor_reasons":{"A":"Incorrect because ordinary shareholders are residual owners paid last in a liquidation.","B":"Correct selection.","C":"Incorrect because limited liability protects both from personal liability for corporate debts.","D":"Incorrect because separate legal personality shields shareholders' personal assets."}}},{"id":"P1_U5_MCQ_765","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_765","question":"Besides providing immediate cash from unpaid invoices, what administrative benefit can 'debt factoring' provide to a growing business?","options":{"A":"It eliminates the need to pay corporation tax on sales","B":"It guarantees that raw material prices will never rise","C":"The factoring company often takes over managing the sales ledger and chasing credit customers for payment, saving internal administrative time","D":"It converts short-term trade payables into permanent share capital"},"correctOption":"C","correctAnswer":"The factoring company often takes over managing the sales ledger and chasing credit customers for payment, saving internal administrative time","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because specialist factors administer credit collection and ledger management in addition to advancing cash.","distractor_reasons":{"A":"Incorrect because factoring does not affect corporation tax rules.","B":"Incorrect because factoring deals with customer receivables, not raw material prices.","C":"Correct selection.","D":"Incorrect because factoring converts trade receivables into cash, not payables into equity."}}},{"id":"P1_U5_MCQ_766","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_766","question":"Why do governments frequently offer 'grants or subsidies' to businesses willing to locate factories in areas of high unemployment?","options":{"A":"So the government can seize 100% ownership of the business after one year","B":"Because businesses in high-unemployment areas are exempt from paying staff wages","C":"To increase the interest rates paid by small businesses","D":"To incentivize job creation, regional economic regeneration, and inward investment without burdening the business with loan repayments"},"correctOption":"D","correctAnswer":"To incentivize job creation, regional economic regeneration, and inward investment without burdening the business with loan repayments","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because non-repayable grants reduce initial capital costs and encourage firms to create employment in targeted regions.","distractor_reasons":{"A":"Incorrect because grants do not transfer private ownership to the state.","B":"Incorrect because businesses still pay wages to their workers.","C":"Incorrect because grants are interest-free, non-repayable funds.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_767","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_767","question":"Why do many 'microfinance' institutions lend to small groups of local entrepreneurs (group lending) rather than requiring physical property collateral?","options":{"A":"Because peer support and mutual accountability within the group encourage high repayment rates among borrowers who lack traditional collateral","B":"Because microfinance institutions are legally banned from lending to individuals","C":"Because group lending eliminates all interest charges","D":"Because group borrowers are required to list their businesses on a stock exchange"},"correctOption":"A","correctAnswer":"Because peer support and mutual accountability within the group encourage high repayment rates among borrowers who lack traditional collateral","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because social collateral and peer encouragement substitute for physical assets, enabling low-income entrepreneurs to access start-up credit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because microfinance providers lend to both individuals and solidarity groups.","C":"Incorrect because microfinance loans still charge interest to remain financially sustainable.","D":"Incorrect because microfinance serves tiny informal or micro-enterprises."}}},{"id":"P1_U5_MCQ_768","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_768","question":"What role does an online 'crowdfunding platform' play when an entrepreneur launches a funding campaign?","options":{"A":"It lends its own bank reserves as a 25-year commercial mortgage","B":"It acts as an internet intermediary connecting the project creator with thousands of potential backers, usually charging a percentage fee on funds successfully raised","C":"It guarantees that every campaign will reach 100% of its funding goal","D":"It buys all unsold inventory from the business at full retail price"},"correctOption":"B","correctAnswer":"It acts as an internet intermediary connecting the project creator with thousands of potential backers, usually charging a percentage fee on funds successfully raised","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because crowdfunding websites host the pitch, process small online pledges, and earn a commission fee when targets are met.","distractor_reasons":{"A":"Incorrect because crowdfunding platforms connect public backers rather than issuing bank mortgages.","B":"Correct selection.","C":"Incorrect because many crowdfunding pitches fail to reach their target funding goal.","D":"Incorrect because platforms do not purchase leftover inventory."}}},{"id":"P1_U5_MCQ_769","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_769","question":"Why is a 'bank overdraft' classified as a short-term source of finance even if a business uses it periodically over several years?","options":{"A":"Because overdrafts are an internal source of finance","B":"Because overdrafts never incur any interest charges","C":"Because the overdraft facility is reviewed annually and the bank retains the legal right to demand full repayment at very short notice","D":"Because overdrafts can only be used to buy freehold buildings"},"correctOption":"C","correctAnswer":"Because the overdraft facility is reviewed annually and the bank retains the legal right to demand full repayment at very short notice","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because an overdraft is repayable on demand and intended to fluctuate with short-term working capital needs rather than provide permanent capital.","distractor_reasons":{"A":"Incorrect because an overdraft is borrowed from an outside bank (external finance).","B":"Incorrect because overdrafts carry relatively high daily interest rates.","C":"Correct selection.","D":"Incorrect because overdrafts are meant for short-term running costs, not long-term buildings."}}},{"id":"P1_U5_MCQ_770","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_770","question":"Why is 'trade credit' frequently described as an 'interest-free' short-term source of finance for a business buyer?","options":{"A":"Because suppliers never expect the buyer to pay the invoice at all","B":"Because commercial banks pay the supplier on the buyer's behalf","C":"Because trade credit is recorded as shareholders' equity","D":"Because suppliers normally do not charge interest during the agreed credit window (e.g., 30 days), though failing to pay on time can incur late fees or loss of discounts"},"correctOption":"D","correctAnswer":"Because suppliers normally do not charge interest during the agreed credit window (e.g., 30 days), though failing to pay on time can incur late fees or loss of discounts","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because delayed payment within agreed credit terms provides temporary working capital without explicit interest charges.","distractor_reasons":{"A":"Incorrect because the invoice must still be paid in full by the due date.","B":"Incorrect because the buyer pays the supplier directly at the end of the credit period.","C":"Incorrect because unpaid supplier invoices are current liabilities (trade payables).","D":"Correct selection."}}},{"id":"P1_U5_MCQ_771","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_771","question":"Why does 'leasing' often reduce unexpected repair costs for a business using delivery vehicles or photocopiers?","options":{"A":"Because maintenance, servicing, and repairs are typically included in the lease contract and handled by the leasing company","B":"Because leased vehicles and photocopiers never break down","C":"Because the business owns the equipment outright from Day 1","D":"Because the government pays all repair bills for leased assets"},"correctOption":"A","correctAnswer":"Because maintenance, servicing, and repairs are typically included in the lease contract and handled by the leasing company","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the lessor retains ownership and usually bundles routine servicing and repairs into the fixed rental fee.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because leased equipment still requires regular maintenance.","C":"Incorrect because the leasing company retains legal ownership.","D":"Incorrect because leasing is a private commercial contract."}}},{"id":"P1_U5_MCQ_772","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_772","question":"What happens if a business defaults on payments partway through a 'hire purchase' agreement?","options":{"A":"The business automatically keeps the asset free of charge","B":"The finance company retains legal ownership until the final instalment is paid and can repossess the asset","C":"The remaining instalments are converted into ordinary share capital","D":"The supplier must refund all previous instalments with interest"},"correctOption":"B","correctAnswer":"The finance company retains legal ownership until the final instalment is paid and can repossess the asset","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because under hire purchase, legal title only passes upon completion of all contracted payments.","distractor_reasons":{"A":"Incorrect because legal ownership has not yet transferred to the buyer.","B":"Correct selection.","C":"Incorrect because hire purchase is a debt contract, not an equity arrangement.","D":"Incorrect because defaulted agreements allow repossession rather than refunds."}}},{"id":"P1_U5_MCQ_773","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_773","question":"When choosing between 'debt finance' (such as a bank loan) and 'equity finance' (such as issuing shares), what key advantage does equity finance offer during an economic recession?","options":{"A":"Equity finance never dilutes existing owners' voting control","B":"Equity finance requires zero administrative or legal setup costs","C":"Ordinary dividends do not have to be paid when profits fall or losses occur, whereas loan interest remains a rigid legal obligation regardless of profit","D":"Equity finance must be repaid to shareholders within six months"},"correctOption":"C","correctAnswer":"Ordinary dividends do not have to be paid when profits fall or losses occur, whereas loan interest remains a rigid legal obligation regardless of profit","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because discretionary dividends give companies breathing room during downturns, whereas fixed debt interest can trigger insolvency.","distractor_reasons":{"A":"Incorrect because issuing new shares to outside investors does dilute existing ownership.","B":"Incorrect because issuing shares involves significant legal and administrative costs.","C":"Correct selection.","D":"Incorrect because share capital is permanent and has no repayment date."}}},{"id":"P1_U5_MCQ_774","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_774","question":"Why might the founder of a family-owned private limited company (Ltd) choose a 'bank loan' rather than selling new shares to external venture capitalists?","options":{"A":"Because bank loans never charge any interest","B":"Because private limited companies are legally forbidden from issuing shares","C":"Because bank loans increase the company's retained profit","D":"To retain 100% ownership and decision-making control within the family without outside shareholder interference"},"correctOption":"D","correctAnswer":"To retain 100% ownership and decision-making control within the family without outside shareholder interference","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because preserving control is a decisive factor in finance selection; loans add debt obligations but leave ownership intact.","distractor_reasons":{"A":"Incorrect because bank loans always incur interest charges.","B":"Incorrect because Ltds can issue shares privately if existing shareholders agree.","C":"Incorrect because loan interest reduces profit rather than increasing retained profit.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_775","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_775","question":"Which combination of factors best guides a manager when selecting the most appropriate source of finance for a specific business need?","options":{"A":"Purpose and time period of the finance, amount required, legal structure of the business, cost (interest/fees), existing gearing/risk, and impact on ownership control","B":"Only the color of the company's logo and the number of retail shops","C":"Only the personal preferences of raw-material suppliers","D":"Only the current ratio from five years ago"},"correctOption":"A","correctAnswer":"Purpose and time period of the finance, amount required, legal structure of the business, cost (interest/fees), existing gearing/risk, and impact on ownership control","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sound financial decision-making evaluates duration matching, scale, legal eligibility, cost, risk, and control.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because branding aesthetics do not determine financing suitability.","C":"Incorrect because suppliers do not choose how a business finances its investments.","D":"Incorrect because historical liquidity alone ignores legal structure, duration, and control."}}},{"id":"P1_U5_MCQ_776","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_776","question":"Why can a business NOT pay employee wages or supplier bills using 'retained profit' unless it also holds sufficient 'cash'?","options":{"A":"Because retained profit is an accounting equity reserve recorded on paper rather than spendable physical money in a bank account","B":"Because retained profit is legally locked in a government vault for ten years","C":"Because employees are legally forbidden from accepting bank transfers","D":"Because retained profit is classified as a current liability"},"correctOption":"A","correctAnswer":"Because retained profit is an accounting equity reserve recorded on paper rather than spendable physical money in a bank account","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because retained profit may already be tied up in machinery, inventories, or unpaid customer receivables rather than sitting as liquid cash.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because retained profit is an accounting figure, not locked physical money.","C":"Incorrect because bank transfers are standard cash payments.","D":"Incorrect because retained profit is owners' equity."}}},{"id":"P1_U5_MCQ_777","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_777","question":"Why do 'total cash inflows' in a given month rarely equal 'sales revenue' earned during that same month?","options":{"A":"Because sales revenue is never recorded in any financial document","B":"Because some sales are made on credit (so cash arrives in later months), while non-sales cash inflows (like bank loans or asset sales) may also enter the bank","C":"Because cash sales are excluded from sales revenue","D":"Because sales revenue is always paid to suppliers"},"correctOption":"B","correctAnswer":"Because some sales are made on credit (so cash arrives in later months), while non-sales cash inflows (like bank loans or asset sales) may also enter the bank","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because timing differences from trade credit and non-operating financing inflows separate monthly cash receipts from monthly revenue.","distractor_reasons":{"A":"Incorrect because sales revenue is the top line of the statement of profit or loss.","B":"Correct selection.","C":"Incorrect because cash sales are included in both revenue and cash inflows.","D":"Incorrect because sales revenue comes from customers."}}},{"id":"P1_U5_MCQ_778","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_778","question":"Why do 'total cash outflows' in a given month often differ significantly from 'total expenses' on the statement of profit or loss?","options":{"A":"Because employee wages are excluded from cash outflows","B":"Because rent and electricity never require cash payments","C":"Because cash outflows include capital asset purchases, loan principal repayments, and dividends (which are not income statement expenses), while excluding non-cash depreciation","D":"Because expenses on the income statement are always zero"},"correctOption":"C","correctAnswer":"Because cash outflows include capital asset purchases, loan principal repayments, and dividends (which are not income statement expenses), while excluding non-cash depreciation","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because cash flow tracks all cash leaving the bank, whereas the income statement includes only period operating expenses (including non-cash depreciation).","distractor_reasons":{"A":"Incorrect because wages paid are a major cash outflow.","B":"Incorrect because rent and utility bills are regular cash outflows.","C":"Correct selection.","D":"Incorrect because all businesses incur operating expenses."}}},{"id":"P1_U5_MCQ_779","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_779","question":"How are 'dividends paid to shareholders' treated on a company's cash flow forecast?","options":{"A":"They are omitted because dividends are non-cash items","B":"They are recorded as a cash inflow from investors","C":"They are added to the opening cash balance","D":"They are recorded as a cash outflow in the month the cash payment leaves the company's bank account"},"correctOption":"D","correctAnswer":"They are recorded as a cash outflow in the month the cash payment leaves the company's bank account","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because paying cash dividends reduces the company's bank balance in the month paid, even though dividends are not an operating expense on the income statement.","distractor_reasons":{"A":"Incorrect because cash dividends involve actual money leaving the bank.","B":"Incorrect because dividends are paid *out* to shareholders, not received from them.","C":"Incorrect because outflows reduce rather than increase cash.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_780","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_780","question":"If a credit customer goes bankrupt and defaults on an invoice (a 'bad debt'), how does this affect a cash flow forecast?","options":{"A":"The expected future cash inflow from that customer must be removed from the forecast because no cash will ever be received","B":"The unpaid invoice is recorded as an extra cash inflow","C":"The unpaid invoice is recorded as a non-current asset","D":"The unpaid invoice increases the opening cash balance"},"correctOption":"A","correctAnswer":"The expected future cash inflow from that customer must be removed from the forecast because no cash will ever be received","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a bad debt means the anticipated receipt from trade receivables fails to materialize, lowering projected cash inflows.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because default prevents cash from entering the bank.","C":"Incorrect because an irrecoverable debt is written off, not turned into a non-current asset.","D":"Incorrect because an uncollected debt does not increase cash."}}},{"id":"P1_U5_MCQ_781","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_781","question":"What does a 'net cash flow of zero' in a particular month indicate?","options":{"A":"The business had zero sales and zero expenses during the month","B":"Total cash inflows equaled total cash outflows during that month, leaving the closing cash balance identical to the opening cash balance","C":"The business's bank balance has fallen to zero","D":"The business has gone into liquidation"},"correctOption":"B","correctAnswer":"Total cash inflows equaled total cash outflows during that month, leaving the closing cash balance identical to the opening cash balance","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Net cash flow = Total cash inflows - Total cash outflows; when inflows match outflows, the cash balance neither rises nor falls.","distractor_reasons":{"A":"Incorrect because inflows and outflows can both be large yet equal to each other.","B":"Correct selection.","C":"Incorrect because if the opening balance was positive, the closing balance remains at that same positive amount.","D":"Incorrect because breaking even on monthly cash flow is stable, not liquidation."}}},{"id":"P1_U5_MCQ_782","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_782","question":"If a business begins a month with a positive opening cash balance and has a negative net cash flow that is *smaller* than its opening balance, what will its closing cash balance be?","options":{"A":"Negative (an overdraft)","B":"Zero","C":"Still positive, though lower than the opening balance","D":"Higher than the opening balance"},"correctOption":"C","correctAnswer":"Still positive, though lower than the opening balance","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the existing cash cushion absorbs the monthly cash shortfall without pushing the bank account into overdraft.","distractor_reasons":{"A":"Incorrect because the opening cash buffer exceeds the monthly deficit.","B":"Incorrect because the closing balance only hits zero if the deficit exactly equals the opening balance.","C":"Correct selection.","D":"Incorrect because a negative net cash flow reduces the cash balance."}}},{"id":"P1_U5_MCQ_783","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_783","question":"On a 12-month cash flow forecast running from January to December, how is the 'overall net cash flow for the entire year' verified?","options":{"A":"By adding January's opening balance to December's closing balance","B":"By multiplying gross profit by 12","C":"By subtracting current liabilities from current assets","D":"By subtracting January's opening cash balance from December's closing cash balance (which also equals total annual inflows minus total annual outflows)"},"correctOption":"D","correctAnswer":"By subtracting January's opening cash balance from December's closing cash balance (which also equals total annual inflows minus total annual outflows)","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the cumulative change in cash from the start of January to the end of December reflects total annual inflows minus total annual outflows.","distractor_reasons":{"A":"Incorrect because adding opening and closing balances double-counts the starting cash.","B":"Incorrect because gross profit is an income statement figure, not cash flow.","C":"Incorrect because current assets minus current liabilities is working capital.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_784","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_784","question":"How does preparing a realistic cash flow forecast help a new start-up avoid 'under-capitalization'?","options":{"A":"It reveals the total initial cash needed to fund set-up costs and cover negative monthly net cash flows until sales receipts become self-sustaining","B":"It forces suppliers to provide free raw materials for the first year","C":"It guarantees that the start-up will earn a profit in Month 1","D":"It eliminates all fixed overhead costs"},"correctOption":"A","correctAnswer":"It reveals the total initial cash needed to fund set-up costs and cover negative monthly net cash flows until sales receipts become self-sustaining","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because under-capitalization—starting with too little cash buffer—is a leading cause of start-up failure that forecasting directly prevents.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because suppliers charge normal commercial prices.","C":"Incorrect because most start-ups experience losses or cash deficits in early months.","D":"Incorrect because rent, insurance, and utilities still apply."}}},{"id":"P1_U5_MCQ_785","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_785","question":"How can a cash flow forecast be used by senior managers as a tool for 'controlling departmental spending'?","options":{"A":"By banning all departments from buying any raw materials","B":"By setting monthly cash outflow limits (budgets) for each area and investigating whenever actual outflows exceed forecast outflows","C":"By converting all departmental expenses into share capital","D":"By eliminating the need for a statement of financial position"},"correctOption":"B","correctAnswer":"By setting monthly cash outflow limits (budgets) for each area and investigating whenever actual outflows exceed forecast outflows","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because forecast cash outflows serve as spending benchmarks, enabling variance control when costs threaten to overrun.","distractor_reasons":{"A":"Incorrect because production requires purchasing raw materials.","B":"Correct selection.","C":"Incorrect because expenses cannot be converted into share capital.","D":"Incorrect because businesses still prepare annual statements of financial position."}}},{"id":"P1_U5_MCQ_786","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_786","question":"Why do 'potential investors' (such as business angels or venture capitalists) examine a start-up's cash flow forecast before investing equity capital?","options":{"A":"To check the start-up's historical corporation tax payments over the last ten years","B":"To calculate the exact depreciation rate of office stationery","C":"To see how quickly the business will burn through invested cash ('cash burn rate') and when positive net cash flows will make the venture self-sustaining","D":"To set the government's minimum wage rate"},"correctOption":"C","correctAnswer":"To see how quickly the business will burn through invested cash ('cash burn rate') and when positive net cash flows will make the venture self-sustaining","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because investors want to ensure their equity injection is large enough to reach positive cash flow without running dry midway.","distractor_reasons":{"A":"Incorrect because a new start-up has no ten-year tax history.","B":"Incorrect because stationery is an expense, not a depreciable non-current asset.","C":"Correct selection.","D":"Incorrect because governments set minimum wage legislation."}}},{"id":"P1_U5_MCQ_787","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_787","question":"Which statement correctly explains why 'solvency (cash liquidity)' is even more urgent for short-term business survival than 'profitability'?","options":{"A":"Because profitable businesses are forbidden from holding bank accounts","B":"Because losses are never recorded on financial statements","C":"Because cash inflows always equal sales revenue","D":"Because a business can survive temporary accounting losses if it has enough cash to pay bills, whereas running out of cash causes immediate insolvency and closure even if orders are profitable"},"correctOption":"D","correctAnswer":"Because a business can survive temporary accounting losses if it has enough cash to pay bills, whereas running out of cash causes immediate insolvency and closure even if orders are profitable","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because creditors demand cash payment on due dates; without liquidity, operations stop immediately regardless of paper profits.","distractor_reasons":{"A":"Incorrect because all businesses use bank accounts.","B":"Incorrect because losses are fully reported on the statement of profit or loss.","C":"Incorrect because credit terms separate cash inflows from revenue.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_788","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_788","question":"When a sole trader withdraws cash from the business bank account for personal living expenses ('drawings'), how does this affect 'cash flow' versus 'profit'?","options":{"A":"It creates a cash outflow that reduces the business's cash balance, but it is NOT deducted as a business expense when calculating profit","B":"It increases both cash flow and gross profit","C":"It reduces operating profit on the statement of profit or loss, but has zero effect on cash flow","D":"It is recorded as a non-current asset on the statement of financial position"},"correctOption":"A","correctAnswer":"It creates a cash outflow that reduces the business's cash balance, but it is NOT deducted as a business expense when calculating profit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because owner drawings take actual cash out of the business bank account while representing an owner equity withdrawal rather than a trading cost.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because drawings drain cash and do not generate gross profit.","C":"Incorrect because drawings reduce cash and equity without reducing trading profit.","D":"Incorrect because drawings reduce owner's capital rather than creating an asset."}}},{"id":"P1_U5_MCQ_789","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_789","question":"How does offering customers longer credit terms (e.g., increasing credit from 30 days to 90 days) to win more orders create a 'cash flow trap'?","options":{"A":"It reduces sales revenue on the statement of profit or loss immediately","B":"Higher sales require immediate cash outflows for extra materials and wages, while cash inflows from those new customers are delayed for three months, worsening short-term cash deficits","C":"It forces suppliers to wait 180 days for payment automatically","D":"It converts all trade receivables into non-current liabilities"},"correctOption":"B","correctAnswer":"Higher sales require immediate cash outflows for extra materials and wages, while cash inflows from those new customers are delayed for three months, worsening short-term cash deficits","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because expanding credit sales stretches the working capital cycle, draining cash upfront while delaying receipts.","distractor_reasons":{"A":"Incorrect because winning extra orders increases reported sales revenue.","B":"Correct selection.","C":"Incorrect because suppliers do not automatically extend their own credit terms when a business gives longer credit to buyers.","D":"Incorrect because unpaid customer invoices remain current assets (trade receivables)."}}},{"id":"P1_U5_MCQ_790","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_790","question":"What is a key drawback of offering a 'prompt-payment cash discount' to credit customers to accelerate cash inflows?","options":{"A":"It delays cash inflows into the following financial year","B":"It increases the business's non-current liabilities","C":"While cash enters the bank faster, giving a discount reduces the net revenue collected per invoice and lowers overall profit margin","D":"It forces the business to pay higher corporation tax on uncollected invoices"},"correctOption":"C","correctAnswer":"While cash enters the bank faster, giving a discount reduces the net revenue collected per invoice and lowers overall profit margin","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because sacrificing a percentage of invoice value trades slightly lower profitability for improved short-term cash liquidity.","distractor_reasons":{"A":"Incorrect because prompt-payment discounts bring cash inflows *forward*.","B":"Incorrect because discounts affect cash and profit, not long-term debt.","C":"Correct selection.","D":"Incorrect because lower revenue reduces rather than increases taxable profit."}}},{"id":"P1_U5_MCQ_791","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_791","question":"Why can 'arranging a larger bank overdraft limit' prevent a forecast cash crisis even though it does NOT count as a trading cash inflow?","options":{"A":"Because an overdraft eliminates all wage and rent expenses","B":"Because an overdraft increases gross profit on the income statement","C":"Because an overdraft converts trade payables into share capital","D":"Because it gives the business legal permission to spend beyond a zero bank balance up to the agreed limit so essential bills can still be paid during temporary deficits"},"correctOption":"D","correctAnswer":"Because it gives the business legal permission to spend beyond a zero bank balance up to the agreed limit so essential bills can still be paid during temporary deficits","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because an overdraft facility covers negative closing cash balances smoothly until future customer inflows restore a positive balance.","distractor_reasons":{"A":"Incorrect because wages and rent still have to be paid.","B":"Incorrect because overdrafts are financing facilities and do not add to gross profit.","C":"Incorrect because overdrafts are short-term debt, not equity.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_792","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_792","question":"What is a major risk of cutting 'raw material purchases' sharply in order to reduce short-term cash outflows?","options":{"A":"Production may halt due to stockouts, causing missed customer orders, lost future cash inflows, and damaged customer loyalty","B":"Warehouse rent and insurance costs will double immediately","C":"The business's current liabilities will convert into non-current assets","D":"The business will be forced to pay higher dividends"},"correctOption":"A","correctAnswer":"Production may halt due to stockouts, causing missed customer orders, lost future cash inflows, and damaged customer loyalty","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because starving operations of essential inputs protects cash briefly at the cost of halting sales and future receipts.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because holding smaller stock lowers storage costs rather than doubling them.","C":"Incorrect because inventory policies do not alter liability or asset classifications.","D":"Incorrect because dividends are discretionary equity payouts."}}},{"id":"P1_U5_MCQ_793","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_793","question":"Why might 'cancelling or postponing planned marketing expenditure' to save cash in the short term backfire later in the year?","options":{"A":"Because marketing expenses are classified as non-current assets","B":"Because lower promotion can reduce future customer demand and sales orders, causing cash inflows to fall in subsequent months","C":"Because cancelling marketing doubles the cost of sales per unit","D":"Because banks cancel overdrafts whenever marketing budgets are cut"},"correctOption":"B","correctAnswer":"Because lower promotion can reduce future customer demand and sales orders, causing cash inflows to fall in subsequent months","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because reducing customer awareness today shrinks the pipeline of future sales receipts.","distractor_reasons":{"A":"Incorrect because marketing is revenue expenditure (an overhead expense).","B":"Correct selection.","C":"Incorrect because marketing is an indirect overhead and does not change direct unit cost of sales.","D":"Incorrect because banks do not automatically cancel overdrafts over marketing changes."}}},{"id":"P1_U5_MCQ_794","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_794","question":"How does 'converting short-term borrowing (such as an overdraft) into a long-term bank loan' improve a business's monthly cash flow stability?","options":{"A":"It eliminates all interest charges permanently","B":"It increases monthly sales revenue immediately","C":"It removes the risk of sudden full repayment on demand and spreads principal repayments into smaller, predictable instalments over several years","D":"It eliminates all current assets from the balance sheet"},"correctOption":"C","correctAnswer":"It removes the risk of sudden full repayment on demand and spreads principal repayments into smaller, predictable instalments over several years","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because restructuring short-term debt into long-term debt relieves immediate liquidity pressure and improves working capital.","distractor_reasons":{"A":"Incorrect because long-term loans still carry interest charges.","B":"Incorrect because debt restructuring does not directly change sales revenue.","C":"Correct selection.","D":"Incorrect because restructuring debt improves cash stability rather than eliminating current assets."}}},{"id":"P1_U5_MCQ_795","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_795","question":"Why are 'cash flow forecasts' for brand-new start-up businesses typically less accurate than forecasts prepared by long-established firms?","options":{"A":"Because start-ups are legally forbidden from recording cash outflows","B":"Because established firms never experience unexpected changes in customer demand","C":"Because start-ups do not have bank accounts","D":"Because start-ups lack historical sales and payment data from previous years, forcing entrepreneurs to rely on market research estimates"},"correctOption":"D","correctAnswer":"Because start-ups lack historical sales and payment data from previous years, forcing entrepreneurs to rely on market research estimates","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because established businesses can base projections on proven past seasonal patterns and customer payment behavior, whereas start-ups must estimate from scratch.","distractor_reasons":{"A":"Incorrect because start-ups must include all expected cash outflows.","B":"Incorrect because established firms also face market shocks, though they have historical baselines.","C":"Incorrect because start-ups operate business bank accounts.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_796","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_796","question":"How can a sudden rise in 'raw material prices' or 'market interest rates' affect a cash flow forecast prepared six months earlier?","options":{"A":"Actual cash outflows will be higher than originally forecast, reducing net cash flow and potentially turning projected positive balances into unexpected deficits","B":"Actual cash inflows from customers will automatically double","C":"The opening cash balance from six months ago will change retroactively","D":"The business will become exempt from paying suppliers"},"correctOption":"A","correctAnswer":"Actual cash outflows will be higher than originally forecast, reducing net cash flow and potentially turning projected positive balances into unexpected deficits","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because external cost shocks invalidate earlier assumptions, demonstrating why forecasts must be regularly revised.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because higher input or interest costs do not double customer receipts.","C":"Incorrect because past opening balances are historical facts.","D":"Incorrect because supplier invoices remain legally payable."}}},{"id":"P1_U5_MCQ_797","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_797","question":"If a major credit customer unexpectedly delays paying a large invoice by two months, how does this affect a business's cash flow forecast?","options":{"A":"It has no effect because credit sales are never shown on a cash flow forecast","B":"It reduces actual cash inflows in the originally expected month, creating a temporary cash shortfall until the late payment finally arrives","C":"It permanently reduces the business's non-current assets","D":"It immediately increases the business's retained profit"},"correctOption":"B","correctAnswer":"It reduces actual cash inflows in the originally expected month, creating a temporary cash shortfall until the late payment finally arrives","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because timing delays in collecting trade receivables directly disrupt projected monthly cash balances.","distractor_reasons":{"A":"Incorrect because expected receipts from credit customers are a major cash inflow line.","B":"Correct selection.","C":"Incorrect because late customer payments affect current assets (receivables and cash), not non-current assets.","D":"Incorrect because late payments do not increase profit."}}},{"id":"P1_U5_MCQ_798","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_798","question":"What is the key difference between a 'cash flow forecast' and a 'statement of profit or loss' regarding the time period they look at?","options":{"A":"A cash flow forecast records only past transactions, whereas a statement of profit or loss predicts future profits","B":"Both documents record only transactions from ten years ago","C":"A cash flow forecast is a forward-looking estimate of future cash movements, whereas a statement of profit or loss is a historical record of revenue, costs, and profit already earned","D":"A cash flow forecast covers one single day, whereas a statement of profit or loss covers one single hour"},"correctOption":"C","correctAnswer":"A cash flow forecast is a forward-looking estimate of future cash movements, whereas a statement of profit or loss is a historical record of revenue, costs, and profit already earned","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because cash flow forecasts plan ahead for liquidity management, while published income statements report completed past trading periods.","distractor_reasons":{"A":"Incorrect because this reverses forward-looking forecasts and historical financial statements.","B":"Incorrect because forecasts look forward and annual accounts cover the most recent year.","C":"Correct selection.","D":"Incorrect because forecasts typically span 6–12 months and income statements cover an accounting period (usually 12 months)."}}},{"id":"P1_U5_MCQ_799","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_799","question":"Why does a cash flow forecast show 'only cash movements' rather than showing the total value of assets and liabilities owned by the business?","options":{"A":"Because assets and liabilities are illegal to record in limited companies","B":"Because businesses never own any assets or owe any liabilities","C":"Because cash flow forecasts are prepared only by government tax collectors","D":"Because tracking liquidity requires isolating actual money entering and leaving the bank, whereas assets, liabilities, and equity are reported separately on the statement of financial position"},"correctOption":"D","correctAnswer":"Because tracking liquidity requires isolating actual money entering and leaving the bank, whereas assets, liabilities, and equity are reported separately on the statement of financial position","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because each financial document serves a distinct analytical purpose: liquidity timing (cash flow forecast), trading profitability (income statement), and net worth/solvency (statement of financial position).","distractor_reasons":{"A":"Incorrect because assets and liabilities are always recorded on the statement of financial position.","B":"Incorrect because every operating business holds assets and liabilities.","C":"Incorrect because managers and entrepreneurs prepare cash flow forecasts.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_800","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_800","question":"Which summary statement best captures why 'working capital management' is central to cash flow forecasting?","options":{"A":"Because most short-term cash inflows and outflows come from converting inventories into trade receivables and collecting cash while paying trade payables and running expenses on time","B":"Because working capital consists entirely of freehold land and 25-year mortgages","C":"Because working capital guarantees that a business will never have any overhead costs","D":"Because working capital is calculated by subtracting gross profit from sales revenue"},"correctOption":"A","correctAnswer":"Because most short-term cash inflows and outflows come from converting inventories into trade receivables and collecting cash while paying trade payables and running expenses on time","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because managing inventory levels, customer credit periods, and supplier credit periods directly controls the timing of operating cash inflows and outflows.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because land and mortgages are non-current items.","C":"Incorrect because working capital funds rather than eliminates overhead costs.","D":"Incorrect because sales revenue minus gross profit equals cost of sales."}}},{"id":"P1_U5_MCQ_801","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_801","question":"Why is profit described as a 'reward for enterprise and risk-taking' in a private sector economy?","options":{"A":"Because entrepreneurs invest their own capital, time, and effort without any guarantee of success, so the prospect of earning profit compensates them for bearing business risk","B":"Because governments pay a guaranteed salary to every entrepreneur who starts a shop","C":"Because entrepreneurs never risk losing their invested money if a business fails","D":"Because profit is distributed equally to all customers at the end of the year"},"correctOption":"A","correctAnswer":"Because entrepreneurs invest their own capital, time, and effort without any guarantee of success, so the prospect of earning profit compensates them for bearing business risk","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because unlike salaried employees or secured lenders, owners take residual financial risk and require profit returns as an incentive.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because private entrepreneurs earn profit only if revenue exceeds costs.","C":"Incorrect because owners lose their invested capital if the business fails.","D":"Incorrect because profits belong to the business owners/shareholders, not customers."}}},{"id":"P1_U5_MCQ_802","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_802","question":"How does earning consistent profit improve a company's ability to raise 'external finance' from banks and shareholders?","options":{"A":"It exempts the company from providing financial statements to lenders","B":"Strong profitability demonstrates financial viability, reassuring banks that loan interest can be paid and attracting equity investors seeking dividends and share growth","C":"It forces banks to lend money at a 0% interest rate","D":"It eliminates the need for working capital"},"correctOption":"B","correctAnswer":"Strong profitability demonstrates financial viability, reassuring banks that loan interest can be paid and attracting equity investors seeking dividends and share growth","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because profitable businesses represent lower credit risk to lenders and higher return potential to investors.","distractor_reasons":{"A":"Incorrect because lenders still require financial statements.","B":"Correct selection.","C":"Incorrect because banks always charge interest based on risk and market rates.","D":"Incorrect because expanding profitable firms still need working capital."}}},{"id":"P1_U5_MCQ_803","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_803","question":"Why do 'social enterprises' aim to generate a financial profit even though their primary goal is achieving social or environmental objectives?","options":{"A":"So they can distribute maximum cash dividends to stock-market speculators","B":"Because social enterprises are fined by tax authorities if they help the community","C":"So they can remain financially self-sustaining without depending solely on charity donations, reinvesting profits back into their social mission","D":"Because social enterprises are forbidden from charging customers for goods or services"},"correctOption":"C","correctAnswer":"So they can remain financially self-sustaining without depending solely on charity donations, reinvesting profits back into their social mission","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because social enterprises use commercial trading surpluses to fund ongoing community or environmental programs independently.","distractor_reasons":{"A":"Incorrect because social enterprises reinvest surpluses into their mission rather than maximizing private shareholder payouts.","B":"Incorrect because social enterprises are encouraged rather than fined.","C":"Correct selection.","D":"Incorrect because social enterprises sell goods or services commercially to earn revenue."}}},{"id":"P1_U5_MCQ_804","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_804","question":"What does a 'net loss' (negative profit) on a statement of profit or loss signify?","options":{"A":"The business has zero cash in its bank account","B":"The business's current liabilities exceed its non-current assets","C":"The business has paid too much corporation tax","D":"Total costs (cost of sales plus overhead expenses) exceeded total sales revenue during the trading period"},"correctOption":"D","correctAnswer":"Total costs (cost of sales plus overhead expenses) exceeded total sales revenue during the trading period","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because when total costs are greater than total revenue over an accounting period, the business makes a trading loss.","distractor_reasons":{"A":"Incorrect because a loss-making business can still hold cash from loans, share issues, or prior balances.","B":"Incorrect because asset and liability positions appear on the statement of financial position.","C":"Incorrect because corporation tax is only charged when positive profit is earned.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_805","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_805","question":"How are 'sales returns' (faulty or unwanted goods returned by customers for a refund) treated when calculating 'net revenue' on a statement of profit or loss?","options":{"A":"They are subtracted from total gross sales revenue to show net sales revenue actually retained by the business","B":"They are added to sales revenue at the top of the statement","C":"They are classified as a non-current asset","D":"They are deducted after retained profit has been calculated"},"correctOption":"A","correctAnswer":"They are subtracted from total gross sales revenue to show net sales revenue actually retained by the business","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because returned goods reverse a sale, so deducting sales returns gives true net revenue.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because returns reduce rather than increase revenue.","C":"Incorrect because returned sales reduce revenue (and go back to inventory if resalable), not non-current assets.","D":"Incorrect because net revenue is determined at the very top of the income statement."}}},{"id":"P1_U5_MCQ_806","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_806","question":"In the cost of sales formula ('Opening inventory + Purchases - Closing inventory'), what does 'Purchases' refer to?","options":{"A":"Buying new delivery trucks, office computers, and freehold factory buildings","B":"Buying goods for resale (in retail) or raw materials for production (in manufacturing) during the accounting year","C":"Paying monthly electricity bills and administrative salaries","D":"Buying back shares from ordinary shareholders"},"correctOption":"B","correctAnswer":"Buying goods for resale (in retail) or raw materials for production (in manufacturing) during the accounting year","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because 'Purchases' in cost of sales strictly refers to inventory acquired for resale or direct manufacturing.","distractor_reasons":{"A":"Incorrect because trucks, computers, and buildings are non-current assets (capital expenditure).","B":"Correct selection.","C":"Incorrect because utilities and admin salaries are indirect overhead expenses.","D":"Incorrect because share buy-backs are equity financing transactions."}}},{"id":"P1_U5_MCQ_807","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_807","question":"If a business's 'closing inventory' at year-end is higher than its 'opening inventory' at the start of the year, what does this indicate about inventory movement during the year?","options":{"A":"The business sold more units than it bought/produced during the year","B":"The business had zero purchases during the year","C":"The business bought or produced more goods during the year than it sold, so unsold stock levels increased","D":"The business made a net loss for the year"},"correctOption":"C","correctAnswer":"The business bought or produced more goods during the year than it sold, so unsold stock levels increased","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because when additions to inventory (purchases/production) exceed units sold, ending inventory rises above opening inventory.","distractor_reasons":{"A":"Incorrect because selling more than bought/produced reduces closing inventory below opening inventory.","B":"Incorrect because with zero purchases and any sales, closing inventory would be lower than opening inventory.","C":"Correct selection.","D":"Incorrect because inventory changes do not determine whether the business made a profit or loss."}}},{"id":"P1_U5_MCQ_808","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_808","question":"Why is 'gross profit' calculated as a separate subtotal before deducting overhead expenses on a statement of profit or loss?","options":{"A":"Because gross profit is the exact amount of cash in the bank","B":"Because gross profit is used to calculate corporation tax directly","C":"Because overhead expenses are legally optional to report","D":"Because it allows managers to evaluate the core profitability of buying/making and selling products separately from indirect administrative and marketing overheads"},"correctOption":"D","correctAnswer":"Because it allows managers to evaluate the core profitability of buying/making and selling products separately from indirect administrative and marketing overheads","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because isolating gross profit helps managers see whether pricing and direct production costs are healthy before looking at fixed overheads.","distractor_reasons":{"A":"Incorrect because gross profit is a trading calculation, not bank cash.","B":"Incorrect because corporation tax is calculated on profit before tax (after overheads and interest).","C":"Incorrect because all overhead expenses must be deducted to find true profit.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_809","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_809","question":"Why do pure 'service businesses' (such as a law firm or consulting agency) often have little or no physical inventory in their 'cost of sales'?","options":{"A":"Because services are intangible activities delivered directly to clients rather than physical goods held in a warehouse, so most of their costs are staff salaries and office overheads","B":"Because service businesses are legally forbidden from preparing statements of profit or loss","C":"Because service businesses never earn any revenue","D":"Because service businesses record all salaries as non-current assets"},"correctOption":"A","correctAnswer":"Because services are intangible activities delivered directly to clients rather than physical goods held in a warehouse, so most of their costs are staff salaries and office overheads","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because service providers do not buy or manufacture physical stock for resale, resulting in minimal inventory-based cost of sales.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because service companies prepare full financial statements.","C":"Incorrect because service businesses earn fee revenue from clients.","D":"Incorrect because staff salaries are expenses, not non-current assets."}}},{"id":"P1_U5_MCQ_810","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_810","question":"Which cost is classified as an 'overhead expense' (indirect cost) rather than part of 'cost of sales'?","options":{"A":"Wholesale purchase cost of goods bought by a supermarket for resale","B":"Annual fire and theft insurance premiums for the company's head office","C":"Direct steel and rubber components used to assemble bicycles in a factory","D":"Piece-rate wages paid to factory workers directly assembling products"},"correctOption":"B","correctAnswer":"Annual fire and theft insurance premiums for the company's head office","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because head-office insurance is a fixed indirect running cost that does not vary directly with units produced or sold.","distractor_reasons":{"A":"Incorrect because goods bought for resale form a retailer's cost of sales.","B":"Correct selection.","C":"Incorrect because direct raw materials form part of cost of sales.","D":"Incorrect because direct production labor forms part of cost of sales."}}},{"id":"P1_U5_MCQ_811","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_811","question":"How is the annual 'depreciation charge' on factory or office equipment recorded on a statement of profit or loss?","options":{"A":"It is added to sales revenue at the top of the statement","B":"It is omitted completely because it does not involve cash","C":"It is deducted as an expense on the statement of profit or loss, reducing reported profit for the year","D":"It is deducted from dividends after profit after tax"},"correctOption":"C","correctAnswer":"It is deducted as an expense on the statement of profit or loss, reducing reported profit for the year","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because even though depreciation is non-cash, it represents the gradual consumption of a non-current asset's value during the year and must be expensed.","distractor_reasons":{"A":"Incorrect because depreciation is a cost, not revenue.","B":"Incorrect because omitting depreciation would overstate annual profit.","C":"Correct selection.","D":"Incorrect because depreciation is an operating expense deducted before profit before tax."}}},{"id":"P1_U5_MCQ_812","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_812","question":"Why is 'operating profit (profit before interest and tax)' often used when calculating Return on Capital Employed (ROCE)?","options":{"A":"Because operating profit measures the core trading profit generated by the business's assets before financing choices (interest) and government tax rates are applied","B":"Because operating profit is always identical to gross profit","C":"Because operating profit includes share capital raised during the year","D":"Because operating profit excludes all sales revenue"},"correctOption":"A","correctAnswer":"Because operating profit measures the core trading profit generated by the business's assets before financing choices (interest) and government tax rates are applied","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because using operating profit enables fair comparison of operational efficiency between companies with different debt-to-equity structures or tax jurisdictions.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because operating profit deducts overhead expenses from gross profit.","C":"Incorrect because share capital is equity on the balance sheet, not profit.","D":"Incorrect because operating profit starts from sales revenue."}}},{"id":"P1_U5_MCQ_813","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_813","question":"If a company earns 'interest received' from holding cash in an interest-bearing bank deposit account, how does this affect its statement of profit or loss?","options":{"A":"It is deducted from gross profit","B":"It is added to operating profit as finance income when calculating profit before tax","C":"It is classified as a current liability","D":"It increases cost of sales"},"correctOption":"B","correctAnswer":"It is added to operating profit as finance income when calculating profit before tax","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because interest earned on bank deposits is non-trading finance income that adds to profit before tax.","distractor_reasons":{"A":"Incorrect because interest received is income, not an expense.","B":"Correct selection.","C":"Incorrect because interest earned is income, not a debt owed.","D":"Incorrect because interest is unrelated to direct production or purchase costs."}}},{"id":"P1_U5_MCQ_814","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_814","question":"Why are 'dividends' placed *below* 'profit after tax' at the bottom of a limited company's statement of profit or loss rather than included among overhead expenses?","options":{"A":"Because dividends are paid to suppliers for raw materials","B":"Because dividends are a tax-deductible cost of production","C":"Because dividends are a distribution (appropriation) of earned profit to the company's owners, not a cost incurred in generating that profit","D":"Because dividends are owed to commercial banks"},"correctOption":"C","correctAnswer":"Because dividends are a distribution (appropriation) of earned profit to the company's owners, not a cost incurred in generating that profit","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because expenses are costs required to earn revenue, whereas dividends are how owners share the resulting after-tax profit.","distractor_reasons":{"A":"Incorrect because suppliers are paid for goods/services, whereas shareholders receive dividends.","B":"Incorrect because dividends are paid out of after-tax profit and are not tax-deductible expenses.","C":"Correct selection.","D":"Incorrect because banks receive contractual loan interest, not dividends."}}},{"id":"P1_U5_MCQ_815","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_815","question":"Can a limited company legally pay a dividend to shareholders in a year when it makes a small loss, provided it has large accumulated 'retained profit' reserves from previous years?","options":{"A":"No, because paying any dividend is always illegal unless current-year profit exceeds $10 million","B":"Yes, because dividends can legally be paid out of accumulated past retained profits if cash allows, though doing so reduces total equity reserves","C":"No, because past retained profits disappear at the end of every year","D":"Yes, because dividends are paid directly by the government during loss-making years"},"correctOption":"B","correctAnswer":"Yes, because dividends can legally be paid out of accumulated past retained profits if cash allows, though doing so reduces total equity reserves","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because accumulated retained profit reserves represent undistributed historical profits available for dividends, though directors must ensure sufficient cash liquidity.","distractor_reasons":{"A":"Incorrect because company law permits dividends from accumulated distributable profits.","B":"Correct selection.","C":"Incorrect because retained profits accumulate over time on the statement of financial position.","D":"Incorrect because governments do not pay private corporate dividends."}}},{"id":"P1_U5_MCQ_816","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_816","question":"If a company's 'profit after tax' is completely paid out as 'dividends' to shareholders, what is the 'retained profit' for that year?","options":{"A":"Zero, meaning no internal profit from that year is kept inside the business for reinvestment","B":"Equal to gross profit","C":"Equal to total sales revenue","D":"Negative, creating a new bank overdraft"},"correctOption":"A","correctAnswer":"Zero, meaning no internal profit from that year is kept inside the business for reinvestment","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Retained profit = Profit after tax - Dividends; a 100% dividend payout leaves zero retained profit for the year.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because gross profit is before overheads, tax, and dividends.","C":"Incorrect because sales revenue is before all costs.","D":"Incorrect because distributing 100% of profit after tax leaves retained profit at zero (paying *more* than available reserves would be negative)."}}},{"id":"P1_U5_MCQ_817","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_817","question":"When a business increases its sales volume while fixed overhead expenses (such as factory rent) stay constant, why does 'operating profit' often grow at a faster percentage rate than 'gross profit'?","options":{"A":"Because fixed overhead expenses are spread over more units sold, allowing a greater proportion of additional gross profit to flow straight into operating profit","B":"Because higher sales volume automatically eliminates corporation tax","C":"Because higher sales volume reduces raw material costs to zero","D":"Because fixed overhead expenses decrease whenever sales increase"},"correctOption":"A","correctAnswer":"Because fixed overhead expenses are spread over more units sold, allowing a greater proportion of additional gross profit to flow straight into operating profit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because once fixed overheads are covered, every additional unit's gross profit contributes directly to operating profit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because higher profit actually increases the dollar amount of corporation tax paid.","C":"Incorrect because direct variable material costs still rise with output.","D":"Incorrect because fixed overheads stay constant rather than falling to zero."}}},{"id":"P1_U5_MCQ_818","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_818","question":"If a manufacturer replaces manual assembly workers with automated robotic machinery, how does this typically change the structure of its statement of profit or loss?","options":{"A":"Direct labor costs inside cost of sales fall (increasing gross profit), while annual depreciation expenses inside overheads increase","B":"Both direct labor costs and depreciation expenses drop to zero","C":"Sales revenue is replaced by share capital","D":"Gross profit falls while direct labor costs double"},"correctOption":"A","correctAnswer":"Direct labor costs inside cost of sales fall (increasing gross profit), while annual depreciation expenses inside overheads increase","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because automation substitutes capital equipment (depreciated in overheads) for direct production wages (in cost of sales).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because new machinery incurs substantial annual depreciation charges.","C":"Incorrect because automation changes cost structure, not how sales revenue is recorded.","D":"Incorrect because reducing direct assembly wages lowers cost of sales and raises gross profit."}}},{"id":"P1_U5_MCQ_819","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_819","question":"Why do 'potential buyers of a business' examine its statements of profit or loss from the past three to five years rather than looking only at the most recent year?","options":{"A":"Because past statements of profit or loss show the exact market value of freehold land","B":"To verify whether profits are consistent and growing steadily, or whether the most recent year was a temporary one-off spike","C":"Because tax authorities prohibit buying a business with less than five years of losses","D":"To calculate the business's acid-test ratio"},"correctOption":"B","correctAnswer":"To verify whether profits are consistent and growing steadily, or whether the most recent year was a temporary one-off spike","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because multi-year profit trends reveal sustainable earning power and revenue stability.","distractor_reasons":{"A":"Incorrect because asset values appear on the statement of financial position.","B":"Correct selection.","C":"Incorrect because there is no such legal prohibition.","D":"Incorrect because the acid-test ratio uses current assets and current liabilities from the statement of financial position."}}},{"id":"P1_U5_MCQ_820","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_820","question":"Why can two companies with identical sales revenue and identical cash flows report slightly different 'profits for the year' on their statements of profit or loss?","options":{"A":"Because one company is legally allowed to omit all overhead expenses","B":"Because sales revenue is never included in profit calculations","C":"Because accounting judgments and estimates—such as the useful lifespan chosen for depreciating non-current assets or how closing inventory is valued—affect reported expenses and profit","D":"Because limited companies do not deduct cost of sales"},"correctOption":"C","correctAnswer":"Because accounting judgments and estimates—such as the useful lifespan chosen for depreciating non-current assets or how closing inventory is valued—affect reported expenses and profit","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because accrual accounting involves legitimate estimates (such as depreciation rates) that influence non-cash expenses without changing bank cash.","distractor_reasons":{"A":"Incorrect because all companies must include overhead expenses.","B":"Incorrect because sales revenue is always the starting point of the income statement.","C":"Correct selection.","D":"Incorrect because all trading companies deduct cost of sales."}}},{"id":"P1_U5_MCQ_821","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_821","question":"What happens to a company's 'retained profit' if it suffers a 'net loss' for the year?","options":{"A":"The net loss increases accumulated retained profit reserves","B":"The net loss is ignored and has no effect on shareholders' equity","C":"The net loss is transferred into non-current assets","D":"The net loss reduces accumulated retained profit reserves (and therefore reduces total shareholders' equity) on the statement of financial position"},"correctOption":"D","correctAnswer":"The net loss reduces accumulated retained profit reserves (and therefore reduces total shareholders' equity) on the statement of financial position","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because shareholders bear business losses, eroding accumulated equity reserves on the balance sheet.","distractor_reasons":{"A":"Incorrect because profits increase equity reserves, whereas losses reduce them.","B":"Incorrect because losses directly reduce net assets and shareholders' equity.","C":"Incorrect because losses are not assets.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_822","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_822","question":"Which stakeholder group uses a company's statement of profit or loss primarily to check whether the company is generating sufficient profit to pay regular dividends and justify holding its shares?","options":{"A":"Shareholders (owners)","B":"Raw-material suppliers","C":"Local environmental pressure groups","D":"Commercial utility providers"},"correctOption":"A","correctAnswer":"Shareholders (owners)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because shareholders receive dividends out of after-tax profits and rely on profit growth for share price appreciation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because suppliers care primarily about short-term bill payment and repeat orders rather than shareholder dividends.","C":"Incorrect because pressure groups focus on environmental and social impacts.","D":"Incorrect because utility providers care about timely bill settlement."}}},{"id":"P1_U5_MCQ_823","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_823","question":"Why do 'business managers' compare actual figures on the statement of profit or loss against budgeted targets at year-end?","options":{"A":"To calculate the exact market value of freehold land","B":"To evaluate departmental performance, identify areas where revenue fell short or expenses overshot budgets, and set realistic targets for next year","C":"To avoid publishing annual accounts to shareholders","D":"To eliminate all current liabilities"},"correctOption":"B","correctAnswer":"To evaluate departmental performance, identify areas where revenue fell short or expenses overshot budgets, and set realistic targets for next year","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because comparing actual income statement outcomes against budgets supports accountability and strategic planning.","distractor_reasons":{"A":"Incorrect because property values are not shown on the income statement.","B":"Correct selection.","C":"Incorrect because plcs must publish annual accounts by law.","D":"Incorrect because current liabilities are balance sheet obligations."}}},{"id":"P1_U5_MCQ_824","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_824","question":"If a business's sales revenue grows rapidly over a year, why might its 'profit for the year' still fall?","options":{"A":"Because higher sales revenue is always subtracted from gross profit","B":"Because sales revenue is never included on the statement of profit or loss","C":"Because cost of sales or overhead expenses (such as heavy promotional discounting, overtime wages, or higher rent) rose even faster than revenue","D":"Because profitable sales automatically increase corporation tax above 100%"},"correctOption":"C","correctAnswer":"Because cost of sales or overhead expenses (such as heavy promotional discounting, overtime wages, or higher rent) rose even faster than revenue","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because revenue growth without cost discipline or margin protection can compress overall profit.","distractor_reasons":{"A":"Incorrect because revenue is the starting positive figure on the income statement.","B":"Incorrect because revenue is always the top line of the income statement.","C":"Correct selection.","D":"Incorrect because corporation tax is a percentage of profit, never exceeding 100%."}}},{"id":"P1_U5_MCQ_825","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_825","question":"Which statement accurately summarizes the relationship between 'gross profit', 'operating profit', and 'retained profit' on a company's statement of profit or loss?","options":{"A":"Retained profit is always larger than gross profit","B":"Gross profit is calculated after deducting tax and dividends","C":"Operating profit is calculated before deducting cost of sales","D":"Gross profit is after direct cost of sales; operating profit is after also deducting indirect overheads; retained profit is after further deducting interest, tax, and dividends"},"correctOption":"D","correctAnswer":"Gross profit is after direct cost of sales; operating profit is after also deducting indirect overheads; retained profit is after further deducting interest, tax, and dividends","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because each stage down the statement of profit or loss deducts successive layers of costs, taxes, and owner distributions.","distractor_reasons":{"A":"Incorrect because retained profit is smaller than gross profit after overheads, tax, and dividends are deducted.","B":"Incorrect because gross profit is near the top before overheads, tax, and dividends.","C":"Incorrect because cost of sales is deducted first to find gross profit.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_826","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_826","question":"Why does the heading of a 'statement of financial position' state 'as at [specific date]' rather than 'for the year ended [specific date]'?","options":{"A":"Because it records the exact balances of assets, liabilities, and equity at one single moment in time rather than cumulative flows over a 12-month period","B":"Because businesses only operate on one single day each year","C":"Because all assets are sold on that specific date","D":"Because liabilities only exist on the final day of the financial year"},"correctOption":"A","correctAnswer":"Because it records the exact balances of assets, liabilities, and equity at one single moment in time rather than cumulative flows over a 12-month period","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because balance sheet items are point-in-time stock positions (like cash in the bank or stock on shelves on that evening), whereas revenue and expenses are period flows.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because businesses trade throughout the year.","C":"Incorrect because ongoing businesses retain their assets across years.","D":"Incorrect because debts exist continuously until paid."}}},{"id":"P1_U5_MCQ_827","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_827","question":"Which equation represents the fundamental 'accounting equation' underlying every statement of financial position?","options":{"A":"Assets = Liabilities - Equity","B":"Assets = Liabilities + Owners' Equity","C":"Assets + Liabilities = Owners' Equity","D":"Current Assets = Non-Current Liabilities"},"correctOption":"B","correctAnswer":"Assets = Liabilities + Owners' Equity","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because every resource owned by the business (Assets) is funded either by external creditors (Liabilities) or by the owners (Equity).","distractor_reasons":{"A":"Incorrect because Liabilities and Equity are added together to equal Total Assets (or Assets - Liabilities = Equity).","B":"Correct selection.","C":"Incorrect because liabilities are obligations subtracted from assets to find equity, not added to assets.","D":"Incorrect because short-term assets and long-term debts are not equal."}}},{"id":"P1_U5_MCQ_828","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_828","question":"How does the intended *purpose* of holding an item determine whether it is classified as a 'non-current asset' or 'inventory (current asset)'?","options":{"A":"Items costing over $100 are always non-current assets regardless of use","B":"Items made of metal are non-current assets, while items made of paper are current assets","C":"An item kept and used in operations for over a year (such as a delivery van used by a bakery) is a non-current asset, whereas an identical van held for immediate resale by a car dealership is inventory","D":"All vehicles are classified as current liabilities"},"correctOption":"C","correctAnswer":"An item kept and used in operations for over a year (such as a delivery van used by a bakery) is a non-current asset, whereas an identical van held for immediate resale by a car dealership is inventory","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because accounting classification depends on how the business uses the asset: long-term operational use (non-current asset) versus held for resale in ordinary trade (inventory).","distractor_reasons":{"A":"Incorrect because expensive goods held for resale (like luxury cars in a showroom) are still inventory.","B":"Incorrect because physical material does not determine accounting classification.","C":"Correct selection.","D":"Incorrect because owned vehicles are assets, not liabilities."}}},{"id":"P1_U5_MCQ_829","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_829","question":"What is 'goodwill' when it appears as an intangible non-current asset on a company's statement of financial position?","options":{"A":"Cash donated by the company to local charities","B":"Short-term trade credit granted by friendly suppliers","C":"Physical raw materials stored in the warehouse","D":"The extra value paid above net tangible asset value when acquiring an established business, reflecting its brand reputation, loyal customer base, and skilled staff"},"correctOption":"D","correctAnswer":"The extra value paid above net tangible asset value when acquiring an established business, reflecting its brand reputation, loyal customer base, and skilled staff","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because purchased goodwill arises during a takeover when the buyer pays more than the fair value of physical net assets for the target's reputation and customer relationships.","distractor_reasons":{"A":"Incorrect because charitable donations are expenses, not assets.","B":"Incorrect because supplier credit is trade payables (a current liability).","C":"Incorrect because physical raw materials are tangible current assets (inventories).","D":"Correct selection."}}},{"id":"P1_U5_MCQ_830","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_830","question":"How does 'accumulated depreciation' affect the presentation of non-current assets on a statement of financial position?","options":{"A":"It is deducted from the original historical cost of the non-current assets to show their remaining Net Book Value","B":"It is added to cash at bank under current assets","C":"It is recorded under non-current liabilities as a debt owed to the government","D":"It increases issued share capital"},"correctOption":"A","correctAnswer":"It is deducted from the original historical cost of the non-current assets to show their remaining Net Book Value","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because showing Cost minus Accumulated depreciation equals Net Book Value informs readers of both original investment and wear-and-tear to date.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because depreciation is non-cash and does not add to bank balances.","C":"Incorrect because depreciation is an asset valuation adjustment, not a debt owed.","D":"Incorrect because depreciation does not alter share capital."}}},{"id":"P1_U5_MCQ_831","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_831","question":"Which list contains ONLY 'current assets'?","options":{"A":"Inventories, trade payables, and cash in hand","B":"Inventories, trade receivables, and cash at bank","C":"Trade receivables, delivery vehicles, and cash at bank","D":"Cash at bank, bank overdraft, and inventories"},"correctOption":"B","correctAnswer":"Inventories, trade receivables, and cash at bank","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because inventories, trade receivables, and cash are the three standard categories of short-term current assets.","distractor_reasons":{"A":"Incorrect because trade payables are current liabilities.","B":"Correct selection.","C":"Incorrect because delivery vehicles are non-current assets.","D":"Incorrect because a bank overdraft is a current liability."}}},{"id":"P1_U5_MCQ_832","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_832","question":"Why are 'cash in hand' (notes and coins in tills/safes) and 'cash at bank' (positive current account balances) grouped together at the bottom of current assets?","options":{"A":"Because they are the least liquid assets owned by the business","B":"Because they are owed to external suppliers","C":"Because both represent immediately spendable liquid money (the highest degree of liquidity) available to settle debts on demand","D":"Because they are non-current assets lasting more than ten years"},"correctOption":"C","correctAnswer":"Because both represent immediately spendable liquid money (the highest degree of liquidity) available to settle debts on demand","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because current assets are ordered from least liquid (inventories) to most liquid (cash in hand and at bank).","distractor_reasons":{"A":"Incorrect because inventories are the least liquid current assets; cash is the most liquid.","B":"Incorrect because positive cash balances are assets owned by the business.","C":"Correct selection.","D":"Incorrect because cash circulates daily as a current asset."}}},{"id":"P1_U5_MCQ_833","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_833","question":"Why do 'trade receivables' appear on the statement of financial position of a B2B manufacturer, whereas a cash-only retail coffee shop may have zero trade receivables?","options":{"A":"Because retail coffee shops are legally forbidden from holding current assets","B":"Because B2B manufacturers are exempt from collecting payments from customers","C":"Because retail coffee shops record customer payments as non-current liabilities","D":"Because B2B manufacturers routinely sell goods on trade credit (creating unpaid customer invoices), whereas a coffee shop collects immediate cash/card payment at the point of sale"},"correctOption":"D","correctAnswer":"Because B2B manufacturers routinely sell goods on trade credit (creating unpaid customer invoices), whereas a coffee shop collects immediate cash/card payment at the point of sale","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because trade receivables only arise when goods or services are supplied on credit before cash payment is collected.","distractor_reasons":{"A":"Incorrect because coffee shops hold cash and food/drink inventories as current assets.","B":"Incorrect because manufacturers actively collect trade receivables.","C":"Incorrect because point-of-sale payments increase cash (a current asset).","D":"Correct selection."}}},{"id":"P1_U5_MCQ_834","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_834","question":"Within a factory's 'inventories' on its statement of financial position, what is 'work-in-progress'?","options":{"A":"Partly completed goods on the factory floor that have had some raw materials and labor applied to them, but are not yet finished products ready for sale","B":"Finished goods already delivered to credit customers","C":"Long-term factory buildings currently under construction by an outside contractor","D":"Unpaid invoices owed to raw-material suppliers"},"correctOption":"A","correctAnswer":"Partly completed goods on the factory floor that have had some raw materials and labor applied to them, but are not yet finished products ready for sale","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because work-in-progress sits between raw materials and finished goods in a manufacturer's inventory valuation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because goods delivered on credit become trade receivables.","C":"Incorrect because factory buildings are non-current assets.","D":"Incorrect because supplier invoices are trade payables (current liabilities)."}}},{"id":"P1_U5_MCQ_835","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_835","question":"Which feature distinguishes a 'current liability' from a 'non-current liability'?","options":{"A":"Current liabilities are owed to shareholders, whereas non-current liabilities are owed to customers","B":"Current liabilities must be settled within 12 months of the reporting date, whereas non-current liabilities are repayable over more than 12 months","C":"Current liabilities are always interest-free, whereas non-current liabilities always carry dividends","D":"Current liabilities are owned assets, whereas non-current liabilities are expenses"},"correctOption":"B","correctAnswer":"Current liabilities must be settled within 12 months of the reporting date, whereas non-current liabilities are repayable over more than 12 months","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the 12-month repayment horizon separates short-term current obligations from long-term debt.","distractor_reasons":{"A":"Incorrect because both are external debts owed to creditors (suppliers, banks, tax authorities).","B":"Correct selection.","C":"Incorrect because bank overdrafts (current liabilities) charge interest, and debt carries interest rather than dividends.","D":"Incorrect because all liabilities are debts owed by the business."}}},{"id":"P1_U5_MCQ_836","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_836","question":"Why does an increase in 'trade payables' (without exceeding supplier credit limits) help finance a business's current assets?","options":{"A":"Because suppliers pay cash directly into the business's bank account","B":"Because trade payables are added to shareholders' equity","C":"Because buying inventory on supplier credit allows the business to hold and sell stock before having to use its own cash to pay the supplier","D":"Because trade payables reduce non-current assets"},"correctOption":"C","correctAnswer":"Because buying inventory on supplier credit allows the business to hold and sell stock before having to use its own cash to pay the supplier","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because trade payables act as spontaneous short-term financing that reduces the net working capital cash needed.","distractor_reasons":{"A":"Incorrect because suppliers provide goods on credit rather than lending cash.","B":"Incorrect because trade payables are current liabilities, not equity.","C":"Correct selection.","D":"Incorrect because trade payables relate to short-term stock purchases, not non-current assets."}}},{"id":"P1_U5_MCQ_837","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_837","question":"If a business has received electricity and water during the final month of the year but has not yet paid the utility bill by the reporting date, how is that unpaid bill shown on the statement of financial position?","options":{"A":"As a current asset under cash at bank","B":"As a non-current asset under property","C":"As part of issued share capital","D":"As a current liability (accrued expense / short-term payable) because it is owed within 12 months"},"correctOption":"D","correctAnswer":"As a current liability (accrued expense / short-term payable) because it is owed within 12 months","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because unpaid short-term operating bills due within one year are current liabilities.","distractor_reasons":{"A":"Incorrect because owing money is a liability, not a cash asset.","B":"Incorrect because utility bills are short-term expenses, not long-term property assets.","C":"Incorrect because unpaid bills are creditor obligations, not owner share capital.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_838","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_838","question":"If a business takes out a 10-year bank loan, why is the portion due over years 2 to 10 classified as a 'non-current liability'?","options":{"A":"Because those repayments are due more than 12 months after the statement of financial position date","B":"Because bank loans never have to be repaid","C":"Because bank loans are an internal source of finance","D":"Because the loan is owned by the company's customers"},"correctOption":"A","correctAnswer":"Because those repayments are due more than 12 months after the statement of financial position date","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because long-term debt obligations extending beyond one year belong under non-current liabilities.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because all loans must be repaid according to their repayment schedule.","C":"Incorrect because bank loans are external debt.","D":"Incorrect because the loan is owed by the business to the bank."}}},{"id":"P1_U5_MCQ_839","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_839","question":"How are 'debentures' classified differently from 'ordinary share capital' on a company's statement of financial position?","options":{"A":"Debentures are current assets, whereas ordinary share capital is a current liability","B":"Debentures are non-current liabilities (long-term external debt), whereas ordinary share capital is part of shareholders' equity (permanent owners' funds)","C":"Debentures are shareholders' equity, whereas ordinary share capital is a non-current liability","D":"Both debentures and ordinary share capital are recorded as non-current assets"},"correctOption":"B","correctAnswer":"Debentures are non-current liabilities (long-term external debt), whereas ordinary share capital is part of shareholders' equity (permanent owners' funds)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because debenture holders are long-term creditors whose principal must be repaid, whereas ordinary shareholders are permanent owners.","distractor_reasons":{"A":"Incorrect because neither is a current asset or current liability.","B":"Correct selection.","C":"Incorrect because this reverses debt liabilities and owners' equity.","D":"Incorrect because both appear on the financing side (liabilities and equity), not as assets."}}},{"id":"P1_U5_MCQ_840","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_840","question":"On a statement of financial position, what does a positive 'working capital' (net current assets) figure confirm?","options":{"A":"That the business has zero long-term mortgages","B":"That the business's gross profit exceeds its sales revenue","C":"That the business's short-term current assets exceed its short-term current liabilities, providing a liquidity buffer for daily operations","D":"That the business has paid out 100% of its retained profit as dividends"},"correctOption":"C","correctAnswer":"That the business's short-term current assets exceed its short-term current liabilities, providing a liquidity buffer for daily operations","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Working capital = Current assets - Current liabilities; a positive figure means short-term assets cover short-term obligations.","distractor_reasons":{"A":"Incorrect because a business can have positive working capital alongside long-term mortgages.","B":"Incorrect because gross profit cannot exceed sales revenue unless cost of sales is negative.","C":"Correct selection.","D":"Incorrect because working capital measures current assets minus current liabilities, not dividend payout."}}},{"id":"P1_U5_MCQ_841","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_841","question":"Why can holding 'excessively high working capital' on a statement of financial position be criticized by shareholders?","options":{"A":"Because high working capital proves the business is insolvent","B":"Because high working capital increases short-term bank overdraft interest","C":"Because high working capital reduces non-current liabilities to zero automatically","D":"Because excessive funds tied up in idle cash, bloated inventory, or slow-paying trade receivables earn little or no return compared with investing in productive growth"},"correctOption":"D","correctAnswer":"Because excessive funds tied up in idle cash, bloated inventory, or slow-paying trade receivables earn little or no return compared with investing in productive growth","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because too much working capital creates an opportunity cost and drags down Return on Capital Employed (ROCE).","distractor_reasons":{"A":"Incorrect because negative working capital signals insolvency risk, whereas excessive working capital signals inefficiency.","B":"Incorrect because holding large cash reserves reduces rather than increases overdraft borrowing.","C":"Incorrect because working capital levels do not automatically pay off long-term debt.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_842","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_842","question":"Which formula correctly calculates 'Net assets' on a statement of financial position?","options":{"A":"Non-current assets + Current assets - Current liabilities - Non-current liabilities","B":"Non-current assets + Current assets + Current liabilities + Non-current liabilities","C":"Current assets - Current liabilities","D":"Non-current assets - Current assets"},"correctOption":"A","correctAnswer":"Non-current assets + Current assets - Current liabilities - Non-current liabilities","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Net assets equals Total assets (Non-current + Current) minus Total liabilities (Current + Non-current).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because liabilities must be subtracted from assets, not added.","C":"Incorrect because current assets minus current liabilities calculates working capital (net current assets).","D":"Incorrect because current assets are added to non-current assets to form total assets."}}},{"id":"P1_U5_MCQ_843","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_843","question":"How does the 'equity' section on a sole trader's statement of financial position differ from that of a limited company?","options":{"A":"A sole trader has issued share capital and corporate dividends, whereas a limited company has drawings","B":"A sole trader shows Opening capital + Profit for the year - Drawings, whereas a limited company shows Issued share capital + Retained profit reserves","C":"A sole trader has no equity section on its statement of financial position","D":"A limited company includes bank overdrafts inside shareholders' equity"},"correctOption":"B","correctAnswer":"A sole trader shows Opening capital + Profit for the year - Drawings, whereas a limited company shows Issued share capital + Retained profit reserves","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because sole traders do not issue shares and withdraw funds via drawings, whereas limited companies issue shares and accumulate retained profit.","distractor_reasons":{"A":"Incorrect because this reverses sole traders and limited companies.","B":"Correct selection.","C":"Incorrect because sole traders always record owner's capital (equity).","D":"Incorrect because bank overdrafts are current liabilities, not equity."}}},{"id":"P1_U5_MCQ_844","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_844","question":"Why are 'current liabilities' excluded when calculating 'Capital employed' (Shareholders' equity + Non-current liabilities)?","options":{"A":"Because current liabilities are assets rather than liabilities","B":"Because current liabilities are never paid by limited companies","C":"Because capital employed measures the permanent, long-term funds invested in the business, whereas current liabilities are short-term operational debts fluctuating daily","D":"Because current liabilities are already included inside issued share capital"},"correctOption":"C","correctAnswer":"Because capital employed measures the permanent, long-term funds invested in the business, whereas current liabilities are short-term operational debts fluctuating daily","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because capital employed focuses on long-term financing (equity plus long-term debt) used to generate operating profit.","distractor_reasons":{"A":"Incorrect because current liabilities are short-term debts.","B":"Incorrect because current liabilities are settled within 12 months.","C":"Correct selection.","D":"Incorrect because share capital and current liabilities are entirely separate sections."}}},{"id":"P1_U5_MCQ_845","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_845","question":"When a limited company issues new ordinary shares for cash and deposits the proceeds into its bank account, what is the immediate effect on its statement of financial position?","options":{"A":"Current liabilities increase and non-current assets decrease","B":"Non-current liabilities increase and retained profit decreases","C":"Working capital decreases and net assets decrease","D":"Current assets (cash) increase and shareholders' equity (issued share capital) increases by the exact same amount"},"correctOption":"D","correctAnswer":"Current assets (cash) increase and shareholders' equity (issued share capital) increases by the exact same amount","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because cash enters the bank (+current asset) and permanent equity expands (+share capital), keeping the balance sheet in balance.","distractor_reasons":{"A":"Incorrect because issuing shares creates equity, not debt liabilities.","B":"Incorrect because share issues increase equity rather than non-current debt.","C":"Incorrect because higher cash increases both working capital and net assets.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_846","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_846","question":"When a business uses cash from its bank current account to pay off an overdue supplier invoice ('trade payable'), what happens on its statement of financial position?","options":{"A":"Current assets (cash) decrease and current liabilities (trade payables) decrease by the exact same amount, leaving working capital unchanged","B":"Working capital increases by the payment amount","C":"Non-current assets increase and equity increases","D":"Current assets increase and current liabilities decrease"},"correctOption":"A","correctAnswer":"Current assets (cash) decrease and current liabilities (trade payables) decrease by the exact same amount, leaving working capital unchanged","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because subtracting an equal amount from both Current assets and Current liabilities leaves the difference (Current assets - Current liabilities) unchanged.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because both cash and trade payables fall equally, leaving net working capital constant.","C":"Incorrect because paying a supplier does not create non-current assets or equity.","D":"Incorrect because paying cash decreases rather than increases current assets."}}},{"id":"P1_U5_MCQ_847","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_847","question":"Why do commercial banks examine the proportion of 'non-current liabilities' relative to 'shareholders' equity' on a borrower's statement of financial position?","options":{"A":"To check how many products the business sold last week","B":"To assess financial risk (gearing): if long-term debt is already very high relative to equity, taking on another loan increases the risk of defaulting on interest payments","C":"To calculate the business's gross profit margin","D":"To determine whether the business holds enough raw material inventory"},"correctOption":"B","correctAnswer":"To assess financial risk (gearing): if long-term debt is already very high relative to equity, taking on another loan increases the risk of defaulting on interest payments","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because high existing long-term debt reduces the equity cushion protecting lenders and strains future cash flows.","distractor_reasons":{"A":"Incorrect because weekly unit sales are not shown on the statement of financial position.","B":"Correct selection.","C":"Incorrect because gross profit margin is calculated from the statement of profit or loss.","D":"Incorrect because inventory levels are part of current assets, not long-term debt vs equity."}}},{"id":"P1_U5_MCQ_848","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_848","question":"Why do 'suppliers' inspect both 'cash at bank' and 'existing trade payables' on a customer's statement of financial position before offering 60-day trade credit?","options":{"A":"To calculate the customer's annual corporation tax rate","B":"To check whether the customer's directors own personal cars","C":"To judge whether the customer has sufficient liquid cash to pay its bills on time or is already heavily overdue with other suppliers","D":"To decide which advertising agency the customer should hire"},"correctOption":"C","correctAnswer":"To judge whether the customer has sufficient liquid cash to pay its bills on time or is already heavily overdue with other suppliers","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because extending trade credit makes the supplier an unsecured short-term creditor exposed to default if the buyer lacks liquidity.","distractor_reasons":{"A":"Incorrect because tax rates are set by the government.","B":"Incorrect because directors' personal assets are not shown on company statements.","C":"Correct selection.","D":"Incorrect because marketing choices belong to the customer's managers."}}},{"id":"P1_U5_MCQ_849","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_849","question":"How can 'historical cost accounting' cause a statement of financial position to understate the true market value of a long-established company's property?","options":{"A":"Because property is recorded as a current liability","B":"Because property is omitted from the statement of financial position after five years","C":"Because property is always valued at zero","D":"Because freehold land and buildings bought decades ago may have risen substantially in market value, yet remain recorded at original historical purchase cost unless formally revalued"},"correctOption":"D","correctAnswer":"Because freehold land and buildings bought decades ago may have risen substantially in market value, yet remain recorded at original historical purchase cost unless formally revalued","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because recording assets at historical purchase price rather than current market value can create a large gap between book value and resale value.","distractor_reasons":{"A":"Incorrect because owned property is a non-current asset.","B":"Incorrect because freehold property remains on the statement for as long as the company owns it.","C":"Incorrect because property is recorded at its cost/carrying value, not zero.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_850","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_850","question":"Why are 'skilled employees' and 'internally built customer loyalty' NOT listed as assets on a business's statement of financial position?","options":{"A":"Because accounting rules only record assets that can be reliably measured in monetary terms and are legally owned/controlled by the business (such as purchased assets)","B":"Because employees and customers have no impact on business success","C":"Because employees are recorded as non-current liabilities","D":"Because customer loyalty is recorded inside cost of sales"},"correctOption":"A","correctAnswer":"Because accounting rules only record assets that can be reliably measured in monetary terms and are legally owned/controlled by the business (such as purchased assets)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a business does not legally own its workers and cannot objectively assign a dollar valuation to internally generated brand goodwill.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because skilled staff and loyal customers are vital competitive strengths, even though omitted from financial statements.","C":"Incorrect because employees are people, not non-current debt liabilities.","D":"Incorrect because customer loyalty is a qualitative intangible strength, not a direct cost of sales."}}},{"id":"P1_U5_MCQ_851","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_851","question":"How does calculating 'financial ratios' help analysts overcome the difficulty of comparing a large business with a smaller competitor?","options":{"A":"By expressing profits, costs, and assets as relative percentages or proportions rather than raw dollar totals, allowing fair efficiency comparisons regardless of business size","B":"By deleting all non-current assets from the larger business's accounts","C":"By forcing both businesses to report identical dollar sales revenue","D":"By eliminating corporation tax for the smaller business"},"correctOption":"A","correctAnswer":"By expressing profits, costs, and assets as relative percentages or proportions rather than raw dollar totals, allowing fair efficiency comparisons regardless of business size","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because relative ratios (such as ROCE or profit margin) normalize performance for scale.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because ratios use accurate financial statement figures without deleting assets.","C":"Incorrect because ratios compare proportions rather than changing underlying revenue.","D":"Incorrect because analytical ratios do not alter tax obligations."}}},{"id":"P1_U5_MCQ_852","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_852","question":"Why is examining a single year's financial ratios in isolation rarely enough to draw reliable conclusions about a business?","options":{"A":"Because ratios can only be calculated once every ten years","B":"Because without comparing against previous years (trend analysis) and industry benchmarks, an analyst cannot tell whether a ratio is improving, deteriorating, or normal for that sector","C":"Because single-year ratios omit all revenue and current assets","D":"Because financial ratios are illegal to use without government permission"},"correctOption":"B","correctAnswer":"Because without comparing against previous years (trend analysis) and industry benchmarks, an analyst cannot tell whether a ratio is improving, deteriorating, or normal for that sector","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because context is essential: a 10% profit margin might be outstanding in grocery retailing but weak in luxury software.","distractor_reasons":{"A":"Incorrect because ratios are calculated annually (or more frequently internally).","B":"Correct selection.","C":"Incorrect because single-year ratios include the relevant figures from that year's statements.","D":"Incorrect because anyone analyzing published accounts can freely compute ratios."}}},{"id":"P1_U5_MCQ_853","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_853","question":"Which formula correctly calculates 'Gross profit margin (%)'?","options":{"A":"(Revenue / Gross profit) × 100","B":"(Profit / Revenue) × 100","C":"(Gross profit / Revenue) × 100","D":"(Gross profit / Cost of sales) × 100"},"correctOption":"C","correctAnswer":"(Gross profit / Revenue) × 100","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because gross profit margin measures gross profit as a percentage of total sales revenue.","distractor_reasons":{"A":"Incorrect because this inverts gross profit and revenue.","B":"Incorrect because (Profit / Revenue) × 100 is the formula for profit margin.","C":"Correct selection.","D":"Incorrect because dividing by cost of sales calculates mark-up on cost rather than gross profit margin on sales."}}},{"id":"P1_U5_MCQ_854","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_854","question":"How can a shift in 'product sales mix' cause a retailer's 'gross profit margin' to fall even if unit selling prices and supplier costs on every individual item stay unchanged?","options":{"A":"Because head-office rent increased during the year","B":"Because the retailer issued new ordinary shares","C":"Because customers paid their invoices 10 days earlier","D":"Because customers bought a higher proportion of low-margin basic items and a lower proportion of high-margin luxury items, lowering the overall weighted average gross profit margin"},"correctOption":"D","correctAnswer":"Because customers bought a higher proportion of low-margin basic items and a lower proportion of high-margin luxury items, lowering the overall weighted average gross profit margin","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because company-wide gross profit margin reflects the blended average margin across all products sold.","distractor_reasons":{"A":"Incorrect because head-office rent is an indirect overhead expense and does not affect gross profit margin.","B":"Incorrect because share issues affect equity, not gross profit margin.","C":"Incorrect because faster receivable collections improve cash flow, not gross profit margin.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_855","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_855","question":"What does a 'profit margin' of 15% tell a business analyst?","options":{"A":"That for every $100 of sales revenue earned, $15 remains as operating profit after paying both direct cost of sales and indirect overhead expenses","B":"That the business holds $15 of cash for every $100 of current liabilities","C":"That the business generates $15 of profit for every $100 of non-current assets owned","D":"That 15% of the business's customers failed to pay their invoices"},"correctOption":"A","correctAnswer":"That for every $100 of sales revenue earned, $15 remains as operating profit after paying both direct cost of sales and indirect overhead expenses","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Profit margin = (Profit / Revenue) × 100, showing final operating profit retained per $100 of sales.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because liquidity coverage of current liabilities is measured by the current and acid-test ratios.","C":"Incorrect because return on capital invested is measured by ROCE.","D":"Incorrect because bad debts are uncollected receivables, not profit margin."}}},{"id":"P1_U5_MCQ_856","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_856","question":"Why is a business's 'profit margin (%)' always lower than its 'gross profit margin (%)' (assuming the business has positive overhead expenses)?","options":{"A":"Because profit margin divides by capital employed instead of revenue","B":"Because profit margin deducts indirect overhead expenses in addition to direct cost of sales, making the numerator (profit) smaller than gross profit while the denominator (revenue) stays the same","C":"Because gross profit margin adds overhead expenses to revenue","D":"Because profit margin excludes sales revenue"},"correctOption":"B","correctAnswer":"Because profit margin deducts indirect overhead expenses in addition to direct cost of sales, making the numerator (profit) smaller than gross profit while the denominator (revenue) stays the same","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Profit = Gross profit - Overhead expenses; since Profit < Gross profit, (Profit / Revenue) × 100 is smaller than (Gross profit / Revenue) × 100.","distractor_reasons":{"A":"Incorrect because dividing by capital employed is ROCE; both gross profit margin and profit margin divide by revenue.","B":"Correct selection.","C":"Incorrect because gross profit margin does not add overheads to revenue.","D":"Incorrect because revenue is the denominator in profit margin."}}},{"id":"P1_U5_MCQ_857","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_857","question":"If intense market competition prevents a business from raising its selling prices, how can management still increase its 'profit margin'?","options":{"A":"By increasing head-office administrative salaries and rent","B":"By taking out a larger short-term bank overdraft","C":"By reducing direct production wastage, negotiating bulk discounts on materials, and cutting unnecessary indirect overhead expenses","D":"By increasing inventory levels in the warehouse"},"correctOption":"C","correctAnswer":"By reducing direct production wastage, negotiating bulk discounts on materials, and cutting unnecessary indirect overhead expenses","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because when selling prices are constrained by competitors, improving cost efficiency in cost of sales and overheads widens profit margins.","distractor_reasons":{"A":"Incorrect because higher salaries and rent reduce profit margin.","B":"Incorrect because an overdraft adds interest expenses and does not improve operating profit margin.","C":"Correct selection.","D":"Incorrect because holding more inventory increases storage costs without raising profit margin."}}},{"id":"P1_U5_MCQ_858","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_858","question":"Which components form the denominator 'Capital employed' in the formula 'ROCE = (Profit / Capital employed) × 100'?","options":{"A":"Current assets + Current liabilities","B":"Sales revenue - Cost of sales","C":"Cash at bank + Trade receivables","D":"Total shareholders' equity (Share capital + Retained profit) + Non-current liabilities"},"correctOption":"D","correctAnswer":"Total shareholders' equity (Share capital + Retained profit) + Non-current liabilities","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because capital employed represents all long-term funds invested in the business by owners and long-term lenders.","distractor_reasons":{"A":"Incorrect because short-term current items do not equal capital employed.","B":"Incorrect because revenue minus cost of sales is gross profit.","C":"Incorrect because cash and receivables are liquid current assets, not long-term capital employed.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_859","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_859","question":"Besides increasing operating profit, how else can a company improve its 'Return on Capital Employed (ROCE)'?","options":{"A":"By selling off idle, unprofitable non-current assets and using the cash to pay down long-term debt, thereby reducing capital employed without harming profit","B":"By borrowing a large unnecessary long-term loan and leaving the cash idle in a zero-interest current account","C":"By holding excessive amounts of slow-moving inventory","D":"By lowering selling prices on price-inelastic products"},"correctOption":"A","correctAnswer":"By selling off idle, unprofitable non-current assets and using the cash to pay down long-term debt, thereby reducing capital employed without harming profit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ROCE = (Profit / Capital employed) × 100; shrinking unproductive capital employed (denominator) while maintaining profit (numerator) increases ROCE.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because borrowing idle funds increases capital employed without raising profit, lowering ROCE.","C":"Incorrect because bloated inventory ties up capital employed unproductively.","D":"Incorrect because cutting prices on inelastic goods reduces revenue and profit."}}},{"id":"P1_U5_MCQ_860","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_860","question":"Why do shareholders compare a company's 'ROCE' against the interest rate offered on safe government bonds or bank deposit accounts?","options":{"A":"Because ROCE measures whether the company can pay its short-term trade payables","B":"Because investing in company shares carries commercial risk, so shareholders expect ROCE to be significantly higher than risk-free interest rates to justify the risk","C":"Because companies are legally fined if their ROCE exceeds bank interest rates","D":"Because bank deposit interest rates determine the company's gross profit margin"},"correctOption":"B","correctAnswer":"Because investing in company shares carries commercial risk, so shareholders expect ROCE to be significantly higher than risk-free interest rates to justify the risk","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because risk-free deposit rates represent the opportunity cost of capital; if ROCE is lower than bank deposit rates, capital is being used inefficiently.","distractor_reasons":{"A":"Incorrect because short-term debt coverage is measured by liquidity ratios.","B":"Correct selection.","C":"Incorrect because higher ROCE is rewarded by investors, never fined.","D":"Incorrect because deposit rates do not dictate gross profit margins."}}},{"id":"P1_U5_MCQ_861","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_861","question":"Why is 'liquidity analysis' distinct from 'profitability analysis' when judging a business's financial health?","options":{"A":"Liquidity analysis only looks at non-current assets, while profitability analysis only looks at liabilities","B":"Liquidity analysis is used only by shareholders, while profitability analysis is used only by suppliers","C":"Profitability analysis measures whether revenue exceeds costs over time, whereas liquidity analysis measures whether the business holds enough cash and near-cash assets to pay immediate short-term bills","D":"Both liquidity analysis and profitability analysis use the exact same formulas"},"correctOption":"C","correctAnswer":"Profitability analysis measures whether revenue exceeds costs over time, whereas liquidity analysis measures whether the business holds enough cash and near-cash assets to pay immediate short-term bills","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a business can be profitable on paper yet illiquid in cash, so both dimensions must be analyzed separately.","distractor_reasons":{"A":"Incorrect because liquidity focuses on current assets and current liabilities, while profitability focuses on income statement margins and ROCE.","B":"Incorrect because all major stakeholders examine both dimensions.","C":"Correct selection.","D":"Incorrect because profitability and liquidity ratios use distinct formulas."}}},{"id":"P1_U5_MCQ_862","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_862","question":"How is the result of the 'Current ratio' (Current assets / Current liabilities) conventionally written and interpreted?","options":{"A":"As a percentage (e.g., 150%), showing annual return on equity","B":"As a dollar profit figure (e.g., $150), showing total working capital","C":"As a number of days (e.g., 150 days), showing how long inventory sits in the warehouse","D":"As a ratio relative to 1 (e.g., 1.5 : 1), showing how many dollars of current assets the business holds for every $1 of current liabilities"},"correctOption":"D","correctAnswer":"As a ratio relative to 1 (e.g., 1.5 : 1), showing how many dollars of current assets the business holds for every $1 of current liabilities","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because expressing liquidity ratios as X : 1 directly shows short-term asset coverage per unit of short-term debt.","distractor_reasons":{"A":"Incorrect because liquidity ratios are expressed as X : 1 rather than percentages.","B":"Incorrect because subtracting liabilities from assets gives dollar working capital, whereas dividing gives a dimensionless ratio.","C":"Incorrect because inventory turnover days is a separate efficiency metric.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_863","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_863","question":"If a manufacturing company's 'current ratio' falls steadily over three consecutive years from 2.1 : 1 to 1.4 : 1 to 0.9 : 1, what trend does this show?","options":{"A":"Deteriorating short-term liquidity, culminating in current liabilities exceeding current assets and signaling growing risk of cash shortages","B":"Steadily improving profitability and higher gross profit margins","C":"A steady reduction in short-term debts relative to cash","D":"Excessive idle cash accumulating in the bank account"},"correctOption":"A","correctAnswer":"Deteriorating short-term liquidity, culminating in current liabilities exceeding current assets and signaling growing risk of cash shortages","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a falling current ratio below 1 : 1 warns that short-term obligations are outgrowing short-term liquid resources.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the current ratio measures liquidity, not profitability.","C":"Incorrect because a falling ratio means short-term debts are growing *faster* than current assets.","D":"Incorrect because accumulating cash would raise rather than lower the current ratio."}}},{"id":"P1_U5_MCQ_864","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_864","question":"Which transaction would cause a business's 'current ratio' to *fall* immediately?","options":{"A":"Collecting payment from a credit customer in cash","B":"Using existing cash from the bank current account to buy a new freehold factory building","C":"Issuing new ordinary shares for cash","D":"Selling surplus, unused factory machinery for cash"},"correctOption":"B","correctAnswer":"Using existing cash from the bank current account to buy a new freehold factory building","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because spending cash (a current asset) on a freehold building (a non-current asset) reduces the numerator of the current ratio while current liabilities stay unchanged.","distractor_reasons":{"A":"Incorrect because collecting a receivable swaps receivables for cash, leaving total current assets unchanged.","B":"Correct selection.","C":"Incorrect because issuing shares for cash increases current assets and raises the current ratio.","D":"Incorrect because selling non-current assets for cash increases current assets and raises the current ratio."}}},{"id":"P1_U5_MCQ_865","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_865","question":"Which assets are included in the numerator of the 'Acid-test (quick) ratio' [(Current assets - Inventories) / Current liabilities]?","options":{"A":"Non-current assets and inventories","B":"Inventories and trade payables","C":"Liquid current assets only—specifically cash (in hand and at bank) and trade receivables","D":"Issued share capital and retained profit"},"correctOption":"C","correctAnswer":"Liquid current assets only—specifically cash (in hand and at bank) and trade receivables","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because removing inventories from current assets leaves cash and trade receivables as the quick assets tested against current liabilities.","distractor_reasons":{"A":"Incorrect because non-current assets and inventories are both excluded from the acid-test ratio.","B":"Incorrect because inventories are excluded and trade payables are current liabilities.","C":"Correct selection.","D":"Incorrect because share capital and retained profit are shareholders' equity."}}},{"id":"P1_U5_MCQ_866","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_866","question":"For which type of business is the 'acid-test ratio' particularly revealing compared with the 'current ratio'?","options":{"A":"A pure digital software consultancy that holds zero physical inventory","B":"A bank that holds only financial deposits","C":"A business with zero current liabilities","D":"A retailer or manufacturer holding large amounts of slow-moving or perishable inventory (such as fashion clothing or fresh food) that may be hard to sell quickly at full price"},"correctOption":"D","correctAnswer":"A retailer or manufacturer holding large amounts of slow-moving or perishable inventory (such as fashion clothing or fresh food) that may be hard to sell quickly at full price","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because when inventory is large and slow-moving or perishable, the current ratio can look deceptively safe while the acid-test ratio exposes true cash tightness.","distractor_reasons":{"A":"Incorrect because when inventory is zero, the acid-test ratio and current ratio are identical.","B":"Incorrect because without physical inventories, both ratios yield the same value.","C":"Incorrect because zero current liabilities makes both ratios undefined.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_867","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_867","question":"If a business's 'current ratio' and 'acid-test ratio' are exactly equal (for example, both equal 1.6 : 1), what must be true about the business?","options":{"A":"The business holds zero inventories on its statement of financial position","B":"The business has zero trade receivables","C":"The business has zero current liabilities","D":"The business is making a net loss"},"correctOption":"A","correctAnswer":"The business holds zero inventories on its statement of financial position","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Current assets / Current liabilities equals (Current assets - Inventories) / Current liabilities only when Inventories = 0.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because trade receivables are included in both ratios.","C":"Incorrect because zero current liabilities would prevent dividing to get 1.6 : 1.","D":"Incorrect because liquidity ratios do not indicate trading profit or loss."}}},{"id":"P1_U5_MCQ_868","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_868","question":"How do 'potential equity investors' use profitability ratios (such as ROCE and profit margin) when comparing two competing companies in the same industry?","options":{"A":"To check which company employs more factory cleaners","B":"To identify which company converts sales and invested capital into profit more efficiently, signaling stronger management and higher potential returns","C":"To calculate the national unemployment rate","D":"To force the less profitable company to lower its selling prices"},"correctOption":"B","correctAnswer":"To identify which company converts sales and invested capital into profit more efficiently, signaling stronger management and higher potential returns","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because inter-firm ratio comparison helps investors allocate capital toward the best-performing company in a sector.","distractor_reasons":{"A":"Incorrect because ratios measure financial efficiency, not staffing details.","B":"Correct selection.","C":"Incorrect because unemployment is a macroeconomic statistic.","D":"Incorrect because outside investors cannot dictate a company's operational pricing."}}},{"id":"P1_U5_MCQ_869","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_869","question":"When a business applies to renew or increase its 'bank overdraft facility', why does the bank manager scrutinize the business's 'acid-test ratio'?","options":{"A":"Because the acid-test ratio calculates the company's annual dividend payout","B":"Because the bank wants to know the historical purchase price of freehold land","C":"Because the acid-test ratio shows whether the business can quickly generate liquid cash from receivables and existing bank balances to repay the overdraft without relying on fire-sale inventory disposals","D":"Because the acid-test ratio measures employee job satisfaction"},"correctOption":"C","correctAnswer":"Because the acid-test ratio shows whether the business can quickly generate liquid cash from receivables and existing bank balances to repay the overdraft without relying on fire-sale inventory disposals","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because overdrafts are short-term recallable facilities, making immediate near-cash liquidity crucial to the lending bank.","distractor_reasons":{"A":"Incorrect because dividends are shown on the statement of profit or loss.","B":"Incorrect because freehold land is a non-current asset excluded from the acid-test ratio.","C":"Correct selection.","D":"Incorrect because ratios measure financial data, not employee morale."}}},{"id":"P1_U5_MCQ_870","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_870","question":"If a prospective business customer has a dangerously low 'acid-test ratio' (e.g., 0.4 : 1), what protective action might a cautious 'supplier' take?","options":{"A":"Offer the customer 180-day interest-free trade credit automatically","B":"Buy ordinary shares in the customer's business","C":"Double the customer's credit limit without checking references","D":"Refuse open trade credit and insist on 'cash on delivery' (or upfront payment) to avoid the risk of unpaid invoices"},"correctOption":"D","correctAnswer":"Refuse open trade credit and insist on 'cash on delivery' (or upfront payment) to avoid the risk of unpaid invoices","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a very low acid-test ratio signals severe short-term cash strain and high default risk on supplier invoices.","distractor_reasons":{"A":"Incorrect because extending generous credit to an illiquid buyer increases bad-debt risk.","B":"Incorrect because commercial suppliers sell goods rather than buying shares in struggling customers.","C":"Incorrect because a weak liquidity ratio prompts tighter, not looser, credit limits.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_871","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_871","question":"How can 'employees and trade unions' use a company's improving 'profit margin' and 'ROCE' during annual collective bargaining?","options":{"A":"As objective evidence that the company's financial performance and efficiency have strengthened, supporting claims for higher wages, bonuses, or improved working conditions","B":"To legally force the company to cancel all shareholder dividends","C":"To set the government's national corporation tax rate","D":"To replace the board of directors with factory supervisors"},"correctOption":"A","correctAnswer":"As objective evidence that the company's financial performance and efficiency have strengthened, supporting claims for higher wages, bonuses, or improved working conditions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because rising profitability ratios show the employer is generating stronger returns and can better afford pay improvements.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because dividend decisions rest with directors and shareholders.","C":"Incorrect because governments set tax rates.","D":"Incorrect because shareholders appoint directors."}}},{"id":"P1_U5_MCQ_872","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_872","question":"How do 'senior managers' use financial ratio targets (such as a target ROCE or minimum current ratio) in strategic planning?","options":{"A":"To avoid keeping accounting records during the year","B":"As clear performance benchmarks to evaluate investment proposals, control working capital, and reward managerial performance","C":"To eliminate all competitors from the industry","D":"To guarantee that inflation stays at 0%"},"correctOption":"B","correctAnswer":"As clear performance benchmarks to evaluate investment proposals, control working capital, and reward managerial performance","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because ratio targets translate broad financial goals into measurable criteria for capital allocation and operational discipline.","distractor_reasons":{"A":"Incorrect because accurate accounting records are required to compute ratios.","B":"Correct selection.","C":"Incorrect because internal targets do not eliminate market competition.","D":"Incorrect because macroeconomic inflation is outside business control."}}},{"id":"P1_U5_MCQ_873","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_873","question":"Why does 'historical lag' limit the usefulness of published financial ratios when an investor is deciding whether to buy shares today?","options":{"A":"Because published accounts only report figures from ten years ago","B":"Because published ratios exclude all profit and asset figures","C":"Because annual accounts are published months after the financial year ends and reflect past conditions, whereas new competitors, technology shifts, or economic downturns may have already altered current prospects","D":"Because historical ratios are always calculated inaccurately by external auditors"},"correctOption":"C","correctAnswer":"Because annual accounts are published months after the financial year ends and reflect past conditions, whereas new competitors, technology shifts, or economic downturns may have already altered current prospects","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because financial statements are backward-looking; strong past ratios do not guarantee future resilience in fast-changing markets.","distractor_reasons":{"A":"Incorrect because annual accounts cover the most recently completed financial year.","B":"Incorrect because published accounts include complete profit and balance sheet data.","C":"Correct selection.","D":"Incorrect because external auditors verify numerical accuracy; the limitation is time lag and backward focus."}}},{"id":"P1_U5_MCQ_874","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_874","question":"Which critical business factor is completely invisible in financial ratio analysis, requiring decision-makers to look beyond the numbers?","options":{"A":"Sales revenue and cost of sales","B":"Current assets and current liabilities","C":"Issued share capital and non-current liabilities","D":"Qualitative factors such as employee morale, management leadership quality, brand reputation, customer satisfaction, and environmental sustainability"},"correctOption":"D","correctAnswer":"Qualitative factors such as employee morale, management leadership quality, brand reputation, customer satisfaction, and environmental sustainability","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because ratios quantify financial outcomes only and cannot capture non-financial drivers that determine long-term competitiveness.","distractor_reasons":{"A":"Incorrect because revenue and cost of sales are directly measured in gross profit margin.","B":"Incorrect because current assets and current liabilities are directly measured in liquidity ratios.","C":"Incorrect because share capital and non-current liabilities are directly included in ROCE.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_875","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_875","question":"Why must an analyst exercise caution when comparing the 'profit margin' and 'current ratio' of a clothing retailer against those of a civil engineering construction firm?","options":{"A":"Because different industries have completely different operating cycles, cost structures, inventory turnover speeds, and working capital norms, making cross-industry ratio benchmarks invalid","B":"Because civil engineering firms are legally prohibited from calculating profit margins","C":"Because clothing retailers never have any current liabilities","D":"Because financial ratios are only valid for sole traders"},"correctOption":"A","correctAnswer":"Because different industries have completely different operating cycles, cost structures, inventory turnover speeds, and working capital norms, making cross-industry ratio benchmarks invalid","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because valid inter-firm ratio comparisons must compare businesses within the same industry sector and of comparable scale.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because construction companies routinely calculate profit margins.","C":"Incorrect because clothing retailers carry substantial trade payables and short-term obligations.","D":"Incorrect because ratio analysis applies across all business forms, especially limited companies."}}},{"id":"P1_U5_MCQ_876","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_876","question":"Why does 'expansion capital' needed by a domestic manufacturer entering overseas markets differ in purpose from 'start-up capital'?","options":{"A":"Expansion capital funds new overseas distribution hubs, export marketing, and extra production capacity for an established firm, whereas start-up capital funds initial premises, equipment, and launch inventory for a brand-new venture","B":"Expansion capital is always free of interest, whereas start-up capital always incurs corporation tax","C":"Expansion capital is only used to pay daily electricity bills, whereas start-up capital is only used to pay shareholder dividends","D":"Expansion capital is classified as a current liability, whereas start-up capital is classified as sales revenue"},"correctOption":"A","correctAnswer":"Expansion capital funds new overseas distribution hubs, export marketing, and extra production capacity for an established firm, whereas start-up capital funds initial premises, equipment, and launch inventory for a brand-new venture","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because start-up capital launches a new enterprise from scratch, whereas expansion capital scales up operations, capacity, or geographic reach for an existing business.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because both types of capital may incur borrowing costs depending on the source used.","C":"Incorrect because expansion capital funds long-term growth investments rather than routine utility bills.","D":"Incorrect because neither is classified as sales revenue."}}},{"id":"P1_U5_MCQ_877","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_877","question":"A food-processing factory installs a $120,000 industrial refrigeration system expected to last 10 years and spends $3,500 per month on electricity to run it. How are these two outlays classified?","options":{"A":"Both outlays are revenue expenditure","B":"The $120,000 refrigeration system is capital expenditure, whereas the $3,500 monthly electricity bill is revenue expenditure","C":"The $120,000 refrigeration system is revenue expenditure, whereas the $3,500 monthly electricity bill is capital expenditure","D":"Both outlays are capital expenditure"},"correctOption":"B","correctAnswer":"The $120,000 refrigeration system is capital expenditure, whereas the $3,500 monthly electricity bill is revenue expenditure","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because acquiring a long-term non-current asset lasting over 12 months is capital expenditure, while ongoing operational utility bills are revenue expenditure.","distractor_reasons":{"A":"Incorrect because a 10-year refrigeration plant is a non-current asset (capital expenditure).","B":"Correct selection.","C":"Incorrect because this reverses capital and revenue expenditure.","D":"Incorrect because monthly electricity is consumed immediately in daily operations."}}},{"id":"P1_U5_MCQ_878","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_878","question":"How can adopting 'Just-in-Time (JIT) inventory management' act as an internal source of finance for a manufacturer?","options":{"A":"By borrowing extra money from a commercial bank at a variable interest rate","B":"By issuing preference shares to raw-material suppliers","C":"By drastically reducing the volume of raw materials and finished goods held in storage, freeing up cash previously tied up in working capital","D":"By increasing warehouse rent and insurance payments"},"correctOption":"C","correctAnswer":"By drastically reducing the volume of raw materials and finished goods held in storage, freeing up cash previously tied up in working capital","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because lowering inventory levels releases cash trapped in unsold stock without incurring external borrowing costs.","distractor_reasons":{"A":"Incorrect because JIT is an internal operational efficiency method, not bank borrowing.","B":"Incorrect because JIT does not involve issuing shares.","C":"Correct selection.","D":"Incorrect because holding smaller inventories reduces storage and insurance costs."}}},{"id":"P1_U5_MCQ_879","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_879","question":"What is a major financial trade-off when a retail chain raises internal capital through the 'sale and leaseback' of its freehold stores?","options":{"A":"The retail chain must immediately close all its stores and stop trading","B":"The retail chain dilutes its ordinary shareholders' voting rights","C":"The retail chain must repay the sale proceeds to the buyer within 12 months","D":"It unlocks a large lump sum of cash while allowing the retailer to continue operating in the stores, but creates a permanent ongoing fixed rent outflow and forfeits future property appreciation"},"correctOption":"D","correctAnswer":"It unlocks a large lump sum of cash while allowing the retailer to continue operating in the stores, but creates a permanent ongoing fixed rent outflow and forfeits future property appreciation","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because sale and leaseback converts illiquid property equity into immediate cash at the expense of recurring lease payments and loss of asset ownership.","distractor_reasons":{"A":"Incorrect because the 'leaseback' clause guarantees continued operational use of the premises.","B":"Incorrect because selling property does not alter share ownership.","C":"Incorrect because the property is sold outright rather than borrowed.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_880","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_880","question":"Why might a rapidly growing profitable company still be unable to finance a $15 million automated warehouse purely from 'retained profit'?","options":{"A":"Because accumulated retained profits from previous years may be far smaller than $15 million or already tied up in existing equipment and working capital","B":"Because limited companies are legally forbidden from using retained profit to buy buildings","C":"Because retained profit carries a higher interest rate than a bank overdraft","D":"Because using retained profit transfers ownership of the warehouse to the government"},"correctOption":"A","correctAnswer":"Because accumulated retained profits from previous years may be far smaller than $15 million or already tied up in existing equipment and working capital","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because internal retained profits accumulate gradually and are often insufficient on their own for sudden, large-scale capital projects.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because retained profit is frequently used for capital expenditure.","C":"Incorrect because retained profit incurs zero interest charges.","D":"Incorrect because assets bought with retained profit belong entirely to the company."}}},{"id":"P1_U5_MCQ_881","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_881","question":"Besides providing equity finance to high-growth start-ups, what non-financial benefit do 'venture capitalists' often bring to an entrepreneur?","options":{"A":"A legal guarantee that the start-up will never face competitors","B":"Specialist industry expertise, strategic mentoring, and commercial contacts that help scale the business rapidly","C":"100% exemption from corporation tax and value-added tax","D":"Zero dilution of the founder's ownership share or board control"},"correctOption":"B","correctAnswer":"Specialist industry expertise, strategic mentoring, and commercial contacts that help scale the business rapidly","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because venture capital firms actively advise and network with portfolio companies to maximize growth and exit valuation.","distractor_reasons":{"A":"Incorrect because venture capitalists cannot eliminate market competition.","B":"Correct selection.","C":"Incorrect because venture-backed firms still pay all statutory taxes.","D":"Incorrect because venture capitalists require an equity stake and board representation in return for their high-risk investment."}}},{"id":"P1_U5_MCQ_882","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_882","question":"Which external source of finance is specifically designed as a long-term loan (often 15 to 25 years) secured directly against the freehold land or commercial building being purchased?","options":{"A":"Trade credit","B":"Debt factoring","C":"A commercial mortgage","D":"A bank overdraft"},"correctOption":"C","correctAnswer":"A commercial mortgage","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a commercial mortgage uses the acquired real estate as collateral over a multi-decade repayment period.","distractor_reasons":{"A":"Incorrect because trade credit is a 30–60 day supplier facility for inventory purchases.","B":"Incorrect because debt factoring advances cash against short-term customer invoices.","C":"Correct selection.","D":"Incorrect because an overdraft is a short-term working capital facility."}}},{"id":"P1_U5_MCQ_883","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_883","question":"How do 'preference shares' differ from 'ordinary shares' when a limited company distributes profits?","options":{"A":"Preference shareholders control all board voting decisions, whereas ordinary shareholders cannot vote","B":"Preference shares are short-term current liabilities repaid every 30 days","C":"Preference shareholders receive dividends only after ordinary shareholders have been paid","D":"Preference shareholders receive a fixed percentage dividend ahead of ordinary shareholders, though they normally do not carry voting rights at the Annual General Meeting"},"correctOption":"D","correctAnswer":"Preference shareholders receive a fixed percentage dividend ahead of ordinary shareholders, though they normally do not carry voting rights at the Annual General Meeting","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because preference shares combine priority fixed dividend returns with limited voting control, whereas ordinary shares carry voting power and variable residual dividends.","distractor_reasons":{"A":"Incorrect because ordinary shareholders hold voting control, while preference shares are typically non-voting.","B":"Incorrect because share capital is permanent equity, not a 30-day liability.","C":"Incorrect because preference dividends have priority *before* ordinary dividends.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_884","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_884","question":"How does issuing 'debentures' differ from taking a standard 'commercial bank loan'?","options":{"A":"Debentures are long-term debt certificates issued directly to institutional or public investors at a fixed interest rate, allowing a large company to raise substantial long-term debt without relying on a single bank","B":"Debentures give investors permanent voting ownership of the company, whereas bank loans do not","C":"Debentures never require paying interest or repaying principal","D":"Debentures are an internal source of finance"},"correctOption":"A","correctAnswer":"Debentures are long-term debt certificates issued directly to institutional or public investors at a fixed interest rate, allowing a large company to raise substantial long-term debt without relying on a single bank","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because debentures are tradable long-term corporate debt instruments sold to bond investors rather than negotiated with one commercial bank.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because debenture holders are creditors without voting rights.","C":"Incorrect because debentures carry fixed annual interest and a maturity repayment date.","D":"Incorrect because debentures raise funds from external investors."}}},{"id":"P1_U5_MCQ_885","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_885","question":"Why does financing the construction of a new $2 million factory using a 'short-term bank overdraft' violate sound financial management principles?","options":{"A":"Because banks are legally forbidden from offering overdrafts to manufacturers","B":"Because an overdraft carries high daily interest and can be recalled on demand by the bank long before the factory generates enough cash flows to pay for itself","C":"Because using an overdraft turns the factory into a current asset","D":"Because an overdraft dilutes existing shareholders' voting shares"},"correctOption":"B","correctAnswer":"Because an overdraft carries high daily interest and can be recalled on demand by the bank long before the factory generates enough cash flows to pay for itself","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the 'matching principle' requires long-term assets to be funded by long-term finance so asset returns match debt repayment schedules.","distractor_reasons":{"A":"Incorrect because manufacturers routinely use overdrafts for short-term working capital.","B":"Correct selection.","C":"Incorrect because a factory remains a non-current asset regardless of how it is funded.","D":"Incorrect because overdrafts are debt facilities, not equity shares."}}},{"id":"P1_U5_MCQ_886","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_886","question":"A business sells $50,000 of unpaid customer invoices to a 'debt factor', which advances 80% immediately ($40,000) and pays the remaining 20% later minus a 4% service fee ($2,000). What is the key financial cost of this arrangement?","options":{"A":"The business loses $2,000 of its revenue in fees, reducing its net profit margin in exchange for getting $40,000 cash immediately","B":"The business must give 80% of its ordinary shares to the factoring company","C":"The business is banned from offering credit to any future customers","D":"The business's non-current liabilities increase by $50,000"},"correctOption":"A","correctAnswer":"The business loses $2,000 of its revenue in fees, reducing its net profit margin in exchange for getting $40,000 cash immediately","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because factoring trades a percentage fee (lowering profitability) for immediate working capital liquidity.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because debt factoring does not transfer equity ownership.","C":"Incorrect because factoring specifically supports businesses that sell on trade credit.","D":"Incorrect because factoring converts trade receivables into cash rather than creating long-term debt."}}},{"id":"P1_U5_MCQ_887","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_887","question":"What is a distinct commercial risk of launching a public 'crowdfunding' campaign for an innovative new product design before securing patent protection?","options":{"A":"Crowdfunding platforms take 90% of all funds raised as commission","B":"Publicly revealing detailed product prototypes and marketing plans online allows established competitors to copy the unpatented idea rapidly","C":"Backers are legally allowed to seize the entrepreneur's personal home if the product ships one week late","D":"Crowdfunding automatically converts a sole trader into a public limited company"},"correctOption":"B","correctAnswer":"Publicly revealing detailed product prototypes and marketing plans online allows established competitors to copy the unpatented idea rapidly","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because public online pitches expose unpatented innovations to imitation before the start-up has scaled up.","distractor_reasons":{"A":"Incorrect because platform fees are typically around 5%–10%, not 90%.","B":"Correct selection.","C":"Incorrect because reward backers do not hold property liens over the creator's personal home.","D":"Incorrect because crowdfunding does not automatically change legal business structure."}}},{"id":"P1_U5_MCQ_888","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_888","question":"Why do 'microfinance' institutions typically charge higher percentage interest rates than large commercial banks, even though they aim to help low-income entrepreneurs?","options":{"A":"Because microfinance providers are owned by stock-market speculators seeking monopoly profits","B":"Because microfinance loans last for 30 years without any repayments","C":"Because administering, monitoring, and collecting thousands of very small unsecured loans incurs high per-dollar operational costs and higher default risk","D":"Because governments require microfinance banks to charge minimum rates of 100%"},"correctOption":"C","correctAnswer":"Because administering, monitoring, and collecting thousands of very small unsecured loans incurs high per-dollar operational costs and higher default risk","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because processing and field-monitoring tiny loans without physical collateral requires intensive staff administration per dollar lent.","distractor_reasons":{"A":"Incorrect because many microfinance institutions are social enterprises or NGOs focused on financial inclusion.","B":"Incorrect because microfinance loans are typically short-term with frequent weekly or monthly instalments.","C":"Correct selection.","D":"Incorrect because governments do not mandate 100% interest rates."}}},{"id":"P1_U5_MCQ_889","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_889","question":"What is a common drawback for a business applying for a 'government grant' to fund a new green-energy manufacturing line?","options":{"A":"The grant must be repaid with compound interest within six months","B":"The government takes 51% voting control of the board of directors","C":"Grants can only be spent on paying executive bonuses","D":"Application processes are slow and bureaucratic, and the business must meet strict eligibility conditions (such as minimum job creation or carbon targets) or risk having to repay the grant"},"correctOption":"D","correctAnswer":"Application processes are slow and bureaucratic, and the business must meet strict eligibility conditions (such as minimum job creation or carbon targets) or risk having to repay the grant","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because while grants are non-repayable when conditions are met, they carry strict compliance rules and lengthy approval timelines.","distractor_reasons":{"A":"Incorrect because grants do not require repayment if conditions are fulfilled.","B":"Incorrect because grants do not transfer corporate ownership to the state.","C":"Incorrect because grants are restricted to approved capital, training, or R&D purposes.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_890","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_890","question":"What is the fundamental difference between 'leasing' a fleet of delivery vans and acquiring them through 'hire purchase'?","options":{"A":"Under leasing, the business never owns the vans (simply renting them), whereas under hire purchase, legal ownership transfers to the business once the final instalment is paid","B":"Under leasing, the business owns the vans immediately on Day 1, whereas under hire purchase, the vans are returned after one year","C":"Leasing is an internal source of finance, whereas hire purchase is equity share capital","D":"Leasing requires paying the full purchase price upfront in cash, whereas hire purchase requires zero payments"},"correctOption":"A","correctAnswer":"Under leasing, the business never owns the vans (simply renting them), whereas under hire purchase, legal ownership transfers to the business once the final instalment is paid","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because leasing is a pure rental arrangement (ideal for avoiding obsolescence), while hire purchase is an instalment purchase ending in ownership.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because this reverses leasing and hire purchase.","C":"Incorrect because both are external asset-financing arrangements.","D":"Incorrect because both spread cash outflows over time rather than requiring 100% upfront cash."}}},{"id":"P1_U5_MCQ_891","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_891","question":"Why can a '$20,000 bank overdraft limit' sometimes be cheaper in total interest cost than a '$20,000 fixed-term bank loan' for a business with fluctuating seasonal cash needs?","options":{"A":"Because bank overdrafts always have a lower annual percentage interest rate than bank loans","B":"Because overdraft interest is calculated daily only on the exact negative balance actually used on each day, whereas loan interest is paid on the full borrowed principal even when cash sits idle","C":"Because banks never charge interest on overdrafts under $50,000","D":"Because overdraft interest is paid by the government"},"correctOption":"B","correctAnswer":"Because overdraft interest is calculated daily only on the exact negative balance actually used on each day, whereas loan interest is paid on the full borrowed principal even when cash sits idle","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because if a business only dips into its overdraft for 10 days a month, it pays interest only for those 10 days on the exact deficit.","distractor_reasons":{"A":"Incorrect because overdrafts carry a *higher* annual interest rate than secured term loans.","B":"Correct selection.","C":"Incorrect because banks charge daily interest whenever an account is overdrawn.","D":"Incorrect because the business pays its own overdraft interest."}}},{"id":"P1_U5_MCQ_892","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_892","question":"A supplier offers '2% discount for immediate cash payment, or net 30 days'. Why does taking the full 30 days of 'trade credit' carry an implicit opportunity cost?","options":{"A":"Because the business must give up the 2% early-payment discount, paying a higher net price for the goods in exchange for keeping its cash for 30 days","B":"Because the supplier automatically cancels all future deliveries","C":"Because taking 30 days of trade credit increases the business's non-current liabilities","D":"Because the business must pay 20% bank interest to the supplier"},"correctOption":"A","correctAnswer":"Because the business must give up the 2% early-payment discount, paying a higher net price for the goods in exchange for keeping its cash for 30 days","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because although no explicit interest is billed during the 30-day window, forfeiting the 2% prompt-payment discount represents an implicit financing cost.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because paying within the agreed 30-day term respects the contract.","C":"Incorrect because 30-day supplier invoices are current liabilities (trade payables).","D":"Incorrect because suppliers do not charge 20% interest within normal credit terms."}}},{"id":"P1_U5_MCQ_893","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_893","question":"Why is a 'partnership' legally unable to raise expansion finance by issuing shares on a public stock exchange?","options":{"A":"Because partnerships are always loss-making businesses","B":"Because stock exchanges only accept businesses with fewer than five employees","C":"Because only incorporated public limited companies (plcs) can issue shares to the general public; partnerships are unincorporated and have no share capital","D":"Because partners have limited liability"},"correctOption":"C","correctAnswer":"Because only incorporated public limited companies (plcs) can issue shares to the general public; partnerships are unincorporated and have no share capital","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because legal structure dictates eligibility for equity finance: only plcs can float shares publicly.","distractor_reasons":{"A":"Incorrect because many professional partnerships (law, accounting) are highly profitable.","B":"Incorrect because stock-market listed plcs are large enterprises.","C":"Correct selection.","D":"Incorrect because general partners have unlimited liability, and share issuance requires incorporation as a plc."}}},{"id":"P1_U5_MCQ_894","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_894","question":"If a public limited company already has very high long-term debt relative to its equity ('high gearing'), why will directors likely prefer a 'rights issue of shares' over taking out another large bank loan?","options":{"A":"Because taking on more debt would further increase fixed interest obligations and default risk, whereas issuing shares strengthens the equity base without adding mandatory interest costs","B":"Because a rights issue requires zero administrative paperwork","C":"Because banks are legally banned from lending to public limited companies","D":"Because issuing shares reduces the company's current assets"},"correctOption":"A","correctAnswer":"Because taking on more debt would further increase fixed interest obligations and default risk, whereas issuing shares strengthens the equity base without adding mandatory interest costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because existing debt levels (gearing) constrain further borrowing capacity and push firms toward equity financing.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because share issues require formal legal documentation and shareholder approval.","C":"Incorrect because banks regularly lend to creditworthy plcs.","D":"Incorrect because issuing shares for cash *increases* current assets."}}},{"id":"P1_U5_MCQ_895","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_895","question":"Why is 'the amount of finance required' a decisive factor when choosing between a 'bank overdraft' and a 'public share issue'?","options":{"A":"A bank overdraft is suitable for small, temporary sums (e.g., $5,000), whereas the huge legal and underwriting fees of a public share issue only make financial sense when raising millions of dollars","B":"A bank overdraft can only be used for amounts above $10 million","C":"A public share issue is only allowed for raising less than $1,000","D":"Both sources cost the exact same amount in setup fees"},"correctOption":"A","correctAnswer":"A bank overdraft is suitable for small, temporary sums (e.g., $5,000), whereas the huge legal and underwriting fees of a public share issue only make financial sense when raising millions of dollars","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because high fixed transaction costs make public equity issues uneconomic for small sums, while bank limits cap overdraft size.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because overdrafts are small-to-medium short-term facilities.","C":"Incorrect because stock market flotations raise very large sums.","D":"Incorrect because an IPO costs millions in fees, whereas an overdraft has minimal arrangement fees."}}},{"id":"P1_U5_MCQ_896","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_896","question":"Why might a sole trader choose to admit a 'sleeping (silent) partner' rather than converting into a private limited company and selling 60% of the shares to outside investors?","options":{"A":"Because admitting a sleeping partner grants the sole trader limited liability","B":"Because a sleeping partner contributes capital and shares profits without taking part in day-to-day management, allowing the founder to keep operational control","C":"Because sleeping partners are forbidden from receiving any share of profits","D":"Because partnerships never pay income tax"},"correctOption":"B","correctAnswer":"Because a sleeping partner contributes capital and shares profits without taking part in day-to-day management, allowing the founder to keep operational control","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because selling 60% of voting shares surrenders majority control, whereas a sleeping partner injects equity capital while leaving management to the active partner.","distractor_reasons":{"A":"Incorrect because general partners still bear unlimited liability.","B":"Correct selection.","C":"Incorrect because sleeping partners receive an agreed share of business profits.","D":"Incorrect because partners pay personal income tax on their profit shares."}}},{"id":"P1_U5_MCQ_897","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_897","question":"What happens if a company defaults on repayments for a loan secured by 'collateral' (such as its freehold warehouse)?","options":{"A":"The bank has the legal right to seize and sell the pledged warehouse to recover the unpaid loan balance","B":"The bank must convert the unpaid loan into free ordinary shares","C":"The warehouse is automatically transferred to the company's customers","D":"The bank must lend the company an additional $1 million interest-free"},"correctOption":"A","correctAnswer":"The bank has the legal right to seize and sell the pledged warehouse to recover the unpaid loan balance","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because collateral protects the lender against default by granting a legal claim over specific assets.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because secured debt gives the lender asset repossession rights, not compulsory equity conversion.","C":"Incorrect because customers have no claim on collateralized assets.","D":"Incorrect because defaulting borrowers lose creditworthiness rather than receiving extra loans."}}},{"id":"P1_U5_MCQ_898","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_898","question":"How does 'peer-to-peer (P2P) business lending' differ from traditional commercial bank lending?","options":{"A":"P2P lending connects small businesses directly with individual and institutional lenders through an online platform rather than borrowing from a traditional bank's balance sheet","B":"P2P lending requires zero repayment of the borrowed principal","C":"P2P lending is operated exclusively by government tax offices","D":"P2P lending is an internal source of finance"},"correctOption":"A","correctAnswer":"P2P lending connects small businesses directly with individual and institutional lenders through an online platform rather than borrowing from a traditional bank's balance sheet","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because P2P debt crowdfunding disintermediates traditional banks by pooling smaller loans from online investors.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because P2P loans must be repaid with interest.","C":"Incorrect because P2P platforms are private financial technology intermediaries.","D":"Incorrect because P2P loans come from outside investors."}}},{"id":"P1_U5_MCQ_899","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_899","question":"What is a potential shareholder concern when a public limited company relies heavily on 'retained profit' year after year to fund expansion?","options":{"A":"Retained profit increases the company's fixed interest expenses","B":"Retaining more profit reduces immediate cash dividends paid out to shareholders, which may dissatisfy investors seeking regular dividend income","C":"Retained profit dilutes existing shareholders' voting percentages","D":"Retained profit forces the company to sell its factories"},"correctOption":"B","correctAnswer":"Retaining more profit reduces immediate cash dividends paid out to shareholders, which may dissatisfy investors seeking regular dividend income","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Profit after tax is split between dividends and retained profit; retaining more means paying out less today.","distractor_reasons":{"A":"Incorrect because retained profit is internal equity with zero interest.","B":"Correct selection.","C":"Incorrect because retained profit does not issue any new shares.","D":"Incorrect because retained profit keeps funds inside the business for investment."}}},{"id":"P1_U5_MCQ_900","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.1 Business finance","questionNumber":"P1_U5_MCQ_900","question":"A profitable, family-owned private limited company (Ltd) needs $400,000 to buy new CNC machinery lasting 8 years. The family refuses to share ownership control with outsiders and currently holds $150,000 in retained profit. Which financing combination is most suitable?","options":{"A":"Use $150,000 of retained profit plus a $250,000 medium-term commercial bank loan secured against the machinery/premises","B":"Use a $400,000 bank overdraft repayable on demand","C":"Float the company on the public stock exchange (IPO) to raise $400,000","D":"Use 30-day trade credit from office stationery suppliers"},"correctOption":"A","correctAnswer":"Use $150,000 of retained profit plus a $250,000 medium-term commercial bank loan secured against the machinery/premises","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because blending internal retained profit with a medium-term loan matches the 8-year asset life, avoids IPO costs, and preserves 100% family ownership.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because funding an 8-year machine with a recallable overdraft creates severe liquidity risk.","C":"Incorrect because an IPO dilutes family control and costs far too much for a $400,000 need.","D":"Incorrect because stationery suppliers do not supply or finance $400,000 CNC machines."}}},{"id":"P1_U5_MCQ_901","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_901","question":"What is the primary purpose of constructing a monthly 'cash flow forecast'?","options":{"A":"To estimate the exact timing and amounts of future cash inflows and outflows so managers can spot potential cash deficits in advance and arrange finance","B":"To calculate the exact corporation tax owed for the previous financial year","C":"To record the historical depreciation of freehold buildings","D":"To replace the statement of financial position required by company law"},"correctOption":"A","correctAnswer":"To estimate the exact timing and amounts of future cash inflows and outflows so managers can spot potential cash deficits in advance and arrange finance","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because forecasting monthly cash movements gives management early warning of liquidity shortfalls or idle cash surpluses.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because historical corporation tax is calculated from the statement of profit or loss.","C":"Incorrect because depreciation is a non-cash accounting charge excluded from cash flow forecasts.","D":"Incorrect because a cash flow forecast is an internal planning tool, not a replacement for statutory financial statements."}}},{"id":"P1_U5_MCQ_902","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_902","question":"A wholesaler forecasts $40,000 of total sales in March. Customers pay 25% immediately in cash and 75% on one month's trade credit. How much cash inflow from March sales will appear on the cash flow forecast in March and April respectively?","options":{"A":"$40,000 in March and $0 in April","B":"$10,000 in March and $30,000 in April","C":"$30,000 in March and $10,000 in April","D":"$0 in March and $40,000 in April"},"correctOption":"B","correctAnswer":"$10,000 in March and $30,000 in April","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because 25% of $40,000 ($10,000) enters the bank immediately in March, while 75% ($30,000) is received one month later in April.","distractor_reasons":{"A":"Incorrect because only 25% is paid in cash during March.","B":"Correct selection.","C":"Incorrect because this reverses the 25% cash and 75% credit portions.","D":"Incorrect because immediate cash sales generate $10,000 in March."}}},{"id":"P1_U5_MCQ_903","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_903","question":"In June, a business forecasts an opening cash balance of $15,000, total cash inflows of $62,000, and total cash outflows of $71,000. What are June's 'net cash flow' and 'closing cash balance'?","options":{"A":"Net cash flow: +$9,000; Closing cash balance: $24,000","B":"Net cash flow: -$9,000; Closing cash balance: -$9,000","C":"Net cash flow: -$9,000; Closing cash balance: $6,000","D":"Net cash flow: -$71,000; Closing cash balance: $6,000"},"correctOption":"C","correctAnswer":"Net cash flow: -$9,000; Closing cash balance: $6,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Net cash flow = $62,000 - $71,000 = -$9,000, and Closing cash balance = $15,000 + (-$9,000) = $6,000.","distractor_reasons":{"A":"Incorrect because outflows ($71,000) exceed inflows ($62,000), resulting in a negative net cash flow.","B":"Incorrect because it forgets to add the $15,000 opening cash balance to find the closing balance.","C":"Correct selection.","D":"Incorrect because -$71,000 is total outflows, not net cash flow."}}},{"id":"P1_U5_MCQ_904","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_904","question":"A start-up ends January with a closing cash balance of -$4,500 (an overdraft). In February, it forecasts cash inflows of $30,000 and cash outflows of $22,000. What is February's closing cash balance?","options":{"A":"+$8,000","B":"+$12,500","C":"-$12,500","D":"+$3,500"},"correctOption":"D","correctAnswer":"+$3,500","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because January's closing balance (-$4,500) becomes February's opening balance; adding February's net cash flow of +$8,000 ($30,000 - $22,000) yields +$3,500.","distractor_reasons":{"A":"Incorrect because +$8,000 is February's net cash flow before clearing the -$4,500 opening overdraft.","B":"Incorrect because it adds $4,500 instead of subtracting the -$4,500 opening overdraft.","C":"Incorrect because February has a positive net cash flow (+$8,000) that eliminates the overdraft.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_905","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_905","question":"In October, a business has an opening cash balance of $8,000, total cash inflows of $25,000, and a closing cash balance of $5,000. What were October's 'total cash outflows'?","options":{"A":"$28,000","B":"$22,000","C":"$33,000","D":"$3,000"},"correctOption":"A","correctAnswer":"$28,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the cash balance fell by $3,000 (from $8,000 to $5,000), meaning net cash flow was -$3,000, so Outflows = $25,000 + $3,000 = $28,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $22,000 outflows would leave a closing balance of $11,000 ($8,000 + $25,000 - $22,000).","C":"Incorrect because $33,000 is Opening balance + Inflows (which would leave $0 closing balance).","D":"Incorrect because $3,000 is the net cash deficit, not total cash outflows."}}},{"id":"P1_U5_MCQ_906","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_906","question":"Why is the annual 'depreciation charge' on machinery completely omitted from a cash flow forecast?","options":{"A":"Because machinery never loses value over time","B":"Because depreciation is a non-cash accounting adjustment rather than money physically leaving the bank account each month","C":"Because depreciation is recorded as a cash inflow","D":"Because limited companies are forbidden from calculating depreciation"},"correctOption":"B","correctAnswer":"Because depreciation is a non-cash accounting adjustment rather than money physically leaving the bank account each month","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the actual cash outflow occurred when the machine was paid for; subsequent depreciation entries involve zero cash movement.","distractor_reasons":{"A":"Incorrect because machinery wears out and loses value over its useful life.","B":"Correct selection.","C":"Incorrect because depreciation never brings cash into the business.","D":"Incorrect because companies must record depreciation on their statement of profit or loss."}}},{"id":"P1_U5_MCQ_907","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_907","question":"A printing company buys a $50,000 digital press in cash in April, expecting it to last 5 years ($10,000 annual depreciation). How does this purchase appear on April's cash flow forecast?","options":{"A":"As a $10,000 cash outflow in April","B":"As an $833 monthly cash outflow starting in April","C":"As a $50,000 cash outflow in April when the payment leaves the bank account","D":"It is omitted because non-current assets never appear on cash flow forecasts"},"correctOption":"C","correctAnswer":"As a $50,000 cash outflow in April when the payment leaves the bank account","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because cash flow forecasts record the full $50,000 cash payment in the exact month cash leaves the bank.","distractor_reasons":{"A":"Incorrect because $10,000 is annual depreciation for the income statement, not the cash paid in April.","B":"Incorrect because $833 is monthly depreciation, not the cash outflow.","C":"Correct selection.","D":"Incorrect because capital expenditure paid in cash is a major cash outflow."}}},{"id":"P1_U5_MCQ_908","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_908","question":"Why do 'seasonal businesses' (such as a beach resort or a firework manufacturer) rely heavily on cash flow forecasts?","options":{"A":"Because they incur months of heavy cash outflows for wages, maintenance, and stock buildup during off-peak seasons before peak tourist or holiday cash inflows arrive","B":"Because seasonal businesses never have any fixed overhead costs","C":"Because seasonal businesses are exempt from paying bank overdraft interest","D":"Because seasonal businesses receive identical cash inflows every single week of the year"},"correctOption":"A","correctAnswer":"Because they incur months of heavy cash outflows for wages, maintenance, and stock buildup during off-peak seasons before peak tourist or holiday cash inflows arrive","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because seasonal mismatches between steady outflows and concentrated inflows require pre-arranged overdrafts or cash reserves.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because rent, insurance, and core staff salaries continue year-round.","C":"Incorrect because seasonal firms pay commercial overdraft rates.","D":"Incorrect because seasonal demand fluctuates sharply across the year."}}},{"id":"P1_U5_MCQ_909","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_909","question":"What is 'overtrading' in business finance?","options":{"A":"Selling products below cost price to drive competitors out of the market","B":"Expanding sales and production volume too rapidly without sufficient working capital, causing cash outflows for materials and wages to outstrip delayed receipts from credit customers","C":"Holding excessive idle cash in a bank deposit account","D":"Paying off all non-current liabilities ahead of schedule"},"correctOption":"B","correctAnswer":"Expanding sales and production volume too rapidly without sufficient working capital, causing cash outflows for materials and wages to outstrip delayed receipts from credit customers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because overtrading occurs when fast growth drains liquid cash faster than credit customers pay, risking insolvency despite strong order books.","distractor_reasons":{"A":"Incorrect because selling below cost is predatory pricing, not overtrading.","B":"Correct selection.","C":"Incorrect because overtrading is characterized by a severe *shortage* of liquid cash.","D":"Incorrect because overtrading strains short-term working capital rather than early debt retirement."}}},{"id":"P1_U5_MCQ_910","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_910","question":"When an entrepreneur applies for a $30,000 overdraft limit, what specific information does the bank manager look for inside the 'cash flow forecast'?","options":{"A":"The exact market value of the entrepreneur's personal jewellery","B":"The company's historical gross profit margin from five years ago","C":"The maximum negative closing cash balance (to verify $30,000 is enough) and the specific future months when positive net cash flows will bring the account back into credit","D":"The names and home addresses of all retail customers"},"correctOption":"C","correctAnswer":"The maximum negative closing cash balance (to verify $30,000 is enough) and the specific future months when positive net cash flows will bring the account back into credit","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because banks check both peak borrowing need (to prevent under-funding) and the borrower's capacity to clear the overdraft.","distractor_reasons":{"A":"Incorrect because personal items are not listed in a business cash flow forecast.","B":"Incorrect because cash flow forecasts are forward-looking cash schedules, not historical income statements.","C":"Correct selection.","D":"Incorrect because forecasts summarize aggregate monthly inflows rather than customer directories."}}},{"id":"P1_U5_MCQ_911","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_911","question":"If a business negotiates to extend its 'supplier credit period' from 30 days to 60 days to relieve a forecast cash deficit, what is a potential negative consequence?","options":{"A":"The business's cash inflows will immediately drop to zero","B":"The business will have to pay higher corporation tax immediately","C":"The business's non-current assets will lose half their value","D":"Suppliers may refuse the extension, withdraw early-payment discounts, raise prices, or prioritize rival buyers who pay faster"},"correctOption":"D","correctAnswer":"Suppliers may refuse the extension, withdraw early-payment discounts, raise prices, or prioritize rival buyers who pay faster","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because stretching trade payables improves short-term cash flow only if suppliers agree without damaging supply reliability or pricing.","distractor_reasons":{"A":"Incorrect because supplier credit affects outflows, not customer inflows.","B":"Incorrect because extending payable terms does not increase corporation tax.","C":"Incorrect because supplier terms have no effect on non-current asset values.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_912","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_912","question":"Which action directly speeds up 'cash inflows' to resolve a temporary cash shortage without taking on new debt?","options":{"A":"Chasing overdue trade receivables more aggressively or using a debt factoring agency to unlock cash from unpaid invoices","B":"Buying extra raw materials in bulk for cash","C":"Increasing cash dividends paid to shareholders","D":"Giving credit customers an extra 60 days to pay their bills"},"correctOption":"A","correctAnswer":"Chasing overdue trade receivables more aggressively or using a debt factoring agency to unlock cash from unpaid invoices","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because accelerating receivable collections brings cash into the bank faster without borrowing.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because buying bulk stock increases immediate cash outflows.","C":"Incorrect because paying higher dividends increases cash outflows.","D":"Incorrect because lengthening customer credit delays cash inflows further."}}},{"id":"P1_U5_MCQ_913","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_913","question":"Why is 'postponing planned non-essential capital expenditure' (such as delaying the upgrade of office computers or company cars) an effective short-term cash flow remedy?","options":{"A":"Because it eliminates a large lump-sum cash outflow during the deficit month without disrupting existing daily production","B":"Because it doubles monthly sales revenue immediately","C":"Because it converts current liabilities into shareholders' equity","D":"Because it forces customers to pay cash in advance"},"correctOption":"A","correctAnswer":"Because it eliminates a large lump-sum cash outflow during the deficit month without disrupting existing daily production","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because deferring discretionary equipment upgrades preserves vital cash until liquidity improves.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because delaying office upgrades does not double sales revenue.","C":"Incorrect because postponing spending does not alter liabilities or equity.","D":"Incorrect because capital spending decisions do not change customer payment terms."}}},{"id":"P1_U5_MCQ_914","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_914","question":"How does running a short-term 'clearance sale' on slow-moving warehouse inventory help a business facing a cash flow crunch?","options":{"A":"It increases the book value of non-current assets","B":"It converts stagnant stock into immediate cash inflows and reduces storage costs, even though selling at discounted prices lowers gross profit margin","C":"It increases trade payables owed to suppliers","D":"It eliminates all fixed overhead costs for the rest of the year"},"correctOption":"B","correctAnswer":"It converts stagnant stock into immediate cash inflows and reduces storage costs, even though selling at discounted prices lowers gross profit margin","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because during a liquidity emergency, generating immediate cash from excess inventory takes priority over maximizing profit margin.","distractor_reasons":{"A":"Incorrect because clearance sales sell current asset inventory, not non-current assets.","B":"Correct selection.","C":"Incorrect because selling existing stock does not increase supplier debts.","D":"Incorrect because fixed overheads still continue."}}},{"id":"P1_U5_MCQ_915","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_915","question":"Why is 'delaying payment of employee wages' NOT a viable strategy for solving a forecast cash flow deficit?","options":{"A":"Because employee wages are never included as cash outflows","B":"Because delaying wages is a breach of employment contracts and labor laws that destroys morale, triggers strikes or resignations, and halts operations","C":"Because delaying wages automatically increases corporation tax rates","D":"Because employee wages are paid by the company's customers directly"},"correctOption":"B","correctAnswer":"Because delaying wages is a breach of employment contracts and labor laws that destroys morale, triggers strikes or resignations, and halts operations","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because payroll is a legally binding priority obligation; non-payment rapidly destroys the business's workforce and reputation.","distractor_reasons":{"A":"Incorrect because wages are one of the largest regular cash outflows.","B":"Correct selection.","C":"Incorrect because tax rates are set by statute, not wage timing.","D":"Incorrect because the employer pays wages out of its own bank account."}}},{"id":"P1_U5_MCQ_916","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_916","question":"A company receives a $100,000 long-term bank loan into its current account in July. What is the immediate effect on July's 'cash flow' and July's 'operating profit'?","options":{"A":"Cash inflow increases by $100,000, while operating profit is completely unchanged","B":"Both cash inflow and operating profit increase by $100,000","C":"Cash inflow is unchanged, while operating profit increases by $100,000","D":"Cash outflow increases by $100,000, while operating profit falls by $100,000"},"correctOption":"A","correctAnswer":"Cash inflow increases by $100,000, while operating profit is completely unchanged","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because borrowing money brings cash into the bank (+cash inflow) and creates a loan liability, which is not trading revenue.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because loan proceeds are debt financing, not earned profit.","C":"Incorrect because receiving loan funds directly increases cash inflows.","D":"Incorrect because receiving a loan brings cash *in*, rather than sending cash out."}}},{"id":"P1_U5_MCQ_917","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_917","question":"A retailer buys $18,000 of inventory on two months' trade credit in May. In which months does this purchase affect the retailer's 'cash flow forecast'?","options":{"A":"$18,000 cash outflow in May","B":"$9,000 cash outflow in May and $9,000 in June","C":"$0 cash outflow in May and June, and $18,000 cash outflow in July when the supplier invoice is paid","D":"$18,000 cash inflow in July"},"correctOption":"C","correctAnswer":"$0 cash outflow in May and June, and $18,000 cash outflow in July when the supplier invoice is paid","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because cash flow forecasts record cash movements only when money actually leaves the bank account (two months after May = July).","distractor_reasons":{"A":"Incorrect because the goods were bought on 2-month credit rather than cash.","B":"Incorrect because the payment is due in full after two months (July), not split.","C":"Correct selection.","D":"Incorrect because paying a supplier is a cash outflow, not an inflow."}}},{"id":"P1_U5_MCQ_918","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_918","question":"How does comparing 'actual monthly cash flows' against 'forecast monthly cash flows' improve financial control?","options":{"A":"It automatically cancels all supplier debts if actual outflows are higher than forecast","B":"It enables managers to spot adverse variances early (such as slower customer collections or rising utility bills) and take corrective action before cash runs out","C":"It eliminates the need to prepare an annual statement of profit or loss","D":"It guarantees that next month's sales will double"},"correctOption":"B","correctAnswer":"It enables managers to spot adverse variances early (such as slower customer collections or rising utility bills) and take corrective action before cash runs out","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because monitoring forecast vs actual cash variances turns a static document into an active management control tool.","distractor_reasons":{"A":"Incorrect because legal supplier debts remain payable.","B":"Correct selection.","C":"Incorrect because statutory financial statements are still required.","D":"Incorrect because variance monitoring diagnoses problems rather than guaranteeing sales growth."}}},{"id":"P1_U5_MCQ_919","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_919","question":"Why can external macroeconomic changes (such as an unexpected central bank interest rate hike or currency depreciation) make a 12-month cash flow forecast inaccurate?","options":{"A":"Because external shocks increase variable loan interest payments and imported raw material outflows above the figures assumed when the forecast was written","B":"Because external shocks change historical opening cash balances from last year","C":"Because businesses are forbidden from updating cash flow forecasts during the year","D":"Because external shocks eliminate all current liabilities"},"correctOption":"A","correctAnswer":"Because external shocks increase variable loan interest payments and imported raw material outflows above the figures assumed when the forecast was written","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cash flow forecasts rely on assumptions about external prices and rates that can shift unexpectedly.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because past opening balances are fixed historical facts.","C":"Incorrect because managers should prepare rolling updates whenever assumptions change.","D":"Incorrect because macroeconomic shifts do not erase existing debts."}}},{"id":"P1_U5_MCQ_920","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_920","question":"What behavioral bias often causes new entrepreneurs to produce overly optimistic 'cash flow forecasts'?","options":{"A":"Overestimating how fast customers will buy and pay while underestimating unexpected start-up delays and overhead costs","B":"Assuming sales revenue will be zero for the first five years","C":"Multiplying all expected expenses by ten","D":"Recording share capital as a monthly cash outflow"},"correctOption":"A","correctAnswer":"Overestimating how fast customers will buy and pay while underestimating unexpected start-up delays and overhead costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because entrepreneur optimism bias frequently leads to over-projected early inflows and under-budgeted costs, causing unexpected cash shortfalls.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because over-optimism exaggerates sales rather than assuming zero sales.","C":"Incorrect because over-optimistic forecasts underestimate rather than exaggerate expenses.","D":"Incorrect because share capital injected is a cash inflow."}}},{"id":"P1_U5_MCQ_921","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_921","question":"What is the 'working capital cycle' in a manufacturing business?","options":{"A":"The 25-year lifespan of a freehold factory building","B":"The continuous time lag between paying cash for raw materials, manufacturing and storing finished goods, selling on credit, and finally collecting cash from customers","C":"The annual election of company directors at the AGM","D":"The process of issuing new shares on a stock exchange"},"correctOption":"B","correctAnswer":"The continuous time lag between paying cash for raw materials, manufacturing and storing finished goods, selling on credit, and finally collecting cash from customers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the shorter the working capital cycle, the faster cash returns to the bank and the smaller the risk of liquidity shortages.","distractor_reasons":{"A":"Incorrect because buildings are long-term non-current assets.","B":"Correct selection.","C":"Incorrect because director elections relate to corporate governance, not cash cycles.","D":"Incorrect because share flotation is long-term equity financing."}}},{"id":"P1_U5_MCQ_922","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_922","question":"How does choosing to 'lease' delivery vans instead of buying them outright for cash improve a start-up's early cash flow forecast?","options":{"A":"It eliminates all cash outflows for vehicles permanently","B":"It turns vehicle rental payments into cash inflows","C":"It avoids a massive initial cash outflow in Month 1, replacing it with smaller, predictable monthly lease outflows that preserve working capital","D":"It increases the start-up's non-current assets on Day 1"},"correctOption":"C","correctAnswer":"It avoids a massive initial cash outflow in Month 1, replacing it with smaller, predictable monthly lease outflows that preserve working capital","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because spreading vehicle costs via leasing prevents draining the start-up's cash cushion upfront.","distractor_reasons":{"A":"Incorrect because monthly lease rentals are still cash outflows.","B":"Incorrect because lease payments leave the bank as outflows.","C":"Correct selection.","D":"Incorrect because leased assets remain owned by the leasing company."}}},{"id":"P1_U5_MCQ_923","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_923","question":"How is 'corporation tax' recorded on a limited company's monthly cash flow forecast?","options":{"A":"It is omitted completely because taxes are non-cash expenses","B":"It is recorded as a cash inflow from the government","C":"It is deducted from gross profit every week","D":"It is recorded as a cash outflow in the specific month when the tax payment actually leaves the company's bank account"},"correctOption":"D","correctAnswer":"It is recorded as a cash outflow in the specific month when the tax payment actually leaves the company's bank account","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because tax payments represent real cash outflows in the month remitted to tax authorities.","distractor_reasons":{"A":"Incorrect because taxes are paid in cash.","B":"Incorrect because profitable companies pay tax *out* to the government.","C":"Incorrect because cash flow forecasts track monthly cash movements, not weekly gross profit.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_924","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_924","question":"When a company makes a $2,500 monthly bank loan payment consisting of $1,800 principal repayment and $700 interest, how much appears as a 'cash outflow' on the cash flow forecast?","options":{"A":"The full $2,500 payment, because the entire $2,500 leaves the bank account in cash","B":"Only the $700 interest portion","C":"Only the $1,800 principal portion","D":"$0, because bank loans are excluded from cash flow forecasts"},"correctOption":"A","correctAnswer":"The full $2,500 payment, because the entire $2,500 leaves the bank account in cash","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because both principal repayment and interest leave the bank account in cash (whereas only the $700 interest is an expense on the income statement).","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the $1,800 principal repayment also leaves the bank in cash.","C":"Incorrect because the $700 interest charge also leaves the bank in cash.","D":"Incorrect because all debt service payments are cash outflows."}}},{"id":"P1_U5_MCQ_925","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.2 Cash flow forecast","questionNumber":"P1_U5_MCQ_925","question":"Which scenario best illustrates how a profitable company can still collapse due to 'cash flow insolvency'?","options":{"A":"A company sells all goods for immediate cash and keeps low overheads","B":"A construction company wins huge profitable contracts on 90-day customer credit, spends all its cash upfront on materials and wages, and cannot pay its own overdue bills before customer payments arrive","C":"A software firm holds $5 million in cash and has zero debt","D":"A retailer sells inventory faster than its 60-day supplier credit period"},"correctOption":"B","correctAnswer":"A construction company wins huge profitable contracts on 90-day customer credit, spends all its cash upfront on materials and wages, and cannot pay its own overdue bills before customer payments arrive","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because profits tied up in uncollected trade receivables cannot pay immediate wages and supplier bills, triggering insolvency.","distractor_reasons":{"A":"Incorrect because immediate cash sales and low overheads produce strong cash flow.","B":"Correct selection.","C":"Incorrect because large cash reserves and zero debt ensure high solvency.","D":"Incorrect because collecting cash from buyers before paying suppliers generates positive cash flow."}}},{"id":"P1_U5_MCQ_926","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_926","question":"A clothing retailer starts the year with opening inventory worth $14,000, buys $86,000 of new stock during the year, and holds $18,000 of closing inventory at year-end. What is its 'cost of sales'?","options":{"A":"$100,000","B":"$82,000","C":"$90,000","D":"$118,000"},"correctOption":"B","correctAnswer":"$82,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Cost of sales = Opening inventory ($14,000) + Purchases ($86,000) - Closing inventory ($18,000) = $82,000.","distractor_reasons":{"A":"Incorrect because $100,000 forgets to subtract the $18,000 unsold closing inventory.","B":"Correct selection.","C":"Incorrect because $90,000 adds closing inventory ($18,000) and subtracts opening inventory ($14,000).","D":"Incorrect because $118,000 adds all three figures together instead of subtracting closing inventory."}}},{"id":"P1_U5_MCQ_927","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_927","question":"A furniture maker records annual sales revenue of $210,000, cost of sales of $135,000, and overhead expenses of $42,000. What is its 'gross profit'?","options":{"A":"$33,000","B":"$93,000","C":"$75,000","D":"$168,000"},"correctOption":"C","correctAnswer":"$75,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Gross profit = Revenue ($210,000) - Cost of sales ($135,000) = $75,000 (overheads are deducted later to find operating profit).","distractor_reasons":{"A":"Incorrect because $33,000 is operating profit ($75,000 - $42,000), not gross profit.","B":"Incorrect because $93,000 subtracts overheads instead of cost of sales.","C":"Correct selection.","D":"Incorrect because $168,000 subtracts overheads from revenue."}}},{"id":"P1_U5_MCQ_928","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_928","question":"A logistics company achieves a gross profit of $90,000 and incurs indirect overhead expenses of $54,000 during the year. What is its 'operating profit'?","options":{"A":"$144,000","B":"$90,000","C":"$54,000","D":"$36,000"},"correctOption":"D","correctAnswer":"$36,000","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Operating profit = Gross profit ($90,000) - Overhead expenses ($54,000) = $36,000.","distractor_reasons":{"A":"Incorrect because overhead expenses must be subtracted from gross profit, not added.","B":"Incorrect because $90,000 is gross profit before deducting overheads.","C":"Incorrect because $54,000 is the overhead expense figure.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_929","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_929","question":"A limited company reports operating profit of $50,000, loan interest of $6,000, a corporation tax rate of 25% on profit before tax, and dividends paid of $13,000. What is its 'retained profit' for the year?","options":{"A":"$20,000","B":"$33,000","C":"$44,000","D":"$31,000"},"correctOption":"A","correctAnswer":"$20,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Profit before tax = $50,000 - $6,000 = $44,000; Tax (25% of $44,000) = $11,000; Profit after tax = $33,000; Retained profit = $33,000 - $13,000 = $20,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because $33,000 is profit after tax before deducting the $13,000 dividends.","C":"Incorrect because $44,000 is profit before tax.","D":"Incorrect because $31,000 forgets to deduct the $11,000 corporation tax."}}},{"id":"P1_U5_MCQ_930","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_930","question":"If a business's cost of sales is $64,000 and its gross profit is $36,000, what was its 'sales revenue'?","options":{"A":"$28,000","B":"$100,000","C":"$64,000","D":"$36,000"},"correctOption":"B","correctAnswer":"$100,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Revenue - Cost of sales = Gross profit, so Revenue = Cost of sales ($64,000) + Gross profit ($36,000) = $100,000.","distractor_reasons":{"A":"Incorrect because subtracting gross profit from cost of sales gives $28,000 instead of total revenue.","B":"Correct selection.","C":"Incorrect because $64,000 is cost of sales alone.","D":"Incorrect because $36,000 is gross profit alone."}}},{"id":"P1_U5_MCQ_931","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_931","question":"A trader had opening inventory of $10,000, made purchases of $55,000 during the year, and recorded a cost of sales of $52,000. What was the value of 'closing inventory' at year-end?","options":{"A":"$7,000","B":"$3,000","C":"$13,000","D":"$65,000"},"correctOption":"C","correctAnswer":"$13,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Goods available for sale = $10,000 + $55,000 = $65,000; subtracting Cost of sales ($52,000) leaves Closing inventory of $13,000.","distractor_reasons":{"A":"Incorrect because $7,000 subtracts opening inventory instead of adding it.","B":"Incorrect because $3,000 ignores the $10,000 opening inventory.","C":"Correct selection.","D":"Incorrect because $65,000 is total goods available for sale before deducting cost of sales."}}},{"id":"P1_U5_MCQ_932","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_932","question":"If an accounting error causes a business to 'overvalue its closing inventory' at year-end, how does this distort its statement of profit or loss for that year?","options":{"A":"Cost of sales is understated, which artificially inflates both gross profit and operating profit","B":"Cost of sales is overstated, which artificially reduces gross profit","C":"Sales revenue is reduced by the amount of closing inventory","D":"It has zero effect on gross profit or operating profit"},"correctOption":"A","correctAnswer":"Cost of sales is understated, which artificially inflates both gross profit and operating profit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Closing inventory is subtracted in Cost of sales; subtracting a larger number lowers Cost of sales and raises reported profit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a higher closing inventory reduces rather than increases cost of sales.","C":"Incorrect because inventory valuation affects cost of sales, not sales revenue.","D":"Incorrect because closing inventory directly enters the cost of sales calculation."}}},{"id":"P1_U5_MCQ_933","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_933","question":"How are 'carriage inwards' (delivery charges paid to bring purchased raw materials into the factory) treated differently from 'carriage outwards' (delivery charges to ship finished goods to customers)?","options":{"A":"Both are added to sales revenue","B":"Carriage inwards is included in cost of sales (reducing gross profit), whereas carriage outwards is recorded as a distribution overhead expense below gross profit","C":"Carriage inwards is a non-current asset, whereas carriage outwards is a current liability","D":"Carriage inwards is deducted after tax, whereas carriage outwards is deducted from revenue"},"correctOption":"B","correctAnswer":"Carriage inwards is included in cost of sales (reducing gross profit), whereas carriage outwards is recorded as a distribution overhead expense below gross profit","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because inward freight is part of acquiring inventory for production/resale (cost of sales), while outward delivery is a selling/distribution overhead.","distractor_reasons":{"A":"Incorrect because both are business costs, not revenue.","B":"Correct selection.","C":"Incorrect because delivery charges are operating costs, not balance sheet assets or liabilities.","D":"Incorrect because both are deducted before operating profit."}}},{"id":"P1_U5_MCQ_934","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_934","question":"When a retailer returns damaged inventory back to its wholesale supplier ('purchase returns'), how is this recorded when calculating 'cost of sales'?","options":{"A":"It is added to sales revenue","B":"It is added to purchases, increasing cost of sales","C":"It is subtracted from purchases to show net purchases actually kept by the business","D":"It is recorded under overhead expenses"},"correctOption":"C","correctAnswer":"It is subtracted from purchases to show net purchases actually kept by the business","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because returning goods to suppliers cancels that purchase cost, lowering net purchases and cost of sales.","distractor_reasons":{"A":"Incorrect because returning stock to a supplier is not a sale to a customer.","B":"Incorrect because purchase returns reduce rather than increase net purchases.","C":"Correct selection.","D":"Incorrect because purchase returns adjust purchases inside cost of sales."}}},{"id":"P1_U5_MCQ_935","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_935","question":"In a commercial bakery, which pair of costs belongs inside 'cost of sales' rather than 'overhead expenses'?","options":{"A":"High-street retail shop rent and local radio advertising","B":"Accountant's annual audit fee and head-office telephone bills","C":"Flour, yeast, sugar, and piece-rate wages of bakers directly making bread","D":"Delivery van insurance and managing director's fixed annual salary"},"correctOption":"C","correctAnswer":"Flour, yeast, sugar, and piece-rate wages of bakers directly making bread","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because direct ingredients and direct production labor vary with output and form cost of sales.","distractor_reasons":{"A":"Incorrect because shop rent and advertising are indirect overhead expenses.","B":"Incorrect because audit fees and office phone bills are administrative overheads.","C":"Correct selection.","D":"Incorrect because vehicle insurance and executive salaries are fixed indirect overheads."}}},{"id":"P1_U5_MCQ_936","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_936","question":"If a company switches to a cheaper commercial electricity supplier and saves $15,000 per year on head-office lighting and heating, what happens on its statement of profit or loss?","options":{"A":"Gross profit stays unchanged, while overhead expenses fall by $15,000 and operating profit rises by $15,000","B":"Gross profit rises by $15,000, while operating profit stays unchanged","C":"Sales revenue rises by $15,000","D":"Cost of sales falls by $15,000"},"correctOption":"A","correctAnswer":"Gross profit stays unchanged, while overhead expenses fall by $15,000 and operating profit rises by $15,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because head-office electricity is an indirect overhead deducted *after* gross profit, so saving on overheads leaves gross profit unaffected while raising operating profit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because gross profit is calculated before deducting office overheads.","C":"Incorrect because lower utility bills do not increase sales revenue.","D":"Incorrect because head-office utilities are overheads, not direct cost of sales."}}},{"id":"P1_U5_MCQ_937","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_937","question":"If a manufacturer negotiates a 10% bulk discount on direct raw materials while keeping selling prices and overheads constant, how does this affect its statement of profit or loss?","options":{"A":"Cost of sales falls, causing BOTH gross profit and operating profit to increase","B":"Gross profit falls, while operating profit rises","C":"Only retained profit changes, while gross profit and operating profit stay identical","D":"Overhead expenses increase by 10%"},"correctOption":"A","correctAnswer":"Cost of sales falls, causing BOTH gross profit and operating profit to increase","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cheaper direct materials reduce cost of sales, immediately raising gross profit and flowing down into higher operating profit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because lower cost of sales increases gross profit.","C":"Incorrect because gross profit and operating profit both rise first.","D":"Incorrect because direct raw materials are in cost of sales, not overheads."}}},{"id":"P1_U5_MCQ_938","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_938","question":"How does profit act as a 'performance indicator' for a company's board of directors?","options":{"A":"It measures whether the company has enough cash in the till to pay today's lunch bill","B":"It summarizes how effectively management has priced products, generated revenue, and controlled costs compared with previous years and industry rivals","C":"It shows the exact market value of the company's freehold land","D":"It measures how many hours employees worked overtime"},"correctOption":"B","correctAnswer":"It summarizes how effectively management has priced products, generated revenue, and controlled costs compared with previous years and industry rivals","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because profit aggregates the financial outcome of marketing, pricing, and operational cost control.","distractor_reasons":{"A":"Incorrect because daily till cash is tracked via cash management, not annual profit.","B":"Correct selection.","C":"Incorrect because property values are recorded on the statement of financial position.","D":"Incorrect because labor hours are operational HR metrics."}}},{"id":"P1_U5_MCQ_939","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_939","question":"How does profit serve directly as a 'source of finance' for business expansion?","options":{"A":"By being retained inside the business after tax and dividends to fund new equipment, R&D, or market entry without debt interest","B":"By forcing suppliers to lend money to the business","C":"By reducing the business's issued share capital","D":"By automatically paying off all non-current liabilities overnight"},"correctOption":"A","correctAnswer":"By being retained inside the business after tax and dividends to fund new equipment, R&D, or market entry without debt interest","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because retained profit is the primary internal source of long-term capital for established enterprises.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because suppliers do not lend cash based on a buyer's profit.","C":"Incorrect because retained profit adds to equity reserves without reducing share capital.","D":"Incorrect because retained profit is an equity reserve rather than an automatic debt repayment."}}},{"id":"P1_U5_MCQ_940","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_940","question":"Why do investors often tolerate a planned 'net loss' on a tech start-up's statement of profit or loss during its first year of trading?","options":{"A":"Because start-ups are legally prohibited from earning a profit in Year 1","B":"Because heavy upfront launch marketing, software R&D, and fixed overheads are incurred before customer sales volume scales up to break-even levels","C":"Because start-ups never record sales revenue on their income statement","D":"Because making a loss exempts the start-up from paying employee wages"},"correctOption":"B","correctAnswer":"Because heavy upfront launch marketing, software R&D, and fixed overheads are incurred before customer sales volume scales up to break-even levels","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because early-stage businesses intentionally invest in customer acquisition and infrastructure ahead of scale-driven profitability.","distractor_reasons":{"A":"Incorrect because start-ups are welcome to make profits immediately if revenue exceeds costs.","B":"Correct selection.","C":"Incorrect because all earned revenue is recorded on the income statement.","D":"Incorrect because wages remain legally payable regardless of profit or loss."}}},{"id":"P1_U5_MCQ_941","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_941","question":"If a company has a large variable-rate bank loan and market interest rates rise sharply, which lines on its statement of profit or loss are directly affected?","options":{"A":"Gross profit and operating profit fall immediately","B":"Sales revenue and cost of sales fall immediately","C":"Operating profit stays unchanged, while finance costs (interest) rise, reducing profit before tax, profit after tax, and retained profit","D":"Only dividends paid to shareholders increase"},"correctOption":"C","correctAnswer":"Operating profit stays unchanged, while finance costs (interest) rise, reducing profit before tax, profit after tax, and retained profit","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because interest is deducted *after* operating profit (profit before interest and tax), squeezing bottom-line profit.","distractor_reasons":{"A":"Incorrect because interest is a financing cost excluded from gross profit and operating profit.","B":"Incorrect because loan interest rates do not directly change revenue or cost of sales.","C":"Correct selection.","D":"Incorrect because lower profit after tax reduces funds available for dividends."}}},{"id":"P1_U5_MCQ_942","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_942","question":"If the government raises the national 'corporation tax rate' from 20% to 25%, how does this impact a profitable company's statement of profit or loss?","options":{"A":"Gross profit, operating profit, and profit before tax remain unchanged, while the tax deduction increases, reducing profit after tax and retained profit","B":"Gross profit falls by 5%","C":"Operating profit falls by 5%","D":"Cost of sales increases by 5%"},"correctOption":"A","correctAnswer":"Gross profit, operating profit, and profit before tax remain unchanged, while the tax deduction increases, reducing profit after tax and retained profit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because corporation tax is levied on profit before tax, leaving all trading profit lines above it unaffected.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because gross profit is before tax.","C":"Incorrect because operating profit is profit before interest and tax.","D":"Incorrect because corporation tax is not part of cost of sales."}}},{"id":"P1_U5_MCQ_943","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_943","question":"Why do 'government tax authorities' examine a limited company's statement of profit or loss?","options":{"A":"To verify revenue, deductible expenses, and profit before tax so they can calculate and collect the accurate amount of corporation tax owed","B":"To decide which products the company should stop selling","C":"To set the salary of the company's marketing manager","D":"To check the company's acid-test liquidity ratio"},"correctOption":"A","correctAnswer":"To verify revenue, deductible expenses, and profit before tax so they can calculate and collect the accurate amount of corporation tax owed","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because statutory income statements provide the verified profit base for corporate taxation.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because product portfolio decisions belong to company management.","C":"Incorrect because executive pay is set by the company's remuneration committee.","D":"Incorrect because tax authorities assess tax liability rather than short-term liquidity ratios."}}},{"id":"P1_U5_MCQ_944","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_944","question":"Why do 'employees and trade unions' examine an employer's statement of profit or loss?","options":{"A":"To calculate the market value of the company's freehold land","B":"To assess whether the business is profitable enough to guarantee job security and afford wage increases or performance bonuses","C":"To determine how much corporation tax the government should charge","D":"To approve the company's bank overdraft limit"},"correctOption":"B","correctAnswer":"To assess whether the business is profitable enough to guarantee job security and afford wage increases or performance bonuses","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because sustained losses threaten redundancies, while strong profits strengthen union arguments for pay rises.","distractor_reasons":{"A":"Incorrect because property values are not shown on the statement of profit or loss.","B":"Correct selection.","C":"Incorrect because tax rates are set by the government.","D":"Incorrect because banks approve overdraft facilities."}}},{"id":"P1_U5_MCQ_945","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_945","question":"Why do 'competitors' examine the published statements of profit or loss of a rival public limited company (plc)?","options":{"A":"To benchmark their own revenue growth, gross profit margins, and cost efficiency against an industry rival","B":"To legally force the rival plc to reduce its dividend payouts","C":"To audit the rival plc's inventory warehouse in person","D":"To pay the rival plc's corporation tax bill"},"correctOption":"A","correctAnswer":"To benchmark their own revenue growth, gross profit margins, and cost efficiency against an industry rival","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because published annual reports give rivals valuable competitive intelligence on relative margins and scale.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because competitors have no legal authority over a rival's dividends.","C":"Incorrect because external auditors inspect inventory, not competitors.","D":"Incorrect because each company pays its own tax."}}},{"id":"P1_U5_MCQ_946","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_946","question":"Under accrual accounting, when is a $25,000 credit sale delivered in December (with customer payment due in February) recorded on the statement of profit or loss?","options":{"A":"In February when cash arrives in the bank","B":"In December when the goods are delivered and invoiced, because revenue is recognized when earned rather than when cash is collected","C":"Split 50% in December and 50% in February","D":"It is omitted until the customer buys a second order"},"correctOption":"B","correctAnswer":"In December when the goods are delivered and invoiced, because revenue is recognized when earned rather than when cash is collected","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because accrual accounting matches earned revenue to the period of sale regardless of credit collection timing.","distractor_reasons":{"A":"Incorrect because February is when the cash inflow appears on the cash flow statement, whereas revenue was earned in December.","B":"Correct selection.","C":"Incorrect because revenue is recognized in full upon delivery/invoicing.","D":"Incorrect because all valid credit sales are recorded when earned."}}},{"id":"P1_U5_MCQ_947","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_947","question":"When a business determines that a $4,000 customer invoice is completely uncollectible ('irrecoverable bad debt') and writes it off, how does this affect its statement of profit or loss?","options":{"A":"It is recorded as an expense, reducing operating profit by $4,000","B":"It is added to gross profit","C":"It increases retained profit by $4,000","D":"It has zero effect on profit because the sale was already recorded earlier"},"correctOption":"A","correctAnswer":"It is recorded as an expense, reducing operating profit by $4,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because writing off a bad debt recognizes the loss of an expected receivable as an operating expense.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a bad debt is a loss/expense, not profit.","C":"Incorrect because lower operating profit reduces retained profit.","D":"Incorrect because because the revenue was recorded earlier, failing to collect the cash requires an expense write-off to correct profit."}}},{"id":"P1_U5_MCQ_948","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_948","question":"Why are a sole trader's personal 'drawings' NOT deducted as an expense on the statement of profit or loss?","options":{"A":"Because sole traders never pay taxes","B":"Because drawings are a personal withdrawal of owner's equity (recorded on the statement of financial position), not a business operating cost incurred to earn revenue","C":"Because drawings are added to sales revenue","D":"Because drawings are classified as non-current assets"},"correctOption":"B","correctAnswer":"Because drawings are a personal withdrawal of owner's equity (recorded on the statement of financial position), not a business operating cost incurred to earn revenue","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because deducting personal drawings as an expense would artificially understate true business trading profit.","distractor_reasons":{"A":"Incorrect because sole traders pay income tax on business profits.","B":"Correct selection.","C":"Incorrect because drawings reduce owner's capital, not add to revenue.","D":"Incorrect because drawings are equity reductions, not assets."}}},{"id":"P1_U5_MCQ_949","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_949","question":"If a bakery sells an old delivery van for $8,000 (which equals its exact Net Book Value), why is the $8,000 NOT included inside 'sales revenue' at the top of the statement of profit or loss?","options":{"A":"Because sales revenue only records income from selling the business's trading goods or services (bread and cakes), whereas disposing of a non-current asset is a capital transaction","B":"Because selling a van is illegal for a bakery","C":"Because the $8,000 is recorded as an overhead expense","D":"Because the $8,000 is recorded as a current liability"},"correctOption":"A","correctAnswer":"Because sales revenue only records income from selling the business's trading goods or services (bread and cakes), whereas disposing of a non-current asset is a capital transaction","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because mixing one-off asset disposal proceeds into trading revenue would distort gross profit margin and sales trends.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because businesses routinely sell surplus equipment.","C":"Incorrect because selling an asset at book value is neither an expense nor trading revenue.","D":"Incorrect because cash received from selling an owned asset is not a debt owed."}}},{"id":"P1_U5_MCQ_950","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.3 Profit and loss","questionNumber":"P1_U5_MCQ_950","question":"Which sequence shows the correct top-to-bottom order of lines on a limited company's 'statement of profit or loss'?","options":{"A":"Revenue → Cost of sales → Gross profit → Overhead expenses → Operating profit → Interest → Profit before tax → Corporation tax → Profit after tax → Dividends → Retained profit","B":"Revenue → Overhead expenses → Gross profit → Cost of sales → Operating profit → Dividends → Corporation tax → Retained profit","C":"Gross profit → Revenue → Cost of sales → Corporation tax → Operating profit → Dividends → Retained profit","D":"Revenue → Cost of sales → Operating profit → Gross profit → Dividends → Interest → Retained profit"},"correctOption":"A","correctAnswer":"Revenue → Cost of sales → Gross profit → Overhead expenses → Operating profit → Interest → Profit before tax → Corporation tax → Profit after tax → Dividends → Retained profit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because it follows standard international presentation from top-line trading revenue down to final retained profit.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because cost of sales is deducted before gross profit, and tax is deducted before dividends.","C":"Incorrect because revenue comes first, and tax is deducted after operating profit and interest.","D":"Incorrect because gross profit comes before operating profit, and interest/tax come before dividends."}}},{"id":"P1_U5_MCQ_951","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_951","question":"A business reports inventories of $22,000, trade receivables of $18,000, cash at bank of $5,000, trade payables of $20,000, and a bank overdraft of $7,000. What is its 'working capital (net current assets)'?","options":{"A":"$45,000","B":"$18,000","C":"$27,000","D":"$32,000"},"correctOption":"B","correctAnswer":"$18,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Current assets = $22,000 + $18,000 + $5,000 = $45,000; Current liabilities = $20,000 + $7,000 = $27,000; Working capital = $45,000 - $27,000 = $18,000.","distractor_reasons":{"A":"Incorrect because $45,000 is total current assets before subtracting current liabilities.","B":"Correct selection.","C":"Incorrect because $27,000 is total current liabilities.","D":"Incorrect because $32,000 adds the $7,000 bank overdraft instead of subtracting it."}}},{"id":"P1_U5_MCQ_952","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_952","question":"On its statement of financial position, a company has non-current assets of $150,000, current assets of $60,000, current liabilities of $25,000, and non-current liabilities of $45,000. What are its 'net assets'?","options":{"A":"$210,000","B":"$185,000","C":"$140,000","D":"$35,000"},"correctOption":"C","correctAnswer":"$140,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Net assets = Total assets ($150,000 + $60,000 = $210,000) - Total liabilities ($25,000 + $45,000 = $70,000) = $140,000.","distractor_reasons":{"A":"Incorrect because $210,000 is total assets before deducting liabilities.","B":"Incorrect because $185,000 forgets to subtract the $45,000 non-current liabilities.","C":"Correct selection.","D":"Incorrect because $35,000 is working capital ($60,000 - $25,000), not total net assets."}}},{"id":"P1_U5_MCQ_953","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_953","question":"A limited company has issued share capital of $100,000, retained profit reserves of $40,000, non-current liabilities of $45,000, and current liabilities of $25,000. What is its 'capital employed'?","options":{"A":"$140,000","B":"$210,000","C":"$100,000","D":"$185,000"},"correctOption":"D","correctAnswer":"$185,000","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Capital employed = Total shareholders' equity ($100,000 + $40,000 = $140,000) + Non-current liabilities ($45,000) = $185,000 (current liabilities are excluded).","distractor_reasons":{"A":"Incorrect because $140,000 is shareholders' equity alone without non-current liabilities.","B":"Incorrect because $210,000 mistakenly includes $25,000 of short-term current liabilities.","C":"Incorrect because $100,000 is issued share capital alone.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_954","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_954","question":"A sole trader begins the financial year with opening capital of $50,000, earns a profit for the year of $24,000, and takes personal drawings of $14,000. What is the sole trader's 'closing capital' on the statement of financial position?","options":{"A":"$60,000","B":"$88,000","C":"$74,000","D":"$40,000"},"correctOption":"A","correctAnswer":"$60,000","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Closing capital = Opening capital ($50,000) + Profit for the year ($24,000) - Drawings ($14,000) = $60,000.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because drawings must be subtracted rather than added.","C":"Incorrect because $74,000 forgets to subtract the $14,000 drawings.","D":"Incorrect because $40,000 subtracts profit instead of adding it."}}},{"id":"P1_U5_MCQ_955","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_955","question":"A factory bought CNC machinery three years ago for $80,000 and has recorded accumulated depreciation of $32,000 to date. At what 'Net Book Value' is the machinery shown on the statement of financial position?","options":{"A":"$112,000","B":"$48,000","C":"$80,000","D":"$32,000"},"correctOption":"B","correctAnswer":"$48,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Net Book Value = Original cost ($80,000) - Accumulated depreciation ($32,000) = $48,000.","distractor_reasons":{"A":"Incorrect because accumulated depreciation is subtracted from cost, not added.","B":"Correct selection.","C":"Incorrect because $80,000 is original historical cost before depreciation.","D":"Incorrect because $32,000 is the depreciation deducted so far."}}},{"id":"P1_U5_MCQ_956","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_956","question":"How are a '$12,000 bank overdraft' and a '$90,000 five-year bank loan' presented on a statement of financial position?","options":{"A":"Both are presented under non-current liabilities","B":"The bank overdraft is a current asset, while the five-year loan is a non-current liability","C":"The bank overdraft is presented under current liabilities, while the five-year loan is presented under non-current liabilities","D":"Both are presented under shareholders' equity"},"correctOption":"C","correctAnswer":"The bank overdraft is presented under current liabilities, while the five-year loan is presented under non-current liabilities","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because an overdraft is a short-term obligation repayable within 12 months, whereas a 5-year loan is a long-term debt.","distractor_reasons":{"A":"Incorrect because an overdraft is short-term, not non-current.","B":"Incorrect because a negative bank overdraft is money owed to the bank (a liability), not an asset.","C":"Correct selection.","D":"Incorrect because both are external bank debts, not owner equity."}}},{"id":"P1_U5_MCQ_957","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_957","question":"Which group consists entirely of 'intangible non-current assets'?","options":{"A":"Freehold land, factory buildings, and delivery vans","B":"Inventories, trade receivables, and cash at bank","C":"Trade payables, bank overdrafts, and unpaid taxes","D":"Purchased goodwill, registered patents, copyrights, and acquired brand trademarks"},"correctOption":"D","correctAnswer":"Purchased goodwill, registered patents, copyrights, and acquired brand trademarks","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because these are long-term assets lacking physical substance that confer legal or commercial rights over more than one year.","distractor_reasons":{"A":"Incorrect because land, buildings, and vans are tangible physical non-current assets.","B":"Incorrect because inventories, receivables, and cash are current assets.","C":"Incorrect because payables, overdrafts, and unpaid taxes are current liabilities.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_958","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_958","question":"Which group consists entirely of 'tangible non-current assets'?","options":{"A":"Factory premises, assembly line machinery, office computers, and commercial trucks","B":"Patents, copyrights, and purchased goodwill","C":"Raw material inventory, work-in-progress, and finished goods","D":"Issued share capital, debentures, and retained profit"},"correctOption":"A","correctAnswer":"Factory premises, assembly line machinery, office computers, and commercial trucks","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because these are physical long-term operational assets held for use for more than 12 months.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because patents, copyrights, and goodwill are intangible non-current assets.","C":"Incorrect because inventories are current assets.","D":"Incorrect because share capital, debentures, and retained profit are financing items (equity and non-current liabilities)."}}},{"id":"P1_U5_MCQ_959","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_959","question":"In what standard order are 'current assets' listed on a statement of financial position, moving from least liquid to most liquid?","options":{"A":"Cash at bank → Trade receivables → Inventories","B":"Inventories → Trade receivables → Cash at bank and in hand","C":"Trade receivables → Inventories → Cash at bank","D":"Inventories → Cash at bank → Trade receivables"},"correctOption":"B","correctAnswer":"Inventories → Trade receivables → Cash at bank and in hand","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because inventories take longest to turn into cash, followed by trade receivables, with cash already in liquid form at the bottom.","distractor_reasons":{"A":"Incorrect because this lists from most liquid to least liquid.","B":"Correct selection.","C":"Incorrect because inventories are less liquid than trade receivables.","D":"Incorrect because trade receivables are less liquid than cash at bank."}}},{"id":"P1_U5_MCQ_960","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_960","question":"Why are 'inventories' considered the least liquid of all current assets?","options":{"A":"Because inventories are legally prohibited from being sold for 10 years","B":"Because inventories are owed to commercial banks","C":"Because converting inventories into cash requires two uncertain steps: first finding buyers to sell the goods, and then waiting for credit customers to pay their invoices","D":"Because inventories have zero monetary value on the balance sheet"},"correctOption":"C","correctAnswer":"Because converting inventories into cash requires two uncertain steps: first finding buyers to sell the goods, and then waiting for credit customers to pay their invoices","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because unsold stock may suffer slow demand, obsolescence, or price discounting before ever turning into cash.","distractor_reasons":{"A":"Incorrect because inventories are held specifically for short-term sale.","B":"Incorrect because inventories are owned assets (unless pledged as collateral).","C":"Correct selection.","D":"Incorrect because inventories are valued at cost (or net realizable value if lower)."}}},{"id":"P1_U5_MCQ_961","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_961","question":"A retailer buys $12,000 of inventory on 30-day trade credit. What is the immediate effect on the retailer's statement of financial position?","options":{"A":"Current assets (inventories) increase by $12,000 and current liabilities (trade payables) increase by $12,000, leaving working capital unchanged","B":"Working capital increases by $12,000","C":"Non-current assets increase by $12,000 and equity increases by $12,000","D":"Current assets decrease by $12,000 and current liabilities increase by $12,000"},"correctOption":"A","correctAnswer":"Current assets (inventories) increase by $12,000 and current liabilities (trade payables) increase by $12,000, leaving working capital unchanged","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Current assets and Current liabilities both rise by $12,000, leaving Current assets - Current liabilities unchanged.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because the rise in trade payables offsets the rise in inventories.","C":"Incorrect because inventory is a current asset and trade credit is a current liability.","D":"Incorrect because receiving new inventory *increases* current assets."}}},{"id":"P1_U5_MCQ_962","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_962","question":"When a credit customer pays a $9,000 invoice by bank transfer, how does this transaction affect the seller's statement of financial position?","options":{"A":"Total current assets increase by $9,000","B":"Cash at bank increases by $9,000 and trade receivables decrease by $9,000, leaving total current assets and working capital unchanged","C":"Current liabilities decrease by $9,000","D":"Shareholders' equity increases by $9,000"},"correctOption":"B","correctAnswer":"Cash at bank increases by $9,000 and trade receivables decrease by $9,000, leaving total current assets and working capital unchanged","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because collecting a receivable merely swaps one current asset (receivables) for another (cash), improving liquidity quality without changing total current assets.","distractor_reasons":{"A":"Incorrect because trade receivables drop by $9,000 at the same time cash rises by $9,000.","B":"Correct selection.","C":"Incorrect because a customer paying us affects current assets, not current liabilities.","D":"Incorrect because profit/equity was already recognized when the credit sale occurred."}}},{"id":"P1_U5_MCQ_963","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_963","question":"A company borrows $50,000 via a 5-year bank loan and holds the proceeds in its bank current account. What happens to its 'working capital' and 'net assets' immediately?","options":{"A":"Working capital is unchanged, while net assets increase by $50,000","B":"Both working capital and net assets decrease by $50,000","C":"Working capital increases by $50,000 (because cash rises while current liabilities stay unchanged), while net assets remain unchanged (because non-current liabilities also rose by $50,000)","D":"Both working capital and net assets increase by $50,000"},"correctOption":"C","correctAnswer":"Working capital increases by $50,000 (because cash rises while current liabilities stay unchanged), while net assets remain unchanged (because non-current liabilities also rose by $50,000)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Current assets (+$50,000 cash) rise without any increase in Current liabilities (+working capital), while the $50,000 Non-current liability keeps Net assets constant.","distractor_reasons":{"A":"Incorrect because cash is a current asset while the 5-year loan is non-current, so working capital rises.","B":"Incorrect because receiving cash increases working capital.","C":"Correct selection.","D":"Incorrect because borrowing money adds a $50,000 liability, leaving net assets unchanged."}}},{"id":"P1_U5_MCQ_964","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_964","question":"When a limited company retains $30,000 of its after-tax profit at year-end rather than paying it out as dividends, how is this reflected on its statement of financial position?","options":{"A":"Non-current liabilities increase by $30,000","B":"Current liabilities increase by $30,000","C":"Issued share capital decreases by $30,000","D":"Retained profit reserves inside shareholders' equity increase by $30,000, increasing total equity and net assets"},"correctOption":"D","correctAnswer":"Retained profit reserves inside shareholders' equity increase by $30,000, increasing total equity and net assets","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because retained profit belongs to the shareholders and builds up internal equity reserves.","distractor_reasons":{"A":"Incorrect because retained profit is internal equity, not an external loan.","B":"Incorrect because retained profit is not a short-term debt.","C":"Incorrect because retaining profit does not reduce issued share capital.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_965","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_965","question":"What does a 'negative working capital' figure (where current liabilities exceed current assets) on a manufacturing firm's statement of financial position warn analysts about?","options":{"A":"The manufacturer may struggle to pay its short-term debts and supplier bills over the next 12 months without arranging emergency finance or selling non-current assets","B":"The manufacturer has too much idle cash sitting in the bank","C":"The manufacturer has zero non-current assets","D":"The manufacturer's gross profit margin is above 80%"},"correctOption":"A","correctAnswer":"The manufacturer may struggle to pay its short-term debts and supplier bills over the next 12 months without arranging emergency finance or selling non-current assets","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because negative working capital means short-term obligations exceed short-term liquid resources.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because negative working capital signals a cash/current-asset *shortage*, not excess cash.","C":"Incorrect because working capital compares current assets and current liabilities only.","D":"Incorrect because working capital is a liquidity measure, not gross profit margin."}}},{"id":"P1_U5_MCQ_966","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_966","question":"Why can large 'supermarket chains' operate comfortably with very low—or even slightly negative—working capital without facing a liquidity crisis?","options":{"A":"Because supermarkets never buy inventory from suppliers","B":"Because supermarkets sell groceries rapidly for immediate cash/card payment every day, collecting cash from shoppers weeks before their 30–60 day supplier trade payables fall due","C":"Because supermarkets are exempt from paying current liabilities","D":"Because supermarkets record all groceries as non-current assets"},"correctOption":"B","correctAnswer":"Because supermarkets sell groceries rapidly for immediate cash/card payment every day, collecting cash from shoppers weeks before their 30–60 day supplier trade payables fall due","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because ultra-fast inventory turnover combined with immediate cash sales lets supermarkets fund operations using supplier trade credit.","distractor_reasons":{"A":"Incorrect because supermarkets purchase massive volumes of stock daily.","B":"Correct selection.","C":"Incorrect because supermarkets pay all supplier bills on agreed credit terms.","D":"Incorrect because groceries held for sale are current asset inventories."}}},{"id":"P1_U5_MCQ_967","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_967","question":"How do 'existing shareholders' use a company's statement of financial position?","options":{"A":"To check the growth in net asset value (shareholders' equity) and see how the company's assets are financed between owners' funds and external debt","B":"To calculate the exact hourly wage rate of factory cleaners","C":"To track daily customer footfall in retail stores","D":"To set government interest rates"},"correctOption":"A","correctAnswer":"To check the growth in net asset value (shareholders' equity) and see how the company's assets are financed between owners' funds and external debt","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the statement of financial position shows the net wealth owned by shareholders and the company's capital structure.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because individual wage rates are not reported on the balance sheet.","C":"Incorrect because customer footfall is an operational marketing metric.","D":"Incorrect because central banks set interest rates."}}},{"id":"P1_U5_MCQ_968","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_968","question":"Why does a company considering a 'takeover' of a rival inspect the target firm's statement of financial position closely before making an offer?","options":{"A":"To see the exact value of property, patents, inventory, and cash it will acquire, as well as the existing short-term and long-term debts it will inherit","B":"To verify the target firm's advertising slogans from ten years ago","C":"To calculate the national inflation rate","D":"To avoid paying corporation tax after the takeover"},"correctOption":"A","correctAnswer":"To see the exact value of property, patents, inventory, and cash it will acquire, as well as the existing short-term and long-term debts it will inherit","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because acquiring a business means taking over both its assets and its outstanding liabilities.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because advertising slogans are not recorded on the statement of financial position.","C":"Incorrect because inflation is a macroeconomic statistic.","D":"Incorrect because merged companies still pay corporation tax on profits."}}},{"id":"P1_U5_MCQ_969","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_969","question":"Why must 'Net assets (Total assets minus Total liabilities)' ALWAYS equal 'Total equity' on a correctly prepared statement of financial position?","options":{"A":"Because double-entry accounting ensures that whatever residual asset value remains after paying off all external creditor claims belongs entirely to the owners (equity)","B":"Because businesses are legally forbidden from taking out loans","C":"Because current assets always equal current liabilities","D":"Because non-current assets are always worth $0"},"correctOption":"A","correctAnswer":"Because double-entry accounting ensures that whatever residual asset value remains after paying off all external creditor claims belongs entirely to the owners (equity)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Assets = Liabilities + Equity rearranges directly to Assets - Liabilities = Equity.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because liabilities are subtracted from total assets in the equation.","C":"Incorrect because current assets and current liabilities rarely equal each other.","D":"Incorrect because non-current assets have positive Net Book Values."}}},{"id":"P1_U5_MCQ_970","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_970","question":"If a business pays $6,000 in advance for next year's warehouse insurance ('prepaid expense') before the reporting date, how is that $6,000 shown on the statement of financial position?","options":{"A":"As a current liability","B":"As a non-current liability","C":"As a current asset (other receivable / prepayment), because the business has already paid for a service benefit it will receive within the next 12 months","D":"As issued share capital"},"correctOption":"C","correctAnswer":"As a current asset (other receivable / prepayment), because the business has already paid for a service benefit it will receive within the next 12 months","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a prepayment represents a short-term economic benefit owed to the business over the coming year.","distractor_reasons":{"A":"Incorrect because unpaid bills owed *by* the business are liabilities, whereas prepaid bills are assets.","B":"Incorrect because annual insurance covers the next 12 months, making it current.","C":"Correct selection.","D":"Incorrect because prepayments are operational current assets, not owner share capital."}}},{"id":"P1_U5_MCQ_971","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_971","question":"Why does 'issued share capital' on a public limited company's statement of financial position rarely match the company's total 'stock market value (market capitalization)'?","options":{"A":"Because issued share capital records the original nominal/issue value paid to the company when shares were first sold, whereas market capitalization reflects the current fluctuating share price traded between investors on the stock exchange","B":"Because stock exchange share prices are fixed permanently by the government","C":"Because issued share capital is recorded under current liabilities","D":"Because public limited companies never issue shares"},"correctOption":"A","correctAnswer":"Because issued share capital records the original nominal/issue value paid to the company when shares were first sold, whereas market capitalization reflects the current fluctuating share price traded between investors on the stock exchange","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because secondary stock market trading changes share prices based on future profit expectations without changing the historical share capital figure on the company's books.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because stock market prices fluctuate continuously with supply and demand.","C":"Incorrect because issued share capital is part of shareholders' equity.","D":"Incorrect because plcs raise equity by issuing shares."}}},{"id":"P1_U5_MCQ_972","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_972","question":"How does 'retained profit' on the statement of financial position differ from 'retained profit' on the statement of profit or loss?","options":{"A":"The statement of profit or loss shows the profit retained from *that single year*, whereas the statement of financial position shows the *cumulative total* of all undistributed profits accumulated over the company's entire history","B":"Both statements always show the exact same dollar figure even for a 20-year-old company","C":"The statement of financial position shows retained profit as a current liability","D":"The statement of profit or loss excludes dividends before calculating retained profit"},"correctOption":"A","correctAnswer":"The statement of profit or loss shows the profit retained from *that single year*, whereas the statement of financial position shows the *cumulative total* of all undistributed profits accumulated over the company's entire history","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because each year's retained profit flow adds to the cumulative retained profit reserve on the balance sheet.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because for a multi-year company, cumulative reserves equal prior years' reserves plus the current year's retained profit.","C":"Incorrect because retained profit is shareholders' equity.","D":"Incorrect because dividends are deducted from profit after tax to arrive at annual retained profit."}}},{"id":"P1_U5_MCQ_973","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_973","question":"What is 'window dressing' as a limitation when analyzing a company's statement of financial position?","options":{"A":"Decorating retail shop windows to attract Christmas shoppers","B":"Taking short-term actions right before the year-end reporting date (such as delaying supplier payments or holding back equipment purchases) to make cash and liquidity look temporarily stronger than normal","C":"Hiring external auditors to verify inventory counts","D":"Revaluing freehold property upwards after an independent survey"},"correctOption":"B","correctAnswer":"Taking short-term actions right before the year-end reporting date (such as delaying supplier payments or holding back equipment purchases) to make cash and liquidity look temporarily stronger than normal","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a single year-end snapshot can be manipulated through temporary timing tactics right around the reporting date.","distractor_reasons":{"A":"Incorrect because in accounting, 'window dressing' refers to cosmetic presentation of year-end financial positions.","B":"Correct selection.","C":"Incorrect because external audits aim to *prevent* misleading financial reporting.","D":"Incorrect because formal independent revaluation follows accounting standards rather than short-term cash manipulation."}}},{"id":"P1_U5_MCQ_974","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_974","question":"Why can two competitors owning identical machinery of the exact same age and condition show different 'non-current asset Net Book Values' on their statements of financial position?","options":{"A":"Because one company is allowed to omit machinery from its balance sheet","B":"Because one company records machinery under current liabilities","C":"Because one company may have estimated a shorter useful lifespan (recording higher annual depreciation) than the other, lowering its book value faster","D":"Because machinery never depreciates in limited companies"},"correctOption":"C","correctAnswer":"Because one company may have estimated a shorter useful lifespan (recording higher annual depreciation) than the other, lowering its book value faster","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Net Book Value depends on accounting depreciation estimates rather than real-time second-hand market valuations.","distractor_reasons":{"A":"Incorrect because all owned operational machinery must be recorded.","B":"Incorrect because owned machinery is always a non-current asset.","C":"Correct selection.","D":"Incorrect because all companies depreciate machinery over its useful life."}}},{"id":"P1_U5_MCQ_975","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.4 Statement of financial position","questionNumber":"P1_U5_MCQ_975","question":"Which accounting link directly connects a limited company's 'statement of profit or loss' to its 'statement of financial position' at the end of the financial year?","options":{"A":"Gross profit is added directly to cash at bank","B":"Sales revenue is added directly to issued share capital","C":"Cost of sales is added directly to non-current liabilities","D":"The retained profit earned during the year (from the bottom of the statement of profit or loss) is added to the retained profit reserve inside shareholders' equity on the statement of financial position"},"correctOption":"D","correctAnswer":"The retained profit earned during the year (from the bottom of the statement of profit or loss) is added to the retained profit reserve inside shareholders' equity on the statement of financial position","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because undistributed profit earned over the year increases the owners' cumulative equity stake in the business.","distractor_reasons":{"A":"Incorrect because gross profit is not equal to bank cash.","B":"Incorrect because sales revenue does not increase share capital.","C":"Incorrect because cost of sales is an income statement cost, not a long-term debt.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_976","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_976","question":"A retailer reports annual sales revenue of $160,000 and gross profit of $48,000. What is its 'gross profit margin'?","options":{"A":"30%","B":"70%","C":"42.9%","D":"3.33%"},"correctOption":"A","correctAnswer":"30%","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Gross profit margin = ($48,000 / $160,000) × 100 = 30%.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because 70% ($112,000 / $160,000) is the cost-of-sales-to-revenue ratio.","C":"Incorrect because 42.9% ($48,000 / $112,000) is mark-up on cost of sales rather than gross profit margin on revenue.","D":"Incorrect because 3.33 is Revenue divided by Gross profit ($160,000 / $48,000)."}}},{"id":"P1_U5_MCQ_977","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_977","question":"An engineering firm records annual sales revenue of $180,000, gross profit of $72,000, and operating profit of $27,000. What is its 'profit margin'?","options":{"A":"40%","B":"15%","C":"37.5%","D":"25%"},"correctOption":"B","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Profit margin = (Operating profit / Revenue) × 100 = ($27,000 / $180,000) × 100 = 15%.","distractor_reasons":{"A":"Incorrect because 40% ($72,000 / $180,000) is the gross profit margin.","B":"Correct selection.","C":"Incorrect because 37.5% divides operating profit by gross profit ($27,000 / $72,000) instead of revenue.","D":"Incorrect because 25% ($45,000 / $180,000) is overhead expenses as a percentage of revenue."}}},{"id":"P1_U5_MCQ_978","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_978","question":"A company generates an operating profit of $45,000 using shareholders' equity of $200,000 and non-current liabilities of $100,000. What is its 'Return on Capital Employed (ROCE)'?","options":{"A":"22.5%","B":"45%","C":"15%","D":"10%"},"correctOption":"C","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Capital employed = $200,000 + $100,000 = $300,000; ROCE = ($45,000 / $300,000) × 100 = 15%.","distractor_reasons":{"A":"Incorrect because 22.5% ($45,000 / $200,000) omits the $100,000 non-current liabilities from capital employed.","B":"Incorrect because 45% divides by $100,000 non-current liabilities alone.","C":"Correct selection.","D":"Incorrect because 10% ($45,000 / $450,000) miscalculates capital employed."}}},{"id":"P1_U5_MCQ_979","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_979","question":"A business holds current assets of $90,000 (including $36,000 of inventories) and owes current liabilities of $60,000. What is its 'current ratio'?","options":{"A":"0.9 : 1","B":"0.67 : 1","C":"2.1 : 1","D":"1.5 : 1"},"correctOption":"D","correctAnswer":"1.5 : 1","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Current ratio = Current assets ($90,000) / Current liabilities ($60,000) = 1.5 : 1.","distractor_reasons":{"A":"Incorrect because 0.9 : 1 is the acid-test ratio after subtracting inventories.","B":"Incorrect because 0.67 : 1 inverts current liabilities and current assets ($60,000 / $90,000).","C":"Incorrect because 2.1 : 1 adds inventories ($90,000 + $36,000) instead of recognizing they are already inside current assets.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_980","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_980","question":"Using the same business figures—current assets of $90,000, inventories of $36,000, and current liabilities of $60,000—what is its 'acid-test (quick) ratio'?","options":{"A":"0.9 : 1","B":"1.5 : 1","C":"0.6 : 1","D":"1.11 : 1"},"correctOption":"A","correctAnswer":"0.9 : 1","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Acid-test ratio = ($90,000 - $36,000) / $60,000 = $54,000 / $60,000 = 0.9 : 1.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because 1.5 : 1 is the current ratio before excluding inventories.","C":"Incorrect because 0.6 : 1 divides inventories ($36,000) by current liabilities ($60,000).","D":"Incorrect because 1.11 : 1 divides current liabilities by quick assets ($60,000 / $54,000)."}}},{"id":"P1_U5_MCQ_981","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_981","question":"A company reports annual sales revenue of $250,000 and achieves a 'profit margin' of 12%. What was its 'operating profit' in dollars?","options":{"A":"$20,833","B":"$30,000","C":"$220,000","D":"$12,000"},"correctOption":"B","correctAnswer":"$30,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Operating profit = 12% × $250,000 = 0.12 × $250,000 = $30,000.","distractor_reasons":{"A":"Incorrect because $20,833 divides $250,000 by 12 instead of multiplying by 0.12.","B":"Correct selection.","C":"Incorrect because $220,000 is total costs ($250,000 - $30,000).","D":"Incorrect because $12,000 treats 12% as a fixed dollar sum."}}},{"id":"P1_U5_MCQ_982","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_982","question":"If a company earns an operating profit of $54,000 and achieves a 'Return on Capital Employed (ROCE)' of 18%, what is its total 'capital employed'?","options":{"A":"$9,720","B":"$540,000","C":"$300,000","D":"$360,000"},"correctOption":"C","correctAnswer":"$300,000","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because ROCE = Operating profit / Capital employed, so Capital employed = $54,000 / 0.18 = $300,000.","distractor_reasons":{"A":"Incorrect because $9,720 multiplies $54,000 by 0.18 instead of dividing.","B":"Incorrect because $540,000 corresponds to a 10% ROCE.","C":"Correct selection.","D":"Incorrect because $360,000 corresponds to a 15% ROCE."}}},{"id":"P1_U5_MCQ_983","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_983","question":"What does an unusually high 'current ratio' of 4.2 : 1 suggest to a financial analyst?","options":{"A":"The business is on the verge of immediate bankruptcy","B":"The business has zero current assets","C":"The business is guaranteed to have the highest ROCE in its industry","D":"While short-term debt coverage is very safe, the business is holding excessive idle cash, bloated inventory, or slow-paying receivables that could be invested more productively"},"correctOption":"D","correctAnswer":"While short-term debt coverage is very safe, the business is holding excessive idle cash, bloated inventory, or slow-paying receivables that could be invested more productively","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because typical healthy current ratios sit around 1.5 : 1 to 2 : 1; ratios above 3 : 1 or 4 : 1 signal inefficient working capital use.","distractor_reasons":{"A":"Incorrect because a ratio below 1 : 1 signals liquidity danger, not 4.2 : 1.","B":"Incorrect because 4.2 : 1 means current assets are 4.2 times larger than current liabilities.","C":"Incorrect because idle working capital actually lowers ROCE.","D":"Correct selection."}}},{"id":"P1_U5_MCQ_984","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_984","question":"A fashion retailer has a 'current ratio' of 1.8 : 1, but its 'acid-test ratio' is only 0.5 : 1. What does this large gap reveal?","options":{"A":"Most of the retailer's current assets are tied up in unsold clothing inventory, leaving insufficient liquid cash and receivables to pay short-term bills if seasonal fashion stock fails to sell quickly","B":"The retailer holds zero clothing inventory","C":"The retailer has zero current liabilities","D":"The retailer's operating profit margin is 180%"},"correctOption":"A","correctAnswer":"Most of the retailer's current assets are tied up in unsold clothing inventory, leaving insufficient liquid cash and receivables to pay short-term bills if seasonal fashion stock fails to sell quickly","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the difference between the current ratio and acid-test ratio is driven entirely by inventory levels.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because zero inventory would make both ratios equal.","C":"Incorrect because current liabilities are positive in both ratios.","D":"Incorrect because liquidity ratios do not measure profit margins."}}},{"id":"P1_U5_MCQ_985","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_985","question":"What is a potential drawback of trying to boost 'gross profit margin' by switching to cheaper raw-material suppliers?","options":{"A":"Direct cost of sales will increase immediately","B":"Lower-quality materials may cause higher product defect rates, customer returns, and damage to brand reputation, ultimately hurting future sales","C":"Head-office rent will automatically double","D":"The company will be forced to pay higher corporation tax rates"},"correctOption":"B","correctAnswer":"Lower-quality materials may cause higher product defect rates, customer returns, and damage to brand reputation, ultimately hurting future sales","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because cutting input costs improves unit margin only if product quality and customer loyalty are maintained.","distractor_reasons":{"A":"Incorrect because cheaper raw materials *lower* cost of sales.","B":"Correct selection.","C":"Incorrect because raw-material sourcing does not affect office rent.","D":"Incorrect because tax rates are set by statute."}}},{"id":"P1_U5_MCQ_986","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_986","question":"How can a business increase its 'profit margin (%)' without making any change to its 'gross profit margin (%)'?","options":{"A":"By raising product selling prices by 15%","B":"By negotiating cheaper wholesale prices on inventory for resale","C":"By reducing indirect overhead expenses (such as downsizing expensive head-office space or automating administrative paperwork)","D":"By holding larger amounts of closing inventory"},"correctOption":"C","correctAnswer":"By reducing indirect overhead expenses (such as downsizing expensive head-office space or automating administrative paperwork)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because indirect overheads sit between gross profit and operating profit; cutting overheads lifts profit margin while leaving gross profit margin unchanged.","distractor_reasons":{"A":"Incorrect because raising selling prices increases gross profit margin as well.","B":"Incorrect because cheaper inventory reduces cost of sales and raises gross profit margin.","C":"Correct selection.","D":"Incorrect because holding more inventory increases storage overheads."}}},{"id":"P1_U5_MCQ_987","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_987","question":"Over a single year, a manufacturer's 'gross profit margin' rises from 35% to 40%, yet its 'profit margin' falls from 14% to 9%. What is the most logical explanation?","options":{"A":"Direct production/material costs fell relative to sales, but indirect overhead expenses (such as heavy advertising campaigns or head-office salaries) increased even more sharply","B":"Sales revenue fell to zero during the year","C":"The company paid off all its non-current liabilities","D":"Current liabilities exceeded current assets"},"correctOption":"A","correctAnswer":"Direct production/material costs fell relative to sales, but indirect overhead expenses (such as heavy advertising campaigns or head-office salaries) increased even more sharply","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because gross profit margin reflects direct costs, whereas profit margin also reflects indirect overhead expenses.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because zero sales would eliminate both margins.","C":"Incorrect because paying off long-term debt reduces future interest rather than lowering operating profit margin.","D":"Incorrect because liquidity ratios do not cause gross and operating margins to diverge."}}},{"id":"P1_U5_MCQ_988","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_988","question":"Which action will directly improve BOTH a business's 'current ratio' and its 'acid-test ratio'?","options":{"A":"Buying extra raw materials on 30-day trade credit","B":"Using existing bank cash to buy a new freehold factory","C":"Selling surplus, unused non-current machinery for cash and keeping the cash in the bank account","D":"Paying cash dividends to ordinary shareholders"},"correctOption":"C","correctAnswer":"Selling surplus, unused non-current machinery for cash and keeping the cash in the bank account","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because selling a non-current asset for cash increases cash (raising both Current assets and Quick assets) without increasing current liabilities.","distractor_reasons":{"A":"Incorrect because buying inventory on credit raises inventories (excluded from acid-test) and raises current liabilities.","B":"Incorrect because spending cash on a building reduces cash and lowers both liquidity ratios.","C":"Correct selection.","D":"Incorrect because paying cash dividends drains bank cash and lowers both liquidity ratios."}}},{"id":"P1_U5_MCQ_989","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_989","question":"Which action improves a retailer's 'acid-test ratio' while leaving its 'current ratio' completely unchanged?","options":{"A":"Selling $15,000 of inventory at cost price for immediate cash","B":"Taking out a $50,000 long-term bank loan","C":"Issuing $100,000 of new ordinary shares for cash","D":"Buying $20,000 of new delivery vehicles for cash"},"correctOption":"A","correctAnswer":"Selling $15,000 of inventory at cost price for immediate cash","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because swapping $15,000 of inventory for $15,000 of cash leaves total Current assets unchanged (same current ratio), while increasing quick assets (cash) in the acid-test ratio.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because a long-term loan for cash increases *both* the current ratio and acid-test ratio.","C":"Incorrect because issuing shares for cash increases *both* the current ratio and acid-test ratio.","D":"Incorrect because spending cash on vehicles reduces *both* the current ratio and acid-test ratio."}}},{"id":"P1_U5_MCQ_990","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_990","question":"A business currently has $100,000 of current assets and $50,000 of current liabilities (a current ratio of 2.0 : 1). If it uses $20,000 of bank cash to pay off $20,000 of trade payables, what happens to its 'current ratio'?","options":{"A":"It stays at 2.0 : 1","B":"It rises to 2.67 : 1 ($80,000 / $30,000)","C":"It falls to 1.6 : 1","D":"It falls to 1.0 : 1"},"correctOption":"B","correctAnswer":"It rises to 2.67 : 1 ($80,000 / $30,000)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because subtracting $20,000 from both numerator and denominator changes the ratio from $100,000 / $50,000 (2.0 : 1) to $80,000 / $30,000 (2.67 : 1).","distractor_reasons":{"A":"Incorrect because working capital ($50,000) stays the same, but the *ratio* changes.","B":"Correct selection.","C":"Incorrect because 1.6 : 1 divides $80,000 by the original $50,000 liabilities.","D":"Incorrect because $80,000 / $30,000 equals 2.67 : 1, not 1.0 : 1."}}},{"id":"P1_U5_MCQ_991","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_991","question":"Why can differences in 'accounting policies' between two competing companies distort an inter-firm comparison of 'profit margin' and 'ROCE'?","options":{"A":"Because one company may depreciate identical machinery faster or value inventories differently than its rival, altering reported operating profit and asset book values without any real difference in cash performance","B":"Because one company is legally allowed to omit sales revenue from its accounts","C":"Because limited companies are exempt from using double-entry bookkeeping","D":"Because accounting policies determine the government's interest rate"},"correctOption":"A","correctAnswer":"Because one company may depreciate identical machinery faster or value inventories differently than its rival, altering reported operating profit and asset book values without any real difference in cash performance","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because legitimate differences in depreciation rates or inventory valuation methods affect accounting profit and capital employed.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because all companies must report full sales revenue.","C":"Incorrect because all companies use double-entry accounting.","D":"Incorrect because central banks set interest rates."}}},{"id":"P1_U5_MCQ_992","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_992","question":"Why should an analyst be cautious when comparing the liquidity ratios of two seasonal toy retailers if Retailer A prepares its accounts on 31 December and Retailer B prepares its accounts on 31 August?","options":{"A":"Because on 31 December Retailer A has just converted holiday stock into peak cash, whereas on 31 August Retailer B is holding maximum unsold inventory and short-term debt ahead of the holiday rush","B":"Because toy retailers never hold any inventory","C":"Because accounts prepared in August are legally invalid","D":"Because Retailer B is exempt from paying current liabilities"},"correctOption":"A","correctAnswer":"Because on 31 December Retailer A has just converted holiday stock into peak cash, whereas on 31 August Retailer B is holding maximum unsold inventory and short-term debt ahead of the holiday rush","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because different financial year-end dates capture seasonal businesses at completely different points in their working capital cycle.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because toy retailers hold substantial inventory prior to peak seasons.","C":"Incorrect because companies can choose different financial year-end dates.","D":"Incorrect because all businesses must settle current liabilities."}}},{"id":"P1_U5_MCQ_993","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_993","question":"How can high 'inflation' distort a five-year time-series analysis of a business's revenue and profit figures?","options":{"A":"Inflation makes dollar sales and profits appear to grow rapidly each year even if the actual physical volume of goods sold has stagnated or fallen","B":"Inflation reduces all nominal dollar revenue figures to zero","C":"Inflation automatically doubles the business's acid-test ratio","D":"Inflation eliminates all overhead expenses"},"correctOption":"A","correctAnswer":"Inflation makes dollar sales and profits appear to grow rapidly each year even if the actual physical volume of goods sold has stagnated or fallen","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because rising general price levels inflate nominal monetary figures over multi-year comparisons.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because inflation raises nominal prices rather than reducing revenue to zero.","C":"Incorrect because inflation does not double liquidity ratios.","D":"Incorrect because inflation increases nominal overhead costs."}}},{"id":"P1_U5_MCQ_994","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_994","question":"How do 'trade creditors (suppliers)' and 'shareholders' differ in the financial ratios they prioritize when analyzing a company's accounts?","options":{"A":"Suppliers focus primarily on liquidity ratios (current and acid-test) to ensure their 30-day invoices will be paid, whereas shareholders focus primarily on profitability ratios (ROCE and profit margin) to assess long-term returns","B":"Suppliers focus only on ROCE, whereas shareholders focus only on the acid-test ratio","C":"Neither group ever looks at published financial statements","D":"Both groups look solely at gross profit in dollars"},"correctOption":"A","correctAnswer":"Suppliers focus primarily on liquidity ratios (current and acid-test) to ensure their 30-day invoices will be paid, whereas shareholders focus primarily on profitability ratios (ROCE and profit margin) to assess long-term returns","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because each stakeholder group analyzes the ratios most relevant to its specific financial relationship with the business.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because this reverses supplier and shareholder priorities.","C":"Incorrect because both groups rely heavily on financial ratio analysis.","D":"Incorrect because raw dollar gross profit ignores scale, overheads, and short-term solvency."}}},{"id":"P1_U5_MCQ_995","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_995","question":"A company issues $5 million of new ordinary shares in January to build a new factory that will not start producing goods until next year. Why will the company's 'ROCE' likely drop during the current year?","options":{"A":"Because capital employed (the denominator) increases immediately by $5 million, while the new factory has not yet generated any additional operating profit (the numerator)","B":"Because issuing shares increases annual interest expenses","C":"Because building a factory reduces sales revenue from existing factories to zero","D":"Because issuing shares increases current liabilities by $5 million"},"correctOption":"A","correctAnswer":"Because capital employed (the denominator) increases immediately by $5 million, while the new factory has not yet generated any additional operating profit (the numerator)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because long-term capital investments expand capital employed immediately while profit returns lag behind during construction and ramp-up.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because issuing shares is equity and incurs zero interest.","C":"Incorrect because existing factories continue generating revenue.","D":"Incorrect because issuing shares increases shareholders' equity, not current liabilities."}}},{"id":"P1_U5_MCQ_996","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_996","question":"How can a high-volume 'discount supermarket chain' achieve a strong Return on Capital Employed (ROCE) even though its 'profit margin' is very low (e.g., 3%)?","options":{"A":"By generating huge annual sales turnover from lean, low-cost stores so that a 3% margin on massive sales volume produces a high total dollar profit relative to capital employed","B":"By refusing to pay corporation tax on its profits","C":"By charging higher prices than luxury boutiques","D":"By holding unsold inventory in warehouses for three years"},"correctOption":"A","correctAnswer":"By generating huge annual sales turnover from lean, low-cost stores so that a 3% margin on massive sales volume produces a high total dollar profit relative to capital employed","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ROCE combines margin and asset turnover: high volume at thin margins can yield high returns on invested capital.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because profitable supermarkets pay corporation tax.","C":"Incorrect because discount supermarkets compete on low prices.","D":"Incorrect because rapid inventory turnover is central to supermarket efficiency."}}},{"id":"P1_U5_MCQ_997","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_997","question":"Why does a 'luxury diamond jeweler' typically report a high gross profit margin (e.g., 60%) and a high current ratio (e.g., 3.2 : 1), alongside a much lower acid-test ratio (e.g., 0.8 : 1)?","options":{"A":"Because luxury watches and diamonds carry high mark-ups but sit in display inventory for many months before selling, tying up most current assets in high-value stock","B":"Because luxury jewelers sell diamonds on 10-year interest-free credit","C":"Because luxury jewelers never hold any physical inventory","D":"Because luxury jewelers have zero overhead expenses"},"correctOption":"A","correctAnswer":"Because luxury watches and diamonds carry high mark-ups but sit in display inventory for many months before selling, tying up most current assets in high-value stock","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because industry business models shape normal ratio profiles: high-margin, slow-turning inventory creates a wide gap between current and acid-test ratios.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because retail jewelers sell mostly at point of sale rather than 10-year receivables.","C":"Incorrect because jewelers hold high-value physical display stock.","D":"Incorrect because prime retail store rents and security overheads are substantial."}}},{"id":"P1_U5_MCQ_998","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_998","question":"A company reports an impressive ROCE of 22% and a profit margin of 16%, but its acid-test ratio has fallen to 0.45 : 1. What is the most accurate overall financial diagnosis?","options":{"A":"The company is unprofitable and inefficient, but has excess cash","B":"The company is highly profitable on its trading operations, but faces an acute short-term liquidity crisis that could force insolvency unless working capital is restructured","C":"The company is both unprofitable and insolvent","D":"The company has no current liabilities and no inventory"},"correctOption":"B","correctAnswer":"The company is highly profitable on its trading operations, but faces an acute short-term liquidity crisis that could force insolvency unless working capital is restructured","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because evaluating profitability and liquidity together exposes profitable firms suffering from severe cash tightness.","distractor_reasons":{"A":"Incorrect because 22% ROCE and 16% profit margin show strong profitability, while 0.45 : 1 shows a cash shortage.","B":"Correct selection.","C":"Incorrect because the company is clearly profitable.","D":"Incorrect because a 0.45 : 1 acid-test ratio implies substantial current liabilities relative to liquid assets."}}},{"id":"P1_U5_MCQ_999","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_999","question":"What role do independent 'external auditors' play in supporting the reliability of financial ratio analysis for public limited companies?","options":{"A":"They inspect accounting records and financial statements to verify that the figures present a 'true and fair view' in accordance with accounting standards","B":"They guarantee that the company's share price will rise next year","C":"They lend money to the company whenever its current ratio drops below 1 : 1","D":"They set the company's selling prices and marketing budget"},"correctOption":"A","correctAnswer":"They inspect accounting records and financial statements to verify that the figures present a 'true and fair view' in accordance with accounting standards","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ratio analysis is only as trustworthy as the underlying financial statements; external audits deter fraud and material misstatements.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because auditors verify historical statements rather than guaranteeing stock market performance.","C":"Incorrect because auditors are independent accountants, not commercial lenders.","D":"Incorrect because operational pricing and marketing belong to management."}}},{"id":"P1_U5_MCQ_1000","section":"5","unit":"Unit 5: Financial information and decisions","chapter":"5.5 Analysis of accounts","questionNumber":"P1_U5_MCQ_1000","question":"A growing company has a 19% ROCE, a 0.7 : 1 acid-test ratio, and high existing bank debt. It needs $300,000 to modernize its packaging line while restoring short-term liquidity. Which integrated financial decision best addresses all three indicators?","options":{"A":"Raise $400,000 through a rights issue of ordinary shares—using $300,000 for the packaging line and keeping $100,000 in cash to strengthen working capital without adding debt interest","B":"Borrow $300,000 via a short-term bank overdraft repayable on demand","C":"Spend all remaining cash reserves on paying an extra special dividend to shareholders","D":"Take out another high-interest variable loan while extending customer credit to 120 days"},"correctOption":"A","correctAnswer":"Raise $400,000 through a rights issue of ordinary shares—using $300,000 for the packaging line and keeping $100,000 in cash to strengthen working capital without adding debt interest","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because raising equity avoids adding risk to an already indebted balance sheet, funds the long-term asset, and injects $100,000 of liquid cash to lift the weak 0.7 : 1 acid-test ratio.","distractor_reasons":{"A":"Correct selection.","B":"Incorrect because funding long-term machinery with an overdraft worsens short-term liquidity and risk.","C":"Incorrect because paying extra cash dividends when the acid-test ratio is 0.7 : 1 would trigger a cash crisis.","D":"Incorrect because adding variable debt and lengthening customer credit would worsen both gearing and liquidity."}}}];
